    translation: "\u5C0F\u65F6\u5019\uFF0C\u4E61\u6101\u662F\u4E00\u679A\u5C0F\u5C0F\u7684\u90AE\u7968\uFF0C\u6211\u5728\u8FD9\u5934\uFF0C\u6BCD\u4EB2\u5728\u90A3\u5934\u3002\u957F\u5927\u4EE5\u540E\uFF0C\u4E61\u6101\u662F\u4E00\u5F20\u7A84\u7A84\u7684\u8239\u7968\uFF0C\u6211\u5728\u8FD9\u5934\uFF0C\u65B0\u5A18\u5728\u90A3\u5934\u3002\u540E\u6765\u554A\uFF0C\u4E61\u6101\u662F\u4E00\u65B9\u77EE\u77EE\u7684\u575F\u5893\uFF0C\u6211\u5728\u5916\u5934\uFF0C\u6BCD\u4EB2\u5728\u91CC\u5934\u3002\u800C\u73B0\u5728\uFF0C\u4E61\u6101\u662F\u4E00\u6E7E\u6D45\u6D45\u7684\u6D77\u5CE1\uFF0C\u6211\u5728\u8FD9\u5934\uFF0C\u5927\u9646\u5728\u90A3\u5934\u3002",
    appreciation: "\u8FD9\u9996\u8BD7\u4EE5\u65F6\u95F4\u987A\u5E8F\u7ED3\u6784\u5168\u7BC7\uFF0C\u7528\u300C\u5C0F\u65F6\u5019\u300D\u300C\u957F\u5927\u540E\u300D\u300C\u540E\u6765\u554A\u300D\u300C\u800C\u73B0\u5728\u300D\u56DB\u4E2A\u4EBA\u751F\u9636\u6BB5\u4E32\u8D77\u56DB\u7EC4\u610F\u8C61\uFF1A\u90AE\u7968\u3001\u8239\u7968\u3001\u575F\u5893\u3001\u6D77\u5CE1\uFF0C\u628A\u62BD\u8C61\u7684\u4E61\u6101\u5316\u4E3A\u53EF\u89E6\u53EF\u611F\u7684\u5177\u4F53\u4E8B\u7269\uFF0C\u5C42\u5C42\u9012\u8FDB\uFF0C\u7531\u4E2A\u4EBA\u7684\u6BCD\u5B50\u4E4B\u601D\u3001\u592B\u59BB\u4E4B\u604B\u6269\u5C55\u5230\u5BF9\u7956\u56FD\u5927\u9646\u7684\u6DF1\u5207\u6000\u5FF5\uFF0C\u300C\u6D45\u6D45\u7684\u6D77\u5CE1\u300D\u4EE5\u6D45\u886C\u6DF1\uFF0C\u6210\u4E3A\u5168\u8BD7\u60C5\u611F\u7684\u9AD8\u5CF0\u3002\u56DB\u4E2A\u8BD7\u8282\u5B57\u6570\u3001\u53E5\u5F0F\u5927\u81F4\u76F8\u540C\uFF0C\u56DE\u73AF\u5F80\u590D\uFF0C\u5F62\u6210\u97F3\u4E50\u7F8E\u4E0E\u5EFA\u7B51\u7F8E\u3002\u4E2D\u8003\u5E38\u8003\uFF1A\u56DB\u4E2A\u610F\u8C61\u5404\u81EA\u5BC4\u6258\u7684\u60C5\u611F\uFF1B\u65F6\u95F4\u987A\u5E8F\u4E0E\u60C5\u611F\u9012\u8FDB\u7684\u5173\u7CFB\uFF1B\u300C\u5C0F\u5C0F\u7684\u300D\u300C\u7A84\u7A84\u7684\u300D\u300C\u77EE\u77EE\u7684\u300D\u300C\u6D45\u6D45\u7684\u300D\u8FD9\u7EC4\u53E0\u8BCD\u7684\u8868\u8FBE\u6548\u679C\uFF08\u53CD\u886C\u4E61\u6101\u4E4B\u91CD\u3001\u4E4B\u6DF1\uFF09\uFF1B\u6258\u7269\u5BC4\u60C5\u4E0E\u53CD\u590D\u548F\u53F9\u7684\u624B\u6CD5\u3002",
    famousLines: ["\u800C\u73B0\u5728\uFF0C\u4E61\u6101\u662F\u4E00\u6E7E\u6D45\u6D45\u7684\u6D77\u5CE1\uFF0C\u6211\u5728\u8FD9\u5934\uFF0C\u5927\u9646\u5728\u90A3\u5934\u3002"],
    tags: ["\u601D\u4E61", "\u73B0\u4EE3\u8BD7", "\u610F\u8C61"],
