        stem: "\u8BF7\u7528\u300C/\u300D\u7ED9\u4E0B\u9762\u7684\u53E5\u5B50\u65AD\u53E5\uFF1A\u4E09\u4EBA\u884C\u5FC5\u6709\u6211\u5E08\u7109\u62E9\u5176\u5584\u8005\u800C\u4ECE\u4E4B\u5176\u4E0D\u5584\u8005\u800C\u6539\u4E4B",
        answer: "\u4E09\u4EBA\u884C/\u5FC5\u6709\u6211\u5E08\u7109/\u62E9\u5176\u5584\u8005\u800C\u4ECE\u4E4B/\u5176\u4E0D\u5584\u8005\u800C\u6539\u4E4B",
        explanation: "\u65AD\u53E5\u5148\u8981\u758F\u901A\u53E5\u610F\uFF1A\u51E0\u4E2A\u4EBA\u540C\u884C\uFF0C\u5176\u4E2D\u5FC5\u5B9A\u6709\u53EF\u4EE5\u505A\u6211\u8001\u5E08\u7684\u4EBA\uFF1B\u9009\u53D6\u4ED6\u4EEC\u7684\u4F18\u70B9\u6765\u5B66\u4E60\uFF0C\u770B\u5230\u4ED6\u4EEC\u7684\u7F3A\u70B9\u5C31\u5BF9\u7167\u81EA\u5DF1\u52A0\u4EE5\u6539\u6B63\u3002\u636E\u6B64\u53EF\u5728\u300C\u4E09\u4EBA\u884C\u300D\u300C\u5FC5\u6709\u6211\u5E08\u7109\u300D\u300C\u62E9\u5176\u5584\u8005\u800C\u4ECE\u4E4B\u300D\u4E4B\u540E\u65AD\u5F00\u3002\u300C\u7109\u300D\u662F\u517C\u8BCD\uFF0C\u76F8\u5F53\u4E8E\u300C\u4E8E\u6B64\u300D\uFF0C\u662F\u300C\u5FC5\u6709\u6211\u5E08\u300D\u7684\u5904\u6240\u8865\u8BED\uFF0C\u5FC5\u987B\u7D27\u8DDF\u300C\u5FC5\u6709\u6211\u5E08\u300D\uFF0C\u4E0D\u80FD\u4E0E\u540E\u9762\u7684\u300C\u62E9\u5176\u5584\u8005\u300D\u8FDE\u8BFB\u3002\u6613\u9519\u70B9\uFF1A\u628A\u300C\u7109\u300D\u5F53\u4F5C\u53E5\u672B\u8BED\u6C14\u8BCD\uFF0C\u5728\u300C\u5FC5\u6709\u6211\u5E08\u300D\u540E\u65AD\u53E5\uFF0C\u4F7F\u300C\u62E9\u5176\u5584\u8005\u800C\u4ECE\u4E4B\u300D\u5931\u53BB\u4E3B\u8BED\u4E2D\u5FC3\u3002",
