      { word: "\u662F\u975E\u6728\u676E", explain: "\u8FD9\u4E0D\u662F\u6728\u7247\u3002\u662F\uFF0C\u4EE3\u8BCD\uFF0C\u8FD9\uFF1B\u975E\uFF0C\u4E0D\u662F\uFF1B\u6728\u676E\uFF0C\u524A\u4E0B\u7684\u6728\u7247\uFF0C\u676E\u8BFB f\xE8i\u3002\u6587\u8A00\u4E2D\u201C\u662F\u201D\u591A\u4F5C\u4EE3\u8BCD\uFF0C\u4E0D\u8981\u8BEF\u5F53\u5224\u65AD\u52A8\u8BCD\u3002" },
      { word: "\u5C14\u8F88", explain: "\u4F60\u4EEC\u8FD9\u4E9B\u4EBA\u3002\u5C14\uFF0C\u4F60\uFF1B\u8F88\uFF0C\u7C7B\u3001\u7B49\u3002\u8FD9\u4E00\u79F0\u547C\u5E26\u6709\u5C45\u9AD8\u4E34\u4E0B\u7684\u53E3\u543B\uFF0C\u8BB2\u5B66\u5BB6\u7684\u81EA\u8D1F\u6B63\u4ECE\u8FD9\u4E24\u4E2A\u5B57\u91CC\u900F\u51FA\u3002" },
      { word: "\u8BBE\u5E10", explain: "\u8BBE\u5E10\u8BB2\u5B66\uFF0C\u5373\u5F00\u9986\u6559\u4E66\u3002\u53E4\u4EBA\u8BB2\u5B66\u5E38\u8BBE\u5E37\u5E10\u4EE5\u5C45\uFF0C\u6545\u79F0\u201C\u8BBE\u5E10\u201D\u3002\u6587\u4E2D\u6307\u8BB2\u5B66\u5BB6\u5728\u5BFA\u4E2D\u6559\u4E66\u3002" },
      { word: "\u4F17\u670D\u4E3A\u786E\u8BBA", explain: "\u5927\u5BB6\u4FE1\u670D\uFF0C\u8BA4\u4E3A\u8FD9\u662F\u6B63\u786E\u7684\u8A00\u8BBA\u3002\u670D\uFF0C\u4FE1\u670D\uFF1B\u786E\u8BBA\uFF0C\u6B63\u786E\u7684\u8A00\u8BBA\u3002\u6B64\u53E5\u5199\u4F17\u4EBA\u7684\u53CD\u5E94\uFF0C\u4E3A\u4E0B\u6587\u8001\u6CB3\u5175\u7684\u6B63\u786E\u5224\u65AD\u4F5C\u53CD\u886C\u3002" },
      { word: "\u7136\u5219", explain: "\u65E2\u7136\u8FD9\u6837\uFF0C\u90A3\u4E48\u3002\u7531\u4EE3\u8BCD\u201C\u7136\u201D\u4E0E\u8FDE\u8BCD\u201C\u5219\u201D\u7EC4\u6210\uFF0C\u7528\u4E8E\u627F\u63A5\u4E0A\u6587\u3001\u5F15\u51FA\u7ED3\u8BBA\uFF0C\u662F\u8BAE\u8BBA\u6BB5\u843D\u7684\u6807\u5FD7\u6027\u8BCD\u8BED\u3002" },
      { word: "\u6B24", explain: "\u8BFB y\xFA\uFF0C\u53E5\u672B\u8BED\u6C14\u8BCD\uFF0C\u8868\u53CD\u95EE\uFF0C\u53EF\u8BD1\u4E3A\u201C\u5417\u201D\u3002\u201C\u53EF\u2026\u2026\u6B24\u201D\u6784\u6210\u53CD\u95EE\u53E5\uFF0C\u4F7F\u672B\u6BB5\u7684\u8BAE\u8BBA\u8BED\u6C14\u5F3A\u70C8\uFF0C\u5352\u7AE0\u663E\u5FD7\u3002" }
