        stem: "\u8001\u6CB3\u5175\u8BA4\u4E3A\u201C\u51E1\u6CB3\u4E2D\u5931\u77F3\uFF0C\u5F53\u6C42\u4E4B\u4E8E\u4E0A\u6D41\u201D\uFF0C\u5176\u5224\u65AD\u7684\u4E3B\u8981\u4F9D\u636E\u662F\u4EC0\u4E48\uFF1F",
