        items: [
          { word: "\u81EA\u4E09\u5CE1\u4E03\u767E\u91CC\u4E2D\uFF0F\u81EA\u975E\u4EAD\u5348\u591C\u5206", explain: "\u300C\u81EA\u4E09\u5CE1\u4E03\u767E\u91CC\u4E2D\u300D\u7684\u300C\u81EA\u300D\u662F\u300C\u5728\u300D\uFF1B\u300C\u81EA\u975E\u4EAD\u5348\u591C\u5206\u300D\u7684\u300C\u81EA\u300D\u662F\u300C\u5982\u679C\u300D\uFF0C\u4E8C\u8005\u610F\u4E49\u4E0D\u540C\u3002" },
          { word: "\u6CBF\u6EAF\u963B\u7EDD\uFF0F\u7EDD\u5DD8\u591A\u751F\u602A\u67CF\uFF0F\u54C0\u8F6C\u4E45\u7EDD", explain: "\u4F9D\u6B21\u662F\u300C\u65AD\u7EDD\u3001\u963B\u65AD\u300D\u300C\u6781\u3001\u975E\u5E38\u300D\u300C\u6D88\u5931\u3001\u505C\u6B62\u300D\uFF0C\u540C\u4E00\u4E2A\u300C\u7EDD\u300D\u968F\u8BED\u5883\u4E0D\u540C\u800C\u4E49\u53D8\u3002" },
          { word: "\u98DE\u6F31\u5176\u95F4\uFF0F\u5176\u95F4\u5343\u4E8C\u767E\u91CC", explain: "\u4E24\u5904\u300C\u5176\u300D\u90FD\u662F\u4EE3\u8BCD\uFF1A\u300C\u98DE\u6F31\u5176\u95F4\u300D\u6307\u300C\u5B83\u4EEC\uFF08\u5C71\u5CF0\uFF09\u4E4B\u95F4\u300D\uFF1B\u300C\u5176\u95F4\u5343\u4E8C\u767E\u91CC\u300D\u6307\u300C\u8FD9\uFF08\u767D\u5E1D\u57CE\u5230\u6C5F\u9675\uFF09\u4E2D\u95F4\u300D\u3002" },
          { word: "\u6216\u738B\u547D\u6025\u5BA3", explain: "\u300C\u6216\u300D\u5728\u672C\u6587\u4E2D\u4F5C\u300C\u6709\u65F6\u300D\u8BB2\uFF1B\u6587\u8A00\u4E2D\u300C\u6216\u300D\u8FD8\u53EF\u8868\u793A\u300C\u6709\u4EBA\u300D\uFF08\u5982\u300C\u6216\u66F0\u300D\uFF09\uFF0C\u4F46\u6CA1\u6709\u73B0\u4EE3\u6C49\u8BED\u300C\u6216\u8005\u300D\u7684\u9009\u62E9\u4E49\u3002" }
        ]
