        stem: "\u4E0B\u5217\u53E5\u4E2D\u201C\u5176\u201D\u7684\u610F\u4E49\u548C\u7528\u6CD5\uFF0C\u4E0E\u201C\u4E0D\u77E5\u5176\u65E8\u4E5F\u201D\u4E2D\u7684\u201C\u5176\u201D\u76F8\u540C\u7684\u4E00\u9879\u662F\uFF08\u3000\uFF09",
