      {
        id: "c-yueyanglouji-q7",
        type: "choice",
        stem: "\u672C\u6587\u591A\u5904\u8FD0\u7528\u5BF9\u6BD4\uFF0C\u4E0B\u5217\u5206\u6790\u4E0D\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF1A",
        options: [
          "\u300C\u6DEB\u96E8\u970F\u970F\u300D\u4E0E\u300C\u6625\u548C\u666F\u660E\u300D\u4E24\u79CD\u666F\u8C61\u4E00\u6697\u4E00\u660E\uFF0C\u5F62\u6210\u5BF9\u6BD4\uFF0C\u4E3A\u4E0B\u6587\u5199\u4E24\u79CD\u622A\u7136\u4E0D\u540C\u7684\u5FC3\u60C5\u4F5C\u94FA\u57AB\u3002",
          "\u300C\u611F\u6781\u800C\u60B2\u8005\u77E3\u300D\u4E0E\u300C\u5176\u559C\u6D0B\u6D0B\u8005\u77E3\u300D\u5F62\u6210\u60B2\u559C\u5BF9\u6BD4\uFF0C\u5F62\u8C61\u5730\u8868\u73B0\u51FA\u8FC1\u5BA2\u9A9A\u4EBA\u300C\u4EE5\u7269\u559C\u3001\u4EE5\u5DF1\u60B2\u300D\u3002",
          "\u300C\u8FC1\u5BA2\u9A9A\u4EBA\u300D\u4E0E\u300C\u53E4\u4EC1\u4EBA\u300D\u5F62\u6210\u5BF9\u6BD4\uFF0C\u7A81\u51FA\u53E4\u4EC1\u4EBA\u300C\u4E0D\u4EE5\u7269\u559C\uFF0C\u4E0D\u4EE5\u5DF1\u60B2\u300D\u7684\u65F7\u8FBE\u80F8\u895F\u3002",
          "\u300C\u5C45\u5E99\u5802\u4E4B\u9AD8\u300D\u4E0E\u300C\u5904\u6C5F\u6E56\u4E4B\u8FDC\u300D\u5F62\u6210\u5BF9\u6BD4\uFF0C\u610F\u5728\u8BF4\u660E\u53E4\u4EC1\u4EBA\u65E0\u8BBA\u8FDB\u9000\u90FD\u53EA\u5FE7\u8651\u4E2A\u4EBA\u7684\u5F97\u5931\u3002"
        ],
        answer: "D",
        explanation: "\u300C\u5C45\u5E99\u5802\u4E4B\u9AD8\u5219\u5FE7\u5176\u6C11\uFF0C\u5904\u6C5F\u6E56\u4E4B\u8FDC\u5219\u5FE7\u5176\u541B\u300D\u662F\u4E92\u6587\u89C1\u4E49\uFF0C\u5199\u53E4\u4EC1\u4EBA\u65E0\u8BBA\u8EAB\u5C45\u671D\u5EF7\u8FD8\u662F\u9000\u5904\u6C5F\u6E56\uFF0C\u90FD\u4E3A\u56FD\u4E8B\u4E0E\u767E\u59D3\u800C\u5FE7\uFF0C\u662F\u5FE7\u56FD\u5FE7\u6C11\u800C\u975E\u5FE7\u8651\u4E2A\u4EBA\u5F97\u5931\uFF0CD \u9879\u66F2\u89E3\u4E86\u6587\u610F\u3002A\u3001B\u3001C \u4E09\u9879\u7684\u5BF9\u6BD4\u5206\u6790\u5747\u4E0E\u539F\u6587\u76F8\u7B26\uFF0C\u8FD9\u4E09\u7EC4\u5BF9\u6BD4\u5C42\u5C42\u63A8\u8FDB\uFF0C\u5171\u540C\u4E3A\u7ED3\u5C3E\u300C\u5148\u5FE7\u540E\u4E50\u300D\u7684\u62B1\u8D1F\u4F5C\u94FA\u57AB\u3002",
        difficulty: 3,
        tags: ["\u5BF9\u6BD4\u624B\u6CD5", "\u4E92\u6587"]
      }
