        stem: "\u5173\u4E8E\u672C\u6587\u7684\u8BE6\u7565\u5B89\u6392\u548C\u4EBA\u7269\u523B\u753B\uFF0C\u5206\u6790\u4E0D\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\uFF09",
