        stem: "\u4E0B\u5217\u5BF9\u9009\u6587\u5185\u5BB9\u7684\u7406\u89E3\u548C\u5206\u6790\uFF0C\u4E0D\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\uFF09",
