        type: "fill",
        stem: "\u6587\u7AE0\u7ED3\u5C3E\u6BB5\uFF08\u7B2C\u2466\u6BB5\uFF09\u5728\u5168\u6587\u4E2D\u7684\u4F5C\u7528\u662F\u4EC0\u4E48\uFF1F\u8BF7\u7B80\u8981\u56DE\u7B54\u3002",
        answer: "\u603B\u7ED3\u5168\u6587\uFF0C\u70B9\u660E\u4E3B\u65E8|\u603B\u7ED3\u5168\u6587\uFF0C\u6DF1\u5316\u4E3B\u65E8|\u70B9\u660E\u4E3B\u65E8\uFF0C\u603B\u7ED3\u5168\u6587|\u603B\u7ED3\u5168\u6587\uFF0C\u5347\u534E\u4E3B\u65E8|\u603B\u7ED3\u5168\u6587\uFF0C\u70B9\u660E\u4E2D\u5FC3",
        explanation: "\u8003\u67E5\u6BB5\u843D\u4F5C\u7528\uFF0C\u5148\u770B\u4F4D\u7F6E\uFF0C\u518D\u770B\u5185\u5BB9\u4E0E\u60C5\u611F\u3002\u7ED3\u5C3E\u6BB5\u4F4D\u4E8E\u5168\u6587\u6700\u540E\uFF0C\u7ED3\u6784\u4E0A\u6536\u675F\u5168\u6587\u3001\u7167\u5E94\u5F00\u5934\u5BF9\u83DC\u56ED\u7684\u63CF\u5199\uFF1B\u5185\u5BB9\u4E0A\u501F\u6BCD\u4EB2\u201C\u4EBA\u6B47\u4E86\uFF0C\u5730\u5C31\u8352\u4E86\u201D\u7684\u8BDD\u628A\u83DC\u56ED\u7684\u610F\u4E49\u4ECE\u201C\u51E0\u7566\u852C\u83DC\u201D\u5347\u534E\u4E3A\u201C\u4E0E\u571F\u5730\u7684\u7EA6\u5B9A\u201D\u201C\u6700\u5B9E\u5728\u7684\u7275\u6302\u201D\uFF0C\u4ECE\u800C\u70B9\u660E\u5E76\u6DF1\u5316\u4E3B\u65E8\uFF1B\u60C5\u611F\u4E0A\u6292\u53D1\u201C\u6211\u201D\u7684\u611F\u6FC0\u4E0E\u601D\u5FF5\u3002\u7B54\u9898\u6A21\u677F\uFF1A\u7ED3\u6784\uFF08\u603B\u7ED3\u5168\u6587\u3001\u7167\u5E94\u6807\u9898\u6216\u5F00\u5934\uFF09\uFF0B\u5185\u5BB9\uFF08\u70B9\u660E\u2026\u2026\u4E3B\u65E8\uFF09\uFF0B\u60C5\u611F\uFF08\u6292\u53D1\u2026\u2026\uFF09\uFF0C\u4E09\u70B9\u9F50\u5907\u624D\u4E0D\u4E22\u5206\u3002",
        difficulty: 2,
        tags: ["\u6BB5\u843D\u4F5C\u7528", "\u7ED3\u5C3E\u6BB5"]
