        stem: "\u7ED3\u5408\u5168\u6587\uFF0C\u4E0B\u5217\u5BF9\u6BCD\u4EB2\u5F62\u8C61\u7684\u5206\u6790\uFF0C\u4E0D\u6070\u5F53\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
