        answer: "\u53C2\u8003\u7B54\u6848\uFF1A\u8FD9\u53E5\u8BDD\u8FD0\u7528\u5FC3\u7406\u63CF\u5199\uFF08\u5185\u5FC3\u6D3B\u52A8\u63CF\u5199\uFF09\uFF0C\u5199\u300C\u6211\u300D\u4E3A\u63A9\u9970\u8FC7\u5931\u800C\u5728\u5FC3\u91CC\u53CD\u590D\u6392\u7EC3\u5404\u79CD\u8BF4\u6CD5\uFF0C\u8FDE\u8BED\u6C14\u548C\u8868\u60C5\u90FD\u9884\u5148\u6F14\u7EC3\u8FC7\uFF0C\u5177\u4F53\u751F\u52A8\u5730\u523B\u753B\u51FA\u300C\u6211\u300D\u5F53\u65F6\u7684\u614C\u4E71\u3001\u5FC3\u865A\u4E0E\u5BB3\u6015\u88AB\u8D23\u9A82\u7684\u5FC3\u7406\uFF1B\u300C\u6F14\u300D\u5B57\u53CD\u590D\u51FA\u73B0\uFF0C\u5E26\u6709\u81EA\u6211\u5BA1\u89C6\u7684\u610F\u5473\uFF0C\u4E5F\u540C\u4E0B\u6587\u300C\u6211\u300D\u6700\u7EC8\u8BF4\u51FA\u5B9E\u8BDD\u5F62\u6210\u53CD\u5DEE\uFF0C\u4F7F\u4EBA\u7269\u5185\u5FC3\u7684\u6323\u624E\u4E0E\u540E\u6765\u7684\u6210\u957F\u66F4\u52A0\u771F\u5B9E\u53EF\u4FE1\u3002",
