          "\u70B9\u660E\u63CF\u5199\u65B9\u6CD5\uFF1A\u7B54\u51FA\u8FD0\u7528\u5FC3\u7406\u63CF\u5199\uFF08\u5185\u5FC3\u6D3B\u52A8\u63CF\u5199\u3001\u7EC6\u8282\u63CF\u5199\uFF09\uFF0C\u5F97 1 \u5206\u3002",
          "\u89E3\u91CA\u53E5\u5B50\u5185\u5BB9\uFF1A\u5199\u51FA\u300C\u6211\u300D\u4E3A\u63A9\u9970\u8FC7\u5931\u800C\u5728\u5FC3\u91CC\u53CD\u590D\u6392\u7EC3\u5404\u79CD\u8BF4\u6CD5\uFF0C\u8FDE\u8BED\u6C14\u3001\u8868\u60C5\u90FD\u9884\u5148\u6F14\u7EC3\uFF0C\u5F97 1 \u5206\u3002",
          "\u7B54\u51FA\u8868\u8FBE\u6548\u679C\uFF1A\u51C6\u786E\u5199\u51FA\u300C\u6211\u300D\u5F53\u65F6\u614C\u4E71\u3001\u5FC3\u865A\u3001\u5BB3\u6015\u88AB\u8D23\u9A82\uFF08\u9003\u907F\u8D23\u4EFB\uFF09\u7684\u5FC3\u7406\uFF0C\u5F97 1 \u5206\u3002",
          "\u7B54\u51FA\u4E0E\u4E0B\u6587\u7684\u5173\u7CFB\u6216\u8868\u73B0\u529B\uFF1A\u300C\u6F14\u300D\u5B57\u53CD\u590D\u4F7F\u7528\u7A81\u51FA\u5185\u5FC3\u7684\u6323\u624E\uFF0C\u4E0E\u540E\u6587\u8BF4\u51FA\u5B9E\u8BDD\u5F62\u6210\u5BF9\u6BD4\uFF0C\u4F7F\u4EBA\u7269\u6210\u957F\u66F4\u771F\u5B9E\uFF0C\u5F97 1 \u5206\u3002",
