        stem: "\u7B2C\u2463\u6BB5\u5199\u79CB\u5929\u94F6\u674F\u843D\u53F6\uFF0C\u672B\u5C3E\u8BF4\u300C\u6709\u4E00\u5929\u6211\u5FFD\u7136\u53D1\u73B0\u7237\u7237\u7684\u624B\u80CC\u6BD4\u53BB\u5E74\u66F4\u677E\uFF0C\u9752\u8272\u7684\u8840\u7BA1\u6D6E\u8D77\u6765\uFF0C\u50CF\u90A3\u4E9B\u53F6\u7247\u4E0A\u7EC6\u7EC6\u7684\u7EB9\u300D\u3002\u8BF7\u8BF4\u8BF4\u8FD9\u53E5\u8BDD\u5728\u6587\u4E2D\u7684\u4F5C\u7528\u3002",
