        type: "fill",
        stem: "\u7B2C 2 \u6BB5\u4E2D\u300C\u4FDD\u8D28\u671F\u662F\u6307\u98DF\u54C1\u5728\u6807\u7B7E\u6307\u660E\u7684\u8D2E\u5B58\u6761\u4EF6\u4E0B\uFF0C\u4FDD\u6301\u54C1\u8D28\u7684\u671F\u9650\u300D\uFF0C\u7528\u7B80\u6D01\u660E\u786E\u7684\u8BDD\u63ED\u793A\u51FA\u4E8B\u7269\u7684\u672C\u8D28\u7279\u5F81\u3002\u8FD9\u79CD\u8BF4\u660E\u65B9\u6CD5\u53EB ________\u3002\uFF08\u586B\u4E09\u4E2A\u5B57\uFF09",
