        stem: "\u6750\u6599\u4F5C\u6587\u7ACB\u610F\u7684\u4E09\u4E2A\u6B65\u9AA4\u4F9D\u6B21\u662F\uFF1A\u63D0\u53D6\u3001____\u3001\u5B9A\u5411\u3002",
        answer: "\u6BD4\u8F83",
        explanation: "\u63D0\u53D6\u8981\u7D20\u4E0E\u5173\u952E\u8BCD\u4E4B\u540E\uFF0C\u5FC5\u987B\u6BD4\u8F83\u591A\u4E2A\u89D2\u5EA6\u7684\u8D34\u5408\u5EA6\u4E0E\u7D20\u6750\u53EF\u884C\u6027\uFF0C\u6700\u540E\u624D\u80FD\u5B9A\u5411\u4E3A\u4E00\u53E5\u53EF\u9A8C\u8BC1\u7684\u4E2D\u5FC3\u53E5\u3002",
        difficulty: 1,
