        stem: "\u603B\u5206\u603B\u7ED3\u6784\u7684\u7ED3\u5C3E\u6BB5\u53EA\u627F\u62C5\u7EC4\u7EC7\u4E0E\u5347\u534E\u7684\u4EFB\u52A1\uFF0C\u4E0D\u5F97\u5F15\u5165\u65B0\u7684____\u3002",
        answer: "\u4E8B\u4EF6|\u6750\u6599|\u4E8B\u4F8B|\u60C5\u8282",
        explanation: "\u7ED3\u5C3E\u5F15\u5165\u65B0\u4E8B\u4EF6\u4F1A\u8BA9\u6587\u7AE0\u5934\u8F7B\u811A\u91CD\u3001\u6536\u675F\u65E0\u529B\uFF0C\u6240\u6709\u5177\u4F53\u6750\u6599\u90FD\u5E94\u5728\u4E2D\u95F4\u6BB5\u4EA4\u4EE3\u5B8C\u6BD5\u3002",
