var writingSamplesNature = [
  {
    id: "w-sample-ziran-2",
    grade: "all",
    category: "\u8303\u6587\u70B9\u8BC4",
    theme: "\u81EA\u7136\u611F\u609F",
    title: "\u8303\u6587\u70B9\u8BC4\uFF1A\u81EA\u7136\u611F\u609F \xB7 \u540C\u9898\u4E24\u7BC7\u300A\u53F0\u98CE\u8FC7\u540E\u7684\u90A3\u76C6\u8309\u8389\u300B\u300A\u4E0B\u96E8\u524D\u7684\u90A3\u4E00\u961F\u8682\u8681\u300B",
    summary: "\u4E00\u76C6\u88AB\u53F0\u98CE\u6380\u5012\u7684\u8309\u8389\u3001\u4E00\u961F\u4E0B\u96E8\u524D\u642C\u5BB6\u7684\u8682\u8681\uFF0C\u4E24\u7BC7\u7ACB\u610F\u4E0D\u540C\u7684\u81EA\u7136\u611F\u609F\u8303\u6587\uFF0C\u6559\u4F60\u628A\u4E00\u6B21\u5177\u4F53\u5230\u80FD\u770B\u89C1\u7EC6\u8282\u7684\u89C2\u5BDF\uFF0C\u5199\u6210\u5C5E\u4E8E\u4F60\u81EA\u5DF1\u7684\u4E00\u4E2A\u5C0F\u8BA4\u8BC6\u3002",
    content: [
      "## \u9898\u76EE",
      "\u81EA\u7136\u611F\u609F\u7C7B\u9898\u76EE\u5E38\u8003\u4E24\u79CD\u5F62\u5F0F\uFF1A\u4E00\u79CD\u4EE5\u7269\u4E3A\u9898\uFF08\u300A\u90A3\u4E00\u62B9\u7EFF\u300B\u300A\u9633\u53F0\u4E0A\u7684\u2026\u2026\u300B\u300A\u6211\u770B\u89C1\u4E86\u4E00\u79CD\u6D3B\u6CD5\u300B\uFF09\uFF0C\u8981\u6C42\u56F4\u7ED5\u4E00\u6B21\u5177\u4F53\u7684\u89C2\u5BDF\u5C55\u5F00\uFF1B\u4E00\u79CD\u662F\u53D9\u4E8B\u52A0\u611F\u609F\uFF08\u300A\u90A3\u4E00\u523B\uFF0C\u6211\u61C2\u5F97\u4E86\u2026\u2026\u300B\u300A\u539F\u6765\u5B83\u81EA\u5DF1\u4F1A\u597D\u300B\uFF09\uFF0C\u8981\u6C42\u5199\u51FA\u8BA4\u8BC6\u7684\u53D8\u5316\u3002\u4E24\u7BC7\u8303\u6587\u90FD\u5C5E\u4E8E\u7B2C\u4E8C\u7C7B\uFF0C\u843D\u70B9\u5374\u5B8C\u5168\u4E0D\u540C\uFF1A\u4E00\u7BC7\u5199\u4E00\u76C6\u88AB\u53F0\u98CE\u6380\u5012\u7684\u8309\u8389\uFF0C\u4E00\u7BC7\u5199\u4E00\u961F\u4E0B\u96E8\u524D\u642C\u5BB6\u7684\u8682\u8681\u3002",
      "\u8FD9\u7C7B\u9898\u6700\u5927\u7684\u5751\u662F\u628A\u81EA\u7136\u5199\u6210\u80CC\u666F\u3001\u628A\u611F\u609F\u5199\u6210\u53E3\u53F7\uFF1A\u524D\u534A\u7BC7\u5199\u666F\uFF0C\u540E\u534A\u7BC7\u300C\u751F\u547D\u771F\u987D\u5F3A\uFF0C\u6211\u4EEC\u8981\u70ED\u7231\u5927\u81EA\u7136\u300D\u3002\u8303\u6587\u7684\u529E\u6CD5\u662F\u8BA9\u666F\u7269\u5148\u6709\u80FD\u770B\u89C1\u7684\u7EC6\u8282\uFF08\u78D5\u6389\u4E00\u5757\u7684\u76C6\u53E3\u3001\u88AB\u6C34\u51B2\u6389\u7684\u9ED1\u5370\u5B50\uFF09\uFF0C\u518D\u8BA9\u8BA4\u8BC6\u4ECE\u300C\u6211\u505A\u7684\u4E8B\u300D\u91CC\u957F\u51FA\u6765\u2014\u2014\u7236\u4EB2\u526A\u4E86\u679D\uFF0C\u6211\u8E72\u4E86\u5F88\u4E45\u3002",
      "## \u7ACB\u610F",
      "\u7B2C\u4E00\u7BC7\u7684\u611F\u609F\u843D\u5728\u300C\u4FEE\u8865\u4E0D\u7B49\u4E8E\u590D\u539F\u300D\uFF1A\u526A\u6389\u7684\u90A3\u4E00\u679D\u518D\u6CA1\u6709\u957F\u56DE\u6765\uFF0C\u65B0\u7684\u679D\u4ECE\u65C1\u8FB9\u53E6\u4E00\u4E2A\u5730\u65B9\u957F\u51FA\u53BB\uFF0C\u6700\u540E\u957F\u5F97\u6BD4\u539F\u6765\u8FD8\u5BBD\u3002\u5B83\u4E0D\u5199\u300C\u575A\u6301\u5C31\u6709\u5E0C\u671B\u300D\uFF0C\u53EA\u5199\u4E00\u4EF6\u771F\u4E8B\uFF1A\u574F\u4E86\u7684\u4E1C\u897F\u4F1A\u81EA\u5DF1\u627E\u4E00\u4E2A\u8FD8\u80FD\u7528\u7684\u65B9\u5411\u3002",
      "\u7B2C\u4E8C\u7BC7\u7684\u611F\u609F\u843D\u5728\u300C\u79E9\u5E8F\u4E0D\u662F\u88AB\u8C01\u6307\u6325\u51FA\u6765\u7684\u300D\uFF1A\u8682\u8681\u7684\u961F\u4F0D\u6574\u9F50\u5F97\u8BA9\u4EBA\u4EE5\u4E3A\u6709\u4E2A\u6307\u6325\u5B98\uFF0C\u8E72\u4E45\u4E86\u624D\u53D1\u73B0\u6BCF\u4E00\u53EA\u53EA\u7BA1\u81EA\u5DF1\u9762\u524D\u90A3\u4E00\u6B65\uFF0C\u9ED1\u5370\u5B50\u662F\u5B83\u4EEC\u4E00\u8D9F\u4E00\u8D9F\u8E29\u51FA\u6765\u7684\u3002",
      "\u4E24\u4E2A\u7ACB\u610F\u90FD\u4E0D\u78B0\u300C\u751F\u547D\u7684\u610F\u4E49\u300D\u8FD9\u7C7B\u5927\u8BCD\uFF0C\u90FD\u505C\u5728\u4E00\u4E2A\u521D\u4E2D\u751F\u771F\u80FD\u60F3\u660E\u767D\u7684\u5C3A\u5BF8\u4E0A\u3002\u81EA\u7136\u611F\u609F\u7C7B\u7684\u5206\u6570\u4E0D\u5728\u611F\u609F\u591A\u5927\uFF0C\u5728\u611F\u609F\u51C6\u4E0D\u51C6\uFF1A\u4F60\u770B\u89C1\u7684\u662F\u8FD9\u4E00\u4EF6\u4E8B\uFF0C\u4F60\u8BF4\u51FA\u7684\u5C31\u5F97\u662F\u4E0E\u8FD9\u4E00\u4EF6\u4E8B\u6709\u5173\u7684\u8FD9\u4E00\u70B9\u8BA4\u8BC6\u3002",
      "## \u7ED3\u6784",
      "\u7B2C\u4E00\u7BC7\uFF1A\u53F0\u98CE\u540E\u7684\u72FC\u85C9\uFF08\u666F\uFF09\u2014\u7236\u4EB2\u6276\u82B1\u3001\u7ED1\u7AF9\u7AFF\u3001\u526A\u679D\uFF08\u4E8B\uFF09\u2014\u300C\u7559\u7740\u5B83\u624D\u6B7B\u300D\u4E00\u53E5\u8BDD\u7FFB\u8FC7\u300C\u6551\u300D\u5B57\uFF08\u8F6C\u6298\uFF09\u2014\u4E09\u4E2A\u661F\u671F\u7684\u7B49\u5F85\u4E0E\u526A\u53E3\u4E0B\u7684\u82BD\u70B9\uFF08\u89C2\u5BDF\uFF09\u2014\u65B0\u679D\u6362\u4E86\u65B9\u5411\uFF08\u609F\uFF09\u3002\u5168\u6587\u53EA\u6709\u4E00\u4E2A\u7269\u4EF6\uFF0C\u8BA4\u8BC6\u8DDF\u7740\u679D\u6761\u7684\u65B9\u5411\u4E00\u8D77\u504F\u3002",
      "\u7B2C\u4E8C\u7BC7\uFF1A\u7B49\u8F66\u65F6\u7684\u5076\u7136\u53D1\u73B0\uFF08\u8D77\uFF09\u2014\u8E72\u4E0B\u6765\u770B\uFF0C\u4E45\u5230\u819D\u76D6\u53D1\u9178\uFF08\u4E3A\u4EC0\u4E48\u80FD\u770B\u4E0B\u53BB\uFF09\u2014\u53D1\u73B0\u56FA\u5B9A\u8DEF\u7EBF\u4E0E\u4E24\u53EA\u4E0D\u642C\u4E1C\u897F\u7684\u8682\u8681\uFF08\u89C2\u5BDF\u63A8\u8FDB\uFF09\u2014\u6389\u5728\u6C34\u6CE5\u7F1D\u91CC\u7684\u90A3\u7C92\u5375\uFF08\u523A\u4E00\u4E0B\uFF09\u2014\u96E8\u6765\u3001\u8DEF\u7EBF\u88AB\u51B2\u6389\u3001\u7B2C\u4E09\u5929\u6362\u4E86\u66F4\u9760\u5899\u7684\u4E00\u6761\uFF08\u6536\u675F\uFF09\u2014\u7531\u8682\u8681\u60F3\u5230\u81EA\u5DF1\u505A\u503C\u65E5\u7684\u90A3\u4E00\u6BB5\uFF08\u609F\uFF09\u3002",
      "\u4E24\u7BC7\u7684\u5171\u540C\u70B9\u662F\u89C2\u5BDF\u5FC5\u987B\u6709\u8FC7\u7A0B\uFF1A\u4E0D\u662F\u770B\u4E00\u773C\u5C31\u61C2\uFF0C\u800C\u662F\u8E72\u7740\u770B\u4E86\u5F88\u4E45\u3001\u7B49\u4E0A\u4E86\u4E09\u4E2A\u661F\u671F\u3002\u8FC7\u7A0B\u672C\u8EAB\u5C31\u662F\u6587\u7AE0\u7684\u9AA8\u67B6\uFF0C\u5B83\u66FF\u6389\u4E86\u672C\u8BE5\u7531\u6292\u60C5\u6765\u586B\u7684\u90A3\u4E9B\u4F4D\u7F6E\u3002",
      "## \u4EAE\u70B9",
      "\u7B2C\u4E00\u7BC7\u6700\u89C1\u529F\u529B\u7684\u4E00\u7B14\u662F\u628A\u526A\u679D\u5199\u6210\u4F24\u53E3\uFF1A\u300C\u526A\u53E3\u5728\u79BB\u571F\u4E0D\u5230\u5341\u5398\u7C73\u7684\u5730\u65B9\uFF0C\u767D\u751F\u751F\u7684\uFF0C\u770B\u7740\u50CF\u4F24\u53E3\u300D\uFF0C\u4F5C\u8005\u4E0D\u89E3\u91CA\uFF0C\u8BFB\u8005\u5374\u77E5\u9053\u7236\u4EB2\u90A3\u4E00\u526A\u662F\u72E0\u7684\u3002\u7236\u4EB2\u90A3\u53E5\u300C\u7559\u7740\u5B83\u624D\u6B7B\u3002\u5B83\u81EA\u5DF1\u77E5\u9053\u5F80\u54EA\u513F\u957F\u300D\u662F\u5168\u7BC7\u7684\u5206\u6C34\u5CAD\uFF0C\u628A\u300C\u6551\u300D\u5B57\u7FFB\u4E86\u4E2A\u9762\u3002",
      "\u7B2C\u4E8C\u7BC7\u6700\u597D\u7684\u7EC6\u8282\u662F\u300C\u540E\u9762\u8DDF\u4E0A\u6765\u7684\u8682\u8681\u4ECE\u65C1\u8FB9\u7ED5\u4E86\u8FC7\u53BB\uFF0C\u4E00\u53EA\uFF0C\u4E24\u53EA\uFF0C\u4E09\u53EA\uFF0C\u6CA1\u6709\u8C01\u505C\u4E0B\u6765\u6361\u5B83\u300D\u2014\u2014\u6574\u9F50\u7684\u961F\u4F0D\u91CC\u51FA\u73B0\u4E86\u4E0D\u6574\u9F50\u7684\u4E8B\uFF0C\u4F5C\u8005\u65E2\u4E0D\u66FF\u5B83\u4EEC\u5706\u573A\uFF0C\u4E5F\u4E0D\u628A\u5B83\u5347\u534E\uFF0C\u53EA\u7559\u4E0B\u4E00\u4E2A\u771F\u5B9E\u7684\u7591\u95EE\u3002\u540E\u9762\u8FD8\u6709\u4E00\u5904\u597D\u53E5\uFF1A\u300C\u9ED1\u5370\u5B50\u5C31\u662F\u5B83\u4EEC\u7684\u529F\u52B3\u7C3F\uFF0C\u8C01\u4E5F\u6CA1\u5728\u4E0A\u9762\u5199\u540D\u5B57\u300D\uFF0C\u628A\u89C2\u5BDF\u4E0E\u300C\u6211\u300D\u7684\u5904\u5883\u63A5\u4E0A\u4E86\u3002",
      "\u4E24\u7BC7\u7684\u5171\u540C\u957F\u5904\u662F\u6BD4\u55BB\u7684\u6765\u6E90\u90FD\u5728\u8EAB\u8FB9\uFF1A\u4F24\u53E3\u3001\u73ED\u91CC\u7684\u5C0F\u7EC4\u957F\u3001\u529F\u52B3\u7C3F\uFF0C\u90FD\u662F\u5B66\u751F\u624B\u8FB9\u7684\u4E1C\u897F\uFF0C\u4E0D\u501F\u5927\u4EBA\u7684\u8BCD\uFF0C\u4E5F\u4E0D\u501F\u7F51\u7EDC\u6D41\u884C\u8BED\u3002",
      "## \u53EF\u6539\u8FDB",
      "\u7B2C\u4E00\u7BC7\u91CC\u300C\u6211\u5988\u8BF4\uFF0C\u6254\u4E86\u5427\u300D\u53EA\u7528\u4E86\u4E00\u6B21\u3002\u6BCD\u4EB2\u540E\u6765\u6001\u5EA6\u600E\u4E48\u53D8\u7684\uFF0C\u6587\u7AE0\u6CA1\u6709\u4EA4\u4EE3\uFF1B\u82E5\u5728\u5F00\u82B1\u90A3\u4E00\u6BB5\u8BA9\u6BCD\u4EB2\u4E5F\u8BF4\u4E00\u53E5\u8BDD\uFF0C\u5BB6\u91CC\u4E09\u4E2A\u4EBA\u5C31\u90FD\u5728\u8FD9\u76C6\u82B1\u4E0A\u6709\u4E86\u4F4D\u7F6E\u3002",
      "\u7B2C\u4E8C\u7BC7\u5199\u5230\u300C\u7F1D\u91CC\u7684\u90A3\u7C92\u5375\u5DF2\u7ECF\u4E0D\u5728\u4E86\u300D\uFF0C\u524D\u9762\u90A3\u7C92\u5375\u7684\u7591\u95EE\u88AB\u8F7B\u8F7B\u653E\u6389\u4E86\u3002\u5B83\u53EF\u4EE5\u4E00\u76F4\u7559\u5230\u6700\u540E\uFF0C\u4E0E\u300C\u6211\u300D\u505A\u503C\u65E5\u6CA1\u4EBA\u770B\u89C1\u7684\u90A3\u4E00\u6BB5\u5F62\u6210\u7167\u5E94\uFF0C\u6587\u7AE0\u7684\u7EBF\u5C31\u6536\u5F97\u66F4\u7D27\u3002",
      "\u4E24\u7BC7\u7684\u7ED3\u5C3E\u8BAE\u8BBA\u90FD\u504F\u987A\uFF1A\u7B2C\u4E00\u7BC7\u7684\u300C\u8FD9\u4E2A\u9053\u7406\u8BF4\u5F97\u518D\u6F02\u4EAE\u4E5F\u6CA1\u7528\u300D\u548C\u7B2C\u4E8C\u7BC7\u7684\u300C\u9760\u6BCF\u4E2A\u4EBA\u628A\u81EA\u5DF1\u90A3\u4E00\u6B65\u632A\u5230\u4F4D\u300D\u90FD\u5C5E\u4E8E\u4E3B\u52A8\u628A\u8BDD\u8BF4\u5230\u81EA\u5DF1\u8EAB\u4E0A\uFF0C\u662F\u5408\u683C\u7684\u5199\u6CD5\uFF0C\u4F46\u90FD\u4E0D\u7B97\u65B0\u9C9C\u3002\u82E5\u7ED3\u5C3E\u53EA\u7559\u5177\u4F53\u573A\u9762\uFF08\u7A00\u7A00\u62C9\u62C9\u7684\u4E94\u516D\u6735\u82B1\u3001\u56DB\u5341\u4E8C\u6B65\u7684\u8D70\u5ECA\uFF09\uFF0C\u4F59\u5473\u4F1A\u66F4\u957F\u3002"
    ],
    examples: [
      {
        title: "\u8303\u6587\u4E00\uFF1A\u53F0\u98CE\u8FC7\u540E\u7684\u90A3\u76C6\u8309\u8389",
        prompt: "\u9898\u76EE\uFF1A\u300A\u53F0\u98CE\u4E4B\u540E\u300B\u3002\u8981\u6C42\uFF1A\u5199\u4E00\u7BC7\u4E0D\u5C11\u4E8E 600 \u5B57\u7684\u8BB0\u53D9\u6587\uFF0C\u9009\u4E00\u6B21\u5177\u4F53\u7684\u81EA\u7136\u89C2\u5BDF\uFF0C\u5199\u51FA\u4F60\u4ECE\u4E2D\u5F97\u5230\u7684\u8BA4\u8BC6\uFF1B\u4E0D\u5F97\u7A7A\u6CDB\u6292\u60C5\uFF0C\u4E0D\u5F97\u51FA\u73B0\u300C\u751F\u547D\u7684\u610F\u4E49\u300D\u4E00\u7C7B\u7684\u5927\u8BCD\u3002",
        score: "\u4E00\u7C7B\u6587\uFF0850\u201455 \u5206\uFF09",
        text: "\u53BB\u5E74\u4E5D\u6708\uFF0C\u53F0\u98CE\u5728\u591C\u91CC\u8FC7\u5883\u3002\u6211\u7761\u5F97\u4E0D\u5B9E\uFF0C\u542C\u89C1\u9633\u53F0\u4E0A\u6709\u4EC0\u4E48\u4E1C\u897F\u88AB\u5439\u5012\u4E86\uFF0C\u53C8\u542C\u89C1\u96E8\u70B9\u6253\u5728\u73BB\u7483\u4E0A\uFF0C\u50CF\u6709\u4EBA\u6293\u7740\u4E00\u628A\u7EC6\u6C99\u4E0D\u505C\u5730\u6492\u3002\n\u7B2C\u4E8C\u5929\u65E9\u4E0A\u51FA\u95E8\uFF0C\u9633\u53F0\u4E0A\u4E00\u7247\u72FC\u85C9\uFF1A\u667E\u8863\u6746\u6B6A\u4E86\uFF0C\u5851\u6599\u76C6\u6EDA\u5230\u4E86\u5899\u89D2\uFF0C\u90A3\u76C6\u8309\u8389\u4E5F\u5012\u4E86\u3002\u5B83\u672C\u6765\u653E\u5728\u6700\u5916\u9762\u7684\u6C34\u6CE5\u53F0\u4E0A\uFF0C\u662F\u6211\u4EEC\u5BB6\u517B\u5F97\u6700\u4E45\u7684\u4E00\u76C6\u82B1\u3002\u82B1\u76C6\u662F\u7236\u4EB2\u4ECE\u65E7\u8D27\u5E02\u573A\u6DD8\u6765\u7684\u9752\u7070\u8272\u74E6\u76C6\uFF0C\u76C6\u53E3\u78D5\u6389\u8FC7\u4E00\u5C0F\u5757\u3002\u53F0\u98CE\u628A\u5B83\u4ECE\u53F0\u4E0A\u6380\u4E0B\u6765\uFF0C\u4E00\u679D\u4E3B\u5E72\u6298\u4E86\uFF0C\u5269\u4E0B\u7684\u679D\u6761\u8D34\u7740\u5730\u9762\uFF0C\u53F6\u5B50\u6389\u4E86\u4E00\u591A\u534A\uFF0C\u6CE5\u571F\u4ECE\u76C6\u91CC\u6D12\u51FA\u6765\uFF0C\u5728\u9633\u53F0\u4E0A\u644A\u6210\u4E00\u5C0F\u7247\u3002\n\u6211\u5988\u8BF4\uFF0C\u6254\u4E86\u5427\u3002\u7236\u4EB2\u6CA1\u8BF4\u8BDD\u3002\u4ED6\u62FF\u4E86\u4E00\u628A\u626B\u5E1A\uFF0C\u5148\u628A\u571F\u626B\u56DE\u76C6\u91CC\uFF0C\u7528\u624B\u538B\u4E86\u538B\uFF0C\u518D\u628A\u8309\u8389\u6276\u8D77\u6765\uFF0C\u8BD5\u4E86\u4E24\u6B21\uFF0C\u5B83\u90FD\u5F80\u4E00\u8FB9\u5012\u2014\u2014\u6298\u7684\u90A3\u4E00\u679D\u592A\u91CD\uFF0C\u628A\u5B83\u6574\u4E2A\u62FD\u504F\u4E86\u3002\u4ED6\u4ECE\u5DE5\u5177\u7BB1\u91CC\u7FFB\u51FA\u4E00\u6839\u65E7\u7AF9\u7AFF\uFF0C\u63D2\u8FDB\u76C6\u8FB9\uFF0C\u7528\u4E00\u6761\u526A\u5F00\u7684\u65E7\u68C9\u5E03\u6761\u628A\u4E3B\u5E72\u548C\u7AF9\u7AFF\u7ED1\u5728\u4E00\u8D77\uFF0C\u7ED1\u4E86\u4E09\u9053\u3002\n\u6211\u4EE5\u4E3A\u8FD9\u4E8B\u5C31\u5B8C\u4E86\u3002\u7B2C\u4E09\u5929\u653E\u5B66\u56DE\u5BB6\uFF0C\u6211\u770B\u89C1\u7236\u4EB2\u8E72\u5728\u76C6\u8FB9\uFF0C\u628A\u6298\u4E86\u4E00\u534A\u7684\u90A3\u679D\u526A\u6389\u4E86\u3002\u526A\u53E3\u5728\u79BB\u571F\u4E0D\u5230\u5341\u5398\u7C73\u7684\u5730\u65B9\uFF0C\u767D\u751F\u751F\u7684\uFF0C\u770B\u7740\u50CF\u4F24\u53E3\u3002\u6211\u8BF4\uFF1A\u300C\u4F60\u4E0D\u662F\u8981\u6551\u5B83\u5417\uFF1F\u300D\u4ED6\u8BF4\uFF1A\u300C\u7559\u7740\u5B83\u624D\u6B7B\u3002\u5B83\u81EA\u5DF1\u77E5\u9053\u5F80\u54EA\u513F\u957F\u3002\u300D\n\u63A5\u4E0B\u6765\u7684\u4E24\u4E2A\u661F\u671F\uFF0C\u90A3\u76C6\u8309\u8389\u4E00\u76F4\u6CA1\u6709\u8D77\u8272\u3002\u53F6\u5B50\u7EE7\u7EED\u9EC4\uFF0C\u5269\u4E0B\u4E00\u4E24\u7247\u4E5F\u5377\u4E86\u8D77\u6765\u3002\u6211\u6BCF\u5929\u653E\u5B66\u90FD\u8981\u770B\u4E00\u773C\uFF0C\u8D8A\u770B\u8D8A\u89C9\u5F97\u7236\u4EB2\u90A3\u6B21\u767D\u8D39\u4E86\u529B\u6C14\u3002\u6709\u4E00\u6B21\u6211\u628A\u624B\u4F38\u8FDB\u571F\u91CC\u6478\u4E86\u6478\uFF0C\u662F\u6E7F\u7684\uFF0C\u8BF4\u660E\u4ED6\u8FD8\u5728\u6D47\u6C34\u3002\n\u7B2C\u4E09\u4E2A\u661F\u671F\u7684\u65E9\u4E0A\uFF0C\u6211\u5728\u526A\u53E3\u4E0B\u9762\u770B\u89C1\u4E00\u4E2A\u5C0F\u70B9\uFF0C\u9752\u7684\uFF0C\u50CF\u9488\u5C16\u4E0A\u6311\u4E86\u4E00\u70B9\u7EFF\u3002\u51E0\u5929\u4E4B\u540E\uFF0C\u90A3\u4E2A\u70B9\u957F\u6210\u4E86\u82BD\u3002\u5B83\u6CA1\u6709\u957F\u5728\u539F\u6765\u7684\u4F4D\u7F6E\u4E0A\uFF0C\u800C\u662F\u4ECE\u526A\u53E3\u65C1\u8FB9\u7684\u5206\u53C9\u5904\u957F\u51FA\u6765\uFF0C\u671D\u7740\u9633\u53F0\u5916\u9762\u659C\u7740\u8D70\u2014\u2014\u90A3\u6B63\u662F\u539F\u6765\u88AB\u7AF9\u7AFF\u6321\u4F4F\u7684\u65B9\u5411\u3002\n\u540E\u6765\u53C8\u8FC7\u4E86\u4E00\u4E2A\u591A\u6708\uFF0C\u5B83\u62BD\u51FA\u4E86\u4E09\u6761\u65B0\u679D\uFF0C\u6700\u957F\u7684\u957F\u5230\u534A\u5C3A\u3002\u65B0\u679D\u4E0D\u76F4\uFF0C\u5148\u659C\u7740\u5F80\u5916\uFF0C\u518D\u6162\u6162\u5F80\u4E0A\u62AC\uFF0C\u8D70\u5F97\u6B6A\u6B6A\u626D\u626D\uFF0C\u4F46\u65B9\u5411\u662F\u7A33\u7684\u3002\u5341\u6708\u91CC\u5B83\u7ADF\u7136\u53C8\u5F00\u4E86\u82B1\uFF0C\u7A00\u7A00\u62C9\u62C9\u4E94\u516D\u6735\uFF0C\u95FB\u8D77\u6765\u8FD8\u662F\u90A3\u4E2A\u5473\u9053\u3002\n\u6211\u4E00\u76F4\u4EE5\u4E3A\uFF0C\u628A\u4E00\u76C6\u82B1\u517B\u597D\u5C31\u662F\u8BA9\u5B83\u56DE\u5230\u539F\u6765\u7684\u6837\u5B50\uFF1A\u53F6\u5B50\u90FD\u957F\u56DE\u6765\uFF0C\u679D\u6761\u7AD9\u76F4\uFF0C\u82B1\u5F00\u5F97\u8DDF\u53BB\u5E74\u4E00\u6837\u591A\u3002\u53EF\u5B83\u6CA1\u6709\u3002\u526A\u6389\u7684\u90A3\u4E00\u679D\u518D\u6CA1\u6709\u957F\u51FA\u6765\uFF0C\u65B0\u7684\u679D\u4ECE\u65C1\u8FB9\u53E6\u4E00\u4E2A\u5730\u65B9\u957F\u51FA\u53BB\uFF0C\u6700\u540E\u957F\u5F97\u6BD4\u539F\u6765\u90A3\u76C6\u8FD8\u5BBD\u3002\n\u539F\u6765\u6709\u4E9B\u4E1C\u897F\u574F\u4E86\uFF0C\u662F\u4E0D\u7528\u63B0\u56DE\u539F\u4F4D\u3001\u4E5F\u4E0D\u4E00\u5B9A\u80FD\u4FEE\u56DE\u539F\u6837\u7684\u3002\u5B83\u4F1A\u81EA\u5DF1\u627E\u4E00\u4E2A\u8FD8\u80FD\u7528\u7684\u5730\u65B9\uFF0C\u628A\u529B\u6C14\u632A\u8FC7\u53BB\u3002\u8FD9\u4E2A\u9053\u7406\u8BF4\u5F97\u518D\u6F02\u4EAE\u4E5F\u6CA1\u7528\uFF0C\u5F97\u81EA\u5DF1\u8E72\u5728\u76C6\u8FB9\u7B49\u4E0A\u4E09\u4E2A\u661F\u671F\uFF0C\u624D\u770B\u5F97\u61C2\u3002",
        highlights: [
          {
            sentence: "\u526A\u53E3\u5728\u79BB\u571F\u4E0D\u5230\u5341\u5398\u7C73\u7684\u5730\u65B9\uFF0C\u767D\u751F\u751F\u7684\uFF0C\u770B\u7740\u50CF\u4F24\u53E3\u3002",
            why: "\u526A\u679D\u672C\u6765\u662F\u4E2A\u5904\u7406\u690D\u7269\u7684\u52A8\u4F5C\uFF0C\u4F5C\u8005\u7ED9\u51FA\u4F4D\u7F6E\u3001\u989C\u8272\uFF0C\u518D\u52A0\u4E00\u4E2A\u4E0D\u5938\u5F20\u7684\u6BD4\u55BB\uFF0C\u4E00\u4E0B\u5B50\u628A\u5B83\u5199\u6210\u4E86\u4E00\u4EF6\u72E0\u4E8B\uFF1B\u4E0D\u89E3\u91CA\u7236\u4EB2\u7684\u5FC3\u60C5\uFF0C\u5FC3\u60C5\u5374\u5168\u5728\u8FD9\u4E2A\u526A\u53E3\u4E0A\u3002"
          },
          {
            sentence: "\u300C\u7559\u7740\u5B83\u624D\u6B7B\u3002\u5B83\u81EA\u5DF1\u77E5\u9053\u5F80\u54EA\u513F\u957F\u3002\u300D",
            why: "\u7236\u4EB2\u7684\u4E24\u53E5\u77ED\u8BDD\uFF0C\u628A\u300C\u6551\u300D\u5B57\u7684\u542B\u4E49\u7FFB\u4E86\u8FC7\u6765\uFF1A\u771F\u6B63\u7684\u6551\u4E0D\u662F\u7EF4\u6301\u539F\u72B6\uFF0C\u800C\u662F\u8BA9\u6D3B\u7684\u529B\u6C14\u53BB\u522B\u5904\u3002\u4EBA\u7269\u4E0D\u6292\u60C5\uFF0C\u4E00\u53E5\u8BDD\u7ACB\u4F4F\u4E86\u4ED6\u7684\u89C1\u8BC6\u3002"
          },
          {
            sentence: "\u65B0\u679D\u4E0D\u76F4\uFF0C\u5148\u659C\u7740\u5F80\u5916\uFF0C\u518D\u6162\u6162\u5F80\u4E0A\u62AC\uFF0C\u8D70\u5F97\u6B6A\u6B6A\u626D\u626D\uFF0C\u4F46\u65B9\u5411\u662F\u7A33\u7684\u3002",
            why: "\u628A\u65B0\u679D\u7684\u5F62\u72B6\u5199\u6210\u4E00\u4E2A\u52A8\u4F5C\u8FC7\u7A0B\uFF08\u659C\u7740\u8D70\u3001\u5F80\u4E0A\u62AC\uFF09\uFF0C\u518D\u8865\u4E00\u53E5\u5224\u65AD\uFF1B\u53E5\u5B50\u672C\u8EAB\u5C31\u50CF\u5B83\u5199\u7684\u90A3\u6839\u679D\u6761\uFF0C\u6B6A\u7740\uFF0C\u4F46\u4E0D\u6563\u3002"
          },
          {
            sentence: "\u539F\u6765\u6709\u4E9B\u4E1C\u897F\u574F\u4E86\uFF0C\u662F\u4E0D\u7528\u63B0\u56DE\u539F\u4F4D\u3001\u4E5F\u4E0D\u4E00\u5B9A\u80FD\u4FEE\u56DE\u539F\u6837\u7684\u3002",
            why: "\u5168\u6587\u7684\u8BA4\u8BC6\u53EA\u5230\u8FD9\u4E00\u53E5\u4E3A\u6B62\uFF0C\u6CA1\u6709\u6ED1\u5411\u300C\u751F\u547D\u771F\u987D\u5F3A\u300D\uFF1B\u300C\u63B0\u56DE\u539F\u4F4D\u300D\u662F\u5B66\u751F\u81EA\u5DF1\u7684\u8BDD\uFF0C\u8BF4\u5F97\u571F\u4E00\u70B9\uFF0C\u53CD\u800C\u53EF\u4FE1\u3002"
          }
        ],
        review: [
          {
            aspect: "\u5BA1\u9898\u7ACB\u610F",
            text: "\u6263\u4F4F\u300C\u4E4B\u540E\u300D\u4E8C\u5B57\uFF0C\u4E0D\u5199\u53F0\u98CE\u672C\u8EAB\uFF0C\u53EA\u5199\u53F0\u98CE\u8FC7\u540E\u4E09\u4E2A\u661F\u671F\u91CC\u4E00\u76C6\u82B1\u7684\u53D8\u5316\uFF1B\u7ACB\u610F\u4E0D\u843D\u5728\u575A\u5F3A\u4E0A\uFF0C\u800C\u843D\u5728\u300C\u4FEE\u8865\u4E0D\u7B49\u4E8E\u590D\u539F\u300D\uFF0C\u6BD4\u540C\u9898\u4F5C\u6587\u5E38\u89C1\u7684\u300C\u751F\u547D\u529B\u771F\u987D\u5F3A\u300D\u9AD8\u51FA\u4E00\u5C42\uFF0C\u4E5F\u907F\u5F00\u4E86\u5927\u8BCD\u3002"
          },
          {
            aspect: "\u7ED3\u6784\u5E03\u5C40",
            text: "\u72FC\u85C9\uFF08\u666F\uFF09\u2014\u6276\u4E0E\u7ED1\uFF08\u7236\u4EB2\u7684\u7B2C\u4E00\u6B21\u52AA\u529B\uFF09\u2014\u526A\u679D\uFF08\u8F6C\u6298\u4E0E\u5173\u952E\u4E00\u53E5\u8BDD\uFF09\u2014\u4E24\u5468\u65E0\u53D8\u5316\uFF08\u5199\u300C\u4EC0\u4E48\u4E5F\u6CA1\u53D1\u751F\u300D\uFF09\u2014\u82BD\u70B9\u2014\u65B0\u679D\u6362\u5411\uFF08\u609F\uFF09\u3002\u5168\u6587\u53EA\u56F4\u7ED5\u4E00\u76C6\u82B1\u63A8\u8FDB\uFF0C\u6CA1\u6709\u65C1\u679D\uFF0C\u8282\u594F\u7531\u7D27\u5230\u677E\uFF0C\u4E0E\u690D\u7269\u7684\u6062\u590D\u901F\u5EA6\u4E00\u81F4\u3002"
          },
          {
            aspect: "\u8BED\u8A00\u8868\u8FBE",
            text: "\u901A\u7BC7\u77ED\u53E5\u4E0E\u52A8\u4F5C\u63CF\u5199\uFF0C\u300C\u626B\u3001\u538B\u3001\u6276\u3001\u7ED1\u3001\u526A\u300D\u4E00\u8FDE\u4E32\u52A8\u8BCD\u5199\u7236\u4EB2\uFF1B\u6BD4\u55BB\u53EA\u7528\u8EAB\u8FB9\u7684\u7269\uFF08\u7EC6\u6C99\u3001\u4F24\u53E3\u3001\u9488\u5C16\uFF09\uFF0C\u8BED\u611F\u6734\u7D20\u3002\u5BF9\u8BDD\u6781\u5C11\uFF0C\u7236\u4EB2\u4E24\u53E5\u3001\u6BCD\u4EB2\u4E00\u53E5\uFF0C\u90FD\u843D\u5728\u4EBA\u7269\u6027\u683C\u4E0A\u3002"
          },
          {
            aspect: "\u7D20\u6750\u8FD0\u7528",
            text: "\u300C\u65E7\u8D27\u5E02\u573A\u6DD8\u6765\u7684\u9752\u7070\u8272\u74E6\u76C6\uFF0C\u76C6\u53E3\u78D5\u6389\u8FC7\u4E00\u5C0F\u5757\u300D\u4E00\u53E5\u4EA4\u4EE3\u4E86\u8FD9\u76C6\u82B1\u5728\u5BB6\u7684\u5E74\u5934\u4E0E\u5730\u4F4D\uFF0C\u4E3A\u540E\u6587\u4E0D\u80AF\u6254\u5B83\u63D0\u4F9B\u4E86\u7406\u7531\uFF1B\u300C\u624B\u4F38\u8FDB\u571F\u91CC\u6478\u4E86\u6478\uFF0C\u662F\u6E7F\u7684\u300D\u7528\u4E00\u4E2A\u89E6\u89C9\u7EC6\u8282\u8BF4\u660E\u7236\u4EB2\u4ECD\u5728\u7167\u6599\uFF0C\u6BD4\u5199\u300C\u7236\u4EB2\u6CA1\u6709\u653E\u5F03\u300D\u6709\u6548\u5F97\u591A\u3002"
          },
          {
            aspect: "\u5347\u683C\u5EFA\u8BAE",
            text: "\u7ED3\u5C3E\u4E24\u53E5\u8BAE\u8BBA\u504F\u76F4\uFF0C\u5C24\u5176\u300C\u8FD9\u4E2A\u9053\u7406\u8BF4\u5F97\u518D\u6F02\u4EAE\u4E5F\u6CA1\u7528\u300D\u6709\u8BF4\u6559\u6C14\uFF0C\u53EF\u4EE5\u5220\u6389\uFF0C\u53EA\u7559\u300C\u5B83\u4F1A\u81EA\u5DF1\u627E\u4E00\u4E2A\u8FD8\u80FD\u7528\u7684\u5730\u65B9\u300D\uFF1B\u5F00\u82B1\u7684\u6BB5\u843D\u53EF\u4EE5\u5199\u51FA\u82B1\u7684\u4F4D\u7F6E\uFF08\u957F\u5728\u65B0\u679D\u4E0A\uFF0C\u4E0D\u5728\u65E7\u679D\u4E0A\uFF09\uFF0C\u8BA9\u300C\u6362\u4E86\u65B9\u5411\u300D\u8FD9\u4E00\u70B9\u7531\u4E8B\u5B9E\u81EA\u5DF1\u8BF4\u660E\uFF1B\u6BCD\u4EB2\u7684\u6001\u5EA6\u524D\u540E\u7F3A\u5C11\u53D8\u5316\uFF0C\u8865\u4E00\u53E5\u5979\u770B\u82B1\u7684\u8BDD\uFF0C\u5168\u7BC7\u7684\u4EBA\u7269\u5173\u7CFB\u4F1A\u66F4\u5B8C\u6574\u3002"
          }
        ],
        comment: "\u8FD9\u7BC7\u7684\u957F\u5904\u662F\u300C\u53EA\u5199\u4E00\u76C6\u82B1\uFF0C\u5199\u900F\u4E00\u76C6\u82B1\u300D\u3002\u4ECE\u5934\u5230\u5C3E\u6CA1\u6709\u79BB\u5F00\u9752\u7070\u8272\u74E6\u76C6\uFF1A\u6380\u5012\u3001\u626B\u571F\u3001\u7ED1\u7AF9\u7AFF\u3001\u526A\u679D\u3001\u62BD\u82BD\u3001\u5F00\u82B1\uFF0C\u6BCF\u4E2A\u52A8\u4F5C\u90FD\u5BF9\u7740\u4E00\u4EF6\u5177\u4F53\u7684\u7269\uFF0C\u8BFB\u8005\u56E0\u6B64\u770B\u5F97\u89C1\uFF0C\u4E5F\u4FE1\u5F97\u8FC7\u3002\u6700\u51FA\u8272\u7684\u662F\u7ACB\u610F\u7684\u5206\u5BF8\uFF1A\u5B83\u627F\u8BA4\u526A\u6389\u7684\u90A3\u4E00\u679D\u518D\u4E0D\u4F1A\u957F\u56DE\u6765\uFF0C\u53EA\u627F\u8BA4\u5269\u4E0B\u7684\u4E00\u622A\u627E\u5230\u4E86\u53E6\u4E00\u4E2A\u65B9\u5411\u2014\u2014\u8FD9\u4EFD\u8BDA\u5B9E\uFF0C\u6BD4\u300C\u9006\u5883\u4E2D\u6210\u957F\u300D\u7684\u7ED3\u8BBA\u91CD\u5F97\u591A\u3002\u7236\u4EB2\u7684\u4E24\u53E5\u8BDD\u662F\u5168\u7BC7\u7684\u652F\u70B9\uFF0C\u300C\u7559\u7740\u5B83\u624D\u6B7B\u300D\u628A\u300C\u6551\u300D\u5B57\u7FFB\u4E86\u4E2A\u9762\uFF0C\u662F\u540C\u7C7B\u4F5C\u6587\u91CC\u5C11\u89C1\u7684\u597D\u53E5\u3002\u4E0D\u8DB3\u6709\u4E8C\uFF1A\u7ED3\u5C3E\u8BAE\u8BBA\u8BF4\u5F97\u504F\u6EE1\uFF0C\u300C\u8BF4\u5F97\u518D\u6F02\u4EAE\u4E5F\u6CA1\u7528\u300D\u5E26\u7740\u8BF4\u6559\u6C14\uFF0C\u7559\u4E00\u53E5\u5C31\u591F\uFF1B\u6BCD\u4EB2\u53EA\u51FA\u73B0\u5728\u7B2C\u4E8C\u6BB5\u8BF4\u300C\u6254\u4E86\u5427\u300D\uFF0C\u540E\u9762\u518D\u65E0\u58F0\u97F3\uFF0C\u5BB6\u91CC\u4E09\u4E2A\u4EBA\u7684\u5173\u7CFB\u53EA\u7528\u4E86\u4E00\u4E2A\u4EBA\u7684\u773C\u775B\u770B\uFF0C\u7565\u663E\u5355\u8584\u3002"
      },
      {
        title: "\u8303\u6587\u4E8C\uFF1A\u4E0B\u96E8\u524D\u7684\u90A3\u4E00\u961F\u8682\u8681",
        prompt: "\u9898\u76EE\uFF1A\u300A\u6211\u8E72\u4E86\u5F88\u4E45\u300B\u3002\u8981\u6C42\uFF1A\u5199\u4E00\u7BC7\u4E0D\u5C11\u4E8E 600 \u5B57\u7684\u8BB0\u53D9\u6587\uFF0C\u4EE5\u4E00\u6B21\u5177\u4F53\u7684\u81EA\u7136\u89C2\u5BDF\u4E3A\u5BF9\u8C61\uFF0C\u8981\u6709\u89C2\u5BDF\u7684\u8FC7\u7A0B\u4E0E\u8BA4\u8BC6\u7684\u53D8\u5316\uFF0C\u4E0D\u80FD\u5199\u6210\u5199\u666F\u6292\u60C5\u6587\u3002",
        score: "\u4E00\u7C7B\u6587\u4E0B\uFF0846\u201449 \u5206\uFF09",
        text: "\u516D\u6708\u521D\u7684\u4E00\u4E2A\u4E0B\u5348\uFF0C\u5929\u538B\u5F97\u5F88\u4F4E\uFF0C\u8749\u8FD8\u5728\u53EB\uFF0C\u98CE\u4E00\u4E1D\u4E5F\u6CA1\u6709\u3002\u6211\u5728\u697C\u4E0B\u7B49\u5988\u5988\u6765\u63A5\uFF0C\u7AD9\u5728\u5355\u5143\u95E8\u53E3\u7684\u6C34\u6CE5\u53F0\u9636\u4E0A\uFF0C\u770B\u89C1\u811A\u8FB9\u6709\u4E00\u6761\u9ED1\u7EBF\u5728\u52A8\u3002\n\u90A3\u4E0D\u662F\u7EBF\uFF0C\u662F\u8682\u8681\u3002\u5B83\u4EEC\u4ECE\u53F0\u9636\u4E0B\u82B1\u575B\u7684\u7F1D\u9699\u91CC\u51FA\u6765\uFF0C\u6CBF\u7740\u6C34\u6CE5\u5730\u7684\u4E00\u9053\u7F1D\u5F80\u524D\u8D70\uFF0C\u5230\u5899\u89D2\u53C8\u62D0\u5F2F\uFF0C\u4E00\u8DEF\u8D70\u8FDB\u9999\u6A1F\u6811\u6839\u5E95\u4E0B\u3002\u961F\u4F0D\u5F88\u5BC6\uFF0C\u524D\u540E\u51E0\u4E4E\u63A5\u4E0A\uFF0C\u6BCF\u4E00\u53EA\u7684\u5634\u91CC\u6216\u8005\u524D\u80A2\u4E0A\u90FD\u9876\u7740\u4E00\u7C92\u767D\u8272\u7684\u4E1C\u897F\uFF0C\u6BD4\u5B83\u81EA\u5DF1\u7684\u8EAB\u4F53\u8FD8\u5927\uFF0C\u4E3E\u5F97\u9AD8\u9AD8\u7684\uFF0C\u50CF\u8C01\u5728\u62AC\u4E00\u53E3\u5F88\u5C0F\u7684\u767D\u7BB1\u5B50\u3002\u6211\u77E5\u9053\u90A3\u662F\u5375\u3002\n\u6211\u672C\u6765\u5728\u50AC\u5988\u5988\u5FEB\u70B9\uFF0C\u7535\u8BDD\u4E5F\u6253\u8FC7\u4E86\u3002\u53EF\u770B\u7740\u770B\u7740\u5C31\u5FD8\u4E86\u3002\u6211\u8E72\u4E0B\u6765\uFF0C\u8E72\u4E86\u5F88\u4E45\uFF0C\u4E45\u5230\u819D\u76D6\u53D1\u9178\u3002\u6211\u770B\u89C1\u961F\u4F0D\u6709\u56FA\u5B9A\u7684\u8DEF\u7EBF\uFF1A\u5B83\u4EEC\u4E0D\u662F\u6563\u7740\u8D70\uFF0C\u5168\u90FD\u8E29\u7740\u540C\u4E00\u6761\u5370\u5B50\uFF0C\u90A3\u6761\u5370\u5B50\u6BD4\u522B\u5904\u989C\u8272\u6DF1\u4E00\u70B9\uFF0C\u50CF\u88AB\u8C01\u7528\u94C5\u7B14\u8F7B\u8F7B\u5212\u8FC7\u3002\n\u6211\u8FD8\u770B\u89C1\u4E00\u4EF6\u5947\u602A\u7684\u4E8B\u3002\u961F\u4F0D\u4E2D\u95F4\u6709\u4E00\u4E24\u53EA\u8682\u8681\u8EAB\u4E0A\u4EC0\u4E48\u4E5F\u6CA1\u625B\uFF0C\u6765\u56DE\u5730\u8DD1\uFF0C\u8DDF\u8FD9\u4E2A\u78B0\u4E00\u4E0B\u89E6\u89D2\uFF0C\u8DDF\u90A3\u4E2A\u78B0\u4E00\u4E0B\u89E6\u89D2\u3002\u6211\u4E00\u5F00\u59CB\u8BA4\u5B9A\u5B83\u4EEC\u662F\u300C\u6307\u6325\u7684\u300D\uFF0C\u5C31\u50CF\u73ED\u91CC\u7684\u5C0F\u7EC4\u957F\uFF0C\u8D1F\u8D23\u50AC\u522B\u4EBA\u5FEB\u70B9\u8D70\u3002\u770B\u4E86\u4E00\u4F1A\u513F\u6211\u624D\u53D1\u73B0\uFF0C\u90A3\u4E24\u53EA\u78B0\u8FC7\u89E6\u89D2\u4E4B\u540E\u4E5F\u62D0\u56DE\u53BB\u642C\u4E1C\u897F\u4E86\uFF0C\u800C\u4E14\u5B83\u4EEC\u8D70\u7684\u65B9\u5411\u8DDF\u522B\u4EBA\u4E0D\u4E00\u6837\uFF0C\u662F\u9006\u7740\u961F\u4F0D\u8D70\u7684\u3002\n\u6709\u4E00\u7C92\u5375\u5728\u6C34\u6CE5\u7F1D\u8FB9\u4E0A\u6389\u4E86\u3002\u5B83\u6EDA\u4E86\u534A\u5708\uFF0C\u5361\u5728\u90A3\u91CC\u3002\u540E\u9762\u8DDF\u4E0A\u6765\u7684\u8682\u8681\u4ECE\u65C1\u8FB9\u7ED5\u4E86\u8FC7\u53BB\uFF0C\u4E00\u53EA\uFF0C\u4E24\u53EA\uFF0C\u4E09\u53EA\uFF0C\u6CA1\u6709\u8C01\u505C\u4E0B\u6765\u6361\u5B83\u3002\u6211\u5F53\u65F6\u6709\u70B9\u66FF\u5B83\u59D4\u5C48\uFF0C\u89C9\u5F97\u8FD9\u4E48\u6574\u9F50\u7684\u961F\u4F0D\u600E\u4E48\u8FD9\u4E48\u4E0D\u8BB2\u7A76\u3002\u7B49\u7B2C\u4E8C\u5929\u6211\u53C8\u7ECF\u8FC7\u90A3\u91CC\uFF0C\u770B\u89C1\u7F1D\u91CC\u7684\u90A3\u7C92\u5375\u5DF2\u7ECF\u4E0D\u5728\u4E86\u2014\u2014\u662F\u88AB\u54EA\u4E00\u53EA\u987A\u624B\u5E26\u8D70\u4E86\uFF0C\u8FD8\u662F\u88AB\u592A\u9633\u6652\u5E72\u4E86\uFF0C\u6211\u4E0D\u77E5\u9053\u3002\n\u98CE\u7EC8\u4E8E\u6765\u4E86\uFF0C\u7B2C\u4E00\u6EF4\u96E8\u7838\u5728\u53F0\u9636\u4E0A\uFF0C\u7838\u51FA\u4E00\u4E2A\u6DF1\u8272\u7684\u5706\u70B9\u3002\u6211\u62AC\u5934\u65F6\uFF0C\u961F\u4F0D\u8FD8\u5728\u8D70\uFF0C\u6700\u540E\u4E00\u622A\u8FD8\u6CA1\u8FDB\u5C4B\u3002\u540E\u6765\u96E8\u5927\u4E86\uFF0C\u90A3\u6761\u9ED1\u5370\u5B50\u88AB\u51B2\u6CA1\u4E86\u3002\n\u7B2C\u4E09\u5929\u6211\u518D\u53BB\u770B\uFF0C\u5B83\u4EEC\u6362\u4E86\u4E00\u6761\u8DEF\uFF0C\u6BD4\u539F\u6765\u90A3\u6761\u66F4\u9760\u5899\uFF0C\u8D34\u7740\u4E00\u9053\u5E72\u7684\u5899\u6839\u8D70\u3002\u6211\u5728\u90A3\u513F\u53C8\u8E72\u4E86\u4E00\u4F1A\u513F\uFF0C\u819D\u76D6\u8FD8\u662F\u9178\u7684\u3002\n\u5728\u90A3\u4E4B\u524D\u6211\u4E00\u76F4\u4EE5\u4E3A\uFF0C\u8FD9\u4E48\u6574\u9F50\u7684\u4E00\u652F\u961F\u4F0D\u80AF\u5B9A\u6709\u4EBA\u5728\u7BA1\u3002\u6211\u4EEC\u73ED\u505A\u503C\u65E5\u4E5F\u662F\u8FD9\u6837\uFF0C\u603B\u5F97\u6709\u4EBA\u558A\u4E00\u58F0\uFF1A\u300C\u8C01\u53BB\u5012\u5783\u573E\uFF1F\u300D\u53EF\u8682\u8681\u6CA1\u6709\u6307\u6325\u7684\uFF0C\u4E5F\u6CA1\u6709\u558A\u7684\u3002\u6BCF\u4E00\u53EA\u53EA\u7BA1\u5B83\u9762\u524D\u90A3\u4E00\u6B65\u8DEF\uFF0C\u628A\u4E1C\u897F\u5F80\u524D\u632A\uFF0C\u632A\u5230\u8BE5\u4EA4\u7ED9\u4E0B\u4E00\u53EA\u7684\u5730\u65B9\u5C31\u56DE\u5934\u3002\u8DEF\u662F\u5B83\u4EEC\u4E00\u8D9F\u4E00\u8D9F\u8E29\u51FA\u6765\u7684\uFF0C\u90A3\u6761\u9ED1\u5370\u5B50\u5C31\u662F\u5B83\u4EEC\u7684\u529F\u52B3\u7C3F\uFF0C\u8C01\u4E5F\u6CA1\u5728\u4E0A\u9762\u5199\u540D\u5B57\u3002\n\u6211\u4EEC\u73ED\u505A\u503C\u65E5\u7684\u90A3\u6761\u8D70\u5ECA\uFF0C\u4ECE\u6559\u5BA4\u95E8\u53E3\u5230\u697C\u68AF\u53E3\uFF0C\u4E00\u5171\u56DB\u5341\u4E8C\u6B65\u3002\u6CA1\u6709\u4EBA\u77E5\u9053\u6211\u6BCF\u5929\u626B\u7684\u662F\u54EA\u4E00\u6BB5\u3002\u73B0\u5728\u6211\u77E5\u9053\u4E86\uFF1A\u4E00\u6BB5\u8DEF\u80FD\u5E72\u51C0\uFF0C\u9760\u7684\u4E0D\u662F\u8C01\u8BB0\u5F97\u6211\uFF0C\u662F\u9760\u6BCF\u4E00\u4E2A\u4EBA\u628A\u81EA\u5DF1\u90A3\u4E00\u6B65\u632A\u5230\u4F4D\u3002",
        highlights: [
          {
            sentence: "\u5B83\u4EEC\u4E0D\u662F\u6563\u7740\u8D70\uFF0C\u5168\u90FD\u8E29\u7740\u540C\u4E00\u6761\u5370\u5B50\uFF0C\u90A3\u6761\u5370\u5B50\u6BD4\u522B\u5904\u989C\u8272\u6DF1\u4E00\u70B9\uFF0C\u50CF\u88AB\u8C01\u7528\u94C5\u7B14\u8F7B\u8F7B\u5212\u8FC7\u3002",
            why: "\u5148\u5426\u5B9A\u4E00\u4E2A\u5E38\u89C1\u7684\u9519\u89C9\uFF08\u6563\u7740\u8D70\uFF09\uFF0C\u518D\u7ED9\u51FA\u771F\u6B63\u7684\u89C2\u5BDF\uFF1B\u300C\u94C5\u7B14\u8F7B\u8F7B\u5212\u8FC7\u300D\u628A\u4E00\u6761\u866B\u8DEF\u5199\u5F97\u53EF\u770B\u53EF\u89E6\uFF0C\u4E5F\u4E3A\u7ED3\u5C3E\u7684\u300C\u529F\u52B3\u7C3F\u300D\u57CB\u4E0B\u4F0F\u7B14\u3002"
          },
          {
            sentence: "\u6211\u4E00\u5F00\u59CB\u8BA4\u5B9A\u5B83\u4EEC\u662F\u300C\u6307\u6325\u7684\u300D\uFF0C\u5C31\u50CF\u73ED\u91CC\u7684\u5C0F\u7EC4\u957F\uFF0C\u8D1F\u8D23\u50AC\u522B\u4EBA\u5FEB\u70B9\u8D70\u3002",
            why: "\u6562\u5199\u51FA\u81EA\u5DF1\u7684\u9519\u8BEF\u5224\u65AD\uFF0C\u89C2\u5BDF\u6587\u624D\u6709\u300C\u6211\u300D\uFF1B\u6BD4\u65B9\u7684\u53D6\u6750\u5728\u6559\u5BA4\u751F\u6D3B\u91CC\uFF0C\u5B66\u751F\u8BFB\u5230\u8FD9\u91CC\u4F1A\u5FC3\u4E00\u7B11\uFF0C\u4E5F\u7ACB\u523B\u660E\u767D\u4E86\u540E\u9762\u7684\u8F6C\u6298\u9488\u5BF9\u4EC0\u4E48\u3002"
          },
          {
            sentence: "\u540E\u9762\u8DDF\u4E0A\u6765\u7684\u8682\u8681\u4ECE\u65C1\u8FB9\u7ED5\u4E86\u8FC7\u53BB\uFF0C\u4E00\u53EA\uFF0C\u4E24\u53EA\uFF0C\u4E09\u53EA\uFF0C\u6CA1\u6709\u8C01\u505C\u4E0B\u6765\u6361\u5B83\u3002",
            why: "\u7528\u300C\u4E00\u53EA\uFF0C\u4E24\u53EA\uFF0C\u4E09\u53EA\u300D\u7684\u6570\u6570\u4EE3\u66FF\u300C\u5F88\u591A\u53EA\u300D\uFF0C\u8BFB\u8005\u8DDF\u7740\u4E00\u8D77\u6570\uFF0C\u5931\u671B\u5C31\u6709\u4E86\u5206\u91CF\uFF1B\u961F\u4F0D\u7684\u4E0D\u6574\u9F50\u6CA1\u6709\u88AB\u5706\u573A\uFF0C\u8FD9\u662F\u5168\u6587\u6700\u8BDA\u5B9E\u7684\u4E00\u7B14\u3002"
          },
          {
            sentence: "\u8DEF\u662F\u5B83\u4EEC\u4E00\u8D9F\u4E00\u8D9F\u8E29\u51FA\u6765\u7684\uFF0C\u90A3\u6761\u9ED1\u5370\u5B50\u5C31\u662F\u5B83\u4EEC\u7684\u529F\u52B3\u7C3F\uFF0C\u8C01\u4E5F\u6CA1\u5728\u4E0A\u9762\u5199\u540D\u5B57\u3002",
            why: "\u628A\u89C2\u5BDF\u7684\u7ED3\u679C\u4E0E\u81EA\u5DF1\u7684\u5904\u5883\u63A5\u4E0A\uFF1A\u529F\u52B3\u7C3F\u4E09\u4E2A\u5B57\u6765\u81EA\u5B66\u751F\u7684\u7ECF\u9A8C\uFF0C\u4E00\u4E2A\u6BD4\u55BB\u540C\u65F6\u8BF4\u6E05\u4E86\u8682\u8681\u7684\u79E9\u5E8F\u4E0E\u503C\u65E5\u7684\u59D4\u5C48\uFF0C\u662F\u5168\u7BC7\u7684\u652F\u70B9\u3002"
          }
        ],
        review: [
          {
            aspect: "\u5BA1\u9898\u7ACB\u610F",
            text: "\u7D27\u6263\u300C\u8E72\u4E86\u5F88\u4E45\u300D\u8FD9\u4E2A\u52A8\u4F5C\uFF0C\u628A\u6587\u7AE0\u7684\u91CD\u91CF\u653E\u5728\u89C2\u5BDF\u7684\u8FC7\u7A0B\u4E0A\uFF1B\u7ACB\u610F\u843D\u5728\u300C\u79E9\u5E8F\u4E0D\u662F\u88AB\u8C01\u6307\u6325\u51FA\u6765\u7684\u300D\uFF0C\u53EA\u8BF4\u5230\u300C\u6BCF\u4E2A\u4EBA\u628A\u81EA\u5DF1\u90A3\u4E00\u6B65\u632A\u5230\u4F4D\u300D\uFF0C\u6CA1\u6709\u5347\u5230\u300C\u56E2\u7ED3\u5C31\u662F\u529B\u91CF\u300D\u7684\u65E7\u7ED3\u8BBA\uFF0C\u7B26\u5408\u81EA\u7136\u611F\u609F\u7C7B\u300C\u611F\u609F\u8981\u5C0F\u8981\u771F\u300D\u7684\u8981\u6C42\u3002"
          },
          {
            aspect: "\u7ED3\u6784\u5E03\u5C40",
            text: "\u5076\u9047\uFF08\u7B49\u8F66\u65F6\u7684\u4E00\u6761\u9ED1\u7EBF\uFF09\u2014\u8E72\u4E0B\uFF08\u89C2\u5BDF\u7684\u7B2C\u4E00\u6B65\uFF09\u2014\u4E24\u5C42\u53D1\u73B0\uFF08\u56FA\u5B9A\u8DEF\u7EBF\u3001\u4E0D\u642C\u4E1C\u897F\u7684\u8682\u8681\uFF09\u2014\u4E00\u5904\u610F\u5916\uFF08\u6389\u5728\u7F1D\u91CC\u7684\u5375\uFF09\u2014\u96E8\u6765\uFF08\u8DEF\u7EBF\u88AB\u51B2\u6389\uFF09\u2014\u7B2C\u4E09\u5929\u6362\u8DEF\uFF08\u6536\u675F\u89C2\u5BDF\uFF09\u2014\u7531\u8682\u8681\u60F3\u5230\u503C\u65E5\uFF08\u8BA4\u8BC6\u843D\u5730\uFF09\u3002\u89C2\u5BDF\u5C42\u5C42\u52A0\u7801\uFF0C\u6700\u540E\u4E00\u6BB5\u7684\u81EA\u6211\u8054\u7CFB\u6709\u524D\u6587\u4E24\u5904\u94FA\u57AB\uFF0C\u4E0D\u7B97\u786C\u8F6C\u3002"
          },
          {
            aspect: "\u8BED\u8A00\u8868\u8FBE",
            text: "\u53D9\u8FF0\u53E3\u543B\u662F\u300C\u6211\u4E00\u8FB9\u770B\u4E00\u8FB9\u60F3\u300D\uFF0C\u8BF4\u9519\u4E86\u53C8\u81EA\u5DF1\u7EA0\u6B63\uFF0C\u8BFB\u8D77\u6765\u6709\u771F\u5B9E\u7684\u547C\u5438\u611F\uFF1B\u767D\u63CF\u4E3A\u4E3B\uFF0C\u6BD4\u55BB\u53EA\u7528\u4E09\u4E2A\uFF08\u767D\u7BB1\u5B50\u3001\u94C5\u7B14\u5212\u8FC7\u3001\u529F\u52B3\u7C3F\uFF09\uFF0C\u90FD\u4E0D\u8D8A\u51FA\u5B66\u751F\u7684\u751F\u6D3B\u8303\u56F4\u3002"
          },
          {
            aspect: "\u7D20\u6750\u8FD0\u7528",
            text: "\u300C\u6BD4\u5B83\u81EA\u5DF1\u7684\u8EAB\u4F53\u8FD8\u5927\u300D\u300C\u4E3E\u5F97\u9AD8\u9AD8\u7684\u300D\u5199\u51FA\u5375\u7684\u4F53\u91CF\uFF0C\u8BFB\u8005\u624D\u4F1A\u5173\u5FC3\u90A3\u7C92\u6389\u4E0B\u53BB\u7684\u5375\uFF1B\u300C\u7B2C\u4E00\u6EF4\u96E8\u7838\u51FA\u4E00\u4E2A\u6DF1\u8272\u7684\u5706\u70B9\u300D\u7528\u96E8\u70B9\u7684\u5927\u5C0F\u4EA4\u4EE3\u96E8\u521A\u8D77\uFF0C\u968F\u540E\u300C\u9ED1\u5370\u5B50\u88AB\u6C34\u51B2\u6CA1\u4E86\u300D\u6B63\u597D\u6536\u4F4F\u89C2\u5BDF\uFF0C\u7D20\u6750\u7684\u8FDB\u51FA\u90FD\u6709\u7406\u7531\u3002"
          },
          {
            aspect: "\u5347\u683C\u5EFA\u8BAE",
            text: "\u6389\u5728\u7F1D\u91CC\u7684\u90A3\u7C92\u5375\u662F\u5168\u7BC7\u6700\u597D\u7684\u60AC\u5FF5\uFF0C\u4F5C\u8005\u5374\u5728\u4E0B\u4E00\u53E5\u5C31\u653E\u6389\u4E86\uFF0C\u53EF\u4EE5\u628A\u5B83\u63A8\u8FDF\u5230\u7ED3\u5C3E\u4E4B\u524D\uFF0C\u8BA9\u5B83\u4E0E\u300C\u6CA1\u4EBA\u770B\u89C1\u6211\u626B\u7684\u90A3\u4E00\u6BB5\u300D\u547C\u5E94\uFF1B\u7B2C\u4E03\u6BB5\u300C\u6211\u5728\u90A3\u513F\u53C8\u8E72\u4E86\u4E00\u4F1A\u513F\uFF0C\u819D\u76D6\u8FD8\u662F\u9178\u7684\u300D\u4E0E\u524D\u6587\u91CD\u590D\uFF0C\u53EF\u6362\u6210\u65B0\u7684\u611F\u5B98\u7EC6\u8282\uFF08\u5899\u6839\u662F\u5E72\u7684\u3001\u8682\u8681\u8D34\u7740\u5F71\u5B50\u8D70\uFF09\uFF1B\u6700\u540E\u4E24\u53E5\u8BAE\u8BBA\u4ECD\u504F\u987A\uFF0C\u82E5\u5220\u5230\u53EA\u5269\u300C\u56DB\u5341\u4E8C\u6B65\u300D\u7684\u4E8B\u5B9E\uFF0C\u529B\u91CF\u53CD\u800C\u66F4\u5927\u3002"
          }
        ],
        comment: "\u8FD9\u7BC7\u7684\u53EF\u8D35\u5904\u662F\u6562\u8BA9\u89C2\u5BDF\u300C\u4E0D\u5B8C\u7F8E\u300D\uFF1A\u6574\u9F50\u7684\u961F\u4F0D\u91CC\u6709\u4E00\u53EA\u8682\u8681\u7ED5\u8FC7\u4E86\u6389\u843D\u7684\u5375\uFF0C\u4F5C\u8005\u65E2\u6CA1\u6709\u66FF\u5B83\u627E\u7406\u7531\uFF0C\u4E5F\u6CA1\u6709\u628A\u8FD9\u4EF6\u4E8B\u5347\u534E\u6210\u300C\u4E2A\u4F53\u4E0E\u96C6\u4F53\u300D\uFF0C\u53EA\u7559\u4E0B\u4E00\u4E2A\u771F\u5B9E\u7684\u7591\u95EE\u3002\u5199\u6CD5\u4E0A\u6700\u503C\u5F97\u5B66\u7684\u662F\u628A\u8BA4\u8BC6\u7684\u8FC7\u7A0B\u5199\u51FA\u6765\uFF1A\u5148\u8BA4\u5B9A\u6709\u6307\u6325\u8005\uFF0C\u518D\u81EA\u5DF1\u63A8\u7FFB\uFF0C\u6700\u540E\u843D\u5728\u503C\u65E5\u7684\u90A3\u56DB\u5341\u4E8C\u6B65\u4E0A\u2014\u2014\u8F6C\u53D8\u6709\u6765\u8DEF\uFF0C\u611F\u609F\u5C31\u4E0D\u7A7A\u3002\u4E09\u4E2A\u6BD4\u55BB\u7684\u53D6\u6750\u5168\u5728\u5B66\u751F\u7684\u751F\u6D3B\u91CC\uFF0C\u5C24\u5176\u662F\u300C\u529F\u52B3\u7C3F\u300D\uFF0C\u4E00\u4E2A\u8BCD\u628A\u8682\u8681\u4E0E\u6211\u62C9\u5230\u4E86\u4E00\u8D77\u3002\u4E0D\u8DB3\u6709\u4E09\uFF1A\u6389\u843D\u7684\u5375\u8FD9\u4E00\u5904\u60AC\u5FF5\u6D6A\u8D39\u5F97\u65E9\uFF0C\u672C\u53EF\u6210\u4E3A\u7ED3\u5C3E\u7684\u7167\u5E94\uFF1B\u7B2C\u4E03\u6BB5\u91CD\u590D\u4E86\u819D\u76D6\u53D1\u9178\uFF0C\u6CA1\u63D0\u4F9B\u65B0\u4FE1\u606F\uFF1B\u7ED3\u5C3E\u4E24\u53E5\u8BAE\u8BBA\u8FC7\u4E8E\u987A\u7406\u6210\u7AE0\uFF0C\u50CF\u603B\u7ED3\u62A5\u544A\uFF0C\u6536\u5728\u4E00\u4E2A\u5177\u4F53\u573A\u9762\u4E0A\u4F1A\u66F4\u597D\u3002"
      }
    ],
    exercise: {
      prompt: "\u4ECE\u4E0A\u9762\u4E24\u7BC7\u91CC\u9009\u4E00\u7BC7\uFF0C\u7167\u7740\u5B83\u7684\u300C\u5148\u770B\u5F88\u4E45\u2014\u518D\u60F3\u660E\u767D\u4E00\u4EF6\u5C0F\u4E8B\u300D\u7684\u8DEF\u5B50\uFF0C\u5199\u4E00\u6B21\u4F60\u81EA\u5DF1\u7684\u81EA\u7136\u89C2\u5BDF\uFF08\u9633\u53F0\u4E0A\u7684\u82B1\u3001\u697C\u4E0B\u7684\u6811\u3001\u7A97\u53F0\u4E0A\u7684\u9E1F\u3001\u96E8\u524D\u7684\u866B\u5B50\u2026\u2026\uFF09\uFF0C\u5199\u4E00\u7BC7 650 \u5B57\u4EE5\u4E0A\u7684\u8BB0\u53D9\u6587\u3002\u611F\u609F\u53EA\u80FD\u5C5E\u4E8E\u4F60\u81EA\u5DF1\uFF0C\u4E0D\u8981\u5199\u300C\u751F\u547D\u7684\u610F\u4E49\u300D\u300C\u5927\u81EA\u7136\u771F\u7F8E\u300D\u3002",
      tips: [
        "\u9009\u5B9A\u4E00\u4E2A\u5177\u4F53\u7684\u89C2\u5BDF\u5BF9\u8C61\uFF0C\u5199\u6E05\u5B83\u7684\u4F4D\u7F6E\u3001\u72B6\u6001\u548C\u4E00\u5904\u5C0F\u6BDB\u75C5\uFF08\u78D5\u6389\u4E00\u5757\u7684\u76C6\u53E3\u3001\u6811\u5E95\u4E0B\u57AB\u7740\u7684\u7EB8\u677F\uFF09\u3002",
        "\u89C2\u5BDF\u5FC5\u987B\u6709\u8FC7\u7A0B\uFF1A\u81F3\u5C11\u5B89\u6392\u4E24\u6B21\u56DE\u8BBF\uFF0C\u628A\u4E2D\u95F4\u90A3\u6BB5\u300C\u4EC0\u4E48\u4E5F\u6CA1\u53D1\u751F\u300D\u4E5F\u5982\u5B9E\u5199\u8FDB\u53BB\u3002",
        "\u611F\u609F\u8981\u5C0F\uFF1A\u5199\u6210\u4E00\u53E5\u4F60\u80FD\u7528\u81EA\u5DF1\u505A\u8BC1\u7684\u8BDD\uFF0C\u4E0D\u66FF\u5168\u4EBA\u7C7B\u53D1\u8A00\uFF0C\u4E5F\u4E0D\u7528\u300C\u8FD9\u5C31\u662F\u751F\u547D\u300D\u6536\u5C3E\u3002",
        "\u7ED3\u5C3E\u6536\u5728\u4E00\u4E2A\u5177\u4F53\u573A\u9762\u4E0A\uFF08\u5F00\u51FA\u7684\u51E0\u6735\u82B1\u3001\u8D70\u5B8C\u7684\u6700\u540E\u4E00\u6B65\uFF09\uFF0C\u4E0D\u8981\u8D34\u6807\u7B7E\uFF0C\u4E0D\u8981\u53CD\u95EE\u8BFB\u8005\u3002"
      ]
    }
  },
  {
    id: "w-sample-pingfan-2",
    grade: "all",
    category: "\u8303\u6587\u70B9\u8BC4",
    theme: "\u5E73\u51E1\u82F1\u96C4",
    title: "\u8303\u6587\u70B9\u8BC4\uFF1A\u5E73\u51E1\u82F1\u96C4 \xB7 \u540C\u9898\u4E24\u7BC7\u300A\u83DC\u573A\u5C3D\u5934\u7684\u83B2\u59E8\u300B\u300A\u69D0\u6811\u4E0B\u7684\u4FEE\u978B\u644A\u300B",
    summary: "\u83DC\u573A\u91CC\u7684\u83B2\u59E8\u4E0E\u69D0\u6811\u4E0B\u7684\u4FEE\u978B\u5320\u8001\u5468\uFF0C\u4E24\u7BC7\u7ACB\u610F\u4E0D\u540C\u7684\u4EBA\u7269\u8303\u6587\uFF0C\u6559\u4F60\u4E0D\u5199\u300C\u4F1F\u5927\u300D\uFF0C\u53EA\u5199\u4E13\u4E1A\u4E0E\u4F53\u9762\uFF1A\u624B\u827A\u7684\u53EF\u9760\u3001\u5BF9\u4EBA\u7684\u5206\u5BF8\u3001\u5341\u5E74\u4E0D\u53D8\u7684\u51C6\u65F6\u3002",
    content: [
      "## \u9898\u76EE",
      "\u5E73\u51E1\u82F1\u96C4\u7C7B\u9898\u76EE\u5E38\u6709\u4E24\u8DEF\uFF1A\u4E00\u8DEF\u7ED9\u6750\u6599\uFF08\u300C\u6211\u4EEC\u8EAB\u8FB9\u6709\u8BB8\u591A\u666E\u901A\u52B3\u52A8\u8005\uFF0C\u4ED6\u4EEC\u7684\u5DE5\u4F5C\u770B\u8D77\u6765\u5E73\u5E38\uFF0C\u5374\u8BA9\u4E00\u5EA7\u57CE\u5E02\u8FD0\u8F6C\u8D77\u6765\u300D\uFF09\uFF0C\u8981\u6C42\u81EA\u62DF\u9898\u76EE\u5199\u8BB0\u53D9\u6587\uFF1B\u4E00\u8DEF\u662F\u534A\u547D\u9898\uFF08\u300A\u6211\u8EAB\u8FB9\u7684\u2026\u2026\u300B\u300A\u4E00\u4E2A\u2026\u2026\u7684\u4EBA\u300B\uFF09\u3002\u4E24\u7BC7\u8303\u6587\u90FD\u9009\u300C\u6709\u56FA\u5B9A\u4F4D\u7F6E\u7684\u4EBA\u300D\uFF1A\u83DC\u573A\u7B2C\u56DB\u6392\u6700\u91CC\u9762\u7684\u644A\u4E3B\u83B2\u59E8\u3001\u5C0F\u533A\u5357\u95E8\u69D0\u6811\u4E0B\u7684\u4FEE\u978B\u5320\u8001\u5468\u3002",
      "\u8FD9\u7C7B\u9898\u6700\u5BB9\u6613\u5199\u574F\u6210\u9881\u5956\u8BCD\uFF1A\u4E00\u4E0A\u6765\u5C31\u300C\u5E73\u51E1\u800C\u4F1F\u5927\u300D\u300C\u9ED8\u9ED8\u5949\u732E\u300D\uFF0C\u4EBA\u7269\u53CD\u5012\u4E0D\u89C1\u4E86\u3002\u8303\u6587\u7684\u529E\u6CD5\u662F\u628A\u300C\u82F1\u96C4\u300D\u4E24\u4E2A\u5B57\u653E\u4E0B\uFF0C\u53EA\u5199\u4ED6\u6BCF\u5929\u600E\u4E48\u5E72\u6D3B\u3001\u600E\u4E48\u8BF4\u8BDD\u3001\u600E\u4E48\u7B97\u8D26\u2014\u2014\u656C\u91CD\u611F\u4ECE\u7EC6\u8282\u91CC\u51FA\u6765\uFF0C\u4E0D\u4ECE\u5F62\u5BB9\u8BCD\u91CC\u51FA\u6765\u3002",
      "## \u7ACB\u610F",
      "\u7B2C\u4E00\u7BC7\u7684\u7ACB\u610F\u662F\u300C\u4E00\u89C6\u540C\u4EC1\u7684\u51C6\u300D\uFF1A\u83B2\u59E8\u7684\u597D\u4E0D\u662F\u5BF9\u67D0\u4E2A\u5B69\u5B50\u7279\u522B\u7167\u987E\uFF0C\u800C\u662F\u7ED9\u6BCF\u4E2A\u4EBA\u4E00\u6837\u7684\u79E4\u3001\u4E00\u6837\u7684\u6311\u6CD5\u3001\u4E00\u6837\u7684\u627E\u96F6\u987A\u5E8F\uFF1B\u8BA9\u4E00\u6761\u8857\u5B89\u5FC3\u7684\u662F\u8FD9\u4EFD\u5341\u5E74\u4E0D\u53D8\u7684\u51C6\uFF0C\u4E0D\u662F\u70ED\u60C5\u3002",
      "\u7B2C\u4E8C\u7BC7\u7684\u7ACB\u610F\u662F\u300C\u4E0D\u80AF\u5C06\u5C31\u300D\uFF1A\u8001\u5468\u5B81\u53EF\u5C11\u6536\u4E00\u6B21\u94B1\uFF0C\u4E5F\u4E0D\u80AF\u628A\u4E00\u53EA\u78E8\u504F\u7684\u978B\u8DDF\u968F\u968F\u4FBF\u4FBF\u6362\u6389\uFF1B\u4ED6\u4E00\u53E5\u300C\u5148\u7A7F\u4E09\u5929\uFF0C\u4E0D\u5BF9\u518D\u6765\u300D\uFF0C\u662F\u628A\u9A8C\u6536\u7684\u6743\u5229\u4EA4\u8FD8\u7ED9\u7A7F\u978B\u7684\u4EBA\u3002",
      "\u4E24\u4E2A\u7ACB\u610F\u90FD\u7ED5\u5F00\u4E86\u300C\u4ED6\u4EEC\u5F88\u8F9B\u82E6\u300D\u300C\u4ED6\u4EEC\u5F88\u4E86\u4E0D\u8D77\u300D\u3002\u5199\u666E\u901A\u4EBA\u7684\u656C\u91CD\u611F\uFF0C\u6700\u7A33\u7684\u4E00\u6761\u8DEF\u662F\u5199\u4E13\u4E1A\uFF1A\u624B\u827A\u4EBA\u9760\u624B\u827A\u7ACB\u8EAB\uFF0C\u53EF\u9760\u5C31\u662F\u4ED6\u7684\u4F53\u9762\u3002\u628A\u300C\u4F1F\u5927\u300D\u6362\u6210\u300C\u51C6\u300D\u4E0E\u300C\u4E0D\u5C06\u5C31\u300D\uFF0C\u6587\u7AE0\u7ACB\u523B\u843D\u5730\uFF0C\u4EBA\u7269\u4E5F\u7ACB\u523B\u50CF\u4EBA\u3002",
      "## \u7ED3\u6784",
      "\u7B2C\u4E00\u7BC7\uFF1A\u4F4D\u7F6E\u4E0E\u73AF\u5883\uFF08\u83DC\u573A\u7B2C\u56DB\u6392\u3001\u6C34\u78E8\u77F3\u6848\u5B50\u3001\u4E09\u6837\u5BB6\u5F53\uFF09\u2014\u89C4\u77E9\uFF08\u4E0D\u558A\u644A\u3001\u628A\u597D\u83DC\u7FFB\u5230\u4E0A\u9762\u3001\u79E4\u9762\u8F6C\u5411\u987E\u5BA2\u3001\u627E\u96F6\u5148\u628A\u96F6\u94B1\u6446\u51FA\u6765\uFF09\u2014\u4E00\u6B21\u4E92\u52A8\uFF08\u8C46\u89D2\u7092\u8FD8\u662F\u7116\uFF09\u2014\u4E00\u4E2A\u5177\u4F53\u4E8B\u4EF6\uFF08\u591A\u6536\u4E00\u5757\u94B1\uFF0C\u7B2C\u4E8C\u5929\u4E3B\u52A8\u8FD8\uFF09\u2014\u8BA4\u8BC6\u8F6C\u53D8\uFF08\u4ECE\u300C\u5BF9\u6211\u597D\u300D\u5230\u300C\u5BF9\u6240\u6709\u4EBA\u90FD\u4E00\u6837\u300D\uFF09\u2014\u6536\u5728\u6848\u5B50\u4E0A\u3002",
      "\u7B2C\u4E8C\u7BC7\uFF1A\u5BB6\u5F53\u4E0E\u5916\u8C8C\uFF08\u624B\u6447\u8865\u978B\u673A\u3001\u7F20\u7740\u767D\u80F6\u5E03\u7684\u773C\u955C\u817F\uFF09\u2014\u4E00\u6B21\u4FEE\u978B\uFF08\u5148\u5BF9\u9F50\u4E24\u53EA\u978B\u8DDF\uFF0C\u6307\u51FA\u53F3\u811A\u78E8\u504F\uFF09\u2014\u624B\u4E0A\u7684\u52A8\u4F5C\uFF08\u524A\u6BDB\u8FB9\u3001\u6BD4\u4E09\u6B21\u624D\u526A\u3001\u4E0A\u80F6\u540E\u7B49\u4E03\u516B\u5206\u949F\uFF09\u2014\u7B2C\u4E8C\u6B21\u4E0A\u95E8\uFF08\u6572\u8584\u978B\u638C\u8FB9\uFF0C\u4E00\u5206\u6CA1\u591A\u6536\uFF09\u2014\u80CC\u666F\u8865\u5145\uFF08\u76AE\u978B\u5382\u505A\u8FC7\u5341\u51E0\u5E74\u6837\u978B\uFF09\u2014\u8BA4\u8BC6\u8F6C\u53D8\uFF08\u8865\u5F97\u7262\u662F\u672C\u4E8B\uFF0C\u4E0D\u80AF\u5C06\u5C31\u624D\u662F\u89C4\u77E9\uFF09\u3002",
      "\u4E24\u7BC7\u7684\u7ED3\u6784\u90FD\u9760\u4E00\u6B21\u5177\u4F53\u7684\u4EA4\u6613\u6491\u8D77\u6765\uFF1A\u4E0D\u662F\u7AD9\u5728\u8FDC\u5904\u8D5E\u7F8E\uFF0C\u800C\u662F\u8D70\u8FDB\u53BB\u4E70\u4E00\u6B21\u83DC\u3001\u4FEE\u4E00\u6B21\u978B\u3002\u4EBA\u7269\u5728\u4EA4\u6613\u91CC\u9732\u51FA\u771F\u6837\u5B50\u2014\u2014\u95EE\u4E00\u53E5\u300C\u7092\u8FD8\u662F\u7116\u300D\u3001\u8BF4\u4E00\u53E5\u300C\u8D70\u4E24\u6B65\u6211\u770B\u770B\u300D\uFF0C\u6BD4\u4E00\u6574\u6BB5\u8BC4\u4EF7\u6709\u7528\u5F97\u591A\u3002",
      "## \u4EAE\u70B9",
      "\u7B2C\u4E00\u7BC7\u6709\u56DB\u5904\u53EF\u4EE5\u76F4\u63A5\u80CC\u4E0B\u6765\uFF1A\u4E0D\u558A\u644A\u800C\u7FFB\u83DC\u7684\u4E24\u4E2A\u52A8\u4F5C\uFF1B\u300C\u7092\u5C31\u6311\u7EC6\u7684\uFF0C\u7116\u5C31\u6311\u7C97\u7684\u300D\uFF1B\u79E4\u9762\u6C38\u8FDC\u8F6C\u5411\u987E\u5BA2\u7684\u89C4\u77E9\uFF1B\u300C\u4EBA\u5BB6\u4E5F\u8981\u8D70\u8DEF\u300D\u56DB\u4E2A\u5B57\u7684\u56DE\u7B54\u3002\u6700\u8981\u7D27\u7684\u4E00\u7B14\u662F\u8FD8\u94B1\u90A3\u6BB5\uFF0C\u4F5C\u8005\u5199\u5979\u300C\u8BF4\u5B8C\u5C31\u4F4E\u5934\u7ED9\u53E6\u4E00\u4E2A\u987E\u5BA2\u6311\u756A\u8304\u300D\uFF0C\u628A\u5979\u4E0D\u505A\u81EA\u6211\u8868\u626C\u7684\u5206\u5BF8\u5199\u51FA\u6765\u4E86\u3002",
      "\u7B2C\u4E8C\u7BC7\u6700\u597D\u7684\u7EC6\u8282\u662F\u300C\u628A\u4E24\u53EA\u978B\u8DDF\u5E76\u5728\u4E00\u8D77\u5BF9\u9F50\uFF0C\u772F\u7740\u773C\u770B\u4E86\u4E00\u4F1A\u513F\u300D\u2014\u2014\u4E13\u4E1A\u7684\u7B2C\u4E00\u52A8\u4F5C\u662F\u770B\uFF0C\u4E0D\u662F\u62A5\u4EF7\uFF1B\u300C\u8FD9\u4E00\u7B49\u5C31\u662F\u4E03\u516B\u5206\u949F\u300D\u5199\u51FA\u4E86\u624B\u827A\u4EBA\u7684\u65F6\u95F4\u89C2\uFF0C\u4E0E\u6025\u7740\u8D70\u7684\u300C\u6211\u300D\u6070\u597D\u5BF9\u7167\uFF1B\u7ED3\u5C3E\u300C\u8D70\u4E24\u6B65\u6211\u770B\u770B\u300D\u516D\u4E2A\u5B57\uFF0C\u628A\u9A8C\u6536\u6743\u4EA4\u8FD8\u987E\u5BA2\uFF0C\u6BD4\u4EFB\u4F55\u8BC4\u8BED\u90FD\u4F53\u9762\u3002",
      "\u4E24\u7BC7\u7684\u5171\u540C\u70B9\u662F\u4E0D\u7ED9\u4EBA\u7269\u6234\u5149\u73AF\uFF1A\u83B2\u59E8\u6CA1\u6709\u4E00\u53E5\u611F\u6168\uFF0C\u8001\u5468\u6CA1\u6709\u4E00\u53E5\u4EBA\u751F\u9053\u7406\uFF0C\u5168\u7BC7\u7684\u9053\u7406\u90FD\u7531\u300C\u6211\u300D\u6765\u8BF4\uFF0C\u800C\u4E14\u8BF4\u5F97\u6709\u4FDD\u7559\u3002\u5199\u666E\u901A\u4EBA\u7684\u6587\u7AE0\u8D8A\u514B\u5236\uFF0C\u8BFB\u8005\u8D8A\u4FE1\u3002",
      "## \u53EF\u6539\u8FDB",
      "\u7B2C\u4E00\u7BC7\u7684\u8F6C\u6298\u53E5\u300C\u6211\u4EE5\u524D\u89C9\u5F97\u2026\u2026\u6162\u6162\u5730\u6211\u53D1\u73B0\u300D\u504F\u8BF4\u660E\u6027\uFF0C\u53EF\u4EE5\u76F4\u63A5\u7528\u4E00\u6B21\u4EB2\u773C\u6240\u89C1\u4EE3\u66FF\uFF0C\u4F8B\u5982\u5979\u7ED9\u90A3\u4F4D\u8033\u6735\u4E0D\u592A\u597D\u7684\u963F\u5A46\u91CD\u590D\u7B2C\u4E09\u904D\u65F6\u624B\u653E\u5728\u54EA\u513F\uFF1B\u300C\u597D\u50CF\u90A3\u4E00\u5757\u94B1\u6BD4\u5979\u5341\u5E74\u91CC\u7684\u4EFB\u4F55\u4E00\u5929\u90FD\u4E0D\u503C\u5F97\u591A\u8BB2\u300D\u7528\u529B\u7A0D\u8FC7\uFF0C\u53E5\u5F0F\u4E5F\u522B\u626D\uFF0C\u6539\u6210\u300C\u597D\u50CF\u90A3\u4E00\u5757\u94B1\u4E0D\u503C\u5F97\u591A\u8BB2\u300D\u66F4\u5E72\u51C0\u3002",
      "\u7B2C\u4E8C\u7BC7\u300C\u6211\u540E\u6765\u4ECE\u6211\u5988\u90A3\u513F\u77E5\u9053\u300D\u8865\u51FA\u76AE\u978B\u5382\u7684\u80CC\u666F\uFF0C\u6765\u5F97\u6709\u70B9\u7A81\u7136\uFF0C\u53EF\u4EE5\u5728\u524D\u6587\u57CB\u4E00\u53E5\uFF08\u4F8B\u5982\u5DE5\u5177\u7BB1\u4FA7\u9762\u8D34\u7740\u4E00\u5F20\u65E7\u5382\u91CC\u7684\u6807\u7B7E\uFF09\uFF1B\u300C\u53EF\u6BCF\u5929\u8D70\u8DEF\u7684\u4EBA\u662F\u6211\u300D\u7565\u6709\u81EA\u6211\u5F3A\u8C03\uFF0C\u5220\u6389\u4E4B\u540E\u66F4\u6C89\u7A33\u3002",
      "\u4E24\u7BC7\u6709\u4E00\u4E2A\u5171\u540C\u7684\u5C0F\u6BDB\u75C5\uFF1A\u8BA4\u8BC6\u8F6C\u53D8\u7684\u53E5\u5B50\u90FD\u6324\u5728\u6700\u540E\u4E24\u6BB5\u91CC\uFF0C\u8BFB\u8D77\u6765\u50CF\u7A81\u7136\u603B\u7ED3\u3002\u53EF\u4EE5\u8BA9\u8F6C\u53D8\u5206\u4E24\u6B21\u5B8C\u6210\uFF0C\u4E00\u6B21\u5728\u4E8B\u4E2D\uFF08\u6BD4\u5982\u5F53\u573A\u6539\u4E86\u4E70\u83DC\u7684\u8BF4\u6CD5\uFF09\uFF0C\u4E00\u6B21\u5728\u4E8B\u540E\uFF0C\u6587\u7AE0\u5C31\u6709\u5C42\u6B21\u4E86\u3002"
    ],
    examples: [
      {
        title: "\u8303\u6587\u4E00\uFF1A\u83DC\u573A\u5C3D\u5934\u7684\u83B2\u59E8",
        prompt: "\u9898\u76EE\uFF1A\u300A\u6211\u5E38\u5E38\u8DEF\u8FC7\u7684\u5730\u65B9\u300B\u3002\u8981\u6C42\uFF1A\u5199\u4E00\u4F4D\u4F60\u5E38\u5E38\u9047\u89C1\u7684\u666E\u901A\u4EBA\uFF0C\u5199\u51FA\u4ED6/\u5979\u7684\u65E5\u5E38\u4E0E\u4E13\u4E1A\uFF0C\u4E0D\u5C11\u4E8E 600 \u5B57\uFF1B\u4E0D\u8981\u5199\u6210\u9881\u5956\u8BCD\u5F0F\u7684\u8D5E\u7F8E\u3002",
        score: "\u4E00\u7C7B\u6587\u4E0A\uFF0855\u201460 \u5206\uFF09",
        text: "\u4ECE\u6211\u5BB6\u51FA\u95E8\u5F80\u897F\u8D70\u4E03\u5206\u949F\uFF0C\u662F\u57CE\u897F\u83DC\u5E02\u573A\u3002\u83DC\u573A\u6709\u4E09\u4E2A\u95E8\uFF0C\u6211\u4E60\u60EF\u8D70\u5357\u95E8\uFF0C\u8FDB\u95E8\u7B2C\u56DB\u6392\u6700\u9760\u91CC\u90A3\u4E2A\u644A\u5B50\u662F\u83B2\u59E8\u7684\u3002\u5979\u7684\u644A\u4F4D\u53EA\u6709\u4E00\u5F20\u6848\u5B50\u5BBD\uFF0C\u6848\u5B50\u662F\u6C34\u78E8\u77F3\u7684\uFF0C\u8FB9\u89D2\u88AB\u78E8\u5F97\u53D1\u4EAE\uFF0C\u4E0A\u5934\u6C38\u8FDC\u6446\u7740\u4E09\u6837\u4E1C\u897F\uFF1A\u4E00\u53F0\u7535\u5B50\u79E4\uFF0C\u4E00\u4E2A\u88C5\u96F6\u94B1\u7684\u94C1\u76AE\u997C\u5E72\u76D2\uFF0C\u4E00\u628A\u526A\u83DC\u6839\u7528\u7684\u65E7\u526A\u5200\u3002\n\u6211\u5988\u4E70\u5979\u7684\u83DC\u4E70\u4E86\u5341\u5E74\u3002\u6211\u5C0F\u65F6\u5019\u8DDF\u7740\u6765\uFF0C\u53EA\u8BB0\u5F97\u5979\u4E0D\u600E\u4E48\u8BF4\u8BDD\u3002\u522B\u7684\u644A\u4E3B\u4F1A\u558A\uFF1A\u300C\u9753\u4ED4\uFF0C\u4E70\u70B9\u8C46\u89D2\u5566\uFF0C\u4ECA\u5929\u521A\u5230\u7684\uFF01\u300D\u5979\u4E0D\u558A\u3002\u5979\u53EA\u662F\u628A\u7B50\u91CC\u7684\u83DC\u7FFB\u4E00\u7FFB\uFF0C\u628A\u597D\u770B\u7684\u6311\u5230\u4E0A\u9762\uFF0C\u574F\u7684\u62E3\u51FA\u6765\u6254\u8FDB\u8EAB\u540E\u7684\u6876\u91CC\u3002\n\u4E0A\u521D\u4E2D\u4EE5\u540E\uFF0C\u6211\u5E38\u5E38\u88AB\u6D3E\u6765\u4E70\u83DC\u3002\u7B2C\u4E00\u6B21\u81EA\u5DF1\u53BB\uFF0C\u6211\u8BF4\u8981\u4E00\u65A4\u8C46\u89D2\u3002\u5979\u6CA1\u76F4\u63A5\u79F0\uFF0C\u5148\u95EE\uFF1A\u300C\u7092\u8FD8\u662F\u7116\uFF1F\u300D\u6211\u8BF4\u4E0D\u77E5\u9053\uFF0C\u6211\u5988\u6CA1\u8BF4\u3002\u5979\u8BF4\uFF1A\u300C\u7092\u5C31\u6311\u7EC6\u7684\uFF0C\u7116\u5C31\u6311\u7C97\u7684\u3002\u300D\u7136\u540E\u4E24\u6839\u624B\u6307\u628A\u8C46\u89D2\u62E8\u5F00\uFF0C\u6311\u4E86\u4E00\u628A\u7EC6\u7684\uFF0C\u4E0A\u79E4\u2014\u2014\u4E00\u65A4\u96F6\u4E8C\u4E24\u3002\u5979\u8BF4\uFF1A\u300C\u4E8C\u4E24\u9001\u4F60\u7684\u3002\u300D\u6211\u8BF4\u4E0D\u7528\uFF0C\u5979\u4E5F\u4E0D\u89E3\u91CA\uFF0C\u628A\u888B\u53E3\u62E7\u4E86\u4E24\u4E0B\uFF0C\u9012\u8FC7\u6765\u3002\n\u540E\u6765\u6211\u6478\u51FA\u5979\u7684\u89C4\u77E9\u3002\u5979\u79F0\u4E1C\u897F\uFF0C\u6C38\u8FDC\u628A\u79E4\u9762\u8F6C\u8FC7\u6765\u671D\u7740\u4F60\uFF0C\u6570\u5B57\u8BA9\u4F60\u770B\u89C1\uFF1B\u4ECE\u6765\u4E0D\u7F3A\u65A4\u5C11\u4E24\uFF0C\u4F46\u4E5F\u4ECE\u6765\u4E0D\u51D1\u6574\u3002\u627E\u94B1\u7684\u65F6\u5019\uFF0C\u5979\u5148\u628A\u96F6\u94B1\u6570\u51FA\u6765\u653E\u5728\u6848\u5B50\u4E0A\uFF0C\u518D\u6536\u4F60\u7684\u6574\u94B1\u3002\u6709\u4E00\u6B21\u4E0B\u5927\u96E8\uFF0C\u83DC\u573A\u91CC\u8FDB\u4E86\u6C34\uFF0C\u5404\u5BB6\u90FD\u5F80\u5916\u632A\uFF0C\u628A\u83DC\u6446\u5230\u8FC7\u9053\u4E0A\u3002\u5979\u628A\u644A\u5B50\u5F80\u91CC\u6536\u4E86\u534A\u6B65\uFF0C\u5B81\u53EF\u5C11\u6446\u4E00\u7B50\u83DC\uFF0C\u4E5F\u6CA1\u5360\u90A3\u6761\u8FC7\u9053\u3002\u6211\u5988\u8BF4\uFF1A\u300C\u4F60\u8FD9\u6837\u5356\u5F97\u5C11\u554A\u3002\u300D\u5979\u8BF4\uFF1A\u300C\u4EBA\u5BB6\u4E5F\u8981\u8D70\u8DEF\u3002\u300D\n\u6709\u4E00\u56DE\u5979\u7B97\u9519\u4E86\u94B1\uFF0C\u591A\u6536\u4E86\u6211\u4E00\u5757\u3002\u6211\u5F53\u65F6\u5DF2\u7ECF\u8D70\u4E86\uFF0C\u4E5F\u6CA1\u60F3\u56DE\u53BB\u3002\u7B2C\u4E8C\u5929\u6211\u53BB\u4E70\u8471\uFF0C\u5979\u5148\u628A\u4E00\u5757\u94B1\u62CD\u5728\u6848\u5B50\u4E0A\uFF0C\u8BF4\uFF1A\u300C\u6628\u5929\u8C46\u89D2\u7B97\u9519\u3002\u300D\u6211\u95EE\u5979\u600E\u4E48\u77E5\u9053\u7684\u3002\u5979\u8BF4\u665A\u4E0A\u6536\u644A\u6570\u94B1\uFF0C\u8D26\u5BF9\u4E0D\u4E0A\uFF0C\u7FFB\u4E86\u4E00\u4E0B\u888B\u5B50\u4E0A\u7684\u4EF7\u7B7E\u5C31\u7B97\u51FA\u6765\u4E86\u3002\u5979\u8BF4\u5B8C\u5C31\u4F4E\u5934\u7ED9\u53E6\u4E00\u4E2A\u987E\u5BA2\u6311\u756A\u8304\uFF0C\u597D\u50CF\u90A3\u4E00\u5757\u94B1\u6BD4\u5979\u5341\u5E74\u91CC\u7684\u4EFB\u4F55\u4E00\u5929\u90FD\u4E0D\u503C\u5F97\u591A\u8BB2\u3002\n\u6211\u4EE5\u524D\u89C9\u5F97\uFF0C\u4E00\u4E2A\u4EBA\u5BF9\u4F60\u597D\uFF0C\u662F\u56E0\u4E3A\u5979\u8BA4\u8BC6\u4F60\u3001\u559C\u6B22\u4F60\u3002\u6162\u6162\u5730\u6211\u53D1\u73B0\uFF0C\u83B2\u59E8\u7684\u597D\u4E0D\u662F\u7ED9\u6211\u4E00\u4E2A\u4EBA\u7684\u3002\u5979\u7ED9\u6765\u4E70\u83DC\u7684\u6BCF\u4E2A\u4EBA\u4E00\u6837\u7684\u79E4\u3001\u4E00\u6837\u7684\u6311\u6CD5\u3001\u4E00\u6837\u7684\u627E\u96F6\u987A\u5E8F\uFF0C\u8FDE\u5BF9\u90A3\u4F4D\u8033\u6735\u4E0D\u592A\u597D\u3001\u6BCF\u56DE\u90FD\u8981\u5927\u58F0\u91CD\u590D\u4E09\u904D\u7684\u963F\u5A46\u4E5F\u4E00\u6837\u3002\u5979\u505A\u7684\u8FD9\u4EF6\u4E8B\u4E0D\u96BE\uFF0C\u96BE\u7684\u662F\u8FD9\u5341\u5E74\u91CC\u6BCF\u4E00\u4E2A\u4E0A\u5348\u90FD\u8FD9\u4E48\u505A\u3002\n\u83DC\u573A\u91CC\u4E00\u5E74\u8981\u6362\u597D\u51E0\u5BB6\u644A\u4E3B\uFF0C\u5356\u6C34\u4EA7\u7684\u6362\u8FC7\u4E09\u56DE\uFF0C\u5356\u5364\u5473\u7684\u6362\u8FC7\u4E24\u56DE\u3002\u83B2\u59E8\u7684\u644A\u5B50\u8FD8\u5728\u7B2C\u56DB\u6392\u6700\u91CC\u9762\uFF0C\u6848\u5B50\u8FD8\u662F\u90A3\u5F20\u6C34\u78E8\u77F3\u7684\uFF0C\u526A\u5200\u8FD8\u662F\u90A3\u628A\u65E7\u7684\u3002\u6211\u6709\u65F6\u4F1A\u60F3\uFF0C\u8FD9\u6761\u8857\u4E3A\u4EC0\u4E48\u8BA9\u4EBA\u5B89\u5FC3\uFF1A\u4E0D\u662F\u56E0\u4E3A\u8C01\u505A\u4E86\u4EC0\u4E48\u5927\u4E8B\uFF0C\u662F\u56E0\u4E3A\u6709\u51E0\u4E2A\u4EBA\uFF0C\u6BCF\u5929\u90FD\u5728\u540C\u4E00\u4E2A\u4F4D\u7F6E\u4E0A\uFF0C\u628A\u540C\u4E00\u4EF6\u5C0F\u4E8B\u505A\u5F97\u8DDF\u6628\u5929\u4E00\u6837\u51C6\u3002",
        highlights: [
          {
            sentence: "\u5979\u4E0D\u558A\u3002\u5979\u53EA\u662F\u628A\u7B50\u91CC\u7684\u83DC\u7FFB\u4E00\u7FFB\uFF0C\u628A\u597D\u770B\u7684\u6311\u5230\u4E0A\u9762\uFF0C\u574F\u7684\u62E3\u51FA\u6765\u6254\u8FDB\u8EAB\u540E\u7684\u6876\u91CC\u3002",
            why: "\u5148\u7528\u4E00\u4E2A\u77ED\u53E5\u5426\u5B9A\u5E02\u573A\u4E0A\u6700\u5E38\u89C1\u7684\u63FD\u5BA2\u65B9\u5F0F\uFF08\u558A\uFF09\uFF0C\u518D\u7ED9\u51FA\u5979\u7528\u52A8\u4F5C\u4EE3\u66FF\u5406\u559D\u7684\u4E24\u4E2A\u7EC6\u8282\uFF1B\u4EBA\u7269\u4E00\u53E5\u8BDD\u4E0D\u8BF4\uFF0C\u4E13\u4E1A\u5374\u5DF2\u7ECF\u9732\u51FA\u6765\u4E86\u3002"
          },
          {
            sentence: "\u5979\u8BF4\uFF1A\u300C\u7092\u5C31\u6311\u7EC6\u7684\uFF0C\u7116\u5C31\u6311\u7C97\u7684\u3002\u300D",
            why: "\u4E00\u53E5\u5341\u56DB\u4E2A\u5B57\u7684\u5BF9\u8BDD\uFF0C\u62B5\u5F97\u4E0A\u4E00\u6BB5\u300C\u5979\u5F88\u61C2\u83DC\u300D\u7684\u8BF4\u660E\uFF1A\u5979\u95EE\u9700\u6C42\u3001\u7ED9\u65B9\u6848\uFF0C\u662F\u4E00\u4F4D\u61C2\u884C\u7684\u644A\u4E3B\u5728\u505A\u4E13\u4E1A\u5224\u65AD\uFF0C\u800C\u4E0D\u662F\u4E00\u4E2A\u70ED\u5FC3\u7684\u5927\u4EBA\u3002"
          },
          {
            sentence: "\u5979\u79F0\u4E1C\u897F\uFF0C\u6C38\u8FDC\u628A\u79E4\u9762\u8F6C\u8FC7\u6765\u671D\u7740\u4F60\uFF0C\u6570\u5B57\u8BA9\u4F60\u770B\u89C1\uFF1B\u4ECE\u6765\u4E0D\u7F3A\u65A4\u5C11\u4E24\uFF0C\u4F46\u4E5F\u4ECE\u6765\u4E0D\u51D1\u6574\u3002",
            why: "\u4E09\u53E5\u5206\u53F7\u5E76\u5217\uFF0C\u5199\u51FA\u4E00\u6761\u6210\u6587\u7684\u89C4\u77E9\uFF1A\u628A\u79E4\u7ED9\u4F60\u770B\u662F\u5766\u8361\uFF0C\u4E0D\u51D1\u6574\u662F\u4E0D\u8BA8\u597D\u3002\u8FD9\u6B63\u662F\u300C\u4E13\u4E1A\u4E0E\u4F53\u9762\u300D\u6700\u5177\u4F53\u7684\u5199\u6CD5\uFF0C\u6BD4\u300C\u5979\u5F88\u8BDA\u5B9E\u300D\u6709\u529B\u5F97\u591A\u3002"
          },
          {
            sentence: "\u5979\u8BF4\uFF1A\u300C\u4EBA\u5BB6\u4E5F\u8981\u8D70\u8DEF\u3002\u300D",
            why: "\u4E0B\u5927\u96E8\u5B81\u53EF\u5C11\u6446\u4E00\u7B50\u83DC\u4E5F\u4E0D\u5360\u8FC7\u9053\uFF0C\u56DE\u7B54\u53EA\u6709\u4E94\u4E2A\u5B57\uFF0C\u6CA1\u6709\u4EFB\u4F55\u81EA\u6211\u8868\u626C\uFF1B\u4EBA\u7269\u7684\u5206\u5BF8\u611F\u5168\u5728\u8FD9\u4E94\u4E2A\u5B57\u91CC\uFF0C\u8BFB\u8005\u5BF9\u5979\u7684\u656C\u91CD\u7531\u6B64\u800C\u751F\u3002"
          },
          {
            sentence: "\u6211\u6709\u65F6\u4F1A\u60F3\uFF0C\u8FD9\u6761\u8857\u4E3A\u4EC0\u4E48\u8BA9\u4EBA\u5B89\u5FC3\uFF1A\u4E0D\u662F\u56E0\u4E3A\u8C01\u505A\u4E86\u4EC0\u4E48\u5927\u4E8B\uFF0C\u662F\u56E0\u4E3A\u6709\u51E0\u4E2A\u4EBA\uFF0C\u6BCF\u5929\u90FD\u5728\u540C\u4E00\u4E2A\u4F4D\u7F6E\u4E0A\uFF0C\u628A\u540C\u4E00\u4EF6\u5C0F\u4E8B\u505A\u5F97\u8DDF\u6628\u5929\u4E00\u6837\u51C6\u3002",
            why: "\u7ED3\u5C3E\u628A\u300C\u5E73\u51E1\u82F1\u96C4\u300D\u7684\u9898\u773C\u843D\u5728\u4E00\u4E2A\u300C\u51C6\u300D\u5B57\u4E0A\uFF0C\u7ED5\u5F00\u4E86\u300C\u5949\u732E\u300D\u7684\u65E7\u8DEF\uFF1B\u53E5\u5F0F\u4E5F\u514B\u5236\u6210\u300C\u6211\u6709\u65F6\u4F1A\u60F3\u300D\uFF0C\u4E0D\u4E0B\u7ED3\u8BBA\uFF0C\u50CF\u662F\u521A\u521A\u60F3\u660E\u767D\u3002"
          }
        ],
        review: [
          {
            aspect: "\u5BA1\u9898\u7ACB\u610F",
            text: "\u5199\u4E00\u4F4D\u5E38\u89C1\u9762\u7684\u666E\u901A\u4EBA\uFF0C\u5168\u7BC7\u4E0D\u51FA\u73B0\u300C\u5E73\u51E1\u300D\u300C\u4F1F\u5927\u300D\u300C\u5949\u732E\u300D\u4EFB\u4F55\u4E00\u4E2A\u8BCD\uFF0C\u628A\u4EBA\u7269\u4EF7\u503C\u5EFA\u7ACB\u5728\u300C\u4E13\u4E1A\u300D\u4E0A\uFF1A\u79E4\u9762\u671D\u987E\u5BA2\u3001\u4E0D\u51D1\u6574\u3001\u4E0D\u5360\u9053\u3002\u7ACB\u610F\u662F\u300C\u4E00\u89C6\u540C\u4EC1\u7684\u51C6\u300D\uFF0C\u6BD4\u540C\u9898\u7684\u8D5E\u7F8E\u6587\u9AD8\u51FA\u4E00\u5C42\uFF0C\u4E5F\u907F\u514D\u4E86\u611F\u52A8\u5F0F\u7684\u6292\u60C5\u3002"
          },
          {
            aspect: "\u7ED3\u6784\u5E03\u5C40",
            text: "\u73AF\u5883\uFF08\u644A\u4F4D\u4E0E\u4E09\u6837\u5BB6\u5F53\uFF09\u2014\u89C4\u77E9\uFF08\u56DB\u4E2A\u7EC6\u8282\u5E76\u5217\uFF09\u2014\u4E00\u6B21\u4E92\u52A8\uFF08\u8C46\u89D2\u7092\u8FD8\u662F\u7116\uFF09\u2014\u4E00\u4E2A\u4E8B\u4EF6\uFF08\u591A\u6536\u4E00\u5757\u4E3B\u52A8\u8FD8\uFF09\u2014\u8BA4\u8BC6\u8F6C\u53D8\uFF08\u4ECE\u5BF9\u6211\u597D\u5230\u5BF9\u6240\u6709\u4EBA\u4E00\u6837\uFF09\u2014\u6536\u5728\u6848\u5B50\u4E0A\u3002\u7531\u7269\u5230\u4EBA\u3001\u7531\u4EBA\u5230\u89C4\u77E9\u3001\u7531\u89C4\u77E9\u5230\u8BA4\u8BC6\uFF0C\u5C42\u5C42\u5411\u5185\uFF0C\u6700\u540E\u4E00\u6BB5\u56DE\u6263\u5F00\u5934\u7684\u4F4D\u7F6E\uFF0C\u7ED3\u6784\u95ED\u5408\u3002"
          },
          {
            aspect: "\u8BED\u8A00\u8868\u8FBE",
            text: "\u53D9\u8FF0\u6E05\u7B80\uFF0C\u51E0\u4E4E\u4E0D\u7528\u5F62\u5BB9\u8BCD\uFF1B\u5BF9\u8BDD\u5168\u90E8\u77ED\u53E5\uFF0C\u90FD\u662F\u5E72\u6D3B\u7684\u4EBA\u4F1A\u8BF4\u7684\u8BDD\uFF1B\u300C\u6848\u5B50\u300D\u300C\u6C34\u78E8\u77F3\u300D\u300C\u4EF7\u7B7E\u300D\u8FD9\u7C7B\u804C\u4E1A\u7528\u8BED\u7EDF\u4E00\u4E86\u5168\u6587\u7684\u8D28\u611F\u3002\u5168\u7BC7\u6700\u50CF\u5B66\u751F\u7684\u4E00\u5904\u662F\u300C\u597D\u50CF\u90A3\u4E00\u5757\u94B1\u6BD4\u5979\u5341\u5E74\u91CC\u7684\u4EFB\u4F55\u4E00\u5929\u90FD\u4E0D\u503C\u5F97\u591A\u8BB2\u300D\uFF0C\u53E5\u5B50\u504F\u957F\uFF0C\u7528\u529B\u7A0D\u8FC7\u3002"
          },
          {
            aspect: "\u7D20\u6750\u8FD0\u7528",
            text: "\u8FD8\u94B1\u4E00\u6BB5\u662F\u5168\u7BC7\u6700\u6709\u529B\u7684\u7D20\u6750\uFF1A\u4E00\u4E2A\u804C\u4E1A\u9519\u8BEF\uFF08\u7B97\u9519\u94B1\uFF09\u4E0E\u4E00\u4E2A\u804C\u4E1A\u4E60\u60EF\uFF08\u6536\u644A\u6570\u94B1\u3001\u5BF9\u8D26\u3001\u7FFB\u4EF7\u7B7E\uFF09\u8FDE\u5728\u4E00\u8D77\uFF0C\u4EBA\u7269\u56E0\u6B64\u53EF\u4FE1\uFF1B\u300C\u5356\u6C34\u4EA7\u7684\u6362\u8FC7\u4E09\u56DE\uFF0C\u5356\u5364\u5473\u7684\u6362\u8FC7\u4E24\u56DE\u300D\u7528\u522B\u4EBA\u7684\u6D41\u52A8\u886C\u6258\u5979\u7684\u4E0D\u53D8\uFF0C\u6BD4\u76F4\u63A5\u5938\u300C\u5979\u4E00\u76F4\u575A\u6301\u300D\u6709\u8BF4\u670D\u529B\u3002"
          },
          {
            aspect: "\u5347\u683C\u5EFA\u8BAE",
            text: "\u300C\u6211\u4EE5\u524D\u89C9\u5F97\u2026\u2026\u6162\u6162\u5730\u6211\u53D1\u73B0\u300D\u662F\u8BF4\u660E\u6027\u7684\u8F6C\u6298\uFF0C\u53EF\u6539\u6210\u4E00\u6B21\u4EB2\u773C\u6240\u89C1\uFF08\u5979\u7ED9\u8033\u6735\u4E0D\u597D\u7684\u963F\u5A46\u91CD\u590D\u7B2C\u4E09\u904D\u65F6\uFF0C\u624B\u4E00\u76F4\u6276\u7740\u888B\u53E3\u4E0D\u52A8\uFF09\uFF0C\u8BA9\u8F6C\u53D8\u7531\u753B\u9762\u5B8C\u6210\uFF1B\u300C\u6BD4\u5979\u5341\u5E74\u91CC\u7684\u4EFB\u4F55\u4E00\u5929\u90FD\u4E0D\u503C\u5F97\u591A\u8BB2\u300D\u5220\u6210\u300C\u597D\u50CF\u90A3\u4E00\u5757\u94B1\u4E0D\u503C\u5F97\u591A\u8BB2\u300D\uFF0C\u53E5\u5B50\u5E72\u51C0\uFF0C\u5206\u5BF8\u4E5F\u66F4\u51C6\uFF1B\u7B2C\u4E09\u6BB5\u300C\u4E0D\u77E5\u9053\uFF0C\u6211\u5988\u6CA1\u8BF4\u300D\u53EF\u4EE5\u7701\u53BB\uFF0C\u76F4\u63A5\u8BA9\u5979\u56DE\u7B54\uFF0C\u8282\u594F\u66F4\u5229\u843D\u3002"
          }
        ],
        comment: "\u8FD9\u7BC7\u7684\u6210\u529F\u5728\u4E8E\u628A\u300C\u656C\u91CD\u300D\u5EFA\u7ACB\u5728\u4E13\u4E1A\u4E0A\uFF0C\u800C\u4E0D\u662F\u60C5\u611F\u4E0A\u3002\u5168\u7BC7\u6CA1\u6709\u4E00\u53E5\u5938\u83B2\u59E8\u7684\u8BDD\uFF0C\u300C\u51C6\u300D\u5B57\u7531\u4E09\u4EF6\u4E8B\u6491\u8D77\u6765\uFF1A\u628A\u79E4\u9762\u8F6C\u5411\u987E\u5BA2\u3001\u627E\u96F6\u5148\u628A\u96F6\u94B1\u6446\u5728\u6848\u5B50\u4E0A\u3001\u7B97\u9519\u4E00\u5757\u94B1\u6B21\u65E5\u4E3B\u52A8\u5949\u8FD8\u3002\u8FD8\u94B1\u90A3\u4E00\u6BB5\u5C24\u5176\u89C1\u529F\u529B\u2014\u2014\u9519\u8BEF\u7684\u6765\u6E90\uFF08\u6536\u644A\u5BF9\u8D26\uFF09\u548C\u9762\u5BF9\u9519\u8BEF\u7684\u65B9\u5F0F\uFF08\u62CD\u4E0B\u4E00\u5757\u94B1\uFF0C\u5C31\u53BB\u62DB\u547C\u4E0B\u4E00\u4E2A\u987E\u5BA2\uFF09\u90FD\u662F\u804C\u4E1A\u6027\u7684\uFF0C\u4EBA\u7269\u56E0\u6B64\u65E2\u4E0D\u5351\u5FAE\u4E5F\u4E0D\u9080\u529F\u3002\u7ED3\u6784\u4E0A\u4ECE\u5934\u5230\u5C3E\u5B88\u7740\u90A3\u5F20\u6C34\u78E8\u77F3\u6848\u5B50\uFF0C\u5F00\u5934\u4E0E\u7ED3\u5C3E\u5404\u51FA\u73B0\u4E00\u6B21\uFF0C\u4F4D\u7F6E\u4E0D\u53D8\uFF0C\u6070\u597D\u5370\u8BC1\u4E86\u300C\u540C\u4E00\u4EF6\u5C0F\u4E8B\u505A\u5F97\u8DDF\u6628\u5929\u4E00\u6837\u51C6\u300D\u3002\u4E0D\u8DB3\u662F\u8F6C\u6298\u53E5\u4ECD\u504F\u8BF4\u660E\uFF0C\u300C\u6162\u6162\u5730\u6211\u53D1\u73B0\u300D\u7565\u7A7A\uFF1B\u300C\u6BD4\u5979\u5341\u5E74\u91CC\u7684\u4EFB\u4F55\u4E00\u5929\u90FD\u4E0D\u503C\u5F97\u591A\u8BB2\u300D\u4E00\u8BCD\u7528\u529B\u8FC7\u731B\uFF0C\u7565\u7834\u574F\u901A\u7BC7\u514B\u5236\u7684\u8BED\u611F\u3002"
      },
      {
        title: "\u8303\u6587\u4E8C\uFF1A\u69D0\u6811\u4E0B\u7684\u4FEE\u978B\u644A",
        prompt: "\u9898\u76EE\uFF1A\u300A\u4E00\u4E2A\u4E0D\u80AF\u5C06\u5C31\u7684\u4EBA\u300B\u3002\u8981\u6C42\uFF1A\u5199\u4E00\u7BC7\u4E0D\u5C11\u4E8E 600 \u5B57\u7684\u8BB0\u53D9\u6587\uFF0C\u5199\u8EAB\u8FB9\u4E00\u4F4D\u666E\u901A\u52B3\u52A8\u8005\uFF0C\u7528\u5177\u4F53\u7684\u52A8\u4F5C\u4E0E\u5BF9\u8BDD\u8868\u73B0\u4ED6/\u5979\u7684\u4E13\u4E1A\uFF1B\u4E0D\u5F97\u4F7F\u7528\u300C\u5E73\u51E1\u800C\u4F1F\u5927\u300D\u4E00\u7C7B\u7684\u8BC4\u8BED\u3002",
        score: "\u4E00\u7C7B\u6587\uFF0850\u201455 \u5206\uFF09",
        text: "\u5C0F\u533A\u5357\u95E8\u5916\u6709\u4E00\u68F5\u8001\u69D0\u6811\uFF0C\u6811\u4E0B\u6446\u7740\u4E00\u4E2A\u4FEE\u978B\u644A\u3002\u644A\u4E3B\u59D3\u5468\uFF0C\u4E03\u5341\u5C81\u4E0A\u4E0B\uFF0C\u6234\u4E00\u526F\u773C\u955C\uFF0C\u955C\u817F\u7F20\u7740\u767D\u80F6\u5E03\u3002\u4ED6\u7684\u5BB6\u5F53\u5F88\u5C11\uFF1A\u4E00\u53F0\u624B\u6447\u8865\u978B\u673A\uFF0C\u4E00\u4E2A\u6728\u5934\u7BB1\u5B50\uFF0C\u4E00\u53EA\u5C0F\u9A6C\u624E\uFF0C\u811A\u8FB9\u7684\u6728\u677F\u4E0A\u9489\u7740\u51E0\u6392\u5C0F\u94C1\u9489\u548C\u978B\u638C\u3002\n\u6211\u7B2C\u4E00\u6B21\u53BB\u662F\u521D\u4E8C\u90A3\u5E74\u51AC\u5929\uFF0C\u7403\u978B\u7684\u53F3\u811A\u540E\u8DDF\u78E8\u7A7F\u4E86\uFF0C\u9732\u51FA\u91CC\u9762\u767D\u8272\u7684\u6CE1\u68C9\u3002\u6211\u628A\u978B\u9012\u8FC7\u53BB\uFF1A\u300C\u4E24\u8FB9\u90FD\u6362\u4E00\u4E0B\u5427\uFF0C\u597D\u770B\u3002\u300D\n\u8001\u5468\u628A\u4E24\u53EA\u978B\u63A5\u8FC7\u53BB\uFF0C\u5148\u4E0D\u770B\u7834\u7684\u5730\u65B9\uFF0C\u800C\u662F\u628A\u978B\u7FFB\u8FC7\u6765\u653E\u5728\u819D\u76D6\u4E0A\uFF0C\u4E24\u53EA\u978B\u8DDF\u5E76\u5728\u4E00\u8D77\u5BF9\u9F50\uFF0C\u772F\u7740\u773C\u770B\u4E86\u4E00\u4F1A\u513F\u3002\u4ED6\u8BF4\uFF1A\u300C\u4E0D\u7528\u6362\u4E24\u53EA\u3002\u300D\u4ED6\u628A\u978B\u8DDF\u4E3E\u7ED9\u6211\u770B\uFF1A\u5DE6\u811A\u7684\u53EA\u78E8\u6389\u4E00\u5C42\uFF0C\u53F3\u811A\u5DF2\u7ECF\u78E8\u5230\u5E95\uFF0C\u8FD8\u78E8\u5F97\u504F\u5916\u3002\u4ED6\u8BF4\uFF1A\u300C\u4F60\u8D70\u8DEF\u53F3\u811A\u5F80\u5916\u6487\uFF0C\u5149\u6362\u8DDF\u6CA1\u7528\uFF0C\u6211\u7ED9\u4F60\u628A\u53F3\u638C\u52A0\u539A\u4E00\u70B9\uFF0C\u78E8\u8D77\u6765\u8DDF\u5DE6\u8FB9\u5DEE\u4E0D\u591A\u65F6\u5019\u5230\u3002\u300D\n\u6211\u4E0D\u592A\u61C2\uFF0C\u4E5F\u4E0D\u60F3\u61C2\uFF0C\u53EA\u60F3\u5FEB\u70B9\u8D70\uFF0C\u5C31\u8BF4\u968F\u4FBF\u3002\n\u4ED6\u6CA1\u6025\u7740\u52A8\u624B\u3002\u4ED6\u5148\u7528\u5200\u628A\u7834\u53E3\u8FB9\u7F18\u7684\u6BDB\u8FB9\u524A\u9F50\uFF0C\u524A\u4E0B\u6765\u7684\u788E\u5C51\u662F\u7070\u767D\u8272\u7684\uFF0C\u4ED6\u7528\u624B\u6307\u626B\u5230\u4E00\u8FB9\uFF1B\u7136\u540E\u526A\u4E86\u4E00\u5757\u6BD4\u978B\u8DDF\u7A0D\u5927\u7684\u9ED1\u80F6\u76AE\uFF0C\u653E\u5728\u978B\u8DDF\u4E0A\u6BD4\u4E86\u4E09\u6B21\uFF0C\u7528\u94C5\u7B14\u5728\u80CC\u9762\u753B\u4E86\u4E00\u9053\u7EBF\u624D\u4E0B\u526A\uFF1B\u4E0A\u80F6\u4EE5\u540E\uFF0C\u4ED6\u6CA1\u6709\u7ACB\u523B\u538B\uFF0C\u800C\u662F\u628A\u978B\u6401\u5728\u7BB1\u5B50\u4E0A\u7B49\u4E86\u4E00\u4F1A\u513F\uFF0C\u8BF4\u80F6\u8981\u5403\u8FDB\u53BB\u3002\u4ED6\u4E24\u624B\u4EA4\u53C9\u653E\u5728\u819D\u76D6\u4E0A\uFF0C\u51AC\u5929\u7684\u592A\u9633\u7167\u5728\u4ED6\u624B\u80CC\u4E0A\uFF0C\u80FD\u770B\u89C1\u4E00\u5757\u5757\u6DF1\u8272\u7684\u6591\u3002\u8FD9\u4E00\u7B49\u5C31\u662F\u4E03\u516B\u5206\u949F\u3002\n\u8865\u597D\u4EE5\u540E\uFF0C\u4ED6\u628A\u978B\u9012\u7ED9\u6211\uFF0C\u8BF4\uFF1A\u300C\u5148\u7A7F\u4E09\u5929\uFF0C\u4E0D\u5BF9\u518D\u6765\u3002\u300D\n\u6211\u7A7F\u5230\u7B2C\u56DB\u5929\uFF0C\u89C9\u5F97\u53F3\u8FB9\u6709\u70B9\u786C\uFF0C\u78E8\u811A\u8E1D\u3002\u6211\u53C8\u53BB\u4E86\uFF0C\u4EE5\u4E3A\u4ED6\u8981\u8BF4\u6211\u8D70\u8DEF\u59FF\u52BF\u7684\u4E8B\u3002\u4ED6\u6CA1\u8BF4\u3002\u4ED6\u628A\u978B\u7FFB\u8FC7\u6765\u770B\u770B\uFF0C\u62FF\u5C0F\u9524\u628A\u638C\u8FB9\u6572\u8584\u4E86\u4E00\u70B9\uFF0C\u53C8\u7528\u5200\u524A\u4E86\u4E24\u4E0B\uFF0C\u8BF4\uFF1A\u300C\u8FD9\u56DE\u884C\u4E86\u3002\u300D\u94B1\u4E00\u5206\u6CA1\u591A\u8981\u3002\u6211\u638F\u94B1\u65F6\u8BF4\u8C22\u8C22\uFF0C\u4ED6\u8BF4\uFF1A\u300C\u8D70\u4E24\u6B65\u6211\u770B\u770B\u3002\u300D\u6211\u8D70\u4E86\u51E0\u6B65\uFF0C\u4ED6\u70B9\u4E86\u70B9\u5934\uFF0C\u624D\u628A\u978B\u88C5\u8FDB\u888B\u5B50\u3002\n\u540E\u6765\u6211\u624D\u77E5\u9053\uFF0C\u4ED6\u5728\u76AE\u978B\u5382\u505A\u8FC7\u5341\u51E0\u5E74\u6837\u978B\uFF0C\u9000\u4F11\u540E\u5728\u8FD9\u513F\u6446\u644A\uFF0C\u4E00\u5929\u4FEE\u4E0D\u4E86\u51E0\u53CC\u3002\u6709\u4EBA\u529D\u4ED6\u6DA8\u4EF7\uFF0C\u4ED6\u8BF4\uFF1A\u300C\u6DA8\u4E86\u4EBA\u5C31\u4E0D\u6765\u4E86\uFF0C\u6211\u5728\u8FD9\u513F\u4E0D\u662F\u4E3A\u4E86\u6323\u8FD9\u4E2A\u3002\u300D\n\u6211\u539F\u6765\u4EE5\u4E3A\uFF0C\u624B\u827A\u597D\u5C31\u662F\u8865\u5F97\u7262\u3001\u770B\u4E0D\u51FA\u6765\u3002\u8BA4\u8BC6\u8001\u5468\u4EE5\u540E\uFF0C\u6211\u6539\u4E86\u60F3\u6CD5\u3002\u8865\u5F97\u7262\u662F\u672C\u4E8B\uFF0C\u4E0D\u80AF\u5C06\u5C31\u624D\u662F\u4ED6\u7684\u89C4\u77E9\uFF1A\u4ED6\u5B81\u53EF\u5C11\u6536\u4E00\u6B21\u94B1\uFF0C\u4E5F\u4E0D\u80AF\u628A\u4E00\u53EA\u78E8\u504F\u7684\u978B\u8DDF\u968F\u968F\u4FBF\u4FBF\u6362\u6389\uFF1B\u4ED6\u4E00\u53E5\u300C\u5148\u7A7F\u4E09\u5929\u300D\uFF0C\u662F\u628A\u9A8C\u6536\u7684\u6743\u5229\u4EA4\u8FD8\u7ED9\u7A7F\u978B\u7684\u4EBA\u3002\u4ED6\u4E0D\u80AF\u628A\u6D3B\u5E72\u5F97\u521A\u521A\u597D\uFF0C\u4ED6\u8981\u8BA9\u4EBA\u8D70\u8DEF\u65F6\u4E0D\u522B\u626D\u2014\u2014\u8FD9\u4EF6\u4E8B\u542C\u4E0A\u53BB\u5F88\u5C0F\uFF0C\u53EF\u6BCF\u5929\u8D70\u8DEF\u7684\u4EBA\u662F\u6211\u3002\n\u540E\u6765\u6211\u8DEF\u8FC7\u69D0\u6811\u5E95\u4E0B\uFF0C\u5E38\u5E38\u770B\u89C1\u4ED6\u4F4E\u7740\u5934\u3002\u644A\u5B50\u4E0A\u6CA1\u6709\u62DB\u724C\uFF0C\u53EA\u6709\u90A3\u5757\u9489\u6EE1\u5C0F\u94C1\u9489\u7684\u6728\u677F\uFF0C\u548C\u4ED6\u978B\u5E95\u5728\u6C34\u6CE5\u5730\u4E0A\u78E8\u51FA\u7684\u4E00\u5C0F\u5757\u6D45\u5751\uFF0C\u6BD4\u62DB\u724C\u5199\u5F97\u6E05\u695A\u3002",
        highlights: [
          {
            sentence: "\u8001\u5468\u628A\u4E24\u53EA\u978B\u63A5\u8FC7\u53BB\uFF0C\u5148\u4E0D\u770B\u7834\u7684\u5730\u65B9\uFF0C\u800C\u662F\u628A\u978B\u7FFB\u8FC7\u6765\u653E\u5728\u819D\u76D6\u4E0A\uFF0C\u4E24\u53EA\u978B\u8DDF\u5E76\u5728\u4E00\u8D77\u5BF9\u9F50\uFF0C\u772F\u7740\u773C\u770B\u4E86\u4E00\u4F1A\u513F\u3002",
            why: "\u4FEE\u978B\u7684\u7B2C\u4E00\u4E2A\u52A8\u4F5C\u662F\u300C\u770B\u300D\uFF0C\u800C\u4E14\u770B\u7684\u662F\u6CA1\u7834\u7684\u90A3\u53EA\u978B\u2014\u2014\u4E00\u4E2A\u52A8\u4F5C\u5C31\u628A\u4E13\u5BB6\u7684\u773C\u5149\u4E0E\u4EBA\u60C5\u5F0F\u7684\u597D\u5FC3\u533A\u5206\u5F00\u4E86\uFF1B\u300C\u772F\u7740\u773C\u300D\u8865\u4E0A\u795E\u6001\uFF0C\u753B\u9762\u5B8C\u6574\u3002"
          },
          {
            sentence: "\u4E0A\u80F6\u4EE5\u540E\uFF0C\u4ED6\u6CA1\u6709\u7ACB\u523B\u538B\uFF0C\u800C\u662F\u628A\u978B\u6401\u5728\u7BB1\u5B50\u4E0A\u7B49\u4E86\u4E00\u4F1A\u513F\uFF0C\u8BF4\u80F6\u8981\u5403\u8FDB\u53BB\u3002",
            why: "\u8FD9\u4E00\u7B49\u662F\u624B\u827A\u4EBA\u7684\u65F6\u95F4\u89C2\uFF0C\u4E0E\u300C\u6211\u300D\u6025\u7740\u8D70\u7684\u5FC3\u7406\u6B63\u9762\u5BF9\u7167\uFF1B\u4F5C\u8005\u7684\u5224\u65AD\u4E0D\u7740\u4E00\u5B57\uFF0C\u5168\u9760\u4E00\u4E2A\u52A8\u4F5C\u548C\u4E00\u53E5\u884C\u4E1A\u8BDD\u5B8C\u6210\u3002"
          },
          {
            sentence: "\u6211\u7A7F\u5230\u7B2C\u56DB\u5929\uFF0C\u89C9\u5F97\u53F3\u8FB9\u6709\u70B9\u786C\uFF0C\u78E8\u811A\u8E1D\u3002\u6211\u53C8\u53BB\u4E86\uFF0C\u4EE5\u4E3A\u4ED6\u8981\u8BF4\u6211\u8D70\u8DEF\u59FF\u52BF\u7684\u4E8B\u3002\u4ED6\u6CA1\u8BF4\u3002",
            why: "\u4E09\u4E2A\u77ED\u53E5\u5C42\u5C42\u9000\u8BA9\uFF0C\u628A\u6211\u9884\u8BBE\u7684\u300C\u4ED6\u4F1A\u63A8\u5378\u8D23\u4EFB\u300D\u6253\u6D88\u6389\uFF1B\u4EBA\u7269\u7684\u4F53\u9762\u5728\u8FD9\u4E00\u300C\u4E0D\u8BF4\u300D\u91CC\u7ACB\u4F4F\uFF0C\u6BD4\u5199\u4ED6\u6001\u5EA6\u597D\u53EF\u4FE1\u5F97\u591A\u3002"
          },
          {
            sentence: "\u4ED6\u4E00\u53E5\u300C\u5148\u7A7F\u4E09\u5929\u300D\uFF0C\u662F\u628A\u9A8C\u6536\u7684\u6743\u5229\u4EA4\u8FD8\u7ED9\u7A7F\u978B\u7684\u4EBA\u3002",
            why: "\u628A\u4E00\u53E5\u884C\u4E1A\u53E3\u8BED\u7FFB\u8BD1\u6210\u4E00\u53E5\u8BA4\u8BC6\uFF0C\u662F\u5168\u7BC7\u7684\u652F\u70B9\uFF1B\u300C\u9A8C\u6536\u7684\u6743\u5229\u300D\u8FD9\u56DB\u4E2A\u5B57\u4E0D\u5938\u5F20\uFF0C\u5374\u70B9\u660E\u4E86\u8FD9\u4F4D\u624B\u827A\u4EBA\u771F\u6B63\u7684\u89C4\u77E9\u2014\u2014\u6D3B\u597D\u4E0D\u597D\uFF0C\u7531\u7528\u8FC7\u7684\u4EBA\u8BF4\u3002"
          },
          {
            sentence: "\u644A\u5B50\u4E0A\u6CA1\u6709\u62DB\u724C\uFF0C\u53EA\u6709\u90A3\u5757\u9489\u6EE1\u5C0F\u94C1\u9489\u7684\u6728\u677F\uFF0C\u548C\u4ED6\u978B\u5E95\u5728\u6C34\u6CE5\u5730\u4E0A\u78E8\u51FA\u7684\u4E00\u5C0F\u5757\u6D45\u5751\uFF0C\u6BD4\u62DB\u724C\u5199\u5F97\u6E05\u695A\u3002",
            why: "\u7ED3\u5C3E\u7528\u4E00\u4E2A\u78E8\u51FA\u6765\u7684\u6D45\u5751\u4EE3\u66FF\u5938\u5956\uFF0C\u7269\u4EF6\u672C\u8EAB\u5C31\u662F\u8D44\u5386\u8BC1\u660E\uFF1B\u300C\u6BD4\u62DB\u724C\u5199\u5F97\u6E05\u695A\u300D\u6536\u5F97\u5E72\u51C0\uFF0C\u4E0D\u6292\u60C5\uFF0C\u4E5F\u4E0D\u558A\u53E3\u53F7\u3002"
          }
        ],
        review: [
          {
            aspect: "\u5BA1\u9898\u7ACB\u610F",
            text: "\u6263\u4F4F\u9898\u76EE\u91CC\u7684\u300C\u4E0D\u80AF\u5C06\u5C31\u300D\uFF0C\u628A\u4EBA\u7269\u4EF7\u503C\u5EFA\u7ACB\u5728\u804C\u4E1A\u6807\u51C6\u4E0A\uFF1A\u4E0D\u4E3A\u591A\u6323\u94B1\u800C\u6362\u6389\u4E24\u53EA\u978B\u8DDF\uFF0C\u4E0D\u4E3A\u7701\u65F6\u95F4\u800C\u8DF3\u8FC7\u7B49\u5F85\u80F6\u5403\u8FDB\u53BB\u7684\u51E0\u5206\u949F\uFF0C\u4E0D\u80AF\u628A\u4E0D\u5408\u811A\u7684\u6D3B\u7559\u5728\u522B\u4EBA\u811A\u4E0A\u3002\u5168\u7BC7\u6CA1\u6709\u4E00\u53E5\u300C\u4ED6\u5F88\u4E86\u4E0D\u8D77\u300D\uFF0C\u5374\u5904\u5904\u8BA9\u4EBA\u656C\u91CD\u3002"
          },
          {
            aspect: "\u7ED3\u6784\u5E03\u5C40",
            text: "\u5BB6\u5F53\u4E0E\u5916\u8C8C\u2014\u7B2C\u4E00\u6B21\u4FEE\u978B\uFF08\u770B\u3001\u5224\u65AD\u3001\u62A5\u4EF7\uFF09\u2014\u624B\u4E0A\u7684\u52A8\u4F5C\uFF08\u524A\u3001\u6BD4\u3001\u526A\u3001\u7B49\uFF09\u2014\u7B2C\u4E8C\u6B21\u4E0A\u95E8\uFF08\u8FD4\u4FEE\u4E0D\u591A\u6536\u94B1\uFF09\u2014\u4ECE\u4E1A\u80CC\u666F\u2014\u8BA4\u8BC6\u8F6C\u53D8\u2014\u56DE\u6263\u644A\u5B50\u3002\u4E24\u6B21\u4E0A\u95E8\u662F\u5168\u7BC7\u7684\u9AA8\u67B6\uFF1A\u7B2C\u4E00\u6B21\u5199\u51FA\u4ED6\u7684\u4E13\u4E1A\u5224\u65AD\uFF0C\u7B2C\u4E8C\u6B21\u5199\u51FA\u4ED6\u5BF9\u8FD4\u4FEE\u7684\u6001\u5EA6\uFF0C\u4EBA\u7269\u7684\u53EF\u9760\u6027\u7531\u4E24\u4EF6\u4E8B\u53E0\u6210\u3002"
          },
          {
            aspect: "\u8BED\u8A00\u8868\u8FBE",
            text: "\u52A8\u4F5C\u63CF\u5199\u5BC6\u5EA6\u9AD8\u4E14\u6709\u5E8F\uFF08\u7FFB\u3001\u5BF9\u9F50\u3001\u772F\u3001\u524A\u3001\u626B\u3001\u6BD4\u3001\u753B\u3001\u526A\u3001\u7B49\uFF09\uFF0C\u51E0\u4E4E\u6BCF\u53E5\u4E00\u4E2A\u52A8\u4F5C\uFF0C\u8BFB\u8D77\u6765\u50CF\u5728\u770B\u5E72\u6D3B\uFF1B\u5BF9\u8BDD\u6781\u7701\uFF0C\u4E03\u53E5\u90FD\u662F\u884C\u4E1A\u91CC\u7684\u8BDD\uFF0C\u6CA1\u6709\u4E00\u53E5\u6292\u60C5\u53F0\u8BCD\u3002"
          },
          {
            aspect: "\u7D20\u6750\u8FD0\u7528",
            text: "\u300C\u524A\u4E0B\u6765\u7684\u788E\u5C51\u662F\u7070\u767D\u8272\u7684\uFF0C\u4ED6\u7528\u624B\u6307\u626B\u5230\u4E00\u8FB9\u300D\u300C\u51AC\u5929\u7684\u592A\u9633\u7167\u5728\u4ED6\u624B\u80CC\u4E0A\uFF0C\u80FD\u770B\u89C1\u4E00\u5757\u5757\u6DF1\u8272\u7684\u6591\u300D\u4E24\u5904\u7EC6\u8282\uFF0C\u628A\u804C\u4E1A\u4E0E\u5E74\u9F84\u540C\u65F6\u5199\u51FA\u6765\uFF0C\u4E0D\u9760\u300C\u4ED6\u5E74\u7EAA\u5927\u4E86\u5F88\u8F9B\u82E6\u300D\u8FD9\u7C7B\u5224\u65AD\uFF1B\u300C\u4E00\u5929\u4FEE\u4E0D\u4E86\u51E0\u53CC\u300D\u5219\u7528\u751F\u610F\u7684\u6E05\u6DE1\u53CD\u886C\u4ED6\u4E0D\u6DA8\u4EF7\u7684\u7406\u7531\u3002"
          },
          {
            aspect: "\u5347\u683C\u5EFA\u8BAE",
            text: "\u300C\u540E\u6765\u6211\u624D\u77E5\u9053\uFF0C\u4ED6\u5728\u76AE\u978B\u5382\u505A\u8FC7\u5341\u51E0\u5E74\u7684\u6837\u978B\u300D\u8FD9\u53E5\u80CC\u666F\u4EA4\u4EE3\u6765\u5F97\u7A81\u7136\uFF0C\u53EF\u4EE5\u5728\u524D\u6587\u57CB\u4E00\u5904\u4F0F\u7B14\uFF08\u5982\u6728\u5934\u7BB1\u5B50\u4FA7\u9762\u8D34\u7740\u4E00\u5F20\u65E7\u5382\u91CC\u7684\u6807\u7B7E\uFF09\uFF0C\u8BA9\u4FE1\u606F\u6709\u6765\u8DEF\uFF1B\u7ED3\u5C3E\u300C\u53EF\u6BCF\u5929\u8D70\u8DEF\u7684\u4EBA\u662F\u6211\u300D\u7565\u6709\u81EA\u6211\u5F3A\u8C03\uFF0C\u5220\u6389\u540E\u534A\u53E5\u8BA9\u53E5\u5B50\u505C\u5728\u300C\u4E0D\u522B\u626D\u300D\u4E0A\u66F4\u6C89\u7A33\uFF1B\u7B2C\u4E8C\u6B21\u4E0A\u95E8\u65F6\u300C\u4EE5\u4E3A\u4ED6\u8981\u8BF4\u6211\u8D70\u8DEF\u59FF\u52BF\u7684\u4E8B\u300D\u82E5\u8865\u4E00\u4E2A\u8EAB\u4F53\u53CD\u5E94\uFF08\u811A\u5F80\u540E\u7F29\u4E86\u4E00\u4E0B\uFF09\uFF0C\u5FC3\u865A\u4F1A\u66F4\u5177\u4F53\u3002"
          }
        ],
        comment: "\u8FD9\u7BC7\u5199\u300C\u4E13\u4E1A\u300D\u5199\u5F97\u5F88\u5230\u4F4D\uFF1A\u5168\u7BC7\u4E09\u5206\u4E4B\u4E8C\u7684\u7BC7\u5E45\u90FD\u5728\u5E72\u6D3B\u2014\u2014\u5BF9\u9F50\u4E24\u53EA\u978B\u8DDF\u3001\u6307\u51FA\u53F3\u811A\u78E8\u504F\u3001\u524A\u6BDB\u8FB9\u3001\u6BD4\u4E09\u6B21\u624D\u4E0B\u526A\u3001\u4E0A\u80F6\u540E\u7B49\u4E03\u516B\u5206\u949F\u3001\u8FD4\u4FEE\u65F6\u6572\u8584\u638C\u8FB9\u3002\u4F5C\u8005\u4E0D\u8BC4\u4EF7\u8001\u5468\u7684\u6280\u672F\uFF0C\u53EA\u7528\u52A8\u4F5C\u5BC6\u5EA6\u8BF4\u8BDD\uFF0C\u8BFB\u8005\u81EA\u7136\u4FE1\u4ED6\u3002\u300C\u5148\u7A7F\u4E09\u5929\uFF0C\u4E0D\u5BF9\u518D\u6765\u300D\u662F\u5168\u7BC7\u6700\u91CD\u7684\u4E00\u53E5\u8BDD\uFF0C\u5B83\u628A\u9A8C\u6536\u6743\u4EA4\u7ED9\u4E86\u7A7F\u978B\u7684\u4EBA\uFF0C\u4E5F\u628A\u8FD9\u4F4D\u624B\u827A\u4EBA\u771F\u6B63\u7684\u4F53\u9762\u70B9\u4E86\u51FA\u6765\uFF1A\u4E0D\u662F\u5634\u4E0A\u8C26\u865A\uFF0C\u662F\u8BA9\u6D3B\u81EA\u5DF1\u7B54\u9898\u3002\u7ED3\u5C3E\u7528\u5730\u4E0A\u78E8\u51FA\u7684\u4E00\u5C0F\u5757\u6D45\u5751\u6536\u675F\uFF0C\u4E0D\u6292\u60C5\u800C\u4F59\u5473\u8DB3\u3002\u4E0D\u8DB3\u6709\u4E8C\uFF1A\u76AE\u978B\u5382\u7684\u80CC\u666F\u6765\u5F97\u7A81\u5140\uFF0C\u524D\u6587\u7F3A\u5C11\u4F0F\u7B14\uFF1B\u300C\u53EF\u6BCF\u5929\u8D70\u8DEF\u7684\u4EBA\u662F\u6211\u300D\u8FD9\u53E5\u7565\u5E26\u81EA\u6211\u5F3A\u8C03\uFF0C\u4F5C\u8005\u660E\u660E\u5DF2\u7ECF\u8DB3\u591F\u514B\u5236\uFF0C\u6B64\u5904\u7A0D\u663E\u591A\u4F59\u3002"
      }
    ],
    exercise: {
      prompt: "\u5199\u4E00\u4F4D\u4F60\u5E38\u89C1\u9762\u7684\u666E\u901A\u52B3\u52A8\u8005\uFF08\u644A\u4E3B\u3001\u4FEE\u978B\u5320\u3001\u5FEB\u9012\u9A7F\u7AD9\u8001\u677F\u3001\u98DF\u5802\u963F\u59E8\u3001\u516C\u4EA4\u53F8\u673A\u2026\u2026\uFF09\uFF0C\u9898\u76EE\u81EA\u62DF\uFF0C\u5199\u4E00\u7BC7 650 \u5B57\u4EE5\u4E0A\u7684\u8BB0\u53D9\u6587\u3002\u8981\u6C42\u5199\u51FA\u4ED6/\u5979\u7684\u4E13\u4E1A\u7EC6\u8282\uFF0C\u5168\u7BC7\u4E0D\u5F97\u4F7F\u7528\u300C\u5E73\u51E1\u800C\u4F1F\u5927\u300D\u300C\u9ED8\u9ED8\u5949\u732E\u300D\u300C\u4EE4\u4EBA\u611F\u52A8\u300D\u8FD9\u7C7B\u8BCD\u3002",
      tips: [
        "\u5148\u5199\u4ED6\u7684\u300C\u5BB6\u4F19\u300D\uFF1A\u5DE5\u5177\u3001\u644A\u4F4D\u3001\u4F4D\u7F6E\u3001\u8EAB\u4E0A\u90A3\u4EF6\u7528\u65E7\u7684\u4E1C\u897F\uFF0C\u8BA9\u8BFB\u8005\u5148\u770B\u89C1\u8FD9\u4E2A\u4EBA\u518D\u542C\u4ED6\u8BF4\u8BDD\u3002",
        "\u81F3\u5C11\u5199\u4E00\u6B21\u5177\u4F53\u7684\u300C\u4EA4\u6613\u300D\u6216\u300C\u670D\u52A1\u300D\u8FC7\u7A0B\uFF0C\u7528\u52A8\u4F5C\u4E0E\u5BF9\u8BDD\u4EE3\u66FF\u8BC4\u4EF7\uFF0C\u4E0D\u7528\u300C\u4ED6\u6280\u672F\u5F88\u597D\u300D\u8FD9\u7C7B\u5224\u65AD\u53E5\u3002",
        "\u4E3A\u4ED6\u627E\u51FA\u4E00\u6761\u89C4\u77E9\uFF08\u4E0D\u51D1\u6574\u3001\u4E0D\u7F3A\u79E4\u3001\u4E0D\u5C06\u5C31\u3001\u4E0D\u5360\u9053\u3001\u4E0D\u8BEF\u70B9\uFF09\uFF0C\u5168\u6587\u56F4\u7ED5\u8FD9\u6761\u89C4\u77E9\u9009\u6750\uFF0C\u4E0D\u5199\u4E0E\u5B83\u65E0\u5173\u7684\u4E8B\u3002",
        "\u4E0D\u8981\u66FF\u4EBA\u7269\u603B\u7ED3\u4EBA\u751F\uFF1A\u4ED6\u8BF4\u7684\u90FD\u662F\u5E72\u6D3B\u7684\u8BDD\uFF0C\u9053\u7406\u8BA9\u300C\u6211\u300D\u6765\u8BF4\uFF0C\u800C\u4E14\u53EA\u8BF4\u4E00\u53E5\u3002"
      ]
    }
  }
];

// src/data/chinese/writing-samples-philosophy.ts
var writingSamplesPhilosophy = [
  {
    id: "w-sample-zheli-2",
    grade: "all",
    category: "\u8303\u6587\u70B9\u8BC4",
    theme: "\u751F\u6D3B\u54F2\u7406",
    title: "\u8303\u6587\u70B9\u8BC4\uFF1A\u751F\u6D3B\u54F2\u7406 \xB7 \u540C\u9898\u4E24\u7BC7\u300A\u8981\u8DFA\u4E24\u4E0B\u624D\u4EAE\u7684\u706F\u300B\u300A\u4E00\u53EA\u7B77\u5B50\u7684\u7528\u5904\u300B",
    summary: "\u540C\u4E00\u4E2A\u300C\u501F\u65E5\u5E38\u5C0F\u7269\u5199\u4E00\u70B9\u8BA4\u8BC6\u300D\u7684\u547D\u9898\uFF0C\u4E24\u7BC7\u5199\u6CD5\u4E0D\u540C\uFF1A\u4E00\u7BC7\u7528\u697C\u9053\u4E0A\u90A3\u76CF\u8981\u8DFA\u4E24\u4E0B\u811A\u624D\u4EAE\u7684\u65E7\u58F0\u63A7\u706F\u5199\u300C\u56DE\u5E94\u300D\uFF0C\u4E00\u7BC7\u7528\u5BB6\u91CC\u51E0\u53EA\u914D\u4E0D\u6210\u5BF9\u7684\u7B77\u5B50\u5199\u300C\u6B8B\u7F3A\u7684\u7528\u5904\u300D\uFF0C\u5BF9\u6BD4\u7740\u770B\u80FD\u5B66\u4F1A\u628A\u8BA4\u8BC6\u843D\u5728\u7269\u4E0A\u3001\u800C\u4E0D\u662F\u558A\u5728\u7ED3\u5C3E\u3002",
    content: [
      "## \u9898\u76EE",
      "\u8FD9\u4E00\u7EC4\u5BF9\u5E94\u7684\u547D\u9898\u5F62\u5F0F\u662F\u300C\u4EE5\u5C0F\u89C1\u5927\u300D\u7C7B\uFF1A\u7ED9\u4E00\u4E2A\u5177\u4F53\u5230\u4E0D\u80FD\u518D\u5177\u4F53\u7684\u5199\u4F5C\u5BF9\u8C61\uFF08\u4E00\u4EF6\u7528\u4E45\u4E86\u7684\u65E7\u7269\u3001\u4E00\u4E2A\u5929\u5929\u91CD\u590D\u7684\u5C0F\u52A8\u4F5C\u3001\u4E00\u5904\u603B\u4E5F\u4E0D\u987A\u624B\u7684\u5730\u65B9\uFF09\uFF0C\u8981\u6C42\u5199\u51FA\u5B83\u5E26\u7ED9\u4F60\u7684\u8BA4\u8BC6\u3002\u4E24\u7BC7\u8303\u6587\u7684\u547D\u9898\u8981\u6C42\u5206\u522B\u662F\uFF1A",
      "\u8303\u6587\u4E00\uFF1A\u300A\u8981\u8DFA\u4E24\u4E0B\u624D\u4EAE\u7684\u706F\u300B\u3002\u9898\u610F\u504F\u300C\u7269\u300D\u2014\u2014\u91CD\u70B9\u4EA4\u4EE3\u8FD9\u76CF\u706F\u7684\u6765\u5386\u548C\u5B83\u7684\u813E\u6C14\uFF0C\u4EE5\u53CA\u4F60\u5ACC\u8FC7\u5B83\u3001\u4E3A\u5B83\u62A5\u4FEE\u8FC7\u3001\u60F3\u6362\u6389\u5B83\u3001\u6700\u540E\u600E\u4E48\u5BF9\u5F85\u5B83\uFF1B\u300C\u8BA4\u8BC6\u300D\u85CF\u5728\u5ACC\u4E0E\u4E0D\u5ACC\u7684\u9009\u62E9\u91CC\u3002",
      "\u8303\u6587\u4E8C\uFF1A\u300A\u4E00\u53EA\u7B77\u5B50\u7684\u7528\u5904\u300B\u3002\u9898\u610F\u504F\u300C\u7528\u300D\u2014\u2014\u91CD\u70B9\u5199\u4E00\u4EF6\u6B8B\u7F3A\u6216\u591A\u4F59\u7684\u4E1C\u897F\u540E\u6765\u88AB\u62FF\u53BB\u505A\u4EC0\u4E48\uFF0C\u4EE5\u53CA\u4F60\u539F\u6765\u600E\u4E48\u770B\u5B83\u3001\u540E\u6765\u600E\u4E48\u770B\u5B83\u3002",
      "\u4E24\u9053\u9898\u540C\u4E00\u547D\u9898\u65B9\u5411\uFF0C\u5BA1\u9898\u65F6\u6709\u4E00\u5904\u662F\u5171\u901A\u7684\uFF1A\u9898\u76EE\u91CC\u7684\u90A3\u4E2A\u8BCD\u5DF2\u7ECF\u5728\u63D0\u793A\u8BA4\u8BC6\u7684\u843D\u70B9\u3002\u300C\u8DFA\u4E24\u4E0B\u300D\u63D0\u793A\u7684\u662F\u300C\u5B83\u4E3A\u4EC0\u4E48\u6162\u3001\u8FD9\u4EFD\u6162\u662F\u7559\u7ED9\u8C01\u7684\u300D\uFF0C\u300C\u7528\u5904\u300D\u63D0\u793A\u7684\u662F\u300C\u4E0D\u88AB\u5F53\u6210\u539F\u6765\u7684\u4E1C\u897F\u4EE5\u540E\uFF0C\u5B83\u8FD8\u80FD\u505A\u4EC0\u4E48\u300D\u3002\u5B66\u751F\u62FF\u5230\u8FD9\u7C7B\u9898\uFF0C\u7B2C\u4E00\u6B65\u4E0D\u662F\u60F3\u7D20\u6750\uFF0C\u800C\u662F\u628A\u90A3\u9053\u9898\u91CC\u6700\u4E0D\u8D77\u773C\u7684\u4E00\u4E2A\u8BCD\u5708\u51FA\u6765\u2014\u2014\u5B83\u5F80\u5F80\u5C31\u662F\u5168\u6587\u7684\u7ACB\u610F\u6240\u5728\u3002",
      "## \u7ACB\u610F",
      "\u4E24\u7BC7\u7684\u7ACB\u610F\u5FC5\u987B\u4E0D\u540C\uFF0C\u5426\u5219\u540C\u9898\u4E24\u7BC7\u770B\u4E0B\u6765\u53EA\u5B66\u4F1A\u4E86\u300C\u6362\u4E00\u4EF6\u4E1C\u897F\u91CD\u5199\u4E00\u904D\u300D\u3002",
      "\u8303\u6587\u4E00\u5199\u300C\u56DE\u5E94\u300D\uFF1A\u5B83\u4E0D\u5199\u8282\u7EA6\u7528\u7535\uFF0C\u4E5F\u4E0D\u5199\u65E7\u7269\u53EF\u8D35\uFF0C\u800C\u5199\u300C\u7075\u654F\u300D\u8FD9\u4EF6\u597D\u4E8B\u7684\u53E6\u4E00\u9762\u2014\u2014\u4E00\u76CF\u706F\u66FF\u6240\u6709\u7684\u58F0\u97F3\u4EAE\uFF0C\u5C31\u7B49\u4E8E\u6CA1\u66FF\u8C01\u4EAE\u8FC7\u3002\u8BA4\u8BC6\u4ECE\u8D34\u62A5\u4FEE\u5355\u65F6\u5199\u4E0B\u7684\u300C\u58F0\u63A7\u5931\u7075\u300D\u843D\u5230\u300C\u5B83\u6162\uFF0C\u4E0D\u662F\u5B83\u574F\uFF0C\u662F\u5B83\u628A\u8FD9\u70B9\u5149\u53EA\u7559\u7ED9\u8981\u8D70\u8FD9\u6BB5\u697C\u68AF\u7684\u4EBA\u300D\u3002",
      "\u8303\u6587\u4E8C\u5199\u300C\u6B8B\u7F3A\u7684\u7528\u5904\u300D\uFF1A\u5B83\u4E0D\u5199\u300C\u6B8B\u7F3A\u4E5F\u5F88\u7F8E\u300D\u8FD9\u7C7B\u7A7A\u8BDD\uFF0C\u800C\u662F\u8001\u8001\u5B9E\u5B9E\u5217\u51FA\u90A3\u4E9B\u5355\u53EA\u7B77\u5B50\u73B0\u5728\u7684\u5DEE\u4E8B\u2014\u2014\u5835\u9171\u6CB9\u74F6\u3001\u677E\u82B1\u76C6\u7684\u571F\u3001\u57AB\u7827\u677F\u3001\u6345\u6CB9\u58F6\u5634\u3002\u4E00\u53EA\u7B77\u5B50\u4E0D\u80FD\u518D\u7528\u6765\u5939\u83DC\uFF0C\u53EF\u5B83\u5E76\u6CA1\u6709\u574F\uFF0C\u53EA\u662F\u88AB\u53EB\u53BB\u505A\u522B\u7684\u4E8B\u3002\u8BA4\u8BC6\u7684\u843D\u70B9\u662F\u300C\u7528\u5904\u6362\u4E86\uFF0C\u4E0D\u662F\u6CA1\u4E86\u300D\u3002",
      "\u4E24\u4E2A\u7ACB\u610F\u7684\u5171\u540C\u8981\u6C42\u662F\u300C\u4E0D\u8BF4\u9053\u6559\u300D\uFF1A\u5168\u6587\u4E0D\u51FA\u73B0\u300C\u4EBA\u751F\u7684\u9053\u7406\u300D\u300C\u8BA9\u6211\u61C2\u5F97\u300D\u300C\u6211\u4EEC\u8981\u73CD\u60DC\u300D\u8FD9\u7C7B\u53E5\u5B50\uFF0C\u6700\u540E\u53EA\u628A\u8BA4\u8BC6\u5E73\u76F4\u5730\u8BF4\u51FA\u6765\uFF08\u300C\u5B83\u6162\uFF0C\u4E0D\u662F\u5B83\u574F\uFF0C\u662F\u5B83\u628A\u8FD9\u70B9\u5149\u53EA\u7559\u7ED9\u8981\u8D70\u8FD9\u6BB5\u697C\u68AF\u7684\u4EBA\u300D\u300C\u5B83\u4EEC\u6CA1\u6709\u574F\uFF0C\u53EA\u662F\u88AB\u53EB\u53BB\u505A\u4E86\u522B\u7684\u4E8B\u300D\uFF09\uFF0C\u8BFB\u8005\u7684\u611F\u53D7\u7531\u524D\u6587\u7684\u4E8B\u5B9E\u81EA\u5DF1\u6512\u51FA\u6765\u3002\u8FD9\u4E00\u70B9\u6BD4\u9009\u6750\u96BE\uFF0C\u4E5F\u6B63\u662F\u8FD9\u4E24\u7BC7\u7684\u5F97\u5206\u70B9\u3002",
      "## \u7ED3\u6784",
      "\u4E24\u7BC7\u90FD\u662F\u516D\u5230\u4E03\u6B65\u7684\u63A8\u8FDB\uFF0C\u4F46\u63A8\u8FDB\u7684\u6293\u624B\u4E0D\u540C\uFF0C\u5B66\u751F\u53EF\u4EE5\u5BF9\u7167\u7740\u9009\u3002",
      "\u8303\u6587\u4E00\u662F\u300C\u7269\u2014\u4E8B\u2014\u609F\u300D\u8D70\u7684\u300C\u53CD\u590D\u5C1D\u8BD5\u578B\u300D\uFF0C\u5171\u516D\u6B65\uFF1A\u4E00\uFF0C\u4EAE\u51FA\u6BDB\u75C5\uFF08\u8DFA\u4E00\u4E0B\u4E0D\u4EAE\uFF0C\u5F97\u8DFA\u4E24\u4E0B\uFF0C\u7B2C\u4E8C\u4E0B\u8FD8\u8981\u6BD4\u7B2C\u4E00\u4E0B\u91CD\uFF0C\u4EAE\u4E4B\u524D\u5148\u95EA\u4E09\u4E0B\uFF09\uFF1B\u4E8C\uFF0C\u4EA4\u4EE3\u6765\u5904\uFF08\u8001\u5F0F\u58F0\u63A7\u706F\uFF0C\u697C\u91CC\u6700\u65E9\u90A3\u6279\u88C5\u4FEE\u65F6\u7EDF\u4E00\u88C5\u7684\uFF0C\u5851\u6599\u7F69\u53D1\u9EC4\u3001\u8FB9\u89D2\u88AB\u649E\u88C2\u8FC7\u4E00\u9053\u53E3\u5B50\uFF09\uFF1B\u4E09\uFF0C\u7B2C\u4E00\u6B21\u5931\u8D25\uFF08\u62CE\u7740\u4E24\u888B\u83DC\u7528\u811A\u5C16\u70B9\u5730\uFF0C\u4E24\u4E0B\u90FD\u6CA1\u4EAE\uFF0C\u53EA\u597D\u628A\u83DC\u888B\u6302\u5728\u6276\u624B\u4E0A\u8DFA\u811A\uFF1B\u6CA1\u770B\u51C6\u53F0\u9636\u8E29\u7A7A\uFF0C\u78D5\u9752\u4E86\u819D\u76D6\uFF09\uFF1B\u56DB\uFF0C\u4E00\u6B21\u65E0\u6548\u7684\u6297\u8BAE\uFF08\u8D34\u62A5\u4FEE\u5355\u88AB\u4EBA\u6495\u6389\uFF0C\u738B\u53D4\u4E00\u53E5\u300C\u4F60\u8D34\u90A3\u4E2A\u6CA1\u7528\uFF0C\u8FD9\u706F\u5C31\u5F97\u8DFA\u4E24\u4E0B\u300D\uFF09\uFF1B\u4E94\uFF0C\u4E3B\u52A8\u53BB\u6362\uFF08\u7269\u4E1A\u7EDF\u4E00\u6539\u4E0A\u65B0\u5F0F\u611F\u5E94\u706F\uFF0C\u592A\u7075\uFF0C\u98CE\u5439\u3001\u6C34\u7BA1\u54CD\u3001\u732B\u8DF3\u90FD\u4EAE\uFF0C\u6574\u591C\u4E0D\u706D\uFF0C\u4E00\u697C\u4F4F\u6237\u8D34\u7EB8\u8981\u6C42\u6362\u56DE\uFF0C\u65E7\u706F\u53C8\u539F\u6837\u6302\u56DE\u53BB\uFF09\uFF1B\u516D\uFF0C\u8BA4\u8BC6\u6539\u53D8\uFF08\u6DF1\u591C\u8DFA\u5B8C\u4E24\u4E0B\uFF0C\u542C\u51FA\u81EA\u5DF1\u90A3\u4E24\u58F0\u7684\u4E0D\u540C\uFF0C\u4E0D\u518D\u5ACC\u5B83\u6162\uFF09\u3002\u5B83\u7684\u5173\u952E\u662F\u7B2C\u4E94\u6B65\u2014\u2014\u5F20\u7F57\u7740\u6362\u65B0\u7684\u4E0D\u662F\u4F5C\u8005\u800C\u662F\u7269\u4E1A\uFF0C\u53EF\u300C\u7075\u654F\u300D\u8FD9\u4E00\u56DE\u5931\u8D25\u5F97\u660E\u660E\u767D\u767D\uFF0C\u7B2C\u516D\u6B65\u7684\u8BA4\u8BC6\u56E0\u6B64\u624D\u4E0D\u7A7A\u3002",
      "\u8303\u6587\u4E8C\u662F\u300C\u7269\u2014\u4EBA\u2014\u609F\u300D\u8D70\u7684\u300C\u91CD\u65B0\u547D\u540D\u578B\u300D\uFF0C\u5171\u4E03\u6B65\uFF1A\u4E00\uFF0C\u6446\u51FA\u73B0\u8C61\uFF08\u7B77\u7B3C\u6C38\u8FDC\u914D\u4E0D\u9F50\uFF0C\u5269\u4E09\u56DB\u53EA\u5355\u7684\uFF09\uFF1B\u4E8C\uFF0C\u4EA4\u4EE3\u6765\u5386\uFF08\u5404\u53EA\u77ED\u4E00\u70B9\u3001\u6D45\u4E00\u70B9\u3001\u6709\u9053\u5200\u5370\uFF0C\u914D\u5BF9\u7684\u90A3\u4E9B\u6298\u65AD\u4E86\u6216\u88AB\u4EBA\u5E26\u8D70\uFF09\uFF1B\u4E09\uFF0C\u4E00\u6B21\u5931\u8D25\u7684\u4F7F\u7528\uFF08\u6BCD\u4EB2\u628A\u5B83\u4EEC\u51D1\u6210\u4E24\u53CC\uFF0C\u5939\u83DC\u65F6\u4E00\u7B77\u5B50\u9752\u83DC\u6ED1\u5230\u684C\u4E0A\uFF09\uFF1B\u56DB\uFF0C\u65B0\u7684\u5B89\u7F6E\uFF08\u5835\u74F6\u53E3\u3001\u677E\u571F\u3001\u57AB\u7827\u677F\u3001\u6345\u6CB9\u58F6\uFF09\uFF1B\u4E94\uFF0C\u4E00\u6B21\u6362\u65B0\u7684\u5931\u6548\uFF08\u6574\u5957\u65B0\u7B77\u5B50\u7528\u4E86\u4E0D\u5230\u534A\u5E74\u4E5F\u65AD\u4E86\u4E00\u53EA\uFF0C\u5269\u4E0B\u4E03\u53EA\u56DE\u4E86\u7B77\u7B3C\uFF09\uFF1B\u516D\uFF0C\u4E00\u6B21\u300C\u5DEE\u70B9\u88AB\u6254\u6389\u300D\u7684\u9669\uFF08\u8FC7\u5E74\u626B\u9664\u6211\u8981\u4E22\uFF0C\u6BCD\u4EB2\u8BF4\u300C\u6254\u4E86\uFF0C\u7827\u677F\u5C31\u6643\u300D\uFF09\uFF1B\u4E03\uFF0C\u4E00\u6B21\u6B63\u7EDF\u7684\u767B\u573A\uFF08\u5BA2\u4EBA\u6765\u5403\u996D\uFF0C\u5355\u53EA\u7684\u4E0A\u4E86\u684C\uFF09\uFF0C\u6700\u540E\u56DE\u5230\u53A8\u623F\u6309\u4E00\u4E0B\u7827\u677F\u3002\u5B83\u7684\u5173\u952E\u662F\u7B2C\u516D\u6B65\u7684\u90A3\u53E5\u5BF9\u8BDD\uFF1A\u4E00\u53E5\u5BB6\u5E38\u8BDD\u5C31\u628A\u300C\u6709\u7528\u300D\u8FD9\u4EF6\u4E8B\u9489\u4F4F\u4E86\uFF0C\u6BD4\u4EFB\u4F55\u8BAE\u8BBA\u90FD\u786C\uFF1B\u7B2C\u4E94\u6B65\u4E5F\u91CD\u8981\u2014\u2014\u5B83\u8BC1\u660E\u300C\u914D\u4E0D\u9F50\u300D\u4E0D\u662F\u5BB6\u91CC\u6CA1\u4EBA\u7BA1\uFF0C\u800C\u662F\u9910\u5177\u672C\u6765\u5C31\u4EE5\u5355\u53EA\u544A\u7EC8\u3002",
      "\u4E24\u7BC7\u5728\u7ED3\u6784\u4E0A\u8FD8\u6709\u4E24\u5904\u5171\u540C\u7684\u624B\u827A\uFF0C\u503C\u5F97\u5B66\u751F\u6284\u4E0B\u6765\u5F53\u6A21\u677F\u3002\u7B2C\u4E00\uFF0C\u300C\u7269\u4EF6\u72B6\u6001\u5728\u53D8\u300D\uFF1A\u706F\u4ECE\u300C\u8DFA\u4E00\u4E0B\u4E0D\u4EAE\u300D\u5230\u300C\u8DFA\u4E24\u4E0B\u5FC5\u4EAE\u300D\uFF0C\u7B77\u5B50\u4ECE\u300C\u6CA1\u6CD5\u914D\u5BF9\u300D\u5230\u300C\u5728\u522B\u5904\u5404\u6709\u4E00\u4EFD\u5DEE\u4E8B\u300D\uFF1B\u72B6\u6001\u53D8\u4E86\uFF0C\u8BA4\u8BC6\u624D\u6709\u4F9D\u636E\u3002\u7B2C\u4E8C\uFF0C\u300C\u8BA4\u8BC6\u653E\u5728\u5012\u6570\u7B2C\u4E8C\u6BB5\uFF0C\u6B63\u6570\u7B2C\u4E8C\u6BB5\u4E4B\u524D\u5C31\u57CB\u597D\u4F0F\u7B14\u300D\uFF1A\u8303\u6587\u4E00\u5728\u7B2C\u4E8C\u6BB5\u5199\u300C\u8FB9\u89D2\u4E0D\u77E5\u88AB\u8C01\u649E\u88C2\u8FC7\u4E00\u9053\u53E3\u5B50\u300D\uFF0C\u65E7\u706F\u6302\u56DE\u53BB\u90A3\u4E00\u6BB5\u4ECD\u7136\u5199\u300C\u8FDE\u90A3\u9053\u88C2\u7F1D\u90FD\u8FD8\u5728\u539F\u6765\u7684\u4F4D\u7F6E\u300D\uFF1B\u8303\u6587\u4E8C\u5728\u5F00\u5934\u5199\u300C\u957F\u77ED\u4E0D\u4E00\u300D\uFF0C\u8FD9\u4E24\u5904\u90FD\u4E0D\u662F\u95F2\u7B14\uFF0C\u540E\u9762\u5168\u9760\u5B83\u4EEC\u63A5\u7BA1\u3002",
      "\u8FD8\u6709\u4E00\u5904\u53EF\u4EE5\u5BF9\u7167\u7740\u5B66\u7684\u95F4\u9694\u5B89\u6392\uFF1A\u4E24\u7BC7\u90FD\u628A\u300C\u6362\u4E00\u4EF6\u65B0\u7684\u300D\u653E\u5728\u5168\u6587\u7684\u4E09\u5206\u4E4B\u4E8C\u5904\uFF0C\u8BA9\u300C\u65B0\u7684\u300D\u5148\u5931\u8D25\u4E00\u6B21\u3002\u8303\u6587\u4E00\u6362\u7684\u662F\u4E00\u76CF\u66F4\u7075\u654F\u7684\u611F\u5E94\u706F\uFF0C\u8303\u6587\u4E8C\u6362\u7684\u662F\u6574\u5957\u65B0\u7B77\u5B50\uFF0C\u7ED3\u679C\u4E00\u76CF\u6574\u591C\u4EAE\u7740\u88AB\u4F4F\u6237\u8981\u6C42\u6362\u56DE\uFF0C\u4E00\u5957\u4E0D\u5230\u534A\u5E74\u53C8\u65AD\u4E86\u4E00\u53EA\u3002\u6362\u65B0\u5931\u6548\u4E4B\u540E\uFF0C\u8BA4\u8BC6\u624D\u4E0D\u662F\u4F5C\u8005\u7684\u611F\u6168\uFF0C\u800C\u662F\u88AB\u4E8B\u5B9E\u903C\u51FA\u6765\u7684\u3002",
      "## \u4EAE\u70B9",
      "\u56E0\u4E3A\u8FD9\u4E00\u6761\u91CC\u53EA\u6709\u4E00\u7EC4\u540C\u9898\uFF0C\u4E24\u7BC7\u7684\u624B\u6CD5\u9010\u6761\u644A\u5F00\u8BF4\uFF0C\u5B66\u751F\u53EF\u4EE5\u62FF\u7740\u6307\u6807\u53BB\u6570\u81EA\u5DF1\u7684\u4F5C\u6587\u3002",
      "\u8303\u6587\u4E00\uFF0C\u7B2C\u4E00\u5904\uFF1A\u628A\u300C\u6162\u300D\u5199\u6210\u4E00\u6761\u80FD\u7167\u7740\u505A\u7684\u89C4\u77E9\u3002\u5F00\u5934\u7684\u300C\u8DFA\u4E00\u4E0B\u4E0D\u4EAE\uFF0C\u5F97\u8DFA\u4E24\u4E0B\uFF0C\u7B2C\u4E8C\u4E0B\u8FD8\u8981\u6BD4\u7B2C\u4E00\u4E0B\u91CD\u300D\u52A0\u4E0A\u300C\u4EAE\u4E4B\u524D\u5148\u95EA\u4E09\u4E0B\u300D\uFF0C\u4EA4\u4EE3\u7684\u662F\u4E00\u4E2A\u53EF\u4EE5\u590D\u73B0\u7684\u64CD\u4F5C\u3002\u7269\u4EF6\u6709\u81EA\u5DF1\u7684\u89C4\u77E9\uFF0C\u540E\u9762\u7684\u6BCF\u4E00\u6B21\u7B49\u5F85\u624D\u7AD9\u5F97\u4F4F\uFF1B\u53CD\u8FC7\u6765\u8BF4\uFF0C\u5982\u679C\u4E00\u4E0A\u6765\u5C31\u5199\u300C\u8FD9\u76CF\u6162\u541E\u541E\u7684\u706F\u50CF\u4E0D\u50CF\u4EBA\u751F\u300D\uFF0C\u6587\u7AE0\u7ACB\u523B\u5C31\u5EC9\u4EF7\u4E86\u3002",
      "\u8303\u6587\u4E00\uFF0C\u7B2C\u4E8C\u5904\uFF1A\u7528\u75D5\u8FF9\u5199\u65F6\u95F4\uFF0C\u800C\u4E0D\u76F4\u63A5\u8BF4\u65F6\u95F4\u3002\u300C\u706F\u7F69\u662F\u767D\u7684\u5851\u6599\u7F69\uFF0C\u5E74\u5934\u4E45\u4E86\uFF0C\u53D1\u9EC4\u300D\uFF0C\u52A0\u4E0A\u300C\u8FB9\u89D2\u4E0D\u77E5\u88AB\u8C01\u649E\u88C2\u8FC7\u4E00\u9053\u53E3\u5B50\u300D\uFF0C\u4E0D\u5199\u300C\u5F88\u591A\u5E74\u8FC7\u53BB\u4E86\u300D\uFF0C\u53EA\u5199\u7F69\u5B50\u9EC4\u4E86\u3001\u88C2\u4E86\u3002\u8FD9\u662F\u751F\u6D3B\u54F2\u7406\u7C7B\u6700\u7A33\u7684\u4E00\u62DB\u2014\u2014\u65F6\u95F4\u4E0D\u80FD\u76F4\u63A5\u8BF4\uFF0C\u8981\u8BA9\u4E00\u4EF6\u4E1C\u897F\u66FF\u5B83\u7559\u75D5\u3002\u5B66\u751F\u53EF\u8FC1\u79FB\u7684\u505A\u6CD5\u662F\uFF1A\u5199\u53D8\u5316\u5C31\u5199\u78E8\u635F\u3001\u7F3A\u53E3\u3001\u6389\u8272\u3001\u8D77\u6BDB\uFF0C\u522B\u5199\u300C\u65E5\u5B50\u4E00\u5929\u5929\u8FC7\u53BB\u300D\u3002",
      "\u8303\u6587\u4E00\uFF0C\u7B2C\u4E09\u5904\uFF1A\u8BA9\u300C\u66F4\u597D\u7684\u4E1C\u897F\u300D\u5931\u8D25\u3002\u65B0\u706F\u66F4\u7075\u654F\u3001\u66F4\u7701\u7535\uFF0C\u88C5\u5F97\u4E5F\u6F02\u4EAE\uFF0C\u53EF\u5B83\u66FF\u98CE\u5439\u3001\u66FF\u6C34\u7BA1\u54CD\u3001\u66FF\u732B\u8DF3\uFF0C\u6700\u540E\u88AB\u4E00\u697C\u4F4F\u6237\u4E00\u5F20\u7EB8\u9000\u56DE\u3002\u8FD9\u4E00\u7B14\u628A\u5168\u6587\u4ECE\u300C\u62B1\u6028\u65E7\u4E1C\u897F\u300D\u63D0\u4E86\u4E00\u5C42\uFF1A\u65E7\u706F\u7684\u6162\u91CC\u6709\u5206\u8FA8\u3002\u7D27\u63A5\u7740\u5E08\u5085\u90A3\u53E5\u300C\u4F60\u4EEC\u8FD9\u76CF\u6162\uFF0C\u53EF\u5B83\u8BA4\u5F97\u4EBA\u300D\uFF0C\u662F\u5168\u6587\u552F\u4E00\u4E00\u6B21\u7531\u5916\u4EBA\u66FF\u8FD9\u76CF\u706F\u4F5C\u8BC1\uFF0C\u4F5C\u8005\u4E0D\u5FC5\u81EA\u5DF1\u5938\u5B83\u597D\u3002",
      "\u8303\u6587\u4E00\uFF0C\u7B2C\u56DB\u5904\uFF1A\u8BA4\u8BC6\u53E5\u4ECD\u7136\u5728\u8BF4\u706F\uFF0C\u6536\u5C3E\u53EA\u7559\u4E00\u4E2A\u52A8\u4F5C\u3002\u5012\u6570\u7B2C\u4E8C\u6BB5\u5199\u300C\u5B83\u6162\uFF0C\u4E0D\u662F\u5B83\u574F\uFF0C\u662F\u5B83\u628A\u8FD9\u70B9\u5149\u53EA\u7559\u7ED9\u8981\u8D70\u8FD9\u6BB5\u697C\u68AF\u7684\u4EBA\u300D\uFF0C\u5168\u53E5\u6CA1\u6709\u300C\u4EBA\u751F\u300D\u300C\u61C2\u5F97\u300D\u8FD9\u7C7B\u5B57\u773C\uFF1B\u672B\u53E5\u53EA\u5199\u300C\u6211\u56DE\u5934\u770B\u4E86\u4E00\u773C\uFF0C\u4E8C\u697C\u534A\u5DF2\u7ECF\u9ED1\u4E86\u300D\u2014\u2014\u697C\u9053\u91CD\u65B0\u9ED1\u4E0B\u53BB\uFF0C\u628A\u524D\u9762\u6240\u6709\u8DFA\u811A\u7684\u58F0\u97F3\u90FD\u6536\u62E2\u4E86\uFF0C\u4E00\u53E5\u6292\u60C5\u4E5F\u6CA1\u6709\u3002",
      "\u8303\u6587\u4E8C\uFF0C\u7B2C\u4E00\u5904\uFF1A\u7528\u4E00\u6B21\u5931\u8D25\u7684\u7528\u5904\u5F00\u5934\u3002\u6BCD\u4EB2\u628A\u5355\u53EA\u7B77\u5B50\u51D1\u6210\u4E24\u53CC\uFF0C\u300C\u4E00\u7B77\u5B50\u9752\u83DC\u6ED1\u4E0B\u53BB\u6389\u5728\u684C\u4E0A\u300D\uFF0C\u8BFB\u8D77\u6765\u662F\u597D\u7B11\u7684\uFF0C\u7B11\u8FC7\u4E4B\u540E\u300C\u4E0D\u6210\u53CC\u300D\u8FD9\u4EF6\u4E8B\u5C31\u6709\u4E86\u4F53\u611F\u3002\u5199\u300C\u4E0D\u65B9\u4FBF\u300D\u6C38\u8FDC\u4E0D\u5982\u5199\u4E00\u6B21\u5177\u4F53\u7684\u4E0D\u65B9\u4FBF\u3002",
      "\u8303\u6587\u4E8C\uFF0C\u7B2C\u4E8C\u5904\uFF1A\u7F57\u5217\u8981\u5177\u4F53\u5230\u52A8\u4F5C\u3002\u5835\u3001\u677E\u3001\u57AB\u3001\u6345\u56DB\u4E2A\u52A8\u8BCD\u5404\u914D\u4E00\u4EF6\u4E1C\u897F\uFF0C\u8BFB\u8005\u773C\u524D\u7ACB\u523B\u6709\u753B\u9762\uFF1B\u5982\u679C\u5199\u6210\u300C\u5B83\u4EEC\u8FD8\u6709\u522B\u7684\u7528\u5904\u300D\uFF0C\u8FD9\u4E00\u6BB5\u5C31\u5E9F\u4E86\u3002\u5B83\u7684\u6BDB\u75C5\u662F\u56DB\u4E2A\u5206\u53E5\u53E5\u5F0F\u5B8C\u5168\u4E00\u6837\uFF08\u89C1\u300C\u53EF\u6539\u8FDB\u300D\uFF09\uFF0C\u5B66\u751F\u7167\u5B66\u65F6\u8981\u7ED9\u5176\u4E2D\u4E00\u6761\u6362\u4E2A\u8BF4\u6CD5\u3002",
      "\u8303\u6587\u4E8C\uFF0C\u7B2C\u4E09\u5904\uFF1A\u8BF7\u4E00\u4E2A\u914D\u89D2\u8BF4\u4E00\u53E5\u786C\u8BDD\u3002\u6BCD\u4EB2\u90A3\u53E5\u300C\u6254\u4E86\uFF0C\u7827\u677F\u5C31\u6643\u300D\u662F\u5168\u6587\u7684\u5B9A\u76D8\u661F\uFF1A\u5979\u4E0D\u8BF4\u300C\u522B\u6D6A\u8D39\u300D\uFF0C\u53EA\u8BF4\u4E00\u4E2A\u540E\u679C\uFF0C\u7269\u7684\u4EF7\u503C\u88AB\u4E00\u53E5\u5BB6\u52A1\u5E38\u8BC6\u56FA\u5B9A\u4E0B\u6765\u3002\u5B66\u751F\u7684\u4F5C\u6587\u91CC\u5E38\u7F3A\u8FD9\u6837\u4E00\u53E5\u8BDD\uFF0C\u66FF\u4EE3\u54C1\u662F\u4F5C\u8005\u81EA\u5DF1\u7AD9\u51FA\u6765\u8BAE\u8BBA\u3002",
      "\u8303\u6587\u4E8C\uFF0C\u7B2C\u56DB\u5904\uFF1A\u8BA4\u8BC6\u7684\u53E5\u6CD5\u3002\u672B\u6BB5\u7684\u300C\u4E00\u53CC\u7B77\u5B50\u7684\u4E8B\uFF0C\u662F\u628A\u83DC\u4ECE\u76D8\u5B50\u91CC\u5939\u8D77\u6765\uFF1B\u4E00\u53EA\u7B77\u5B50\u7684\u4E8B\uFF0C\u662F\u9876\u3001\u57AB\u3001\u6345\u3001\u6311\u300D\uFF0C\u7528\u5BF9\u4E3E\u52A0\u56DB\u4E2A\u5355\u5B57\u52A8\u8BCD\u628A\u9053\u7406\u8BF4\u5F97\u5E72\u8106\uFF0C\u800C\u4E14\u6700\u540E\u7684\u843D\u70B9\u4ECD\u7136\u843D\u5728\u7269\u4E0A\u2014\u2014\u8FD9\u662F\u300C\u4E0D\u8BF4\u6559\u300D\u7684\u6B63\u9762\u793A\u8303\uFF1A\u9053\u7406\u53EF\u4EE5\u7528\u7269\u7684\u8BED\u8A00\u8BB2\u3002",
      "## \u53EF\u6539\u8FDB",
      "\u8303\u6587\u4E00\u7684\u7A1A\u5AE9\u5904\u6709\u4E24\u5904\u3002\u4E00\u662F\u7B2C\u4E94\u6BB5\u5404\u5BB6\u8DFA\u6CD5\u662F\u7EAF\u7F57\u5217\uFF08\u738B\u53D4\u7528\u811A\u8DDF\u3001\u9001\u5FEB\u9012\u7684\u5C0F\u4F19\u5B50\u62CD\u624B\u3001\u5916\u5A46\u7528\u62D0\u6756\u5934\uFF09\uFF0C\u4E09\u4E2A\u5206\u53E5\u53E5\u5F0F\u76F8\u540C\uFF0C\u8BFB\u8D77\u6765\u50CF\u6E05\u5355\uFF0C\u4E0E\u524D\u6587\u300C\u6211\u628A\u83DC\u888B\u6302\u5728\u697C\u68AF\u6276\u624B\u4E0A\u300D\u90A3\u79CD\u6293\u5B9E\u52A8\u4F5C\u7684\u5199\u6CD5\u4E0D\u7EDF\u4E00\uFF0C\u5EFA\u8BAE\u53EA\u7559\u4E24\u79CD\u3001\u628A\u5176\u4E2D\u4E00\u79CD\u5199\u7EC6\uFF08\u5982\u5199\u5916\u5A46\u7528\u62D0\u6756\u5934\u70B9\u5730\u90A3\u4E24\u4E0B\u6709\u591A\u8F7B\uFF09\u3002\u4E8C\u662F\u62A5\u4FEE\u5355\u88AB\u6495\u8FD9\u4EF6\u4E8B\u53EA\u5199\u4E86\u7ED3\u679C\uFF0C\u300C\u90A3\u5F20\u7EB8\u88AB\u4EBA\u6495\u4E86\u300D\u6CA1\u6709\u4EA4\u4EE3\u662F\u8C01\u6495\u7684\uFF0C\u4E5F\u6CA1\u6709\u5199\u300C\u6211\u300D\u5F53\u65F6\u7684\u53CD\u5E94\uFF0C\u738B\u53D4\u90A3\u53E5\u529D\u56E0\u6B64\u5C11\u4E86\u4E00\u5206\u538B\u529B\uFF1B\u672B\u5C3E\u5E08\u5085\u8BF4\u7684\u300C\u8BA4\u5F97\u4EBA\u300D\u4E5F\u6765\u5F97\u7565\u7A81\u5140\uFF0C\u524D\u6587\u6CA1\u8BA9\u8FD9\u4F4D\u5E08\u5085\u9732\u8FC7\u9762\uFF0C\u82E5\u5728\u88C5\u706F\u65F6\u5148\u7ED9\u4ED6\u4E00\u4E2A\u52A8\u4F5C\uFF08\u6BD4\u5982\u6458\u65E7\u706F\u7F69\u4E4B\u524D\u5148\u7528\u624B\u80CC\u8BD5\u4E86\u4E00\u4E0B\u706F\u7BA1\u7684\u6E29\u5EA6\uFF09\uFF0C\u8FD9\u53E5\u8BDD\u5C31\u7AD9\u4F4F\u4E86\u3002",
      "\u8303\u6587\u4E8C\u7684\u7A1A\u5AE9\u5904\u4E5F\u6709\u4E24\u5904\u3002\u4E00\u662F\u7B2C\u56DB\u6BB5\u662F\u7EAF\u7F57\u5217\uFF0C\u56DB\u4E2A\u5206\u53E5\u53E5\u5F0F\u76F8\u540C\uFF0C\u8BFB\u8D77\u6765\u50CF\u6E05\u5355\uFF0C\u4E0E\u524D\u6587\u300C\u957F\u77ED\u4E0D\u4E00\uFF0C\u50CF\u73ED\u91CC\u7AD9\u7740\u51E0\u4E2A\u6CA1\u6392\u4E0A\u961F\u7684\u5B66\u751F\u300D\u90A3\u79CD\u5E26\u6BD4\u55BB\u7684\u5199\u6CD5\u4E0D\u7EDF\u4E00\uFF0C\u5EFA\u8BAE\u4FDD\u7559\u4E09\u4EF6\u3001\u628A\u5176\u4E2D\u4E00\u4EF6\u5199\u7EC6\uFF08\u5982\u5199\u57AB\u7827\u677F\u90A3\u6839\u88AB\u538B\u5F97\u4E24\u5934\u8D77\u8C41\u53E3\uFF09\u3002\u4E8C\u662F\u5012\u6570\u7B2C\u4E8C\u6BB5\u7684\u8BAE\u8BBA\u8FDE\u8BF4\u4E86\u4E09\u53E5\uFF0C\u7B2C\u4E8C\u53E5\u300C\u5B83\u4EEC\u6CA1\u6709\u574F\u300D\u5DF2\u7ECF\u8BF4\u5230\u4E86\u70B9\u5B50\u4E0A\uFF0C\u7B2C\u4E09\u53E5\u300C\u53EA\u662F\u88AB\u53EB\u53BB\u505A\u4E86\u522B\u7684\u4E8B\u300D\u5176\u5B9E\u662F\u91CD\u590D\uFF0C\u5B66\u751F\u7684\u5E38\u89C1\u6BDB\u75C5\u6B63\u662F\u6015\u8BFB\u8005\u4E0D\u61C2\u800C\u628A\u540C\u4E00\u53E5\u8BDD\u6362\u7740\u8BF4\u4E24\u4E09\u904D\u3002",
      "\u4E24\u7BC7\u5171\u6709\u7684\u4E00\u5904\u53EF\u4EE5\u518D\u7D27\u4E00\u70B9\u7684\u5730\u65B9\uFF1A\u8BA4\u8BC6\u51FA\u73B0\u4E4B\u524D\uFF0C\u90FD\u5C11\u4E86\u4E00\u6B21\u300C\u522B\u4EBA\u600E\u4E48\u770B\u300D\u7684\u5BF9\u7167\u3002\u8303\u6587\u4E00\u91CC\u4E09\u697C\u7684\u738B\u53D4\u53EA\u8BF4\u4E86\u4E00\u53E5\u300C\u4F60\u8D34\u90A3\u4E2A\u6CA1\u7528\u300D\uFF0C\u8303\u6587\u4E8C\u91CC\u8205\u8205\u4E5F\u53EA\u662F\u628A\u4E24\u6839\u7B77\u5B50\u300C\u4E3E\u8D77\u6765\u5BF9\u9F50\u4E86\u4E00\u4E0B\u300D\uFF0C\u65C1\u4EBA\u7684\u53CD\u5E94\u90FD\u53EA\u6709\u4E00\u7B14\uFF1B\u82E5\u518D\u8865\u534A\u53E5\uFF08\u6BD4\u5982\u7269\u4E1A\u7684\u4EBA\u8BF4\u4E00\u58F0\u300C\u6362\u4E86\u4F60\u4EEC\u53C8\u5ACC\u5435\u300D\uFF0C\u6216\u8005\u8205\u5988\u95EE\u4E00\u53E5\u600E\u4E48\u7B77\u5B50\u90FD\u4E0D\u4E00\u6837\uFF09\uFF0C\u4F5C\u8005\u7684\u9009\u62E9\u5C31\u6709\u4E86\u538B\u529B\uFF0C\u540E\u9762\u7684\u8BA4\u8BC6\u4E5F\u66F4\u6709\u5206\u91CF\u3002"
    ],
    examples: [
      {
        title: "\u8303\u6587\u4E00\uFF1A\u8981\u8DFA\u4E24\u4E0B\u624D\u4EAE\u7684\u706F",
        prompt: "\u9898\u76EE\uFF1A\u300A\u8981\u8DFA\u4E24\u4E0B\u624D\u4EAE\u7684\u706F\u300B\u3002\u60C5\u5883\uFF1A\u697C\u9053\u91CC\u6216\u5BB6\u91CC\u603B\u6709\u4E00\u4E24\u4EF6\u7528\u5F97\u4E0D\u987A\u624B\u3001\u5374\u4E00\u76F4\u6CA1\u6362\u7684\u65E7\u4E1C\u897F\u3002\u8981\u6C42\uFF1A\u5199\u4E00\u7BC7\u4E0D\u5C11\u4E8E 600 \u5B57\u7684\u8BB0\u53D9\u6587\uFF0C\u5199\u6E05\u8FD9\u4EF6\u4E1C\u897F\u7684\u6765\u5386\u4E0E\u5B83\u7684\u6BDB\u75C5\uFF0C\u4EE5\u53CA\u4F60\u5ACC\u8FC7\u5B83\u4EC0\u4E48\u3001\u4E3A\u5B83\u505A\u8FC7\u4EC0\u4E48\u3001\u6700\u540E\u600E\u4E48\u5BF9\u5F85\u5B83\uFF1B\u4E0D\u5F97\u51FA\u73B0\u771F\u5B9E\u7684\u6821\u540D\u3001\u4EBA\u540D\u3002",
        score: "\u4E00\u7C7B\u6587\u4E0A\uFF0855\u201460 \u5206\uFF09",
        text: "\u6211\u4EEC\u697C\u9053\u90A3\u76CF\u706F\u662F\u8001\u5F0F\u7684\u58F0\u63A7\u706F\uFF0C\u88C5\u5728\u4E8C\u697C\u534A\u7684\u62D0\u89D2\u3002\u5B83\u6709\u4E2A\u813E\u6C14\uFF1A\u8DFA\u4E00\u4E0B\u4E0D\u4EAE\uFF0C\u5F97\u8DFA\u4E24\u4E0B\uFF0C\u7B2C\u4E8C\u4E0B\u8FD8\u8981\u6BD4\u7B2C\u4E00\u4E0B\u91CD\u3002\u706F\u7BA1\u662F\u7EC6\u767D\u7684\u65E5\u5149\u706F\u7BA1\uFF0C\u4EAE\u4E4B\u524D\u5148\u95EA\u4E09\u4E0B\u624D\u7A33\u4F4F\u3002\n\u706F\u7F69\u662F\u767D\u7684\u5851\u6599\u7F69\uFF0C\u5E74\u5934\u4E45\u4E86\uFF0C\u53D1\u9EC4\uFF0C\u4E0A\u9762\u843D\u7740\u4E00\u5C42\u6D6E\u7070\uFF0C\u8FB9\u89D2\u4E0D\u77E5\u88AB\u8C01\u649E\u88C2\u8FC7\u4E00\u9053\u53E3\u5B50\u3002\u8FD9\u76CF\u706F\u662F\u697C\u91CC\u6700\u65E9\u90A3\u6279\u88C5\u4FEE\u65F6\u7EDF\u4E00\u88C5\u7684\uFF0C\u6574\u680B\u697C\u7684\u4EBA\u90FD\u77E5\u9053\u5B83\u7684\u8DEF\u6570\uFF1A\u4E0A\u5230\u4E8C\u697C\u534A\uFF0C\u62AC\u811A\u8DFA\u4E24\u4E0B\u3002\n\u6211\u70E6\u8FC7\u5B83\u3002\u6709\u4E00\u56DE\u6211\u62CE\u7740\u4E24\u888B\u83DC\u4E0A\u697C\uFF0C\u4E24\u53EA\u624B\u90FD\u5360\u7740\uFF0C\u53EA\u597D\u7528\u811A\u5C16\u70B9\u5730\uFF0C\u4E24\u4E0B\u90FD\u6CA1\u4EAE\u3002\u6211\u628A\u83DC\u888B\u6302\u5728\u697C\u68AF\u6276\u624B\u4E0A\uFF0C\u8DFA\u4E86\u4E24\u811A\uFF0C\u706F\u624D\u95EA\u8D77\u6765\u3002\u8FD8\u6709\u4E00\u6B21\u6211\u6CA1\u770B\u51C6\u53F0\u9636\uFF0C\u8E29\u7A7A\u78D5\u9752\u4E86\u819D\u76D6\u3002\n\u6211\u4E00\u6C14\u4E4B\u4E0B\u5199\u4E86\u5F20\u62A5\u4FEE\u5355\uFF0C\u7528\u80F6\u5E26\u8D34\u5728\u706F\u7F69\u8FB9\u4E0A\uFF1A\u300C\u58F0\u63A7\u5931\u7075\uFF0C\u5EFA\u8BAE\u66F4\u6362\u3002\u300D\u7B2C\u4E8C\u5929\u518D\u4E0A\u697C\uFF0C\u90A3\u5F20\u7EB8\u88AB\u4EBA\u6495\u4E86\uFF0C\u53EA\u5269\u4E00\u5C0F\u5757\u80F6\u5E26\u7C98\u5728\u5851\u6599\u7F69\u4E0A\u3002\u6211\u53C8\u5199\u4E00\u5F20\uFF0C\u7B2C\u4E09\u5929\u4E5F\u6CA1\u4E86\u3002\u4E09\u697C\u7684\u738B\u53D4\u78B0\u89C1\u6211\uFF0C\u62CE\u7740\u62D6\u628A\uFF0C\u8BF4\uFF1A\u300C\u4F60\u8D34\u90A3\u4E2A\u6CA1\u7528\uFF0C\u8FD9\u706F\u5C31\u5F97\u8DFA\u4E24\u4E0B\u3002\u300D\u6211\u6CA1\u63A5\u8BDD\u3002\n\u540E\u6765\u6211\u53D1\u73B0\uFF0C\u697C\u91CC\u7684\u4EBA\u5404\u6709\u5404\u7684\u8DFA\u6CD5\u3002\u738B\u53D4\u7528\u811A\u8DDF\u8FDE\u7740\u8DFA\u4E24\u4E0B\uFF0C\u58F0\u97F3\u5F88\u8106\uFF1B\u9001\u5FEB\u9012\u7684\u5C0F\u4F19\u5B50\u8FDB\u95E8\u5148\u62CD\u4E24\u4E0B\u624B\uFF1B\u5916\u5A46\u4E0A\u697C\u6162\uFF0C\u6276\u7740\u6276\u624B\uFF0C\u7528\u62D0\u6756\u5934\u70B9\u4E24\u4E0B\u5730\u3002\u8DEF\u6570\u4E0D\u540C\uFF0C\u6B21\u6570\u90FD\u662F\u4E24\u4E0B\u3002\u6211\u4E5F\u8DFA\u5F97\u51C6\u4E86\uFF0C\u811A\u4E00\u843D\uFF0C\u5C31\u77E5\u9053\u7B2C\u4E8C\u4E0B\u8BE5\u4F7F\u591A\u5927\u52B2\u3002\n\u53BB\u5E74\u79CB\u5929\uFF0C\u7269\u4E1A\u8BF4\u8FD9\u6279\u8001\u706F\u7BA1\u8D39\u7535\uFF0C\u7EDF\u4E00\u6539\u6210\u65B0\u5F0F\u7684\u611F\u5E94\u706F\uFF0C\u7075\u654F\u5EA6\u9AD8\uFF0C\u6709\u4EBA\u7ECF\u8FC7\u5C31\u4EAE\u3002\u88C5\u706F\u90A3\u5929\uFF0C\u5E08\u5085\u8E29\u5728\u51F3\u5B50\u4E0A\u6458\u6389\u65E7\u706F\u7F69\uFF0C\u6362\u4E0A\u4E86\u4E00\u4E2A\u5706\u7684\u3001\u767D\u4EAE\u4EAE\u7684\u65B0\u706F\u3002\u5F53\u665A\u6211\u4ECE\u4E00\u697C\u8D70\u5230\u56DB\u697C\uFF0C\u4E00\u8DEF\u90FD\u4EAE\u3002\n\u53EF\u662F\u90A3\u76CF\u65B0\u706F\u592A\u7075\u4E86\u3002\u98CE\u4ECE\u5355\u5143\u95E8\u7F1D\u91CC\u704C\u8FDB\u6765\uFF0C\u5B83\u4EAE\uFF1B\u697C\u4E0A\u6709\u4EBA\u5173\u6C34\u9F99\u5934\uFF0C\u5B83\u4EAE\uFF1B\u5BF9\u9762\u697C\u7684\u732B\u8DF3\u4E00\u4E0B\uFF0C\u5B83\u4E5F\u4EAE\u3002\u5934\u4E00\u4E2A\u661F\u671F\uFF0C\u5B83\u6574\u591C\u4E0D\u706D\u3002\u4E00\u697C\u4F4F\u7684\u4E00\u5BB6\u7761\u7720\u6D45\uFF0C\u5728\u5355\u5143\u95E8\u4E0A\u8D34\u4E86\u4E00\u5F20\u7EB8\uFF1A\u300C\u8BF7\u628A\u697C\u9053\u706F\u6362\u56DE\u539F\u6765\u7684\u3002\u300D\u7269\u4E1A\u53C8\u6765\u4E86\u4E00\u8D9F\uFF0C\u65E7\u706F\u6CA1\u6254\uFF0C\u91CD\u65B0\u6302\u4E0A\u53BB\uFF0C\u8FDE\u90A3\u9053\u88C2\u7F1D\u90FD\u8FD8\u5728\u539F\u6765\u7684\u4F4D\u7F6E\u3002\u5E08\u5085\u62E7\u5B8C\u6700\u540E\u4E00\u9897\u87BA\u4E1D\uFF0C\u8BF4\uFF1A\u300C\u4F60\u4EEC\u8FD9\u76CF\u6162\uFF0C\u53EF\u5B83\u8BA4\u5F97\u4EBA\u3002\u300D\n\u90A3\u5929\u591C\u91CC\u6211\u56DE\u6765\u5F97\u665A\uFF0C\u8D70\u5230\u4E8C\u697C\u534A\uFF0C\u7167\u4F8B\u8DFA\u4E86\u4E24\u4E0B\uFF0C\u706F\u95EA\u4E09\u4E0B\u624D\u4EAE\u3002\u6211\u5728\u90A3\u70B9\u5149\u91CC\u7AD9\u4E86\u4E00\u4F1A\u513F\uFF0C\u542C\u6E05\u4E86\u81EA\u5DF1\u521A\u624D\u7684\u4E24\u58F0\uFF1A\u7B2C\u4E00\u4E0B\u8F7B\uFF0C\u662F\u8BD5\u63A2\uFF1B\u7B2C\u4E8C\u4E0B\u91CD\uFF0C\u662F\u544A\u8BC9\u5B83\u6211\u771F\u7684\u8981\u8D70\u8FD9\u4E00\u6B65\u3002\n\u65B0\u706F\u4E0D\u7528\u8C01\u5F00\u53E3\u5C31\u4EAE\uFF0C\u5B83\u66FF\u6574\u4E2A\u697C\u9053\u4EAE\uFF0C\u4E5F\u66FF\u98CE\u4EAE\uFF0C\u66FF\u732B\u4EAE\u3002\u6211\u4EEC\u8FD9\u76CF\u8981\u7B49\u7B2C\u4E8C\u4E0B\uFF0C\u7B49\u7684\u662F\u4E00\u4E2A\u4EBA\u771F\u7AD9\u5728\u90A3\u513F\u3002\u5B83\u6162\uFF0C\u4E0D\u662F\u5B83\u574F\uFF0C\u662F\u5B83\u628A\u8FD9\u70B9\u5149\u53EA\u7559\u7ED9\u8981\u8D70\u8FD9\u6BB5\u697C\u68AF\u7684\u4EBA\u3002\n\u6211\u8DFA\u5B8C\u7B2C\u4E8C\u4E0B\u4E0A\u697C\uFF0C\u811A\u4E0B\u6BD4\u5E73\u65F6\u8F7B\u3002\u8D70\u5230\u5BB6\u95E8\u53E3\uFF0C\u6211\u56DE\u5934\u770B\u4E86\u4E00\u773C\uFF0C\u4E8C\u697C\u534A\u5DF2\u7ECF\u9ED1\u4E86\u3002",
        highlights: [
          {
            sentence: "\u5B83\u6709\u4E2A\u813E\u6C14\uFF1A\u8DFA\u4E00\u4E0B\u4E0D\u4EAE\uFF0C\u5F97\u8DFA\u4E24\u4E0B\uFF0C\u7B2C\u4E8C\u4E0B\u8FD8\u8981\u6BD4\u7B2C\u4E00\u4E0B\u91CD\u3002",
            why: "\u628A\u300C\u6BDB\u75C5\u300D\u5199\u6210\u4E00\u6761\u53EF\u4EE5\u7167\u7740\u505A\u7684\u89C4\u77E9\uFF0C\u800C\u4E0D\u662F\u4E00\u4E0A\u6765\u5C31\u5F53\u8C61\u5F81\u7528\u3002\u7269\u4EF6\u6709\u4E86\u81EA\u5DF1\u7684\u813E\u6C14\u548C\u8DEF\u6570\uFF0C\u540E\u6587\u6BCF\u4E00\u6B21\u8DFA\u811A\u3001\u6BCF\u4E00\u6B21\u5931\u8D25\u624D\u90FD\u6709\u4F9D\u636E\uFF1B\u751F\u6D3B\u54F2\u7406\u7C7B\u6700\u6015\u7684\u5C31\u662F\u8DF3\u8FC7\u8FD9\u4E2A\u89C4\u77E9\u76F4\u63A5\u6292\u60C5\u3002"
          },
          {
            sentence: "\u6211\u628A\u83DC\u888B\u6302\u5728\u697C\u68AF\u6276\u624B\u4E0A\uFF0C\u8DFA\u4E86\u4E24\u811A\uFF0C\u706F\u624D\u95EA\u8D77\u6765\u3002",
            why: "\u7528\u4E00\u6B21\u5177\u4F53\u7684\u4E0D\u65B9\u4FBF\u4EE3\u66FF\u62B1\u6028\uFF1A\u4E24\u53EA\u624B\u5360\u7740\uFF0C\u811A\u5C16\u70B9\u5730\u6CA1\u7528\uFF0C\u53EA\u597D\u628A\u83DC\u888B\u5F80\u6276\u624B\u4E0A\u4E00\u6302\u3002\u5199\u300C\u8FD9\u706F\u5F88\u70E6\u300D\u6C38\u8FDC\u4E0D\u5982\u5199\u8FD9\u4E00\u6B21\u4E3A\u96BE\uFF1B\u300C\u6302\u300D\u8FD9\u4E2A\u52A8\u4F5C\u672C\u8EAB\u5C31\u8BF4\u660E\u4E86\u4EBA\u88AB\u4E00\u4EF6\u5C0F\u4E1C\u897F\u652F\u4F7F\u7684\u7A98\u6001\u3002"
          },
          {
            sentence: "\u6211\u5728\u90A3\u70B9\u5149\u91CC\u7AD9\u4E86\u4E00\u4F1A\u513F\uFF0C\u542C\u6E05\u4E86\u81EA\u5DF1\u521A\u624D\u7684\u4E24\u58F0\uFF1A\u7B2C\u4E00\u4E0B\u8F7B\uFF0C\u662F\u8BD5\u63A2\uFF1B\u7B2C\u4E8C\u4E0B\u91CD\uFF0C\u662F\u544A\u8BC9\u5B83\u6211\u771F\u7684\u8981\u8D70\u8FD9\u4E00\u6B65\u3002",
            why: "\u5168\u6587\u7684\u8F6C\u6298\u70B9\u3002\u8BA4\u8BC6\u4E0D\u662F\u4ECE\u9053\u7406\u91CC\u6765\u7684\uFF0C\u662F\u4ECE\u81EA\u5DF1\u811A\u5E95\u4E0B\u7684\u58F0\u97F3\u91CC\u542C\u51FA\u6765\u7684\uFF1B\u300C\u8BD5\u63A2\u300D\u4E0E\u300C\u544A\u8BC9\u5B83\u300D\u628A\u4E24\u58F0\u8DFA\u811A\u5206\u4E86\u5DE5\uFF0C\u62BD\u8C61\u7684\u300C\u56DE\u5E94\u300D\u4E8E\u662F\u5C31\u843D\u5728\u811A\u4E0A\u3002"
          },
          {
            sentence: "\u5B83\u6162\uFF0C\u4E0D\u662F\u5B83\u574F\uFF0C\u662F\u5B83\u628A\u8FD9\u70B9\u5149\u53EA\u7559\u7ED9\u8981\u8D70\u8FD9\u6BB5\u697C\u68AF\u7684\u4EBA\u3002",
            why: "\u5168\u7BC7\u8BA4\u8BC6\u7684\u843D\u70B9\uFF0C\u4ECD\u7136\u5728\u8BF4\u8FD9\u76CF\u706F\uFF0C\u6CA1\u6709\u8DF3\u5230\u4EBA\u751F\u4E0A\u53BB\u3002\u524D\u6587\u90A3\u5F20\u62A5\u4FEE\u5355\u4E0A\u5199\u7684\u6B63\u662F\u300C\u58F0\u63A7\u5931\u7075\u300D\uFF0C\u300C\u4E0D\u662F\u5B83\u574F\u300D\u56DB\u4E2A\u5B57\u56DE\u5934\u628A\u90A3\u5F20\u7EB8\u6495\u4E86\u4E00\u6B21\uFF1B\u9053\u7406\u8BF4\u5F97\u8D8A\u50CF\u5728\u8BF4\u7269\uFF0C\u8D8A\u4E0D\u50CF\u5728\u6559\u80B2\u4EBA\u3002"
          },
          {
            sentence: "\u6211\u56DE\u5934\u770B\u4E86\u4E00\u773C\uFF0C\u4E8C\u697C\u534A\u5DF2\u7ECF\u9ED1\u4E86\u3002",
            why: "\u4EE5\u753B\u9762\u6536\u5C3E\uFF0C\u4E0D\u603B\u7ED3\u3002\u706F\u91CD\u65B0\u9ED1\u4E0B\u53BB\uFF0C\u7B49\u4E8E\u628A\u6EE1\u697C\u9053\u7684\u8DFA\u811A\u58F0\u6536\u62E2\u8D77\u6765\uFF1B\u672B\u53E5\u91CC\u6CA1\u6709\u4E00\u4E2A\u60C5\u7EEA\u8BCD\uFF0C\u8BFB\u8005\u7684\u611F\u53D7\u7531\u524D\u6587\u7684\u4E8B\u5B9E\u81EA\u5DF1\u6512\u51FA\u6765\uFF0C\u4E5F\u4E0D\u4F1A\u88AB\u4E00\u53E5\u603B\u7ED3\u53E5\u538B\u4F4F\u3002"
          }
        ],
        review: [
          {
            aspect: "\u5BA1\u9898\u7ACB\u610F",
            text: "\u6293\u4F4F\u9898\u76EE\u91CC\u300C\u8981\u8DFA\u4E24\u4E0B\u300D\u8FD9\u4E2A\u522B\u626D\u5904\uFF0C\u628A\u300C\u6162\u300D\u5199\u6210\u957F\u671F\u72B6\u6001\u800C\u4E0D\u662F\u5076\u53D1\u6545\u969C\uFF1B\u7ACB\u610F\u4E0D\u843D\u5728\u8282\u7EA6\u7528\u7535\u6216\u65E7\u7269\u53EF\u8D35\u4E0A\uFF0C\u800C\u843D\u5728\u300C\u7075\u654F\u300D\u7684\u53E6\u4E00\u9762\u2014\u2014\u4E00\u76CF\u706F\u66FF\u6240\u6709\u7684\u58F0\u97F3\u4EAE\uFF0C\u5C31\u7B49\u4E8E\u6CA1\u66FF\u8C01\u4EAE\u8FC7\u3002\u8BA4\u8BC6\u7684\u6700\u540E\u4E00\u53E5\u4ECD\u7136\u5728\u8BF4\u8FD9\u76CF\u706F\uFF0C\u6CA1\u6709\u8DE8\u5230\u300C\u4EBA\u751F\u300D\u4E0A\u53BB\uFF0C\u56E0\u6B64\u6BD4\u4E00\u822C\u5199\u65E7\u7269\u7684\u6587\u7AE0\u9AD8\u4E00\u5C42\u3002"
          },
          {
            aspect: "\u7ED3\u6784\u5E03\u5C40",
            text: "\u516D\u6B65\u63A8\u8FDB\uFF1A\u4EAE\u6BDB\u75C5\uFF08\u8DFA\u4E24\u4E0B\u624D\u4EAE\uFF09\u2014\u4EA4\u4EE3\u6765\u5904\uFF08\u8001\u5F0F\u58F0\u63A7\u706F\u3001\u53D1\u9EC4\u7684\u5851\u6599\u7F69\u3001\u88C2\u7F1D\uFF09\u2014\u7B2C\u4E00\u6B21\u5931\u8D25\uFF08\u62CE\u7740\u4E24\u888B\u83DC\u7528\u811A\u5C16\u70B9\u5730\uFF0C\u4E24\u4E0B\u90FD\u6CA1\u4EAE\uFF09\u2014\u4E00\u6B21\u65E0\u6548\u7684\u6297\u8BAE\uFF08\u62A5\u4FEE\u5355\u88AB\u6495\uFF0C\u738B\u53D4\u4E00\u53E5\u8BDD\uFF09\u2014\u4E00\u6B21\u6362\u65B0\u5931\u6548\uFF08\u65B0\u611F\u5E94\u706F\u6574\u591C\u4E0D\u706D\uFF0C\u88AB\u4E00\u697C\u4F4F\u6237\u9000\u56DE\uFF0C\u65E7\u706F\u6302\u56DE\u539F\u5904\uFF09\u2014\u8BA4\u8BC6\u6539\u53D8\u3002\u6362\u65B0\u5931\u6548\u653E\u5728\u5168\u6587\u7684\u4E09\u5206\u4E4B\u4E8C\u5904\uFF0C\u8BA9\u300C\u66F4\u597D\u7684\u4E1C\u897F\u300D\u5148\u5931\u8D25\u4E00\u6B21\uFF0C\u672B\u6BB5\u7684\u8BA4\u8BC6\u624D\u6709\u4F9D\u636E\uFF1B\u7B2C\u4E8C\u6BB5\u57CB\u4E0B\u7684\u88C2\u7F1D\u5728\u65E7\u706F\u6302\u56DE\u53BB\u65F6\u53C8\u88AB\u63D0\u8D77\u63A5\u7BA1\u3002"
          },
          {
            aspect: "\u8BED\u8A00\u8868\u8FBE",
            text: "\u901A\u7BC7\u77ED\u53E5\uFF0C\u52A8\u8BCD\u7528\u5F97\u51C6\uFF08\u8DFA\u3001\u70B9\u3001\u6302\u3001\u62CE\u3001\u62E7\u3001\u78D5\uFF09\uFF1B\u300C\u5B83\u6709\u4E2A\u813E\u6C14\u300D\u300C\u8FDE\u90A3\u9053\u88C2\u7F1D\u90FD\u8FD8\u5728\u539F\u6765\u7684\u4F4D\u7F6E\u300D\u8FD9\u7C7B\u8BF4\u6CD5\u5BB6\u5E38\u800C\u6709\u5206\u5BF8\uFF0C\u6CA1\u6709\u4E00\u53E5\u5806\u780C\u5F62\u5BB9\u8BCD\u3002\u5BF9\u8BDD\u53EA\u6709\u4E24\u53E5\uFF0C\u4E00\u53E5\u662F\u738B\u53D4\u7684\u529D\uFF0C\u4E00\u53E5\u662F\u5E08\u5085\u7684\u8BC1\u8BCD\uFF0C\u7701\u5230\u4E0D\u80FD\u518D\u7701\uFF0C\u4E5F\u6B63\u56E0\u4E3A\u7701\uFF0C\u8FD9\u4E24\u53E5\u90FD\u50CF\u662F\u771F\u7684\u3002"
          },
          {
            aspect: "\u7D20\u6750\u8FD0\u7528",
            text: "\u4E00\u76CF\u697C\u9053\u706F\u627F\u62C5\u4E86\u5168\u6587\u4E09\u4E2A\u529F\u80FD\uFF1A\u8BF4\u660E\u6BDB\u75C5\uFF08\u8DFA\u4E24\u4E0B\u7684\u89C4\u77E9\uFF09\u3001\u6307\u5411\u90BB\u91CC\uFF08\u5404\u5BB6\u7684\u8DFA\u6CD5\u3001\u4E00\u697C\u4F4F\u6237\u7684\u7761\u7720\uFF09\u3001\u627F\u8F7D\u65F6\u95F4\uFF08\u7F69\u5B50\u53D1\u9EC4\u3001\u8FB9\u89D2\u5F00\u88C2\uFF09\u3002\u5B66\u751F\u8981\u5B66\u7684\u662F\u8FD9\u79CD\u300C\u4E00\u4E2A\u7269\u8C61\u591A\u7528\u300D\u7684\u7528\u6CD5\u2014\u2014\u4E0D\u5FC5\u4E3A\u6BCF\u4E2A\u610F\u601D\u6362\u4E00\u4EF6\u4E1C\u897F\uFF0C\u628A\u4E00\u4EF6\u4E1C\u897F\u5199\u900F\u66F4\u5212\u7B97\u3002"
          },
          {
            aspect: "\u5347\u683C\u5EFA\u8BAE",
            text: "\u7B2C\u4E94\u6BB5\u5404\u5BB6\u8DFA\u6CD5\u662F\u7EAF\u7F57\u5217\uFF0C\u4E09\u4E2A\u5206\u53E5\u53E5\u5F0F\u76F8\u540C\uFF0C\u8BFB\u8D77\u6765\u50CF\u6E05\u5355\uFF0C\u5EFA\u8BAE\u53EA\u7559\u4E24\u79CD\u3001\u628A\u5916\u5A46\u7528\u62D0\u6756\u5934\u70B9\u5730\u90A3\u4E24\u4E0B\u5199\u7EC6\uFF1B\u62A5\u4FEE\u5355\u88AB\u6495\u53EA\u5199\u4E86\u7ED3\u679C\uFF0C\u6CA1\u6709\u4EA4\u4EE3\u662F\u8C01\u6495\u7684\u3001\u4F5C\u8005\u5F53\u65F6\u4EC0\u4E48\u53CD\u5E94\uFF0C\u738B\u53D4\u90A3\u4E00\u53E5\u529D\u56E0\u6B64\u5C11\u4E86\u538B\u529B\uFF1B\u672B\u5C3E\u5E08\u5085\u300C\u8BA4\u5F97\u4EBA\u300D\u4E5F\u6765\u5F97\u7565\u7A81\u5140\uFF0C\u53EF\u5728\u88C5\u706F\u65F6\u5148\u7ED9\u4ED6\u4E00\u4E2A\u52A8\u4F5C\uFF08\u5982\u6458\u65E7\u706F\u7F69\u524D\u7528\u624B\u80CC\u8BD5\u4E00\u4E0B\u706F\u7BA1\u7684\u6E29\u5EA6\uFF09\uFF0C\u8BA9\u8FD9\u53E5\u8BDD\u6709\u6765\u5386\u3002"
          }
        ],
        comment: "\u8FD9\u7BC7\u7684\u957F\u5904\u662F\u514B\u5236\uFF1A\u5168\u7BC7\u6CA1\u6709\u4E00\u5904\u300C\u6211\u660E\u767D\u4E86\u300D\uFF0C\u8BA4\u8BC6\u662F\u4ECE\u8DFA\u811A\u58F0\u3001\u53D1\u9EC4\u7684\u5851\u6599\u7F69\u3001\u90A3\u9053\u88C2\u7F1D\u91CC\u957F\u51FA\u6765\u7684\uFF0C\u672B\u53E5\u4ECD\u7136\u5728\u8BF4\u90A3\u76CF\u706F\u3002\u6700\u89C1\u529F\u529B\u7684\u662F\u7B2C\u4E94\u6B65\u2014\u2014\u7269\u4E1A\u7EDF\u4E00\u6362\u4E0A\u7684\u65B0\u706F\u66F4\u7075\u654F\u4E5F\u66F4\u7701\u7535\uFF0C\u5374\u66FF\u98CE\u5439\u3001\u66FF\u6C34\u7BA1\u54CD\u3001\u66FF\u732B\u8DF3\uFF0C\u6700\u540E\u88AB\u4E00\u697C\u4F4F\u6237\u4E00\u5F20\u7EB8\u9000\u56DE\uFF1B\u4F5C\u8005\u56E0\u6B64\u6709\u673A\u4F1A\u91CD\u65B0\u770B\u5F85\u65E7\u706F\u7684\u300C\u6162\u300D\uFF1A\u6162\u4E0D\u662F\u574F\uFF0C\u662F\u4E00\u79CD\u5206\u8FA8\u3002\u6DF1\u591C\u7AD9\u5728\u90A3\u70B9\u5149\u91CC\u542C\u6E05\u81EA\u5DF1\u7684\u4E24\u58F0\uFF08\u7B2C\u4E00\u4E0B\u662F\u8BD5\u63A2\uFF0C\u7B2C\u4E8C\u4E0B\u624D\u662F\u8BDD\uFF09\uFF0C\u5168\u6587\u843D\u5730\u3002\u672B\u53E5\u300C\u4E8C\u697C\u534A\u5DF2\u7ECF\u9ED1\u4E86\u300D\u628A\u6EE1\u697C\u9053\u7684\u8DFA\u811A\u58F0\u6536\u62E2\u8D77\u6765\uFF0C\u80DC\u8FC7\u4EFB\u4F55\u6292\u60C5\u3002\u4E0D\u8DB3\u6709\u4E24\u5904\uFF1A\u4E00\u662F\u7B2C\u4E94\u6BB5\u5404\u5BB6\u7684\u8DFA\u6CD5\u5199\u6210\u4E86\u6E05\u5355\uFF0C\u53E5\u5F0F\u540C\u6784\uFF1B\u4E8C\u662F\u62A5\u4FEE\u5355\u662F\u8C01\u6495\u7684\u6CA1\u6709\u4EA4\u4EE3\uFF0C\u738B\u53D4\u90A3\u53E5\u529D\u5C11\u4E86\u538B\u529B\uFF0C\u672B\u5C3E\u5E08\u5085\u90A3\u53E5\u8BDD\u4E5F\u6765\u5F97\u7565\u5FEB\uFF0C\u53EF\u5728\u524D\u6587\u5148\u7ED9\u8FD9\u53EA\u624B\u4E00\u4E2A\u52A8\u4F5C\u3002"
      },
      {
        title: "\u8303\u6587\u4E8C\uFF1A\u4E00\u53EA\u7B77\u5B50\u7684\u7528\u5904",
        prompt: "\u9898\u76EE\uFF1A\u300A\u4E00\u53EA\u7B77\u5B50\u7684\u7528\u5904\u300B\uFF08\u4E5F\u53EF\u81EA\u62DF\u9898\u76EE\uFF09\u3002\u60C5\u5883\uFF1A\u5BB6\u91CC\u603B\u6709\u914D\u4E0D\u6210\u5BF9\u3001\u7528\u4E0D\u987A\u624B\u5374\u4E00\u76F4\u7559\u7740\u7684\u5C0F\u4E1C\u897F\u3002\u8981\u6C42\uFF1A\u56F4\u7ED5\u8FD9\u6837\u4E00\u4EF6\u4E1C\u897F\uFF0C\u5199\u6E05\u5B83\u7684\u6765\u5386\u3001\u5B83\u73B0\u5728\u7684\u7528\u5904\uFF0C\u4EE5\u53CA\u4F60\u5BF9\u5B83\u7684\u770B\u6CD5\u7684\u53D8\u5316\uFF0C\u4E0D\u5C11\u4E8E 600 \u5B57\u3002",
        score: "\u4E00\u7C7B\u6587\uFF0850\u201455 \u5206\uFF09",
        text: "\u6211\u5BB6\u7B77\u7B3C\u91CC\u7684\u7B77\u5B50\u6C38\u8FDC\u914D\u4E0D\u9F50\u3002\u6BCF\u4E2A\u6708\u6574\u7406\u4E00\u6B21\uFF0C\u90FD\u80FD\u51D1\u51FA\u5341\u51E0\u53CC\uFF0C\u7B3C\u5E95\u8FD8\u5269\u4E09\u56DB\u53EA\u5355\u7684\uFF0C\u957F\u77ED\u4E0D\u4E00\uFF0C\u50CF\u73ED\u91CC\u7AD9\u7740\u51E0\u4E2A\u6CA1\u6392\u4E0A\u961F\u7684\u5B66\u751F\u3002\n\u5B83\u4EEC\u5404\u6709\u5404\u7684\u6765\u5386\u3002\u6709\u4E00\u6839\u6BD4\u522B\u7684\u77ED\u4E00\u622A\uFF0C\u662F\u5F53\u5E74\u88AB\u6211\u62FF\u53BB\u6311\u7089\u5B50\u4E0A\u7684\u9505\u76D6\u3001\u88AB\u706B\u71CE\u6389\u4E86\u5934\uFF1B\u6709\u4E00\u6839\u989C\u8272\u6700\u6D45\uFF0C\u662F\u4E70\u6302\u9762\u65F6\u5E97\u5BB6\u9001\u7684\u8D60\u54C1\uFF1B\u8FD8\u6709\u4E00\u6839\u4E0A\u5934\u6709\u4E00\u9053\u6D45\u6D45\u7684\u5200\u5370\uFF0C\u662F\u6BCD\u4EB2\u5207\u83DC\u65F6\u6CA1\u6CE8\u610F\uFF0C\u4ECE\u65C1\u8FB9\u5212\u8FC7\u53BB\u7684\u3002\u81F3\u4E8E\u548C\u5B83\u4EEC\u914D\u5BF9\u7684\u90A3\u51E0\u53EA\uFF0C\u6709\u7684\u6298\u65AD\u4E86\uFF0C\u6709\u7684\u88AB\u8C01\u5E26\u53BB\u4E86\u5355\u4F4D\uFF0C\u518D\u6CA1\u56DE\u6765\u3002\n\u6BCD\u4EB2\u8BD5\u8FC7\u7ED9\u5B83\u4EEC\u914D\u5BF9\u3002\u5979\u628A\u90A3\u51E0\u53EA\u5355\u7684\u51D1\u6210\u4E24\u53CC\uFF0C\u70EB\u8FC7\uFF0C\u6446\u4E0A\u684C\u3002\u5939\u83DC\u7684\u65F6\u5019\u4E24\u6839\u7B77\u5B50\u4E0D\u542C\u4F7F\u5524\uFF0C\u957F\u7684\u5F80\u524D\u4F38\uFF0C\u77ED\u7684\u8DDF\u4E0D\u4E0A\uFF0C\u4E00\u7B77\u5B50\u9752\u83DC\u6ED1\u4E0B\u53BB\u6389\u5728\u684C\u4E0A\u3002\u90A3\u5929\u665A\u996D\u5168\u5BB6\u90FD\u7B11\u4E86\uFF0C\u7236\u4EB2\u8BF4\u8FD9\u7B77\u5B50\u6709\u813E\u6C14\u3002\u7B11\u5B8C\uFF0C\u6BCD\u4EB2\u53C8\u628A\u5B83\u4EEC\u62C6\u5F00\uFF0C\u653E\u56DE\u7B77\u7B3C\u3002\n\u540E\u6765\u5B83\u4EEC\u5404\u81EA\u6709\u4E86\u522B\u7684\u5DEE\u4E8B\u3002\u9171\u6CB9\u74F6\u7684\u76D6\u5B50\u65E9\u5C31\u4E22\u4E86\uFF0C\u74F6\u53E3\u4E0A\u63D2\u7740\u4E00\u6839\u7B77\u5B50\u5F53\u585E\u5B50\uFF1B\u9633\u53F0\u90A3\u76C6\u540A\u5170\u7684\u571F\u677F\u7ED3\u4E86\uFF0C\u4E00\u6839\u7B77\u5B50\u5E38\u5E74\u63D2\u5728\u91CC\u9762\u677E\u571F\uFF1B\u53A8\u623F\u7684\u7827\u677F\u8584\uFF0C\u5207\u4E1C\u897F\u65F6\u603B\u6643\uFF0C\u5E95\u4E0B\u57AB\u7740\u4E00\u6839\uFF1B\u7076\u53F0\u8FB9\u8FD8\u6709\u4E00\u6839\uFF0C\u7528\u6765\u6345\u8FC7\u51DD\u4F4F\u7684\u6CB9\u58F6\u5634\u3002\n\u6709\u4E00\u5E74\u5BB6\u91CC\u6362\u8FC7\u4E00\u6574\u5957\u65B0\u7B77\u5B50\uFF0C\u516B\u53EA\uFF0C\u6F06\u662F\u4E00\u6837\u7684\u7EA2\u3002\u7528\u4E86\u4E0D\u5230\u534A\u5E74\uFF0C\u65AD\u4E86\u4E00\u53EA\uFF0C\u5269\u4E0B\u4E03\u53EA\uFF0C\u600E\u4E48\u6446\u90FD\u4E0D\u987A\u773C\uFF0C\u6700\u540E\u4E5F\u56DE\u4E86\u7B77\u7B3C\uFF0C\u8DDF\u65E7\u7684\u6DF7\u5728\u4E00\u8D77\u3002\n\u6211\u66FE\u7ECF\u5ACC\u5B83\u4EEC\u5360\u5730\u65B9\u3002\u8FC7\u5E74\u5927\u626B\u9664\u7684\u65F6\u5019\uFF0C\u6211\u628A\u90A3\u51E0\u53EA\u5355\u7684\u6293\u51FA\u6765\uFF0C\u51C6\u5907\u4E22\u6389\u3002\u6BCD\u4EB2\u6B63\u5728\u64E6\u7827\u677F\uFF0C\u5934\u4E5F\u6CA1\u62AC\uFF0C\u8BF4\uFF1A\u300C\u6254\u4E86\uFF0C\u7827\u677F\u5C31\u6643\u3002\u300D\n\u6211\u4F4E\u5934\u770B\u90A3\u6839\u57AB\u5728\u7827\u677F\u5E95\u4E0B\u7684\u7B77\u5B50\u3002\u5B83\u88AB\u538B\u5F97\u53D1\u4EAE\uFF0C\u4E24\u5934\u90FD\u6709\u6D45\u6D45\u7684\u8C41\u53E3\uFF0C\u50CF\u4E00\u6839\u88AB\u7528\u65E7\u7684\u6241\u62C5\u3002\u6211\u628A\u5B83\u653E\u4E86\u56DE\u53BB\u3002\n\u53BB\u5E74\u79CB\u5929\u8205\u8205\u4E00\u5BB6\u6765\u5403\u996D\uFF0C\u4EBA\u6BD4\u5E73\u65F6\u591A\u4E86\u4E00\u534A\u3002\u684C\u5B50\u662F\u4ECE\u9633\u53F0\u642C\u8FDB\u6765\u7684\u6298\u53E0\u684C\uFF0C\u94FA\u4E86\u4E00\u5757\u65E7\u5E8A\u5355\u5F53\u684C\u5E03\u3002\u6446\u684C\u5B50\u7684\u65F6\u5019\u7B77\u5B50\u4E0D\u591F\uFF0C\u6211\u6253\u5F00\u7B77\u7B3C\uFF0C\u7FFB\u51FA\u90A3\u4E09\u56DB\u53EA\u5355\u7684\uFF0C\u7528\u70ED\u6C34\u70EB\u8FC7\uFF0C\u6446\u4E0A\u684C\u3002\u5B83\u4EEC\u4E0D\u6210\u53CC\uFF0C\u989C\u8272\u4E0D\u4E00\u6837\uFF0C\u6709\u4E00\u5934\u8FD8\u6389\u4E86\u4E00\u5C0F\u5757\u6F06\u3002\u8205\u8205\u5939\u83DC\u65F6\u968F\u624B\u6311\u4E86\u4E24\u6839\uFF0C\u957F\u77ED\u4E0D\u4E00\u6837\uFF0C\u4ED6\u4E3E\u8D77\u6765\u5BF9\u9F50\u4E86\u4E00\u4E0B\uFF0C\u4E5F\u6CA1\u8BF4\u4EC0\u4E48\uFF0C\u5C31\u90A3\u4E48\u5403\u4E86\u4E00\u987F\u996D\u3002\n\u996D\u540E\u6211\u6D17\u7897\uFF0C\u628A\u7B77\u5B50\u4E00\u6839\u6839\u64E6\u5E72\u3002\u8F6E\u5230\u57AB\u7827\u677F\u7684\u90A3\u6839\uFF0C\u6211\u51B2\u6D17\u5E72\u51C0\uFF0C\u987A\u624B\u53C8\u585E\u56DE\u7827\u677F\u5E95\u4E0B\uFF0C\u6309\u4E86\u6309\u53F0\u9762\uFF0C\u4E0D\u6643\u4E86\u3002\n\u8FD9\u4E9B\u7B77\u5B50\u672C\u6765\u90FD\u662F\u7B77\u5B50\u3002\u540E\u6765\u6709\u7684\u77ED\u4E86\uFF0C\u6709\u7684\u6389\u4E86\u8272\uFF0C\u6709\u7684\u8EAB\u8FB9\u90A3\u53EA\u4E0D\u77E5\u53BB\u4E86\u54EA\u91CC\uFF0C\u5B83\u4EEC\u5C31\u4E0D\u518D\u662F\u4E00\u53CC\u4E86\u3002\u4E00\u53CC\u7B77\u5B50\u7684\u4E8B\uFF0C\u662F\u628A\u83DC\u4ECE\u76D8\u5B50\u91CC\u5939\u8D77\u6765\uFF1B\u4E00\u53EA\u7B77\u5B50\u7684\u4E8B\uFF0C\u662F\u9876\u3001\u57AB\u3001\u6345\u3001\u6311\u3002\u5B83\u4EEC\u6CA1\u6709\u574F\uFF0C\u53EA\u662F\u88AB\u53EB\u53BB\u505A\u4E86\u522B\u7684\u4E8B\u3002\n\u591C\u91CC\u6211\u53C8\u8FDB\u53A8\u623F\u5012\u6C34\uFF0C\u987A\u624B\u6309\u4E86\u4E00\u4E0B\u7827\u677F\u3002\u5F88\u7A33\u3002",
        highlights: [
          {
            sentence: "\u6BCF\u4E2A\u6708\u6574\u7406\u4E00\u6B21\uFF0C\u90FD\u80FD\u51D1\u51FA\u5341\u51E0\u53CC\uFF0C\u7B3C\u5E95\u8FD8\u5269\u4E09\u56DB\u53EA\u5355\u7684\uFF0C\u957F\u77ED\u4E0D\u4E00\uFF0C\u50CF\u73ED\u91CC\u7AD9\u7740\u51E0\u4E2A\u6CA1\u6392\u4E0A\u961F\u7684\u5B66\u751F\u3002",
            why: "\u6BD4\u55BB\u7684\u5999\u5904\u4E0D\u5728\u5F62\u4F3C\u800C\u5728\u5904\u5883\u2014\u2014\u300C\u6CA1\u6392\u4E0A\u961F\u300D\u5199\u51FA\u4E86\u5B83\u4EEC\u88AB\u5269\u4E0B\u7684\u72B6\u6001\uFF0C\u8BFB\u8005\u7B2C\u4E00\u6BB5\u5C31\u77E5\u9053\u8FD9\u51E0\u53EA\u7B77\u5B50\u7684\u8EAB\u4EFD\uFF1B\u4E5F\u4E3A\u672B\u6BB5\u300C\u88AB\u53EB\u53BB\u505A\u4E86\u522B\u7684\u4E8B\u300D\u57CB\u597D\u4E86\u5BF9\u7167\u3002"
          },
          {
            sentence: "\u5939\u83DC\u7684\u65F6\u5019\u4E24\u6839\u7B77\u5B50\u4E0D\u542C\u4F7F\u5524\uFF0C\u957F\u7684\u5F80\u524D\u4F38\uFF0C\u77ED\u7684\u8DDF\u4E0D\u4E0A\uFF0C\u4E00\u7B77\u5B50\u9752\u83DC\u6ED1\u4E0B\u53BB\u6389\u5728\u684C\u4E0A\u3002",
            why: "\u628A\u300C\u4E0D\u6210\u53CC\u300D\u7684\u540E\u679C\u5199\u6210\u4E00\u6B21\u5177\u4F53\u7684\u5931\u8D25\u52A8\u4F5C\uFF0C\u524D\u6709\u300C\u957F\u7684\u5F80\u524D\u4F38\uFF0C\u77ED\u7684\u8DDF\u4E0D\u4E0A\u300D\u7684\u5BF9\u4E3E\uFF0C\u540E\u6709\u9752\u83DC\u6ED1\u843D\u7684\u7ED3\u679C\uFF0C\u6BD4\u5199\u300C\u5F88\u4E0D\u65B9\u4FBF\u300D\u6709\u6548\u5F97\u591A\uFF1B\u7D27\u63A5\u7740\u4E00\u5BB6\u4EBA\u7B11\uFF0C\u8BED\u6C14\u8F7B\uFF0C\u53CD\u800C\u8BA9\u540E\u9762\u6BCD\u4EB2\u7684\u5904\u7F6E\u663E\u5F97\u8BA4\u771F\u3002"
          },
          {
            sentence: "\u5B83\u88AB\u538B\u5F97\u53D1\u4EAE\uFF0C\u4E24\u5934\u90FD\u6709\u6D45\u6D45\u7684\u8C41\u53E3\uFF0C\u50CF\u4E00\u6839\u88AB\u7528\u65E7\u7684\u6241\u62C5\u3002",
            why: "\u4E0E\u524D\u4E00\u7BC7\u540C\u6CD5\uFF1A\u7528\u78E8\u635F\u4EE3\u66FF\u53D9\u8FF0\u3002\u300C\u53D1\u4EAE\u300D\u662F\u538B\u51FA\u6765\u7684\uFF0C\u300C\u8C41\u53E3\u300D\u662F\u5207\u51FA\u6765\u7684\uFF0C\u4E24\u5904\u75D5\u8FF9\u5C31\u4EA4\u4EE3\u4E86\u5B83\u57AB\u4E86\u591A\u5C11\u5E74\u7827\u677F\uFF1B\u6BD4\u4F5C\u6241\u62C5\uFF0C\u662F\u628A\u4E00\u53EA\u7B77\u5B50\u7684\u8EAB\u4EFD\u5F80\u4E0A\u63D0\uFF0C\u4E3A\u672B\u6BB5\u300C\u6362\u4E86\u5DEE\u4E8B\u300D\u57CB\u4E0B\u4F0F\u7B14\u3002"
          },
          {
            sentence: "\u4E00\u53CC\u7B77\u5B50\u7684\u4E8B\uFF0C\u662F\u628A\u83DC\u4ECE\u76D8\u5B50\u91CC\u5939\u8D77\u6765\uFF1B\u4E00\u53EA\u7B77\u5B50\u7684\u4E8B\uFF0C\u662F\u9876\u3001\u57AB\u3001\u6345\u3001\u6311\u3002",
            why: "\u5168\u7BC7\u8BA4\u8BC6\u7684\u843D\u70B9\u3002\u7528\u5BF9\u4E3E\u53E5\u5F0F\u52A0\u56DB\u4E2A\u5355\u5B57\u52A8\u8BCD\uFF0C\u8BF4\u5F97\u5E72\u8106\u800C\u4E14\u4ECD\u7136\u5728\u8BF4\u7269\uFF1B\u8FD9\u662F\u300C\u4E0D\u8BF4\u6559\u300D\u7684\u6B63\u9762\u793A\u8303\u2014\u2014\u9053\u7406\u5B8C\u5168\u53EF\u4EE5\u7528\u53A8\u623F\u7684\u8BED\u8A00\u8BB2\u51FA\u6765\uFF0C\u4E0D\u5FC5\u7528\u300C\u4EBA\u751F\u300D\u4E24\u4E2A\u5B57\u3002"
          },
          {
            sentence: "\u6211\u51B2\u6D17\u5E72\u51C0\uFF0C\u987A\u624B\u53C8\u585E\u56DE\u7827\u677F\u5E95\u4E0B\uFF0C\u6309\u4E86\u6309\u53F0\u9762\uFF0C\u4E0D\u6643\u4E86\u3002",
            why: "\u7528\u4E00\u4E2A\u52A8\u4F5C\u9A8C\u8BC1\u8BA4\u8BC6\uFF1A\u4ED6\u6CA1\u6709\u8BF4\u300C\u6211\u8981\u73CD\u60DC\u5B83\u4EEC\u300D\uFF0C\u53EA\u628A\u7B77\u5B50\u5F52\u4F4D\u3001\u6309\u4E00\u4E0B\u53F0\u9762\u3002\u300C\u987A\u624B\u300D\u4E0E\u5168\u6587\u5176\u4ED6\u4E09\u5904\u7167\u5E94\uFF0C\u4EBA\u7269\u7684\u6001\u5EA6\u5C31\u53D8\u5728\u8FD9\u4E00\u4E0B\u91CC\u3002"
          }
        ],
        review: [
          {
            aspect: "\u5BA1\u9898\u7ACB\u610F",
            text: "\u9898\u76EE\u95EE\u300C\u7528\u5904\u300D\uFF0C\u5168\u6587\u5C31\u8001\u8001\u5B9E\u5B9E\u56DE\u7B54\u7528\u5904\uFF1A\u5835\u3001\u677E\u3001\u57AB\u3001\u6345\uFF0C\u56DB\u4E2A\u5177\u4F53\u5DEE\u4E8B\u6491\u8D77\u4E86\u7ACB\u610F\u3002\u4F5C\u8005\u6CA1\u6709\u628A\u5B83\u5199\u6210\u300C\u6B8B\u7F3A\u4E5F\u5F88\u7F8E\u300D\u7684\u7A7A\u8BDD\uFF0C\u4E5F\u6CA1\u6709\u501F\u7B77\u5B50\u611F\u6168\u4EBA\u751F\uFF0C\u8BA4\u8BC6\u843D\u5728\u300C\u7528\u5904\u6362\u4E86\uFF0C\u4E0D\u662F\u6CA1\u4E86\u300D\uFF0C\u662F\u751F\u6D3B\u54F2\u7406\u7C7B\u91CC\u6700\u96BE\u5199\u5BF9\u7684\u4E00\u6761\u7EBF\u3002"
          },
          {
            aspect: "\u7ED3\u6784\u5E03\u5C40",
            text: "\u516D\u6B65\u63A8\u8FDB\uFF1A\u6446\u73B0\u8C61\u2014\u4EA4\u4EE3\u6765\u5386\u2014\u4E00\u6B21\u5931\u8D25\u7684\u914D\u7528\u2014\u65B0\u7684\u5B89\u7F6E\u2014\u5DEE\u70B9\u88AB\u6254\u6389\u2014\u4E00\u6B21\u6B63\u7ECF\u7684\u767B\u573A\uFF0C\u6700\u540E\u56DE\u5230\u53A8\u623F\u3002\u5176\u4E2D\u300C\u5DEE\u70B9\u88AB\u6254\u6389\u300D\u662F\u5168\u6587\u552F\u4E00\u6709\u51B2\u7A81\u7684\u73AF\u8282\uFF0C\u4F4D\u7F6E\u6070\u597D\u5728\u4E09\u5206\u4E4B\u4E8C\u5904\uFF0C\u907F\u514D\u4E86\u901A\u7BC7\u5E73\u94FA\uFF1B\u672B\u6BB5\u6309\u7827\u677F\u4E0E\u524D\u6587\u57AB\u7827\u677F\u547C\u5E94\uFF0C\u6536\u5F97\u4F4F\u3002"
          },
          {
            aspect: "\u8BED\u8A00\u8868\u8FBE",
            text: "\u5BB6\u5E38\u8BED\u611F\uFF0C\u77ED\u53E5\u4E3A\u4E3B\uFF0C\u52A8\u4F5C\u8BCD\u7528\u5F97\u51C6\uFF08\u9876\u3001\u57AB\u3001\u6345\u3001\u6311\u3001\u6309\uFF09\uFF1B\u300C\u88AB\u706B\u71CE\u6389\u4E86\u5934\u300D\u300C\u6709\u813E\u6C14\u300D\u300C\u677F\u7ED3\u300D\u8FD9\u7C7B\u8BCD\u6709\u751F\u6D3B\u5473\u3002\u6BCD\u4EB2\u4E00\u53E5\u300C\u6254\u4E86\uFF0C\u7827\u677F\u5C31\u6643\u300D\u662F\u5168\u6587\u8BED\u611F\u6700\u597D\u7684\u4E00\u53E5\uFF1A\u4E0D\u89E3\u91CA\u3001\u4E0D\u8BAD\u4EBA\uFF0C\u53EA\u8BF4\u540E\u679C\u3002"
          },
          {
            aspect: "\u7D20\u6750\u8FD0\u7528",
            text: "\u4E00\u53EA\u7B77\u5B50\u7684\u4E09\u79CD\u6765\u5386\uFF08\u88AB\u706B\u71CE\u3001\u5E97\u5BB6\u8D60\u54C1\u3001\u88AB\u5200\u5212\u8FC7\uFF09\u5404\u914D\u4E00\u53E5\u8BDD\uFF0C\u65E2\u8BF4\u660E\u5B83\u4EEC\u4E3A\u4EC0\u4E48\u914D\u4E0D\u6210\u5BF9\uFF0C\u53C8\u987A\u624B\u5199\u51FA\u4E00\u5BB6\u4EBA\u7684\u65E5\u5E38\uFF1B\u300C\u8D60\u54C1\u300D\u8FD9\u4E00\u7B14\u5C24\u5176\u597D\uFF0C\u5B83\u8BA9\u7B77\u5B50\u7684\u300C\u591A\u4F59\u300D\u6709\u793E\u4F1A\u6765\u5904\uFF0C\u4E0D\u53EA\u662F\u5BB6\u91CC\u7684\u6742\u7269\u3002"
          },
          {
            aspect: "\u5347\u683C\u5EFA\u8BAE",
            text: "\u7B2C\u56DB\u6BB5\u662F\u7EAF\u7F57\u5217\uFF0C\u56DB\u4E2A\u5206\u53E5\u53E5\u5F0F\u76F8\u540C\uFF0C\u4E0E\u524D\u6587\u7684\u6BD4\u55BB\u7B14\u6CD5\u4E0D\u7EDF\u4E00\uFF0C\u5EFA\u8BAE\u53EA\u7559\u4E09\u4EF6\u5E76\u628A\u4E00\u4EF6\u5199\u7EC6\uFF08\u5982\u5199\u57AB\u7827\u677F\u90A3\u6839\u600E\u6837\u88AB\u538B\u51FA\u4E24\u5934\u8C41\u53E3\uFF09\uFF1B\u672B\u6BB5\u8BAE\u8BBA\u8FDE\u8BF4\u4E09\u53E5\uFF0C\u7B2C\u4E8C\u53E5\u300C\u5B83\u4EEC\u6CA1\u6709\u574F\u300D\u5DF2\u8BF4\u5230\u70B9\u4E0A\uFF0C\u300C\u53EA\u662F\u88AB\u53EB\u53BB\u505A\u4E86\u522B\u7684\u4E8B\u300D\u4E0E\u524D\u53E5\u610F\u601D\u91CD\u53E0\uFF0C\u5220\u6389\u4E00\u53E5\u53CD\u800C\u66F4\u6709\u529B\u3002"
          }
        ],
        comment: "\u8FD9\u7BC7\u7684\u9009\u6750\u5728\u53A8\u623F\u91CC\uFF0C\u8BA4\u8BC6\u4E5F\u957F\u5728\u53A8\u623F\u91CC\u3002\u5B83\u907F\u5F00\u4E86\u8FD9\u4E00\u9898\u6700\u5BB9\u6613\u8E29\u7684\u4E24\u4E2A\u5751\uFF1A\u4E00\u662F\u628A\u6B8B\u7F3A\u5199\u6210\u7F8E\uFF08\u300C\u6B8B\u7F3A\u4E5F\u662F\u4E00\u79CD\u7F8E\u300D\u8FD9\u7C7B\u53E5\u5B50\u4E00\u51FA\u73B0\uFF0C\u6587\u7AE0\u5C31\u7A7A\u4E86\uFF09\uFF0C\u4E8C\u662F\u501F\u7269\u611F\u6168\u4EBA\u751F\uFF08\u4E00\u5199\u300C\u4EBA\u751F\u5982\u7B77\u300D\u5C31\u6563\u4E86\uFF09\u3002\u4F5C\u8005\u7684\u529E\u6CD5\u662F\u53EA\u56DE\u7B54\u9898\u76EE\u95EE\u7684\u300C\u7528\u5904\u300D\uFF1A\u4E00\u53EA\u7B77\u5B50\u73B0\u5728\u7684\u5DEE\u4E8B\u662F\u9876\u3001\u57AB\u3001\u6345\u3001\u6311\uFF0C\u7528\u5904\u7684\u8F6C\u79FB\u5C31\u662F\u5168\u6587\u7684\u7B54\u6848\u3002\u6BCD\u4EB2\u90A3\u53E5\u300C\u6254\u4E86\uFF0C\u7827\u677F\u5C31\u6643\u300D\u662F\u5B9A\u76D8\u661F\uFF0C\u4E00\u53E5\u5BB6\u52A1\u5E38\u8BC6\u628A\u7269\u7684\u4EF7\u503C\u9489\u6B7B\uFF0C\u6BD4\u4EFB\u4F55\u8BAE\u8BBA\u90FD\u786C\uFF1B\u7ED3\u5C3E\u6309\u4E00\u4E0B\u7827\u677F\u7684\u52A8\u4F5C\uFF0C\u4E0E\u5168\u6587\u4E09\u5904\u300C\u987A\u624B\u300D\u7167\u5E94\uFF0C\u6001\u5EA6\u5C31\u53D8\u5728\u8FD9\u4E00\u4E0B\u91CC\u3002\u4E0D\u8DB3\u662F\u7B2C\u56DB\u6BB5\u7F57\u5217\u53E5\u5F0F\u540C\u6784\uFF0C\u8BFB\u8D77\u6765\u50CF\u6E05\u5355\uFF0C\u4E0E\u524D\u6587\u7684\u6BD4\u55BB\u7B14\u6CD5\u4E0D\u7EDF\u4E00\uFF1B\u7ED3\u5C3E\u4E00\u6BB5\u7684\u8BAE\u8BBA\u8BF4\u4E86\u4E09\u53E5\uFF0C\u6700\u540E\u4E00\u53E5\u4E0E\u524D\u53E5\u91CD\u590D\uFF0C\u82E5\u80FD\u5220\u5230\u4E24\u53E5\uFF0C\u8FD9\u7BC7\u7684\u7ED3\u5C3E\u4F1A\u548C\u8303\u6587\u4E00\u4E00\u6837\u5E72\u51C0\u3002"
      }
    ],
    exercise: {
      prompt: "\u4ECE\u4E24\u7BC7\u91CC\u6311\u4E00\u7BC7\uFF0C\u628A\u5B83\u300C\u4EAE\u6BDB\u75C5\uFF08\u6216\u4EAE\u73B0\u8C61\uFF09\u2014\u4EA4\u4EE3\u6765\u5386\u2014\u4E00\u6B21\u5931\u8D25\u7684\u5904\u7F6E\uFF08\u60F3\u4FEE\u597D\u3001\u60F3\u914D\u5BF9\u3001\u60F3\u6362\u6389\u3001\u60F3\u62A5\u4FEE\u90FD\u7B97\uFF09\u2014\u8BA4\u8BC6\u6539\u53D8\u300D\u8FD9\u51E0\u6B65\u62C6\u51FA\u6765\uFF0C\u5957\u7528\u5230\u4F60\u81EA\u5DF1\u5BB6\u91CC\u4E00\u4EF6\u7528\u65E7\u7684\u5C0F\u4E1C\u897F\u4E0A\uFF08\u4E00\u628A\u83DC\u5200\u3001\u4E00\u53EA\u5E26\u7F3A\u53E3\u7684\u7897\u3001\u4E00\u4E2A\u6389\u6F06\u7684\u6C34\u58F6\u3001\u4E00\u53EA\u603B\u4E5F\u62E7\u4E0D\u7D27\u7684\u6C34\u9F99\u5934\u2026\u2026\uFF09\uFF0C\u5199\u4E00\u7BC7 600 \u5B57\u4EE5\u4E0A\u7684\u8BB0\u53D9\u6587\uFF0C\u8981\u6C42\u5728\u7ED3\u5C3E\u53EA\u628A\u8BA4\u8BC6\u8BF4\u51FA\u6765\uFF0C\u4E0D\u5199\u300C\u6211\u660E\u767D\u4E86\u300D\u7C7B\u603B\u7ED3\u53E5\u3002",
      tips: [
        "\u5148\u7ED9\u8FD9\u4EF6\u4E1C\u897F\u627E\u51FA\u4E00\u4E2A\u53EF\u4EE5\u6D4B\u91CF\u7684\u6BDB\u75C5\u6216\u7F3A\u53E3\uFF08\u5C3A\u5BF8\u3001\u88C2\u53E3\u3001\u78E8\u635F\u3001\u4F4D\u7F6E\u504F\u5DEE\uFF09\uFF0C\u4E0D\u8981\u4E00\u4E0A\u6765\u5C31\u628A\u5B83\u5F53\u8C61\u5F81\u7528\u3002",
        "\u81F3\u5C11\u5B89\u6392\u4E00\u6B21\u300C\u5931\u8D25\u7684\u5C1D\u8BD5\u300D\uFF1A\u60F3\u4FEE\u597D\u5B83\u3001\u60F3\u7ED9\u5B83\u914D\u5BF9\u3001\u60F3\u6362\u6389\u5B83\u3001\u60F3\u62A5\u4FEE\u90FD\u884C\uFF0C\u8BA9\u300C\u4FEE\u4E0D\u597D\u300D\u300C\u7528\u4E0D\u4E0A\u300D\u6216\u8005\u300C\u6362\u6765\u7684\u66F4\u96BE\u7528\u300D\u6210\u4E3A\u4E00\u4EF6\u53D1\u751F\u8FC7\u7684\u4E8B\u3002",
        "\u628A\u65F6\u95F4\u4EA4\u7ED9\u78E8\u635F\u53BB\u8BF4\uFF1A\u5199\u6389\u6F06\u3001\u8C41\u53E3\u3001\u78E8\u4EAE\u7684\u4E00\u6BB5\u3001\u88AB\u538B\u6241\u7684\u4E00\u89D2\uFF0C\u4E0D\u5199\u300C\u65E5\u5B50\u4E00\u5929\u5929\u8FC7\u53BB\u300D\u3002",
        "\u7ED3\u5C3E\u53EA\u505A\u4E24\u4EF6\u4E8B\u2014\u2014\u4E00\u53E5\u5E73\u76F4\u7684\u8BA4\u8BC6\uFF08\u6700\u597D\u4ECD\u7528\u8FD9\u4EF6\u4E1C\u897F\u81EA\u5DF1\u7684\u8BED\u8A00\u8BF4\uFF09\u52A0\u4E00\u4E2A\u524D\u6587\u51FA\u73B0\u8FC7\u7684\u52A8\u4F5C\uFF0C\u4E0D\u8981\u52A0\u300C\u6211\u61C2\u5F97\u4E86\u4EBA\u751F\u7684\u9053\u7406\u300D\u3002"
      ]
    }
  }
];

