        answer: "B",
        explanation: "\u300A\u9A86\u9A7C\u7965\u5B50\u300B\u7684\u4F5C\u8005\u662F\u8001\u820D\uFF0C\u539F\u540D\u8212\u5E86\u6625\uFF0C\u5B57\u820D\u4E88\uFF0C\u6EE1\u65CF\uFF0C\u5317\u4EAC\u4EBA\uFF0C\u88AB\u8A89\u4E3A\u201C\u4EBA\u6C11\u827A\u672F\u5BB6\u201D\u3002",
        difficulty: 1,
        tags: ["\u9A86\u9A7C\u7965\u5B50", "\u4F5C\u8005\u5E38\u8BC6"]
