        stem: "\u300A\u6D77\u5E95\u4E24\u4E07\u91CC\u300B\u4E2D\uFF0C\u5C3C\u6469\u8239\u957F\u9A7E\u9A76\u7684\u6F5C\u8247\u540D\u53EB\u201C____\u53F7\u201D\u3002",
