        stem: "\u4E0B\u5217\u5173\u4E8E\u300A\u6D77\u5E95\u4E24\u4E07\u91CC\u300B\u7684\u8868\u8FF0\uFF0C\u4E0D\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
