        type: "fill",
        stem: "\u6CD5\u5E03\u5C14\u901A\u8FC7\u89C2\u5BDF\uFF0C\u63A8\u7FFB\u4E86\u5BD3\u8A00\u4E2D\u201C\u8749\u5411____\u4E5E\u98DF\u201D\u7684\u9519\u8BEF\u8BF4\u6CD5\uFF0C\u4E3A\u8749\u7FFB\u4E86\u6848\u3002",
        answer: "\u8682\u8681|\u8681",
