        type: "choice",
        stem: "\u4E0B\u5217\u5173\u4E8E\u300A\u6606\u866B\u8BB0\u300B\u7684\u8868\u8FF0\uFF0C\u4E0D\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
        options: ["\u4F5C\u54C1\u4E3B\u8981\u4F9D\u9760\u5B9E\u9A8C\u5BA4\u89E3\u5256\u6765\u7814\u7A76\u6606\u866B", "\u6CD5\u5E03\u5C14\u5E38\u7528\u62DF\u4EBA\u624B\u6CD5\u63CF\u5199\u6606\u866B", "\u4E66\u4E2D\u8BB0\u8FF0\u4E86\u677E\u6BDB\u866B\u5217\u961F\u884C\u8FDB\u7684\u73B0\u8C61", "\u300A\u6606\u866B\u8BB0\u300B\u88AB\u8A89\u4E3A\u201C\u6606\u866B\u7684\u53F2\u8BD7\u201D"],
        answer: "A",
        explanation: "\u6CD5\u5E03\u5C14\u575A\u6301\u5728\u81EA\u7136\u73AF\u5883\u4E2D\u957F\u671F\u5B9E\u5730\u89C2\u5BDF\u5E76\u4EB2\u624B\u505A\u5B9E\u9A8C\uFF0C\u53CD\u5BF9\u53EA\u51ED\u89E3\u5256\u548C\u63A8\u7406\u4E0B\u7ED3\u8BBA\uFF0CA\u9879\u8BF4\u6CD5\u4E0E\u539F\u8457\u4E0D\u7B26\u3002",
