        type: "fill",
        stem: "\u8BB0\u53D9\u6587\u7684\u516D\u8981\u7D20\u662F\u65F6\u95F4\u3001\u5730\u70B9\u3001\u4EBA\u7269\uFF0C\u4E8B\u4EF6\u7684\u8D77\u56E0\u3001\u7ECF\u8FC7\u548C____\u3002",
        answer: "\u7ED3\u679C",
        explanation: "\u8BB0\u53D9\u6587\u516D\u8981\u7D20\u4E3A\u65F6\u95F4\u3001\u5730\u70B9\u3001\u4EBA\u7269\uFF0C\u4E8B\u4EF6\u7684\u8D77\u56E0\u3001\u7ECF\u8FC7\u3001\u7ED3\u679C\u3002",
        difficulty: 1,
        tags: ["\u6587\u5B66\u4F53\u88C1", "\u8BB0\u53D9\u6587\u5E38\u8BC6"]
