        type: "choice",
        stem: "\u4E0B\u5217\u4E0D\u5C5E\u4E8E\u8BF4\u660E\u65B9\u6CD5\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
        options: ["\u5217\u6570\u5B57", "\u6253\u6BD4\u65B9", "\u6BD4\u55BB\u8BBA\u8BC1", "\u4F5C\u6BD4\u8F83"],
        answer: "C",
        explanation: "\u201C\u6BD4\u55BB\u8BBA\u8BC1\u201D\u662F\u8BAE\u8BBA\u6587\u7684\u8BBA\u8BC1\u65B9\u6CD5\uFF0C\u800C\u201C\u6253\u6BD4\u65B9\u201D\u624D\u662F\u8BF4\u660E\u65B9\u6CD5\uFF0C\u4E8C\u8005\u4E0D\u53EF\u6DF7\u6DC6\u3002",
