        type: "fill",
        stem: "\u6BBF\u8BD5\u4E00\u7532\u7B2C\u4E00\u540D\u79F0\u4E3A____\uFF0C\u7B2C\u4E8C\u540D\u79F0\u4E3A\u699C\u773C\uFF0C\u7B2C\u4E09\u540D\u79F0\u63A2\u82B1\u3002",
        answer: "\u72B6\u5143",
        explanation: "\u6BBF\u8BD5\u5206\u4E09\u7532\u5F55\u53D6\uFF0C\u4E00\u7532\u53EA\u53D6\u4E09\u540D\uFF0C\u4F9D\u6B21\u4E3A\u72B6\u5143\u3001\u699C\u773C\u3001\u63A2\u82B1\uFF0C\u8D50\u201C\u8FDB\u58EB\u53CA\u7B2C\u201D\u3002",
        difficulty: 1,
