      "\u5E38\u89C1\u656C\u79F0\uFF1A\u79F0\u5BF9\u65B9\u7684\u7236\u4EB2\u4E3A\u201C\u4EE4\u5C0A\u201D\u201C\u5C0A\u541B\u201D\uFF0C\u6BCD\u4EB2\u4E3A\u201C\u4EE4\u5802\u201D\uFF1B\u79F0\u5BF9\u65B9\u7684\u513F\u5B50\u4E3A\u201C\u4EE4\u90CE\u201D\uFF0C\u5973\u513F\u4E3A\u201C\u4EE4\u7231\u201D\uFF1B\u79F0\u5BF9\u65B9\u7684\u59BB\u5B50\u4E3A\u201C\u5C0A\u592B\u4EBA\u201D\uFF1B\u79F0\u547C\u5BF9\u65B9\u672C\u4EBA\u7528\u201C\u8DB3\u4E0B\u201D\u201C\u9601\u4E0B\u201D\u201C\u541B\u201D\u201C\u5B50\u201D\u201C\u516C\u201D\u201C\u5148\u751F\u201D\uFF1B\u79F0\u5BF9\u65B9\u7684\u4F4F\u5904\u4E3A\u201C\u8D35\u5E9C\u201D\u201C\u5C0A\u5E9C\u201D\uFF1B\u95EE\u5BF9\u65B9\u5E74\u9F84\u7528\u201C\u8D35\u5E9A\u201D\uFF0C\u95EE\u8001\u4EBA\u5E74\u9F84\u7528\u201C\u9AD8\u5BFF\u201D\u3002\u6B64\u5916\u201C\u8D50\u6559\u201D\u201C\u60E0\u987E\u201D\u201C\u5782\u8BE2\u201D\u201C\u5149\u4E34\u201D\u4E2D\u7684\u201C\u8D50\u201D\u201C\u60E0\u201D\u201C\u5782\u201D\u201C\u5149\u201D\u90FD\u8868\u793A\u5BF9\u65B9\u7684\u884C\u4E3A\u4F7F\u81EA\u5DF1\u53D7\u76CA\u3002",
      "\u5E38\u89C1\u8C26\u79F0\uFF1A\u79F0\u81EA\u5DF1\u7684\u7236\u4EB2\u4E3A\u201C\u5BB6\u7236\u201D\u201C\u5BB6\u4E25\u201D\uFF0C\u6BCD\u4EB2\u4E3A\u201C\u5BB6\u6BCD\u201D\u201C\u5BB6\u6148\u201D\uFF1B\u79F0\u81EA\u5DF1\u7684\u5F1F\u5F1F\u4E3A\u201C\u820D\u5F1F\u201D\uFF0C\u59B9\u59B9\u4E3A\u201C\u820D\u59B9\u201D\uFF1B\u79F0\u81EA\u5DF1\u7684\u513F\u5B50\u4E3A\u201C\u72AC\u5B50\u201D\uFF0C\u5973\u513F\u4E3A\u201C\u5C0F\u5973\u201D\uFF1B\u79F0\u81EA\u5DF1\u7684\u59BB\u5B50\u4E3A\u201C\u62D9\u8346\u201D\u201C\u5185\u4EBA\u201D\uFF1B\u79F0\u547C\u81EA\u5DF1\u7528\u201C\u611A\u201D\u201C\u9119\u4EBA\u201D\u201C\u4E0D\u624D\u201D\u201C\u665A\u751F\u201D\u201C\u4EC6\u201D\uFF0C\u5BF9\u541B\u738B\u5219\u81EA\u79F0\u201C\u81E3\u201D\u201C\u5FAE\u81E3\u201D\u3002\u201C\u5BD2\u820D\u201D\u201C\u655D\u6821\u201D\u201C\u62D9\u4F5C\u201D\u201C\u611A\u89C1\u201D\u201C\u7A83\u4EE5\u4E3A\u201D\u4E5F\u5C5E\u8C26\u8F9E\u3002",
