      "\u300A\u5317\u51A5\u6709\u9C7C\u300B\u8282\u9009\u81EA\u300A\u5E84\u5B50\xB7\u900D\u9065\u6E38\u300B\uFF0C\u662F\u516B\u5E74\u7EA7\u4E0B\u518C\u8BFE\u6587\uFF0C\u5199\u9CB2\u5316\u4E3A\u9E4F\u3001\u9E4F\u5F99\u5357\u51A5\u7684\u5947\u5E7B\u666F\u8C61\u3002",
      "\u540D\u53E5\uFF1A\u201C\u6012\u800C\u98DE\uFF0C\u5176\u7FFC\u82E5\u5782\u5929\u4E4B\u4E91\u201D\u201C\u6C34\u51FB\u4E09\u5343\u91CC\uFF0C\u629F\u6276\u6447\u800C\u4E0A\u8005\u4E5D\u4E07\u91CC\u201D\uFF0C\u4EE5\u5938\u5F20\u4E0E\u60F3\u8C61\u5199\u51FA\u9E4F\u4E4B\u5927\u4E0E\u98DE\u4E4B\u9AD8\u3002",
