        stem: "\u300A\u867D\u6709\u5609\u80B4\u300B\u4E2D\u201C\u662F\u6545\u5B66\u7136\u540E\u77E5\u4E0D\u8DB3\uFF0C____\u201D\u4E24\u53E5\u8BF4\u660E\u5B66\u4E60\u4E0E\u6559\u5B66\u80FD\u8BA9\u4EBA\u53D1\u73B0\u81EA\u5DF1\u7684\u6B20\u7F3A\uFF0C\u4ECE\u800C\u81EA\u6211\u53CD\u7701\u3001\u81EA\u6211\u52C9\u52B1\u3002",
