      "\u300A\u7A7F\u4E95\u5F97\u4E00\u4EBA\u300B\u540D\u53E5\uFF1A\u201C\u5F97\u4E00\u4EBA\u4E4B\u4F7F\uFF0C\u975E\u5F97\u4E00\u4EBA\u4E8E\u4E95\u4E2D\u4E5F\u3002\u201D\u201C\u6C42\u95FB\u4E4B\u82E5\u6B64\uFF0C\u4E0D\u82E5\u65E0\u95FB\u4E5F\u3002\u201D",
      "\u300A\u7A7F\u4E95\u5F97\u4E00\u4EBA\u300B\u7684\u5BD3\u610F\u662F\uFF1A\u5BF9\u4F20\u95FB\u8981\u5B9E\u5730\u8003\u5BDF\u3001\u67E5\u9A8C\u771F\u4F2A\uFF0C\u4E0D\u53EF\u8F7B\u4FE1\uFF0C\u66F4\u4E0D\u80FD\u4EE5\u8BB9\u4F20\u8BB9\u3002",
      "\u300A\u5415\u6C0F\u6625\u79CB\u300B\u4E2D\u300A\u672C\u5473\u300B\u7BC7\u8BB0\u4F2F\u7259\u9F13\u7434\u3001\u949F\u5B50\u671F\u542C\u97F3\u7684\u6545\u4E8B\uFF0C\u662F\u6210\u8BED\u201C\u9AD8\u5C71\u6D41\u6C34\u201D\u4E0E\u201C\u77E5\u97F3\u201D\u4E00\u8BCD\u7684\u51FA\u5904\u3002",
      "\u6613\u9519\u70B9\uFF1A\u300A\u5415\u6C0F\u6625\u79CB\u300B\u4E0D\u662F\u5415\u4E0D\u97E6\u4E00\u4E2A\u4EBA\u7684\u8457\u4F5C\uFF0C\u800C\u662F\u4ED6\u7EC4\u7EC7\u95E8\u5BA2\u96C6\u4F53\u7F16\u5199\uFF1B\u5185\u5BB9\u517C\u91C7\u5404\u5BB6\uFF0C\u6545\u5F52\u5165\u6742\u5BB6\u800C\u975E\u5112\u5BB6\u6216\u6CD5\u5BB6\u3002"
