        type: "choice",
        stem: "\u300A\u7B54\u8C22\u4E2D\u4E66\u4E66\u300B\u9898\u76EE\u4E2D\u7B2C\u4E8C\u4E2A\u201C\u4E66\u201D\u7684\u610F\u601D\u662F\uFF08\u3000\u3000\uFF09",
