        type: "choice",
        stem: "\u201C\u6653\u96FE\u5C06\u6B47\uFF0C\u733F\u9E1F\u4E71\u9E23\uFF1B\u5915\u65E5\u6B32\u9893\uFF0C\u6C89\u9CDE\u7ADE\u8DC3\u201D\u4E2D\u201C\u6B47\u201D\u4E0E\u201C\u9893\u201D\u7684\u610F\u601D\u5206\u522B\u662F\uFF08\u3000\u3000\uFF09",
        options: ["\u4F11\u606F\uFF1B\u9893\u5E9F", "\u6D88\u6563\uFF1B\u5760\u843D", "\u505C\u6B62\uFF1B\u5012\u584C", "\u6D88\u5931\uFF1B\u8870\u8001"],
        answer: "B",
        explanation: "\u201C\u6B47\u201D\u6307\u6668\u96FE\u5C06\u8981\u6D88\u6563\uFF0C\u201C\u9893\u201D\u6307\u5915\u9633\u5C06\u8981\u5760\u843D\u3002\u4E24\u53E5\u4E00\u5199\u6668\u3001\u4E00\u5199\u5915\uFF0C\u4ECE\u89C6\u89C9\u4E0E\u542C\u89C9\u4E24\u9762\u5199\u51FA\u5C71\u5DDD\u7684\u52C3\u52C3\u751F\u673A\uFF0C\u4E0E\u201C\u4E24\u5CB8\u77F3\u58C1\uFF0C\u4E94\u8272\u4EA4\u8F89\u201D\u540C\u4E3A\u5199\u666F\u7684\u7CBE\u5F69\u4E4B\u7B14\u3002",
