    title: "\u6768\u4E07\u91CC\u2014\u2014\u5357\u5B8B\u201C\u4E2D\u5174\u56DB\u5927\u8BD7\u4EBA\u201D\u4E0E\u201C\u8BDA\u658B\u4F53\u201D\u7684\u521B\u59CB\u4EBA",
    content: [
      "\u6768\u4E07\u91CC\uFF081127\u20141206\uFF09\uFF0C\u5B57\u5EF7\u79C0\uFF0C\u53F7\u8BDA\u658B\uFF0C\u5409\u5DDE\u5409\u6C34\uFF08\u4ECA\u6C5F\u897F\u5409\u6C34\uFF09\u4EBA\uFF0C\u5357\u5B8B\u8BD7\u4EBA\uFF0C\u4E0E\u9646\u6E38\u3001\u8303\u6210\u5927\u3001\u5C24\u88A4\u5E76\u79F0\u201C\u4E2D\u5174\u56DB\u5927\u8BD7\u4EBA\u201D\u3002",
      "\u751F\u5E73\u7ECF\u5386\uFF1A\u7ECD\u5174\u4E8C\u5341\u56DB\u5E74\u8003\u4E2D\u8FDB\u58EB\uFF0C\u6B64\u540E\u5386\u4EFB\u96F6\u9675\u4E1E\u3001\u592A\u5E38\u535A\u58EB\u3001\u5E7F\u4E1C\u63D0\u4E3E\u7B49\u804C\uFF0C\u5B98\u81F3\u5B9D\u8C1F\u9601\u76F4\u5B66\u58EB\uFF1B\u4ED6\u4E3A\u5B98\u6E05\u6B63\u6562\u8A00\uFF0C\u4E3B\u5F20\u6297\u91D1\uFF0C\u66FE\u591A\u6B21\u4E0A\u758F\u8BAE\u8BBA\u671D\u653F\u5F97\u5931\uFF1B\u665A\u5E74\u8F9E\u5B98\u5F52\u9690\u5409\u6C34\u6545\u91CC\uFF0C\u957F\u671F\u95F2\u5C45\u4E61\u95F4\uFF0C\u5728\u7530\u56ED\u5C71\u6C34\u4E2D\u5199\u8BD7\u81EA\u9063\u3002",
      "\u4EE3\u8868\u4F5C\u54C1\uFF1A\u300A\u6653\u51FA\u51C0\u6148\u5BFA\u9001\u6797\u5B50\u65B9\u300B\u300A\u5C0F\u6C60\u300B\u300A\u5BBF\u65B0\u5E02\u5F90\u516C\u5E97\u300B\u300A\u8FC7\u677E\u6E90\u6668\u708A\u6F06\u516C\u5E97\u300B\u300A\u95F2\u5C45\u521D\u590F\u5348\u7761\u8D77\u300B\u300A\u821F\u8FC7\u5B89\u4EC1\u300B\u3002",
      "\u98CE\u683C\u4E0E\u5730\u4F4D\uFF1A\u4ED6\u5584\u4E8E\u6355\u6349\u7A0D\u7EB5\u5373\u901D\u7684\u666F\u7269\u4E0E\u77AC\u95F4\u611F\u53D7\uFF0C\u7B14\u8C03\u5E7D\u9ED8\u8BD9\u8C10\u3001\u6D3B\u8131\u81EA\u7136\uFF0C\u8BED\u8A00\u5E73\u6613\u5982\u8BDD\uFF0C\u81EA\u6210\u4E00\u5BB6\uFF0C\u540E\u4EBA\u79F0\u4E3A\u201C\u8BDA\u658B\u4F53\u201D\u3002\u521D\u4E2D\u8BFE\u6587\u6709\u300A\u8FC7\u677E\u6E90\u6668\u708A\u6F06\u516C\u5E97\uFF08\u5176\u4E94\uFF09\u300B\uFF08\u4E03\u4E0B\u8BFE\u5916\u53E4\u8BD7\u8BCD\u8BF5\u8BFB\uFF09\uFF0C\u4E2D\u8003\u5E38\u8003\u201C\u653F\u201D\u4E0E\u201C\u6B63\u201D\u7684\u901A\u5047\u3001\u201C\u8D5A\u5F97\u201D\u201C\u9519\u559C\u6B22\u201D\u7684\u542B\u4E49\u3001\u540D\u53E5\u9ED8\u5199\uFF0C\u4EE5\u53CA\u5168\u8BD7\u7531\u884C\u8DEF\u611F\u53D7\u751F\u53D1\u54F2\u7406\u3001\u5BD3\u7406\u4E8E\u4E8B\u7684\u5199\u6CD5\u3002"
    ],
    keyPoints: [
      "\u6768\u4E07\u91CC\u5B57\u5EF7\u79C0\uFF0C\u53F7\u8BDA\u658B\uFF0C\u5409\u5DDE\u5409\u6C34\uFF08\u4ECA\u6C5F\u897F\u5409\u6C34\uFF09\u4EBA\uFF0C\u5357\u5B8B\u201C\u4E2D\u5174\u56DB\u5927\u8BD7\u4EBA\u201D\u4E4B\u4E00\u3002",
      "\u6768\u4E07\u91CC\u5F00\u521B\u7684\u8BD7\u4F53\u88AB\u79F0\u4E3A\u201C\u8BDA\u658B\u4F53\u201D\uFF0C\u7279\u70B9\u662F\u5E7D\u9ED8\u8BD9\u8C10\u3001\u6D3B\u8131\u81EA\u7136\uFF0C\u5584\u4E8E\u6355\u6349\u77AC\u95F4\u666F\u7269\u3002",
      "\u521D\u4E2D\u8BFE\u6587\u300A\u8FC7\u677E\u6E90\u6668\u708A\u6F06\u516C\u5E97\uFF08\u5176\u4E94\uFF09\u300B\u540D\u53E5\uFF1A\u201C\u653F\u5165\u4E07\u5C71\u56F4\u5B50\u91CC\uFF0C\u4E00\u5C71\u653E\u51FA\u4E00\u5C71\u62E6\u3002\u201D",
      "\u201C\u653F\u5165\u4E07\u5C71\u56F4\u5B50\u91CC\u201D\u7684\u201C\u653F\u201D\u540C\u201C\u6B63\u201D\uFF0C\u662F\u901A\u5047\u73B0\u8C61\uFF0C\u9ED8\u5199\u65F6\u4E0D\u80FD\u5199\u4F5C\u201C\u6B63\u201D\u3002",
      "\u300A\u8FC7\u677E\u6E90\u6668\u708A\u6F06\u516C\u5E97\uFF08\u5176\u4E94\uFF09\u300B\u7531\u7FFB\u5C71\u8D8A\u5CAD\u7684\u5207\u8EAB\u611F\u53D7\u751F\u53D1\u54F2\u7406\uFF1A\u524D\u8FDB\u8DEF\u4E0A\u56F0\u96BE\u91CD\u91CD\uFF0C\u4E0D\u53EF\u88AB\u4E00\u65F6\u7684\u987A\u5883\u8FF7\u60D1\uFF0C\u8981\u653E\u773C\u957F\u8FDC\u3001\u4E0D\u65AD\u514B\u670D\u56F0\u96BE\u3002",
      "\u201C\u83AB\u8A00\u4E0B\u5CAD\u4FBF\u65E0\u96BE\uFF0C\u8D5A\u5F97\u884C\u4EBA\u9519\u559C\u6B22\u201D\u4E2D\u201C\u8D5A\u201D\u662F\u9A97\u7684\u610F\u601D\uFF0C\u201C\u9519\u559C\u6B22\u201D\u6307\u7A7A\u6B22\u559C\u4E00\u573A\uFF0C\u8BED\u6C14\u8BD9\u8C10\u800C\u542B\u8B66\u9192\u3002",
      "\u6768\u4E07\u91CC\u300A\u6653\u51FA\u51C0\u6148\u5BFA\u9001\u6797\u5B50\u65B9\u300B\u540D\u53E5\uFF1A\u201C\u63A5\u5929\u83B2\u53F6\u65E0\u7A77\u78A7\uFF0C\u6620\u65E5\u8377\u82B1\u522B\u6837\u7EA2\u3002\u201D",
      "\u6768\u4E07\u91CC\u300A\u5C0F\u6C60\u300B\u540D\u53E5\uFF1A\u201C\u5C0F\u8377\u624D\u9732\u5C16\u5C16\u89D2\uFF0C\u65E9\u6709\u873B\u8713\u7ACB\u4E0A\u5934\u3002\u201D"
    ],
