        options: ["\u201C\u4E8C\u664F\u201D", "\u201C\u6D4E\u5357\u4E8C\u5B89\u201D", "\u201C\u82CF\u95E8\u56DB\u5B66\u58EB\u201D", "\u201C\u6C38\u5609\u56DB\u7075\u201D"],
