        type: "fill",
        stem: "\u674E\u6E05\u7167\u300A\u5982\u68A6\u4EE4\uFF08\u5E38\u8BB0\u6EAA\u4EAD\u65E5\u66AE\uFF09\u300B\u4E2D\u201C\u4E89\u6E21\uFF0C\u4E89\u6E21\uFF0C____\u201D\u4EE5\u9E25\u9E6D\u60CA\u98DE\u7684\u52A8\u666F\u6536\u675F\u5168\u8BCD\u3002",
        answer: "\u60CA\u8D77\u4E00\u6EE9\u9E25\u9E6D",
