      "\u300A\u671D\u5929\u5B50\xB7\u548F\u5587\u53ED\u300B\u662F\u738B\u78D0\u501F\u548F\u5587\u53ED\u8BBD\u523A\u660E\u4EE3\u5BA6\u5B98\u4E58\u5B98\u8239\u5F80\u6765\u3001\u9A9A\u6270\u767E\u59D3\u3001\u6A2A\u7D22\u8D22\u7269\u7684\u4F5C\u54C1\uFF0C\u901A\u7BC7\u7528\u6258\u7269\u8BBD\u55BB\uFF08\u501F\u7269\u548F\u4EBA\uFF09\u7684\u5199\u6CD5\u3002",
      "\u201C\u519B\u542C\u4E86\u519B\u6101\uFF0C\u6C11\u542C\u4E86\u6C11\u6015\u201D\u7528\u53E5\u5F0F\u76F8\u540C\u7684\u5BF9\u5076\u53E5\u5199\u519B\u6C11\u5171\u540C\u7684\u6050\u60E7\uFF0C\u4ECE\u4FA7\u9762\u70D8\u6258\u5BA6\u5B98\u6270\u6C11\u4E4B\u70C8\u3002",
      "\u201C\u773C\u89C1\u7684\u5439\u7FFB\u4E86\u8FD9\u5BB6\uFF0C\u5439\u4F24\u4E86\u90A3\u5BB6\uFF0C\u53EA\u5439\u7684\u6C34\u5C3D\u9E45\u98DE\u7F62\u201D\u8FDE\u7528\u4E09\u4E2A\u201C\u5439\u201D\u5B57\u5C42\u5C42\u9012\u8FDB\uFF0C\u4EE5\u5938\u5F20\u5199\u767E\u59D3\u88AB\u641C\u522E\u6B86\u5C3D\u7684\u60E8\u72B6\u3002",
      "\u201C\u54EA\u91CC\u53BB\u8FA8\u751A\u4E48\u771F\u5171\u5047\u201D\u7528\u53CD\u95EE\u63ED\u9732\u5BA6\u5B98\u5047\u501F\u5723\u65E8\u3001\u6A2A\u884C\u65E0\u5FCC\u7684\u86EE\u6A2A\uFF0C\u8BED\u6C14\u7531\u51B7\u5632\u8F6C\u4E3A\u6124\u6168\u3002"
