        stem: "\u97E9\u6108\u300A\u9A6C\u8BF4\u300B\u7ED3\u5C3E\u4EE5\u201C\u545C\u547C\uFF01\u5176\u771F\u65E0\u9A6C\u90AA\uFF1F____\u201D\u7684\u53CD\u95EE\u4E0E\u611F\u53F9\uFF0C\u8BBD\u523A\u201C\u98DF\u9A6C\u8005\u201D\u7684\u65E0\u77E5\u3002",
