        stem: "\u8F9B\u5F03\u75BE\u300A\u7834\u9635\u5B50\xB7\u4E3A\u9648\u540C\u752B\u8D4B\u58EE\u8BCD\u4EE5\u5BC4\u4E4B\u300B\u4E2D\u201C\u4E86\u5374\u541B\u738B\u5929\u4E0B\u4E8B\uFF0C____\u3002\u53EF\u601C\u767D\u53D1\u751F\u201D\u5199\u5C3D\u58EE\u5FD7\u672A\u916C\u7684\u60B2\u6168\u3002",
        answer: "\u8D62\u5F97\u751F\u524D\u8EAB\u540E\u540D",
        explanation: "\u8BCD\u4EBA\u5728\u68A6\u4E2D\u8FFD\u5FC6\u519B\u4E2D\u751F\u6D3B\uFF0C\u60F3\u8981\u5B8C\u6210\u6536\u590D\u5931\u5730\u7684\u5927\u4E1A\u3001\u8D62\u5F97\u751F\u524D\u8EAB\u540E\u7684\u7F8E\u540D\uFF0C\u672B\u53E5\u201C\u53EF\u601C\u767D\u53D1\u751F\u201D\u5374\u9661\u7136\u4E00\u8F6C\uFF0C\u628A\u4E0A\u9762\u7684\u8C6A\u58EE\u4E00\u7B14\u626B\u7A7A\uFF0C\u7406\u60F3\u4E0E\u73B0\u5B9E\u7684\u5DE8\u5927\u843D\u5DEE\u6B63\u663E\u51FA\u60B2\u6168\u4E4B\u6DF1\u3002",
