      "\u4EE3\u8868\u4F5C\u54C1\uFF1A\u300A\u7AF9\u91CC\u9986\u300B\u300A\u4F7F\u81F3\u585E\u4E0A\u300B\u300A\u5C71\u5C45\u79CB\u669D\u300B\u300A\u9E1F\u9E23\u6DA7\u300B\u300A\u76F8\u601D\u300B\u300A\u9001\u5143\u4E8C\u4F7F\u5B89\u897F\u300B\u300A\u4E5D\u6708\u4E5D\u65E5\u5FC6\u5C71\u4E1C\u5144\u5F1F\u300B\u3002",
      "\u98CE\u683C\u4E0E\u5730\u4F4D\uFF1A\u4ED6\u65E2\u662F\u8BD7\u4EBA\u53C8\u662F\u753B\u5BB6\uFF0C\u5584\u4E8E\u4EE5\u753B\u5BB6\u7684\u773C\u5149\u7ECF\u8425\u8272\u5F69\u3001\u5149\u5F71\u4E0E\u6784\u56FE\uFF0C\u5C71\u6C34\u7530\u56ED\u8BD7\u610F\u5883\u6E05\u5E7D\u3001\u7985\u610F\u6DF1\u8FDC\uFF0C\u4E0E\u5B5F\u6D69\u7136\u5E76\u79F0\u201C\u738B\u5B5F\u201D\uFF0C\u82CF\u8F7C\u8BC4\u4ED6\u201C\u8BD7\u4E2D\u6709\u753B\uFF0C\u753B\u4E2D\u6709\u8BD7\u201D\u3002\u521D\u4E2D\u8BFE\u6587\u6709\u300A\u7AF9\u91CC\u9986\u300B\uFF08\u4E03\u4E0B\uFF09\u4E0E\u300A\u4F7F\u81F3\u585E\u4E0A\u300B\uFF08\u516B\u4E0A\uFF09\uFF0C\u4E2D\u8003\u5E38\u8003\u201C\u5927\u6F20\u5B64\u70DF\u76F4\uFF0C\u957F\u6CB3\u843D\u65E5\u5706\u201D\u7684\u753B\u9762\u63CF\u8FF0\u4E0E\u201C\u76F4\u201D\u201C\u5706\u201D\u7684\u70BC\u5B57\u3001\u201C\u6DF1\u6797\u4EBA\u4E0D\u77E5\uFF0C\u660E\u6708\u6765\u76F8\u7167\u201D\u7684\u5E7D\u9759\u610F\u5883\uFF0C\u4EE5\u53CA\u201C\u5F81\u84EC\u201D\u201C\u5019\u9A91\u201D\u201C\u71D5\u7136\u201D\u7684\u5B57\u5F62\u4E0E\u8BFB\u97F3\u3002"
