    category: "\u4F5C\u5BB6\u4F5C\u54C1",
    title: "\u5B5F\u6D69\u7136\u2014\u2014\u5510\u4EE3\u5C71\u6C34\u7530\u56ED\u8BD7\u6D3E\u7684\u4EE3\u8868\u4E0E\u201C\u5B5F\u8944\u9633\u201D",
    content: [
      "\u5B5F\u6D69\u7136\uFF08689\u2014740\uFF09\uFF0C\u5B57\u6D69\u7136\uFF0C\u8944\u5DDE\u8944\u9633\uFF08\u4ECA\u6E56\u5317\u8944\u9633\uFF09\u4EBA\uFF0C\u4E16\u79F0\u201C\u5B5F\u8944\u9633\u201D\uFF0C\u5510\u4EE3\u5C71\u6C34\u7530\u56ED\u8BD7\u6D3E\u7684\u4EE3\u8868\u8BD7\u4EBA\u3002",
      "\u751F\u5E73\u7ECF\u5386\uFF1A\u4ED6\u65E9\u5E74\u9690\u5C45\u5BB6\u4E61\u9E7F\u95E8\u5C71\u8BFB\u4E66\uFF0C\u6B64\u540E\u957F\u671F\u6F2B\u6E38\u6C5F\u6E58\u3001\u5434\u8D8A\u4E4B\u95F4\uFF0C\u4E00\u751F\u5927\u90E8\u5206\u65F6\u95F4\u5728\u9690\u5C45\u4E2D\u5EA6\u8FC7\uFF1B\u4ED6\u66FE\u8D74\u957F\u5B89\u5E94\u8FDB\u58EB\u4E3E\u800C\u4E0D\u7B2C\uFF0C\u5728\u592A\u5B66\u8D4B\u8BD7\u800C\u540D\u52A8\u516C\u537F\uFF1B\u540E\u6765\u5F20\u4E5D\u9F84\u9547\u5B88\u8346\u5DDE\uFF0C\u4ED6\u5165\u5176\u5E55\u5E9C\u4E3A\u4ECE\u4E8B\uFF1B\u665A\u5E74\u5F52\u9690\u8944\u9633\uFF0C\u56E0\u75C5\u53BB\u4E16\u3002",
      "\u4EE3\u8868\u4F5C\u54C1\uFF1A\u300A\u671B\u6D1E\u5EAD\u6E56\u8D60\u5F20\u4E1E\u76F8\u300B\u300A\u6625\u6653\u300B\u300A\u8FC7\u6545\u4EBA\u5E84\u300B\u300A\u5BBF\u5EFA\u5FB7\u6C5F\u300B\u300A\u5C81\u66AE\u5F52\u5357\u5C71\u300B\u3002",
      "\u98CE\u683C\u4E0E\u5730\u4F4D\uFF1A\u4ED6\u662F\u5510\u4EE3\u7B2C\u4E00\u4F4D\u5927\u91CF\u5199\u4F5C\u5C71\u6C34\u7530\u56ED\u8BD7\u7684\u8BD7\u4EBA\uFF0C\u8BD7\u98CE\u6E05\u6DE1\u81EA\u7136\u3001\u4E0D\u5047\u96D5\u9970\uFF0C\u4E0E\u738B\u7EF4\u5E76\u79F0\u201C\u738B\u5B5F\u201D\uFF0C\u674E\u767D\u5728\u300A\u8D60\u5B5F\u6D69\u7136\u300B\u4E2D\u79F0\u4ED6\u201C\u543E\u7231\u5B5F\u592B\u5B50\uFF0C\u98CE\u6D41\u5929\u4E0B\u95FB\u201D\u3002\u521D\u4E2D\u8BFE\u6587\u6709\u300A\u671B\u6D1E\u5EAD\u6E56\u8D60\u5F20\u4E1E\u76F8\u300B\uFF08\u516B\u4E0B\uFF09\uFF0C\u8FD9\u662F\u4E00\u9996\u5E72\u8C12\u8BD7\uFF0C\u4E2D\u8003\u5E38\u8003\u201C\u6C14\u84B8\u4E91\u68A6\u6CFD\uFF0C\u6CE2\u64BC\u5CB3\u9633\u57CE\u201D\u4E2D\u201C\u84B8\u201D\u201C\u64BC\u201D\u4E8C\u5B57\u7684\u70BC\u5B57\u8D4F\u6790\u3001\u201C\u821F\u696B\u201D\u201C\u5782\u9493\u8005\u201D\u7684\u6BD4\u55BB\u4E49\uFF0C\u4EE5\u53CA\u501F\u89C2\u6E56\u9493\u9C7C\u59D4\u5A49\u6C42\u8350\u7684\u7528\u610F\u3002"
    ],
    keyPoints: [
      "\u5B5F\u6D69\u7136\u5B57\u6D69\u7136\uFF0C\u8944\u5DDE\u8944\u9633\uFF08\u4ECA\u6E56\u5317\u8944\u9633\uFF09\u4EBA\uFF0C\u4E16\u79F0\u201C\u5B5F\u8944\u9633\u201D\uFF0C\u662F\u5510\u4EE3\u5C71\u6C34\u7530\u56ED\u8BD7\u6D3E\u7684\u4EE3\u8868\u8BD7\u4EBA\u3002",
      "\u5B5F\u6D69\u7136\u4E0E\u738B\u7EF4\u5E76\u79F0\u201C\u738B\u5B5F\u201D\uFF0C\u662F\u5510\u4EE3\u7B2C\u4E00\u4F4D\u5927\u91CF\u5199\u4F5C\u5C71\u6C34\u7530\u56ED\u8BD7\u7684\u8BD7\u4EBA\u3002",
      "\u5B5F\u6D69\u7136\u4E00\u751F\u5927\u90E8\u5206\u65F6\u95F4\u9690\u5C45\u3001\u6F2B\u6E38\uFF0C\u66FE\u8D74\u957F\u5B89\u5E94\u8FDB\u58EB\u4E3E\u800C\u4E0D\u7B2C\uFF0C\u672A\u66FE\u5728\u671D\u5EF7\u6B63\u5F0F\u505A\u5B98\u3002",
      "\u521D\u4E2D\u8BFE\u6587\u300A\u671B\u6D1E\u5EAD\u6E56\u8D60\u5F20\u4E1E\u76F8\u300B\uFF08\u516B\u4E0B\uFF09\u662F\u4E00\u9996\u5E72\u8C12\u8BD7\uFF0C\u5199\u7ED9\u65F6\u4EFB\u4E1E\u76F8\u5F20\u4E5D\u9F84\uFF0C\u59D4\u5A49\u8868\u8FBE\u5E0C\u671B\u5F97\u5230\u5F15\u8350\u3001\u51FA\u4ED5\u7528\u4E16\u7684\u5FC3\u613F\u3002",
      "\u5B5F\u6D69\u7136\u300A\u671B\u6D1E\u5EAD\u6E56\u8D60\u5F20\u4E1E\u76F8\u300B\u540D\u53E5\uFF1A\u201C\u6C14\u84B8\u4E91\u68A6\u6CFD\uFF0C\u6CE2\u64BC\u5CB3\u9633\u57CE\u3002\u201D",
      "\u201C\u6C14\u84B8\u4E91\u68A6\u6CFD\uFF0C\u6CE2\u64BC\u5CB3\u9633\u57CE\u201D\u4E2D\u201C\u84B8\u201D\u5B57\u5199\u6C34\u6C7D\u84B8\u817E\u5F25\u6F2B\u3001\u201C\u64BC\u201D\u5B57\u5199\u6CE2\u6D9B\u6C79\u6D8C\u64BC\u52A8\u57CE\u90ED\uFF0C\u4E00\u5B57\u4E00\u666F\uFF0C\u628A\u6D1E\u5EAD\u6E56\u7684\u78C5\u7934\u6C14\u8C61\u5199\u8DB3\u3002",
      "\u201C\u6B32\u6D4E\u65E0\u821F\u696B\u201D\u4EE5\u6E21\u6E56\u65E0\u8239\u6BD4\u55BB\u51FA\u4ED5\u65E0\u4EBA\u5F15\u8350\uFF1B\u201C\u5750\u89C2\u5782\u9493\u8005\uFF0C\u5F92\u6709\u7FA1\u9C7C\u60C5\u201D\u5316\u7528\u300A\u6DEE\u5357\u5B50\u300B\u201C\u4E34\u6CB3\u800C\u7FA1\u9C7C\uFF0C\u4E0D\u5982\u5F52\u5BB6\u7EC7\u7F51\u201D\u7684\u5178\u6545\uFF0C\u628A\u6C42\u8350\u4E4B\u610F\u8BF4\u5F97\u542B\u84C4\u5F97\u4F53\u3002",
      "\u5B5F\u6D69\u7136\u300A\u6625\u6653\u300B\u540D\u53E5\uFF1A\u201C\u6625\u7720\u4E0D\u89C9\u6653\uFF0C\u5904\u5904\u95FB\u557C\u9E1F\u3002\u201D\u4E0E\u300A\u8FC7\u6545\u4EBA\u5E84\u300B\u201C\u7EFF\u6811\u6751\u8FB9\u5408\uFF0C\u9752\u5C71\u90ED\u5916\u659C\u201D\u540C\u5199\u7530\u56ED\u751F\u6D3B\u7684\u606C\u6DE1\u81EA\u5728\u3002"
    ],
