      "\u5D14\u98A2\u300A\u9EC4\u9E64\u697C\u300B\u88AB\u5B8B\u4EE3\u4E25\u7FBD\u300A\u6CA7\u6D6A\u8BD7\u8BDD\u300B\u63A8\u4E3A\u201C\u5510\u4EBA\u4E03\u8A00\u5F8B\u8BD7\u7B2C\u4E00\u201D\u3002",
      "\u300A\u9EC4\u9E64\u697C\u300B\u4E2D\u201C\u6614\u4EBA\u5DF2\u4E58\u9EC4\u9E64\u53BB\u201D\u7684\u201C\u6614\u4EBA\u201D\u6307\u4F20\u8BF4\u4E2D\u9A91\u9E64\u98DE\u53BB\u7684\u4ED9\u4EBA\uFF08\u4E00\u8BF4\u4E3A\u4E09\u56FD\u65F6\u7684\u8D39\u794E\uFF09\uFF0C\u4E0D\u662F\u6307\u8BD7\u4EBA\u81EA\u5DF1\u3002",
