        stem: "\u81EA\u8BE9\u201C\u4E94\u8A00\u957F\u57CE\u201D\u3001\u5199\u6709\u300A\u957F\u6C99\u8FC7\u8D3E\u8C0A\u5B85\u300B\u7684\u5510\u4EE3\u8BD7\u4EBA\u662F\uFF08\u3000\u3000\uFF09",
