        stem: "\u5218\u957F\u537F\u300A\u957F\u6C99\u8FC7\u8D3E\u8C0A\u5B85\u300B\u4E2D\u201C\u79CB\u8349\u72EC\u5BFB\u4EBA\u53BB\u540E\uFF0C____\u201D\u4EE5\u8427\u745F\u4E4B\u666F\u5199\u51ED\u540A\u8005\u7684\u5BC2\u5BDE\u3002",
        answer: "\u5BD2\u6797\u7A7A\u89C1\u65E5\u659C\u65F6",
        explanation: "\u8BD7\u4EBA\u72EC\u81EA\u5728\u79CB\u8349\u95F4\u5BFB\u8BBF\u8D3E\u8C0A\u7684\u9057\u8FF9\uFF0C\u53EA\u5728\u5BD2\u6797\u4E2D\u7A7A\u81EA\u770B\u89C1\u5915\u9633\u897F\u659C\u3002\u201C\u72EC\u5BFB\u201D\u5199\u5F62\u5355\u5F71\u53EA\uFF0C\u201C\u7A7A\u89C1\u201D\u5199\u4E00\u65E0\u6240\u83B7\uFF0C\u8427\u745F\u7684\u79CB\u8349\u3001\u5BD2\u6797\u4E0E\u65E5\u659C\u5C42\u5C42\u6E32\u67D3\u8352\u51C9\uFF0C\u4E5F\u6697\u542B\u7740\u8BD7\u4EBA\u81EA\u5DF1\u88AB\u8D2C\u5931\u610F\u7684\u8EAB\u4E16\u4E4B\u611F\u3002\u201C\u659C\u201D\u6B64\u5904\u8BFB xi\xE1 \u4EE5\u62BC\u97F5\u3002",
        difficulty: 2,
        tags: ["\u5218\u957F\u537F", "\u6587\u5B66\u5E38\u8BC6", "\u540D\u53E5\u9ED8\u5199"]
