        stem: "\u6797\u5FBD\u56E0\u300A\u4F60\u662F\u4EBA\u95F4\u7684\u56DB\u6708\u5929\u300B\u4E2D\u201C\u4F60\u662F\u7231\uFF0C\u662F\u6696\uFF0C\u662F\u5E0C\u671B\uFF0C____\u201D\u7531\u5177\u4F53\u610F\u8C61\u5347\u534E\u4E3A\u60C5\u611F\u4E0E\u54F2\u601D\uFF0C\u70B9\u4EAE\u5168\u8BD7\u4E3B\u65E8\u3002",
        answer: "\u4F60\u662F\u4EBA\u95F4\u7684\u56DB\u6708\u5929",
        explanation: "\u524D\u9762\u7528\u4E91\u70DF\u3001\u661F\u5B50\u3001\u7EC6\u96E8\u3001\u9E45\u9EC4\u3001\u7EFF\u3001\u767D\u83B2\u3001\u82B1\u5F00\u3001\u71D5\u8BED\u7B49\u610F\u8C61\u53CD\u590D\u63CF\u6479\u201C\u4F60\u201D\uFF0C\u5230\u8FD9\u4E00\u53E5\u7A81\u7136\u62BD\u53BB\u5177\u4F53\u5F62\u8C61\uFF0C\u76F4\u63A5\u8BF4\u51FA\u201C\u7231\u201D\u201C\u6696\u201D\u201C\u5E0C\u671B\u201D\uFF0C\u518D\u56DE\u5230\u201C\u4F60\u662F\u4EBA\u95F4\u7684\u56DB\u6708\u5929\u201D\u6536\u675F\uFF0C\u5168\u8BD7\u7684\u6BD4\u55BB\u81F3\u6B64\u5B8C\u6210\u5347\u534E\u3002\u8FD9\u4E00\u53E5\u4E5F\u662F\u672B\u53E5\uFF0C\u9ED8\u5199\u65F6\u6CE8\u610F\u201C\u95F4\u201D\u4E0D\u5199\u4F5C\u201C\u95EE\u201D\u3002",
