        stem: "\u300A\u5C71\u5761\u7F8A\xB7\u6F7C\u5173\u6000\u53E4\u300B\u4E2D\u201C\u5C71\u5761\u7F8A\u201D\u662F\uFF08\u3000\u3000\uFF09",
        options: ["\u9898\u76EE", "\u8BCD\u724C\u540D", "\u66F2\u724C\u540D", "\u4F5C\u8005\u7684\u53F7"],
        answer: "C",
        explanation: "\u6563\u66F2\u7684\u6807\u76EE\u65B9\u5F0F\u4E0E\u8BCD\u76F8\u8FD1\uFF0C\u201C\u5C71\u5761\u7F8A\u201D\u662F\u66F2\u724C\u540D\uFF0C\u201C\u6F7C\u5173\u6000\u53E4\u201D\u624D\u662F\u9898\u76EE\uFF1B\u4F5C\u8005\u5F20\u517B\u6D69\u53F7\u4E91\u5E84\uFF0C\u4E0E\u201C\u5C71\u5761\u7F8A\u201D\u65E0\u5173\u3002",
