        type: "fill",
        stem: "\u5F20\u517B\u6D69\u300A\u5C71\u5761\u7F8A\xB7\u6F7C\u5173\u6000\u53E4\u300B\u4E2D\u201C____\uFF0C\u6CE2\u6D9B\u5982\u6012\uFF0C\u5C71\u6CB3\u8868\u91CC\u6F7C\u5173\u8DEF\u201D\u4EE5\u201C\u805A\u201D\u201C\u6012\u201D\u4E8C\u5B57\u5199\u666F\u4F20\u795E\u3002",
        answer: "\u5CF0\u5CE6\u5982\u805A",
        explanation: "\u201C\u805A\u201D\u5B57\u628A\u9759\u6B62\u7684\u7FA4\u5CF0\u5199\u5F97\u597D\u50CF\u5411\u6F7C\u5173\u5954\u6D8C\u800C\u6765\uFF0C\u201C\u6012\u201D\u5B57\u628A\u9EC4\u6CB3\u6CE2\u6D9B\u5199\u6D3B\uFF0C\u4E24\u53E5\u5408\u5199\u6F7C\u5173\u5730\u52BF\u7684\u9669\u8981\uFF0C\u4E3A\u4E0B\u6587\u6000\u53E4\u4F5C\u94FA\u57AB\u3002",
        difficulty: 2,
