        stem: "\u9F9A\u81EA\u73CD\u300A\u5DF1\u4EA5\u6742\u8BD7\uFF08\u5176\u4E94\uFF09\u300B\u4E2D\u201C\u843D\u7EA2\u4E0D\u662F\u65E0\u60C5\u7269\uFF0C\u5316\u4F5C\u6625\u6CE5\u66F4\u62A4\u82B1\u201D\u7684\u201C\u843D\u7EA2\u201D\u6307\uFF08\u3000\u3000\uFF09",
