var extensionsBooks = [
  /* ================================================================ */
  /* 一、背景拓展（12 条，每部名著 1 条）                               */
  /* ================================================================ */
  {
    id: "ext-bg-zhaohuaxishi",
    moduleId: "literature",
    entryId: "l-zhaohuaxishi",
    grade: "7a",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u300A\u671D\u82B1\u5915\u62FE\u300B\u4E3A\u4EC0\u4E48\u5728\u6D41\u79BB\u4E2D\u5199\u7AE5\u5E74",
    summary: "1926 \u5E74\u9C81\u8FC5\u88AB\u901A\u7F09\u3001\u8F97\u8F6C\u907F\u96BE\uFF0C\u5728\u53A6\u95E8\u4E0E\u5E7F\u5DDE\u7684\u5F02\u4E61\u5199\u6210\u5341\u7BC7\u56DE\u5FC6\u6563\u6587\uFF0C\u6E29\u60C5\u4E0E\u6279\u5224\u540C\u6E90\u3002",
    content: [
      "## \u4ECE\u300C\u5973\u5E08\u5927\u98CE\u6F6E\u300D\u5230\u300C\u4E09\u4E00\u516B\u300D",
      "1924 \u5E74\u81F3 1925 \u5E74\uFF0C\u5317\u4EAC\u5973\u5B50\u5E08\u8303\u5927\u5B66\u5B66\u751F\u53CD\u5BF9\u6821\u957F\u6768\u836B\u6986\uFF0C\u9C81\u8FC5\u516C\u5F00\u652F\u6301\u5B66\u751F\uFF0C\u56E0\u6B64\u88AB\u6559\u80B2\u603B\u957F\u7AE0\u58EB\u948A\u514D\u53BB\u6559\u80B2\u90E8\u4F65\u4E8B\u7684\u804C\u52A1\uFF1B\u4ED6\u5411\u5E73\u653F\u9662\u8D77\u8BC9\u5E76\u80DC\u8BC9\uFF0C1926 \u5E74\u521D\u624D\u5F97\u4EE5\u590D\u804C\u30021926 \u5E74 3 \u6708 18 \u65E5\uFF0C\u6BB5\u797A\u745E\u6267\u653F\u5E9C\u536B\u961F\u5728\u6267\u653F\u5E9C\u95E8\u524D\u5F00\u67AA\uFF0C\u5236\u9020\u4E86\u300C\u4E09\u4E00\u516B\u300D\u60E8\u6848\uFF0C\u5218\u548C\u73CD\u7B49\u5B66\u751F\u9047\u96BE\uFF1B\u9C81\u8FC5\u5199\u4E0B\u300A\u8BB0\u5FF5\u5218\u548C\u73CD\u541B\u300B\uFF0C\u968F\u5373\u88AB\u5217\u5165\u901A\u7F09\u540D\u5355\u3002\u4ED6\u5148\u540E\u907F\u5C45\u897F\u57CE\u83BD\u539F\u793E\u3001\u5C71\u672C\u533B\u9662\u3001\u5FB7\u56FD\u533B\u9662\u3001\u6CD5\u56FD\u533B\u9662\u7B49\u5904\uFF0C\u5728\u5317\u4EAC\u5DF2\u65E0\u6CD5\u5B89\u8EAB\u3002\u8FD9\u5C31\u662F\u300A\u671D\u82B1\u5915\u62FE\u300B\u52A8\u7B14\u65F6\u7684\u5904\u5883\u3002",
      "## \u5728\u53A6\u95E8\u4E0E\u5E7F\u5DDE\u300C\u4ECE\u8BB0\u5FC6\u4E2D\u6284\u51FA\u6765\u300D",
      "1926 \u5E74 8 \u6708\uFF0C\u9C81\u8FC5\u5E94\u6797\u8BED\u5802\u4E4B\u9080\u79BB\u5F00\u5317\u4EAC\uFF0C\u8D74\u53A6\u95E8\u5927\u5B66\u4EFB\u6559\uFF1B1927 \u5E74 1 \u6708\u53C8\u5230\u5E7F\u5DDE\uFF0C\u4EFB\u4E2D\u5C71\u5927\u5B66\u6587\u5B66\u7CFB\u4E3B\u4EFB\u517C\u6559\u52A1\u4E3B\u4EFB\u3002\u5341\u7BC7\u6563\u6587\u5199\u4E8E 1926 \u5E74 2 \u6708\u81F3 11 \u6708\u4E4B\u95F4\uFF0C\u524D\u4E24\u7BC7\u5199\u5728\u5317\u4EAC\uFF0C\u5176\u4F59\u5404\u7BC7\u5199\u5728\u53A6\u95E8\u4E0E\u5E7F\u5DDE\u3002\u300A\u5C0F\u5F15\u300B\u5B8C\u6210\u4E8E 1927 \u5E74 5 \u6708 1 \u65E5\u7684\u5E7F\u5DDE\u767D\u4E91\u697C\uFF0C\u300A\u540E\u8BB0\u300B\u5199\u4E8E\u540C\u5E74 7 \u6708 11 \u65E5\u3002\u4E5F\u5C31\u662F\u8BF4\uFF0C\u5168\u4E66\u662F\u4ED6\u5728\u4E00\u5E74\u4E4B\u5185\u88AB\u8D76\u7740\u4ECE\u5317\u4EAC\u8D70\u5230\u53A6\u95E8\u3001\u518D\u8D70\u5230\u5E7F\u5DDE\u7684\u8FC7\u7A0B\u4E2D\u9646\u7EED\u5199\u6210\u7684\u3002",
      "## \u4E66\u540D\u4E3A\u4EC0\u4E48\u6539\u4E86",
      "\u8FD9\u5341\u7BC7\u6587\u7AE0\u6700\u521D\u4EE5\u300A\u65E7\u4E8B\u91CD\u63D0\u300B\u4E3A\u603B\u9898\u76EE\uFF0C\u53D1\u8868\u5728\u300A\u83BD\u539F\u300B\u534A\u6708\u520A\u4E0A\uFF1B1928 \u5E74 9 \u6708\u7531\u5317\u65B0\u4E66\u5C40\u7ED3\u96C6\u51FA\u7248\u65F6\uFF0C\u624D\u6539\u540D\u4E3A\u300A\u671D\u82B1\u5915\u62FE\u300B\u3002\u300A\u5C0F\u5F15\u300B\u91CC\u6709\u4E24\u53E5\u5E38\u88AB\u5F15\u7528\u7684\u8BDD\uFF1A\u300C\u6211\u5E38\u60F3\u5728\u7EB7\u6270\u4E2D\u5BFB\u51FA\u4E00\u70B9\u95F2\u9759\u6765\uFF0C\u7136\u800C\u59D4\u5B9E\u4E0D\u5BB9\u6613\u300D\uFF1B\u300C\u5E26\u9732\u6298\u82B1\uFF0C\u8272\u9999\u81EA\u7136\u8981\u597D\u5F97\u591A\uFF0C\u4F46\u662F\u6211\u4E0D\u80FD\u591F\u300D\u3002\u4ED6\u5766\u8A00\u8FD9\u5341\u7BC7\u300C\u5C31\u662F\u4ECE\u8BB0\u5FC6\u4E2D\u6284\u51FA\u6765\u7684\u300D\u3002\u6539\u540D\u4E0E\u8FD9\u4E24\u53E5\u8BDD\u5408\u8D77\u6765\u770B\uFF0C\u610F\u601D\u5F88\u6E05\u695A\uFF1A\u8FD9\u662F\u4E2D\u5E74\u4EBA\u5728\u52A8\u8361\u4E2D\u56DE\u5934\u53BB\u6361\u62FE\u65E9\u5E74\u8BB0\u5FC6\uFF0C\u800C\u4E14\u5DF2\u7ECF\u6361\u4E0D\u56DE\u539F\u6765\u7684\u65B0\u9C9C\uFF0C\u53EA\u80FD\u51ED\u501F\u8BB0\u5FC6\u7684\u6B8B\u7247\u91CD\u5199\u3002",
      "## \u6E29\u60C5\u4ECE\u54EA\u91CC\u6765",
      "\u56DE\u5FC6\u91CC\u7684\u6E29\u6696\u662F\u6709\u5177\u4F53\u4EBA\u4E8B\u7684\uFF1A\u4FDD\u59C6\u957F\u5988\u5988\u867D\u7136\u7C97\u4FD7\u3001\u8FF7\u4FE1\u3001\u7231\u300C\u5207\u5207\u5BDF\u5BDF\u300D\uFF0C\u5374\u8BB0\u4F4F\u4E86\u5C11\u5E74\u9C81\u8FC5\u5BF9\u300A\u5C71\u6D77\u7ECF\u300B\u7684\u6E34\u671B\uFF0C\u4F11\u5047\u56DE\u6765\u65F6\u4E70\u56DE\u90A3\u90E8\u7ED8\u56FE\u4E66\uFF0C\u8BA9\u4ED6\u751F\u51FA\u300C\u65B0\u7684\u656C\u610F\u300D\uFF1B\u79C1\u587E\u5148\u751F\u5BFF\u955C\u543E\u65B9\u6B63\u8D28\u6734\uFF0C\u8BFB\u4E66\u65F6\u628A\u5934\u300C\u62D7\u8FC7\u53BB\uFF0C\u62D7\u8FC7\u53BB\u300D\uFF1B\u5728\u65E5\u672C\u4ED9\u53F0\u7684\u85E4\u91CE\u5148\u751F\u6BEB\u65E0\u6C11\u65CF\u504F\u89C1\u5730\u4E3A\u4ED6\u6DFB\u6539\u8BB2\u4E49\u3001\u7EA0\u6B63\u8840\u7BA1\u56FE\uFF1B\u767E\u8349\u56ED\u91CC\u6709\u7FFB\u7816\u6349\u866B\u3001\u542C\u7F8E\u5973\u86C7\u4F20\u8BF4\u3001\u51AC\u5929\u96EA\u5730\u6355\u9E1F\u7684\u4E50\u8DA3\u3002\u4E00\u4E2A\u5728\u73B0\u5B9E\u4E2D\u88AB\u56F4\u527F\u3001\u88AB\u901A\u7F09\u7684\u4EBA\uFF0C\u8BB0\u5FC6\u91CC\u80AF\u7559\u4E0B\u7684\uFF0C\u6070\u597D\u662F\u8FD9\u51E0\u4E2A\u5F85\u4ED6\u597D\u7684\u4EBA\u3002",
      "## \u6279\u5224\u4ECE\u54EA\u91CC\u6765",
      "\u540C\u4E00\u4E2A\u8BB0\u5FC6\u91CC\u4E5F\u6709\u5BD2\u610F\uFF1A\u300A\u4E8C\u5341\u56DB\u5B5D\u56FE\u300B\u4E2D\u300C\u8001\u83B1\u5A31\u4EB2\u300D\u300C\u90ED\u5DE8\u57CB\u513F\u300D\u8BA9\u4ED6\u611F\u5230\u53CD\u611F\u4EE5\u81F3\u6050\u60E7\uFF1B\u300A\u4E94\u7316\u4F1A\u300B\u91CC\u6B63\u8981\u51FA\u95E8\u770B\u8FCE\u795E\u8D5B\u4F1A\uFF0C\u7236\u4EB2\u5374\u8981\u4ED6\u80CC\u719F\u300A\u9274\u7565\u300B\uFF0C\u80CC\u5B8C\u5174\u81F4\u5168\u65E0\uFF1B\u300A\u7236\u4EB2\u7684\u75C5\u300B\u5199\u5EB8\u533B\u5F00\u51FA\u300C\u539F\u914D\u87CB\u87C0\u4E00\u5BF9\u300D\u4E4B\u7C7B\u79BB\u5947\u836F\u5F15\uFF0C\u7EC8\u81F3\u4E0D\u6CBB\u3002\u66F4\u660E\u663E\u7684\u662F\u300A\u72D7\xB7\u732B\xB7\u9F20\u300B\uFF0C\u4ED6\u5199\u7AE5\u5E74\u4EC7\u732B\u7684\u7F18\u7531\uFF0C\u7B14\u950B\u5374\u65F6\u65F6\u8F6C\u5411\u73B0\u5B9E\u4E2D\u8BBA\u6218\u7684\u5BF9\u624B\uFF0C\u501F\u300C\u732B\u300D\u8BBD\u523A\u300C\u73B0\u4EE3\u8BC4\u8BBA\u6D3E\u300D\u7684\u300C\u6B63\u4EBA\u541B\u5B50\u300D\u3002\u73B0\u5B9E\u7684\u8BBA\u6218\u76F4\u63A5\u8FDB\u5165\u4E86\u56DE\u5FC6\u6587\u672C\u3002",
      "## \u8FD9\u4E00\u70B9\u5982\u4F55\u5E2E\u52A9\u6211\u4EEC\u8BFB\u61C2\u8FD9\u672C\u4E66",
      "\u4E0D\u8981\u628A\u300A\u671D\u82B1\u5915\u62FE\u300B\u8BFB\u6210\u5355\u7EAF\u7684\u6000\u65E7\u6563\u6587\uFF0C\u4E5F\u4E0D\u8981\u628A\u5B83\u8BFB\u6210\u7EAF\u7CB9\u7684\u6279\u5224\u6587\u96C6\u3002\u8427\u745F\u7684\u5904\u5883\u89E3\u91CA\u4E86\u4E24\u8005\u4E3A\u4EC0\u4E48\u5E76\u5B58\uFF1A\u5728\u6D41\u79BB\u4E2D\u56DE\u5FC6\u7AE5\u5E74\uFF0C\u6E29\u6696\u662F\u771F\u5B9E\u7684\u6170\u85C9\uFF0C\u6279\u5224\u662F\u771F\u5B9E\u7684\u75DB\u611F\uFF0C\u4E8C\u8005\u540C\u51FA\u4E00\u6E90\uFF0C\u6240\u4EE5\u5168\u4E66\u300C\u6E29\u99A8\u7684\u56DE\u5FC6\u300D\u4E0E\u300C\u7406\u6027\u7684\u6279\u5224\u300D\u603B\u662F\u7F20\u5728\u4E00\u8D77\u3002\u4E2D\u8003\u5E38\u4ECE\u513F\u7AE5\u89C6\u89D2\u4E0E\u6210\u4EBA\u89C6\u89D2\u7684\u4EA4\u9519\u3001\u6E29\u60C5\u4E0E\u6279\u5224\u5E76\u5B58\u8FD9\u4E24\u5904\u8BBE\u95EE\uFF0C\u77E5\u9053\u4E86\u6210\u4E66\u80CC\u666F\uFF0C\u7B54\u9898\u5C31\u6709\u6839\u3002"
    ],
    think: [
      "\u300C\u671D\u82B1\u5915\u62FE\u300D\u8FD9\u4E2A\u540D\u5B57\u5982\u679C\u6362\u6210\u539F\u6765\u7684\u300C\u65E7\u4E8B\u91CD\u63D0\u300D\uFF0C\u4F60\u5BF9\u8FD9\u672C\u4E66\u7684\u671F\u5F85\u4F1A\u6709\u4EC0\u4E48\u4E0D\u540C\uFF1F",
      "\u9C81\u8FC5\u662F\u5728\u907F\u96BE\u4E2D\u56DE\u5FC6\u7AE5\u5E74\u7684\u3002\u8BF7\u60F3\u4E00\u60F3\uFF1A\u4EBA\u4E3A\u4EC0\u4E48\u5728\u8270\u96BE\u65F6\u523B\u53CD\u800C\u66F4\u60F3\u5199\u7AE5\u5E74\uFF1F\u7ED3\u5408\u4F60\u81EA\u5DF1\u7684\u7ECF\u5386\u8C08\u8C08\u3002",
      "\u300A\u72D7\xB7\u732B\xB7\u9F20\u300B\u4E2D\u5BF9\u300C\u732B\u300D\u7684\u8BBD\u523A\u4E0E\u73B0\u5B9E\u8BBA\u6218\u6709\u5173\uFF0C\u8FD9\u662F\u5426\u5F71\u54CD\u4E86\u4F60\u5BF9\u8FD9\u7BC7\u300C\u5199\u7AE5\u5E74\u300D\u7684\u6587\u7AE0\u7684\u770B\u6CD5\uFF1F"
    ]
  },
  {
    id: "ext-bg-xiyouji",
    moduleId: "literature",
    entryId: "l-xiyouji",
    grade: "7a",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u300A\u897F\u6E38\u8BB0\u300B\u7684\u4F5C\u8005\u4E3A\u4EC0\u4E48\u5199\u5F97\u51FA\u8FD9\u6837\u7684\u795E\u9B54\u4E16\u754C",
    summary: "\u7384\u5958\u53D6\u7ECF\u662F\u53F2\u5B9E\uFF0C\u7ECF\u5B8B\u5143\u8BDD\u672C\u4E0E\u6742\u5267\u6F14\u5316\uFF0C\u79D1\u4E3E\u5931\u610F\u7684\u5434\u627F\u6069\u5199\u6210\u8FD9\u90E8\u795E\u9B54\u5C0F\u8BF4\u3002",
    content: [
      "## \u4E00\u4E2A\u771F\u5B9E\u7684\u548C\u5C1A\u8D70\u4E86\u5341\u4E03\u5E74",
      "\u53D6\u7ECF\u6545\u4E8B\u6709\u771F\u5B9E\u7684\u8D77\u70B9\u3002\u5510\u4EE3\u9AD8\u50E7\u7384\u5958\u4E8E\u8D1E\u89C2\u4E09\u5E74\uFF08629 \u5E74\uFF09\u4ECE\u957F\u5B89\u51FA\u53D1\u897F\u884C\u6C42\u6CD5\uFF0C\u8D1E\u89C2\u5341\u4E5D\u5E74\uFF08645 \u5E74\uFF09\u56DE\u5230\u957F\u5B89\uFF0C\u5386\u65F6\u5341\u4E03\u5E74\uFF0C\u884C\u7A0B\u4E94\u4E07\u91CC\uFF0C\u5E26\u56DE\u4F5B\u7ECF\u516D\u767E\u4E94\u5341\u4E03\u90E8\u3002\u4ED6\u53E3\u8FF0\u897F\u884C\u89C1\u95FB\uFF0C\u7531\u5F1F\u5B50\u8FA9\u673A\u7B14\u5F55\u6210\u300A\u5927\u5510\u897F\u57DF\u8BB0\u300B\uFF0C\u8BB0\u8F7D\u4E86\u6CBF\u9014\u4E00\u767E\u591A\u4E2A\u56FD\u5BB6\u7684\u5C71\u5DDD\u98CE\u7269\uFF1B\u4ED6\u7684\u5F1F\u5B50\u6167\u7ACB\u3001\u5F66\u60B0\u53C8\u5199\u4E86\u300A\u5927\u5510\u5927\u6148\u6069\u5BFA\u4E09\u85CF\u6CD5\u5E08\u4F20\u300B\uFF0C\u5176\u4E2D\u5DF2\u51FA\u73B0\u795E\u5F02\u7684\u4F20\u8BF4\u3002\u53F2\u5B9E\u662F\u79CD\u5B50\uFF0C\u795E\u8BDD\u662F\u540E\u6765\u957F\u51FA\u6765\u7684\u679D\u53F6\u3002",
      "## \u4ECE\u8BDD\u672C\u5230\u6742\u5267\uFF1A\u6545\u4E8B\u957F\u4E86\u4E24\u767E\u5E74",
      "\u4ECE\u5510\u5230\u660E\uFF0C\u53D6\u7ECF\u6545\u4E8B\u5728\u6C11\u95F4\u4E0D\u65AD\u957F\u5927\u3002\u5357\u5B8B\u7684\u300A\u5927\u5510\u4E09\u85CF\u53D6\u7ECF\u8BD7\u8BDD\u300B\u91CC\u51FA\u73B0\u4E86\u7334\u884C\u8005\uFF0C\u662F\u5B59\u609F\u7A7A\u5F62\u8C61\u7684\u91CD\u8981\u6E90\u5934\uFF1B\u5143\u4EE3\u6709\u5434\u660C\u9F84\u7B49\u4EBA\u7684\u53D6\u7ECF\u6742\u5267\uFF0C\u6768\u666F\u8D24\uFF08\u6768\u8BB7\uFF09\u7684\u300A\u897F\u6E38\u8BB0\u300B\u6742\u5267\u5171\u516D\u672C\u4E8C\u5341\u56DB\u6298\uFF0C\u5B59\u609F\u7A7A\u81EA\u79F0\u300C\u901A\u5929\u5927\u5723\u300D\uFF0C\u8FD8\u51FA\u73B0\u4E86\u732A\u516B\u6212\uFF1B\u53E6\u6709\u300A\u897F\u6E38\u8BB0\u5E73\u8BDD\u300B\uFF0C\u6B8B\u6587\u4FDD\u5B58\u5728\u300A\u6C38\u4E50\u5927\u5178\u300B\u4E2D\uFF0C\u5DF2\u6709\u300C\u9B4F\u5F81\u68A6\u65A9\u6CFE\u6CB3\u9F99\u300D\u8FD9\u6837\u7684\u60C5\u8282\u3002\u7ECF\u8FC7\u4E24\u767E\u591A\u5E74\u7684\u7D2F\u79EF\uFF0C\u53D6\u7ECF\u961F\u4F0D\u624D\u9010\u6E10\u51D1\u9F50\uFF0C\u6545\u4E8B\u9AA8\u67B6\u624D\u9010\u6E10\u6210\u5F62\u3002",
      "## \u5434\u627F\u6069\uFF1A\u79D1\u573A\u5931\u610F\u7684\u6DEE\u5B89\u6587\u4EBA",
      "\u5434\u627F\u6069\uFF08\u7EA6 1500 \u2014 \u7EA6 1582\uFF09\uFF0C\u5B57\u6C5D\u5FE0\uFF0C\u53F7\u5C04\u9633\u5C71\u4EBA\uFF0C\u6DEE\u5B89\u5E9C\u5C71\u9633\u53BF\uFF08\u4ECA\u6C5F\u82CF\u6DEE\u5B89\uFF09\u4EBA\u3002\u4ED6\u5C11\u5E74\u65F6\u4FBF\u6709\u6587\u540D\uFF0C\u636E\u8BF4\u8BFB\u4E66\u300C\u535A\u6781\u7FA4\u4E66\uFF0C\u4E3A\u8BD7\u6587\u4E0B\u7B14\u7ACB\u6210\u300D\uFF0C\u7136\u800C\u79D1\u4E3E\u5C61\u8BD5\u4E0D\u7B2C\uFF0C\u76F4\u5230\u4E2D\u5E74\u624D\u8865\u4E0A\u5C81\u8D21\u751F\uFF1B\u516D\u5341\u5C81\u524D\u540E\u505A\u8FC7\u6D59\u6C5F\u957F\u5174\u53BF\u4E1E\uFF0C\u56E0\u4E0D\u80AF\u5C48\u8EAB\u9022\u8FCE\u800C\u8F9E\u5B98\uFF0C\u540E\u6765\u53C8\u505A\u8FC7\u8346\u738B\u5E9C\u7684\u7EAA\u5584\u3002\u665A\u5E74\u5F52\u5C45\u4E61\u91CC\uFF0C\u653E\u6D6A\u8BD7\u9152\uFF0C\u8D2B\u8001\u4EE5\u7EC8\uFF0C\u8457\u6709\u8BD7\u6587\u96C6\u300A\u5C04\u9633\u5148\u751F\u5B58\u7A3F\u300B\u3002\u4ED6\u4E00\u751F\u5728\u79D1\u4E3E\u4E0E\u5B98\u573A\u4E0A\u90FD\u4E0D\u5F97\u610F\u3002",
      "## \u5929\u5EAD\u4E3A\u4EC0\u4E48\u5199\u5F97\u50CF\u5B98\u573A",
      "\u4ED6\u81EA\u5C0F\u300C\u597D\u5947\u95FB\u300D\uFF0C\u7231\u8BFB\u91CE\u8A00\u7A17\u53F2\uFF0C\u8FD9\u4E3A\u5199\u795E\u9B54\u5C0F\u8BF4\u51C6\u5907\u4E86\u6750\u6599\uFF1B\u800C\u4ED6\u81EA\u5DF1\u7684\u5931\u610F\uFF0C\u5219\u4E3A\u8FD9\u90E8\u4E66\u51C6\u5907\u4E86\u773C\u5149\u3002\u5B59\u609F\u7A7A\u8BA8\u6765\u7684\u300C\u9F50\u5929\u5927\u5723\u300D\u53EA\u662F\u4E00\u4E2A\u7A7A\u540D\u53F7\uFF0C\u7389\u5E1D\u628A\u4ED6\u6D3E\u53BB\u770B\u7BA1\u87E0\u6843\u56ED\uFF1B\u4E00\u573A\u87E0\u6843\u4F1A\u7684\u8BF7\u5E16\uFF0C\u5C31\u628A\u7B49\u7EA7\u3001\u6392\u573A\u4E0E\u4EBA\u60C5\u5199\u5F97\u6E05\u6E05\u695A\u695A\uFF1B\u53D6\u7ECF\u8DEF\u4E0A\uFF0C\u6709\u80CC\u666F\u7684\u5996\u602A\u5230\u672B\u4E86\u90FD\u88AB\u4E3B\u4EBA\u6536\u8D70\uFF0C\u6CA1\u80CC\u666F\u7684\u624D\u88AB\u6253\u6B7B\u3002\u5929\u5EAD\u7684\u7ED3\u6784\u3001\u540D\u5206\u7684\u865A\u5B9E\u3001\u529E\u4E8B\u7684\u89C4\u77E9\uFF0C\u4E0E\u4EBA\u95F4\u5B98\u573A\u51E0\u4E4E\u4E00\u6837\u3002\u8BFB\u8FD9\u4E9B\u6BB5\u843D\u65F6\uFF0C\u5F88\u96BE\u4E0D\u60F3\u5230\u4F5C\u8005\u81EA\u5DF1\u7684\u7ECF\u5386\u3002",
      "## \u300C\u4F5C\u8005\u662F\u8C01\u300D\u7684\u4E00\u6BB5\u516C\u6848",
      "\u73B0\u5B58\u6700\u65E9\u520A\u672C\u662F\u660E\u4E07\u5386\u4E8C\u5341\u5E74\uFF081592 \u5E74\uFF09\u91D1\u9675\u4E16\u5FB7\u5802\u520A\u300A\u65B0\u523B\u51FA\u50CF\u5B98\u677F\u5927\u5B57\u897F\u6E38\u8BB0\u300B\uFF0C\u4E00\u767E\u56DE\uFF0C\u7F72\u300C\u534E\u9633\u6D1E\u5929\u4E3B\u4EBA\u6821\u300D\uFF0C\u5E76\u6CA1\u6709\u7F72\u5434\u627F\u6069\u7684\u540D\u5B57\u3002\u6E05\u521D\u7684\u300A\u897F\u6E38\u8BC1\u9053\u4E66\u300B\u751A\u81F3\u628A\u5B83\u9898\u5728\u5143\u4EE3\u9053\u58EB\u4E18\u5904\u673A\u540D\u4E0B\u3002\u76F4\u5230\u6E05\u4EE3\u5434\u7389\u6422\u300A\u5C71\u9633\u5FD7\u9057\u300B\u3001\u962E\u8475\u751F\u300A\u8336\u4F59\u5BA2\u8BDD\u300B\u7B49\u4E66\u63D0\u51FA\u4F5C\u8005\u5E94\u662F\u5434\u627F\u6069\uFF0C\u518D\u7ECF\u9C81\u8FC5\u300A\u4E2D\u56FD\u5C0F\u8BF4\u53F2\u7565\u300B\u4E0E\u80E1\u9002\u300A\u897F\u6E38\u8BB0\u8003\u8BC1\u300B\u7684\u8003\u8BA2\uFF0C\u5434\u627F\u6069\u8457\u300A\u897F\u6E38\u8BB0\u300B\u624D\u6210\u4E3A\u901A\u884C\u8BF4\u6CD5\u3002\u4E25\u683C\u8BF4\u6765\uFF0C\u8FD9\u4E2A\u95EE\u9898\u5728\u5B66\u754C\u4ECD\u6709\u8BA8\u8BBA\u3002",
      "## \u8BFB\u8FD9\u672C\u4E66\u7684\u63D0\u793A",
      "\u77E5\u9053\u53F2\u5B9E\u4E0E\u865A\u6784\u4E4B\u95F4\u7684\u8DDD\u79BB\uFF0C\u624D\u80FD\u660E\u767D\u8FD9\u672C\u4E66\u7684\u5206\u5BF8\uFF1A\u7384\u5958\u7684\u5341\u4E03\u5E74\u662F\u771F\u4E8B\uFF0C\u5B59\u609F\u7A7A\u7684\u91D1\u7B8D\u68D2\u662F\u60F3\u8C61\uFF1B\u4F5C\u8005\u5728\u795E\u9B54\u7684\u6E38\u620F\u7B14\u58A8\u91CC\u653E\u8FDB\u5BF9\u73B0\u5B9E\u7684\u89C2\u5BDF\uFF0C\u4F46\u4E0D\u7B49\u4E8E\u6BCF\u4E00\u4E2A\u5996\u602A\u90FD\u5BF9\u5E94\u67D0\u4E2A\u5177\u4F53\u7684\u4EBA\u3002\u80E1\u9002\u66FE\u8BF4\u300A\u897F\u6E38\u8BB0\u300B\u91CC\u79CD\u79CD\u795E\u8BDD\u300C\u90FD\u5E26\u7740\u4E00\u70B9\u8BD9\u8C10\u610F\u5473\uFF0C\u80FD\u4F7F\u4EBA\u5F00\u53E3\u4E00\u7B11\u300D\u2014\u2014\u7B11\uFF0C\u672C\u8EAB\u5C31\u662F\u8FD9\u90E8\u4E66\u7684\u6001\u5EA6\u3002\u8BFB\u7684\u65F6\u5019\u65E2\u8981\u80FD\u5728\u7B11\u58F0\u91CC\u770B\u51FA\u4E16\u60C5\uFF0C\u4E5F\u4E0D\u5FC5\u5904\u5904\u5750\u5B9E\uFF0C\u628A\u795E\u8BDD\u8BFB\u6210\u5F71\u5C04\u3002"
    ],
    think: [
      "\u5B59\u609F\u7A7A\u88AB\u5C01\u300C\u9F50\u5929\u5927\u5723\u300D\u5374\u53EA\u88AB\u6D3E\u53BB\u7BA1\u87E0\u6843\u56ED\uFF0C\u8FD9\u4E2A\u5B89\u6392\u8BA9\u4F60\u8054\u60F3\u5230\u73B0\u5B9E\u4E2D\u7684\u4EC0\u4E48\u73B0\u8C61\uFF1F",
      "\u53D6\u7ECF\u8DEF\u4E0A\u300C\u6709\u80CC\u666F\u7684\u5996\u602A\u90FD\u88AB\u4E3B\u4EBA\u6536\u8D70\uFF0C\u6CA1\u80CC\u666F\u7684\u624D\u88AB\u6253\u6B7B\u300D\uFF0C\u4F5C\u8005\u8FD9\u6837\u5199\u53EF\u80FD\u60F3\u8BF4\u4EC0\u4E48\uFF1F",
      "\u300A\u897F\u6E38\u8BB0\u300B\u7684\u4F5C\u8005\u81F3\u4ECA\u4ECD\u6709\u4E89\u8BAE\uFF0C\u6211\u4EEC\u5728\u5F15\u7528\u300C\u5434\u627F\u6069\u8457\u300D\u65F6\u5E94\u8BE5\u4FDD\u6301\u4EC0\u4E48\u6001\u5EA6\uFF1F"
    ]
  },
  {
    id: "ext-bg-luotuoxiangzi",
    moduleId: "literature",
    entryId: "l-luotuoxiangzi",
    grade: "7b",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u300A\u9A86\u9A7C\u7965\u5B50\u300B\u662F\u600E\u4E48\u300C\u542C\u300D\u51FA\u6765\u7684",
    summary: "1936 \u5E74\u8001\u820D\u5728\u9752\u5C9B\u542C\u4E24\u4F4D\u8F66\u592B\u7684\u6545\u4E8B\uFF0C\u628A\u4E09\u8D77\u4E09\u843D\u4E0E\u7275\u56DE\u9A86\u9A7C\u5408\u6210\u4E86\u7965\u5B50\u3002",
    content: [
      "## \u4E24\u4E2A\u8F66\u592B\u7684\u6545\u4E8B\u78B0\u5728\u4E00\u5904",
      "1936 \u5E74\u6625\u5929\uFF0C\u8001\u820D\u6B63\u5728\u9752\u5C9B\u7684\u56FD\u7ACB\u5C71\u4E1C\u5927\u5B66\u4EFB\u6559\u3002\u4ED6\u540E\u6765\u5728\u300A\u6211\u600E\u6837\u5199\u3008\u9A86\u9A7C\u7965\u5B50\u3009\u300B\u4E2D\u56DE\u5FC6\uFF1A\u4E00\u4F4D\u670B\u53CB\u8C08\u8D77\u81EA\u5DF1\u96C7\u7528\u8FC7\u7684\u4E00\u4E2A\u8F66\u592B\uFF0C\u90A3\u4E2A\u8F66\u592B\u81EA\u5DF1\u4E70\u4E86\u8F66\uFF0C\u53C8\u5356\u6389\uFF0C\u5982\u6B64\u4E09\u8D77\u4E09\u843D\uFF0C\u5230\u672B\u4E86\u8FD8\u662F\u53D7\u7A77\uFF1B\u670B\u53CB\u53C8\u8BF4\u8D77\u53E6\u4E00\u4E2A\u8F66\u592B\uFF0C\u88AB\u519B\u961F\u6293\u4E86\u53BB\uFF0C\u54EA\u77E5\u8F6C\u7978\u4E3A\u798F\uFF0C\u8D81\u519B\u961F\u79FB\u52A8\u4E4B\u9645\u5077\u5077\u7275\u56DE\u4E09\u5339\u9A86\u9A7C\u3002\u8001\u820D\u8BF4\uFF0C\u5C31\u662F\u8FD9\u4E24\u4EF6\u4E8B\u78B0\u5728\u4E00\u8D77\uFF0C\u8BA9\u4ED6\u60F3\u51FA\u4E86\u7965\u5B50\u8FD9\u6837\u4E00\u4E2A\u4EBA\u7269\u3002\u4E00\u90E8\u6770\u4F5C\u7684\u8D77\u70B9\uFF0C\u662F\u4E24\u6BB5\u95F2\u8C08\u3002",
      "## \u5341\u51E0\u5E74\u89C2\u5BDF\u624D\u6562\u52A8\u7B14",
      "\u95F2\u8C08\u53EA\u662F\u5F15\u5B50\u3002\u8001\u820D 1930 \u5E74\u56DE\u56FD\u540E\uFF0C1930 \u5E74\u81F3 1934 \u5E74\u5728\u6D4E\u5357\u9F50\u9C81\u5927\u5B66\u4EFB\u6559\uFF0C1934 \u5E74\u81F3 1937 \u5E74\u53D7\u8058\u4E8E\u9752\u5C9B\u7684\u56FD\u7ACB\u5C71\u4E1C\u5927\u5B66\uFF0C\u957F\u671F\u751F\u6D3B\u5728\u5317\u65B9\u57CE\u5E02\u7684\u4E0B\u5C42\u793E\u4F1A\u4E2D\u95F4\u3002\u4ED6\u8BF4\u81EA\u5DF1\u662F\u56E0\u4E3A\u79EF\u4E86\u5341\u51E0\u5E74\u5BF9\u6D0B\u8F66\u592B\u751F\u6D3B\u7684\u89C2\u5BDF\uFF0C\u624D\u6562\u5199\u8FD9\u90E8\u5C0F\u8BF4\uFF1B\u4ED6\u8981\u89C2\u5BDF\u7684\u5DF2\u7ECF\u4E0D\u53EA\u662F\u8F66\u592B\u8863\u51A0\u4E0A\u3001\u8A00\u8BED\u4E0A\u3001\u59FF\u6001\u4E0A\u7684\u5C0F\u4E8B\uFF0C\u800C\u662F\u300C\u7531\u8F66\u592B\u7684\u5185\u5FC3\u72B6\u6001\u89C2\u5BDF\u5230\u5730\u72F1\u7A76\u7ADF\u662F\u4EC0\u4E48\u6837\u5B50\u300D\u3002\u8FD9\u53E5\u81EA\u8FF0\u70B9\u660E\u4E86\u5168\u4E66\u7684\u5199\u6CD5\uFF1A\u4E0D\u53EA\u5199\u7A77\uFF0C\u8FD8\u8981\u5199\u7A77\u5982\u4F55\u6539\u53D8\u4E00\u4E2A\u4EBA\u3002",
      "## \u300C\u9A86\u9A7C\u300D\u8FD9\u4E2A\u5916\u53F7\u662F\u600E\u4E48\u6765\u7684",
      "\u5C0F\u8BF4\u91CC\u7965\u5B50\u88AB\u6293\u592B\u7684\u5927\u5175\u8FDE\u4EBA\u5E26\u8F66\u4E00\u8D77\u6349\u8D70\uFF0C\u591C\u91CC\u9003\u51FA\u519B\u8425\u65F6\u987A\u624B\u7275\u56DE\u4E09\u5339\u9A86\u9A7C\uFF0C\u5356\u4E86\u4E09\u5341\u4E94\u5757\u94B1\u3002\u4ED6\u5927\u75C5\u4E00\u573A\uFF0C\u660F\u8FF7\u4E2D\u8BF4\u68A6\u8BDD\u63D0\u5230\u9A86\u9A7C\uFF0C\u4ECE\u6B64\u5F97\u4E86\u300C\u9A86\u9A7C\u7965\u5B50\u300D\u7684\u5916\u53F7\u3002\u8FD9\u4E2A\u5916\u53F7\u672C\u8EAB\u5C31\u662F\u4ED6\u7B2C\u4E00\u6B21\u7834\u4EA7\u7559\u4E0B\u7684\u5370\u8BB0\uFF1A\u4E00\u4E2A\u4EBA\u62FC\u4E86\u4E09\u5E74\u4E70\u6765\u7684\u8F66\u6CA1\u6709\u4E86\uFF0C\u53EA\u5269\u4E00\u4E2A\u8DDF\u9A86\u9A7C\u8FDE\u5728\u4E00\u8D77\u7684\u540D\u5B57\u3002\u8001\u820D\u4E3A\u4EC0\u4E48\u7ED9\u4E3B\u4EBA\u516C\u53D6\u8FD9\u6837\u4E00\u4E2A\u7EF0\u53F7\uFF0C\u503C\u5F97\u5728\u9605\u8BFB\u65F6\u7422\u78E8\u3002",
      "## \u4E09\u8D77\u4E09\u843D\u7684\u73B0\u5B9E\u4F9D\u636E",
      "\u5C0F\u8BF4\u4E2D\u7684\u4E09\u6B21\u5E0C\u671B\u4E0E\u4E09\u6B21\u7834\u706D\uFF0C\u6869\u6869\u90FD\u6709\u65F6\u4EE3\u7684\u5F71\u5B50\uFF1A\u7B2C\u4E00\u6B21\u4E70\u7684\u65B0\u8F66\u88AB\u5927\u5175\u62A2\u8D70\uFF1B\u7B2C\u4E8C\u6B21\u6512\u4E0B\u7684\u94B1\u88AB\u5B59\u4FA6\u63A2\u6572\u8BC8\u4E00\u7A7A\uFF1B\u7B2C\u4E09\u6B21\u662F\u864E\u599E\u51FA\u94B1\u4E70\u4E86\u8F66\uFF0C\u864E\u599E\u96BE\u4EA7\u6B7B\u540E\uFF0C\u4ED6\u53EA\u80FD\u5356\u8F66\u529E\u4E27\u4E8B\uFF1B\u6700\u540E\u5C0F\u798F\u5B50\u4E0A\u540A\u81EA\u6740\uFF0C\u538B\u57AE\u4E86\u4ED6\u6700\u540E\u4E00\u70B9\u5FF5\u60F3\u3002\u65E7\u5317\u5E73\u7684\u6D0B\u8F66\u592B\u8981\u9762\u5BF9\u7684\uFF0C\u6B63\u662F\u5175\u707E\u3001\u4FA6\u63A2\u7684\u52D2\u7D22\u3001\u8F66\u5382\u4E3B\u7684\u76D8\u5265\u3001\u75BE\u75C5\u4E0E\u4E27\u846C\u7684\u6C89\u91CD\u5F00\u9500\u3002\u8001\u820D\u628A\u8FD9\u4E00\u6574\u5957\u73B0\u5B9E\u7684\u6324\u538B\uFF0C\u96C6\u4E2D\u5230\u4E00\u4E2A\u4EBA\u8EAB\u4E0A\u5199\u3002",
      "## \u4E66\u91CC\u4E66\u5916\u90FD\u5728\u52A8\u8361",
      "1936 \u5E74 9 \u6708\uFF0C\u300A\u9A86\u9A7C\u7965\u5B50\u300B\u5F00\u59CB\u5728\u300A\u5B87\u5B99\u98CE\u300B\u534A\u6708\u520A\u4E0A\u8FDE\u8F7D\uFF0C1937 \u5E74 10 \u6708\u7EED\u5B8C\uFF1B1939 \u5E74\u7531\u4E0A\u6D77\u4EBA\u95F4\u4E66\u5C4B\u51FA\u7248\u5355\u884C\u672C\u3002\u5C31\u5728\u5199\u4F5C\u4E0E\u8FDE\u8F7D\u4E4B\u95F4\uFF0C1937 \u5E74 8 \u6708\u8001\u820D\u79BB\u5F00\u9752\u5C9B\uFF0C11 \u6708\u6D4E\u5357\u6CA6\u9677\u524D\u53EA\u8EAB\u5357\u4E0B\u6B66\u6C49\uFF0C\u4ECE\u6B64\u4E0E\u7559\u5728\u6D4E\u5357\u7684\u5BB6\u4EBA\u5206\u9694\u4E24\u5730\u3002\u6297\u6218\u7684\u6D2A\u6D41\u628A\u4E00\u4E2A\u5199\u5317\u5E73\u8F66\u592B\u7684\u4F5C\u5BB6\u51B2\u5230\u4E86\u5357\u65B9\u3002\u73B0\u5B9E\u4E2D\u7684\u52A8\u8361\u4E0E\u5C0F\u8BF4\u91CC\u7684\u4E0B\u5760\uFF0C\u5728\u65F6\u95F4\u4E0A\u662F\u91CD\u5408\u7684\u3002",
      "## \u7ED3\u5C3E\u90A3\u53E5\u8BDD\u4E3A\u4EC0\u4E48\u6C89\u91CD",
      "\u5C0F\u8BF4\u7684\u7ED3\u5C3E\u7ED9\u7965\u5B50\u7684\u5B9A\u8BBA\u662F\uFF1A\u4ED6\u6210\u4E86\u300C\u5815\u843D\u7684\u3001\u81EA\u79C1\u7684\u3001\u4E0D\u5E78\u7684\u3001\u793E\u4F1A\u75C5\u80CE\u91CC\u7684\u4EA7\u513F\uFF0C\u4E2A\u4EBA\u4E3B\u4E49\u7684\u672B\u8DEF\u9B3C\u300D\u3002\u8FD9\u4E2A\u53E5\u5B50\u6709\u4E24\u5C42\u950B\u5203\uFF1A\u4E00\u5C42\u6307\u5411\u793E\u4F1A\u2014\u2014\u90A3\u4E2A\u793E\u4F1A\u300C\u4E0D\u8BA9\u597D\u4EBA\u6709\u51FA\u8DEF\u300D\uFF1B\u4E00\u5C42\u6307\u5411\u4E2A\u4EBA\u2014\u2014\u9760\u4E00\u5DF1\u4E4B\u529B\u4E70\u8F66\u3001\u9760\u4E2A\u4EBA\u594B\u6597\u7FFB\u8EAB\u7684\u9053\u8DEF\u672C\u6765\u5C31\u8D70\u4E0D\u901A\u3002\u77E5\u9053\u4E86\u7965\u5B50\u7684\u539F\u578B\u6765\u81EA\u4E24\u6BB5\u771F\u5B9E\u7684\u95F2\u8C08\uFF0C\u518D\u770B\u8FD9\u4E2A\u7ED3\u5C3E\uFF0C\u5C31\u80FD\u660E\u767D\u8001\u820D\u5199\u7684\u4E0D\u662F\u4E00\u4E2A\u4EBA\u7684\u5815\u843D\uFF0C\u800C\u662F\u4E00\u6574\u4EE3\u5E95\u5C42\u52B3\u52A8\u8005\u7684\u65E0\u8DEF\u53EF\u8D70\u3002"
    ],
    think: [
      "\u8001\u820D\u53EA\u542C\u4E86\u4E24\u4E2A\u8F66\u592B\u7684\u6545\u4E8B\uFF0C\u5C31\u5199\u51FA\u4E00\u90E8\u6770\u4F5C\uFF0C\u8FD9\u9760\u7684\u662F\u4EC0\u4E48\u6837\u7684\u51C6\u5907\uFF1F\u5BF9\u4F60\u5199\u4F5C\u6587\u6709\u4EC0\u4E48\u542F\u53D1\uFF1F",
      "\u7965\u5B50\u7684\u5916\u53F7\u6765\u81EA\u4E00\u6B21\u7834\u4EA7\u3002\u5982\u679C\u8BA9\u4F60\u4E3A\u4ED6\u53E6\u53D6\u4E00\u4E2A\u5916\u53F7\uFF0C\u4F60\u4F1A\u53D6\u4EC0\u4E48\uFF1F\u8BF7\u8BF4\u660E\u7406\u7531\u3002",
      "\u8001\u820D\u8BF4\u4ED6\u8981\u300C\u7531\u8F66\u592B\u7684\u5185\u5FC3\u72B6\u6001\u89C2\u5BDF\u5230\u5730\u72F1\u7A76\u7ADF\u662F\u4EC0\u4E48\u6837\u5B50\u300D\u3002\u4F60\u8BA4\u4E3A\u5C0F\u8BF4\u4E2D\u54EA\u4E00\u5904\u6700\u50CF\u300C\u5730\u72F1\u300D\uFF1F"
    ]
  },
  {
    id: "ext-bg-gangtie",
    moduleId: "literature",
    entryId: "l-gangtie",
    grade: "7b",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u300A\u94A2\u94C1\u662F\u600E\u6837\u70BC\u6210\u7684\u300B\u662F\u53E3\u8FF0\u51FA\u6765\u7684",
    summary: "\u5965\u65AF\u7279\u6D1B\u592B\u65AF\u57FA\u53CC\u76EE\u5931\u660E\u3001\u5168\u8EAB\u762B\u75EA\u540E\u9760\u523B\u5B57\u677F\u4E0E\u53E3\u8FF0\u5B8C\u6210\u5C0F\u8BF4\uFF0C\u4FDD\u5C14\u7684\u7ECF\u5386\u5927\u534A\u662F\u4ED6\u7684\u81EA\u4F20\u3002",
    content: [
      "## \u4E00\u4E2A\u4E09\u5341\u4E8C\u5C81\u5C31\u53BB\u4E16\u7684\u4F5C\u5BB6",
      "\u5C3C\u53E4\u62C9\xB7\u5965\u65AF\u7279\u6D1B\u592B\u65AF\u57FA\uFF081904 \u2014 1936\uFF09\u51FA\u751F\u4E8E\u4E4C\u514B\u5170\u7684\u4E00\u4E2A\u5DE5\u4EBA\u5BB6\u5EAD\uFF0C\u7236\u4EB2\u5728\u917F\u9152\u5382\u505A\u5DE5\u30021919 \u5E74\u4ED6\u52A0\u5165\u5171\u9752\u56E2\uFF0C1920 \u5E74\u5728\u4E0E\u6CE2\u5170\u519B\u961F\u4F5C\u6218\u65F6\u8D1F\u91CD\u4F24\uFF0C\u5F39\u7247\u4F24\u53CA\u5934\u90E8\u548C\u8179\u90E8\uFF0C\u53F3\u773C\u56E0\u6B64\u5931\u660E\uFF1B1924 \u5E74\u52A0\u5165\u5171\u4EA7\u515A\u3002\u6B64\u540E\u4ED6\u7684\u5065\u5EB7\u6301\u7EED\u6076\u5316\uFF1A1927 \u5E74\u5168\u8EAB\u762B\u75EA\uFF0C1928 \u5E74\u53CC\u76EE\u5931\u660E\u30021936 \u5E74 12 \u6708 22 \u65E5\u4ED6\u75C5\u901D\u4E8E\u83AB\u65AF\u79D1\uFF0C\u5E74\u4EC5\u4E09\u5341\u4E8C\u5C81\u3002\u4ED6\u4E00\u751F\u771F\u6B63\u5065\u5EB7\u7684\u65F6\u95F4\uFF0C\u53EA\u6709\u4E8C\u5341\u5C81\u4EE5\u524D\u7684\u90A3\u51E0\u5E74\u3002",
      "## \u4ECE\u4FEE\u94C1\u8DEF\u5230\u762B\u75EA\u5931\u660E",
      "1921 \u5E74\u79CB\uFF0C\u4ED6\u53C2\u52A0\u62A2\u4FEE\u57FA\u8F85\u9644\u8FD1\u535A\u4E9A\u5C14\u5361\u7684\u7A84\u8F68\u94C1\u8DEF\uFF0C\u5728\u4E25\u5BD2\u4E0E\u9965\u997F\u4E2D\u52B3\u52A8\uFF0C\u67D3\u4E0A\u4F24\u5BD2\u548C\u98CE\u6E7F\u75C5\uFF1B\u8FD9\u6BB5\u7ECF\u5386\u88AB\u51E0\u4E4E\u539F\u6837\u5199\u8FDB\u5C0F\u8BF4\u2014\u2014\u4FDD\u5C14\u5728\u7B51\u8DEF\u5DE5\u5730\u4E0A\u5012\u4E0B\uFF0C\u6B64\u540E\u8EAB\u4F53\u4E00\u6B65\u4E00\u6B65\u57AE\u6389\u3002\u5C0F\u8BF4\u91CC\u4FDD\u5C14\u505A\u8F66\u7AD9\u98DF\u5802\u7684\u5C0F\u5DE5\u3001\u53C2\u52A0\u7EA2\u519B\u3001\u8D1F\u4F24\u3001\u4FEE\u8DEF\u3001\u5931\u660E\u3001\u5199\u4F5C\uFF0C\u4E0E\u4F5C\u8005\u672C\u4EBA\u7684\u7ECF\u5386\u9AD8\u5EA6\u91CD\u5408\u3002\u6240\u4EE5\u8BFB\u300A\u94A2\u94C1\u662F\u600E\u6837\u70BC\u6210\u7684\u300B\u65F6\uFF0C\u53EF\u4EE5\u628A\u4FDD\u5C14\u770B\u4F5C\u4F5C\u8005\u7684\u81EA\u6211\u5199\u7167\uFF0C\u800C\u4E0D\u662F\u51ED\u7A7A\u5851\u9020\u7684\u82F1\u96C4\u3002",
      "## \u7528\u523B\u5B57\u677F\u5199\u4F5C\u7684\u8EAB\u4F53",
      "1930 \u5E74\u8FC1\u5C45\u83AB\u65AF\u79D1\u540E\uFF0C\u4ED6\u5F00\u59CB\u5199\u8FD9\u90E8\u5C0F\u8BF4\u3002\u624B\u4E0D\u80FD\u52A8\u3001\u773C\u4E0D\u80FD\u770B\uFF0C\u4ED6\u5C31\u7528\u786C\u7EB8\u677F\u523B\u51FA\u9542\u7A7A\u7684\u5B57\u6BCD\uFF0C\u628A\u94C5\u7B14\u5D4C\u5728\u5B57\u6BCD\u69FD\u91CC\uFF0C\u4E00\u4E2A\u5B57\u6BCD\u4E00\u4E2A\u5B57\u6BCD\u5730\u6478\u7D22\u7740\u5199\uFF1B\u540E\u6765\u8FDE\u8FD9\u6837\u5199\u4E5F\u652F\u6491\u4E0D\u4F4F\uFF0C\u53EA\u80FD\u53E3\u8FF0\uFF0C\u7531\u59BB\u5B50\u8D56\u838E\u548C\u53CB\u4EBA\u8BB0\u5F55\u6574\u7406\u3002\u4ED6\u8BF4\u8FC7\uFF0C\u53EA\u8981\u5FC3\u810F\u8FD8\u5728\u8DF3\u52A8\uFF0C\u5C31\u7EDD\u4E0D\u80FD\u505C\u6B62\u5DE5\u4F5C\u3002\u4E86\u89E3\u8FD9\u4E00\u5C42\uFF0C\u518D\u8BFB\u4FDD\u5C14\u5931\u660E\u540E\u575A\u6301\u5199\u4F5C\u7684\u60C5\u8282\uFF0C\u5C31\u80FD\u4F53\u4F1A\u90A3\u4E0D\u53EA\u662F\u6545\u4E8B\u91CC\u7684\u575A\u5F3A\uFF0C\u800C\u662F\u4E00\u79CD\u771F\u5B9E\u7684\u5199\u4F5C\u65B9\u5F0F\u3002",
      "## \u51FA\u7248\u4E0E\u8363\u8A89",
      "\u5C0F\u8BF4\u7B2C\u4E00\u90E8\u4E8E 1932 \u5E74\u5728\u300A\u9752\u5E74\u8FD1\u536B\u519B\u300B\u6742\u5FD7\u4E0A\u8FDE\u8F7D\uFF0C\u7B2C\u4E8C\u90E8\u4E8E 1934 \u5E74\u95EE\u4E16\u30021934 \u5E74\u4ED6\u52A0\u5165\u82CF\u8054\u4F5C\u5BB6\u534F\u4F1A\uFF0C1935 \u5E74 10 \u6708\u83B7\u5217\u5B81\u52CB\u7AE0\u3002\u4ED6\u8FD8\u4EE5\u53E3\u8FF0\u65B9\u5F0F\u5199\u4F5C\u957F\u7BC7\u5C0F\u8BF4\u300A\u66B4\u98CE\u96E8\u6240\u8BDE\u751F\u7684\u300B\uFF0C\u53EA\u5B8C\u6210\u7B2C\u4E00\u5377\u4FBF\u53BB\u4E16\u4E86\u3002\u4E00\u4E2A\u762B\u75EA\u5931\u660E\u7684\u4EBA\uFF0C\u9760\u522B\u4EBA\u7684\u624B\u548C\u7EB8\u7B14\uFF0C\u5728\u751F\u547D\u7684\u6700\u540E\u51E0\u5E74\u5B8C\u6210\u4E86\u4E24\u90E8\u4F5C\u54C1\u2014\u2014\u8FD9\u672C\u8EAB\u5C31\u662F\u5BF9\u300C\u94A2\u94C1\u662F\u600E\u6837\u70BC\u6210\u7684\u300D\u8FD9\u4E2A\u4E66\u540D\u7684\u8BF4\u660E\u3002",
      "## \u4E66\u540D\u91CC\u90A3\u4E2A\u6BD4\u55BB",
      "\u94A2\u8981\u7ECF\u8FC7\u9AD8\u6E29\u7194\u70BC\u548C\u53CD\u590D\u953B\u6253\u624D\u80FD\u6210\u5F62\uFF0C\u4EBA\u7684\u610F\u5FD7\u8981\u5728\u82E6\u96BE\u91CC\u5B9A\u5F62\u3002\u4FDD\u5C14\u6CA1\u6709\u8BFB\u8FC7\u591A\u5C11\u4E66\uFF0C\u4E5F\u6CA1\u6709\u663E\u8D6B\u7684\u51FA\u8EAB\uFF0C\u4ED6\u7684\u300C\u6210\u94A2\u300D\u8FC7\u7A0B\u5C31\u662F\u88AB\u4E00\u6B21\u6B21\u6253\u51FB\u2014\u2014\u6218\u4E89\u4E2D\u7684\u4F24\u3001\u7B51\u8DEF\u65F6\u7684\u75C5\u3001\u5931\u660E\u3001\u762B\u75EA\u2014\u2014\u53CD\u590D\u9524\u6253\u7684\u8FC7\u7A0B\u3002\u4E66\u540D\u7528\u7684\u662F\u4E00\u4E2A\u65E2\u6734\u7D20\u53C8\u51C6\u786E\u7684\u6BD4\u55BB\uFF1A\u4E0D\u662F\u5929\u751F\u7684\u575A\u786C\uFF0C\u800C\u662F\u88AB\u953B\u9020\u51FA\u6765\u7684\u575A\u786C\u3002\u7406\u89E3\u4E86\u8FD9\u4E2A\u6BD4\u55BB\uFF0C\u4E5F\u5C31\u7406\u89E3\u4E86\u6574\u672C\u4E66\u4E3A\u4EC0\u4E48\u8981\u628A\u82E6\u96BE\u5199\u5F97\u90A3\u6837\u7EC6\u81F4\u3002",
      "## \u5728\u4E2D\u56FD\uFF1A\u4E00\u53E5\u8BDD\u5F71\u54CD\u4E86\u51E0\u4EE3\u4EBA",
      "1942 \u5E74\uFF0C\u6885\u76CA\u6839\u636E\u82F1\u6587\u8BD1\u672C\u8F6C\u8BD1\u7684\u5168\u8BD1\u672C\u7531\u4E0A\u6D77\u65B0\u77E5\u4E66\u5E97\u51FA\u7248\uFF0C\u8FD9\u662F\u5F71\u54CD\u6700\u5927\u7684\u4E2D\u8BD1\u672C\uFF0C\u6B64\u540E\u300C\u94A2\u94C1\u662F\u600E\u6837\u70BC\u6210\u7684\u300D\u6210\u4E86\u51E0\u4EE3\u4E2D\u56FD\u9752\u5E74\u7684\u8BFB\u7269\u3002\u4E66\u4E2D\u90A3\u6BB5\u8BDD\u6700\u6709\u540D\uFF1A\u300C\u4EBA\u6700\u5B9D\u8D35\u7684\u4E1C\u897F\u662F\u751F\u547D\u3002\u751F\u547D\u5BF9\u4E8E\u6211\u4EEC\u53EA\u6709\u4E00\u6B21\u3002\u4E00\u4E2A\u4EBA\u7684\u751F\u547D\u5E94\u5F53\u8FD9\u6837\u5EA6\u8FC7\uFF1A\u5F53\u4ED6\u56DE\u9996\u5F80\u4E8B\u7684\u65F6\u5019\uFF0C\u4E0D\u56E0\u865A\u5EA6\u5E74\u534E\u800C\u6094\u6068\uFF0C\u4E5F\u4E0D\u56E0\u788C\u788C\u65E0\u4E3A\u800C\u7F9E\u803B\u3002\u300D\u77E5\u9053\u5199\u4E0B\u8FD9\u4E9B\u8BDD\u7684\u4EBA\u5F53\u65F6\u6B63\u762B\u75EA\u5728\u5E8A\u3001\u53CC\u76EE\u5931\u660E\uFF0C\u8FD9\u53E5\u8BDD\u5C31\u4E0D\u518D\u662F\u4E00\u53E5\u53E3\u53F7\uFF0C\u800C\u662F\u4E00\u4EFD\u7528\u8EAB\u4F53\u6362\u6765\u7684\u81EA\u767D\u3002"
    ],
    think: [
      "\u77E5\u9053\u8FD9\u672C\u4E66\u662F\u53E3\u8FF0\u5B8C\u6210\u7684\u4E4B\u540E\uFF0C\u4F60\u91CD\u8BFB\u4FDD\u5C14\u7B51\u8DEF\u90A3\u4E00\u6BB5\uFF0C\u611F\u53D7\u6709\u4EC0\u4E48\u4E0D\u540C\uFF1F",
      "\u4FDD\u5C14\u66FE\u5728\u6D77\u8FB9\u8BA4\u771F\u5730\u60F3\u8FC7\u7ED3\u675F\u81EA\u5DF1\uFF0C\u4F5C\u8005\u4E3A\u4EC0\u4E48\u8981\u628A\u8FD9\u4E2A\u5FF5\u5934\u5199\u51FA\u6765\uFF1F\u8FD9\u6BD4\u5851\u9020\u4E00\u4E2A\u6BEB\u65E0\u52A8\u6447\u7684\u82F1\u96C4\uFF0C\u6548\u679C\u6709\u4F55\u4E0D\u540C\uFF1F",
      "\u300C\u94A2\u94C1\u662F\u600E\u6837\u70BC\u6210\u7684\u300D\u8FD9\u4E2A\u6BD4\u55BB\uFF0C\u4ECA\u5929\u8FD8\u6210\u7ACB\u5417\uFF1F\u8BF7\u7ED3\u5408\u4E00\u4E2A\u4F60\u719F\u6089\u7684\u4EBA\u8BF4\u660E\u3002"
    ]
  },
  {
    id: "ext-bg-hongxing",
    moduleId: "literature",
    entryId: "l-hongxingzhaoyaozhongguo",
    grade: "8a",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u65AF\u8BFA\u662F\u600E\u6837\u8D70\u8FDB\u9655\u5317\u7EA2\u533A\u7684",
    summary: "1936 \u5E74\u65AF\u8BFA\u7A7F\u8D8A\u5C01\u9501\u8FDB\u5165\u9655\u5317\u4FDD\u5B89\uFF0C\u6210\u4E3A\u7B2C\u4E00\u4E2A\u91C7\u8BBF\u7EA2\u533A\u7684\u897F\u65B9\u8BB0\u8005\u3002",
    content: [
      "## \u957F\u8FBE\u4E5D\u5E74\u7684\u65B0\u95FB\u5C01\u9501",
      "1927 \u5E74\u4EE5\u540E\uFF0C\u5173\u4E8E\u4E2D\u56FD\u5171\u4EA7\u515A\u548C\u7EA2\u519B\u7684\u6D88\u606F\u957F\u671F\u88AB\u5C01\u9501\uFF0C\u5916\u754C\u6D41\u4F20\u7684\u591A\u662F\u300C\u571F\u532A\u300D\u4E4B\u7C7B\u7684\u8BF4\u6CD5\u4E0E\u6D41\u8A00\u3002\u57C3\u5FB7\u52A0\xB7\u65AF\u8BFA\uFF081905 \u2014 1972\uFF09\u662F\u7F8E\u56FD\u4EBA\uFF0C1928 \u5E74\u6765\u5230\u4E2D\u56FD\uFF0C\u4EFB\u300A\u5BC6\u52D2\u6C0F\u8BC4\u8BBA\u62A5\u300B\u52A9\u7406\u7F16\u8F91\uFF0C\u540E\u6765\u4E3A\u591A\u5BB6\u62A5\u520A\u505A\u8BB0\u8005\uFF1B1933 \u5E74\u81F3 1938 \u5E74\u5728\u71D5\u4EAC\u5927\u5B66\u4EFB\u6559\uFF0C\u4E0E\u9C81\u8FC5\u3001\u5B8B\u5E86\u9F84\u4EE5\u53CA\u8FDB\u6B65\u5B66\u751F\u6709\u4EA4\u5F80\uFF0C\u8FD8\u62A5\u9053\u8FC7 1935 \u5E74\u7684\u300C\u4E00\u4E8C\xB7\u4E5D\u300D\u8FD0\u52A8\u3002\u4ED6\u6BD4\u5F88\u591A\u5916\u56FD\u8BB0\u8005\u66F4\u6E05\u695A\uFF1A\u5173\u4E8E\u90A3\u7247\u88AB\u5C01\u9501\u7684\u533A\u57DF\uFF0C\u5916\u754C\u77E5\u9053\u7684\u51E0\u4E4E\u5168\u662F\u4F20\u95FB\u3002",
      "## \u4E00\u6B21\u79D8\u5BC6\u7684\u884C\u7A0B",
      "1936 \u5E74 6 \u6708\uFF0C\u7ECF\u5B8B\u5E86\u9F84\u4E0E\u4E2D\u5171\u65B9\u9762\u5B89\u6392\uFF0C\u65AF\u8BFA\u5E26\u7740\u4ECB\u7ECD\u4FE1\u4ECE\u5317\u5E73\u51FA\u53D1\uFF0C\u5148\u5230\u897F\u5B89\uFF0C\u7531\u8463\u5065\u543E\uFF08\u4E66\u4E2D\u79F0\u4E3A\u300C\u738B\u7267\u5E08\u300D\uFF09\u4E0E\u5218\u9F0E\u534F\u52A9\uFF0C\u4E58\u4E1C\u5317\u519B\u7684\u5361\u8F66\u5317\u4E0A\u30027 \u6708\u521D\u4ED6\u5230\u8FBE\u5B89\u585E\uFF0C\u89C1\u5230\u5468\u6069\u6765\uFF1B7 \u6708\u4E2D\u65EC\u5230\u8FBE\u5F53\u65F6\u4E2D\u5171\u4E2D\u592E\u6240\u5728\u5730\u4FDD\u5B89\uFF08\u4ECA\u9655\u897F\u5FD7\u4E39\u53BF\uFF09\u3002\u4ED6\u968F\u8EAB\u5E26\u7740\u7167\u76F8\u673A\u3001\u7B14\u8BB0\u672C\u548C\u4E00\u6279\u836F\u54C1\uFF0C\u6B64\u540E\u7684\u56DB\u4E2A\u6708\u91CC\uFF0C\u4ED6\u5728\u9655\u5317\u7684\u7A91\u6D1E\u4E0E\u5C71\u6C9F\u95F4\u8BBF\u95EE\u3001\u8BB0\u5F55\u3001\u62CD\u7167\u3002",
      "## \u7B2C\u4E00\u4E2A\u8FDB\u5165\u7EA2\u533A\u7684\u897F\u65B9\u8BB0\u8005",
      "\u65AF\u8BFA\u662F\u7B2C\u4E00\u4E2A\u8FDB\u5165\u9655\u7518\u5B81\u9769\u547D\u6839\u636E\u5730\u91C7\u8BBF\u7684\u897F\u65B9\u8BB0\u8005\u3002\u4ED6\u91C7\u8BBF\u4E86\u6BDB\u6CFD\u4E1C\u3001\u5468\u6069\u6765\u3001\u5F6D\u5FB7\u6000\u3001\u6797\u5F6A\u3001\u8D3A\u9F99\u3001\u5F90\u6D77\u4E1C\u3001\u5F90\u7279\u7ACB\u7B49\u7EA2\u519B\u9886\u5BFC\u4EBA\uFF0C\u4E5F\u8BBF\u95EE\u4E86\u666E\u901A\u6218\u58EB\u3001\u519C\u6C11\u548C\u88AB\u79F0\u4E3A\u300C\u7EA2\u5C0F\u9B3C\u300D\u7684\u5C11\u5E74\u3002\u4ED6\u5728\u4FDD\u5B89\u62CD\u4E0B\u5927\u91CF\u7167\u7247\uFF0C\u5176\u4E2D\u6700\u8457\u540D\u7684\u4E00\u5F20\uFF0C\u662F\u6BDB\u6CFD\u4E1C\u5934\u6234\u7EA2\u519B\u516B\u89D2\u5E3D\u7684\u534A\u8EAB\u50CF\u2014\u2014\u90A3\u9876\u5E3D\u5B50\u662F\u7EA2\u519B\u7684\u519B\u5E3D\uFF0C\u7167\u7247\u6210\u4E3A\u5168\u4E16\u754C\u8BA4\u8BC6\u4E2D\u56FD\u5171\u4EA7\u515A\u4EBA\u7684\u7ECF\u5178\u5F71\u50CF\u3002",
      "## \u6BDB\u6CFD\u4E1C\u7B2C\u4E00\u6B21\u5411\u5916\u4EBA\u8BB2\u81EA\u5DF1\u7684\u751F\u5E73",
      "\u5728\u4FDD\u5B89\u7684\u7A91\u6D1E\u91CC\uFF0C\u6BDB\u6CFD\u4E1C\u4E0E\u65AF\u8BFA\u591A\u6B21\u957F\u8C08\uFF0C\u6709\u65F6\u4E00\u8C08\u5C31\u662F\u4E00\u591C\u3002\u8FD9\u662F\u6BDB\u6CFD\u4E1C\u7B2C\u4E00\u6B21\u5B8C\u6574\u5730\u5411\u5916\u4EBA\u8BB2\u8FF0\u81EA\u5DF1\u7684\u7ECF\u5386\uFF1A\u7AE5\u5E74\u3001\u6C42\u5B66\u3001\u7EC4\u7EC7\u56E2\u4F53\u3001\u8D70\u4E0A\u9769\u547D\u9053\u8DEF\u7684\u7ECF\u8FC7\u3002\u65AF\u8BFA\u7684\u7B14\u8BB0\u540E\u6765\u88AB\u6574\u7406\u6210\u300A\u6BDB\u6CFD\u4E1C\u81EA\u4F20\u300B\u51FA\u7248\uFF0C\u81F3\u4ECA\u4ECD\u662F\u7814\u7A76\u6BDB\u6CFD\u4E1C\u65E9\u671F\u751F\u5E73\u6700\u91CD\u8981\u7684\u6750\u6599\u4E4B\u4E00\u3002\u4E00\u4F4D\u5916\u56FD\u8BB0\u8005\u7684\u91C7\u8BBF\u672C\uFF0C\u5C31\u8FD9\u6837\u4FDD\u5B58\u4E0B\u4E86\u4E00\u6BB5\u4E2D\u56FD\u4EBA\u81EA\u5DF1\u7684\u8BB0\u5FC6\u3002",
      "## \u4E00\u672C\u4E66\u7684\u8BDE\u751F\u4E0E\u6539\u540D",
      "1936 \u5E74 10 \u6708\u5E95\uFF0C\u65AF\u8BFA\u56DE\u5230\u5317\u5E73\uFF0C\u968F\u540E\u5728\u62A5\u520A\u4E0A\u9646\u7EED\u53D1\u8868\u62A5\u9053\uFF0C1937 \u5E74\u5B8C\u6210\u4E66\u7A3F\u30021937 \u5E74 10 \u6708\uFF0C\u4F26\u6566\u7684\u6208\u5170\u8328\u516C\u53F8\u51FA\u7248\u300ARed Star Over China\u300B\u30021938 \u5E74 2 \u6708\uFF0C\u4E0A\u6D77\u300C\u590D\u793E\u300D\u7EC4\u7EC7\u7FFB\u8BD1\u51FA\u7248\u4E2D\u8BD1\u672C\uFF0C\u4E3A\u4E86\u4FBF\u4E8E\u5728\u6CA6\u9677\u533A\u548C\u56FD\u7EDF\u533A\u53D1\u884C\u6D41\u4F20\uFF0C\u4E66\u540D\u6539\u4E3A\u300A\u897F\u884C\u6F2B\u8BB0\u300B\u3002\u540C\u4E00\u672C\u4E66\u7684\u4E24\u4E2A\u540D\u5B57\uFF0C\u6070\u597D\u8BF4\u660E\u4E86\u5B83\u5F53\u65F6\u7684\u5904\u5883\uFF1A\u4E66\u8981\u6D3B\u7740\uFF0C\u5C31\u5F97\u6362\u4E00\u4E2A\u540D\u5B57\u3002",
      "## \u4E3A\u4EC0\u4E48\u5B83\u81F3\u4ECA\u4ECD\u662F\u5FC5\u8BFB\u4E66",
      "\u5B83\u7684\u4EF7\u503C\u4E0D\u53EA\u5728\u53F2\u6599\uFF0C\u66F4\u5728\u76EE\u5149\u3002\u65AF\u8BFA\u662F\u5916\u6765\u8005\uFF0C\u4E66\u91CC\u4FDD\u7559\u4E86\u5927\u91CF\u7684\u7591\u95EE\u3001\u56F0\u60D1\u548C\u4E0D\u5B8C\u6574\u7684\u89C2\u5BDF\u2014\u2014\u300C\u6211\u95EE\u4ED6\u300D\u300C\u6211\u4E0D\u660E\u767D\u300D\u300C\u4ED6\u4EEC\u8BF4\u300D\u8FD9\u6837\u7684\u53E5\u5B50\u968F\u5904\u53EF\u89C1\uFF1B\u4ED6\u4E0D\u63A9\u9970\u81EA\u5DF1\u60F3\u4E0D\u901A\u7684\u5730\u65B9\uFF0C\u4E5F\u4E0D\u63A9\u9970\u5BF9\u67D0\u4E9B\u73B0\u8C61\u7684\u4FDD\u7559\u6001\u5EA6\u3002\u6B63\u662F\u8FD9\u79CD\u4E0D\u5B8C\u7F8E\u7684\u76EE\u5149\uFF0C\u8BA9\u4E16\u754C\u76F8\u4FE1\u4E86\u4ED6\u7684\u62A5\u9053\uFF1B\u4E5F\u56E0\u4E3A\u8FD9\u79CD\u76EE\u5149\uFF0C\u4ECA\u5929\u7684\u8BFB\u8005\u80FD\u4ECE\u4E2D\u8BFB\u51FA\u4E00\u79CD\u5C0A\u91CD\u4E8B\u5B9E\u7684\u6001\u5EA6\u30021972 \u5E74 2 \u6708 15 \u65E5\u65AF\u8BFA\u5728\u65E5\u5185\u74E6\u75C5\u901D\uFF0C\u9075\u5176\u9057\u5631\uFF0C\u4E00\u90E8\u5206\u9AA8\u7070\u5B89\u846C\u5728\u5317\u4EAC\u5927\u5B66\u672A\u540D\u6E56\u7554\u3002"
    ],
    think: [
      "\u65AF\u8BFA\u662F\u5916\u56FD\u8BB0\u8005\uFF0C\u8FD9\u4E2A\u8EAB\u4EFD\u8BA9\u4ED6\u5199\u51FA\u4E86\u54EA\u4E9B\u5F53\u65F6\u7684\u4E2D\u56FD\u8BB0\u8005\u5199\u4E0D\u51FA\u7684\u5185\u5BB9\uFF1F",
      "\u4E66\u91CC\u4FDD\u7559\u4E86\u65AF\u8BFA\u7684\u7591\u95EE\u548C\u672A\u5B8C\u6210\u7684\u89C2\u5BDF\uFF0C\u8FD9\u79CD\u300C\u4E0D\u5B8C\u7F8E\u300D\u4E3A\u4EC0\u4E48\u53CD\u800C\u589E\u52A0\u4E86\u53EF\u4FE1\u5EA6\uFF1F",
      "\u5982\u679C\u4F60\u8981\u4E3A\u4ECA\u5929\u7684\u4E2D\u56FD\u5199\u4E00\u4EFD\u300C\u7EA2\u661F\u7167\u8000\u4E2D\u56FD\u300D\u5F0F\u7684\u62A5\u9053\uFF0C\u4F60\u4F1A\u9009\u62E9\u91C7\u8BBF\u8C01\u3001\u8BB0\u5F55\u4EC0\u4E48\uFF1F"
    ]
  },
  {
    id: "ext-bg-hongyan",
    moduleId: "literature",
    entryId: "l-hongyan",
    grade: "8a",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u300A\u7EA2\u5CA9\u300B\u4E3A\u4EC0\u4E48\u5199\u5F97\u8FD9\u6837\u771F\u5B9E",
    summary: "\u4E24\u4F4D\u4F5C\u8005\u90FD\u662F\u6E23\u6ED3\u6D1E\u3001\u767D\u516C\u9986\u7684\u5E78\u5B58\u8005\uFF0C\u5C0F\u8BF4\u7531\u56DE\u5FC6\u5F55\u53D1\u5C55\u800C\u6765\uFF0C\u4EBA\u7269\u591A\u6709\u539F\u578B\u3002",
    content: [
      "## \u4F5C\u8005\u5C31\u662F\u4ECE\u90A3\u91CC\u6D3B\u7740\u51FA\u6765\u7684\u4EBA",
      "\u7F57\u5E7F\u658C\uFF081924 \u2014 1967\uFF091948 \u5E74\u52A0\u5165\u4E2D\u56FD\u5171\u4EA7\u515A\uFF0C\u540C\u5E74 9 \u6708\u5728\u6210\u90FD\u88AB\u6355\uFF0C\u5148\u540E\u5173\u62BC\u5728\u6E23\u6ED3\u6D1E\u548C\u767D\u516C\u9986\u30021949 \u5E74 11 \u6708 27 \u65E5\u5927\u5C60\u6740\u4E4B\u591C\uFF0C\u4ED6\u7B56\u52A8\u770B\u5B88\u6253\u5F00\u7262\u95E8\uFF0C\u5E26\u9886\u90E8\u5206\u96BE\u53CB\u8D8A\u72F1\u8131\u9669\u3002\u6768\u76CA\u8A00\uFF081925 \u2014 2017\uFF091948 \u5E74 8 \u6708\u88AB\u6355\uFF0C\u5173\u62BC\u5728\u6E23\u6ED3\u6D1E\uFF0C1949 \u5E74\u83B7\u4FDD\u91CA\u51FA\u72F1\u3002\u4E24\u4E2A\u4EBA\u90FD\u4EB2\u5386\u8FC7\u90A3\u6BB5\u5C81\u6708\uFF0C\u90FD\u662F\u4ECE\u6B7B\u4EBA\u5806\u91CC\u51FA\u6765\u7684\u4EBA\u3002\u8FD9\u672C\u4E66\u7684\u7B2C\u4E00\u5C42\u771F\u5B9E\uFF0C\u6765\u81EA\u4F5C\u8005\u672C\u4EBA\u3002",
      "## \u5148\u6709\u56DE\u5FC6\u5F55\uFF0C\u540E\u6709\u5C0F\u8BF4",
      "1950 \u5E74\u4EE3\uFF0C\u7F57\u5E7F\u658C\u3001\u6768\u76CA\u8A00\u4E0E\u5218\u5FB7\u5F6C\u5408\u4F5C\uFF0C\u628A\u4EB2\u8EAB\u7ECF\u5386\u5199\u6210\u9769\u547D\u56DE\u5FC6\u5F55\u300A\u5728\u70C8\u706B\u4E2D\u6C38\u751F\u300B\uFF0C1959 \u5E74\u51FA\u7248\uFF1B\u6B64\u540E\uFF0C\u7F57\u5E7F\u658C\u4E0E\u6768\u76CA\u8A00\u5728\u56DE\u5FC6\u5F55\u7684\u57FA\u7840\u4E0A\u8FDB\u884C\u827A\u672F\u52A0\u5DE5\uFF0C\u521B\u4F5C\u957F\u7BC7\u5C0F\u8BF4\u300A\u7EA2\u5CA9\u300B\uFF0C1961 \u5E74 12 \u6708\u7531\u4E2D\u56FD\u9752\u5E74\u51FA\u7248\u793E\u51FA\u7248\u3002\u5218\u5FB7\u5F6C\u540E\u6765\u5728\u653F\u6CBB\u8FD0\u52A8\u4E2D\u53D7\u5230\u9519\u8BEF\u5904\u7406\uFF0C\u672A\u80FD\u53C2\u4E0E\u5C0F\u8BF4\u7684\u7F72\u540D\uFF0C\u56E0\u6B64\u8BFB\u8005\u770B\u5230\u7684\u4F5C\u8005\u53EA\u6709\u4E24\u4F4D\u3002\u4ECE\u56DE\u5FC6\u5F55\u5230\u5C0F\u8BF4\uFF0C\u6750\u6599\u6CA1\u53D8\uFF0C\u5199\u6CD5\u53D8\u4E86\uFF1A\u8FD9\u662F\u7406\u89E3\u5168\u4E66\u7684\u5173\u952E\u3002",
      "## \u4EBA\u7269\u5927\u591A\u6709\u539F\u578B",
      "\u4E66\u4E2D\u4EBA\u7269\u51E0\u4E4E\u90FD\u80FD\u627E\u5230\u5BF9\u5E94\u7684\u771F\u5B9E\u70C8\u58EB\uFF1A\u6C5F\u96EA\u7434\uFF08\u6C5F\u59D0\uFF09\u7684\u539F\u578B\u662F\u6C5F\u7AF9\u7B60\uFF0C\u5C0F\u841D\u535C\u5934\u672C\u540D\u5B8B\u632F\u4E2D\uFF0C\u6210\u5C97\u7684\u539F\u578B\u662F\u300A\u633A\u8FDB\u62A5\u300B\u4E3B\u7F16\u9648\u7136\uFF0C\u534E\u5B50\u826F\u7684\u539F\u578B\u662F\u5728\u767D\u516C\u9986\u88C5\u75AF\u5341\u4F59\u5E74\u30011947 \u5E74\u9003\u51FA\u7684\u97E9\u5B50\u680B\uFF1B\u8BB8\u4E91\u5CF0\u5219\u7EFC\u5408\u4E86\u8BB8\u6653\u8F69\u3001\u8F66\u8000\u5148\u7B49\u591A\u4F4D\u70C8\u58EB\u7684\u4E8B\u8FF9\u3002\u53CD\u9762\u4EBA\u7269\u540C\u6837\u6709\u539F\u578B\uFF1A\u53DB\u5F92\u752B\u5FD7\u9AD8\u7EFC\u5408\u4E86\u84B2\u534E\u8F85\u3001\u5189\u76CA\u667A\u7B49\u53DB\u5F92\u7684\u52A3\u8FF9\uFF0C\u7279\u52A1\u5934\u5B50\u5F90\u9E4F\u98DE\u7684\u539F\u578B\u662F\u5F90\u8FDC\u4E3E\u3002\u77E5\u9053\u8FD9\u4E9B\u5BF9\u5E94\u5173\u7CFB\uFF0C\u8BFB\u5C0F\u8BF4\u65F6\u5C31\u591A\u4E86\u4E00\u91CD\u53F2\u6599\u7684\u652F\u6491\u3002",
      "## \u5C0F\u8BF4\u4E0E\u53F2\u5B9E\u7684\u4E00\u5904\u5DEE\u522B\uFF1A\u7EE3\u7EA2\u65D7",
      "\u636E\u53F2\u6599\uFF0C\u7528\u7EA2\u8272\u88AB\u9762\u548C\u9EC4\u7EB8\u505A\u6210\u4E94\u661F\u7EA2\u65D7\u7684\uFF0C\u662F\u5173\u62BC\u5728\u767D\u516C\u9986\u7684\u7F57\u5E7F\u658C\u3001\u9648\u7136\u7B49\u4EBA\uFF1B\u4ED6\u4EEC\u53EA\u77E5\u9053\u56FD\u65D7\u7684\u540D\u5B57\uFF0C\u5E76\u4E0D\u77E5\u9053\u4E94\u9897\u661F\u7684\u5177\u4F53\u6392\u5217\uFF0C\u51ED\u60F3\u8C61\u505A\u6210\u540E\u85CF\u5728\u7262\u623F\u7684\u5730\u677F\u4E0B\u9762\u3002\u5C0F\u8BF4\u628A\u8FD9\u4EF6\u4E8B\u5199\u6210\u5973\u7262\u4E2D\u7684\u6C5F\u59D0\u7B49\u4EBA\u4E00\u9488\u4E00\u7EBF\u5730\u7EE3\u7EA2\u65D7\u3002\u4F5C\u8005\u628A\u5206\u6563\u5728\u591A\u4F4D\u70C8\u58EB\u8EAB\u4E0A\u7684\u4E8B\u8FF9\u96C6\u4E2D\u5230\u4E00\u4E2A\u6700\u6709\u4EE3\u8868\u6027\u7684\u4EBA\u7269\u8EAB\u4E0A\uFF0C\u8FD9\u6837\u505A\u8BA9\u4EBA\u7269\u66F4\u96C6\u4E2D\u3001\u60C5\u611F\u66F4\u5F3A\u70C8\uFF0C\u4E5F\u63D0\u9192\u6211\u4EEC\uFF1A\u8BFB\u7EA2\u8272\u7ECF\u5178\uFF0C\u8981\u5206\u6E05\u54EA\u91CC\u662F\u53F2\u5B9E\uFF0C\u54EA\u91CC\u662F\u827A\u672F\u52A0\u5DE5\u3002",
      "## \u4E3A\u4EC0\u4E48\u771F\u5B9E\u5F97\u8BA9\u4EBA\u900F\u4E0D\u8FC7\u6C14",
      "\u7AF9\u7B7E\u9489\u6307\u3001\u96C6\u4F53\u7EDD\u98DF\u3001\u8FFD\u60BC\u6218\u53CB\u3001\u72F1\u4E2D\u8054\u6B22\u3001\u6316\u901A\u77F3\u58C1\u3001\u8D8A\u72F1\u7A81\u56F4\uFF0C\u8FD9\u4E9B\u60C5\u8282\u90FD\u4E0D\u662F\u51ED\u7A7A\u6784\u60F3\uFF1A\u6E23\u6ED3\u6D1E\u4E0E\u767D\u516C\u9986\u786E\u5B9E\u5173\u62BC\u8FC7\u5927\u6279\u9769\u547D\u8005\uFF0C1949 \u5E74 11 \u6708 27 \u65E5\u591C\u91CC\u786E\u5B9E\u53D1\u751F\u4E86\u5927\u5C60\u6740\uFF0C\u9047\u96BE\u8005\u4E09\u767E\u4F59\u4EBA\uFF1B\u800C\u91CD\u5E86\u662F\u5728\u4E09\u5929\u4E4B\u540E\u7684 11 \u6708 30 \u65E5\u89E3\u653E\u7684\u3002\u80DC\u5229\u53EA\u5DEE\u4E09\u5929\u2014\u2014\u8FD9\u4E2A\u65F6\u95F4\u5DEE\u672C\u8EAB\u5C31\u662F\u6700\u6C89\u91CD\u7684\u7EC6\u8282\u3002\u5C0F\u8BF4\u91CC\u90A3\u79CD\u903C\u8FD1\u771F\u5B9E\u7684\u7A92\u606F\u611F\uFF0C\u6839\u5B50\u5728\u8FD9\u4E9B\u6570\u5B57\u91CC\u3002",
      "## \u6559\u6750\u8981\u6211\u4EEC\u6CE8\u610F\u4EC0\u4E48",
      "\u7EDF\u7F16\u6559\u6750\u628A\u300A\u7EA2\u5CA9\u300B\u5B89\u6392\u5728\u516B\u5E74\u7EA7\u4E0A\u518C\u7B2C\u56DB\u5355\u5143\uFF0C\u8BFB\u6CD5\u6307\u5BFC\u8BED\u662F\u300C\u600E\u6837\u8BFB\u7EA2\u8272\u7ECF\u5178\u4F5C\u54C1\u300D\uFF1A\u5148\u4E86\u89E3\u65F6\u4EE3\u80CC\u666F\u4E0E\u771F\u5B9E\u4EBA\u7269\u4E8B\u8FF9\uFF0C\u77E5\u9053\u4E66\u4E2D\u4EBA\u7269\u591A\u6709\u539F\u578B\uFF1B\u518D\u6293\u4F4F\u91CD\u5927\u60C5\u8282\u4E0E\u4EBA\u7269\u5728\u5173\u952E\u65F6\u523B\u7684\u9009\u62E9\uFF0C\u4F53\u4F1A\u5176\u7CBE\u795E\u54C1\u8D28\uFF1B\u6700\u540E\u8981\u5728\u7EAA\u5B9E\u4E0E\u865A\u6784\u7684\u7ED3\u5408\u5904\u7528\u5FC3\uFF0C\u5206\u8FA8\u54EA\u4E9B\u5C5E\u4E8E\u53F2\u5B9E\u3001\u54EA\u4E9B\u662F\u827A\u672F\u52A0\u5DE5\uFF0C\u5E76\u601D\u8003\u4F5C\u8005\u4E3A\u4EC0\u4E48\u8FD9\u6837\u5199\u3002\u8FD9\u4E09\u6B65\uFF0C\u6B63\u597D\u4E5F\u662F\u4E2D\u8003\u540D\u8457\u9605\u8BFB\u5F00\u653E\u9898\u7684\u7B54\u9898\u601D\u8DEF\u3002"
    ],
    think: [
      "\u4F5C\u8005\u628A\u767D\u516C\u9986\u7684\u300C\u7EE3\u7EA2\u65D7\u300D\u79FB\u5230\u5973\u7262\u7684\u6C5F\u59D0\u8EAB\u4E0A\uFF0C\u8FD9\u6837\u6539\u5199\u597D\u4E0D\u597D\uFF1F\u8BF7\u8BF4\u660E\u7406\u7531\u3002",
      "\u5982\u679C\u300A\u7EA2\u5CA9\u300B\u5B8C\u5168\u6309\u53F2\u5B9E\u9010\u4EBA\u8BB0\u5F55\uFF0C\u4E0D\u505A\u4EFB\u4F55\u96C6\u4E2D\u4E0E\u79FB\u7F6E\uFF0C\u5B83\u4F1A\u66F4\u52A0\u52A8\u4EBA\u8FD8\u662F\u66F4\u96BE\u8BFB\uFF1F",
      "\u300C\u80DC\u5229\u53EA\u5DEE\u4E09\u5929\u300D\u3002\u8BF7\u7ED3\u5408\u8FD9\u4E2A\u65F6\u95F4\u5DEE\uFF0C\u8C08\u8C08\u4F60\u5BF9\u9769\u547D\u4EE3\u4EF7\u7684\u7406\u89E3\u3002"
    ]
  },
  {
    id: "ext-bg-jingdianchangtan",
    moduleId: "literature",
    entryId: "l-jingdianchangtan",
    grade: "8b",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u300A\u7ECF\u5178\u5E38\u8C08\u300B\u662F\u4E00\u4F4D\u6E05\u534E\u6559\u6388\u5199\u7ED9\u4E2D\u5B66\u751F\u7684\u5165\u95E8\u4E66",
    summary: "\u6297\u6218\u65F6\u671F\u6731\u81EA\u6E05\u5E94\u53F6\u5723\u9676\u4E4B\u7EA6\uFF0C\u4E3A\u96BE\u61C2\u7684\u53E4\u4EBA\u5199\u767D\u8BDD\u5165\u95E8\uFF0C1942 \u5E74\u6210\u4E66\u5341\u4E09\u7BC7\u3002",
    content: [
      "## \u4E00\u6B21\u7EA6\u7A3F\uFF0C\u4E24\u6B21\u52A8\u7B14",
      "1940 \u5E74\uFF0C\u6731\u81EA\u6E05\u5728\u6210\u90FD\u4F11\u5047\uFF08\u4ED6\u7684\u592B\u4EBA\u9648\u7AF9\u9690\u662F\u6210\u90FD\u4EBA\uFF09\u3002\u5F53\u65F6\u53F6\u5723\u9676\u5728\u6210\u90FD\u4E3B\u6301\u5F00\u660E\u4E66\u5E97\u7684\u7F16\u8F91\u5DE5\u4F5C\uFF0C\u7EA6\u8BF7\u6731\u81EA\u6E05\u4E3A\u9762\u5411\u4E2D\u5B66\u751F\u7684\u520A\u7269\u5199\u4E00\u7EC4\u4ECB\u7ECD\u4E2D\u56FD\u53E4\u4EE3\u7ECF\u5178\u7684\u6587\u7AE0\u3002\u7A3F\u5B50\u5199\u4E86\u51E0\u7BC7\u4E4B\u540E\uFF0C\u56E0\u520A\u7269\u505C\u520A\u800C\u4E2D\u65AD\uFF1B1942 \u5E74 2 \u6708\uFF0C\u6731\u81EA\u6E05\u5728\u6606\u660E\u7684\u897F\u5357\u8054\u5408\u5927\u5B66\u628A\u5168\u4E66\u7EED\u5199\u5B8C\u6210\uFF0C\u5171\u5341\u4E09\u7BC7\uFF0C\u540E\u6765\u7531\u6587\u5149\u4E66\u5E97\u51FA\u7248\u3002\u8FD9\u662F\u4E00\u672C\u7531\u7EA6\u7A3F\u50AC\u751F\u3001\u53C8\u88AB\u6218\u4E71\u6253\u65AD\u3001\u6700\u7EC8\u5728\u6D41\u4EA1\u5927\u5B66\u91CC\u6536\u5C3E\u7684\u4E66\u3002",
      "## \u4F5C\u8005\u662F\u8C01\uFF1A\u6563\u6587\u5BB6\u3001\u6E05\u534E\u6559\u6388\u3001\u6C11\u4E3B\u6218\u58EB",
      "\u6731\u81EA\u6E05\uFF081898 \u2014 1948\uFF09\uFF0C\u5B57\u4F69\u5F26\uFF0C\u539F\u540D\u81EA\u534E\uFF0C\u7956\u7C4D\u6D59\u6C5F\u7ECD\u5174\uFF0C\u4ECE\u5C0F\u5728\u626C\u5DDE\u957F\u5927\u30021925 \u5E74\u8D77\u4EFB\u6E05\u534E\u5927\u5B66\u4E2D\u6587\u7CFB\u6559\u6388\uFF0C1931 \u5E74\u81F3 1932 \u5E74\u7559\u5B66\u82F1\u56FD\u5E76\u6E38\u5386\u6B27\u6D32\uFF0C\u56DE\u56FD\u540E\u4EFB\u6E05\u534E\u5927\u5B66\u4E2D\u6587\u7CFB\u4E3B\u4EFB\uFF1B\u6297\u6218\u7206\u53D1\u540E\u968F\u6821\u5357\u8FC1\uFF0C\u4EFB\u897F\u5357\u8054\u5927\u4E2D\u6587\u7CFB\u6559\u6388\uFF0C1946 \u5E74\u56DE\u5230\u5317\u5E73\u30021948 \u5E74 8 \u6708 12 \u65E5\uFF0C\u4ED6\u56E0\u80C3\u6E83\u75A1\u7A7F\u5B54\u5728\u5317\u5E73\u75C5\u901D\uFF0C\u4E34\u7EC8\u5631\u5490\u5BB6\u4EBA\u4E0D\u8981\u4E70\u7F8E\u56FD\u9762\u7C89\u3002\u6BDB\u6CFD\u4E1C\u5728\u300A\u522B\u4E86\uFF0C\u53F8\u5F92\u96F7\u767B\u300B\u4E2D\u8BF4\uFF0C\u4ED6\u7684\u6B7B\u300C\u8868\u73B0\u4E86\u6211\u4EEC\u6C11\u65CF\u7684\u82F1\u96C4\u6C14\u6982\u300D\u3002",
      "## \u5341\u4E09\u7BC7\u8BB2\u4E86\u4EC0\u4E48",
      "\u5168\u4E66\u4F9D\u6B21\u662F\uFF1A\u300A\u8BF4\u6587\u89E3\u5B57\u300B\u7B2C\u4E00\u3001\u300A\u5468\u6613\u300B\u7B2C\u4E8C\u3001\u300A\u5C1A\u4E66\u300B\u7B2C\u4E09\u3001\u300A\u8BD7\u7ECF\u300B\u7B2C\u56DB\u3001\u4E09\u793C\u7B2C\u4E94\u3001\u300A\u6625\u79CB\u300B\u4E09\u4F20\u7B2C\u516D\uFF08\u9644\u300A\u56FD\u8BED\u300B\uFF09\u3001\u56DB\u4E66\u7B2C\u4E03\u3001\u300A\u6218\u56FD\u7B56\u300B\u7B2C\u516B\u3001\u300A\u53F2\u8BB0\u300B\u300A\u6C49\u4E66\u300B\u7B2C\u4E5D\u3001\u8BF8\u5B50\u7B2C\u5341\u3001\u8F9E\u8D4B\u7B2C\u5341\u4E00\u3001\u8BD7\u7B2C\u5341\u4E8C\u3001\u6587\u7B2C\u5341\u4E09\u3002\u4ECE\u4E00\u90E8\u5B57\u4E66\u8BB2\u8D77\uFF0C\u63A5\u7740\u8BB2\u7ECF\u4E66\uFF0C\u518D\u8BB2\u53F2\u4E66\u4E0E\u8BF8\u5B50\uFF0C\u6700\u540E\u843D\u5230\u8F9E\u8D4B\u4E0E\u8BD7\u6587\uFF0C\u662F\u4E00\u6761\u6309\u65F6\u95F4\u4E0E\u7C7B\u522B\u987A\u4E0B\u6765\u7684\u7EBF\u7D22\u3002\u4E2D\u5B66\u751F\u8BFB\u5B8C\u8FD9\u5341\u4E09\u7BC7\uFF0C\u5C31\u5927\u81F4\u77E5\u9053\u4E2D\u56FD\u53E4\u4E66\u5206\u51E0\u7C7B\u3001\u5404\u7C7B\u91CC\u6700\u91CD\u8981\u7684\u4E66\u662F\u54EA\u51E0\u90E8\u3002",
      "## \u4ED6\u7684\u6001\u5EA6\uFF1A\u8BFB\u7ECF\u4E0D\u662F\u80CC\u6559\u6761",
      "\u6731\u81EA\u6E05\u5728\u5E8F\u91CC\u8BF4\uFF1A\u300C\u5728\u4E2D\u7B49\u4EE5\u4E0A\u7684\u6559\u80B2\u91CC\uFF0C\u7ECF\u5178\u8BAD\u7EC3\u5E94\u8BE5\u662F\u4E00\u4E2A\u5FC5\u8981\u7684\u9879\u76EE\u3002\u7ECF\u5178\u8BAD\u7EC3\u7684\u4EF7\u503C\u4E0D\u5728\u5B9E\u7528\uFF0C\u800C\u5728\u6587\u5316\u3002\u300D\u90A3\u4E2A\u5E74\u4EE3\u6709\u4EBA\u63D0\u5021\u300C\u5C0A\u5B54\u8BFB\u7ECF\u300D\uFF0C\u628A\u7ECF\u5178\u5F53\u6559\u6761\u8BA9\u4EBA\u80CC\u8BF5\uFF1B\u6731\u81EA\u6E05\u7684\u4E3B\u5F20\u6070\u6070\u76F8\u53CD\uFF1A\u7ECF\u5178\u5E94\u5F53\u4F5C\u6587\u5316\u9057\u4EA7\u6765\u8BFB\uFF0C\u7528\u73B0\u4EE3\u7684\u3001\u79D1\u5B66\u7684\u773C\u5149\u53BB\u770B\u5B83\u8BB2\u4E86\u4EC0\u4E48\u3001\u4E3A\u4EC0\u4E48\u8FD9\u6837\u8BB2\uFF0C\u800C\u4E0D\u662F\u5F53\u4F5C\u4E0D\u53EF\u6000\u7591\u7684\u6559\u6761\u3002\u8FD9\u53E5\u300C\u4E0D\u5728\u5B9E\u7528\uFF0C\u800C\u5728\u6587\u5316\u300D\uFF0C\u662F\u7406\u89E3\u8FD9\u672C\u4E66\u7684\u94A5\u5319\u3002",
      "## \u4E3A\u4EC0\u4E48\u8FD9\u4E9B\u8BF4\u660E\u6587\u5B57\u8FD9\u6837\u597D\u8BFB",
      "\u4ED6\u7528\u767D\u8BDD\u8BB2\u53E4\u4E66\uFF1A\u628A\u300A\u8BF4\u6587\u89E3\u5B57\u300B\u7684\u300C\u516D\u4E66\u300D\u8BB2\u5F97\u5C42\u6B21\u6E05\u695A\uFF0C\u628A\u300A\u8BD7\u7ECF\u300B\u7684\u300C\u98CE\u96C5\u9882\u300D\u4E0E\u8D4B\u6BD4\u5174\u8BB2\u5F97\u660E\u767D\uFF0C\u8BF4\u300A\u53F2\u8BB0\u300B\u300C\u662F\u4E00\u90E8\u5386\u53F2\uFF0C\u4E5F\u662F\u4E00\u90E8\u6587\u5B66\u4E66\u300D\u3002\u4E00\u4F4D\u5199\u60EF\u4E86\u6563\u6587\u7684\u4EBA\u6765\u5199\u8BF4\u660E\u6587\u5B57\uFF0C\u53E5\u5B50\u81EA\u7136\u3001\u4EB2\u5207\uFF0C\u5076\u5C14\u8FD8\u6709\u4E00\u70B9\u5E7D\u9ED8\u3002\u53F6\u5723\u9676\u66FE\u79F0\u8D5E\u8FD9\u4E9B\u6587\u7AE0\u7528\u767D\u8BDD\u8FF0\u8BF4\u53E4\u4E66\uFF0C\u300C\u4F7F\u4EBA\u5BB9\u6613\u9886\u4F1A\u300D\u3002\u540C\u6837\u8BB2\u53E4\u4EE3\u7ECF\u5178\uFF0C\u8FD9\u672C\u4E66\u6240\u4EE5\u6D41\u4F20\u81F3\u4ECA\uFF0C\u4E00\u534A\u9760\u5B66\u95EE\uFF0C\u4E00\u534A\u9760\u6587\u7B14\u3002",
      "## \u8BFB\u6CD5\u4E0E\u8003\u70B9",
      "\u65B0\u6559\u6750\u628A\u300A\u7ECF\u5178\u5E38\u8C08\u300B\u5217\u4E3A\u516B\u5E74\u7EA7\u4E0B\u518C\u300C\u6574\u672C\u4E66\u9605\u8BFB\u300D\uFF0C\u8BFB\u4E66\u65B9\u6CD5\u7684\u6307\u5BFC\u662F\u300C\u9009\u62E9\u6027\u9605\u8BFB\u300D\u2014\u2014\u8FD9\u672C\u4E66\u4E0D\u5FC5\u4ECE\u5934\u8BFB\u5230\u5C3E\uFF0C\u53EF\u4EE5\u5148\u8BFB\u81EA\u5DF1\u611F\u5174\u8DA3\u6216\u6B63\u5728\u5B66\u7684\u90E8\u5206\uFF08\u6BD4\u5982\u521A\u5B66\u8FC7\u300A\u8BD7\u7ECF\u300B\u91CC\u7684\u7BC7\u76EE\uFF0C\u5C31\u8BFB\u300A\u8BD7\u7ECF\u300B\u7B2C\u56DB\u90A3\u4E00\u7BC7\uFF09\uFF0C\u4E5F\u53EF\u4EE5\u6309\u7C7B\u522B\u8DF3\u8BFB\u3002\u9762\u5BF9\u4E2D\u8003\uFF0C\u8981\u80FD\u8BF4\u6E05\u4F5C\u8005\u3001\u6210\u4E66\u65F6\u95F4\u3001\u5341\u4E09\u7BC7\u7684\u6B21\u5E8F\u4E0E\u5927\u81F4\u5185\u5BB9\uFF0C\u5E76\u8BB0\u4F4F\u4ED6\u300C\u4E0D\u5728\u5B9E\u7528\uFF0C\u800C\u5728\u6587\u5316\u300D\u7684\u7ECF\u5178\u89C2\u3002"
    ],
    think: [
      "\u6731\u81EA\u6E05\u8BF4\u7ECF\u5178\u8BAD\u7EC3\u7684\u4EF7\u503C\u300C\u4E0D\u5728\u5B9E\u7528\uFF0C\u800C\u5728\u6587\u5316\u300D\u3002\u4F60\u540C\u610F\u5417\uFF1F\u8BF7\u7528\u4E00\u4E2A\u4F8B\u5B50\u8BF4\u660E\u3002",
      "\u300C\u9009\u62E9\u6027\u9605\u8BFB\u300D\u610F\u5473\u7740\u4E0D\u5FC5\u4ECE\u5934\u8BFB\u5230\u5C3E\u3002\u9762\u5BF9\u5341\u4E09\u7BC7\u5185\u5BB9\uFF0C\u4F60\u4F1A\u6309\u4EC0\u4E48\u987A\u5E8F\u9009\u8BFB\uFF1F\u8BF4\u660E\u7406\u7531\u3002",
      "\u4E3A\u4EC0\u4E48\u4E00\u90E8\u8BB2\u53E4\u4E66\u7684\u4E66\u8981\u7528\u767D\u8BDD\u5199\uFF1F\u8FD9\u4E0E\u5B83\u5199\u7ED9\u4E2D\u5B66\u751F\u770B\u6709\u4EC0\u4E48\u5173\u7CFB\uFF1F"
    ]
  },
  {
    id: "ext-bg-kunchongji",
    moduleId: "literature",
    entryId: "l-kunchongji",
    grade: "8b",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u6CD5\u5E03\u5C14\u5728\u8352\u77F3\u56ED\u91CC\u4F4F\u4E86\u4E09\u5341\u591A\u5E74",
    summary: "\u6CD5\u5E03\u5C14\u88AB\u8D76\u4E0B\u8BB2\u53F0\u540E\u4E70\u4E0B\u4E00\u5757\u8352\u5730\uFF0C\u5728\u8352\u77F3\u56ED\u89C2\u5BDF\u6606\u866B\u4E09\u5341\u4E94\u5E74\uFF0C\u5199\u6210\u5341\u5377\u300A\u6606\u866B\u8BB0\u300B\u3002",
    content: [
      "## \u4ECE\u7A77\u5B69\u5B50\u5230\u7406\u5B66\u535A\u58EB",
      "\u8BA9-\u4EA8\u5229\xB7\u6CD5\u5E03\u5C14\uFF081823 \u2014 1915\uFF09\u751F\u4E8E\u6CD5\u56FD\u5357\u90E8\u963F\u97E6\u9F99\u7701\u4E00\u4E2A\u8D2B\u5BD2\u7684\u519C\u5BB6\uFF0C\u9760\u81EA\u5B66\u8003\u5165\u5E08\u8303\u5B66\u6821\uFF0C\u6BD5\u4E1A\u540E\u505A\u8FC7\u5C0F\u5B66\u6559\u5E08\u548C\u4E2D\u5B66\u6559\u5E08\u3002\u4ED6\u4E00\u8FB9\u6559\u4E66\u4E00\u8FB9\u81EA\u5B66\uFF0C\u5148\u540E\u53D6\u5F97\u5B66\u4F4D\uFF0C1854 \u5E74\u83B7\u7406\u5B66\u535A\u58EB\u5B66\u4F4D\u3002\u4ED6\u7684\u8D77\u70B9\u5E76\u4E0D\u9AD8\uFF0C\u4E00\u751F\u4E5F\u6CA1\u6709\u8FDB\u5165\u5DF4\u9ECE\u7684\u5B66\u672F\u4E2D\u5FC3\uFF1B\u4ED6\u7814\u7A76\u6606\u866B\u6240\u9700\u7684\u8010\u5FC3\u4E0E\u5E38\u8BC6\uFF0C\u4E00\u534A\u6765\u81EA\u7530\u91CE\uFF0C\u4E00\u534A\u6765\u81EA\u4E66\u672C\u3002",
      "## \u56E0\u4E3A\u8BB2\u79D1\u5B66\u800C\u4E22\u6389\u6559\u804C",
      "1868 \u5E74\uFF0C\u4ED6\u56E0\u7814\u7A76\u8461\u8404\u5BB3\u866B\u7684\u6210\u679C\u83B7\u5F97\u6CD5\u56FD\u8363\u8A89\u519B\u56E2\u52CB\u7AE0\u3002\u4F46 1870 \u5E74\u524D\u540E\uFF0C\u4ED6\u5728\u963F\u7EF4\u5C3C\u7FC1\u4E3A\u666E\u901A\u5E02\u6C11\u7279\u522B\u662F\u5973\u5B50\u5F00\u8BBE\u81EA\u7136\u79D1\u5B66\u8BFE\u7A0B\uFF0C\u8FD9\u79CD\u300C\u8BA9\u4E0D\u61C2\u79D1\u5B66\u7684\u4EBA\u4E5F\u80FD\u542C\u61C2\u79D1\u5B66\u300D\u7684\u505A\u6CD5\u89E6\u6012\u4E86\u4FDD\u5B88\u6D3E\u4E0E\u6559\u4F1A\uFF0C\u4ED6\u88AB\u8FEB\u8F9E\u53BB\u6559\u804C\u3002\u6B64\u540E\u76F8\u5F53\u957F\u4E00\u6BB5\u65F6\u95F4\uFF0C\u4ED6\u751F\u6D3B\u56F0\u7A98\uFF0C\u53EA\u80FD\u9760\u7F16\u5199\u8BFE\u672C\u548C\u79D1\u666E\u8BFB\u7269\u7EF4\u6301\u5BB6\u7528\u3002\u4E00\u4E2A\u4E0D\u5408\u65F6\u5B9C\u7684\u4E3E\u52A8\uFF0C\u628A\u4ED6\u4ECE\u8BB2\u53F0\u4E0A\u63A8\u5230\u4E86\u7530\u91CE\u91CC\u3002",
      "## \u8352\u77F3\u56ED\uFF1A\u4E00\u5757\u6CA1\u4EBA\u8981\u7684\u8352\u5730",
      "1879 \u5E74\uFF0C\u4ED6\u7528\u79EF\u6512\u4E0B\u6765\u7684\u94B1\uFF0C\u5728\u6CD5\u56FD\u5357\u90E8\u6C83\u514B\u5415\u5179\u7701\u7684\u585E\u91CC\u5C3C\u6602\u4E70\u4E0B\u4E00\u5757\u8352\u5730\uFF0C\u53D6\u540D\u300C\u8352\u77F3\u56ED\u300D\uFF08Harmas\uFF0C\u610F\u4E3A\u4F11\u8015\u7684\u8352\u5730\uFF09\u3002\u6B64\u540E\u4E09\u5341\u591A\u5E74\uFF0C\u4ED6\u5728\u8FD9\u91CC\u79CD\u82B1\u3001\u517B\u866B\u3001\u89C2\u5BDF\u3001\u8BB0\u5F55\uFF0C\u51E0\u4E4E\u4E0D\u4E0E\u5F53\u65F6\u7684\u5B66\u754C\u5F80\u6765\u3002\u540C\u5E74\u300A\u6606\u866B\u8BB0\u300B\u7B2C\u4E00\u5377\u51FA\u7248\uFF0C\u6B64\u540E\u4E00\u5377\u4E00\u5377\u5730\u5199\u4E0B\u53BB\uFF0C\u5230 1910 \u5E74\u51FA\u9F50\u5341\u5377\u30021915 \u5E74 10 \u6708 11 \u65E5\uFF0C\u4ED6\u5728\u8352\u77F3\u56ED\u4E2D\u53BB\u4E16\u3002\u8FD9\u672C\u4E66\u4E0D\u662F\u5B9E\u9A8C\u5BA4\u7684\u4EA7\u7269\uFF0C\u800C\u662F\u4E00\u4E2A\u4EBA\u5B88\u7740\u4E00\u5757\u5730\u3001\u770B\u4E86\u5927\u534A\u8F88\u5B50\u7684\u4EA7\u7269\u3002",
      "## \u4E00\u90E8\u79D1\u5B66\u7684\u4E66\uFF0C\u53C8\u662F\u4E00\u90E8\u6587\u5B66\u7684\u4E66",
      "\u300A\u6606\u866B\u8BB0\u300B\u7684\u539F\u4E66\u540D\u662F\u300A\u6606\u866B\u5B66\u56DE\u5FC6\u5F55\u300B\u3002\u8FBE\u5C14\u6587\u79F0\u6CD5\u5E03\u5C14\u662F\u300C\u65E0\u4E0E\u4F26\u6BD4\u7684\u89C2\u5BDF\u8005\u300D\uFF0C\u4EBA\u4EEC\u4E5F\u5E38\u5F15\u7528\u6CD5\u56FD\u4F5C\u5BB6\u96E8\u679C\u7684\u8BF4\u6CD5\uFF0C\u79F0\u4ED6\u4E3A\u300C\u6606\u866B\u754C\u7684\u8377\u9A6C\u300D\uFF0C\u628A\u8FD9\u90E8\u4E66\u79F0\u4F5C\u300C\u6606\u866B\u7684\u53F2\u8BD7\u300D\u3002\u4ED6\u5199\u8749\u5E76\u4E0D\u662F\u4E5E\u4E10\uFF0C\u53CD\u800C\u662F\u8682\u8681\u62A2\u8D70\u4E86\u8749\u7684\u996E\u6599\uFF1B\u5199\u87CB\u87C0\u600E\u6837\u4FEE\u7B51\u81EA\u5DF1\u7684\u4F4F\u5B85\uFF1B\u5199\u8723\u8782\u600E\u6837\u63A8\u6EDA\u7CAA\u7403\uFF1B\u5199\u87B3\u8782\u6355\u98DF\u524D\u90A3\u526F\u50CF\u5728\u300C\u7948\u7977\u300D\u7684\u59FF\u6001\u3002\u4E25\u5BC6\u7684\u89C2\u5BDF\u914D\u4E0A\u8BB2\u6545\u4E8B\u4E00\u6837\u7684\u7B14\u8C03\uFF0C\u662F\u5B83\u6D41\u4F20\u4E00\u767E\u591A\u5E74\u7684\u539F\u56E0\u3002",
      "## \u4E5F\u8981\u77E5\u9053\u5B83\u7684\u5C40\u9650",
      "\u6CD5\u5E03\u5C14\u7684\u5C40\u9650\u540C\u6837\u6E05\u695A\uFF1A\u4ED6\u4E0D\u63A5\u53D7\u8FBE\u5C14\u6587\u7684\u8FDB\u5316\u8BBA\uFF0C\u575A\u6301\u7269\u79CD\u4E0D\u53D8\uFF1B\u4ED6\u5E38\u7528\u62DF\u4EBA\u7684\u7B14\u6CD5\u5199\u6606\u866B\u7684\u300C\u6BCD\u7231\u300D\u300C\u7B97\u8BA1\u300D\u4E0E\u300C\u601D\u8003\u300D\uFF0C\u6709\u65F6\u628A\u4EBA\u7684\u5FC3\u7406\u6295\u5C04\u5230\u4E86\u866B\u5B50\u8EAB\u4E0A\u3002\u8FD9\u4E9B\u5199\u6CD5\u8BFB\u8D77\u6765\u52A8\u4EBA\uFF0C\u5374\u4E0D\u80FD\u5F53\u4F5C\u79D1\u5B66\u7ED3\u8BBA\u3002\u8BFB\u79D1\u666E\u4F5C\u54C1\uFF0C\u65E2\u8981\u6B23\u8D4F\u4F5C\u8005\u89C2\u5BDF\u7684\u624E\u5B9E\uFF0C\u4E5F\u8981\u5206\u8FA8\u54EA\u4E9B\u662F\u4E8B\u5B9E\u3001\u54EA\u4E9B\u662F\u6587\u5B66\u6027\u7684\u89E3\u91CA\u2014\u2014\u8FD9\u6B63\u662F\u516B\u5E74\u7EA7\u4E0A\u518C\u300C\u79D1\u666E\u4F5C\u54C1\u7684\u9605\u8BFB\u300D\u8FD9\u4E00\u8BFB\u6CD5\u6307\u5BFC\u8981\u7EC3\u7684\u80FD\u529B\u3002"
    ],
    think: [
      "\u6CD5\u5E03\u5C14\u4E3A\u4E86\u7ED9\u666E\u901A\u4EBA\u8BB2\u79D1\u5B66\u800C\u5931\u53BB\u6559\u804C\uFF0C\u5374\u5728\u8352\u77F3\u56ED\u91CC\u6210\u5C31\u4E86\u66F4\u5927\u7684\u4E8B\u4E1A\u3002\u4F60\u600E\u6837\u770B\u5F85\u8FD9\u79CD\u300C\u5931\u53BB\u300D\u4E0E\u300C\u5F97\u5230\u300D\uFF1F",
      "\u6CD5\u5E03\u5C14\u5E38\u628A\u4EBA\u7684\u5FC3\u7406\u6295\u5C04\u5230\u6606\u866B\u8EAB\u4E0A\u3002\u8FD9\u79CD\u5199\u6CD5\u4F1A\u5E26\u6765\u4EC0\u4E48\u597D\u5904\uFF0C\u53C8\u53EF\u80FD\u5E26\u6765\u4EC0\u4E48\u95EE\u9898\uFF1F",
      "\u300A\u6606\u866B\u8BB0\u300B\u662F\u4E00\u90E8\u300C\u5B88\u7740\u89C2\u5BDF\u4E86\u8FD1\u56DB\u5341\u5E74\u7684\u4E66\u300D\u3002\u5728\u8FD9\u4E2A\u53EF\u4EE5\u5FEB\u67E5\u8D44\u6599\u7684\u65F6\u4EE3\uFF0C\u957F\u671F\u89C2\u5BDF\u8FD8\u6709\u4EF7\u503C\u5417\uFF1F"
    ]
  },
  {
    id: "ext-bg-jianai",
    moduleId: "literature",
    entryId: "l-jianai",
    grade: "9a",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u300A\u7B80\xB7\u7231\u300B\u91CC\u6709\u591A\u5C11\u590F\u6D1B\u8482\xB7\u52C3\u6717\u7279\u81EA\u5DF1",
    summary: "\u590F\u6D1B\u8482\xB7\u52C3\u6717\u7279\u505A\u8FC7\u5BB6\u5EAD\u6559\u5E08\uFF0C1847 \u5E74\u4EE5\u7537\u6027\u7B14\u540D\u53D1\u8868\u8FD9\u90E8\u81EA\u4F20\u8272\u5F69\u7684\u5C0F\u8BF4\u3002",
    content: [
      "## \u4E00\u4E2A\u7267\u5E08\u5BB6\u5EAD\u91CC\u63A5\u8FDE\u7684\u6B7B\u4EA1",
      "\u590F\u6D1B\u8482\xB7\u52C3\u6717\u7279\uFF081816 \u2014 1855\uFF09\u751F\u4E8E\u82F1\u56FD\u7EA6\u514B\u90E1\uFF0C\u7236\u4EB2\u662F\u7231\u5C14\u5170\u88D4\u7267\u5E08\uFF0C1820 \u5E74\u5168\u5BB6\u8FC1\u5230\u970D\u6C83\u601D\u6559\u533A\u3002\u6BCD\u4EB2\u5728 1821 \u5E74\u75C5\u901D\uFF1B1824 \u5E74\uFF0C\u5979\u548C\u59D0\u59D0\u3001\u59B9\u59B9\u88AB\u9001\u8FDB\u7BA1\u6559\u4E25\u5389\u3001\u751F\u6D3B\u6761\u4EF6\u6076\u52A3\u7684\u8003\u6069\u6865\u5B66\u6821\uFF0C\u4E24\u4E2A\u59D0\u59D0\u739B\u4E3D\u4E9A\u548C\u4F0A\u4E3D\u838E\u767D\u5728 1825 \u5E74\u76F8\u7EE7\u75C5\u6B7B\u3002\u5C0F\u8BF4\u4E2D\u6D1B\u4F0D\u5FB7\u5B66\u6821\u7684\u5BD2\u51B7\u3001\u9965\u997F\u4E0E\u4F53\u7F5A\uFF0C\u4EE5\u53CA\u6D77\u4F26\xB7\u5F6D\u65AF\u7684\u9690\u5FCD\u4E0E\u65E9\u901D\uFF0C\u5C31\u6765\u81EA\u8FD9\u6BB5\u7ECF\u5386\u2014\u2014\u6D77\u4F26\u7684\u539F\u578B\u6B63\u662F\u5979\u7684\u5927\u59D0\u739B\u4E3D\u4E9A\u3002",
      "## \u5BB6\u5EAD\u6559\u5E08\uFF1A\u4E00\u4EFD\u88AB\u8F7B\u89C6\u7684\u5DE5\u4F5C",
      "\u4E3A\u4E86\u8C0B\u751F\uFF0C\u590F\u6D1B\u8482\u5728 1839 \u5E74\u548C 1841 \u5E74\u4E24\u6B21\u505A\u5BB6\u5EAD\u6559\u5E08\u3002\u5728\u522B\u4EBA\u7684\u5B85\u5B50\u91CC\uFF0C\u5979\u65E2\u4E0D\u662F\u4E3B\u4EBA\u4E5F\u4E0D\u662F\u4EC6\u4EBA\uFF0C\u5904\u5883\u5C34\u5C2C\uFF1B\u5979\u66FE\u8BF4\u8FC7\uFF0C\u5BB6\u5EAD\u6559\u5E08\u5728\u5BB6\u91CC\u662F\u4E0D\u7B97\u4EBA\u7684\u3002\u7B80\xB7\u7231\u5728\u6851\u83F2\u5C14\u5FB7\u5E9C\u7684\u5904\u5883\u3001\u5979\u90A3\u79CD\u4E0D\u80AF\u4F4E\u5934\u7684\u81EA\u5C0A\u3001\u5979\u5BF9\u7F57\u5207\u65AF\u7279\u65E2\u7231\u53C8\u8981\u6C42\u5E73\u7B49\u7684\u6001\u5EA6\uFF0C\u90FD\u662F\u4ECE\u8FD9\u4EFD\u5C48\u8FB1\u91CC\u751F\u957F\u51FA\u6765\u7684\u3002\u505A\u8FC7\u5BB6\u5EAD\u6559\u5E08\u7684\u7ECF\u5386\uFF0C\u7ED9\u4E86\u8FD9\u90E8\u5C0F\u8BF4\u6700\u771F\u5B9E\u7684\u4E00\u5C42\u8D28\u5730\u3002",
      "## \u5E03\u9C81\u585E\u5C14\u7684\u4E00\u573A\u65E0\u671B\u7684\u7231",
      "1842 \u5E74\uFF0C\u5979\u4E0E\u59B9\u59B9\u827E\u7C73\u8389\u5230\u5E03\u9C81\u585E\u5C14\u7684\u57C3\u70ED\u5B66\u6821\u5B66\u4E60\u6CD5\u8BED\u5E76\u6559\u6388\u82F1\u8BED\uFF0C\u5BF9\u6559\u5E08\u57C3\u70ED\u5148\u751F\u4EA7\u751F\u4E86\u75DB\u82E6\u800C\u65E0\u671B\u7684\u611F\u60C5\u3002\u8FD9\u6BB5\u7ECF\u5386\u540E\u6765\u5728\u300A\u7EF4\u83B1\u7279\u300B\u4E2D\u7559\u4E0B\u4E86\u66F4\u6E05\u6670\u7684\u75D5\u8FF9\uFF0C\u4E5F\u6295\u6620\u5230\u300A\u7B80\xB7\u7231\u300B\u91CC\uFF1A\u7B80\u4E0E\u7F57\u5207\u65AF\u7279\u4E4B\u95F4\u90A3\u79CD\u77E5\u8BC6\u7684\u8F83\u91CF\u3001\u7CBE\u795E\u7684\u4EA4\u950B\u4E0E\u60C5\u611F\u7684\u514B\u5236\uFF0C\u5E95\u8272\u6B63\u662F\u8FD9\u6BB5\u7ECF\u5386\u3002\u5C0F\u8BF4\u7684\u526F\u6807\u9898\u662F\u300C\u4E00\u90E8\u81EA\u4F20\u300D\uFF0C\u5E76\u975E\u865A\u8A00\u3002",
      "## \u7537\u6027\u7B14\u540D\uFF1A\u5148\u81EA\u8D39\u51FA\u8BD7\u96C6\uFF0C\u518D\u5199\u5C0F\u8BF4",
      "1846 \u5E74\uFF0C\u4E09\u59D0\u59B9\u4EE5\u67EF\u52D2\xB7\u8D1D\u5C14\u3001\u57C3\u5229\u65AF\xB7\u8D1D\u5C14\u3001\u963F\u514B\u987F\xB7\u8D1D\u5C14\u4E09\u4E2A\u4E2D\u6027\u7B14\u540D\u81EA\u8D39\u51FA\u7248\u4E86\u4E00\u90E8\u8BD7\u96C6\uFF0C\u7ED3\u679C\u53EA\u5356\u51FA\u4E24\u672C\u30021847 \u5E74 8 \u6708\uFF0C\u300A\u7B80\xB7\u7231\u300B\u5B8C\u7A3F\u5E76\u5BC4\u7ED9\u4F26\u6566\u7684\u53F2\u5BC6\u65AF\xB7\u57C3\u5C14\u5FB7\u51FA\u7248\u793E\uFF0C\u540C\u5E74 10 \u6708\u51FA\u7248\uFF0C\u7F72\u540D\u4ECD\u662F\u300C\u67EF\u52D2\xB7\u8D1D\u5C14\u300D\u3002\u5F53\u65F6\u7684\u8BFB\u8005\u4EE5\u4E3A\u4F5C\u8005\u662F\u7537\u4EBA\uFF0C\u4E66\u8BC4\u91CC\u751A\u81F3\u6709\u4EBA\u5728\u731C\u8FD9\u4F4D\u65B0\u4F5C\u5BB6\u662F\u8C01\uFF1B\u76F4\u5230 1848 \u5E74\uFF0C\u590F\u6D1B\u8482\u4E0E\u59B9\u59B9\u5B89\u59AE\u5230\u4F26\u6566\u62DC\u8BBF\u51FA\u7248\u5546\uFF0C\u4F5C\u8005\u7684\u8EAB\u4EFD\u624D\u88AB\u8BC1\u5B9E\u3002\u7528\u7537\u6027\u7B14\u540D\uFF0C\u662F\u56E0\u4E3A\u5728\u90A3\u4E2A\u5E74\u4EE3\uFF0C\u5973\u4F5C\u5BB6\u8981\u88AB\u4EBA\u8BA4\u771F\u5BF9\u5F85\u5E76\u4E0D\u5BB9\u6613\u3002",
      "## \u5199\u5B8C\u8FD9\u672C\u4E66\u4E4B\u540E",
      "1848 \u5E74 9 \u6708\uFF0C\u5F1F\u5F1F\u5E03\u5170\u97E6\u5C14\u53BB\u4E16\uFF1B\u540C\u5E74 12 \u6708\uFF0C\u59B9\u59B9\u827E\u7C73\u8389\uFF08\u300A\u547C\u5578\u5C71\u5E84\u300B\u7684\u4F5C\u8005\uFF09\u53BB\u4E16\uFF1B1849 \u5E74 5 \u6708\uFF0C\u59B9\u59B9\u5B89\u59AE\u53BB\u4E16\u3002\u77ED\u77ED\u516B\u4E2A\u6708\u91CC\uFF0C\u5979\u5931\u53BB\u4E86\u4E09\u4E2A\u624B\u8DB3\uFF0C\u4E00\u5BB6\u4EBA\u76F8\u7EE7\u51CB\u96F6\u30021854 \u5E74 6 \u6708\uFF0C\u5979\u4E0E\u7236\u4EB2\u7684\u526F\u7267\u5E08\u5C3C\u79D1\u5C14\u65AF\u7ED3\u5A5A\uFF1B1855 \u5E74 3 \u6708 31 \u65E5\uFF0C\u5979\u75C5\u901D\uFF0C\u5E74\u4EC5\u4E09\u5341\u516B\u5C81\u3002\u5979\u4E00\u751F\u5199\u7684\u4F5C\u54C1\u5E76\u4E0D\u591A\uFF0C\u5374\u51E0\u4E4E\u6BCF\u4E00\u90E8\u90FD\u4ECE\u81EA\u5DF1\u7F13\u6162\u800C\u6C89\u91CD\u7684\u7ECF\u5386\u91CC\u957F\u51FA\u6765\u3002",
      "## \u81EA\u4F20\u8272\u5F69\u600E\u6837\u5E2E\u52A9\u6211\u4EEC\u8BFB\u8FD9\u672C\u4E66",
      "\u77E5\u9053\u590F\u6D1B\u8482\u7684\u8EAB\u4E16\uFF0C\u5C31\u80FD\u7406\u89E3\u7B80\xB7\u7231\u4E3A\u4EC0\u4E48\u628A\u300C\u5C0A\u4E25\u300D\u770B\u5F97\u6BD4\u300C\u7231\u60C5\u300D\u66F4\u91CD\uFF1A\u5979\u5728\u5A5A\u793C\u4E0A\u5F97\u77E5\u7F57\u5207\u65AF\u7279\u5DF2\u6709\u75AF\u59BB\uFF0C\u5B81\u53EF\u5728\u6DF1\u591C\u51FA\u8D70\u4E5F\u4E0D\u80AF\u505A\u4ED6\u7684\u60C5\u5987\uFF1B\u5979\u62D2\u7EDD\u5723\u7EA6\u7FF0\u65E0\u7231\u7684\u6C42\u5A5A\uFF0C\u56E0\u4E3A\u90A3\u6869\u5A5A\u59FB\u91CC\u6CA1\u6709\u5E73\u7B49\uFF1B\u6700\u540E\u5979\u5E26\u7740\u7EE7\u627F\u6765\u7684\u9057\u4EA7\uFF0C\u56DE\u5230\u5931\u660E\u6B8B\u75BE\u7684\u7F57\u5207\u65AF\u7279\u8EAB\u8FB9\u3002\u5979\u8981\u7684\u4E0D\u662F\u88AB\u62EF\u6551\uFF0C\u800C\u662F\u300C\u5E73\u7B49\u300D\u3002\u4E2D\u8003\u5E38\u8003\u300C\u7B80\xB7\u7231\u8FD9\u4E00\u5F62\u8C61\u7684\u610F\u4E49\u300D\uFF0C\u7B54\u6848\u7684\u6839\u5C31\u5728\u8FD9\u91CC\u2014\u2014\u4E00\u4E2A\u4E0D\u7F8E\u3001\u4E0D\u5BCC\u3001\u51FA\u8EAB\u4F4E\u5FAE\u7684\u5973\u6027\uFF0C\u51ED\u4EBA\u683C\u4E0E\u610F\u5FD7\u4E3A\u81EA\u5DF1\u4E89\u5F97\u4E86\u4F4D\u7F6E\u3002"
    ],
    think: [
      "\u590F\u6D1B\u8482\u7528\u7537\u6027\u7B14\u540D\u53D1\u8868\u5C0F\u8BF4\uFF0C\u8BF4\u660E\u5F53\u65F6\u5973\u4F5C\u5BB6\u9762\u4E34\u4EC0\u4E48\u6837\u7684\u5904\u5883\uFF1F\u8FD9\u4E00\u5904\u5883\u4E0E\u7B80\xB7\u7231\u7684\u6027\u683C\u6709\u4EC0\u4E48\u5173\u7CFB\uFF1F",
      "\u6709\u4EBA\u8BA4\u4E3A\uFF0C\u7B80\xB7\u7231\u76F4\u5230\u7EE7\u627F\u4E86\u9057\u4EA7\u624D\u80FD\u4E0E\u7F57\u5207\u65AF\u7279\u5E73\u7B49\u7ED3\u5408\uFF0C\u8FD9\u524A\u5F31\u4E86\u5C0F\u8BF4\u7684\u601D\u60F3\u529B\u91CF\u3002\u4F60\u600E\u4E48\u770B\uFF1F",
      "\u300C\u4F60\u4EE5\u4E3A\uFF0C\u56E0\u4E3A\u6211\u7A77\u3001\u4F4E\u5FAE\u3001\u4E0D\u7F8E\u3001\u77EE\u5C0F\uFF0C\u6211\u5C31\u6CA1\u6709\u7075\u9B42\u6CA1\u6709\u5FC3\u5417\uFF1F\u300D\u5982\u679C\u8FD9\u53E5\u8BDD\u7531\u300A\u7EA2\u697C\u68A6\u300B\u91CC\u7684\u6797\u9EDB\u7389\u8BF4\u51FA\uFF0C\u6548\u679C\u4F1A\u6709\u4EC0\u4E48\u4E0D\u540C\uFF1F"
    ]
  },
  {
    id: "ext-bg-tangshi",
    moduleId: "literature",
    entryId: "l-tangshi-sanbaishou",
    grade: "9a",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u5B59\u6D19\u4E3A\u4EC0\u4E48\u8981\u7F16\u4E00\u672C\u300C\u4E09\u767E\u9996\u300D",
    summary: "\u6E05\u4EE3\u5B59\u6D19\u5ACC\u300A\u5343\u5BB6\u8BD7\u300B\u9009\u5F97\u6742\u4E71\uFF0C\u4FBF\u4E13\u6311\u5510\u8BD7\u540D\u7BC7\uFF0C\u6309\u4F53\u88C1\u7F16\u6210\u300A\u5510\u8BD7\u4E09\u767E\u9996\u300B\u3002",
    content: [
      "## \u8605\u5858\u9000\u58EB\u662F\u8C01",
      "\u8605\u5858\u9000\u58EB\u672C\u540D\u5B59\u6D19\uFF081711 \u2014 1778\uFF09\uFF0C\u5B57\u4E34\u897F\uFF08\u4E00\u4F5C\u82D3\u897F\uFF09\uFF0C\u6C5F\u82CF\u65E0\u9521\u4EBA\uFF0C\u4E7E\u9686\u5341\u516D\u5E74\uFF081751 \u5E74\uFF09\u4E2D\u8FDB\u58EB\uFF0C\u505A\u8FC7\u77E5\u53BF\u548C\u6C5F\u5B81\u5E9C\u5B66\u6559\u6388\uFF0C\u4E3A\u5B98\u6709\u6E05\u540D\u3002\u4ED6\u751F\u6D3B\u7684\u4E7E\u9686\u65F6\u4EE3\uFF0C\u79D1\u4E3E\u4E0E\u8BD7\u6559\u90FD\u88AB\u770B\u5F97\u6781\u91CD\uFF0C\u8BFB\u4E66\u4EBA\u5BB6\u5BB6\u8981\u6559\u5B69\u5B50\u8BFB\u8BD7\u80CC\u8BD7\uFF0C\u5E02\u9762\u4E0A\u6025\u9700\u4E00\u672C\u9009\u5F97\u7CBE\u3001\u4F53\u4F8B\u6E05\u3001\u4FBF\u4E8E\u4E0A\u53E3\u7684\u8BFB\u672C\u3002\u4ED6\u7684\u8EAB\u4EFD\u2014\u2014\u65E2\u662F\u79D1\u4E3E\u51FA\u8EAB\u7684\u6587\u4EBA\uFF0C\u53C8\u662F\u7BA1\u6559\u80B2\u7684\u5B66\u5B98\u2014\u2014\u6070\u597D\u77E5\u9053\u5B69\u5B50\u8BE5\u4ECE\u4EC0\u4E48\u6837\u7684\u8BD7\u8BFB\u8D77\u3002",
      "## \u4E00\u672C\u300C\u4E0D\u6EE1\u610F\u300D\u7684\u5E8F",
      "\u5B59\u6D19\u5728\u81EA\u5E8F\u91CC\u628A\u7F16\u5199\u7F18\u7531\u8BF4\u5F97\u5F88\u76F4\u767D\uFF1A\u5C0F\u5B69\u5B50\u4E00\u4E0A\u5B66\u5C31\u5148\u8BFB\u300A\u5343\u5BB6\u8BD7\u300B\uFF0C\u56E0\u4E3A\u5B83\u5BB9\u6613\u80CC\u8BF5\uFF0C\u6240\u4EE5\u6D41\u4F20\u4E0D\u5E9F\uFF1B\u4F46\u300A\u5343\u5BB6\u8BD7\u300B\u300C\u968F\u624B\u6387\u62FE\uFF0C\u5DE5\u62D9\u83AB\u8FA8\u300D\uFF0C\u800C\u4E14\u53EA\u6709\u4E94\u4E03\u5F8B\u7EDD\u4E24\u79CD\u4F53\u88C1\uFF0C\u5510\u5B8B\u4EBA\u7684\u8BD7\u8FD8\u6DF7\u5728\u4E00\u8D77\uFF0C\u300C\u6B8A\u4E0D\u4E13\u300D\u3002\u9009\u5F97\u6742\u3001\u4F53\u4F8B\u4E0D\u6E05\u3001\u597D\u8BD7\u574F\u8BD7\u4E0D\u5206\uFF0C\u662F\u8FD9\u90E8\u901A\u884C\u8BFB\u672C\u6700\u8981\u7D27\u7684\u6BDB\u75C5\u3002\u4ED6\u8981\u505A\u7684\u4E8B\u60C5\u56E0\u6B64\u5F88\u6E05\u695A\uFF1A\u91CD\u65B0\u9009\uFF0C\u91CD\u65B0\u6392\u3002",
      "## \u4ED6\u7684\u529E\u6CD5\uFF1A\u6309\u4F53\u88C1\u5206\u5377",
      "\u4ED6\u5B9A\u7684\u6807\u51C6\u662F\u300C\u4E13\u5C31\u5510\u8BD7\u4E2D\u810D\u7099\u4EBA\u53E3\u4E4B\u4F5C\uFF0C\u62E9\u5176\u5C24\u8981\u8005\uFF0C\u6BCF\u4F53\u5F97\u6570\u5341\u9996\uFF0C\u5171\u4E09\u767E\u4F59\u9996\uFF0C\u5F55\u6210\u4E00\u7F16\uFF0C\u4E3A\u5BB6\u587E\u8BFE\u672C\uFF0C\u4FFE\u7AE5\u800C\u4E60\u4E4B\uFF0C\u767D\u9996\u4EA6\u83AB\u80FD\u5E9F\u300D\u3002\u5168\u4E66\u6309\u4E94\u8A00\u53E4\u8BD7\u3001\u4E03\u8A00\u53E4\u8BD7\u3001\u4E94\u8A00\u5F8B\u8BD7\u3001\u4E03\u8A00\u5F8B\u8BD7\u3001\u4E94\u8A00\u7EDD\u53E5\u3001\u4E03\u8A00\u7EDD\u53E5\u5206\u5377\uFF0C\u4E50\u5E9C\u8BD7\u9644\u5728\u76F8\u5E94\u4F53\u88C1\u4E4B\u540E\u3002\u8FD9\u6837\u7F16\u6392\u7684\u597D\u5904\u662F\u4F53\u88C1\u5206\u660E\u3001\u683C\u5F8B\u6E05\u695A\uFF1A\u8BFB\u4E00\u5377\u5C31\u80FD\u638C\u63E1\u4E00\u79CD\u8BD7\u4F53\u7684\u57FA\u672C\u9762\u8C8C\u3002\u5B83\u65E2\u662F\u4E00\u90E8\u5510\u8BD7\u9009\u672C\uFF0C\u4E5F\u662F\u4E00\u90E8\u5B66\u4F5C\u8BD7\u7684\u8303\u672C\u3002",
      "## \u592B\u59BB\u4E00\u8D77\u5546\u5B9A\u7BC7\u76EE",
      "\u76F8\u4F20\u5B59\u6D19\u7684\u7EE7\u5BA4\u592B\u4EBA\u5F90\u5170\u82F1\u5DE5\u4E8E\u8BD7\uFF0C\u7F16\u9009\u65F6\u66FE\u4E0E\u4ED6\u4E00\u540C\u5546\u5B9A\u7BC7\u76EE\u3002\u8FD9\u4EF6\u4E8B\u5728\u9009\u672C\u53F2\u4E0A\u5F88\u6709\u610F\u601D\uFF1A\u4E00\u90E8\u6D41\u4F20\u6700\u5E7F\u7684\u5510\u8BD7\u9009\u672C\uFF0C\u80CC\u540E\u4E5F\u6709\u4E00\u4F4D\u5973\u6027\u7684\u53C2\u4E0E\u3002\u4E66\u540D\u53EB\u300C\u4E09\u767E\u9996\u300D\uFF0C\u53D6\u81EA\u6C11\u8C1A\u300C\u719F\u8BFB\u5510\u8BD7\u4E09\u767E\u9996\uFF0C\u4E0D\u4F1A\u541F\u8BD7\u4E5F\u4F1A\u541F\u300D\uFF0C\u540C\u65F6\u4E5F\u6697\u7528\u300A\u8BD7\u7ECF\u300B\u300C\u8BD7\u4E09\u767E\u300D\u7684\u65E7\u79F0\uFF0C\u628A\u5510\u8BD7\u63A5\u5230\u8BD7\u6B4C\u4F20\u7EDF\u4E0A\u53BB\u3002",
      "## \u300C\u4E09\u767E\u9996\u300D\u4E0D\u53EA\u662F\u4E09\u767E\u9996",
      "\u901A\u884C\u672C\u5B9E\u9645\u9009\u8BD7\u4E09\u767E\u4E00\u5341\u4F59\u9996\uFF0C\u5165\u9009\u8BD7\u4EBA\u4E03\u5341\u4F59\u5BB6\uFF0C\u5176\u4E2D\u675C\u752B\u6700\u591A\uFF08\u7EA6\u4E09\u5341\u4E5D\u9996\uFF09\uFF0C\u5176\u6B21\u738B\u7EF4\uFF08\u7EA6\u4E8C\u5341\u4E5D\u9996\uFF09\u3001\u674E\u767D\uFF08\u7EA6\u4E8C\u5341\u4E03\u9996\uFF09\u3001\u674E\u5546\u9690\u7EA6\u4E8C\u5341\u56DB\u9996\uFF09\u3002\u9009\u76EE\u7684\u504F\u5411\u5F88\u660E\u663E\uFF1A\u591A\u53D6\u7BC7\u5E45\u77ED\u5C0F\u3001\u60C5\u97F5\u517C\u5907\u3001\u5BB6\u56FD\u60C5\u6000\u4E0E\u4EBA\u751F\u51B5\u5473\u517C\u5177\u7684\u540D\u7BC7\uFF0C\u5220\u53BB\u957F\u800C\u8270\u6DF1\u7684\u5947\u9669\u4E4B\u4F5C\u3002\u8FD9\u4E0D\u662F\u7F16\u8005\u7684\u773C\u754C\u4E0D\u591F\uFF0C\u800C\u662F\u300C\u5BB6\u587E\u8BFE\u672C\uFF0C\u4FFE\u7AE5\u800C\u4E60\u4E4B\u300D\u8FD9\u4E00\u5B9A\u4F4D\u51B3\u5B9A\u7684\u2014\u2014\u4ED6\u5148\u8981\u8BA9\u5B69\u5B50\u8BFB\u5F97\u4E0B\u53BB\u3002",
      "## \u5BF9\u6211\u4EEC\u8BFB\u8FD9\u672C\u9009\u672C\u7684\u610F\u4E49",
      "\u5B83\u662F\u4E3A\u7AE5\u8499\u7F16\u7684\uFF0C\u5374\u4E0D\u662F\u5E7C\u7A1A\u7684\u4E66\uFF1A\u300A\u6625\u671B\u300B\u300A\u767B\u9AD8\u300B\u300A\u51FA\u585E\u300B\u300A\u67AB\u6865\u591C\u6CCA\u300B\u300A\u767D\u96EA\u6B4C\u9001\u6B66\u5224\u5B98\u5F52\u4EAC\u300B\u90FD\u8DB3\u4EE5\u4EE3\u8868\u5510\u8BD7\u7684\u9AD8\u5EA6\u3002\u4E24\u5343\u591A\u5E74\u6765\u5B83\u98CE\u884C\u4E0D\u8870\uFF0C\u88AB\u79F0\u4F5C\u6D41\u4F20\u6700\u5E7F\u3001\u5F71\u54CD\u6700\u5927\u7684\u5510\u8BD7\u9009\u672C\u3002\u8BFB\u6CD5\u4E0A\uFF0C\u6309\u4F53\u88C1\u901A\u8BFB\u3001\u6309\u8BD7\u4EBA\u5F52\u7C7B\uFF08\u6BD4\u8F83\u674E\u767D\u4E0E\u675C\u752B\u3001\u738B\u7EF4\u4E0E\u5B5F\u6D69\u7136\uFF09\u3001\u6309\u4E3B\u9898\u6574\u7406\uFF08\u9001\u522B\u3001\u8FB9\u585E\u3001\u601D\u4E61\u3001\u5C71\u6C34\u7530\u56ED\u3001\u548F\u53F2\u6000\u53E4\uFF09\uFF0C\u90FD\u6BD4\u4ECE\u5934\u786C\u80CC\u6709\u6548\u3002\u80CC\u8BF5\u65F6\u7559\u610F\u6613\u9519\u5B57\uFF0C\u5982\u300C\u6E2D\u57CE\u671D\u96E8\u6D65\u8F7B\u5C18\u300D\u7684\u300C\u6D65\u300D\u3001\u300C\u6708\u843D\u4E4C\u557C\u971C\u6EE1\u5929\u300D\u7684\u300C\u4E4C\u300D\u3002"
    ],
    think: [
      "\u5B59\u6D19\u5ACC\u300A\u5343\u5BB6\u8BD7\u300B\u300C\u968F\u624B\u6387\u62FE\uFF0C\u5DE5\u62D9\u83AB\u8FA8\u300D\u3002\u5982\u679C\u4F60\u662F\u7F16\u8005\uFF0C\u9762\u5BF9\u4E09\u5343\u591A\u4F4D\u5510\u4EE3\u8BD7\u4EBA\uFF0C\u4F60\u4F1A\u7528\u4EC0\u4E48\u6807\u51C6\u9009\u8BD7\uFF1F",
      "\u300C\u4E3A\u5BB6\u587E\u8BFE\u672C\u300D\u8FD9\u4E00\u5B9A\u4F4D\u8BA9\u300A\u5510\u8BD7\u4E09\u767E\u9996\u300B\u504F\u91CD\u77ED\u5C0F\u7684\u540D\u7BC7\uFF0C\u8FD9\u6837\u7684\u504F\u597D\u662F\u4F18\u70B9\u8FD8\u662F\u5C40\u9650\uFF1F",
      "\u675C\u752B\u5165\u9009\u6700\u591A\uFF0C\u674E\u767D\u5374\u5C11\u4E8E\u738B\u7EF4\u3002\u4F60\u89C9\u5F97\u8FD9\u53EF\u80FD\u4E0E\u7F16\u8005\u7684\u4EC0\u4E48\u8003\u8651\u6709\u5173\uFF1F"
    ]
  },
  {
    id: "ext-bg-shuihu",
    moduleId: "literature",
    entryId: "l-shuihuzhuan",
    grade: "9b",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u5B8B\u6C5F\u8D77\u4E49\u53EA\u6709\u4E09\u5341\u516D\u4EBA\uFF1A\u4E00\u90E8\u5927\u4E66\u7684\u6765\u5386",
    summary: "\u5317\u5B8B\u5B8B\u6C5F\u8D77\u4E49\u7684\u53F2\u5B9E\u53EA\u6709\u96F6\u661F\u8BB0\u8F7D\uFF0C\u7ECF\u5B8B\u5143\u8BDD\u672C\u4E0E\u6742\u5267\u7D2F\u79EF\uFF0C\u624D\u6709\u4E86\u8FD9\u90E8\u5927\u4E66\u3002",
    content: [
      "## \u53F2\u4E66\u91CC\u7684\u5B8B\u6C5F",
      "\u300A\u6C34\u6D52\u4F20\u300B\u7684\u53F2\u5B9E\u5185\u6838\u5F88\u5C0F\u3002\u5317\u5B8B\u5BA3\u548C\u5E74\u95F4\uFF08\u7EA6 1119 \u2014 1121\uFF09\uFF0C\u5B8B\u6C5F\u7387\u4F17\u8D77\u4E49\uFF0C\u636E\u300A\u5B8B\u53F2\xB7\u4FAF\u8499\u4F20\u300B\u6240\u8F7D\uFF0C\u4FAF\u8499\u4E0A\u4E66\u8BF4\u300C\u6C5F\u4EE5\u4E09\u5341\u516D\u4EBA\u6A2A\u884C\u9F50\u9B4F\uFF0C\u5B98\u519B\u6570\u4E07\u65E0\u6562\u6297\u8005\u300D\uFF1B\u540E\u6765\u6D77\u5DDE\u77E5\u5DDE\u5F20\u53D4\u591C\u8BBE\u4F0F\uFF0C\u7528\u706B\u70E7\u5176\u8239\u53EA\uFF0C\u5B8B\u6C5F\u5175\u8D25\u88AB\u62DB\u964D\u3002\u81F3\u4E8E\u4ED6\u662F\u5426\u53C2\u4E0E\u5F81\u8BA8\u65B9\u814A\uFF0C\u53F2\u4E66\u7684\u8BB0\u8F7D\u5E76\u4E0D\u4E00\u81F4\u3002\u771F\u5B9E\u5386\u53F2\u7559\u4E0B\u7684\u53EA\u6709\u51E0\u5341\u4E2A\u5B57\uFF0C\u5C0F\u8BF4\u5374\u5199\u4E86\u6881\u5C71\u4E00\u767E\u96F6\u516B\u5C06\u3002\u4ECE\u8FD9\u6BB5\u8BB0\u8F7D\u5230\u4E00\u90E8\u767E\u4E07\u5B57\u7684\u5927\u4E66\uFF0C\u4E2D\u95F4\u9694\u7740\u4E24\u767E\u591A\u5E74\u7684\u6C11\u95F4\u521B\u9020\u3002",
      "## \u4ECE\u4E09\u5341\u516D\u4EBA\u5230\u4E00\u767E\u96F6\u516B\u4EBA",
      "\u5357\u5B8B\u7F57\u70E8\u300A\u9189\u7FC1\u8C08\u5F55\u300B\u5DF2\u8BB0\u6709\u300C\u9752\u9762\u517D\u300D\u300C\u82B1\u548C\u5C1A\u300D\u300C\u6B66\u884C\u8005\u300D\u7B49\u8BF4\u8BDD\u540D\u76EE\uFF1B\u5B8B\u672B\u5143\u521D\u9F9A\u5F00\u4F5C\u300A\u5B8B\u6C5F\u4E09\u5341\u516D\u4EBA\u8D5E\u300B\uFF0C\u4E3A\u4E09\u5341\u516D\u4EBA\u5404\u5199\u8D5E\u8BED\uFF1B\u5143\u521D\u7684\u300A\u5927\u5B8B\u5BA3\u548C\u9057\u4E8B\u300B\u5DF2\u7ECF\u51FA\u73B0\u300C\u667A\u53D6\u751F\u8FB0\u7EB2\u300D\u300C\u5B8B\u6C5F\u6740\u960E\u60DC\u5A07\u300D\u7B49\u60C5\u8282\uFF0C\u4EBA\u7269\u4E0E\u6545\u4E8B\u7684\u9AA8\u67B6\u5927\u81F4\u6210\u5F62\uFF1B\u5143\u4EE3\u6742\u5267\u4E2D\u7684\u6C34\u6D52\u620F\u591A\u8FBE\u4E09\u5341\u4F59\u79CD\uFF0C\u674E\u9035\u3001\u71D5\u9752\u3001\u6B66\u677E\u6210\u4E86\u821E\u53F0\u4E0A\u7684\u4E3B\u89D2\u3002\u6C34\u6D52\u6545\u4E8B\u5148\u5728\u8BF4\u4E66\u4EBA\u7684\u5634\u91CC\u3001\u5728\u620F\u53F0\u4E0A\u957F\u5927\uFF0C\u6700\u540E\u624D\u843D\u5230\u6587\u4EBA\u7684\u7B14\u4E0B\u3002",
      "## \u65BD\u8010\u5EB5\u662F\u4E2A\u4EC0\u4E48\u6837\u7684\u4EBA",
      "\u65BD\u8010\u5EB5\uFF08\u7EA6 1296 \u2014 \u7EA6 1370\uFF09\u662F\u5143\u672B\u660E\u521D\u4EBA\uFF0C\u6C5F\u82CF\u5174\u5316\uFF08\u4E00\u8BF4\u82CF\u5DDE\uFF09\u4EBA\u3002\u76F8\u4F20\u4ED6\u5143\u672B\u4E2D\u8FC7\u8FDB\u58EB\uFF0C\u5728\u94B1\u5858\u505A\u8FC7\u5B98\uFF0C\u56E0\u4E0D\u6EE1\u5B98\u573A\u9ED1\u6697\u800C\u5F03\u5B98\u5F52\u4E61\uFF0C\u665A\u5E74\u9690\u5C45\u8457\u4E66\uFF1B\u4E5F\u6709\u8BB0\u8F7D\u8BF4\u4ED6\u66FE\u5165\u5143\u672B\u5272\u636E\u8005\u5F20\u58EB\u8BDA\u7684\u5E55\u5E9C\u3002\u9700\u8981\u8BF4\u660E\u7684\u662F\uFF0C\u5173\u4E8E\u4ED6\u7684\u751F\u5E73\uFF0C\u53EF\u9760\u6750\u6599\u6781\u5C11\uFF0C\u8FDE\u540D\u5B57\u3001\u7C4D\u8D2F\u3001\u662F\u5426\u4E2D\u8FC7\u8FDB\u58EB\uFF0C\u5B66\u754C\u90FD\u6709\u4E89\u8BAE\uFF1B\u660E\u4EE3\u520A\u672C\u5E38\u7F72\u300C\u65BD\u8010\u5EB5\u96C6\u64B0\u3001\u7F57\u8D2F\u4E2D\u7E82\u4FEE\u300D\uFF0C\u76F8\u4F20\u4ED6\u7684\u5B66\u751F\u7F57\u8D2F\u4E2D\u66FE\u53C2\u4E0E\u6574\u7406\u3002",
      "## \u7248\u672C\uFF1A\u4E00\u767E\u56DE\u3001\u4E00\u767E\u4E8C\u5341\u56DE\u4E0E\u4E03\u5341\u56DE",
      "\u73B0\u5B58\u6700\u65E9\u7684\u5B8C\u6574\u520A\u672C\u662F\u4E07\u5386\u4E09\u5341\u516B\u5E74\uFF081610 \u5E74\uFF09\u7684\u5BB9\u4E0E\u5802\u523B\u672C\uFF0C\u4E00\u767E\u56DE\uFF0C\u5185\u5BB9\u5305\u62EC\u6881\u5C71\u805A\u4E49\u3001\u53D7\u62DB\u5B89\u4E0E\u5F81\u8FBD\u3001\u5F81\u65B9\u814A\uFF1B\u660E\u672B\u51FA\u73B0\u4E00\u79CD\u4E00\u767E\u4E8C\u5341\u56DE\u672C\uFF0C\u589E\u5165\u5F81\u7530\u864E\u3001\u5F81\u738B\u5E86\u7684\u6545\u4E8B\uFF1B\u660E\u672B\u6E05\u521D\u7684\u91D1\u5723\u53F9\u5219\u628A\u5168\u4E66\u5220\u6539\u4E3A\u4E03\u5341\u56DE\uFF0C\u780D\u6389\u62DB\u5B89\u4EE5\u540E\u7684\u60C5\u8282\uFF0C\u53E6\u52A0\u300C\u5362\u4FCA\u4E49\u60CA\u5669\u68A6\u300D\u4F5C\u7ED3\u3002\u4E0D\u540C\u7248\u672C\u8BFB\u51FA\u6765\u7684\u4E3B\u65E8\u5E76\u4E0D\u4E00\u6837\uFF1A\u4FDD\u7559\u62DB\u5B89\u4EE5\u540E\u7684\u5185\u5BB9\uFF0C\u8BFB\u8005\u770B\u5230\u7684\u662F\u300C\u5FE0\u4E49\u300D\u7684\u60B2\u5267\uFF1B\u5220\u6389\u4E4B\u540E\uFF0C\u5168\u4E66\u5C31\u505C\u5728\u805A\u4E49\u7684\u9876\u70B9\u4E0A\u3002",
      "## \u5143\u672B\u7684\u4E71\u4E16\u4E3A\u4EC0\u4E48\u4F1A\u5199\u51FA\u300C\u5B98\u903C\u6C11\u53CD\u300D",
      "\u5C0F\u8BF4\u91CC\u6700\u80FD\u8BF4\u660E\u4E3B\u65E8\u7684\u4E00\u70B9\u662F\uFF1A\u6881\u5C71\u597D\u6C49\u4E2D\u8BB8\u591A\u4EBA\u539F\u672C\u90FD\u4E0D\u662F\u9020\u53CD\u8005\u3002\u6797\u51B2\u662F\u4E1C\u4EAC\u516B\u5341\u4E07\u7981\u519B\u67AA\u68D2\u6559\u5934\uFF0C\u6B66\u677E\u662F\u53BF\u91CC\u7684\u90FD\u5934\uFF0C\u5B8B\u6C5F\u662F\u90D3\u57CE\u53BF\u7684\u62BC\u53F8\uFF0C\u6731\u4EDD\u662F\u9A6C\u5175\u90FD\u5934\u2014\u2014\u4ED6\u4EEC\u90FD\u6709\u4E00\u4EFD\u4F53\u9762\u7684\u5DEE\u4E8B\uFF0C\u90FD\u60F3\u8FC7\u5B89\u7A33\u65E5\u5B50\u3002\u4ED6\u4EEC\u662F\u88AB\u9AD8\u4FC5\u3001\u5F20\u90FD\u76D1\u3001\u5218\u9AD8\u3001\u9EC4\u6587\u70B3\u4E00\u5C42\u5C42\u9677\u5BB3\uFF0C\u4E00\u6B65\u6B65\u63A8\u5230\u6881\u5C71\u7684\u3002\u8FD9\u79CD\u300C\u903C\u300D\u7684\u903B\u8F91\uFF0C\u4E0E\u5143\u672B\u540F\u6CBB\u8150\u8D25\u3001\u6C11\u4E0D\u804A\u751F\u7684\u73B0\u5B9E\u6B63\u597D\u7167\u5E94\uFF0C\u4E5F\u662F\u4F5C\u8005\u5199\u8FD9\u90E8\u4E66\u7684\u7528\u5FC3\u6240\u5728\u3002",
      "## \u8BFB\u7684\u65F6\u5019\u8981\u7559\u610F\u4EC0\u4E48",
      "\u4E00\u662F\u5206\u8FA8\u53F2\u5B9E\u4E0E\u865A\u6784\uFF1A\u4E00\u767E\u96F6\u516B\u5C06\u4E2D\u7EDD\u5927\u591A\u6570\u662F\u6587\u5B66\u4EBA\u7269\uFF0C\u4E0D\u8981\u628A\u5C0F\u8BF4\u5F53\u5386\u53F2\uFF1B\u4E8C\u662F\u6CE8\u610F\u7248\u672C\u5DEE\u5F02\uFF0C\u5C24\u5176\u662F\u300C\u62DB\u5B89\u4E4B\u540E\u300D\u7684\u90E8\u5206\uFF0C\u7B54\u9898\u65F6\u6700\u597D\u8BF4\u660E\u4F9D\u636E\u7684\u662F\u54EA\u4E2A\u7248\u672C\uFF1B\u4E09\u662F\u6CE8\u610F\u4F5C\u8005\u5BF9\u66B4\u529B\u7684\u6001\u5EA6\uFF0C\u4E66\u4E2D\u65E2\u6709\u5BF9\u4E49\u4E3E\u7684\u8D5E\u7F8E\uFF0C\u4E5F\u6709\u5BF9\u6EE5\u6740\u65E0\u8F9C\u7684\u51B7\u5CFB\u63CF\u5199\uFF0C\u5176\u4E2D\u8FD8\u5939\u7740\u660E\u663E\u7684\u65F6\u4EE3\u5C40\u9650\uFF08\u5982\u5BF9\u5973\u6027\u7684\u8F7B\u6162\uFF09\u3002\u4E2D\u8003\u7684\u6BD4\u8F83\u63A2\u7A76\u9898\u5E38\u5E38\u5C31\u8BBE\u5728\u8FD9\u4E9B\u5730\u65B9\u3002"
    ],
    think: [
      "\u53F2\u4E66\u91CC\u7684\u5B8B\u6C5F\u300C\u4EE5\u4E09\u5341\u516D\u4EBA\u6A2A\u884C\u9F50\u9B4F\u300D\uFF0C\u5C0F\u8BF4\u5374\u5199\u5230\u4E00\u767E\u96F6\u516B\u5C06\u3002\u8FD9\u4E2A\u300C\u653E\u5927\u300D\u8BF4\u660E\u4E86\u4EC0\u4E48\uFF1F",
      "\u91D1\u5723\u53F9\u5220\u53BB\u62DB\u5B89\u4EE5\u540E\u7684\u60C5\u8282\uFF0C\u53EA\u7559\u4E03\u5341\u56DE\u3002\u4F60\u8BA4\u4E3A\u54EA\u79CD\u7ED3\u5C40\u66F4\u7B26\u5408\u300C\u5B98\u903C\u6C11\u53CD\u300D\u7684\u4E3B\u65E8\uFF1F",
      "\u6797\u51B2\u3001\u6B66\u677E\u3001\u5B8B\u6C5F\u539F\u672C\u90FD\u662F\u4F53\u5236\u5185\u7684\u4EBA\uFF0C\u4ED6\u4EEC\u7684\u5171\u540C\u906D\u9047\u8BA9\u4F60\u60F3\u5230\u4EC0\u4E48\uFF1F"
    ]
  },
  {
    id: "ext-bg-rulin",
    moduleId: "literature",
    entryId: "l-rulinwaishi",
    grade: "9b",
    kind: "\u80CC\u666F\u62D3\u5C55",
    title: "\u5434\u656C\u6893\u4E3A\u4EC0\u4E48\u5199\u5F97\u51FA\u8FD9\u6837\u4E00\u90E8\u8BBD\u523A\u4E4B\u4E66",
    summary: "\u5434\u656C\u6893\u51FA\u8EAB\u79D1\u4E3E\u4E16\u5BB6\u5374\u8D25\u5C3D\u5BB6\u4EA7\uFF0C\u665A\u5E74\u5728\u5357\u4EAC\u7684\u8D2B\u56F0\u4E2D\u5199\u51FA\u5112\u6797\u4F17\u751F\u3002",
    content: [
      "## \u4E00\u4E2A\u79D1\u4E3E\u4E16\u5BB6\u51FA\u6765\u7684\u300C\u8D25\u5BB6\u5B50\u300D",
      "\u5434\u656C\u6893\uFF081701 \u2014 1754\uFF09\uFF0C\u5B57\u654F\u8F69\uFF0C\u53F7\u7C92\u6C11\uFF0C\u665A\u5E74\u53C8\u53F7\u6587\u6728\u8001\u4EBA\uFF0C\u5B89\u5FBD\u5168\u6912\u4EBA\u3002\u4ED6\u7684\u66FE\u7956\u5434\u56FD\u5BF9\u662F\u987A\u6CBB\u5E74\u95F4\u7684\u63A2\u82B1\uFF0C\u5BB6\u65CF\u51E0\u4EE3\u4EBA\u90FD\u9760\u79D1\u4E3E\u505A\u5B98\uFF0C\u95E8\u7B2C\u5F88\u76DB\u3002\u4ED6\u5341\u4E09\u5C81\u4E27\u6BCD\uFF0C\u4E8C\u5341\u51FA\u5934\u7236\u4EB2\u53BB\u4E16\uFF0C\u7EE7\u627F\u9057\u4EA7\u4E4B\u540E\u6177\u6168\u597D\u65BD\u3001\u4E0D\u5584\u6CBB\u751F\uFF0C\u300C\u7530\u5E90\u5C3D\u5356\uFF0C\u4E61\u91CC\u4F20\u4E3A\u5B50\u5F1F\u6212\u300D\u3002\u5728\u4E00\u4E2A\u4EE5\u529F\u540D\u4E3A\u8363\u5149\u7684\u5BB6\u65CF\u91CC\uFF0C\u4ED6\u5148\u6210\u4E86\u88AB\u4EBA\u8BAE\u8BBA\u7684\u53CD\u9762\u4F8B\u5B50\u3002\u8FD9\u6BB5\u7ECF\u5386\u4F7F\u4ED6\u65E2\u6DF1\u77E5\u79D1\u4E3E\u4EBA\u5BB6\u7684\u4F53\u9762\u4E0E\u7B97\u8BA1\uFF0C\u4E5F\u5C1D\u5230\u4E86\u88AB\u4EBA\u8F7B\u89C6\u7684\u6ECB\u5473\u3002",
      "## \u79FB\u5C45\u5357\u4EAC\u4E0E\u4E00\u6B21\u62D2\u7EDD",
      "\u4E09\u5341\u4E09\u5C81\u524D\u540E\uFF0C\u4ED6\u79FB\u5C45\u5357\u4EAC\u79E6\u6DEE\u6C34\u4EAD\uFF0C\u9760\u5356\u6587\u4E0E\u670B\u53CB\u63A5\u6D4E\u5EA6\u65E5\u3002\u4E7E\u9686\u5143\u5E74\uFF081736 \u5E74\uFF09\uFF0C\u5B89\u5FBD\u5DE1\u629A\u8350\u4E3E\u4ED6\u5E94\u535A\u5B66\u9E3F\u8BCD\u79D1\uFF0C\u4ED6\u6258\u75C5\u4E0D\u53BB\u3002\u5BF9\u5F53\u65F6\u7684\u8BFB\u4E66\u4EBA\u6765\u8BF4\uFF0C\u8FD9\u662F\u53EF\u9047\u4E0D\u53EF\u6C42\u7684\u673A\u4F1A\uFF1B\u4ED6\u7684\u62D2\u7EDD\uFF0C\u672C\u8EAB\u5C31\u662F\u4E00\u79CD\u8868\u6001\u3002\u628A\u8FD9\u4EF6\u4E8B\u4E0E\u4ED6\u7B14\u4E0B\u7684\u8303\u8FDB\u3001\u5468\u8FDB\u653E\u5728\u4E00\u8D77\u770B\uFF0C\u5C31\u80FD\u660E\u767D\u300A\u5112\u6797\u5916\u53F2\u300B\u7684\u601D\u60F3\u503E\u5411\u4ECE\u54EA\u91CC\u6765\uFF1A\u4ED6\u5E76\u4E0D\u662F\u4E0D\u61C2\u529F\u540D\uFF0C\u800C\u662F\u770B\u900F\u4E86\u529F\u540D\u3002",
      "## \u665A\u5E74\u7684\u7A77\uFF1A\u51B7\u773C\u662F\u4ECE\u54EA\u91CC\u6765\u7684",
      "\u4ED6\u7684\u665A\u5E74\u6781\u4E3A\u8D2B\u56F0\u3002\u53CB\u4EBA\u7A0B\u664B\u82B3\u5728\u300A\u6587\u6728\u5148\u751F\u4F20\u300B\u4E2D\u8BB0\u4E0B\u8FD9\u6837\u4E00\u4EF6\u4E8B\uFF1A\u51AC\u5929\u82E6\u5BD2\uFF0C\u6CA1\u6709\u9152\u98DF\uFF0C\u4ED6\u5C31\u9080\u4E0A\u4E94\u516D\u4F4D\u670B\u53CB\u4E58\u7740\u6708\u8272\u51FA\u57CE\u5357\u95E8\uFF0C\u7ED5\u7740\u57CE\u5899\u8D70\u51E0\u5341\u91CC\uFF0C\u4E00\u8DEF\u6B4C\u541F\u957F\u5578\u3001\u4E92\u76F8\u5E94\u548C\uFF0C\u5230\u5929\u4EAE\u624D\u8FDB\u57CE\uFF0C\u5404\u81EA\u5927\u7B11\u7740\u6563\u53BB\uFF0C\u591C\u591C\u5982\u6B64\uFF0C\u4ED6\u79F0\u4E4B\u4E3A\u300C\u6696\u8DB3\u300D\u30021754 \u5E74\uFF0C\u4ED6\u5728\u626C\u5DDE\uFF08\u4E00\u8BF4\u4EEA\u5F81\uFF09\u75C5\u901D\u3002\u505A\u8FC7\u5BCC\u8D35\u5B50\u5F1F\uFF0C\u4E5F\u505A\u8FC7\u7A77\u6587\u4EBA\uFF0C\u4ED6\u624D\u770B\u5F97\u6E05\u529F\u540D\u5BCC\u8D35\u600E\u6837\u5851\u9020\u4EBA\u3001\u53C8\u600E\u6837\u8150\u8680\u4EBA\u3002",
      "## \u4E66\u4E2D\u4EBA\u7269\u5927\u591A\u6709\u539F\u578B",
      "\u300A\u5112\u6797\u5916\u53F2\u300B\u7EA6\u6210\u4E66\u4E8E\u4E7E\u9686\u5341\u56DB\u5E74\uFF081749 \u5E74\uFF09\u524D\u540E\uFF0C\u5171\u4E94\u5341\u516D\u56DE\uFF1B\u73B0\u5B58\u6700\u65E9\u7684\u523B\u672C\u662F\u5609\u5E86\u516B\u5E74\uFF081803 \u5E74\uFF09\u7684\u5367\u95F2\u8349\u5802\u672C\u3002\u4E66\u4E2D\u4EBA\u7269\u591A\u6709\u539F\u578B\uFF1A\u9A6C\u7EAF\u4E0A\u7684\u539F\u578B\u662F\u51AF\u7CB9\u4E2D\uFF0C\u5E84\u7ECD\u5149\u662F\u7A0B\u5EF7\u795A\u7684\u5F71\u5B50\uFF0C\u675C\u5C11\u537F\u8EAB\u4E0A\u6709\u4F5C\u8005\u81EA\u5DF1\u7684\u5F71\u5B50\uFF0C\u865E\u80B2\u5FB7\u3001\u8FDF\u8861\u5C71\u7B49\u4E5F\u5404\u6709\u5176\u4EBA\u3002\u5168\u4E66\u5F00\u7BC7\u7684\u738B\u5195\u662F\u5143\u672B\u660E\u521D\u7684\u771F\u5B9E\u4EBA\u7269\uFF0C\u4F5C\u8005\u501F\u4ED6\u7ED9\u5168\u4E66\u7ACB\u4E00\u4E2A\u4E0D\u6155\u529F\u540D\u7684\u6807\u6746\u3002\u5199\u300C\u5B9E\u6709\u7684\u4EBA\u548C\u4E8B\u300D\uFF0C\u6B63\u662F\u8FD9\u90E8\u4E66\u8BBD\u523A\u529B\u91CF\u7684\u6765\u6E90\u3002",
      "## \u4E3A\u4EC0\u4E48\u53EB\u300C\u5916\u53F2\u300D",
      "\u300C\u5112\u6797\u300D\u6307\u8BFB\u4E66\u4EBA\u8FD9\u4E2A\u7FA4\u4F53\uFF0C\u300C\u5916\u53F2\u300D\u5219\u6709\u522B\u4E8E\u6B63\u53F2\uFF1A\u6B63\u53F2\u5199\u7684\u662F\u5E1D\u738B\u5C06\u76F8\u7684\u519B\u56FD\u5927\u4E8B\uFF0C\u8FD9\u90E8\u4E66\u5199\u7684\u662F\u4E00\u7FA4\u666E\u901A\u8BFB\u4E66\u4EBA\u7684\u65E5\u5E38\u2014\u2014\u4E2D\u4E3E\u3001\u53D1\u75AF\u3001\u5B88\u8D22\u3001\u5439\u725B\u3001\u884C\u9A97\u3001\u7ED3\u4EA4\u540D\u58EB\u3001\u4E92\u76F8\u6807\u699C\u3002\u4F5C\u8005\u4E0D\u5199\u4F20\u5947\u82F1\u96C4\uFF0C\u53EA\u5199\u8EAB\u8FB9\u7684\u5C0F\u4EBA\u7269\uFF0C\u4ECE\u4ED6\u4EEC\u7684\u8A00\u884C\u91CC\u7167\u51FA\u5236\u5EA6\u7684\u8352\u5510\u3002\u8FD9\u4E2A\u4E66\u540D\u672C\u8EAB\u5C31\u5BA3\u544A\u4E86\u4ED6\u7684\u5199\u6CD5\uFF1A\u4E0D\u5199\u5927\u4E8B\uFF0C\u53EA\u5199\u4E16\u76F8\u3002",
      "## \u9C81\u8FC5\u7684\u5224\u65AD\u4E0E\u6211\u4EEC\u7684\u8BFB\u6CD5",
      "\u9C81\u8FC5\u5728\u300A\u4E2D\u56FD\u5C0F\u8BF4\u53F2\u7565\u300B\u91CC\u8BC4\u4EF7\u300A\u5112\u6797\u5916\u53F2\u300B\uFF1A\u300C\u4E43\u79C9\u6301\u516C\u5FC3\uFF0C\u6307\u64FF\u65F6\u5F0A\uFF0C\u673A\u950B\u6240\u5411\uFF0C\u5C24\u5728\u58EB\u6797\uFF1B\u5176\u6587\u53C8\u621A\u800C\u80FD\u8C10\uFF0C\u5A49\u800C\u591A\u8BBD\u300D\uFF0C\u5E76\u6307\u51FA\u5B83\u300C\u867D\u4E91\u957F\u7BC7\uFF0C\u9887\u540C\u77ED\u5236\u300D\u2014\u2014\u7531\u4E00\u4E2A\u4E2A\u4E2D\u5FC3\u4EBA\u7269\u7684\u77ED\u7BC7\u8FDE\u7F00\u800C\u6210\u3002\u8BFB\u8FD9\u672C\u4E66\uFF0C\u8981\u80FD\u4ECE\u8303\u8FDB\u4E2D\u4E3E\u53D1\u75AF\u3001\u5468\u8FDB\u649E\u53F7\u677F\u75DB\u54ED\u3001\u4E25\u76D1\u751F\u4E34\u6B7B\u4F38\u7740\u4E24\u6839\u624B\u6307\u4E0D\u80AF\u54BD\u6C14\u8FD9\u4E9B\u51B7\u5CFB\u7684\u7EC6\u8282\u91CC\uFF0C\u770B\u51FA\u4F5C\u8005\u8BBD\u523A\u4E0E\u60B2\u60AF\u5E76\u5B58\u7684\u7B14\u6CD5\uFF1A\u4ED6\u7B11\u4ED6\u4EEC\uFF0C\u4E5F\u601C\u4ED6\u4EEC\u3002"
    ],
    think: [
      "\u5434\u656C\u6893\u62D2\u7EDD\u4E86\u535A\u5B66\u9E3F\u8BCD\u79D1\u7684\u8350\u4E3E\uFF0C\u8FD9\u4EF6\u4E8B\u4E0E\u4ED6\u7B14\u4E0B\u7684\u5112\u6797\u4F17\u751F\u6709\u4EC0\u4E48\u5173\u7CFB\uFF1F",
      "\u300A\u5112\u6797\u5916\u53F2\u300B\u5199\u7684\u5927\u591A\u662F\u300C\u5B9E\u6709\u7684\u4EBA\u548C\u4E8B\u300D\u3002\u4E0E\u51ED\u7A7A\u865A\u6784\u76F8\u6BD4\uFF0C\u8FD9\u6837\u7684\u5199\u6CD5\u4E3A\u4EC0\u4E48\u8BBD\u523A\u529B\u91CF\u66F4\u5F3A\uFF1F",
      "\u9C81\u8FC5\u8BF4\u5B83\u300C\u621A\u800C\u80FD\u8C10\uFF0C\u5A49\u800C\u591A\u8BBD\u300D\u3002\u8BF7\u4ECE\u8303\u8FDB\u3001\u5468\u8FDB\u3001\u4E25\u76D1\u751F\u4E2D\u9009\u4E00\u4E2A\u4EBA\u7269\uFF0C\u8BF4\u8BF4\u4F5C\u8005\u5BF9\u4ED6\u6709\u6CA1\u6709\u540C\u60C5\u3002"
    ]
  },
  /* ================================================================ */
  /* 二、对比阅读（6 条，跨书比较）                                     */
  /* ================================================================ */
  {
    id: "ext-cmp-linchong-xiangzi",
    moduleId: "literature",
    entryId: "l-shuihuzhuan",
    grade: "9b",
    kind: "\u5BF9\u6BD4\u9605\u8BFB",
    title: "\u6797\u51B2\u4E0E\u7965\u5B50\uFF1A\u4E24\u79CD\u300C\u88AB\u903C\u300D",
    summary: "\u6797\u51B2\u4E00\u5FCD\u518D\u5FCD\u7EC8\u4E8E\u53CD\u6297\uFF0C\u7965\u5B50\u4E00\u62FC\u518D\u62FC\u7EC8\u4E8E\u5815\u843D\uFF1B\u540C\u662F\u88AB\u903C\uFF0C\u4E00\u4E2A\u8D70\u4E0A\u6881\u5C71\uFF0C\u4E00\u4E2A\u8D70\u5411\u672B\u8DEF\u3002",
    content: [
      "## \u4E24\u4E2A\u8001\u5B9E\u4EBA\u7684\u5F00\u5934",
      "\u6797\u51B2\u662F\u4E1C\u4EAC\u516B\u5341\u4E07\u7981\u519B\u67AA\u68D2\u6559\u5934\uFF0C\u6709\u5BB6\u5BA4\u3001\u6709\u4F53\u9762\u7684\u5DEE\u4E8B\uFF0C\u4E3A\u4EBA\u9690\u5FCD\u3001\u8BB2\u7A76\u5206\u5BF8\u3002\u59BB\u5B50\u88AB\u9AD8\u8859\u5185\u8C03\u620F\uFF0C\u4ED6\u4E3E\u8D77\u62F3\u5934\u53C8\u653E\u4E0B\u2014\u2014\u56E0\u4E3A\u5BF9\u65B9\u662F\u9AD8\u592A\u5C09\u7684\u5E72\u513F\u5B50\uFF0C\u300C\u4E0D\u6015\u5B98\uFF0C\u53EA\u6015\u7BA1\u300D\u3002\u7965\u5B50\u662F\u5317\u5E73\u57CE\u91CC\u4E00\u4E2A\u5065\u58EE\u3001\u8981\u5F3A\u3001\u4F53\u9762\u7684\u6D0B\u8F66\u592B\uFF0C\u6700\u5927\u7684\u68A6\u60F3\u662F\u6512\u94B1\u4E70\u4E00\u8F86\u81EA\u5DF1\u7684\u8F66\uFF0C\u8FD9\u6837\u5C31\u4E0D\u5FC5\u518D\u53D7\u8F66\u5382\u7684\u6C14\u3002\u4E24\u4E2A\u4EBA\u90FD\u76F8\u4FE1\u89C4\u77E9\uFF0C\u90FD\u60F3\u8FC7\u5B89\u5206\u7684\u65E5\u5B50\uFF0C\u90FD\u662F\u9760\u672C\u4E8B\u5403\u996D\u7684\u5B9E\u5728\u4EBA\u3002\u4ED6\u4EEC\u7684\u60B2\u5267\uFF0C\u90FD\u662F\u4ECE\u8FD9\u4EFD\u300C\u8001\u5B9E\u300D\u5F00\u59CB\u7684\u3002",
      "## \u6797\u51B2\u7684\u300C\u903C\u300D\uFF1A\u4E00\u6B21\u6BD4\u4E00\u6B21\u72E0",
      "\u6797\u51B2\u7684\u906D\u9047\u662F\u4E00\u6761\u5C42\u5C42\u52A0\u7801\u7684\u8FEB\u5BB3\u94FE\uFF1A\u88AB\u8BF1\u5165\u767D\u864E\u5802\uFF0C\u4EE5\u6301\u5200\u8FDB\u5165\u519B\u673A\u91CD\u5730\u4E3A\u7F6A\u540D\u523A\u914D\u6CA7\u5DDE\uFF1B\u62BC\u89E3\u9014\u4E2D\u5728\u91CE\u732A\u6797\u9669\u88AB\u8463\u8D85\u3001\u859B\u9738\u5BB3\u6B7B\uFF0C\u5E78\u5F97\u9C81\u667A\u6DF1\u76F8\u6551\uFF1B\u5230\u6CA7\u5DDE\u7262\u57CE\u8425\u770B\u5B88\u8349\u6599\u573A\uFF0C\u9646\u8C26\u3001\u5BCC\u5B89\u3001\u5DEE\u62E8\u53C8\u653E\u706B\u70E7\u8349\u6599\u573A\u8981\u5BB3\u4ED6\u6027\u547D\u3002\u76F4\u5230\u98CE\u96EA\u5C71\u795E\u5E99\uFF0C\u4ED6\u6740\u6B7B\u8FD9\u4E09\u4E2A\u4EC7\u4EBA\uFF0C\u96EA\u591C\u4E0A\u4E86\u6881\u5C71\u3002\u6574\u4E2A\u8FC7\u7A0B\u91CC\uFF0C\u4ED6\u6BCF\u4E00\u6B21\u90FD\u60F3\u5FCD\uFF0C\u6BCF\u4E00\u6B21\u90FD\u9000\u8BA9\uFF0C\u662F\u88AB\u4E00\u6B65\u4E00\u6B65\u63A8\u5230\u9000\u65E0\u53EF\u9000\u2014\u2014\u8FD9\u5C31\u662F\u300C\u5B98\u903C\u6C11\u53CD\u300D\u56DB\u4E2A\u5B57\u6700\u5B8C\u6574\u7684\u6F14\u793A\u3002",
      "## \u7965\u5B50\u7684\u300C\u903C\u300D\uFF1A\u4E00\u843D\u518D\u843D\u6CA1\u6709\u5C3D\u5934",
      "\u7965\u5B50\u7684\u906D\u9047\u662F\u53E6\u4E00\u6761\u94FE\u6761\uFF1A\u7B2C\u4E00\u6B21\u4E70\u8F66\uFF0C\u8FDE\u4EBA\u5E26\u8F66\u88AB\u5927\u5175\u6293\u8D70\uFF0C\u9003\u51FA\u65F6\u7275\u56DE\u4E09\u5339\u9A86\u9A7C\u5356\u4E86\u4E09\u5341\u4E94\u5757\u94B1\uFF0C\u4ECE\u6B64\u843D\u4E0B\u300C\u9A86\u9A7C\u7965\u5B50\u300D\u7684\u5916\u53F7\uFF1B\u7B2C\u4E8C\u6B21\u6512\u591F\u4E86\u94B1\uFF0C\u88AB\u5B59\u4FA6\u63A2\u6572\u8BC8\u4E00\u7A7A\uFF1B\u7B2C\u4E09\u6B21\u662F\u864E\u599E\u51FA\u94B1\u4E70\u4E86\u8F66\uFF0C\u864E\u599E\u96BE\u4EA7\u6B7B\u540E\uFF0C\u4ED6\u53EA\u80FD\u5356\u8F66\u529E\u4E27\u4E8B\uFF1B\u6700\u540E\u5C0F\u798F\u5B50\u4E0A\u540A\u81EA\u6740\uFF0C\u538B\u57AE\u4E86\u4ED6\u6700\u540E\u4E00\u70B9\u5FF5\u60F3\u3002\u6797\u51B2\u7684\u654C\u4EBA\u662F\u5177\u4F53\u7684\u4EBA\uFF0C\u7965\u5B50\u7684\u5BF9\u624B\u5374\u662F\u5175\u3001\u4FA6\u63A2\u3001\u8F66\u5382\u4E3B\u3001\u7578\u5F62\u7684\u5A5A\u59FB\u2014\u2014\u6BCF\u4E00\u79CD\u529B\u91CF\u90FD\u4E0D\u540C\uFF0C\u6BCF\u4E00\u6B21\u91CD\u6765\u90FD\u88AB\u6253\u788E\u3002",
      "## \u5173\u952E\u5DEE\u522B\uFF1A\u6709\u6CA1\u6709\u51FA\u8DEF\u4E0E\u96C6\u4F53",
      "\u6797\u51B2\u7684\u53CD\u6297\u6709\u4E00\u4E2A\u53BB\u5904\uFF1A\u6881\u5C71\u3002\u90A3\u91CC\u6709\u4E00\u7FA4\u540C\u6837\u88AB\u903C\u4E0A\u5C71\u7684\u5144\u5F1F\uFF0C\u6709\u4E00\u4E2A\u300C\u66FF\u5929\u884C\u9053\u300D\u7684\u65D7\u53F7\uFF0C\u6709\u4E00\u79CD\u96C6\u4F53\u7684\u79E9\u5E8F\u53EF\u4EE5\u4F9D\u9760\u3002\u4ED6\u7684\u53CD\u6297\u56E0\u6B64\u4ECE\u4E2A\u4EBA\u8F6C\u5411\u4E86\u96C6\u4F53\uFF0C\u6240\u4EE5\u5C3D\u7BA1\u7ED3\u5C40\u60B2\u51C9\u2014\u2014\u5F81\u65B9\u814A\u540E\u98CE\u762B\uFF0C\u7559\u5728\u676D\u5DDE\u516D\u548C\u5BFA\uFF0C\u534A\u5E74\u540E\u75C5\u6545\u2014\u2014\u4ED6\u59CB\u7EC8\u662F\u4E2A\u82F1\u96C4\u3002\u7965\u5B50\u6CA1\u6709\u4EFB\u4F55\u51FA\u8DEF\uFF1A\u6CA1\u6709\u540C\u4F34\uFF0C\u6CA1\u6709\u7EC4\u7EC7\uFF0C\u6CA1\u6709\u4FE1\u4EF0\uFF0C\u53EA\u6709\u4E00\u4E2A\u4E70\u8F66\u7684\u68A6\u60F3\u3002\u4ED6\u53CD\u6297\u7684\u5BF9\u8C61\u6A21\u7CCA\u4E0D\u6E05\uFF0C\u4E8E\u662F\u4ED6\u53EA\u80FD\u628A\u6068\u8F6C\u5411\u81EA\u5DF1\u548C\u8EAB\u8FB9\u7684\u4EBA\uFF0C\u6700\u540E\u8D70\u5411\u5815\u843D\u3002",
      "## \u4E3B\u65E8\u5DEE\u5F02\uFF1A\u6279\u5224\u7684\u65B9\u5411\u4E0D\u540C",
      "\u300A\u6C34\u6D52\u4F20\u300B\u7684\u77DB\u5934\u6307\u5411\u5C01\u5EFA\u7EDF\u6CBB\u9636\u7EA7\u7684\u8150\u8D25\u4E0E\u9ED1\u6697\uFF0C\u5199\u300C\u5B98\u903C\u6C11\u53CD\u300D\uFF0C\u80AF\u5B9A\u53CD\u6297\u7684\u6B63\u5F53\u6027\uFF1A\u4E00\u4E2A\u672C\u6765\u5B88\u6CD5\u7684\u4EBA\u88AB\u903C\u5230\u6740\u4EBA\u9020\u53CD\uFF0C\u7F6A\u4E0D\u5728\u4ED6\uFF0C\u7F6A\u5728\u903C\u4ED6\u7684\u5236\u5EA6\u3002\u300A\u9A86\u9A7C\u7965\u5B50\u300B\u7684\u6279\u5224\u5219\u662F\u53CC\u91CD\u7684\uFF1A\u65E2\u6279\u5224\u90A3\u4E2A\u300C\u4E0D\u8BA9\u597D\u4EBA\u6709\u51FA\u8DEF\u300D\u7684\u793E\u4F1A\uFF0C\u4E5F\u6279\u5224\u4E2A\u4EBA\u594B\u6597\u672C\u8EAB\u2014\u2014\u8001\u820D\u7ED9\u7965\u5B50\u7684\u5B9A\u8BBA\u662F\u300C\u4E2A\u4EBA\u4E3B\u4E49\u7684\u672B\u8DEF\u9B3C\u300D\u3002\u6797\u51B2\u662F\u88AB\u793E\u4F1A\u903C\u6210\u4E86\u82F1\u96C4\uFF0C\u7965\u5B50\u662F\u88AB\u793E\u4F1A\u78E8\u6210\u4E86\u9B3C\u3002\u8FD9\u4E2A\u5DEE\u522B\uFF0C\u5C31\u662F\u4E24\u90E8\u4F5C\u54C1\u4E3B\u65E8\u7684\u5206\u91CE\u3002",
      "## \u6BD4\u8F83\u9898\u600E\u6837\u843D\u7B14",
      "\u4E2D\u8003\u7684\u6BD4\u8F83\u63A2\u7A76\u9898\u5E38\u95EE\uFF1A\u540C\u662F\u88AB\u903C\u8FEB\uFF0C\u4E24\u4EBA\u7684\u8FC7\u7A0B\u4E0E\u7ED3\u5C40\u4E3A\u4EC0\u4E48\u4E0D\u540C\uFF1F\u7B54\u9898\u7684\u843D\u70B9\u5E94\u6709\u4E09\u5C42\u3002\u7B2C\u4E00\u5C42\u662F\u8FC7\u7A0B\u5F62\u6001\u4E0D\u540C\uFF1A\u6797\u51B2\u662F\u300C\u7531\u987A\u5230\u53CD\u300D\u7684\u8F6C\u53D8\uFF0C\u7965\u5B50\u662F\u300C\u7531\u594B\u6597\u5230\u5815\u843D\u300D\u7684\u4E0B\u5760\u3002\u7B2C\u4E8C\u5C42\u662F\u539F\u56E0\u4E0D\u540C\uFF1A\u4EBA\u7269\u6240\u5904\u7684\u793E\u4F1A\u6027\u8D28\u4E0D\u540C\uFF08\u5C01\u5EFA\u5B98\u573A\u4E0E\u534A\u6B96\u6C11\u5730\u534A\u5C01\u5EFA\u7684\u90FD\u5E02\u5E95\u5C42\uFF09\uFF0C\u6709\u65E0\u96C6\u4F53\u51FA\u8DEF\u4E0D\u540C\uFF0C\u81EA\u8EAB\u7684\u7CBE\u795E\u8D44\u6E90\u4E0D\u540C\uFF08\u6797\u51B2\u6709\u6B66\u827A\u3001\u6709\u540D\u58F0\u3001\u6709\u670B\u53CB\uFF0C\u7965\u5B50\u53EA\u6709\u529B\u6C14\u548C\u4E00\u4E2A\u7269\u8D28\u76EE\u6807\uFF09\u3002\u7B2C\u4E09\u5C42\u662F\u4F5C\u8005\u610F\u56FE\u4E0D\u540C\uFF1A\u4E00\u4E2A\u5199\u53CD\u6297\u7684\u5FC5\u7136\uFF0C\u4E00\u4E2A\u5199\u4E2A\u4EBA\u594B\u6597\u7684\u7834\u706D\u3002"
    ],
    think: [
      "\u5982\u679C\u6797\u51B2\u751F\u6D3B\u5728\u7965\u5B50\u7684\u65F6\u4EE3\uFF0C\u4ED6\u8FD8\u80FD\u4E0A\u6881\u5C71\u5417\uFF1F\u5982\u679C\u7965\u5B50\u751F\u5728\u5317\u5B8B\u672B\u5E74\uFF0C\u4ED6\u4F1A\u6210\u4E3A\u6881\u5C71\u597D\u6C49\u5417\uFF1F",
      "\u6797\u51B2\u7684\u9690\u5FCD\u5E38\u88AB\u8D5E\u4E3A\u5FCD\u8FB1\u8D1F\u91CD\uFF0C\u7965\u5B50\u7684\u5FCD\u8010\u5374\u53EA\u6362\u6765\u5815\u843D\u3002\u540C\u6837\u7684\u300C\u5FCD\u300D\uFF0C\u8BC4\u4EF7\u4E3A\u4EC0\u4E48\u4E0D\u540C\uFF1F",
      "\u4E24\u4F4D\u4F5C\u8005\u4E00\u4E2A\u5199\u51FA\u4E86\u53CD\u6297\u7684\u51FA\u8DEF\uFF0C\u4E00\u4E2A\u5199\u51FA\u4E86\u6CA1\u6709\u51FA\u8DEF\u3002\u4F60\u8BA4\u4E3A\u54EA\u4E00\u79CD\u5199\u6CD5\u66F4\u6709\u529B\u91CF\uFF1F"
    ]
  },
  {
    id: "ext-cmp-jiangjie-baoer",
    moduleId: "literature",
    entryId: "l-hongyan",
    grade: "8a",
    kind: "\u5BF9\u6BD4\u9605\u8BFB",
    title: "\u6C5F\u59D0\u4E0E\u4FDD\u5C14\uFF1A\u9177\u5211\u4E0E\u75BE\u75C5\uFF0C\u4E24\u79CD\u53D7\u96BE",
    summary: "\u6C5F\u59D0\u9762\u5BF9\u7AF9\u7B7E\u9489\u6307\u7684\u9177\u5211\uFF0C\u4FDD\u5C14\u9762\u5BF9\u5931\u660E\u762B\u75EA\u7684\u6F2B\u957F\u6298\u78E8\uFF1B\u4E00\u4E2A\u4E0D\u5C48\u800C\u6B7B\uFF0C\u4E00\u4E2A\u4E0D\u606F\u800C\u751F\u3002",
    content: [
      "## \u4E24\u79CD\u82E6\u96BE\u7684\u6027\u8D28\u5B8C\u5168\u4E0D\u540C",
      "\u6C5F\u59D0\u627F\u53D7\u7684\u662F\u5916\u529B\u5F3A\u52A0\u7684\u3001\u77ED\u4FC3\u800C\u5267\u70C8\u7684\u9177\u5211\u3002\u654C\u4EBA\u628A\u7AF9\u7B7E\u9489\u8FDB\u5979\u7684\u6307\u5C16\u903C\u4F9B\uFF0C\u8FD9\u662F\u5BA1\u8BAF\u7684\u4E00\u90E8\u5206\uFF0C\u76EE\u7684\u662F\u6467\u6BC1\u5979\u7684\u610F\u5FD7\u3001\u903C\u5979\u5F00\u53E3\u3001\u7F9E\u8FB1\u5979\u7684\u4EBA\u683C\u3002\u4FDD\u5C14\u627F\u53D7\u7684\u662F\u4ECE\u8EAB\u4F53\u5185\u90E8\u6765\u7684\u3001\u7F13\u6162\u800C\u6F2B\u957F\u7684\u75C5\u6B8B\uFF1A\u4ED6\u5148\u5728\u6218\u573A\u4E0A\u8D1F\u91CD\u4F24\uFF0C\u53F3\u773C\u5931\u660E\uFF0C\u53C8\u5728\u62A2\u4FEE\u94C1\u8DEF\u65F6\u67D3\u4E0A\u4F24\u5BD2\u4E0E\u98CE\u6E7F\uFF0C1927 \u5E74\u5168\u8EAB\u762B\u75EA\uFF0C1928 \u5E74\u53CC\u76EE\u5931\u660E\u3002\u4E00\u79CD\u662F\u300C\u88AB\u65BD\u52A0\u7684\u75DB\u300D\uFF0C\u4E00\u79CD\u662F\u300C\u88AB\u5265\u593A\u7684\u75DB\u300D\uFF1B\u4E00\u79CD\u8981\u5728\u4E00\u77AC\u95F4\u4F5C\u7B54\uFF0C\u4E00\u79CD\u8981\u7528\u4F59\u4E0B\u7684\u5168\u90E8\u65E5\u5B50\u4F5C\u7B54\u3002",
      "## \u6C5F\u59D0\u7684\u300C\u521A\u300D\u662F\u77AC\u95F4\u7684\u9009\u62E9",
      "\u6C5F\u59D0\u5230\u534E\u84E5\u5C71\u9014\u4E2D\uFF0C\u5728\u57CE\u95E8\u53E3\u770B\u5230\u4E08\u592B\u5F6D\u677E\u6D9B\u7684\u5934\u9885\u88AB\u654C\u4EBA\u60AC\u6302\u793A\u4F17\uFF0C\u5979\u5F3A\u5FCD\u60B2\u75DB\u7EE7\u7EED\u6267\u884C\u4EFB\u52A1\uFF1B\u88AB\u6355\u5165\u72F1\u540E\u53D7\u5211\u660F\u6B7B\u6570\u6B21\u4ECD\u4E0D\u5410\u4E00\u5B57\uFF0C\u8BF4\u51FA\u300C\u7AF9\u7B7E\u5B50\u662F\u7AF9\u5B50\u505A\u7684\uFF0C\u5171\u4EA7\u515A\u5458\u7684\u610F\u5FD7\u662F\u94A2\u94C1\u505A\u7684\u300D\u3002\u5C0F\u8BF4\u4E2D\u7684\u6C5F\u96EA\u7434\uFF08\u6C5F\u59D0\uFF09\u6709\u771F\u5B9E\u7684\u539F\u578B\u2014\u2014\u6C5F\u7AF9\u7B60\uFF081920 \u2014 1949\uFF09\u3002\u5979 1939 \u5E74\u52A0\u5165\u4E2D\u56FD\u5171\u4EA7\u515A\uFF0C1948 \u5E74 6 \u6708\u5728\u4E07\u53BF\u88AB\u6355\uFF0C\u5173\u62BC\u5728\u6E23\u6ED3\u6D1E\uFF0C1949 \u5E74 11 \u6708 14 \u65E5\u88AB\u6740\u5BB3\u4E8E\u6B4C\u4E50\u5C71\u7535\u53F0\u5C9A\u57AD\uFF0C\u5E74\u4EC5\u4E8C\u5341\u4E5D\u5C81\u3002\u5728\u9177\u5211\u9762\u524D\uFF0C\u610F\u5FD7\u5FC5\u987B\u5728\u4E00\u79D2\u4E4B\u5185\u4F5C\u51FA\u51B3\u5B9A\u3002",
      "## \u4FDD\u5C14\u7684\u300C\u521A\u300D\u662F\u6F2B\u957F\u7684\u575A\u6301",
      "\u4FDD\u5C14\u66FE\u5728\u6D77\u8FB9\u63E1\u7740\u624B\u67AA\uFF0C\u8BA4\u771F\u5730\u60F3\u8FC7\u7ED3\u675F\u81EA\u5DF1\u7684\u751F\u547D\uFF1B\u4ED6\u6700\u7EC8\u9009\u62E9\u6D3B\u4E0B\u53BB\uFF0C\u7528\u5199\u4F5C\u91CD\u65B0\u56DE\u5230\u6218\u6597\u7684\u884C\u5217\u3002\u5931\u660E\u4EE5\u540E\uFF0C\u4ED6\u9760\u59BB\u5B50\u8D56\u838E\u548C\u53CB\u4EBA\u8BB0\u5F55\uFF0C\u5199\u6210\u4E86\u5C0F\u8BF4\u3002\u4F5C\u8005\u5965\u65AF\u7279\u6D1B\u592B\u65AF\u57FA\u81EA\u5DF1\u4E5F\u662F\u8FD9\u6837\u5199\u4F5C\u7684\uFF1A\u7528\u523B\u4E86\u9542\u7A7A\u5B57\u6BCD\u7684\u786C\u7EB8\u677F\uFF0C\u4E00\u4E2A\u5B57\u6BCD\u4E00\u4E2A\u5B57\u6BCD\u5730\u6478\u7D22\uFF0C\u540E\u6765\u53EA\u80FD\u53E3\u8FF0\u3002\u75BE\u75C5\u4E0D\u7ED9\u4ED6\u82F1\u96C4\u5F0F\u7684\u77AC\u95F4\uFF0C\u53EA\u7ED9\u4ED6\u65E5\u590D\u4E00\u65E5\u7684\u6D88\u8017\u2014\u2014\u800C\u4ED6\u7684\u610F\u5FD7\uFF0C\u5C31\u5728\u8FD9\u79CD\u6D88\u8017\u4E2D\u88AB\u8BC1\u660E\u3002",
      "## \u5171\u540C\u70B9\uFF1A\u628A\u4E2A\u4EBA\u7684\u75DB\u53D8\u6210\u4FE1\u4EF0\u7684\u8BC1\u636E",
      "\u4E24\u4E2A\u4EBA\u7684\u53D7\u96BE\u90FD\u4E0D\u662F\u4E3A\u4E86\u4E2A\u4EBA\u7684\u4E8B\u3002\u6C5F\u59D0\u5B88\u4F4F\u7684\u662F\u5730\u4E0B\u515A\u7EC4\u7EC7\u4E0E\u6218\u53CB\u7684\u5B89\u5168\uFF0C\u4FDD\u5C14\u5B88\u4F4F\u7684\u662F\u4ED6\u76F8\u4FE1\u7684\u3001\u5173\u4E8E\u4EBA\u7C7B\u89E3\u653E\u7684\u4E8B\u4E1A\u3002\u6B63\u56E0\u5982\u6B64\uFF0C\u4ED6\u4EEC\u7684\u5FCD\u8010\u624D\u4E0D\u88AB\u8BFB\u4F5C\u5355\u7EAF\u7684\u53D7\u82E6\uFF0C\u800C\u88AB\u8BFB\u4F5C\u4E00\u79CD\u8BC1\u660E\uFF1A\u8BC1\u660E\u4FE1\u4EF0\u6BD4\u8089\u4F53\u66F4\u5F3A\u3002\u8FD9\u4E5F\u6B63\u662F\u300A\u7EA2\u5CA9\u300B\u4E0E\u300A\u94A2\u94C1\u662F\u600E\u6837\u70BC\u6210\u7684\u300B\u90FD\u88AB\u79F0\u4E3A\u7EA2\u8272\u7ECF\u5178\u7684\u539F\u56E0\u2014\u2014\u5B83\u4EEC\u5199\u7684\u4E0D\u662F\u4E2A\u4EBA\u7684\u82E6\u96BE\u53F2\uFF0C\u800C\u662F\u4FE1\u5FF5\u5728\u82E6\u96BE\u4E2D\u7684\u6837\u5B50\u3002",
      "## \u4EBA\u7269\u8D28\u611F\u7684\u5DEE\u5F02\uFF1A\u4E00\u4E2A\u521A\u70C8\uFF0C\u4E00\u4E2A\u6C89\u539A",
      "\u6C5F\u59D0\u7684\u5F62\u8C61\u6E05\u6F88\u800C\u6709\u950B\u5203\uFF1A\u5979\u59CB\u7EC8\u6C89\u7740\u3001\u7AEF\u5E84\uFF0C\u8FDE\u75BC\u75DB\u4E5F\u4E0D\u80AF\u5728\u4EBA\u524D\u793A\u5F31\u3002\u4FDD\u5C14\u7684\u5F62\u8C61\u7C97\u7C9D\u800C\u6709\u88C2\u75D5\uFF1A\u4ED6\u4F1A\u6124\u6012\u3001\u4F1A\u52A8\u6447\u3001\u4F1A\u9A82\u4EBA\uFF0C\u4E5F\u4F1A\u5728\u7231\u60C5\u4E0E\u7406\u60F3\u4E4B\u95F4\u72AF\u9519\u3002\u56E0\u6B64\u6C5F\u59D0\u8BA9\u4EBA\u656C\uFF0C\u4FDD\u5C14\u8BA9\u4EBA\u4EB2\u3002\u4E24\u79CD\u5199\u6CD5\u5BF9\u5E94\u4E24\u79CD\u6750\u6599\uFF1A\u300A\u7EA2\u5CA9\u300B\u53D6\u6750\u4E8E\u771F\u5B9E\u7684\u70C8\u58EB\u4E8B\u8FF9\uFF0C\u843D\u7B14\u8981\u6709\u5206\u5BF8\uFF0C\u5199\u7684\u662F\u6C14\u8282\uFF1B\u300A\u94A2\u94C1\u662F\u600E\u6837\u70BC\u6210\u7684\u300B\u5E26\u6709\u81EA\u4F20\u8272\u5F69\uFF0C\u53EF\u4EE5\u653E\u5F00\u5199\u4E00\u4E2A\u4EBA\u7684\u6323\u624E\u4E0E\u6210\u957F\u3002",
      "## \u8003\u573A\u4E0A\u600E\u6837\u7528\u8FD9\u7EC4\u6750\u6599",
      "\u4E2D\u8003\u7684\u6BD4\u8F83\u9898\u5E38\u8981\u6C42\u300C\u7ED3\u5408\u4EBA\u7269\u5728\u5173\u952E\u5904\u7684\u9009\u62E9\uFF0C\u8C08\u8C08\u4F60\u611F\u53D7\u5230\u7684\u610F\u5FD7\u54C1\u8D28\u300D\u3002\u7B54\u9898\u65F6\u4E0D\u8981\u53EA\u5199\u300C\u4ED6\u4EEC\u90FD\u5F88\u575A\u5F3A\u300D\uFF0C\u8981\u5199\u6E05\u4E0D\u540C\uFF1A\u53D7\u96BE\u7684\u65B9\u5F0F\u4E0D\u540C\uFF08\u9177\u5211\u4E0E\u75BE\u75C5\uFF09\uFF0C\u8003\u9A8C\u7684\u65F6\u95F4\u5F62\u6001\u4E0D\u540C\uFF08\u77AC\u95F4\u7684\u6289\u62E9\u4E0E\u957F\u4E45\u7684\u575A\u6301\uFF09\uFF0C\u8868\u73B0\u51FA\u7684\u54C1\u8D28\u4FA7\u91CD\u4E0D\u540C\uFF08\u5B81\u6B7B\u4E0D\u5C48\u4E0E\u575A\u97E7\u4E0D\u606F\uFF09\uFF1B\u540C\u65F6\u8981\u70B9\u660E\u5171\u540C\u70B9\u2014\u2014\u90FD\u628A\u4E2A\u4EBA\u7684\u751F\u6B7B\u82E6\u4E50\u653E\u5728\u4E86\u4FE1\u4EF0\u4E4B\u540E\u3002\u6709\u540C\u6709\u5F02\uFF0C\u6761\u7406\u6E05\u695A\uFF0C\u624D\u662F\u8FD9\u9053\u9898\u7684\u5F97\u5206\u70B9\u3002"
    ],
    think: [
      "\u300C\u77AC\u95F4\u7684\u9009\u62E9\u300D\u4E0E\u300C\u957F\u4E45\u7684\u575A\u6301\u300D\uFF0C\u54EA\u4E00\u79CD\u66F4\u8003\u9A8C\u610F\u5FD7\uFF1F\u8BF7\u8BF4\u8BF4\u4F60\u7684\u7406\u7531\u3002",
      "\u4FDD\u5C14\u66FE\u60F3\u8FC7\u81EA\u6740\uFF0C\u4F5C\u8005\u4E3A\u4EC0\u4E48\u8981\u628A\u8FD9\u4E2A\u5FF5\u5934\u5199\u51FA\u6765\uFF1F\u8FD9\u4E0E\u5851\u9020\u4E00\u4E2A\u6BEB\u65E0\u52A8\u6447\u7684\u82F1\u96C4\u76F8\u6BD4\uFF0C\u6548\u679C\u6709\u4F55\u4E0D\u540C\uFF1F",
      "\u5982\u679C\u6C5F\u59D0\u6CA1\u6709\u727A\u7272\uFF0C\u800C\u662F\u50CF\u4FDD\u5C14\u4E00\u6837\u6D3B\u4E86\u4E0B\u6765\uFF0C\u4F60\u8BA4\u4E3A\u5979\u4F1A\u600E\u6837\u5EA6\u8FC7\u4F59\u751F\uFF1F"
    ]
  },
  {
    id: "ext-cmp-wukong-luzhishen",
    moduleId: "literature",
    entryId: "l-xiyouji",
    grade: "7a",
    kind: "\u5BF9\u6BD4\u9605\u8BFB",
    title: "\u5B59\u609F\u7A7A\u4E0E\u9C81\u667A\u6DF1\uFF1A\u4E24\u6B21\u300C\u95F9\u300D\u7684\u6BD4\u8F83",
    summary: "\u5B59\u609F\u7A7A\u5927\u95F9\u5929\u5BAB\u662F\u4E3A\u540D\u5206\uFF0C\u9C81\u667A\u6DF1\u5927\u95F9\u4E94\u53F0\u5C71\u3001\u91CE\u732A\u6797\u662F\u4E3A\u4E49\u6124\uFF1B\u4E00\u4E2A\u5F52\u987A\u79E9\u5E8F\uFF0C\u4E00\u4E2A\u6563\u6F2B\u8D85\u8131\u3002",
    content: [
      "## \u7B2C\u4E00\u6B21\u300C\u95F9\u300D\uFF1A\u4E3A\u4E86\u88AB\u627F\u8BA4",
      "\u5B59\u609F\u7A7A\u95F9\u8D77\u6765\u7684\u8D77\u56E0\u662F\u540D\u5206\u3002\u4ED6\u5148\u88AB\u7389\u5E1D\u5C01\u4E3A\u300C\u5F3C\u9A6C\u6E29\u300D\uFF0C\u5F97\u77E5\u8FD9\u662F\u4E2A\u300C\u672A\u5165\u6D41\u300D\u7684\u5C0F\u5B98\uFF0C\u4E00\u6012\u53CD\u4E0B\u5929\u5BAB\uFF1B\u540E\u6765\u8BA8\u5F97\u300C\u9F50\u5929\u5927\u5723\u300D\u7684\u540D\u53F7\uFF0C\u5374\u53EA\u662F\u4E2A\u7A7A\u8854\uFF0C\u88AB\u6D3E\u53BB\u770B\u7BA1\u87E0\u6843\u56ED\uFF1B\u738B\u6BCD\u7684\u87E0\u6843\u4F1A\u6CA1\u6709\u8BF7\u4ED6\uFF0C\u4ED6\u4FBF\u6405\u4E71\u87E0\u6843\u4F1A\u3001\u5077\u559D\u5FA1\u9152\u3001\u5077\u5403\u592A\u4E0A\u8001\u541B\u7684\u91D1\u4E39\uFF0C\u53CD\u51FA\u5929\u5BAB\u3002\u8FD9\u4E00\u95F9\u7684\u52A8\u56E0\u662F\u300C\u6211\u51ED\u4EC0\u4E48\u4E0D\u88AB\u627F\u8BA4\u300D\u2014\u2014\u662F\u5411\u9AD8\u9AD8\u5728\u4E0A\u7684\u7B49\u7EA7\u79E9\u5E8F\u8981\u4E00\u4E2A\u4F4D\u7F6E\uFF0C\u8981\u7684\u662F\u5C0A\u4E25\u4E0E\u540D\u5206\u3002",
      "## \u7B2C\u4E8C\u6B21\u300C\u95F9\u300D\uFF1A\u4E3A\u4E86\u522B\u4EBA",
      "\u9C81\u667A\u6DF1\u7684\u300C\u95F9\u300D\u51E0\u4E4E\u90FD\u4E0D\u662F\u4E3A\u81EA\u5DF1\u3002\u4ED6\u5728\u6F58\u5BB6\u9152\u697C\u542C\u91D1\u7FE0\u83B2\u8BC9\u8BF4\u88AB\u90D1\u5C60\u5F3A\u5360\u53C8\u8FFD\u8BA8\u5178\u8EAB\u94B1\u7684\u51A4\u60C5\uFF0C\u4E09\u62F3\u6253\u6B7B\u9547\u5173\u897F\uFF1B\u5728\u6843\u82B1\u6751\u5047\u626E\u65B0\u5A18\uFF0C\u75DB\u6253\u5F3A\u5A36\u6C11\u5973\u7684\u5C0F\u9738\u738B\u5468\u901A\uFF1B\u5728\u91CE\u732A\u6797\u6551\u4E0B\u88AB\u8463\u8D85\u3001\u859B\u9738\u6697\u5BB3\u7684\u6797\u51B2\u3002\u81F3\u4E8E\u4ED6\u5728\u4E94\u53F0\u5C71\u6587\u6B8A\u9662\u51FA\u5BB6\u540E\u559D\u9152\u5403\u8089\u3001\u6253\u574F\u5C71\u95E8\u91D1\u521A\uFF0C\u88AB\u667A\u771F\u957F\u8001\u9063\u5F80\u4E1C\u4EAC\u5927\u76F8\u56FD\u5BFA\uFF0C\u90A3\u662F\u7387\u6027\u800C\u4E3A\uFF0C\u4E0D\u662F\u79C1\u6124\u3002\u4ED6\u7684\u6BCF\u4E00\u6B21\u52A8\u624B\uFF0C\u90FD\u4E3A\u7684\u662F\u4E00\u4E2A\u4E0E\u4ED6\u65E0\u5173\u7684\u4EBA\u3002",
      "## \u95F9\u7684\u5BF9\u8C61\u4E0D\u540C",
      "\u5B59\u609F\u7A7A\u95F9\u7684\u662F\u79E9\u5E8F\u672C\u8EAB\uFF1A\u7389\u5E1D\u3001\u738B\u6BCD\u3001\u5929\u5175\u5929\u5C06\uFF0C\u662F\u6743\u529B\u4E0E\u7B49\u7EA7\u7684\u8C61\u5F81\u3002\u9C81\u667A\u6DF1\u95F9\u7684\u662F\u79E9\u5E8F\u91CC\u7684\u4E0D\u4E49\uFF1A\u4ED7\u52BF\u6B3A\u4EBA\u7684\u5C60\u6237\u3001\u5F3A\u62A2\u6C11\u5973\u7684\u5F3A\u76D7\u3001\u53D7\u8D3F\u5BB3\u4EBA\u7684\u516C\u5DEE\u3002\u4E00\u4E2A\u6311\u6218\u7684\u662F\u300C\u8C01\u5728\u4E0A\u300D\uFF0C\u4E00\u4E2A\u6536\u62FE\u7684\u662F\u300C\u8C01\u5728\u6B3A\u8D1F\u4EBA\u300D\u3002\u6240\u4EE5\u5B59\u609F\u7A7A\u7684\u53CD\u6297\u5E26\u6709\u653F\u6CBB\u6027\u7684\u950B\u8292\uFF0C\u9C81\u667A\u6DF1\u7684\u53CD\u6297\u5E26\u6709\u6C11\u95F4\u4FA0\u4E49\u7684\u6E29\u5EA6\uFF1B\u4E00\u4E2A\u662F\u53DB\u9006\u8005\u7684\u53CD\u6297\uFF0C\u4E00\u4E2A\u662F\u4FA0\u5BA2\u7684\u53CD\u6297\u3002",
      "## \u7ED3\u679C\u4E0D\u540C\uFF1A\u5F52\u987A\u4E0E\u89E3\u8131",
      "\u5B59\u609F\u7A7A\u88AB\u538B\u5728\u4E94\u884C\u5C71\u4E0B\u4E94\u767E\u5E74\uFF0C\u540E\u6765\u7688\u4F9D\u4F5B\u95E8\u3001\u4FDD\u5510\u50E7\u897F\u884C\uFF0C\u5386\u7ECF\u516B\u5341\u4E00\u96BE\uFF0C\u6700\u7EC8\u53D7\u5C01\u300C\u6597\u6218\u80DC\u4F5B\u300D\uFF0C\u4ECE\u300C\u53CD\u79E9\u5E8F\u8005\u300D\u53D8\u6210\u4E86\u300C\u79E9\u5E8F\u4E2D\u7684\u795E\u300D\u3002\u9C81\u667A\u6DF1\u968F\u5B8B\u6C5F\u5F81\u65B9\u814A\u4E4B\u540E\u4E0D\u80AF\u8FD8\u671D\u53D7\u5C01\uFF0C\u7559\u5728\u676D\u5DDE\u516D\u548C\u5BFA\uFF0C\u591C\u91CC\u542C\u89C1\u94B1\u5858\u6C5F\u6F6E\u58F0\u800C\u609F\uFF0C\u7559\u4E0B\u300C\u5E73\u751F\u4E0D\u4FEE\u5584\u679C\uFF0C\u53EA\u7231\u6740\u4EBA\u653E\u706B\u3002\u5FFD\u5730\u987F\u5F00\u91D1\u7EF3\uFF0C\u8FD9\u91CC\u626F\u65AD\u7389\u9501\u3002\u54A6\uFF01\u94B1\u5858\u6C5F\u4E0A\u6F6E\u4FE1\u6765\uFF0C\u4ECA\u65E5\u65B9\u77E5\u6211\u662F\u6211\u300D\uFF0C\u5750\u5316\u5706\u5BC2\u3002\u4E00\u4E2A\u88AB\u5236\u5EA6\u6536\u7F16\uFF0C\u4E00\u4E2A\u4ECE\u5236\u5EA6\u4E2D\u9000\u51FA\u3002",
      "## \u5171\u540C\u70B9\uFF1A\u90FD\u6709\u4E00\u9897\u4E0D\u53D7\u62D8\u675F\u7684\u5FC3",
      "\u4E24\u4EBA\u90FD\u4E0D\u5B88\u793C\u6CD5\uFF1A\u5B59\u609F\u7A7A\u4E0D\u53D7\u5929\u6761\u7684\u7EA6\u675F\uFF0C\u9C81\u667A\u6DF1\u4E0D\u5B88\u4F5B\u95E8\u7684\u6E05\u89C4\uFF1B\u4E24\u4EBA\u90FD\u76F4\u7387\u3001\u5929\u771F\u3001\u8BB2\u4E49\u6C14\uFF0C\u90FD\u5E26\u7740\u4E00\u70B9\u5B69\u5B50\u6C14\u2014\u2014\u5B59\u609F\u7A7A\u597D\u80DC\u7231\u663E\u6446\uFF0C\u9C81\u667A\u6DF1\u7C97\u9C81\u5374\u5FC3\u7EC6\uFF08\u6551\u91D1\u6C0F\u7236\u5973\u4E4B\u524D\u5148\u9001\u94F6\u5B50\uFF0C\u53C8\u6015\u5E97\u5C0F\u4E8C\u53BB\u8FFD\u8D76\uFF0C\u7D22\u6027\u5750\u7740\u4E0D\u8D70\uFF09\u3002\u4ED6\u4EEC\u8EAB\u4E0A\u6700\u52A8\u4EBA\u7684\u5730\u65B9\uFF0C\u662F\u5FC3\u91CC\u6CA1\u6709\u7B97\u8BA1\u3002\u8FD9\u4EFD\u53EF\u7231\u7684\u6765\u5904\u662F\u76F8\u540C\u7684\uFF1A\u4ED6\u4EEC\u90FD\u6CA1\u6709\u88AB\u89C4\u77E9\u6253\u78E8\u5149\u6ED1\u3002",
      "## \u6BD4\u8F83\u9898\u7684\u7B54\u9898\u601D\u8DEF",
      "\u8DE8\u4E66\u6BD4\u8F83\u7684\u5173\u952E\u662F\u627E\u5230\u300C\u53EF\u6BD4\u70B9\u300D\u3002\u8FD9\u4E00\u7EC4\u7684\u53EF\u6BD4\u70B9\u6709\u56DB\u4E2A\uFF1A\u8D77\u56E0\uFF08\u4E3A\u79C1\u6124\u6C42\u540D\u5206\uFF0C\u8FD8\u662F\u4E3A\u516C\u4E49\u52A9\u4ED6\u4EBA\uFF09\u3001\u5BF9\u8C61\uFF08\u7B49\u7EA7\u79E9\u5E8F\u4E0E\u6743\u5A01\uFF0C\u8FD8\u662F\u4E0D\u4E49\u4E0E\u6076\u4EBA\uFF09\u3001\u7ED3\u679C\uFF08\u5F52\u987A\u6210\u4F5B\uFF0C\u8FD8\u662F\u542C\u6F6E\u5750\u5316\uFF09\u3001\u7CBE\u795E\u6C14\u8D28\uFF08\u53DB\u9006\u7684\u8FDB\u53D6\uFF0C\u8FD8\u662F\u6563\u6F2B\u7684\u8D85\u8131\uFF09\u3002\u6709\u4E86\u8FD9\u56DB\u4E2A\u7EF4\u5EA6\uFF0C\u7B54\u9898\u5C31\u80FD\u4ECE\u300C\u4ED6\u4EEC\u90FD\u5F88\u52C7\u6562\u300D\u5347\u7EA7\u4E3A\u6709\u6761\u7406\u7684\u5206\u6790\u3002\u6700\u540E\u53EF\u4EE5\u8865\u4E00\u53E5\u603B\u7ED3\uFF1A\u4E24\u6B21\u300C\u95F9\u300D\u80CC\u540E\uFF0C\u662F\u4E24\u79CD\u5173\u4E8E\u53CD\u6297\u7684\u60F3\u8C61\u2014\u2014\u4E00\u79CD\u6700\u7EC8\u56DE\u5230\u79E9\u5E8F\u91CC\uFF0C\u4E00\u79CD\u59CB\u7EC8\u5728\u79E9\u5E8F\u4E4B\u5916\u3002"
    ],
    think: [
      "\u5B59\u609F\u7A7A\u6700\u7EC8\u6210\u4E86\u300C\u6597\u6218\u80DC\u4F5B\u300D\uFF0C\u6709\u4EBA\u8BA4\u4E3A\u8FD9\u662F\u6210\u957F\uFF0C\u6709\u4EBA\u8BA4\u4E3A\u8FD9\u662F\u88AB\u6536\u7F16\u3002\u4F60\u600E\u4E48\u770B\uFF1F",
      "\u9C81\u667A\u6DF1\u7684\u300C\u95F9\u300D\u51E0\u4E4E\u90FD\u662F\u4E3A\u522B\u4EBA\uFF0C\u4E3A\u4EC0\u4E48\u4ED6\u6700\u540E\u53CD\u800C\u9009\u62E9\u4E86\u9000\u51FA\uFF1F\u8FD9\u4E0E\u4ED6\u7684\u6027\u683C\u6709\u4EC0\u4E48\u5173\u7CFB\uFF1F",
      "\u5982\u679C\u8BA9\u9C81\u667A\u6DF1\u53BB\u5927\u95F9\u5929\u5BAB\u3001\u8BA9\u5B59\u609F\u7A7A\u53BB\u6551\u6797\u51B2\uFF0C\u4E24\u4E2A\u6545\u4E8B\u4F1A\u6709\u4EC0\u4E48\u4E0D\u540C\uFF1F"
    ]
  },
  {
    id: "ext-cmp-jianai-xiangzi",
    moduleId: "literature",
    entryId: "l-jianai",
    grade: "9a",
    kind: "\u5BF9\u6BD4\u9605\u8BFB",
    title: "\u7B80\xB7\u7231\u4E0E\u7965\u5B50\uFF1A\u9762\u5BF9\u547D\u8FD0\u7684\u4E0D\u540C\u9009\u62E9",
    summary: "\u540C\u4E3A\u5E95\u5C42\u53D7\u96BE\u8005\uFF0C\u7B80\xB7\u7231\u9760\u5C0A\u4E25\u4E0E\u4FE1\u4EF0\u4E3B\u52A8\u9009\u62E9\uFF0C\u7965\u5B50\u53EA\u6709\u4E00\u4E2A\u4E70\u8F66\u7684\u68A6\u3002",
    content: [
      "## \u76F8\u4F3C\u7684\u8D77\u70B9\uFF1A\u538B\u5728\u6700\u4E0B\u9762\u7684\u5E74\u8F7B\u4EBA",
      "\u7B80\xB7\u7231\u662F\u5B64\u513F\uFF0C\u5BC4\u517B\u5728\u8205\u5988\u91CC\u5FB7\u592A\u592A\u5BB6\uFF0C\u88AB\u8868\u54E5\u7EA6\u7FF0\u6BB4\u6253\u8FB1\u9A82\uFF0C\u88AB\u5173\u8FDB\u300C\u7EA2\u623F\u5B50\u300D\uFF0C\u8FDE\u4EC6\u4EBA\u90FD\u53EF\u4EE5\u8F7B\u89C6\u5979\u3002\u7965\u5B50\u4E5F\u51E0\u4E4E\u662F\u4E2A\u5B64\u513F\uFF0C\u7236\u6BCD\u53CC\u4EA1\uFF0C\u4ECE\u4E61\u4E0B\u6765\u5230\u5317\u5E73\uFF0C\u4E00\u65E0\u6240\u6709\uFF0C\u9760\u4E00\u8EAB\u529B\u6C14\u62C9\u8F66\u8FC7\u6D3B\u3002\u4E24\u4E2A\u4EBA\u90FD\u6CA1\u6709\u5BB6\u4E16\u3001\u6CA1\u6709\u9760\u5C71\uFF0C\u90FD\u5FC5\u987B\u72EC\u81EA\u5728\u522B\u4EBA\u7684\u4E16\u754C\u91CC\u6323\u4E00\u4E2A\u4F4D\u7F6E\u3002\u4F5C\u4E3A\u6587\u5B66\u4EBA\u7269\uFF0C\u4ED6\u4EEC\u7684\u8D77\u70B9\u540C\u6837\u4F4E\uFF0C\u540C\u6837\u88AB\u4EBA\u770B\u4F5C\u300C\u4E0D\u7B97\u4EC0\u4E48\u300D\u7684\u4EBA\u3002",
      "## \u7B80\xB7\u7231\u7684\u9009\u62E9\uFF1A\u4E00\u6B21\u6B21\u4E3B\u52A8\u7684\u300C\u4E0D\u300D",
      "\u5979\u6562\u5BF9\u8868\u54E5\u8FD8\u624B\uFF0C\u6562\u5BF9\u8205\u5988\u8BF4\u300C\u4F60\u574F\uFF0C\u4F60\u5FC3\u80A0\u72E0\u6BD2\u300D\uFF1B\u5728\u6D1B\u4F0D\u5FB7\u5B66\u6821\uFF0C\u5979\u5B66\u4F1A\u4E86\u5FCD\u8010\u4E0E\u5BBD\u6055\uFF08\u6D77\u4F26\xB7\u5F6D\u65AF\u7ED9\u4E86\u5979\u8FD9\u79CD\u5F71\u54CD\uFF09\uFF0C\u4F46\u6CA1\u6709\u4E22\u6389\u8BF4\u300C\u4E0D\u300D\u7684\u80FD\u529B\uFF1B\u5728\u6851\u83F2\u5C14\u5FB7\uFF0C\u5979\u7231\u4E0A\u7F57\u5207\u65AF\u7279\uFF0C\u5374\u5728\u5F97\u77E5\u4ED6\u5DF2\u6709\u75AF\u59BB\u4E4B\u540E\u62D2\u7EDD\u505A\u4ED6\u7684\u60C5\u5987\uFF0C\u5B81\u53EF\u5728\u6DF1\u591C\u51FA\u8D70\uFF1B\u9762\u5BF9\u5723\u7EA6\u7FF0\u65E0\u7231\u7684\u6C42\u5A5A\uFF0C\u5979\u518D\u6B21\u8BF4\u300C\u4E0D\u300D\uFF1B\u6700\u540E\u5979\u5E26\u7740\u7EE7\u627F\u7684\u9057\u4EA7\u56DE\u5230\u5931\u660E\u6B8B\u75BE\u7684\u7F57\u5207\u65AF\u7279\u8EAB\u8FB9\u3002\u4EBA\u751F\u7684\u6BCF\u4E00\u4E2A\u5173\u53E3\uFF0C\u5979\u90FD\u662F\u81EA\u5DF1\u4F5C\u51B3\u5B9A\u7684\u3002",
      "## \u7965\u5B50\u7684\u9009\u62E9\uFF1A\u4E00\u4E2A\u76EE\u6807\u4E0E\u4E09\u6B21\u7834\u706D",
      "\u7965\u5B50\u7684\u76EE\u6807\u53EA\u6709\u4E00\u4E2A\uFF1A\u4E70\u4E00\u8F86\u81EA\u5DF1\u7684\u8F66\u3002\u4ED6\u7701\u5403\u4FED\u7528\uFF0C\u300C\u4E00\u5929\u4E0D\u62C9\u8F66\u5C31\u4E00\u5929\u4E0D\u5403\u996D\u300D\uFF0C\u4F46\u4ED6\u7684\u751F\u6D3B\u91CC\u51E0\u4E4E\u6CA1\u6709\u4E00\u6B21\u4E3B\u52A8\u7684\u9009\u62E9\u3002\u864E\u599E\u8BBE\u5C40\uFF0C\u4ED6\u88AB\u52A8\u5730\u8FDB\u5165\u4E86\u5A5A\u59FB\uFF1B\u5B59\u4FA6\u63A2\u6572\u8BC8\uFF0C\u4ED6\u53EA\u80FD\u628A\u94B1\u4EA4\u51FA\u53BB\uFF1B\u8F66\u5382\u4E3B\u5218\u56DB\u7237\u7FFB\u8138\uFF0C\u4ED6\u53EA\u80FD\u4F4E\u5934\u3002\u4ED6\u7684\u300C\u9009\u62E9\u300D\u5176\u5B9E\u662F\u88AB\u9009\u62E9\uFF1A\u5927\u5175\u3001\u4FA6\u63A2\u3001\u8F66\u5382\u4E3B\u3001\u7578\u5F62\u7684\u5A5A\u59FB\uFF0C\u4E00\u6B21\u6B21\u66FF\u4ED6\u4F5C\u4E86\u51B3\u5B9A\u3002\u5230\u6700\u540E\uFF0C\u8FDE\u5815\u843D\u4E5F\u4E0D\u662F\u4ED6\u9009\u7684\uFF0C\u662F\u88AB\u63A8\u7740\u8D70\u5230\u7684\u3002",
      "## \u5DEE\u522B\u7684\u6839\u6E90\uFF1A\u7CBE\u795E\u8D44\u6E90\u4E0D\u540C",
      "\u7B80\xB7\u7231\u6709\u4FE1\u4EF0\uFF0C\u5979\u5411\u4E0A\u5E1D\u7948\u7977\uFF0C\u4E5F\u5411\u7F57\u5207\u65AF\u7279\u8981\u6C42\u7075\u9B42\u7684\u5E73\u7B49\uFF1B\u5979\u6709\u6587\u5316\uFF0C\u5728\u6D1B\u4F0D\u5FB7\u53D7\u6559\u3001\u505A\u8FC7\u6559\u5E08\uFF0C\u80FD\u9760\u6559\u4E66\u8C0B\u751F\uFF1B\u5979\u6709\u660E\u786E\u7684\u81EA\u6211\u610F\u8BC6\uFF0C\u90A3\u53E5\u300C\u4F60\u4EE5\u4E3A\uFF0C\u56E0\u4E3A\u6211\u7A77\u3001\u4F4E\u5FAE\u3001\u4E0D\u7F8E\u3001\u77EE\u5C0F\uFF0C\u6211\u5C31\u6CA1\u6709\u7075\u9B42\u6CA1\u6709\u5FC3\u5417\u300D\u5C31\u662F\u5979\u7684\u5BA3\u8A00\u3002\u7965\u5B50\u6CA1\u6709\u4FE1\u4EF0\uFF0C\u6CA1\u6709\u6587\u5316\uFF0C\u6CA1\u6709\u540C\u4F34\uFF0C\u5FC3\u5E95\u53EA\u5269\u300C\u8F66\u300D\u8FD9\u4E00\u4EF6\u4E1C\u897F\u3002\u4EBA\u4E00\u65E6\u53EA\u6709\u4E00\u4E2A\u7269\u8D28\u76EE\u6807\uFF0C\u4E00\u65E6\u5931\u53BB\u5B83\uFF0C\u5C31\u6CA1\u6709\u4EFB\u4F55\u4E1C\u897F\u53EF\u4EE5\u652F\u6491\u81EA\u5DF1\u3002\u7B80\xB7\u7231\u7684\u5BCC\u6709\u662F\u7CBE\u795E\u4E0A\u7684\uFF0C\u7965\u5B50\u7684\u8D2B\u7A77\u4E5F\u662F\u7CBE\u795E\u4E0A\u7684\u3002",
      "## \u793E\u4F1A\u6761\u4EF6\u4E0D\u540C\uFF0C\u4E24\u90E8\u5C0F\u8BF4\u90FD\u4E0D\u53EA\u5728\u5199\u73AF\u5883",
      "\u7EF4\u591A\u5229\u4E9A\u65F6\u4EE3\u7684\u82F1\u56FD\u6709\u68EE\u4E25\u7684\u9636\u7EA7\u58C1\u5792\uFF0C\u4F46\u4E5F\u5B58\u5728\u5973\u6027\u9760\u6559\u4E66\u8C0B\u751F\u3001\u9760\u7EE7\u627F\u9057\u4EA7\u6539\u53D8\u547D\u8FD0\u7684\u7A7A\u95F4\uFF1B\u4E8C\u5341\u4E16\u7EAA\u4E8C\u5341\u5E74\u4EE3\u7684\u5317\u5E73\uFF0C\u7965\u5B50\u9762\u5BF9\u7684\u662F\u4E00\u4E2A\u300C\u4E0D\u8BA9\u597D\u4EBA\u6709\u51FA\u8DEF\u300D\u7684\u793E\u4F1A\uFF0C\u4E2A\u4EBA\u7684\u52AA\u529B\u51E0\u4E4E\u6CE8\u5B9A\u88AB\u78BE\u788E\u3002\u4F46\u4E24\u90E8\u4F5C\u54C1\u7684\u91CD\u5FC3\u5E76\u4E0D\u76F8\u540C\uFF1A\u300A\u7B80\xB7\u7231\u300B\u5F3A\u8C03\u4EBA\u683C\u7684\u529B\u91CF\u4E0E\u9009\u62E9\uFF0C\u8981\u8BA9\u4E00\u4E2A\u4E0D\u7F8E\u3001\u4E0D\u5BCC\u7684\u5973\u6559\u5E08\u8D62\u5F97\u5C0A\u4E25\uFF1B\u300A\u9A86\u9A7C\u7965\u5B50\u300B\u6070\u6070\u8981\u5199\u4E2A\u4EBA\u594B\u6597\u7684\u7834\u4EA7\u3002\u4E00\u4E2A\u8BA9\u4EBA\u76F8\u4FE1\u300C\u6211\u80FD\u51B3\u5B9A\u300D\uFF0C\u4E00\u4E2A\u8BA9\u4EBA\u770B\u6E05\u300C\u6211\u672A\u5FC5\u80FD\u51B3\u5B9A\u300D\u3002",
      "## \u505A\u6BD4\u8F83\u9605\u8BFB\u9898\u65F6\u600E\u6837\u843D\u7B14",
      "\u53EF\u4EE5\u5148\u5217\u4E00\u5F20\u8868\uFF1A\u8D77\u70B9\u3001\u76EE\u6807\u3001\u9762\u5BF9\u5173\u952E\u4E8B\u4EF6\u7684\u9009\u62E9\u3001\u53EF\u7528\u7684\u8D44\u6E90\uFF08\u4FE1\u4EF0\u3001\u6587\u5316\u3001\u540C\u4F34\u3001\u91D1\u94B1\uFF09\u3001\u7ED3\u5C40\u3002\u518D\u5F52\u7EB3\u4E24\u70B9\uFF1A\u7B80\xB7\u7231\u7684\u529B\u91CF\u6765\u81EA\u7CBE\u795E\u4E0A\u7684\u5E73\u7B49\u610F\u8BC6\uFF0C\u7965\u5B50\u7684\u60B2\u5267\u6765\u81EA\u300C\u4E2A\u4EBA\u4E3B\u4E49\u300D\u7684\u5B64\u7ACB\u65E0\u63F4\u3002\u6700\u540E\u843D\u5230\u4E24\u4F4D\u4F5C\u8005\u7684\u610F\u56FE\u2014\u2014\u590F\u6D1B\u8482\u8981\u4E3A\u4E00\u4E2A\u8D2B\u7A77\u800C\u4E0D\u7F8E\u7684\u5973\u6559\u5E08\u4E89\u4E00\u4EFD\u5C0A\u4E25\uFF0C\u8001\u820D\u8981\u4E3A\u4E00\u4E2A\u88AB\u793E\u4F1A\u78BE\u788E\u7684\u8F66\u592B\u7559\u4E0B\u8BC1\u636E\u3002\u540C\u4E00\u7C7B\u4EBA\u7269\uFF0C\u4E24\u79CD\u6587\u5B66\u7684\u56DE\u7B54\uFF0C\u8FD9\u5C31\u662F\u8FD9\u7EC4\u6BD4\u8F83\u7684\u843D\u70B9\u3002"
    ],
    think: [
      "\u5982\u679C\u628A\u7965\u5B50\u7684\u300C\u8F66\u300D\u6362\u6210\u4ECA\u5929\u7684\u300C\u623F\u5B50\u300D\uFF0C\u4ED6\u7684\u6545\u4E8B\u8FD8\u6210\u7ACB\u5417\uFF1F\u8BF7\u8BF4\u660E\u7406\u7531\u3002",
      "\u7965\u5B50\u6CA1\u6709\u6587\u5316\u3001\u6CA1\u6709\u4FE1\u4EF0\u3001\u6CA1\u6709\u540C\u4F34\u3002\u5982\u679C\u4ED6\u8BFB\u4E86\u4E66\u3001\u6709\u4E86\u670B\u53CB\uFF0C\u547D\u8FD0\u4F1A\u6539\u53D8\u5417\uFF1F",
      "\u6709\u4EBA\u8BF4\u662F\u793E\u4F1A\u6BC1\u4E86\u7965\u5B50\uFF0C\u6709\u4EBA\u8BF4\u7965\u5B50\u81EA\u5DF1\u4E5F\u6709\u8D23\u4EFB\u3002\u4F60\u66F4\u540C\u610F\u54EA\u4E00\u79CD\uFF1F\u8BF7\u7528\u5C0F\u8BF4\u4E2D\u7684\u5177\u4F53\u60C5\u8282\u652F\u6301\u4F60\u7684\u770B\u6CD5\u3002"
    ]
  },
  {
    id: "ext-cmp-rulin-xiyou",
    moduleId: "literature",
    entryId: "l-rulinwaishi",
    grade: "9b",
    kind: "\u5BF9\u6BD4\u9605\u8BFB",
    title: "\u300A\u5112\u6797\u5916\u53F2\u300B\u4E0E\u300A\u897F\u6E38\u8BB0\u300B\uFF1A\u8BBD\u523A\u7684\u4E24\u79CD\u7B14\u6CD5",
    summary: "\u4E00\u4E2A\u7528\u5199\u5B9E\u767D\u63CF\u753B\u5112\u6797\u4F17\u751F\uFF0C\u4E00\u4E2A\u7528\u5E7B\u60F3\u8352\u8BDE\u5199\u5929\u5EAD\u5B98\u573A\uFF1B\u540C\u662F\u8BBD\u523A\uFF0C\u4E00\u4E2A\u60B2\u60AF\uFF0C\u4E00\u4E2A\u8BD9\u8C10\u3002",
    content: [
      "## \u8BBD\u523A\u7684\u5BF9\u8C61\u4E0D\u540C",
      "\u300A\u5112\u6797\u5916\u53F2\u300B\u8BBD\u523A\u7684\u662F\u79D1\u4E3E\u5236\u5EA6\u4E0B\u7684\u8BFB\u4E66\u4EBA\uFF1A\u8303\u8FDB\u4E2D\u4E3E\u540E\u53D1\u75AF\uFF0C\u5468\u8FDB\u770B\u89C1\u8D21\u9662\u53F7\u677F\u4E00\u5934\u649E\u53BB\u3001\u54ED\u5F97\u5410\u8840\uFF0C\u4E25\u76D1\u751F\u4E34\u6B7B\u4F38\u7740\u4E24\u6839\u624B\u6307\u4E0D\u80AF\u54BD\u6C14\uFF08\u4E3A\u7684\u662F\u706F\u76CF\u91CC\u70B9\u7740\u4E24\u830E\u706F\u8349\uFF09\uFF0C\u5321\u8D85\u4EBA\u4ECE\u4E00\u4E2A\u5B5D\u987A\u7684\u7A77\u5C0F\u5B50\u53D8\u6210\u5FD8\u6069\u8D1F\u4E49\u7684\u9A97\u5B50\uFF0C\u9A6C\u4E8C\u5148\u751F\u6EE1\u53E3\u4E3E\u4E1A\u6587\u7AE0\uFF0C\u725B\u6D66\u90CE\u5192\u540D\u884C\u9A97\u3002\u8FD9\u4E9B\u90FD\u662F\u300C\u5112\u6797\u300D\u91CC\u7684\u65E5\u5E38\u4EBA\u7269\u3002\u300A\u897F\u6E38\u8BB0\u300B\u8BBD\u523A\u7684\u5219\u662F\u795E\u4F5B\u4E16\u754C\u7684\u79E9\u5E8F\u4E0E\u4EBA\u6027\u5F31\u70B9\uFF1A\u7389\u5E1D\u660F\u8069\u3001\u5929\u5EAD\u7B49\u7EA7\u68EE\u4E25\uFF0C\u300C\u9F50\u5929\u5927\u5723\u300D\u53EA\u662F\u4E2A\u7A7A\u8854\uFF0C\u53D6\u7ECF\u8DEF\u4E0A\u963F\u50A9\u3001\u8FE6\u53F6\u8FD8\u8981\u5411\u5510\u50E7\u7D22\u8981\u300C\u4EBA\u4E8B\u300D\u624D\u80AF\u4F20\u7ECF\u3002",
      "## \u624B\u6CD5\u4E0D\u540C\uFF1A\u767D\u63CF\u5199\u5B9E\u4E0E\u5E7B\u60F3\u8352\u8BDE",
      "\u5434\u656C\u6893\u7684\u7B14\u6CD5\u662F\u51B7\u7684\u3002\u4ED6\u51E0\u4E4E\u4E0D\u52A0\u8BC4\u8BBA\uFF0C\u53EA\u628A\u4EBA\u7269\u7684\u8A00\u884C\u539F\u6837\u6446\u51FA\u6765\uFF1A\u4E25\u76D1\u751F\u4F38\u7740\u4E24\u6839\u624B\u6307\uFF0C\u8C01\u4E5F\u4E0D\u53BB\u89E3\u91CA\uFF0C\u8BFB\u8005\u81EA\u5DF1\u7B11\u51FA\u6765\uFF0C\u4E5F\u81EA\u5DF1\u5FC3\u51C9\u4E0B\u6765\u3002\u8FD9\u5C31\u662F\u9C81\u8FC5\u6240\u8BF4\u7684\u300C\u5A49\u800C\u591A\u8BBD\u300D\u3002\u300A\u897F\u6E38\u8BB0\u300B\u7684\u7B14\u6CD5\u662F\u70ED\u7684\uFF1A\u5B83\u628A\u73B0\u5B9E\u7684\u8352\u5510\u653E\u5927\u6210\u795E\u8BDD\u7684\u5938\u5F20\uFF0C\u8BA9\u4E00\u53EA\u7334\u5B50\u7684\u987D\u76AE\u53BB\u51B2\u649E\u795E\u4ED9\u7684\u4F53\u9762\uFF0C\u8BA9\u732A\u516B\u6212\u7684\u8D2A\u61D2\u53BB\u66B4\u9732\u4EBA\u7684\u5F31\u70B9\u3002\u8BFB\u8005\u4E00\u8DEF\u7B11\uFF0C\u4E00\u8DEF\u9192\u3002",
      "## \u7B11\u7684\u6027\u8D28\u4E0D\u540C\uFF1A\u60B2\u60AF\u4E0E\u8BD9\u8C10",
      "\u300A\u5112\u6797\u5916\u53F2\u300B\u91CC\u7684\u5632\u8BBD\u5E26\u7740\u601C\u60AF\u3002\u8303\u8FDB\u3001\u5468\u8FDB\u672C\u8EAB\u4E5F\u662F\u5236\u5EA6\u7684\u53D7\u5BB3\u8005\uFF1A\u4ED6\u4EEC\u8017\u5C3D\u4E00\u751F\u53EA\u4E3A\u4E2D\u4E3E\uFF0C\u4E2D\u4E3E\u4E4B\u540E\u7ACB\u523B\u6362\u4E86\u4E00\u526F\u9762\u5B54\u3002\u4F5C\u8005\u7B11\u4ED6\u4EEC\uFF0C\u4E5F\u601C\u4ED6\u4EEC\u3002\u9C81\u8FC5\u56E0\u6B64\u8BF4\u5B83\u300C\u79C9\u6301\u516C\u5FC3\uFF0C\u6307\u64FF\u65F6\u5F0A\u300D\u300C\u621A\u800C\u80FD\u8C10\u300D\u3002\u300A\u897F\u6E38\u8BB0\u300B\u5219\u66F4\u591A\u662F\u6E38\u620F\u7B14\u58A8\u5F0F\u7684\u63F6\u63C4\uFF1A\u80E1\u9002\u66FE\u8BF4\u5B83\u300C\u81F3\u591A\u4E0D\u8FC7\u662F\u4E00\u90E8\u5F88\u6709\u8DA3\u5473\u7684\u6ED1\u7A3D\u5C0F\u8BF4\u3001\u795E\u8BDD\u5C0F\u8BF4\u300D\u3002\u524D\u8005\u7684\u7B11\u91CC\u6709\u5BD2\u610F\uFF0C\u540E\u8005\u7684\u7B11\u91CC\u6709\u8C10\u8DA3\u3002",
      "## \u7ED3\u6784\u4E0D\u540C\uFF1A\u77ED\u5236\u8FDE\u7F00\u4E0E\u516B\u5341\u4E00\u96BE",
      "\u9C81\u8FC5\u8BC4\u300A\u5112\u6797\u5916\u53F2\u300B\u300C\u867D\u4E91\u957F\u7BC7\uFF0C\u9887\u540C\u77ED\u5236\u300D\uFF1A\u5168\u4E66\u7531\u4E00\u4E2A\u4EBA\u7269\u63A5\u7EED\u4E00\u4E2A\u4EBA\u7269\u5C55\u5F00\uFF0C\u4E00\u4E2A\u4EBA\u7684\u6545\u4E8B\u8BB2\u5B8C\uFF0C\u4E0B\u4E00\u4E2A\u4EBA\u63A5\u4E0A\uFF0C\u6CA1\u6709\u8D2F\u7A7F\u59CB\u7EC8\u7684\u4E3B\u89D2\u3002\u300A\u897F\u6E38\u8BB0\u300B\u5219\u6709\u5927\u95F9\u5929\u5BAB\u4E0E\u897F\u884C\u53D6\u7ECF\u4E24\u5927\u5757\uFF0C\u53D6\u7ECF\u90E8\u5206\u7531\u4E5D\u4E5D\u516B\u5341\u4E00\u96BE\u8FDE\u7F00\uFF0C\u5B59\u609F\u7A7A\u662F\u8D2F\u7A7F\u5168\u4E66\u7684\u6838\u5FC3\u4EBA\u7269\u3002\u524D\u8005\u9760\u5171\u540C\u7684\u4E3B\u9898\u4E0E\u8BBD\u523A\u6001\u5EA6\u7EDF\u4E00\u5168\u4E66\uFF0C\u540E\u8005\u9760\u4E00\u4E2A\u4E3B\u89D2\u4E0E\u4E00\u8FDE\u4E32\u5386\u9669\u4E32\u8D77\u5168\u4E66\u3002\u7ED3\u6784\u4E0A\u7684\u5DEE\u522B\uFF0C\u6B63\u662F\u4E24\u79CD\u7B14\u6CD5\u7684\u81EA\u7136\u7ED3\u679C\u3002",
      "## \u4E3A\u4EC0\u4E48\u5E7B\u60F3\u5C0F\u8BF4\u7279\u522B\u9002\u5408\u8BBD\u523A",
      "\u795E\u8BDD\u63D0\u4F9B\u4E86\u4E00\u79CD\u300C\u5B89\u5168\u7684\u8DDD\u79BB\u300D\uFF1A\u5199\u8001\u864E\u3001\u5199\u960E\u738B\uFF0C\u4E0D\u5FC5\u76F4\u63A5\u6307\u540D\u73B0\u5B9E\uFF0C\u5374\u8C01\u90FD\u80FD\u770B\u61C2\uFF1B\u5938\u5F20\u53C8\u6BD4\u5199\u5B9E\u66F4\u9192\u76EE\uFF0C\u5929\u5EAD\u5F00\u4E00\u6B21\u87E0\u6843\u4F1A\uFF0C\u5C31\u628A\u7B49\u7EA7\u3001\u6392\u573A\u3001\u4EBA\u60C5\u4E00\u5E76\u5199\u4E86\u51FA\u6765\u3002\u5199\u5B9E\u767D\u63CF\u7684\u8BBD\u523A\u5219\u53E6\u6709\u529B\u91CF\uFF0C\u5B83\u7684\u529B\u91CF\u6765\u81EA\u300C\u786E\u6709\u5176\u4EBA\u5176\u4E8B\u300D\u7684\u5B9E\u8BC1\u611F\u2014\u2014\u8BFB\u8005\u77E5\u9053\u8303\u8FDB\u3001\u5468\u8FDB\u8FD9\u6837\u7684\u4EBA\u662F\u771F\u5B9E\u5B58\u5728\u7684\u3002\u4E24\u79CD\u7B14\u6CD5\u5404\u5360\u4E00\u7AEF\uFF0C\u653E\u5728\u4E00\u8D77\u770B\uFF0C\u6B63\u597D\u7167\u51FA\u660E\u6E05\u5C0F\u8BF4\u8BBD\u523A\u827A\u672F\u7684\u5168\u8C8C\u3002",
      "## \u6BD4\u8F83\u9898\u7684\u843D\u70B9",
      "\u4E2D\u8003\u7684\u8DE8\u4E66\u6BD4\u8F83\u9898\u5E38\u95EE\u300C\u8FD9\u4E24\u90E8\u4F5C\u54C1\u7684\u8BBD\u523A\u6709\u4F55\u4E0D\u540C\u300D\u3002\u53EF\u4EE5\u4ECE\u56DB\u4E2A\u7EF4\u5EA6\u4F5C\u7B54\uFF1A\u5BF9\u8C61\uFF08\u8BFB\u4E66\u4EBA\u4E0E\u79D1\u4E3E\uFF0C\u795E\u4F5B\u79E9\u5E8F\u4E0E\u4EBA\u6027\u5F31\u70B9\uFF09\u3001\u624B\u6CD5\uFF08\u5199\u5B9E\u767D\u63CF\uFF0C\u5E7B\u60F3\u5938\u5F20\uFF09\u3001\u60C5\u611F\u5E95\u8272\uFF08\u60B2\u60AF\u4E2D\u5E26\u8BBD\u523A\uFF0C\u8BD9\u8C10\u4E2D\u5E26\u8BBD\u55BB\uFF09\u3001\u7ED3\u6784\uFF08\u77ED\u7BC7\u8FDE\u7F00\uFF0C\u5386\u9669\u4E32\u8FDE\uFF09\u3002\u6700\u540E\u8865\u4E00\u53E5\u5171\u540C\u7684\u6307\u5411\uFF1A\u4E24\u8005\u90FD\u501F\u8352\u8BDE\u663E\u51FA\u771F\u5B9E\uFF0C\u90FD\u8BA9\u8BFB\u8005\u5728\u7B11\u4E2D\u770B\u89C1\u95EE\u9898\u3002\u6709\u7EF4\u5EA6\u3001\u6709\u4F8B\u8BC1\u3001\u6709\u603B\u7ED3\uFF0C\u5C31\u662F\u5B8C\u6574\u7684\u7B54\u6848\u3002"
    ],
    think: [
      "\u8303\u8FDB\u53D1\u75AF\u4E0E\u732A\u516B\u6212\u7684\u8D2A\u61D2\uFF0C\u54EA\u4E00\u79CD\u66F4\u80FD\u8BA9\u4F60\u300C\u7B11\u4E2D\u5E26\u523A\u300D\uFF1F\u4E3A\u4EC0\u4E48\uFF1F",
      "\u5982\u679C\u8BA9\u5434\u656C\u6893\u53BB\u5199\u5929\u5EAD\u3001\u8BA9\u5434\u627F\u6069\u53BB\u5199\u79D1\u4E3E\uFF0C\u4E24\u4F4D\u4F5C\u8005\u7684\u5199\u6CD5\u4F1A\u5404\u6709\u4EC0\u4E48\u53D8\u5316\uFF1F",
      "\u5E7B\u60F3\u5C0F\u8BF4\u4E3A\u4EC0\u4E48\u8981\u7ED9\u73B0\u5B9E\u8499\u4E0A\u4E00\u5C42\u795E\u8BDD\u7684\u5916\u8863\uFF1F\u8FD9\u79CD\u300C\u8DDD\u79BB\u300D\u5E26\u6765\u4EC0\u4E48\u597D\u5904\uFF1F"
    ]
  },
  {
    id: "ext-cmp-hongxing-hongyan",
    moduleId: "literature",
    entryId: "l-hongxingzhaoyaozhongguo",
    grade: "8a",
    kind: "\u5BF9\u6BD4\u9605\u8BFB",
    title: "\u300A\u7EA2\u661F\u7167\u8000\u4E2D\u56FD\u300B\u4E0E\u300A\u7EA2\u5CA9\u300B\uFF1A\u7EAA\u5B9E\u4E0E\u5C0F\u8BF4\u4E24\u79CD\u771F\u5B9E",
    summary: "\u65AF\u8BFA\u7528\u91C7\u8BBF\u7B14\u8BB0\u5199\u771F\u5B9E\u7684\u4EBA\u7269\uFF0C\u300A\u7EA2\u5CA9\u300B\u628A\u591A\u4F4D\u70C8\u58EB\u7684\u4E8B\u8FF9\u96C6\u4E2D\u5728\u4E00\u4EBA\u8EAB\u4E0A\u3002",
    content: [
      "## \u6587\u4F53\u4E0D\u540C\uFF1A\u62A5\u544A\u6587\u5B66\u4E0E\u957F\u7BC7\u5C0F\u8BF4",
      "\u300A\u7EA2\u661F\u7167\u8000\u4E2D\u56FD\u300B\u662F\u7EAA\u5B9E\u4F5C\u54C1\uFF0C\u5C5E\u4E8E\u62A5\u544A\u6587\u5B66\u3002\u65AF\u8BFA\u662F\u8BB0\u8005\uFF0C\u4ED6\u5199\u7684\u662F\u91C7\u8BBF\u89C1\u95FB\u3001\u5BF9\u8BDD\u8BB0\u5F55\u4E0E\u4E2A\u4EBA\u89C2\u5BDF\uFF0C\u6750\u6599\u6765\u81EA 1936 \u5E74 7 \u6708\u81F3 10 \u6708\u5728\u9655\u5317\u7684\u5B9E\u5730\u8BBF\u95EE\uFF0C\u65F6\u95F4\u3001\u5730\u70B9\u3001\u4EBA\u7269\u3001\u539F\u8BDD\u90FD\u53EF\u4EE5\u6838\u67E5\u3002\u300A\u7EA2\u5CA9\u300B\u5219\u662F\u957F\u7BC7\u5C0F\u8BF4\u3002\u7F57\u5E7F\u658C\u3001\u6768\u76CA\u8A00\u867D\u7136\u90FD\u662F\u6E23\u6ED3\u6D1E\u3001\u767D\u516C\u9986\u7684\u5E78\u5B58\u8005\uFF0C\u4F46\u4ED6\u4EEC\u5199\u7684\u662F\u7ECF\u8FC7\u827A\u672F\u52A0\u5DE5\u7684\u6587\u5B66\u4F5C\u54C1\uFF0C\u53EF\u4EE5\u96C6\u4E2D\u3001\u79FB\u7F6E\u3001\u865A\u6784\u3002\u6587\u4F53\u4E0D\u540C\uFF0C\u8BC4\u4EF7\u5B83\u4EEC\u7684\u6807\u51C6\u4E5F\u4E0D\u540C\uFF1A\u524D\u8005\u770B\u662F\u5426\u771F\u5B9E\u53EF\u4FE1\uFF0C\u540E\u8005\u770B\u662F\u5426\u5178\u578B\u52A8\u4EBA\u3002",
      "## \u4EBA\u7269\u6765\u6E90\u4E0D\u540C\uFF1A\u771F\u540D\u5B9E\u59D3\u4E0E\u539F\u578B\u5851\u9020",
      "\u65AF\u8BFA\u7B14\u4E0B\u7684\u4EBA\u7269\u90FD\u662F\u771F\u5B9E\u7684\uFF1A\u6BDB\u6CFD\u4E1C\u3001\u5468\u6069\u6765\u3001\u5F6D\u5FB7\u6000\u3001\u6797\u5F6A\u3001\u8D3A\u9F99\u3001\u5F90\u6D77\u4E1C\u3001\u5F90\u7279\u7ACB\uFF0C\u8FD8\u6709\u666E\u901A\u7684\u7EA2\u519B\u6218\u58EB\u548C\u88AB\u79F0\u4E3A\u300C\u7EA2\u5C0F\u9B3C\u300D\u7684\u5C11\u5E74\u3002\u4ED6\u5199\u6BDB\u6CFD\u4E1C\u300C\u9762\u5BB9\u7626\u524A\uFF0C\u770B\u4E0A\u53BB\u5F88\u50CF\u6797\u80AF\u7684\u4EBA\u7269\u300D\uFF0C\u5199\u5468\u6069\u6765\u7528\u80F3\u818A\u6402\u7740\u7EA2\u5C0F\u9B3C\u7684\u80A9\u8180\u2014\u2014\u8FD9\u4E9B\u90FD\u662F\u4EB2\u773C\u6240\u89C1\u3002\u300A\u7EA2\u5CA9\u300B\u7684\u4EBA\u7269\u5219\u662F\u300C\u539F\u578B\u52A0\u7EFC\u5408\u300D\uFF1A\u6C5F\u96EA\u7434\uFF08\u6C5F\u59D0\uFF09\u7684\u539F\u578B\u662F\u6C5F\u7AF9\u7B60\uFF0C\u6210\u5C97\u7684\u539F\u578B\u662F\u9648\u7136\uFF0C\u534E\u5B50\u826F\u7684\u539F\u578B\u662F\u97E9\u5B50\u680B\uFF0C\u5C0F\u841D\u535C\u5934\u672C\u540D\u5B8B\u632F\u4E2D\uFF1B\u800C\u8BB8\u4E91\u5CF0\u5219\u7EFC\u5408\u4E86\u8BB8\u6653\u8F69\u3001\u8F66\u8000\u5148\u7B49\u591A\u4F4D\u70C8\u58EB\u7684\u4E8B\u8FF9\uFF0C\u53DB\u5F92\u752B\u5FD7\u9AD8\u4E5F\u7EFC\u5408\u4E86\u51E0\u540D\u53DB\u5F92\u7684\u52A3\u8FF9\u3002",
      "## \u4E00\u5904\u5177\u4F53\u7684\u5DEE\u522B\uFF1A\u7EE3\u7EA2\u65D7",
      "\u636E\u53F2\u6599\uFF0C\u7528\u7EA2\u8272\u88AB\u9762\u548C\u9EC4\u7EB8\u505A\u6210\u4E94\u661F\u7EA2\u65D7\u7684\uFF0C\u662F\u5173\u62BC\u5728\u767D\u516C\u9986\u7684\u7F57\u5E7F\u658C\u3001\u9648\u7136\u7B49\u4EBA\uFF1B\u4ED6\u4EEC\u53EA\u77E5\u9053\u56FD\u65D7\u7684\u540D\u5B57\uFF0C\u4E0D\u77E5\u9053\u4E94\u9897\u661F\u7684\u5177\u4F53\u6392\u5217\uFF0C\u51ED\u60F3\u8C61\u505A\u6210\u4E4B\u540E\u85CF\u5728\u7262\u623F\u7684\u5730\u677F\u4E0B\u9762\u3002\u5C0F\u8BF4\u5219\u628A\u8FD9\u4EF6\u4E8B\u5199\u6210\u5973\u7262\u4E2D\u6C5F\u59D0\u7B49\u4EBA\u4E00\u9488\u4E00\u7EBF\u5730\u7EE3\u3002\u8FD9\u5C31\u662F\u6240\u8C13\u300C\u5178\u578B\u5316\u300D\uFF1A\u4F5C\u8005\u628A\u5206\u6563\u5728\u4E0D\u540C\u4EBA\u8EAB\u4E0A\u7684\u4E8B\u8FF9\uFF0C\u96C6\u4E2D\u5230\u4E00\u4E2A\u6700\u6709\u4EE3\u8868\u6027\u7684\u4EBA\u7269\u8EAB\u4E0A\uFF0C\u4F7F\u60C5\u8282\u66F4\u96C6\u4E2D\u3001\u60C5\u611F\u66F4\u5F3A\u70C8\u3002\u8FD9\u4E5F\u6B63\u662F\u8BFB\u7EA2\u8272\u7ECF\u5178\u8981\u5206\u6E05\u53F2\u5B9E\u4E0E\u827A\u672F\u52A0\u5DE5\u7684\u5730\u65B9\u3002",
      "## \u89C2\u5BDF\u8005\u7684\u4F4D\u7F6E\u4E0D\u540C",
      "\u65AF\u8BFA\u662F\u5916\u6765\u8005\u3002\u4ED6\u7684\u4E66\u91CC\u4FDD\u7559\u4E86\u5927\u91CF\u7684\u7591\u95EE\u3001\u8BEF\u89E3\u4E0E\u4E0D\u5B8C\u6574\uFF0C\u8BB8\u591A\u6BB5\u843D\u5199\u7684\u662F\u300C\u6211\u95EE\u4ED6\u300D\u300C\u6211\u4E0D\u660E\u767D\u300D\u300C\u4ED6\u4EEC\u8BF4\u300D\uFF1B\u4ED6\u4E0D\u63A9\u9970\u81EA\u5DF1\u60F3\u4E0D\u901A\u7684\u5730\u65B9\u3002\u6B63\u662F\u8FD9\u79CD\u5E26\u6709\u7F3A\u53E3\u7684\u76EE\u5149\uFF0C\u8BA9\u4E16\u754C\u76F8\u4FE1\u4E86\u4ED6\u7684\u62A5\u9053\u3002\u7F57\u5E7F\u658C\u3001\u6768\u76CA\u8A00\u662F\u4EB2\u5386\u8005\uFF0C\u4ED6\u4EEC\u5BF9\u72F1\u4E2D\u7684\u7EC6\u8282\u2014\u2014\u7AF9\u7B7E\u3001\u7EDD\u98DF\u3001\u8FFD\u60BC\u3001\u8054\u6B22\u4F1A\u3001\u8D8A\u72F1\u2014\u2014\u6709\u5207\u8EAB\u7684\u8BB0\u5FC6\uFF0C\u6240\u4EE5\u5199\u6765\u6CA1\u6709\u9694\u819C\uFF1B\u4F46\u4E5F\u6B63\u56E0\u4E3A\u8EAB\u5728\u5176\u4E2D\uFF0C\u4ED6\u4EEC\u66F4\u9700\u8981\u7528\u6587\u5B66\u7684\u65B9\u5F0F\u628A\u4F17\u591A\u4E8B\u8FF9\u51DD\u805A\u6210\u51E0\u4E2A\u5F62\u8C61\u3002",
      "## \u4E24\u79CD\u300C\u771F\u5B9E\u300D\u5404\u81EA\u7684\u4EF7\u503C",
      "\u7EAA\u5B9E\u4F5C\u54C1\u7684\u4EF7\u503C\u5728\u4E8E\u53EF\u6838\u67E5\uFF1A\u65AF\u8BFA\u662F\u7B2C\u4E00\u4E2A\u8FDB\u5165\u7EA2\u533A\u91C7\u8BBF\u7684\u897F\u65B9\u8BB0\u8005\uFF0C\u4ED6\u7684\u8BB0\u5F55\u81F3\u4ECA\u662F\u7814\u7A76\u90A3\u6BB5\u5386\u53F2\u7684\u91CD\u8981\u53F2\u6599\uFF0C\u8BFB\u8005\u4ECE\u4E2D\u5F97\u5230\u7684\u662F\u5F00\u9614\u4E0E\u53EF\u4FE1\u3002\u5C0F\u8BF4\u7684\u4EF7\u503C\u5728\u4E8E\u53EF\u611F\u53D7\uFF1A\u5B83\u628A\u4E09\u767E\u591A\u4F4D\u9047\u96BE\u8005\u7684\u547D\u8FD0\u538B\u7F29\u8FDB\u51E0\u4E2A\u5F62\u8C61\u4E4B\u4E2D\uFF0C\u8BA9\u8BFB\u8005\u8BB0\u4F4F\u6C5F\u59D0\u3001\u8BB8\u4E91\u5CF0\uFF0C\u4E5F\u8BB0\u4F4F 1949 \u5E74 11 \u6708 27 \u65E5\u90A3\u4E2A\u591C\u665A\u2014\u2014\u91CD\u5E86\u5728\u4E09\u5929\u4E4B\u540E\u7684 11 \u6708 30 \u65E5\u89E3\u653E\u3002\u4E00\u4E2A\u8BA9\u4EBA\u300C\u77E5\u9053\u300D\uFF0C\u4E00\u4E2A\u8BA9\u4EBA\u300C\u8BB0\u4F4F\u300D\u3002",
      "## \u4E2D\u8003\u6BD4\u8F83\u9898\u7684\u601D\u8DEF",
      "\u9047\u5230\u300C\u7EAA\u5B9E\u4F5C\u54C1\u4E0E\u5C0F\u8BF4\u5199\u540C\u4E00\u6BB5\u5386\u53F2\uFF0C\u4F60\u66F4\u559C\u6B22\u54EA\u4E00\u79CD\u300D\u8FD9\u7C7B\u5F00\u653E\u9898\uFF0C\u4E0D\u5FC5\u6025\u4E8E\u9009\u8FB9\u3002\u53EF\u4EE5\u4ECE\u4E09\u4E2A\u65B9\u9762\u5206\u6790\uFF1A\u6750\u6599\u6765\u6E90\uFF08\u91C7\u8BBF\u8BB0\u5F55\u4E0E\u4EB2\u8EAB\u7ECF\u5386\u3001\u53F2\u6599\uFF09\u3001\u5851\u9020\u65B9\u6CD5\uFF08\u5982\u5B9E\u8BB0\u5F55\u4E0E\u5178\u578B\u5316\u96C6\u4E2D\uFF09\u3001\u9605\u8BFB\u6548\u679C\uFF08\u53EF\u4FE1\u5F00\u9614\u4E0E\u52A8\u4EBA\u96C6\u4E2D\uFF09\uFF1B\u7136\u540E\u7ED9\u51FA\u81EA\u5DF1\u7684\u504F\u597D\uFF0C\u5E76\u8BF4\u660E\u7406\u7531\u3002\u5BA1\u9898\u7684\u5173\u952E\u662F\u5148\u770B\u6E05\u9898\u76EE\u95EE\u7684\u662F\u300C\u6587\u4F53\u5DEE\u5F02\u300D\u8FD8\u662F\u300C\u8868\u8FBE\u6548\u679C\u300D\u2014\u2014\u95EE\u5DEE\u5F02\u5C31\u5206\u70B9\u5BF9\u7167\uFF0C\u95EE\u6548\u679C\u5C31\u7ED3\u5408\u5177\u4F53\u60C5\u8282\u8C08\u611F\u53D7\u3002"
    ],
    think: [
      "\u5C0F\u8BF4\u53EF\u4EE5\u628A\u51E0\u4F4D\u70C8\u58EB\u7684\u4E8B\u8FF9\u300C\u5408\u5E76\u300D\u5230\u4E00\u4E2A\u4EBA\u8EAB\u4E0A\u3002\u8FD9\u6837\u7684\u5904\u7406\u4E0E\u5386\u53F2\u8457\u4F5C\u7684\u8981\u6C42\u6709\u4EC0\u4E48\u4E0D\u540C\uFF1F",
      "\u65AF\u8BFA\u5728\u4E66\u91CC\u4FDD\u7559\u4E86\u7591\u95EE\u4E0E\u8BEF\u89E3\uFF0C\u7F57\u5E7F\u658C\u3001\u6768\u76CA\u8A00\u5219\u51E0\u4E4E\u4E0D\u5199\u72B9\u7591\u3002\u8FD9\u4E24\u79CD\u5199\u6CD5\u5404\u6709\u4EC0\u4E48\u4EE3\u4EF7\u4E0E\u6536\u83B7\uFF1F",
      "\u5982\u679C\u8981\u4E3A\u4E00\u767E\u5E74\u540E\u7684\u8BFB\u8005\u4FDD\u5B58\u8FD9\u6BB5\u5386\u53F2\uFF0C\u4F60\u4F1A\u9009\u62E9\u7EAA\u5B9E\u7684\u7B14\uFF0C\u8FD8\u662F\u5C0F\u8BF4\u7684\u7B14\uFF1F"
    ]
  }
];

