      stem: "\u4E0B\u5217\u8BCD\u8BED\u4E2D\u52A0\u70B9\u5B57\u7684\u8BFB\u97F3\u5B8C\u5168\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
