        "\u4E0D\u8D85\u8FC7 60 \u5B57\uFF0C\u6CA1\u6709\u300C\u4F60\u5FC5\u987B\u300D\u300C\u4E0D\u8BB8\u9000\u7F29\u300D\u8FD9\u7C7B\u547D\u4EE4\u5F0F\u8868\u8FBE\u3002"
