      difficulty: 2,
      tags: ["\u53E3\u8BED\u4EA4\u9645\u4E0E\u60C5\u5883\u8868\u8FBE", "\u79EF\u7D2F\u4E0E\u8FD0\u7528", "\u529D\u8BF4"]
