      stem: "\u4E0B\u9762\u53E5\u5B50\u4E2D\u6709\u4E00\u4E2A\u6807\u70B9\u4F7F\u7528\u4E0D\u5F53\uFF0C\u8BF7\u5199\u51FA\u5E94\u8BE5\u5220\u53BB\u7684\u90A3\u4E2A\u6807\u70B9\u7684\u540D\u79F0\uFF08\u53EA\u5199\u540D\u79F0\uFF09\uFF1A\n\u300C\u8FD9\u6B21\u8BFB\u4E66\u8282\u5B89\u6392\u4E86\u7ECF\u5178\u8BF5\u8BFB\u3001\u8BFB\u4E66\u5206\u4EAB\u3001\u548C\u8BD7\u8BCD\u63A5\u9F99\u4E09\u9879\u6D3B\u52A8\u3002\u300D",
