      stem: "\u4E0B\u5217\u5404\u53E5\u4E2D\uFF0C\u8BED\u75C5\u7C7B\u578B\u4E0E\u5176\u4ED6\u4E09\u9879\u4E0D\u540C\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
