      type: "choice",
      stem: "\u4E0B\u5217\u53E4\u4EE3\u5E74\u9F84\u4EE3\u79F0\u4E0E\u6240\u6307\u5E74\u9F84\u5BF9\u5E94\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
