      stem: "\u5168\u5305\u56F4\u7ED3\u6784\u7684\u5B57\u8981\u6309\u300C\u5148\u5916\u540E\u5185\u518D\u5C01\u53E3\u300D\u7684\u7B14\u987A\u6765\u5199\u3002\u8BF7\u5199\u51FA\u300C\u56FD\u300D\u5B57\u7684\u6700\u540E\u4E00\u7B14\u662F\u54EA\u4E00\u79CD\u7B14\u753B\uFF08\u53EA\u5199\u7B14\u753B\u540D\u79F0\uFF0C\u5982\u6A2A\u3001\u7AD6\u3001\u6487\u3001\u70B9\u3001\u637A\u3001\u6A2A\u6298\u7B49\uFF09\u3002",
      answer: "\u6A2A|\u6A2A\u753B|\u957F\u6A2A",
      explanation: "\u600E\u4E48\u60F3\u5230\u7684\uFF1A\u5168\u5305\u56F4\u7ED3\u6784\u7684\u5B57\uFF08\u56FD\u3001\u56DE\u3001\u56E0\u3001\u56FE\uFF09\u90FD\u6309\u300C\u5148\u5916\u540E\u5185\u518D\u5C01\u53E3\u300D\u7684\u7B14\u987A\u5199\u3002\u300C\u56FD\u300D\u5171\u516B\u7B14\uFF0C\u5148\u5199\u5DE6\u8FB9\u7684\u7AD6\u3001\u4E0A\u8FB9\u7684\u6A2A\u6298\u642D\u51FA\u5916\u6846\uFF0C\u4E2D\u95F4\u5199\u6846\u91CC\u7684\u300C\u7389\u300D\uFF0C\u6700\u540E\u7528\u4E00\u6A2A\u628A\u5E95\u8FB9\u5C01\u4F4F\uFF0C\u6240\u4EE5\u6700\u540E\u4E00\u7B14\u662F\u6A2A\u3002\u8FD9\u4E00\u7B14\u662F\u6536\u53E3\u7B14\uFF0C\u5199\u6210\u7AD6\u6216\u70B9\u90FD\u5C01\u4E0D\u4F4F\u6846\uFF0C\u5B57\u5C31\u4F1A\u663E\u5F97\u6563\u3002\u5BF9\u6BD4\u5176\u4ED6\u7ED3\u6784\uFF1A\u5DE6\u4E2D\u53F3\u7ED3\u6784\u7684\u5B57\u5982\u300C\u6E56\u300D\u6309\u5DE6\u3001\u4E2D\u3001\u53F3\u7684\u987A\u5E8F\u5199\uFF1B\u300C\u4E49\u300D\u7684\u70B9\u5728\u6B63\u4E0A\u65B9\uFF0C\u8981\u7B2C\u4E00\u7B14\u5199\u70B9\u3002\u5404\u7ED3\u6784\u7684\u6536\u7B14\u4E0D\u540C\uFF0C\u4E0D\u80FD\u4E00\u5F8B\u5957\u7528\u5168\u5305\u56F4\u7684\u7ED3\u8BBA\u3002",
