      stem: "\u4E0B\u9762\u8FD9\u53E5\u8BDD\u6709\u4E24\u79CD\u7406\u89E3\uFF1A\u300C\u5988\u5988\u8BA9\u6211\u628A\u6628\u5929\u4E70\u7684\u86CB\u7CD5\u548C\u725B\u5976\u7ED9\u90BB\u5C45\u9001\u53BB\u3002\u300D\u8BF7\u5199\u51FA\u8FD9\u4E24\u79CD\u7406\u89E3\uFF0C\u5E76\u8BF4\u660E\u6539\u52A8\u54EA\u4E00\u5904\u53EF\u4EE5\u8BA9\u53E5\u5B50\u53EA\u6709\u4E00\u4E2A\u610F\u601D\uFF0C\u518D\u5199\u51FA\u6539\u540E\u7684\u53E5\u5B50\u3002",
      answer: "\u4E24\u79CD\u7406\u89E3\uFF1A\u2460\u300C\u6628\u5929\u4E70\u7684\u300D\u540C\u65F6\u4FEE\u9970\u86CB\u7CD5\u548C\u725B\u5976\uFF0C\u4E24\u6837\u90FD\u662F\u6628\u5929\u4E70\u7684\uFF1B\u2461\u300C\u6628\u5929\u4E70\u7684\u300D\u53EA\u4FEE\u9970\u86CB\u7CD5\uFF0C\u725B\u5976\u4E0D\u662F\u6628\u5929\u4E70\u7684\u3002\u6539\u6CD5\u662F\u70B9\u660E\u4FEE\u9970\u8BED\u7BA1\u5230\u54EA\u513F\uFF1A\u60F3\u8BA9\u4E24\u6837\u90FD\u662F\u6628\u5929\u4E70\u7684\uFF0C\u5C31\u5199\u6210\u300C\u5988\u5988\u8BA9\u6211\u628A\u6628\u5929\u4E70\u7684\u86CB\u7CD5\u548C\u725B\u5976\u90FD\u7ED9\u90BB\u5C45\u9001\u53BB\u300D\uFF1B\u60F3\u8BA9\u53EA\u6709\u86CB\u7CD5\u662F\u6628\u5929\u4E70\u7684\uFF0C\u5C31\u5199\u6210\u300C\u5988\u5988\u8BA9\u6211\u628A\u6628\u5929\u4E70\u7684\u86CB\u7CD5\u548C\u5BB6\u91CC\u7684\u725B\u5976\u7ED9\u90BB\u5C45\u9001\u53BB\u300D\u3002",
      explanation: "\u600E\u4E48\u60F3\u5230\u7684\uFF1A\u4E00\u4E2A\u4FEE\u9970\u8BED\u540E\u9762\u8DDF\u7740\u4E24\u4E2A\u540D\u8BCD\uFF0C\u5C31\u8981\u95EE\u5B83\u6302\u5728\u54EA\u4E2A\u540D\u8BCD\u4E0A\uFF1B\u4E24\u4E2A\u90FD\u8BB2\u5F97\u901A\uFF0C\u5C31\u662F\u4FEE\u9970\u8303\u56F4\u4E0D\u660E\u3002\u6539\u7684\u65F6\u5019\u4E0D\u5FC5\u91CD\u5199\u53E5\u5B50\uFF0C\u53EA\u8981\u628A\u8303\u56F4\u70B9\u660E\u2014\u2014\u8981\u4E48\u8BA9\u4FEE\u9970\u8BED\u7BA1\u4F4F\u4E24\u9879\uFF0C\u8981\u4E48\u628A\u53E6\u4E00\u9879\u5355\u72EC\u4EA4\u4EE3\u6E05\u695A\u3002\u6539\u5B8C\u6309\u4E24\u79CD\u505C\u987F\u5404\u8BFB\u4E00\u904D\uFF0C\u53EA\u6709\u4E00\u79CD\u8BFB\u6CD5\u6210\u7ACB\u624D\u7B97\u6539\u597D\u3002",
