      type: "fill",
      stem: "\u300A\u6708\u591C\u5FC6\u820D\u5F1F\u300B\u4E2D\u501F\u4ECA\u591C\u767D\u9732\u4E0E\u6545\u4E61\u4E4B\u6708\u5BC4\u6258\u601D\u4E61\u6000\u4EBA\u4E4B\u60C5\u7684\u8FDE\u7EED\u4E24\u53E5\u662F\uFF1A\n________\uFF0C________\u3002",
      answer: "\u9732\u4ECE\u4ECA\u591C\u767D\uFF0C\u6708\u662F\u6545\u4E61\u660E",
      explanation: "\u63D0\u793A\u8BED\u300C\u4ECA\u591C\u767D\u9732\u300D\u300C\u6545\u4E61\u4E4B\u6708\u300D\u76F4\u63A5\u5BF9\u5E94\u300C\u9732\u4ECE\u4ECA\u591C\u767D\uFF0C\u6708\u662F\u6545\u4E61\u660E\u300D\uFF0C\u540E\u8005\u662F\u601D\u4E61\u540D\u53E5\uFF0C\u6708\u4EAE\u672C\u8EAB\u5404\u5904\u4E00\u6837\u660E\uFF0C\u8BF4\u300C\u6545\u4E61\u660E\u300D\u662F\u4E3B\u89C2\u611F\u53D7\uFF0C\u5C5E\u4EE5\u666F\u5199\u60C5\u7684\u5199\u6CD5\u3002\u6613\u9519\uFF1A\u300C\u9732\u300D\u662F\u96E8\u5B57\u5934\uFF1B\u300C\u660E\u300D\u4E0D\u8981\u5199\u6210\u300C\u540D\u300D\uFF1B\u300C\u6545\u4E61\u300D\u4E0D\u8981\u5199\u6210\u300C\u6545\u9999\u300D\u3002",
      difficulty: 2,
