        "\u8BF4\u660E\u8FD9\u53E5\u8BDD\u5F3A\u8C03\u865A\u5FC3\u5B66\u4E60\u3001\u4EE5\u4ED6\u4EBA\u4E3A\u5E08\u3002",
        "\u542F\u793A\u843D\u5230\u81EA\u8EAB\u5B66\u4E60\uFF0C\u5177\u4F53\u800C\u4E0D\u7A7A\u6CDB\u3002",
        "\u4E0D\u8D85\u8FC7 50 \u5B57\uFF0C\u8BED\u8A00\u8FDE\u8D2F\u3002"
