      stem: "\u4E0B\u9762\u662F\u4E00\u6761\u9488\u5BF9\u300A\u7B54\u8C22\u4E2D\u4E66\u4E66\u300B\u7684\u6279\u6CE8\uFF0C\u8BF7\u5199\u51FA\u4E0E\u6279\u6CE8\u610F\u601D\u5BF9\u5E94\u7684\u4E24\u7EC4\u539F\u6587\u53E5\u5B50\uFF0C\u5E76\u8BF4\u660E\u6279\u6CE8\u6293\u4F4F\u4E86\u54EA\u51E0\u4E2A\u5173\u952E\u8BCD\uFF1A\n\u6279\u6CE8\uFF1A\u4EE5\u300C\u5C06\u300D\u300C\u6B32\u300D\u5199\u65F6\u95F4\u63A8\u79FB\uFF0C\u733F\u9E1F\u4E0E\u6C89\u9CDE\u4E00\u4E0A\u4E00\u4E0B\u3001\u4E00\u52A8\u4E00\u9759\uFF0C\u5199\u5C3D\u6668\u660F\u4E4B\u7F8E\u3002",
