      stem: "\u4E0B\u9762\u8FD9\u53E5\u9ED8\u5199\u4E2D\u6709\u4E00\u4E2A\u9519\u522B\u5B57\uFF0C\u8BF7\u6307\u51FA\u5B83\u5E76\u5199\u51FA\u6539\u6B63\u540E\u7684\u5B8C\u6574\u53E5\u5B50\uFF1A\n\u4E88\u72EC\u7231\u83B2\u4E4B\u51FA\u6DE4\u6CE5\u800C\u4E0D\u67D3\uFF0C\u6FEF\u6E05\u83B2\u800C\u4E0D\u5996\u3002",
      answer: "\u300C\u6E05\u83B2\u300D\u5E94\u4E3A\u300C\u6E05\u6D9F\u300D\uFF0C\u6539\u6B63\u540E\u662F\u300C\u4E88\u72EC\u7231\u83B2\u4E4B\u51FA\u6DE4\u6CE5\u800C\u4E0D\u67D3\uFF0C\u6FEF\u6E05\u6D9F\u800C\u4E0D\u5996\u300D\u3002",
      explanation: "\u505A\u9898\u5148\u770B\u504F\u65C1\uFF1A\u300C\u6D9F\u300D\u4ECE\u4E09\u70B9\u6C34\uFF0C\u6307\u6C34\u6CE2\uFF08\u300C\u6D9F\u6F2A\u300D\u5373\u7EC6\u5C0F\u7684\u6C34\u6CE2\uFF09\uFF0C\u300C\u6FEF\u6E05\u6D9F\u300D\u610F\u4E3A\u5728\u6E05\u6C34\u91CC\u6D17\u6DA4\uFF1B\u300C\u83B2\u300D\u4ECE\u8349\u5B57\u5934\uFF0C\u662F\u8377\u82B1\u3002\u5199\u9519\u7684\u6839\u6E90\u662F\u8FD9\u4E00\u53E5\u91CC\u672C\u6765\u5C31\u6709\u300C\u83B2\u300D\u5B57\uFF0C\u5199\u7B2C\u4E8C\u4E2A\u540C\u97F3\u5B57\u65F6\u88AB\u524D\u6587\u7684\u300C\u83B2\u300D\u5E26\u504F\u2014\u2014\u8FD9\u662F\u540C\u53E5\u5185\u81EA\u6211\u5E72\u6270\u7684\u5178\u578B\uFF0C\u6240\u4EE5\u68C0\u67E5\u65F6\u8981\u4E13\u95E8\u56DE\u5934\u5355\u770B\u90A3\u4E2A\u5B57\uFF0C\u4E0D\u80FD\u4E00\u53E5\u8BFB\u8FC7\u53BB\u5C31\u7B97\u8FC7\u4E86\u3002",
