      stem: "\u4E3B\u9898\u5F0F\u9ED8\u5199\uFF08\u300C\u540C\u60C5\u767E\u59D3\u300D\uFF09\uFF1A\u300A\u5356\u70AD\u7FC1\u300B\u4E2D\u5199\u5356\u70AD\u8001\u4EBA\u8863\u886B\u5355\u8584\u3001\u5374\u56E0\u62C5\u5FC3\u70AD\u8D31\u5356\u4E0D\u51FA\u53BB\u800C\u76FC\u671B\u5929\u66F4\u51B7\u7684\u4E24\u53E5\u662F\uFF1A\n________\uFF0C________\u3002",
      answer: "\u53EF\u601C\u8EAB\u4E0A\u8863\u6B63\u5355\uFF0C\u5FC3\u5FE7\u70AD\u8D31\u613F\u5929\u5BD2",
      explanation: "\u4E3B\u9898\u662F\u300C\u540C\u60C5\u767E\u59D3\u300D\uFF0C\u68C0\u7D22\u65B9\u5411\u53EF\u62C6\u6210\u4E09\u5C42\uFF1A\u5199\u52B3\u52A8\u73AF\u5883\u4E4B\u82E6\u3001\u5199\u751F\u6D3B\u5904\u5883\u4E4B\u96BE\u3001\u5199\u5FC3\u7406\u4E4B\u77DB\u76FE\u3002\u8FD9\u4E24\u53E5\u6700\u52A8\u4EBA\u7684\u5730\u65B9\u6B63\u5728\u300C\u8863\u6B63\u5355\u300D\u4E0E\u300C\u613F\u5929\u5BD2\u300D\u7684\u77DB\u76FE\uFF1A\u4EBA\u51B7\u5F97\u53EA\u7A7F\u5355\u8863\uFF0C\u5374\u5B81\u613F\u5929\u518D\u51B7\u4E00\u4E9B\uFF0C\u56E0\u4E3A\u5929\u51B7\u70AD\u624D\u5356\u5F97\u4E0A\u4EF7\u3002\u6293\u4F4F\u8FD9\u4E2A\u77DB\u76FE\uFF0C\u5C31\u6293\u4F4F\u4E86\u300C\u540C\u60C5\u767E\u59D3\u300D\u7684\u843D\u70B9\u3002\u6613\u9519\u5B57\uFF1A\u300C\u601C\u300D\u662F\u7AD6\u5FC3\u65C1\uFF0C\u4E0D\u8981\u5199\u6210\u300C\u90BB\u300D\uFF1B\u300C\u70AD\u300D\u662F\u5C71\u5B57\u5934\uFF0C\u4E0D\u8981\u5199\u6210\u300C\u78B3\u300D\uFF1B\u300C\u8D31\u300D\u662F\u8D1D\u5B57\u65C1\uFF08\u4E0E\u94B1\u8D22\u6709\u5173\uFF09\uFF0C\u4E0D\u8981\u5199\u6210\u300C\u6E85\u300D\uFF1B\u300C\u613F\u300D\u4E0B\u9762\u662F\u5FC3\u5B57\u5E95\u3002",
