      type: "short",
      stem: "\u7FFB\u8BD1\u4E0B\u9762\u7684\u53E5\u5B50\uFF0C\u5E76\u8BF4\u660E\u5176\u4E2D\u5FC5\u987B\u843D\u5B9E\u7684\u91C7\u5206\u8BCD\uFF1A\n\u4EE5\u4E2D\u6709\u8DB3\u4E50\u8005\uFF0C\u4E0D\u77E5\u53E3\u4F53\u4E4B\u5949\u4E0D\u82E5\u4EBA\u4E5F\u3002\uFF08\u300A\u9001\u4E1C\u9633\u9A6C\u751F\u5E8F\u300B\uFF09",
      answer: "\u56E0\u4E3A\u5FC3\u4E2D\u6709\u8DB3\u4EE5\u5FEB\u4E50\u7684\u4E8B\uFF08\u8BFB\u4E66\uFF09\uFF0C\u5C31\u4E0D\u89C9\u5F97\u5403\u7684\u7A7F\u7684\u6BD4\u4E0D\u4E0A\u522B\u4EBA\u3002\u91C7\u5206\u8BCD\uFF1A\u300C\u4EE5\u300D\u662F\u56E0\u4E3A\uFF1B\u300C\u4E2D\u300D\u662F\u5FC3\u4E2D\uFF1B\u300C\u8DB3\u4E50\u8005\u300D\u662F\u8DB3\u4EE5\u5FEB\u4E50\u7684\u4E8B\uFF1B\u300C\u53E3\u4F53\u4E4B\u5949\u300D\u6307\u5403\u7684\u7A7F\u7684\u4F9B\u517B\uFF1B\u300C\u4E0D\u82E5\u300D\u662F\u4E0D\u5982\u3001\u6BD4\u4E0D\u4E0A\u3002",
      explanation: "\u8FD9\u4E00\u53E5\u6700\u5BB9\u6613\u9519\u7684\u662F\u300C\u53E3\u4F53\u4E4B\u5949\u300D\u2014\u2014\u82E5\u671B\u6587\u751F\u4E49\u89E3\u6210\u300C\u5634\u5DF4\u548C\u8EAB\u4F53\u7684\u5949\u517B\u300D\u5C31\u5B8C\u5168\u504F\u4E86\uFF0C\u5B83\u6307\u7684\u662F\u8863\u98DF\u4F9B\u517B\u3002\u5224\u65AD\u7684\u65B9\u6CD5\u662F\u5148\u770B\u5168\u53E5\u5728\u8BF4\u4EC0\u4E48\uFF08\u4F5C\u8005\u8BF4\u81EA\u5DF1\u4E0D\u7FA1\u6155\u540C\u820D\u751F\u7684\u534E\u670D\u7F8E\u98DF\uFF09\uFF0C\u518D\u636E\u6B64\u63A8\u300C\u53E3\u4F53\u4E4B\u5949\u300D\u7684\u6240\u6307\uFF0C\u800C\u4E0D\u662F\u9010\u5B57\u786C\u51D1\u3002\u5176\u4F59\u4E09\u5904\uFF08\u4EE5\u3001\u8DB3\u4E50\u8005\u3001\u4E0D\u82E5\uFF09\u90FD\u5C5E\u5E38\u89C1\u4E49\u9879\uFF0C\u843D\u5B9E\u5373\u53EF\u3002",
      rubric: [
        "\u300C\u4EE5\u300D\u8BD1\u4E3A\u300C\u56E0\u4E3A\u300D\u3002",
        "\u300C\u53E3\u4F53\u4E4B\u5949\u300D\u8BD1\u4E3A\u300C\u5403\u7684\u7A7F\u7684\uFF08\u4F9B\u517B\uFF09\u300D\uFF0C\u4E0D\u671B\u6587\u751F\u4E49\u3002",
        "\u300C\u4E0D\u82E5\u300D\u8BD1\u4E3A\u300C\u4E0D\u5982\u3001\u6BD4\u4E0D\u4E0A\u300D\u3002",
        "\u5168\u53E5\u901A\u987A\uFF0C\u8865\u8DB3\u300C\uFF08\u8BFB\u4E66\uFF09\u300D\u4E4B\u7C7B\u7701\u7565\u6210\u5206\u3002"
      ],
      difficulty: 2,
      tags: ["\u7FFB\u8BD1", "\u6587\u8A00\u6587\u9605\u8BFB", "\u5B9E\u8BCD"]
