      stem: "\u9605\u8BFB\u4E0B\u9762\u7684\u6587\u8A00\u77ED\u6587\uFF0C\u56DE\u7B54\u95EE\u9898\u3002\n" + WEN_A + "\n\u89E3\u91CA\u53E5\u4E2D\u52A0\u70B9\u8BCD\uFF1A\u300C\u8BF5\u8BFB\u4E4B\u58F0\u8FBE\u65E6\u4E0D\u8F8D\u300D\u7684\u300C\u8F8D\u300D\u610F\u4E3A________\u3002",
