      stem: "\u9605\u8BFB\u4E0B\u9762\u7684\u6587\u8A00\u77ED\u6587\uFF0C\u56DE\u7B54\u95EE\u9898\u3002\n" + WEN_A + "\n\u7FFB\u8BD1\u53E5\u5B50\uFF1A\u53D7\u4EBA\u60E0\u800C\u5FD7\u4E0D\u81EA\u7ACB\uFF0C\u975E\u543E\u6240\u6C42\u4E5F\u3002\n\u8BD1\u6587\uFF1A________",
      answer: "\u63A5\u53D7\u522B\u4EBA\u7684\u6069\u60E0\u5374\u4F7F\u81EA\u5DF1\u7684\u5FD7\u5411\u4E0D\u80FD\u81EA\u7ACB\uFF0C\u8FD9\u4E0D\u662F\u6211\u6240\u8FFD\u6C42\u7684\u3002|\u63A5\u53D7\u522B\u4EBA\u7684\u597D\u5904\u800C\u4E0D\u80FD\u4F7F\u81EA\u5DF1\u7ACB\u5FD7\u81EA\u7ACB\uFF0C\u8FD9\u4E0D\u662F\u6211\u6240\u6C42\u7684\u3002",
      explanation: "\u5148\u5224\u5B9A\u53E5\u5F0F\uFF1A\u300C\u975E\u2026\u2026\u4E5F\u300D\u8868\u5426\u5B9A\u5224\u65AD\uFF0C\u8BD1\u6587\u8981\u5199\u51FA\u300C\u4E0D\u662F\u2026\u2026\u300D\u3002\u518D\u5708\u91C7\u5206\u8BCD\uFF1A\u300C\u60E0\u300D\u662F\u6069\u60E0\u3001\u597D\u5904\uFF1B\u300C\u5FD7\u4E0D\u81EA\u7ACB\u300D\u662F\u300C\u5FD7\u5411\u4E0D\u80FD\u81EA\u7ACB\u300D\uFF1B\u300C\u975E\u300D\u662F\u300C\u4E0D\u662F\u300D\uFF1B\u300C\u543E\u6240\u6C42\u300D\u662F\u300C\u6211\u6240\u8FFD\u6C42\u7684\u300D\u3002\u56DB\u70B9\u843D\u5B9E\u540E\u518D\u901A\u8BFB\uFF0C\u6CE8\u610F\u4E0D\u8981\u6F0F\u6389\u300C\u800C\u300D\u6240\u8868\u7684\u8F6C\u6298\uFF08\u63A5\u53D7\u6069\u60E0\u5374\u4F7F\u5FD7\u5411\u4E0D\u80FD\u81EA\u7ACB\uFF09\uFF0C\u8FD9\u4E00\u8F6C\u6298\u6B63\u662F\u9648\u751F\u62D2\u7EDD\u7684\u7406\u7531\u3002",
      difficulty: 2,
      tags: ["\u8BFE\u5916\u6587\u8A00\u6587\u8FC1\u79FB", "\u6587\u8A00\u6587\u9605\u8BFB", "\u7FFB\u8BD1"]
