      difficulty: 3,
      tags: ["\u8BFE\u5916\u6587\u8A00\u6587\u8FC1\u79FB", "\u6587\u8A00\u6587\u9605\u8BFB", "\u4EBA\u7269\u5F62\u8C61"]
