      stem: "\u9605\u8BFB\u4E0B\u9762\u7684\u6587\u8A00\u77ED\u6587\uFF0C\u56DE\u7B54\u95EE\u9898\u3002\n" + WEN_B + "\n\u7528\u300C/\u300D\u7ED9\u4E0B\u9762\u53E5\u5B50\u65AD\u53E5\uFF1A\n\u541B\u60AF\u5176\u60C5\u800C\u4E0D\u5E9F\u5176\u6CD5\u4EE4\u5176\u4F63\u4F5C\u4EE5\u507F\u590D\u6212\u4E4B\u66F0\u6CD5\u4E0D\u53EF\u72AF\u5B5D\u4EA6\u5F53\u5168",
      answer: "\u541B\u60AF\u5176\u60C5\u800C\u4E0D\u5E9F\u5176\u6CD5/\u4EE4\u5176\u4F63\u4F5C\u4EE5\u507F/\u590D\u6212\u4E4B\u66F0/\u6CD5\u4E0D\u53EF\u72AF/\u5B5D\u4EA6\u5F53\u5168",
      explanation: "\u5148\u7406\u4E8B\u4EF6\uFF1A\u8D75\u541B\u540C\u60C5\u5C11\u5E74\u7684\u5904\u5883\u5374\u4E0D\u5E9F\u5F03\u6CD5\u4EE4\uFF0C\u8BA9\u4ED6\u505A\u5DE5\u62B5\u507F\uFF0C\u53C8\u544A\u8BEB\u4ED6\u6CD5\u4EE4\u4E0D\u53EF\u8FDD\u72AF\u3001\u5B5D\u9053\u4E5F\u5E94\u5F53\u6210\u5168\u3002\u65AD\u53E5\u770B\u56DB\u5904\uFF1A\u300C\u541B\u60AF\u5176\u60C5\u800C\u4E0D\u5E9F\u5176\u6CD5\u300D\u662F\u4E00\u4E2A\u5B8C\u6574\u53E5\u5B50\uFF0C\u300C\u800C\u300D\u8FDE\u63A5\u7684\u4E24\u9879\u5728\u540C\u4E00\u5206\u53E5\u4E4B\u5185\uFF0C\u4E0D\u5728\u5B83\u524D\u540E\u65AD\uFF1B\u300C\u4EE4\u5176\u4F63\u4F5C\u4EE5\u507F\u300D\u662F\u53E6\u4E00\u4EF6\u4E8B\uFF0C\u4E0E\u4E0A\u53E5\u5E76\u5217\uFF1B\u300C\u590D\u6212\u4E4B\u66F0\u300D\u4E2D\u300C\u66F0\u300D\u5F15\u51FA\u5F15\u8BED\uFF0C\u5FC5\u987B\u65AD\u5728\u5B83\u540E\u9762\uFF1B\u5F15\u8BED\u5185\u90E8\u300C\u6CD5\u4E0D\u53EF\u72AF\u300D\u4E0E\u300C\u5B5D\u4EA6\u5F53\u5168\u300D\u662F\u5E76\u5217\u7684\u4E24\u53E5\uFF0C\u5404\u81EA\u72EC\u7ACB\u3002\u56DE\u8BFB\u4E00\u904D\uFF0C\u4E94\u6BB5\u90FD\u80FD\u8BB2\u6210\u610F\u601D\uFF0C\u65AD\u53E5\u6210\u7ACB\u3002",
