      stem: "\u300C\u6CB3\u66F2\u667A\u53DF\u7B11\u800C\u6B62\u4E4B\u66F0\uFF1A\u300E\u751A\u77E3\uFF0C\u6C5D\u4E4B\u4E0D\u60E0\uFF01\u300F\u300D\uFF08\u300A\u611A\u516C\u79FB\u5C71\u300B\uFF09\u53E5\u4E2D\u300C\u800C\u300D\u8FDE\u63A5\u300C\u7B11\u300D\u4E0E\u300C\u6B62\u4E4B\u300D\u4E24\u9879\uFF0C\u524D\u4E00\u9879\u8BF4\u660E\u540E\u4E00\u9879\u7684\u65B9\u5F0F\uFF0C\u5B83\u8868\u793A\u7684\u5173\u7CFB\u662F________\uFF08\u586B\u300C\u987A\u627F\u300D\u300C\u8F6C\u6298\u300D\u6216\u300C\u4FEE\u9970\u300D\uFF09\u3002",
      answer: "\u4FEE\u9970|\u4FEE\u9970\u5173\u7CFB|\u8868\u4FEE\u9970",
      explanation: "\u5224\u65AD\u300C\u800C\u300D\u53EA\u95EE\u4E00\u53E5\uFF1A\u524D\u540E\u4E24\u9879\u662F\u4EC0\u4E48\u5173\u7CFB\u3002\u300C\u7B11\u300D\u4E0E\u300C\u6B62\u4E4B\u300D\u4E0D\u662F\u5148\u540E\u76F8\u627F\u7684\u4E24\u4EF6\u4E8B\uFF08\u4E0D\u662F\u5148\u7B11\u5B8C\u518D\u963B\u6B62\uFF09\uFF0C\u4E5F\u4E0D\u662F\u76F8\u53CD\u7684\u4E24\u9762\uFF08\u4E0D\u662F\u300C\u7B11\u5374\u4E0D\u963B\u6B62\u300D\uFF09\uFF0C\u800C\u662F\u300C\u7B11\u7740\u963B\u6B62\u4ED6\u300D\u2014\u2014\u524D\u9879\u8BF4\u660E\u540E\u9879\u7684\u65B9\u5F0F\u3001\u72B6\u6001\uFF0C\u5C5E\u8868\u4FEE\u9970\u3002\u4E09\u7C7B\u5173\u7CFB\u7684\u5206\u754C\u7531\u6B64\u56FA\u5B9A\uFF1A\u76F8\u53CD\u76F8\u5BF9\u662F\u8F6C\u6298\uFF0C\u5148\u540E\u76F8\u627F\u662F\u987A\u627F\uFF0C\u524D\u9879\u4FEE\u9970\u540E\u9879\u662F\u4FEE\u9970\u3002\u628A\u300C\u7B11\u800C\u6B62\u4E4B\u300D\u8BD1\u6210\u300C\u7B11\u7740\u963B\u6B62\u4ED6\u300D\uFF0C\u8BD1\u6587\u672C\u8EAB\u5C31\u628A\u4FEE\u9970\u5173\u7CFB\u8BF4\u6E05\u695A\u4E86\u3002",
