      answer: "\u5148\u662F\u57CB\u6028\u660E\u6708\u504F\u5728\u79BB\u522B\u65F6\u56E2\u5706\uFF0C\u6D41\u9732\u51FA\u4E0D\u80FD\u4E0E\u4EB2\u4EBA\u56E2\u805A\u7684\u60C6\u6005\u4E0E\u6028\u610F\uFF1B\u7EE7\u800C\u609F\u51FA\u4EBA\u6709\u60B2\u6B22\u79BB\u5408\u3001\u6708\u6709\u9634\u6674\u5706\u7F3A\u90FD\u662F\u81EA\u53E4\u96BE\u5168\u7684\u5E38\u7406\uFF0C\u8F6C\u4E3A\u81EA\u6211\u5BBD\u6170\u3001\u65F7\u8FBE\u81EA\u89E3\uFF1B\u6700\u540E\u4EE5\u300C\u4F46\u613F\u4EBA\u957F\u4E45\uFF0C\u5343\u91CC\u5171\u5A75\u5A1F\u300D\u8868\u8FBE\u5BF9\u4EB2\u4EBA\u7684\u7F8E\u597D\u795D\u613F\uFF0C\u7531\u4E2A\u4EBA\u7684\u79BB\u6101\u5347\u534E\u4E3A\u5BF9\u5929\u4E0B\u79BB\u4EBA\u7684\u795D\u798F\uFF0C\u60C5\u611F\u53D8\u5F97\u4E50\u89C2\u8C41\u8FBE\u3002",
