        "\u82CF\u8F7C\u53E5\uFF1A\u5BC4\u6258\u5BF9\u4EB2\u4EBA\u7684\u7F8E\u597D\u795D\u613F\u4E0E\u65F7\u8FBE\u80F8\u895F\u3002",
        "\u4E24\u5904\u90FD\u70B9\u5230\uFF0C\u5E76\u6307\u51FA\u60C5\u611F\u6027\u8D28\u7684\u5DEE\u5F02\uFF08\u5173\u5207\u4E0D\u5E73 vs \u795D\u613F\u65F7\u8FBE\uFF09\u3002",
