        "\u300C\u5B50\u89C4\u300D\u5373\u675C\u9E43\uFF0C\u557C\u58F0\u54C0\u5207\uFF0C\u53E4\u4EBA\u5E38\u501F\u4EE5\u5199\u60B2\u82E6\uFF0C\u6B64\u5904\u4E3A\u5168\u8BD7\u6E32\u67D3\u4E86\u54C0\u6101\u7684\u6C1B\u56F4\u3002",
        "\u4E24\u4E2A\u610F\u8C61\u90FD\u5E26\u98D8\u96F6\u3001\u60B2\u5207\u7684\u8272\u5F69\uFF0C\u4E00\u5F00\u7BC7\u5C31\u4E3A\u5168\u8BD7\u5B9A\u4E0B\u4E86\u4F24\u611F\u7684\u57FA\u8C03\u3002",
