var TEXT_A = "\u6211\u5BB6\u7684\u8001\u6728\u67DC\u662F\u7236\u4EB2\u6253\u7684\uFF0C\u67DC\u95E8\u4E0A\u6CA1\u6709\u4E00\u9897\u9489\u5B50\u3002\n\u90A3\u5E74\u6211\u516B\u5C81\uFF0C\u8E72\u5728\u9662\u5B50\u91CC\u770B\u4ED6\u5E72\u6D3B\u3002\u7236\u4EB2\u628A\u4E00\u5757\u6728\u677F\u7ACB\u8D77\u6765\uFF0C\u772F\u8D77\u5DE6\u773C\uFF0C\u987A\u7740\u6728\u7EB9\u7684\u65B9\u5411\u770B\u8FC7\u53BB\uFF0C\u50CF\u5728\u7AEF\u8BE6\u4E00\u4E2A\u719F\u4EBA\u7684\u8138\u3002\u4ED6\u4E0D\u7528\u5C3A\u5B50\u91CF\uFF0C\u53EA\u7528\u94C5\u7B14\u5728\u6728\u5934\u4E0A\u8F7B\u8F7B\u5212\u7EBF\uFF0C\u7EBF\u7EC6\u5F97\u50CF\u4E00\u6839\u5934\u53D1\u3002\u952F\u5B50\u62C9\u8D77\u6765\u6C99\u6C99\u5730\u54CD\uFF0C\u6728\u5C51\u843D\u5728\u4ED6\u7684\u978B\u9762\u4E0A\uFF0C\u5806\u6210\u8584\u8584\u4E00\u5C42\uFF0C\u4ED6\u4E5F\u4E0D\u6296\u3002\n\u300C\u6728\u5934\u662F\u6709\u813E\u6C14\u7684\u3002\u300D\u7236\u4EB2\u8BF4\uFF0C\u300C\u987A\u7740\u5B83\uFF0C\u5B83\u5C31\u542C\u4F60\u7684\uFF1B\u62E7\u7740\u5B83\uFF0C\u5B83\u5C31\u88C2\u7ED9\u4F60\u770B\u3002\u300D\n\u4ED6\u51FF\u69AB\u773C\u7684\u65F6\u5019\u6700\u5B89\u9759\u3002\u51FF\u5B50\u4E00\u4E0B\u4E00\u4E0B\u5F80\u4E0B\u8D70\uFF0C\u6728\u5C51\u4E00\u5C0F\u5377\u4E00\u5C0F\u5377\u5730\u5192\u51FA\u6765\uFF0C\u5377\u7740\uFF0C\u50CF\u4E00\u4E2A\u4E2A\u4E0D\u80AF\u6563\u5F00\u7684\u5C0F\u95EE\u53F7\u3002\u4ED6\u5F88\u5C11\u8BF4\u8BDD\uFF0C\u53EA\u5728\u6BCF\u4E00\u6B21\u843D\u9524\u4E4B\u524D\u628A\u51FF\u5B50\u6276\u6B63\uFF0C\u518D\u7528\u638C\u5FC3\u8F7B\u8F7B\u6309\u4E00\u6309\uFF0C\u50CF\u662F\u5728\u8DDF\u90A3\u5757\u6728\u5934\u5546\u91CF\u3002\n\u67DC\u5B50\u505A\u597D\u90A3\u5929\uFF0C\u6211\u4F38\u624B\u53BB\u63A8\u67DC\u95E8\uFF0C\u95E8\u8F74\u8F6C\u5F97\u5F88\u8F7B\uFF0C\u51E0\u4E4E\u6CA1\u6709\u58F0\u97F3\u3002\u6211\u95EE\u7236\u4EB2\u4E3A\u4EC0\u4E48\u4E0D\u7528\u9489\u5B50\uFF0C\u4ED6\u8E72\u4E0B\u6765\uFF0C\u628A\u67DC\u95E8\u5378\u4E0B\uFF0C\u6307\u7740\u91CC\u9762\u8BF4\uFF1A\u300C\u9489\u5B50\u4F1A\u9508\uFF0C\u9508\u4E86\u5C31\u677E\uFF1B\u69AB\u536F\u4E0D\u4E00\u6837\uFF0C\u6728\u5934\u8D8A\u5E72\uFF0C\u5B83\u54AC\u5F97\u8D8A\u7D27\u3002\u300D\n\u540E\u6765\u6211\u53BB\u5916\u5730\u8BFB\u4E66\uFF0C\u90A3\u53EA\u67DC\u5B50\u8FD8\u5728\u8001\u5C4B\u7684\u5899\u89D2\u7ACB\u7740\u3002\u5357\u65B9\u7684\u6885\u96E8\u5929\u4E00\u6765\uFF0C\u5C4B\u91CC\u7684\u5899\u76AE\u90FD\u8D77\u4E86\u6CE1\uFF0C\u67DC\u95E8\u5374\u4ECD\u65E7\u5408\u5F97\u4E25\u4E1D\u5408\u7F1D\u3002\u6709\u4E00\u5E74\u51AC\u5929\u6211\u56DE\u5BB6\uFF0C\u770B\u89C1\u7236\u4EB2\u6234\u7740\u8001\u82B1\u955C\uFF0C\u6B63\u62FF\u7740\u5C0F\u6728\u9524\uFF0C\u8F7B\u8F7B\u6572\u6253\u67DC\u95E8\u8FB9\u7684\u63A5\u7F1D\u3002\u4ED6\u8BF4\uFF0C\u5929\u592A\u5E72\u4E86\uFF0C\u6728\u5934\u7F29\u4E86\uFF0C\u5F97\u8BA9\u5B83\u91CD\u65B0\u54AC\u7D27\u3002\n\u4ED6\u62AC\u5934\u770B\u6211\uFF0C\u7B11\u4E86\u4E00\u4E0B\uFF1A\u300C\u4E1C\u897F\u8DDF\u4EBA\u4E00\u6837\uFF0C\u677E\u4E86\u5C31\u7D27\u4E00\u7D27\uFF0C\u522B\u6025\u7740\u6362\u3002\u300D\n\u5982\u4ECA\u7236\u4EB2\u7684\u624B\u6709\u4E9B\u6296\u4E86\uFF0C\u952F\u5B50\u6302\u5728\u5899\u4E0A\uFF0C\u9508\u8FF9\u722C\u4E0A\u4E86\u952F\u6761\u3002\u6211\u6253\u5F00\u90A3\u53EA\u67DC\u95E8\uFF0C\u91CC\u9762\u8FD8\u7559\u7740\u6DE1\u6DE1\u7684\u6728\u9999\u2014\u2014\u90A3\u662F\u5F88\u591A\u5E74\u524D\uFF0C\u4E00\u4E2A\u590F\u5929\u7684\u5348\u540E\uFF0C\u7236\u4EB2\u51FF\u4E0B\u7684\u7B2C\u4E00\u5200\u7559\u4E0B\u7684\u3002";
var TEXT_B = "\u5916\u5A46\u5BB6\u9662\u5899\u5916\u6709\u4E00\u68F5\u6787\u6777\u6811\uFF0C\u6BD4\u6211\u5E74\u7EAA\u8FD8\u5927\u3002\n\u6BCF\u5E74\u4E94\u6708\u5E95\uFF0C\u6787\u6777\u5C31\u9EC4\u4E86\u3002\u9EC4\u5F97\u4E0D\u6025\uFF0C\u5148\u662F\u6700\u4F4E\u5904\u7684\u51E0\u9897\uFF0C\u9752\u91CC\u900F\u51FA\u4E00\u70B9\u6DE1\u9EC4\uFF0C\u50CF\u5C0F\u5B69\u7B2C\u4E00\u6B21\u7B11\u65F6\u9732\u51FA\u7684\u4E00\u70B9\u7259\uFF1B\u8FC7\u4E0A\u56DB\u4E94\u5929\uFF0C\u4E2D\u95F4\u90A3\u4E00\u5C42\u4E5F\u8DDF\u4E0A\u6765\u4E86\uFF1B\u6700\u540E\u624D\u8F6E\u5230\u6811\u9876\uFF0C\u90A3\u513F\u7684\u679C\u5B50\u88AB\u592A\u9633\u6652\u5F97\u6700\u4E45\uFF0C\u9EC4\u5F97\u6700\u6D53\uFF0C\u4E5F\u6700\u751C\u3002\n\u5916\u5A46\u6709\u4E00\u6839\u957F\u957F\u7684\u7AF9\u94A9\uFF0C\u5934\u4E0A\u5F2F\u6210\u4E00\u4E2A\u5C0F\u94A9\u5B50\u3002\u5979\u7AD9\u5728\u6811\u4E0B\uFF0C\u4EF0\u7740\u5934\uFF0C\u7AF9\u94A9\u4E00\u4F38\u4E00\u6536\uFF0C\u6787\u6777\u5C31\u4E00\u9897\u4E00\u9897\u843D\u8FDB\u5979\u630E\u7740\u7684\u7AF9\u7BEE\u91CC\uFF0C\u8F7B\u5F97\u50CF\u843D\u4E86\u4E00\u9635\u9EC4\u96E8\u3002\u6811\u9876\u7684\u90A3\u4E9B\u5979\u4ECE\u6765\u591F\u4E0D\u7740\uFF0C\u4E5F\u4ECE\u6765\u4E0D\u52C9\u5F3A\u3002\u300C\u7559\u7ED9\u96C0\u513F\u3002\u300D\u5979\u8BF4\uFF0C\u300C\u5B83\u4EEC\u6BD4\u6211\u8D77\u5F97\u65E9\u3002\u300D\n\u6211\u5C0F\u65F6\u5019\u8D2A\u5403\uFF0C\u5E38\u5E38\u7B49\u4E0D\u5230\u6D17\u51C0\u5C31\u5F80\u5634\u91CC\u585E\uFF0C\u628A\u5634\u89D2\u5F04\u5F97\u9EC4\u9EC4\u7684\u3002\u5916\u5A46\u770B\u89C1\u4E0D\u9A82\uFF0C\u53EA\u9012\u8FC7\u4E00\u5757\u624B\u5DFE\uFF0C\u8BF4\uFF1A\u300C\u6162\u4E9B\uFF0C\u679C\u5B50\u4E0D\u8DD1\u3002\u300D\n\u6211\u4E0A\u521D\u4E2D\u540E\u4F4F\u6821\uFF0C\u4E00\u5E74\u53EA\u80FD\u56DE\u53BB\u4E24\u4E09\u8D9F\u3002\u6709\u4E00\u5E74\u4E94\u6708\uFF0C\u6211\u6253\u7535\u8BDD\u8BF4\u60F3\u5403\u6787\u6777\uFF0C\u5916\u5A46\u5728\u7535\u8BDD\u90A3\u5934\u505C\u4E86\u4E00\u4E0B\uFF0C\u8BF4\uFF1A\u300C\u6811\u4ECA\u5E74\u7ED3\u5F97\u5C11\uFF0C\u6211\u7ED9\u4F60\u7559\u7740\u3002\u300D\n\u7B49\u6211\u56DE\u5230\u5BB6\uFF0C\u684C\u4E0A\u679C\u7136\u6446\u7740\u4E00\u5C0F\u7897\u6787\u6777\uFF0C\u4E2A\u4E2A\u9971\u6EE1\uFF0C\u8FDE\u989C\u8272\u90FD\u5300\u51C0\uFF0C\u663E\u7136\u662F\u6311\u8FC7\u7684\u3002\u6211\u5265\u5F00\u4E00\u9897\uFF0C\u5FFD\u7136\u53D1\u73B0\u7897\u5E95\u538B\u7740\u4E00\u5F20\u65E7\u62A5\u7EB8\uFF0C\u62A5\u7EB8\u4E0A\u7684\u65E5\u671F\u662F\u4E00\u4E2A\u6708\u524D\u3002\n\u6211\u95EE\u5916\u5A46\uFF1A\u300C\u600E\u4E48\u653E\u8FD9\u4E48\u4E45\uFF1F\u300D\u5979\u5750\u5728\u7AF9\u6905\u4E0A\uFF0C\u6447\u7740\u84B2\u6247\uFF0C\u6162\u60A0\u60A0\u5730\u8BF4\uFF1A\u300C\u6311\u51FA\u6765\u7684\uFF0C\u653E\u9634\u51C9\u5904\uFF0C\u80FD\u5B58\u3002\u4F60\u8981\u662F\u518D\u665A\u51E0\u5929\u56DE\u6765\uFF0C\u6211\u5C31\u53EA\u80FD\u81EA\u5DF1\u5403\u4E86\u3002\u300D\n\u5979\u7B11\u5F97\u773C\u775B\u90FD\u772F\u8D77\u6765\uFF0C\u50CF\u90A3\u68F5\u6811\u9876\u4E0A\u7684\u6787\u6777\uFF0C\u9EC4\u5F97\u53D1\u4EAE\u3002\u90A3\u4E00\u5E74\uFF0C\u6211\u7B2C\u4E00\u6B21\u53D1\u73B0\uFF0C\u5916\u5A46\u7684\u767D\u5934\u53D1\u6BD4\u6787\u6777\u82B1\u5F00\u5F97\u8FD8\u6EE1\u3002\n\u5982\u4ECA\u5916\u5A46\u4E0D\u5728\u4E86\uFF0C\u6787\u6777\u6811\u8FD8\u5E74\u5E74\u9EC4\u3002\u6811\u9876\u7684\u90A3\u4E9B\u679C\u5B50\uFF0C\u59CB\u7EC8\u6CA1\u6709\u8C01\u6765\u6458\u3002\u98CE\u4E00\u8FC7\uFF0C\u5C31\u843D\u8FDB\u8349\u91CC\uFF0C\u53D1\u51FA\u5F88\u8F7B\u7684\u4E00\u58F0\u3002\u6211\u6709\u65F6\u7AD9\u5728\u6811\u4E0B\u60F3\uFF1A\u6709\u4E9B\u751C\uFF0C\u662F\u4E13\u95E8\u7559\u7740\u7ED9\u522B\u4EBA\u7684\uFF0C\u7559\u7684\u4EBA\u81EA\u5DF1\u672A\u5FC5\u5C1D\u5F97\u5230\u3002";
var TEXT_C = "\u51AC\u5929\uFF0C\u4FDD\u62A4\u533A\u7684\u6C34\u9762\u7ED3\u4E86\u4E00\u5C42\u8584\u51B0\u3002\u5DE1\u62A4\u5458\u8001\u5468\u628A\u8239\u6491\u8FDB\u82A6\u82C7\u8361\u7684\u65F6\u5019\uFF0C\u5929\u8FD8\u6CA1\u4EAE\u900F\u3002\n\u4E39\u9876\u9E64\u7AD9\u5728\u6D45\u6C34\u91CC\uFF0C\u4E00\u53EA\u811A\u6536\u8FDB\u7FBD\u6BDB\u91CC\uFF0C\u53E6\u4E00\u53EA\u811A\u8E29\u5728\u51B0\u78B4\u4E0A\uFF0C\u4E00\u52A8\u4E0D\u52A8\uFF0C\u50CF\u4E00\u6839\u63D2\u5728\u7070\u767D\u6C34\u9762\u4E0A\u7684\u7EA2\u7B14\u5C16\u3002\u8001\u5468\u7184\u4E86\u9A6C\u8FBE\uFF0C\u4EFB\u8239\u6162\u6162\u6F02\u8FC7\u53BB\u2014\u2014\u4ED6\u4E0D\u6562\u9760\u5F97\u592A\u8FD1\uFF0C\u4E5F\u4E0D\u6562\u5F04\u51FA\u592A\u54CD\u7684\u52A8\u9759\u3002\u9E64\u542C\u89C1\u6C34\u58F0\uFF0C\u504F\u4E86\u504F\u5934\uFF0C\u6CA1\u6709\u98DE\u3002\n\u300C\u5B83\u8BA4\u5F97\u6211\u3002\u300D\u8001\u5468\u540E\u6765\u5BF9\u6211\u8BF4\u3002\u4ED6\u5728\u8FD9\u7247\u6EE9\u6D82\u4E0A\u5B88\u4E86\u5341\u4E5D\u5E74\uFF0C\u8BA4\u5F97\u6BCF\u4E00\u5DE2\u9E64\uFF0C\u4E5F\u8BA4\u5F97\u6BCF\u4E00\u7247\u88AB\u98CE\u538B\u5F2F\u7684\u82A6\u82C7\u3002\n\u5341\u51E0\u5E74\u524D\uFF0C\u8FD9\u91CC\u8FD8\u4E0D\u662F\u8FD9\u6837\u3002\u8001\u5468\u8BF4\uFF0C\u90A3\u65F6\u5019\u6709\u4EBA\u4E0B\u7F51\u6355\u9C7C\uFF0C\u4E5F\u6709\u4EBA\u6361\u9E64\u86CB\u3002\u6709\u4E00\u5E74\u6625\u5929\uFF0C\u4E00\u7247\u6EE9\u6D82\u4E0A\u4E00\u7A9D\u86CB\u53EA\u5269\u4E0B\u788E\u7684\u58F3\u3002\u4ECE\u90A3\u4EE5\u540E\uFF0C\u4ED6\u548C\u51E0\u4E2A\u4F19\u4F34\u6BCF\u5929\u5929\u4E0D\u4EAE\u5C31\u6765\uFF0C\u51AC\u5929\u5582\u98DF\uFF0C\u6625\u5929\u770B\u5DE2\uFF0C\u590F\u5929\u5B88\u6C34\u3002\u6BCF\u5E74\u8865\u79CD\u82A6\u82C7\uFF0C\u4E00\u5E74\u4E00\u5E74\u8865\uFF0C\u6EE9\u6D82\u624D\u6162\u6162\u7EFF\u56DE\u6765\u3002\n\u300C\u4E3A\u4EC0\u4E48\u4E0D\u628A\u5B83\u4EEC\u56F4\u8D77\u6765\uFF0C\u770B\u5F97\u66F4\u7262\uFF1F\u300D\u6211\u95EE\u3002\n\u8001\u5468\u6447\u5934\uFF1A\u300C\u56F4\u8D77\u6765\uFF0C\u5B83\u5C31\u6210\u5BB6\u79BD\u4E86\u3002\u300D\n\u8FD9\u51E0\u5E74\uFF0C\u8D8A\u51AC\u7684\u9E64\u7FA4\u4ECE\u51E0\u5341\u53EA\u6DA8\u5230\u4E86\u4E24\u767E\u591A\u53EA\u3002\u5E74\u5E95\u7EDF\u8BA1\u7684\u65F6\u5019\uFF0C\u6280\u672F\u5458\u5728\u7EB8\u4E0A\u753B\u4E0B\u4E00\u4E32\u6570\u5B57\uFF0C\u8001\u5468\u7AD9\u5728\u65C1\u8FB9\u770B\uFF0C\u4EC0\u4E48\u4E5F\u6CA1\u8BF4\uFF0C\u53EA\u662F\u628A\u51BB\u50F5\u7684\u624B\u5728\u8896\u53E3\u91CC\u6413\u4E86\u6413\u3002\n\u65E5\u5934\u51FA\u6765\u7684\u65F6\u5019\uFF0C\u9E64\u6296\u4E86\u6296\u7FC5\u8180\uFF0C\u8D70\u4E0A\u5CB8\uFF0C\u6162\u541E\u541E\u5730\u5544\u98DF\u3002\u8001\u5468\u8E72\u4E0B\u6765\uFF0C\u6293\u4E86\u4E00\u628A\u7389\u7C73\u6492\u5728\u51B0\u9762\u4E0A\u3002\u7389\u7C73\u7C92\u6EDA\u4E86\u4E00\u5730\uFF0C\u9E64\u4F4E\u5934\u5544\u98DF\uFF0C\u8116\u9888\u5F2F\u6210\u4E00\u9053\u67D4\u548C\u7684\u5F27\u3002\n\u8239\u5F80\u56DE\u8D70\u65F6\uFF0C\u82A6\u82C7\u4E1B\u91CC\u5FFD\u7136\u8D77\u4E86\u4E00\u9635\u54CD\u52A8\u2014\u2014\u90A3\u662F\u98CE\u5439\u8FC7\u6210\u5343\u4E0A\u4E07\u7247\u53F6\u5B50\u7684\u58F0\u97F3\uFF0C\u50CF\u6709\u4EBA\u5728\u6C34\u8FB9\u6084\u6084\u7FFB\u7740\u4E00\u672C\u4E66\u3002\u8001\u5468\u5173\u4E86\u9A6C\u8FBE\uFF0C\u5750\u5728\u8239\u5934\uFF0C\u542C\u3002";
var TEXT_D = "\u4E03\u6708\u7684\u6652\u8C37\u573A\u662F\u4E00\u4E2A\u88AB\u592A\u9633\u70E4\u900F\u7684\u5706\u3002\n\u7A3B\u5B50\u6536\u4E0B\u6765\uFF0C\u644A\u5728\u573A\u4E0A\uFF0C\u7528\u6728\u8019\u63A8\u6210\u4E00\u9053\u9053\u6D45\u6D45\u7684\u6C9F\u3002\u7237\u7237\u8BF4\uFF0C\u8FD9\u6837\u7FFB\u7740\u6652\uFF0C\u8C37\u5B50\u624D\u5E72\u5F97\u5300\u3002\u4ED6\u6234\u7740\u8349\u5E3D\uFF0C\u5149\u7740\u7684\u811A\u80CC\u4E0A\u6709\u4E00\u5C42\u8584\u8584\u7684\u9ED1\uFF0C\u662F\u591A\u5E74\u6652\u51FA\u6765\u7684\u989C\u8272\u3002\u4ED6\u5F2F\u8170\u7684\u65F6\u5019\uFF0C\u7A3B\u8C37\u7684\u6C14\u606F\u5C31\u4ECE\u4ED6\u7684\u8863\u8896\u91CC\u6563\u51FA\u6765\uFF0C\u53C8\u5E72\u53C8\u9999\u3002\n\u4E2D\u5348\u662F\u6700\u96BE\u71AC\u7684\u65F6\u5019\u3002\u67CF\u6CB9\u4E00\u6837\u70EB\u7684\u5730\u9762\uFF0C\u9694\u7740\u978B\u5E95\u90FD\u80FD\u611F\u89C9\u5230\u70ED\u5EA6\u3002\u98CE\u662F\u541D\u556C\u7684\uFF0C\u5076\u5C14\u6765\u4E00\u9635\uFF0C\u53EA\u6380\u52A8\u8C37\u5806\u6700\u4E0A\u9762\u7684\u4E00\u5C42\uFF0C\u6380\u8D77\u4E00\u5C0F\u7247\u91D1\u8272\u7684\u6D6A\uFF0C\u7ACB\u523B\u53C8\u5E73\u4E86\u3002\n\u6211\u5750\u5728\u573A\u8FB9\u7684\u8349\u579B\u91CC\uFF0C\u6367\u7740\u4E00\u672C\u7FFB\u4E86\u89D2\u7684\u4E66\u3002\u7237\u7237\u8D70\u8FC7\u6765\uFF0C\u5F80\u6211\u8EAB\u8FB9\u7684\u8C37\u5806\u4E0A\u63D2\u4E86\u4E00\u9876\u8349\u5E3D\uFF0C\u8BF4\uFF1A\u300C\u770B\u4E66\u4E5F\u5F97\u8EB2\u7740\u70B9\u592A\u9633\u3002\u300D\u4ED6\u8BF4\u8BDD\u7684\u58F0\u97F3\u5F88\u4F4E\uFF0C\u50CF\u6015\u5435\u9192\u4EC0\u4E48\u3002\n\u508D\u665A\uFF0C\u5929\u8FB9\u5F00\u59CB\u5806\u4E91\u3002\u7237\u7237\u62AC\u5934\u770B\u4E86\u5F88\u4E45\uFF0C\u5FFD\u7136\u8BF4\uFF1A\u300C\u6536\u8C37\u3002\u300D\u6211\u8FD8\u6CA1\u53CD\u5E94\u8FC7\u6765\uFF0C\u4ED6\u5DF2\u7ECF\u628A\u8019\u5B50\u63A8\u8D77\u6765\uFF0C\u8C37\u5B50\u5728\u8019\u9F7F\u4E0B\u54D7\u54D7\u5730\u54CD\u3002\u98CE\u8D8A\u6765\u8D8A\u6025\uFF0C\u4E91\u4E5F\u538B\u5F97\u8D8A\u6765\u8D8A\u4F4E\u3002\u90BB\u5C45\u4EEC\u4E5F\u6765\u4E86\uFF0C\u4E00\u53E5\u8BDD\u90FD\u4E0D\u591A\u8BF4\uFF0C\u5404\u81EA\u627E\u4E00\u4EF6\u5BB6\u4F19\uFF0C\u6709\u7684\u63A8\uFF0C\u6709\u7684\u626B\uFF0C\u6709\u7684\u88C5\u3002\u573A\u4E0A\u7684\u4EBA\u5F71\u5728\u66AE\u8272\u91CC\u6765\u56DE\u6643\u52A8\uFF0C\u8C01\u4E5F\u6CA1\u6709\u505C\u4E0B\u6765\u6B47\u4E00\u6B47\u3002\n\u96E8\u70B9\u843D\u4E0B\u6765\u7684\u65F6\u5019\uFF0C\u6700\u540E\u4E00\u7B50\u8C37\u5B50\u521A\u8FDB\u4ED3\u3002\u7237\u7237\u9760\u5728\u95E8\u6846\u4E0A\u5598\u6C14\uFF0C\u8349\u5E3D\u6B6A\u5728\u8111\u540E\uFF0C\u8138\u4E0A\u5168\u662F\u6C57\uFF0C\u53EF\u4ED6\u7B11\u5F97\u50CF\u4E2A\u5B69\u5B50\uFF1A\u300C\u62A2\u56DE\u6765\u4E86\u3002\u300D\n\u90A3\u5929\u591C\u91CC\uFF0C\u96E8\u4E00\u76F4\u4E0B\u3002\u6211\u8EBA\u5728\u7AF9\u5E8A\u4E0A\u542C\u96E8\uFF0C\u5FFD\u7136\u60F3\u8D77\u4E2D\u5348\u90A3\u4E00\u9635\u541D\u556C\u7684\u98CE\uFF0C\u548C\u508D\u665A\u90A3\u4E00\u9635\u6025\u5207\u7684\u98CE\uFF0C\u539F\u6765\u5B83\u4EEC\u90FD\u662F\u5E84\u7A3C\u4EBA\u7684\u65F6\u95F4\u8868\u3002\u4EBA\u8981\u8DDF\u7740\u98CE\u8D70\uFF0C\u624D\u4E0D\u81F3\u4E8E\u628A\u4E00\u5E74\u6536\u6210\u4E22\u5728\u5929\u4E0A\u3002\n\u518D\u957F\u5927\u4E00\u4E9B\uFF0C\u6211\u79BB\u5BB6\u8BFB\u4E66\u3002\u6BCF\u9022\u4E0B\u96E8\uFF0C\u6211\u603B\u4F1A\u60F3\u8D77\u90A3\u4E2A\u508D\u665A\uFF1A\u573A\u4E0A\u7684\u4EBA\u4E00\u53E5\u8BDD\u4E5F\u4E0D\u8BF4\uFF0C\u5374\u628A\u529B\u6C14\u5F80\u540C\u4E00\u4E2A\u65B9\u5411\u4F7F\u3002\u90A3\u79CD\u9ED8\u5951\uFF0C\u6BD4\u4EFB\u4F55\u53E3\u53F7\u90FD\u6709\u529B\u3002";
var SEG_1 = "\u96EA\u662F\u591C\u91CC\u843D\u7684\u3002\u5929\u4EAE\u65F6\u63A8\u5F00\u9662\u95E8\uFF0C\u5730\u4E0A\u5DF2\u7ECF\u94FA\u4E86\u539A\u539A\u7684\u4E00\u5C42\u3002\u6A90\u4E0B\u7684\u51B0\u51CC\u4E00\u6839\u4E00\u6839\u5782\u7740\uFF0C\u4EAE\u6676\u6676\u7684\uFF0C\u98CE\u4E00\u5439\uFF0C\u4FBF\u8F7B\u8F7B\u78B0\u5728\u4E00\u8D77\uFF0C\u53D1\u51FA\u53EE\u53EE\u7684\u7EC6\u54CD\u3002\u8FDC\u5904\u7684\u5C4B\u9876\u90FD\u77EE\u4E86\u4E0B\u53BB\uFF0C\u708A\u70DF\u4ECE\u96EA\u767D\u91CC\u6162\u6162\u5347\u8D77\u6765\uFF0C\u6DE1\u6DE1\u7684\uFF0C\u50CF\u8C01\u7528\u94C5\u7B14\u8F7B\u8F7B\u753B\u4E86\u4E00\u7B14\u3002";
var SEG_2 = "\u4ED6\u628A\u4E66\u585E\u8FDB\u4E66\u5305\uFF0C\u62C9\u4E0A\u62C9\u94FE\uFF0C\u6284\u8D77\u6C34\u676F\uFF0C\u51B2\u51FA\u95E8\u53BB\u3002\u697C\u9053\u91CC\u4F20\u6765\u549A\u549A\u7684\u811A\u6B65\u58F0\uFF0C\u4E00\u7EA7\u4E00\u7EA7\u5F80\u4E0B\u8DF3\u3002\u5230\u4E86\u697C\u4E0B\uFF0C\u4ED6\u624D\u53D1\u73B0\u978B\u5E26\u677E\u4E86\uFF0C\u4FBF\u8E72\u4E0B\u6765\u7CFB\uFF0C\u7CFB\u5B8C\uFF0C\u62AC\u5934\u770B\u4E86\u4E00\u773C\u5929\u2014\u2014\u5929\u5F88\u597D\uFF0C\u4E91\u5F88\u767D\uFF0C\u4ED6\u5FFD\u7136\u4E0D\u60F3\u8DD1\u90A3\u4E48\u5FEB\u4E86\u3002";
var SEG_3 = "\u5C0F\u65F6\u5019\uFF0C\u6211\u5ACC\u7236\u4EB2\u8EAB\u4E0A\u7684\u673A\u6CB9\u5473\u96BE\u95FB\uFF0C\u4ED6\u4E00\u8FDB\u95E8\uFF0C\u6211\u5C31\u8EB2\u5F00\u3002\u4E0A\u9AD8\u4E2D\u4F4F\u6821\uFF0C\u6709\u4E00\u56DE\u6DF1\u591C\u53D1\u70E7\uFF0C\u5BA4\u53CB\u6253\u4E0D\u901A\u6211\u7684\u7535\u8BDD\uFF0C\u8F97\u8F6C\u627E\u5230\u4E86\u7236\u4EB2\u7684\u53F7\u7801\u3002\u4ED6\u8D76\u5230\u65F6\u5DF2\u7ECF\u51CC\u6668\u4E24\u70B9\uFF0C\u8EAB\u4E0A\u8FD8\u662F\u90A3\u80A1\u673A\u6CB9\u5473\u3002\u8FD9\u4E00\u6B21\uFF0C\u6211\u5374\u89C9\u5F97\u90A3\u5473\u9053\u5F88\u5B89\u5FC3\u2014\u2014\u90A3\u662F\u4ED6\u521A\u4ECE\u4FEE\u7406\u5382\u51FA\u6765\uFF0C\u8FDE\u8863\u670D\u90FD\u6CA1\u6362\u3002";
var SEG_4 = "\u6BCD\u4EB2\u603B\u5728\u9633\u53F0\u7684\u82B1\u76C6\u91CC\u79CD\u8584\u8377\u3002\u6211\u95EE\u5979\u4E3A\u4EC0\u4E48\u79CD\u8FD9\u4E2A\uFF0C\u5979\u8BF4\uFF1A\u300C\u597D\u6D3B\u3002\u300D\u90A3\u5E74\u79CB\u5929\u6211\u53C2\u52A0\u6F14\u8BB2\u6BD4\u8D5B\uFF0C\u4E0A\u53F0\u524D\u624B\u5FC3\u5168\u662F\u6C57\uFF0C\u4ECE\u53E3\u888B\u91CC\u6478\u51FA\u4E00\u5C0F\u5305\u8584\u8377\u53F6\u2014\u2014\u662F\u51FA\u95E8\u524D\u6BCD\u4EB2\u585E\u7ED9\u6211\u7684\uFF0C\u7528\u7EB8\u5DFE\u5305\u7740\uFF0C\u8FD8\u5E26\u7740\u9732\u6C34\u3002\u540E\u6765\u6211\u624D\u77E5\u9053\uFF0C\u9633\u53F0\u4E0A\u7684\u90A3\u51E0\u76C6\u8584\u8377\uFF0C\u662F\u5979\u77E5\u9053\u6211\u5BB9\u6613\u7D27\u5F20\u4EE5\u540E\u624D\u79CD\u7684\u3002";
var MAT_P1 = "\u3010\u6750\u6599\u4E00\u3011\u6E7F\u5730\u88AB\u79F0\u4E3A\u300C\u5730\u7403\u4E4B\u80BE\u300D\u3002\u5B83\u80FD\u84C4\u6C34\u8C03\u6D2A\uFF0C\u4E5F\u80FD\u51C0\u5316\u6C34\u8D28\uFF1A\u6C34\u6D41\u7ECF\u8FC7\u6E7F\u5730\u65F6\uFF0C\u6CE5\u6C99\u548C\u90E8\u5206\u6C61\u67D3\u7269\u4F1A\u88AB\u6C34\u751F\u690D\u7269\u4E0E\u571F\u58E4\u62E6\u4E0B\u3002\n\u3010\u6750\u6599\u4E8C\u3011\u67D0\u5E02\u5728\u57CE\u90CA\u4FEE\u590D\u4E86\u4E00\u7247\u7EA6\u4E24\u767E\u516C\u9877\u7684\u6EE9\u6D82\u6E7F\u5730\uFF0C\u8865\u79CD\u82A6\u82C7\u3001\u6E05\u7406\u5916\u6765\u7269\u79CD\uFF0C\u5E76\u8BBE\u7F6E\u4E86\u89C2\u9E1F\u6808\u9053\u4E0E\u9650\u6D41\u56F4\u680F\u3002\u4FEE\u590D\u4E09\u5E74\u540E\uFF0C\u6765\u8FD9\u91CC\u505C\u6B47\u7684\u6C34\u9E1F\u79CD\u7C7B\u7531\u539F\u6765\u7684\u4E09\u5341\u4F59\u79CD\u589E\u52A0\u5230\u4E03\u5341\u4F59\u79CD\u3002\n\u3010\u6750\u6599\u4E09\u3011\u6709\u4E13\u5BB6\u63D0\u9192\uFF0C\u89C2\u9E1F\u6D3B\u52A8\u672C\u8EAB\u4E5F\u53EF\u80FD\u5E26\u6765\u5E72\u6270\uFF1A\u4EBA\u9760\u5F97\u592A\u8FD1\u3001\u58F0\u97F3\u592A\u54CD\uFF0C\u90FD\u4F1A\u60CA\u6270\u9E1F\u7C7B\uFF1B\u56E0\u6B64\u5728\u89C2\u9E1F\u70B9\u8BBE\u7F6E\u5B89\u9759\u533A\u57DF\u3001\u89C4\u5B9A\u5B89\u5168\u8DDD\u79BB\uFF0C\u6BD4\u4E00\u5473\u589E\u52A0\u89C2\u9E1F\u8BBE\u65BD\u66F4\u91CD\u8981\u3002";
var MAT_P2 = "\u3010\u6750\u6599\u4E00\u3011\u67D0\u5E02\u975E\u9057\u4FDD\u62A4\u4E2D\u5FC3\u7684\u7EDF\u8BA1\u663E\u793A\uFF0C\u8BE5\u5E02\u5217\u5165\u5E02\u7EA7\u4EE5\u4E0A\u540D\u5F55\u7684\u4F20\u7EDF\u6280\u827A\u7C7B\u9879\u76EE\u6709 40 \u4F59\u9879\uFF0C\u5176\u4E2D\u4F20\u627F\u4EBA\u5E74\u9F84\u5728 60 \u5C81\u4EE5\u4E0A\u7684\u8D85\u8FC7\u4E03\u6210\u3002\u90E8\u5206\u9879\u76EE\u56E0\u7F3A\u5C11\u5E74\u8F7B\u4EBA\u63A5\u624B\uFF0C\u5904\u4E8E\u300C\u4EBA\u5728\u827A\u5728\u3001\u4EBA\u4EA1\u827A\u7EDD\u300D\u7684\u56F0\u5883\u3002\n\u3010\u6750\u6599\u4E8C\u3011\u8FD1\u4E24\u5E74\uFF0C\u8BE5\u5E02\u591A\u6240\u4E2D\u5B66\u628A\u672C\u5730\u624B\u827A\u8BF7\u8FDB\u8BFE\u5802\uFF1A\u6728\u7248\u6C34\u5370\u3001\u7AF9\u7F16\u3001\u7070\u5851\u7B49\u88AB\u7F16\u6210\u6BCF\u5468\u4E00\u8282\u7684\u5B9E\u8DF5\u6D3B\u52A8\u8BFE\uFF0C\u7531\u8001\u827A\u4EBA\u5E26\u5F92\u6388\u8BFE\u3002\u4E00\u5B66\u671F\u540E\uFF0C\u9009\u8BFE\u5B66\u751F\u4ECE\u6700\u521D\u7684\u4E00\u4E2A\u73ED\u6269\u5927\u5230\u516D\u4E2A\u73ED\u3002\n\u3010\u6750\u6599\u4E09\u3011\u6709\u7814\u7A76\u8005\u6307\u51FA\uFF0C\u4F20\u7EDF\u6280\u827A\u8FDB\u6821\u56ED\u7684\u5173\u952E\u4E0D\u5728\u300C\u5B66\u4F1A\u4E00\u95E8\u624B\u827A\u300D\uFF0C\u800C\u5728\u8BA9\u5B66\u751F\u7406\u89E3\u624B\u827A\u80CC\u540E\u7684\u8BB2\u7A76\u2014\u2014\u9009\u6599\u4E3A\u4EC0\u4E48\u8FD9\u6837\u9009\u3001\u5DE5\u5E8F\u4E3A\u4EC0\u4E48\u4E0D\u80FD\u98A0\u5012\u3002\u53EA\u6709\u628A\u300C\u4E3A\u4EC0\u4E48\u300D\u8BB2\u6E05\u695A\uFF0C\u624B\u827A\u624D\u53EF\u80FD\u88AB\u771F\u6B63\u4F20\u4E0B\u53BB\uFF1B\u5426\u5219\u5B66\u751F\u8BB0\u4F4F\u7684\u53EA\u662F\u51E0\u4E2A\u52A8\u4F5C\u3002";
var MAT_P3 = "\u3010\u6750\u6599\u4E00\u3011\u6709\u8C03\u67E5\u663E\u793A\uFF0C\u8FD1\u5E74\u6765\u6211\u56FD\u6210\u5E74\u56FD\u6C11\u6570\u5B57\u5316\u9605\u8BFB\u65B9\u5F0F\u7684\u63A5\u89E6\u7387\u603B\u4F53\u5448\u4E0A\u5347\u8D8B\u52BF\uFF0C\u800C\u4EBA\u5747\u7EB8\u8D28\u56FE\u4E66\u9605\u8BFB\u91CF\u5E76\u672A\u968F\u4E4B\u660E\u663E\u4E0B\u964D\u3002\n\u3010\u6750\u6599\u4E8C\u3011\u67D0\u4E2D\u5B66\u5BF9\u672C\u6821 600 \u540D\u5B66\u751F\u7684\u9605\u8BFB\u65B9\u5F0F\u505A\u4E86\u8C03\u67E5\uFF0C\u7ED3\u679C\u5982\u4E0B\u8868\uFF1A\n\u3000\u3000\u9605\u8BFB\u65B9\u5F0F\u3000\u3000\u3000\u3000\u3000\u3000\u3000\u3000\u3000\u4EBA\u6570\n\u3000\u3000\u53EA\u7528\u7EB8\u8D28\u4E66\u3000\u3000\u3000\u3000\u3000\u3000\u3000\u3000168\n\u3000\u3000\u7EB8\u8D28\u4E66\u4E3A\u4E3B\uFF0C\u5076\u5C14\u770B\u7535\u5B50\u4E66\u3000276\n\u3000\u3000\u7535\u5B50\u4E66\u4E3A\u4E3B\uFF0C\u5076\u5C14\u770B\u7EB8\u8D28\u4E66\u3000108\n\u3000\u3000\u53EA\u7528\u7535\u5B50\u4E66\u3000\u3000\u3000\u3000\u3000\u3000\u3000\u300048\n\u3010\u6750\u6599\u4E09\u3011\u8BED\u6587\u8001\u5E08\u63D0\u9192\uFF1A\u7EB8\u8D28\u9605\u8BFB\u4FBF\u4E8E\u524D\u540E\u7FFB\u68C0\u3001\u505A\u6279\u6CE8\uFF0C\u9002\u5408\u8BFB\u9700\u8981\u53CD\u590D\u7422\u78E8\u7684\u4E66\uFF1B\u7535\u5B50\u9605\u8BFB\u4FBF\u4E8E\u68C0\u7D22\u3001\u643A\u5E26\u65B9\u4FBF\uFF0C\u9002\u5408\u67E5\u8D44\u6599\u548C\u8BFB\u7BC7\u5E45\u77ED\u7684\u6587\u7AE0\u3002\u4E24\u79CD\u65B9\u5F0F\u5404\u6709\u5176\u7528\uFF0C\u5173\u952E\u662F\u8BFB\u4EC0\u4E48\u4E66\u3001\u7528\u4EC0\u4E48\u65B9\u5F0F\u3002";
