      answer: "\u2460\u5929\u4E0D\u4EAE\u5C31\u6765\u5DE1\u62A4\uFF0C\u770B\u62A4\u9E64\u7FA4\u4E0E\u6EE9\u6D82|\u2460\u6BCF\u5929\u5929\u4E0D\u4EAE\u5C31\u6491\u8239\u5DE1\u62A4\n\u2461\u51AC\u5929\u5582\u98DF\u3001\u6625\u5929\u770B\u5DE2\u3001\u590F\u5929\u5B88\u6C34\n\u2462\u6BCF\u5E74\u8865\u79CD\u82A6\u82C7\uFF0C\u8BA9\u6EE9\u6D82\u6162\u6162\u7EFF\u56DE\u6765|\u2462\u4E00\u5E74\u4E00\u5E74\u8865\u79CD\u82A6\u82C7\uFF0C\u6062\u590D\u6EE9\u6D82",
      explanation: "\u600E\u4E48\u60F3\u5230\u7684\uFF1A\u9898\u5E72\u9650\u5B9A\u300C\u8001\u5468\u505A\u7684\u4E8B\u300D\uFF0C\u7B54\u6848\u96C6\u4E2D\u5728\u7B2C\u2463\u6BB5\u3002\u8BE5\u6BB5\u7ED9\u4E86\u4E24\u7EC4\u5E76\u5217\u4FE1\u606F\u2014\u2014\u300C\u4ED6\u548C\u51E0\u4E2A\u4F19\u4F34\u6BCF\u5929\u5929\u4E0D\u4EAE\u5C31\u6765\u300D\u662F\u4E00\u4EF6\u4E8B\uFF1B\u300C\u51AC\u5929\u5582\u98DF\uFF0C\u6625\u5929\u770B\u5DE2\uFF0C\u590F\u5929\u5B88\u6C34\u300D\u662F\u4E00\u4EF6\u4E8B\uFF1B\u300C\u6BCF\u5E74\u8865\u79CD\u82A6\u82C7\uFF0C\u4E00\u5E74\u4E00\u5E74\u8865\uFF0C\u6EE9\u6D82\u624D\u6162\u6162\u7EFF\u56DE\u6765\u300D\u662F\u7B2C\u4E09\u4EF6\u4E8B\u3002\u6982\u62EC\u65F6\u628A\u6BCF\u4E00\u7EC4\u538B\u6210\u77ED\u8BED\u5373\u53EF\u3002\u7B2C\u2461\u6BB5\u7184\u9A6C\u8FBE\u3001\u7B2C\u2467\u6BB5\u6492\u7389\u7C73\u90FD\u5C5E\u300C\u5582\u98DF\u3001\u770B\u62A4\u300D\u4E00\u7C7B\uFF0C\u4E0D\u8981\u91CD\u590D\u8BA1\u70B9\uFF0C\u5199\u6EE1\u4E09\u70B9\u3001\u6BCF\u70B9\u5728 14 \u5B57\u5185\uFF0C\u6B63\u597D\u7EC3\u300C\u538B\u7F29\u300D\u8FD9\u4E00\u6B65\u3002",
