      type: "choice",
      stem: "\u9605\u8BFB\u4E0B\u9762\u7684\u6587\u6BB5\uFF0C\u5B8C\u6210\u9898\u76EE\u3002\n" + TEXT_C + "\n\u4E0B\u5217\u5BF9\u8001\u5468\u8FD9\u4E00\u4EBA\u7269\u5F62\u8C61\u7684\u5206\u6790\uFF0C\u4E0D\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
      options: [
        "\u300C\u5B83\u8BA4\u5F97\u6211\u300D\u4E00\u53E5\uFF0C\u5199\u51FA\u4ED6\u4E0E\u9E64\u957F\u671F\u76F8\u5904\u5EFA\u7ACB\u8D77\u6765\u7684\u719F\u6089\u4E0E\u4EB2\u8FD1\u3002",
        "\u4ED6\u53CD\u5BF9\u628A\u9E64\u56F4\u8D77\u6765\uFF0C\u8BF4\u660E\u4ED6\u5C0A\u91CD\u91CE\u751F\u52A8\u7269\u7684\u5929\u6027\uFF0C\u4E0D\u613F\u628A\u5B83\u4EEC\u517B\u5F97\u50CF\u5BB6\u79BD\u3002",
        "\u5E74\u5E95\u7EDF\u8BA1\u65F6\u4ED6\u300C\u4EC0\u4E48\u4E5F\u6CA1\u8BF4\u300D\uFF0C\u8BF4\u660E\u4ED6\u6027\u683C\u5B64\u50FB\uFF0C\u4E0D\u5584\u4E8E\u4E0E\u4EBA\u4EA4\u6D41\u3002",
        "\u4ED6\u5929\u4E0D\u4EAE\u5C31\u6765\u3001\u4E00\u5E74\u4E00\u5E74\u8865\u79CD\u82A6\u82C7\uFF0C\u8BF4\u660E\u4ED6\u505A\u4E8B\u8E0F\u5B9E\u3001\u7518\u4E8E\u957F\u671F\u9ED8\u9ED8\u4ED8\u51FA\u3002"
      ],
      answer: "C",
      explanation: "\u600E\u4E48\u60F3\u5230\u7684\uFF1A\u5F62\u8C61\u5206\u6790\u8981\u628A\u52A8\u4F5C\u653E\u56DE\u8BED\u5883\uFF0C\u4E0D\u80FD\u628A\u4E00\u5904\u300C\u6C89\u9ED8\u300D\u4E00\u5F8B\u8BFB\u6210\u4EBA\u683C\u7F3A\u9677\u3002C \u9879\u9519\uFF1A\u300C\u4EC0\u4E48\u4E5F\u6CA1\u8BF4\u300D\u5728\u8FD9\u91CC\u662F\u4E0D\u4E8B\u5F20\u626C\u3001\u628A\u6B23\u6170\u653E\u5728\u5FC3\u91CC\u2014\u2014\u9E64\u7FA4\u4ECE\u51E0\u5341\u53EA\u6DA8\u5230\u4E24\u767E\u591A\u53EA\uFF0C\u4ED6\u770B\u7740\u6570\u5B57\u4E0D\u5FC5\u8BF4\u4EC0\u4E48\uFF1B\u800C\u4E14\u6587\u4E2D\u4ED6\u660E\u660E\u4E0E\u300C\u6211\u300D\u4EA4\u8C08\u81EA\u5982\uFF0C\u8FD8\u6E05\u695A\u89E3\u91CA\u4E86\u81EA\u5DF1\u4E3A\u4EC0\u4E48\u4E0D\u8D5E\u6210\u56F4\u8D77\u6765\uFF0C\u53EF\u89C1\u300C\u6027\u683C\u5B64\u50FB\u3001\u4E0D\u5584\u4EA4\u6D41\u300D\u4E0D\u6210\u7ACB\u3002A\u3001B\u3001D \u4E09\u9879\u90FD\u80FD\u5728\u539F\u6587\u627E\u5230\u4F9D\u636E\u3002\u51E1\u662F\u628A\u67D0\u4E2A\u7EC6\u8282\u76F4\u63A5\u7B49\u540C\u4E8E\u300C\u6027\u683C\u5185\u5411\uFF0F\u5B64\u50FB\u300D\u7684\u9009\u9879\uFF0C\u90FD\u8981\u56DE\u5230\u4E0A\u4E0B\u6587\u6838\u5B9E\u3002",
      difficulty: 2,
      tags: ["\u6587\u5B66\u7C7B\xB7\u4EBA\u7269\u5F62\u8C61", "\u73B0\u4EE3\u6587\u9605\u8BFB", "\u5F62\u8C61\u5206\u6790"]
