      stem: "\u9605\u8BFB\u4E0B\u9762\u7684\u6750\u6599\uFF0C\u5B8C\u6210\u9898\u76EE\u3002\n" + MAT_P8 + "\n\u6839\u636E\u6750\u6599\u4E8C\u7684\u8868\u683C\uFF0C\u4E0B\u5217\u8868\u8FF0\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
      options: [
        "\u8BE5\u6821 800 \u540D\u521D\u4E2D\u751F\u4E2D\uFF0C\u7761\u7720\u8FBE\u5230\u6559\u80B2\u90E8\u8981\u6C42\uFF08\u6BCF\u5929 9 \u5C0F\u65F6\uFF09\u7684\u8D85\u8FC7\u4E09\u6210\u3002",
        "\u8868\u683C\u4E2D\u4EBA\u6570\u6700\u591A\u7684\u4E00\u6863\u662F\u300C8\u20149 \u5C0F\u65F6\u300D\uFF0C\u8BF4\u660E\u591A\u6570\u5B66\u751F\u7684\u7761\u7720\u63A5\u8FD1\u8FBE\u6807\u3002",
        "\u8BE5\u6821\u7761\u7720\u4E0D\u8DB3 8 \u5C0F\u65F6\u7684\u5B66\u751F\u7EA6\u5360 56%\uFF0C\u7761\u7720\u8FBE\u6807\uFF089 \u5C0F\u65F6\u53CA\u4EE5\u4E0A\uFF09\u7684\u4EC5\u7EA6 13%\u3002",
        "\u4ECE\u8868\u683C\u770B\uFF0C\u8BE5\u6821\u5B66\u751F\u7684\u7761\u7720\u65F6\u957F\u4E0E\u5B66\u4E60\u65F6\u95F4\u6CA1\u6709\u5173\u7CFB\u3002"
      ],
      answer: "C",
      explanation: "\u9010\u9879\u7B97\u8FC7\u518D\u9009\u3002A \u9879\uFF1A9 \u5C0F\u65F6\u53CA\u4EE5\u4E0A\u4E3A 104 \u4EBA\uFF0C104 \xF7 800 = 13%\uFF0C\u8FDC\u4E0D\u5230\u4E09\u6210\uFF0C\u9519\u3002B \u9879\uFF1A\u4EBA\u6570\u6700\u591A\u7684\u4E00\u6863\u662F\u300C7\u20148 \u5C0F\u65F6\u300D\uFF08312 \u4EBA\uFF09\uFF0C\u4E0D\u662F\u300C8\u20149 \u5C0F\u65F6\u300D\uFF08248 \u4EBA\uFF09\uFF0C\u9519\u3002C \u9879\uFF1A\u4E0D\u8DB3 7 \u5C0F\u65F6\u7684 136 \u4EBA\u4E0E 7\u20148 \u5C0F\u65F6\u7684 312 \u4EBA\u5408\u8BA1 448 \u4EBA\uFF0C448 \xF7 800 = 56%\uFF1B9 \u5C0F\u65F6\u53CA\u4EE5\u4E0A 104 \u4EBA\u5360 13%\uFF0C\u4E24\u9879\u90FD\u7B97\u5BF9\u4E86\uFF0C\u662F\u7B54\u6848\u3002D \u9879\uFF1A\u8868\u683C\u91CC\u53EA\u6709\u7761\u7720\u65F6\u957F\u7684\u4EBA\u6570\uFF0C\u6CA1\u6709\u5B66\u4E60\u65F6\u95F4\u7684\u6570\u636E\uFF0C\u300C\u6CA1\u6709\u5173\u7CFB\u300D\u5C5E\u65E0\u4E2D\u751F\u6709\u3002\u56FE\u8868\u9009\u62E9\u9898\u4E00\u5B9A\u8981\u5148\u628A\u6BCF\u4E00\u6863\u7684\u5360\u6BD4\u7B97\u5728\u8349\u7A3F\u8FB9\u4E0A\uFF0C\u51ED\u5370\u8C61\u770B\u300C\u6700\u591A\u7684\u4E00\u6863\u300D\u6700\u5BB9\u6613\u9519\u3002",
