    { name: "\u4E3B\u9898\u63A2\u7A76", note: "\u7531\u4E8B\u5165\u7406\uFF1A\u4E3B\u9898\u53E5 + \u60C5\u8282\u8BC1\u636E + \u542F\u793A\uFF0C\u4E0D\u8D34\u7A7A\u6CDB\u7684\u5927\u8BCD" },
    { name: "\u827A\u672F\u7279\u8272", note: "\u8BBD\u523A\u4E0E\u767D\u63CF\u3001\u8C61\u5F81\u4E0E\u610F\u8C61\u3001\u53D9\u4E8B\u89C6\u89D2\u3001\u79D1\u5B66\u6027\u4E0E\u6587\u5B66\u6027" },
    { name: "\u8DE8\u4E66\u6BD4\u8F83", note: "\u540C\u2014\u5F02\u2014\u56E0\u4E09\u6B65\u8D70\uFF0C\u4E24\u4FA7\u5404\u5E26\u60C5\u8282\uFF0C\u5199\u5C0F\u4F20\u4E0E\u4E13\u9898\u63A2\u7A76\u4E5F\u5F52\u6B64\u8282" },
    { name: "\u540D\u8457\u4E0E\u6587\u5316\u5E38\u8BC6", note: "\u4F5C\u8005\u4E0E\u56FD\u7C4D\u3001\u4F53\u88C1\u4E0E\u4F53\u4F8B\u3001\u9605\u8BFB\u65B9\u6CD5\u4E0E\u6574\u672C\u4E66\u9605\u8BFB\u5E38\u8BC6" }
