      difficulty: 2,
      tags: ["\u4EBA\u7269\u5F62\u8C61", "\u540D\u8457\u9605\u8BFB\u4E0E\u6574\u672C\u4E66\u9605\u8BFB", "\u6C34\u6D52\u4F20"]
