        "\u300A\u6C34\u6D52\u4F20\u300B\u4E00\u4FA7\u7ED3\u5408\u6797\u51B2\u88AB\u903C\u4E0A\u6881\u5C71\u7684\u60C5\u8282\uFF0C\u70B9\u51FA\u5176\u53CD\u6297\u7684\u300C\u88AB\u8FEB\u6027\u300D\u3002",
