      type: "choice",
      stem: "\u4E0B\u5217\u5BF9\u300A\u6D77\u5E95\u4E24\u4E07\u91CC\u300B\u4E2D\u5C3C\u6469\u8239\u957F\u5F62\u8C61\u7684\u6982\u62EC\uFF0C\u4E0D\u6B63\u786E\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
