      type: "choice",
      stem: "\u7ACB\u610F\uFF1A\u6BCD\u4EB2\u628A\u6211\u7834\u4E86\u7684\u6821\u5FBD\u7F1D\u5728\u4E66\u5305\u4FA7\u9762\uFF0C\u8BF4\u300C\u4E22\u4E86\u5C31\u4E0D\u597D\u627E\u4E86\u300D\u3002\u4E0B\u5217\u56DB\u4E2A\u9898\u76EE\uFF0C\u6700\u80FD\u76F4\u63A5\u62C6\u6210\u5F00\u5934\u3001\u4E2D\u6BB5\u3001\u7ED3\u5C3E\u4E09\u5904\u6263\u9898\u70B9\u7684\u4E00\u9879\u662F\uFF08\u3000\u3000\uFF09",
