// src/data/math/geoFig.ts
function on(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}
function mid(a, b) {
  return on(a, b, 0.5);
}
function centroid(nodes) {
  const xs = Object.values(nodes);
  if (!xs.length) return [50, 50];
  const sx = xs.reduce((n, p) => n + p[0], 0) / xs.length;
  const sy = xs.reduce((n, p) => n + p[1], 0) / xs.length;
  return [sx, sy];
}
function unit(a, b) {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const len = Math.hypot(dx, dy) || 1;
  return [dx / len, dy / len];
}
function degOf(v, to) {
  const d = unit(v, to);
  return Math.atan2(-d[1], d[0]) * 180 / Math.PI;
}
function tag(name, p, ref, opts = {}) {
  let dx = opts.dx ?? 2.2;
  let dy = opts.dy ?? -2.6;
  if (ref && opts.dx === void 0 && opts.dy === void 0) {
    const d = unit(ref, p);
    dx = d[0] < -0.25 ? -5.4 : d[0] > 0.25 ? 2.2 : -1.2;
    dy = d[1] > 0 ? 2.4 : -2.8;
  }
  return { t: "dot", x: p[0], y: p[1], label: name, labelDx: dx, labelDy: dy, hollow: opts.hollow, r: opts.size };
}
function tags(nodes, names) {
  const c = centroid(nodes);
  return (names ?? Object.keys(nodes)).map((n) => tag(n, nodes[n], c));
}
function path(nodes, order, opts = {}) {
  return {
    t: "poly",
    points: order.map((n) => nodes[n]),
    closed: opts.closed,
    tone: opts.tone,
    fill: opts.fill,
    dashed: opts.dashed
  };
}
function seg(a, b, opts = {}) {
  return {
    t: "line",
    x1: a[0],
    y1: a[1],
    x2: b[0],
    y2: b[1],
    tone: opts.tone,
    dashed: opts.dashed,
    width: opts.width
  };
}
function equalTicks(a, b, count = 1, tone = "ok") {
  const m = mid(a, b);
  const u = unit(a, b);
  const n = [-u[1], u[0]];
  const offsets = count <= 1 ? [0] : count === 2 ? [-1.2, 1.2] : [-2.2, 0, 2.2];
  return offsets.map((o) => {
    const c = [m[0] + u[0] * o, m[1] + u[1] * o];
    return seg([c[0] - n[0] * 1.5, c[1] - n[1] * 1.5], [c[0] + n[0] * 1.5, c[1] + n[1] * 1.5], { tone });
  });
}
function rightAngle(v, p1, p2, r = 3.6, tone = "muted") {
  const d1 = unit(v, p1);
  const d2 = unit(v, p2);
  const a = [v[0] + d1[0] * r, v[1] + d1[1] * r];
  const b = [v[0] + d2[0] * r, v[1] + d2[1] * r];
  const c = [a[0] + d2[0] * r, a[1] + d2[1] * r];
  return [seg(a, c, { tone }), seg(c, b, { tone })];
}
function angleArc(v, p1, p2, opts = {}) {
  const d1 = degOf(v, p1);
  const d2 = degOf(v, p2);
  const delta = (d2 - d1 + 540) % 360 - 180;
  return { t: "angle", x: v[0], y: v[1], from: d1, to: d1 + delta, r: opts.r ?? 6.5, tone: opts.tone, label: opts.label };
}
function parallelMark(a, b, count = 1, tone = "accent") {
  const m = mid(a, b);
  const u = unit(a, b);
  const n = [-u[1], u[0]];
  const offs = count <= 1 ? [0] : count === 2 ? [-1.6, 1.6] : [-3.2, 0, 3.2];
  return offs.map((o) => {
    const base = [m[0] + u[0] * o, m[1] + u[1] * o];
    const tail1 = [base[0] - u[0] * 1.9 + n[0] * 1.5, base[1] - u[1] * 1.9 + n[1] * 1.5];
    const tail2 = [base[0] - u[0] * 1.9 - n[0] * 1.5, base[1] - u[1] * 1.9 - n[1] * 1.5];
    const apex = [base[0] + u[0] * 0.5, base[1] + u[1] * 0.5];
    return { t: "poly", points: [tail1, apex, tail2], tone };
  });
}
function note(x, y, text, opts = {}) {
  return { t: "text", x, y, text, anchor: opts.anchor, size: opts.size ?? 3.6, tone: opts.tone ?? "muted" };
}
function geoFigure(f) {
  return { view: "wide", ...f };
}

