        explanation: "\u5206\u5F0F\u503C\u4E3A 0 \u8981\u6C42\u5206\u5B50\u4E3A 0 \u4E14\u5206\u6BCD\u4E0D\u4E3A 0\u3002\u7531 $x^{2}-1=0$ \u5F97 $x=\\pm 1$\uFF1B\u4F46\u5206\u6BCD $x+1\\neq 0$\uFF0C\u5373 $x\\neq -1$\uFF0C\u6545\u53EA\u80FD\u53D6 $x=1$\uFF0C\u9009 A\u3002\u76F4\u63A5\u7531\u5206\u5B50\u4E3A 0 \u53D6 $\\pm 1$ \u4F1A\u9519\u9009 C\uFF0C\u56E0\u4E3A $x=-1$ \u65F6\u5206\u5F0F\u65E0\u610F\u4E49\u3002",
        difficulty: 2,
        tags: ["\u5206\u5F0F\u6709\u610F\u4E49", "\u53D6\u503C\u8303\u56F4", "\u8BA1\u7B97"]
