          "\u7B2C\u4E00\u6B21\u6D4B\u91CF\uFF1A\u7531\u76F8\u4F3C\u5F97\u300C\u7269\u9AD8\u4E0E\u706F\u9AD8\u4E4B\u6BD4\u7B49\u4E8E\u5F71\u957F\u4E0E\uFF08\u706F\u5230\u6746\u8DDD\u79BB\u52A0\u5F71\u957F\uFF09\u4E4B\u6BD4\u300D\uFF0C\u5373 $\\frac{1.5}{H}=\\frac{2.5}{s+2.5}$\u3002",
