        note: "\u524D\u63D0\u662F\u4E24\u6761\u5207\u7EBF\u7531\u540C\u4E00\u4E2A\u5706\u5916\u4E00\u70B9\u5F15\u51FA\u3002\u5207\u7EBF\u957F\u662F\u5207\u70B9\u4E0E\u5706\u5916\u70B9\u4E4B\u95F4\u7EBF\u6BB5\u7684\u957F\u5EA6\uFF08\u4E0D\u662F\u5F27\u957F\uFF0C\u4E5F\u4E0D\u662F\u5207\u7EBF\u7684\u5168\u957F\uFF09\u3002\u7531 $PA=PB$\u3001$OA=OB$ \u53EF\u77E5\u76F4\u7EBF $OP$ \u662F\u5F26 $AB$ \u7684\u5782\u76F4\u5E73\u5206\u7EBF\uFF0C\u8FD9\u662F\u6C42\u5F26\u957F\u6216\u8BC1\u660E\u5782\u76F4\u7684\u5E38\u7528\u7ED3\u8BBA\u3002"
