            { t: "text", x: 50, y: 60, text: "\u89E3\u5F97 x = 42\uFF1A\u7532\u73ED\u539F\u6709 48 \u4EBA\uFF0C\u4E59\u73ED\u539F\u6709 42 \u4EBA", size: 3.4, anchor: "middle" }
