        answer: "\u4E24\u6237\u5206\u522B\u7F34\u8D39\u66F4\u7701\u94B1\uFF0C\u6BD4\u5408\u6210\u4E00\u6237\u7F34\u8D39\u7701 30 \u5143\uFF08\u5206\u7F34\u5171 100 \u5143\uFF0C\u5408\u7F34\u4E3A 130 \u5143\uFF09",
