        stem: "\u8BF7\u5199\u51FA\u89E3\u7B54\u9009\u62E9\u9898\u65F6\u5E38\u7528\u7684\u4E09\u79CD\u901F\u89E3\u6280\u5DE7\uFF0C\u5E76\u5404\u914D\u4E00\u4E2A\u9002\u5408\u8BE5\u6280\u5DE7\u7684\u9898\u76EE\u60C5\u5883\u3002",
        answer: "\uFF081\uFF09\u7279\u503C\u6CD5\uFF1A\u9002\u7528\u4E8E\u300C\u4E0B\u5217\u7ED3\u8BBA\u4E00\u5B9A\u6210\u7ACB\u300D\u7C7B\u7684\u4EE3\u6570\u6052\u7B49\u5224\u65AD\u4EE5\u53CA\u53D6\u503C\u8303\u56F4\u5224\u65AD\uFF0C\u5982\u5DF2\u77E5 $m<n<0$ \u5224\u65AD\u5404\u4E0D\u7B49\u5F0F\u662F\u5426\u6210\u7ACB\uFF0C\u53D6 $m=-2$\u3001$n=-1$ \u4EE3\u5165\u9010\u4E00\u68C0\u9A8C\u3002\uFF082\uFF09\u6392\u9664\u6CD5\uFF08\u4EE3\u5165\u9A8C\u8BC1\uFF09\uFF1A\u9002\u7528\u4E8E\u542B\u53C2\u65B9\u7A0B\u3001\u51FD\u6570\u56FE\u8C61\u5224\u5B9A\u3001\u51E0\u4F55\u56FE\u5F62\u5224\u5B9A\uFF0C\u5982\u7531\u300C\u5F00\u53E3\u5411\u4E0B\u300D\u76F4\u63A5\u6392\u9664 $a>0$ \u7684\u9009\u9879\uFF0C\u518D\u628A\u5269\u4F59\u9009\u9879\u4EE3\u56DE\u6761\u4EF6\u68C0\u9A8C\u3002\uFF083\uFF09\u6570\u5F62\u7ED3\u5408\u6CD5\uFF1A\u9002\u7528\u4E8E\u4E00\u6B21\u51FD\u6570\u3001\u53CD\u6BD4\u4F8B\u51FD\u6570\u3001\u4E8C\u6B21\u51FD\u6570\u7684\u56FE\u8C61\u6027\u8D28\u4E0E\u4F4D\u7F6E\u5173\u7CFB\uFF0C\u5982\u7531\u56FE\u8C61\u7ECF\u8FC7\u7684\u8C61\u9650\u53CD\u63A8 $k$\u3001$b$ \u7684\u7B26\u53F7\uFF0C\u6216\u7531\u629B\u7269\u7EBF\u8FC7 $(-1,0)$\u3001$(3,0)$ \u76F4\u63A5\u8BFB\u51FA\u5BF9\u79F0\u8F74 $x=1$\u3002\u6B64\u5916\u7279\u6B8A\u4F4D\u7F6E\u6CD5\u9002\u7528\u4E8E\u52A8\u70B9\u6700\u503C\u95EE\u9898\uFF0C\u4EE3\u5165\u7AEF\u70B9\u6216\u4E2D\u70B9\u5FEB\u901F\u9884\u5224\u7B54\u6848\u3002",
        explanation: "\u672C\u9898\u4E3A\u65B9\u6CD5\u5F52\u7EB3\u9898\uFF0C\u8BC4\u5206\u770B\u4E09\u70B9\uFF1A\u6280\u5DE7\u540D\u79F0\u662F\u5426\u89C4\u8303\u3001\u662F\u5426\u7ED9\u51FA\u5177\u4F53\u9898\u76EE\u60C5\u5883\u3001\u60C5\u5883\u4E0E\u6280\u5DE7\u662F\u5426\u5339\u914D\u3002\u5224\u65AD\u5339\u914D\u662F\u5426\u5408\u7406\u7684\u6807\u51C6\u662F\u300C\u8BE5\u6280\u5DE7\u786E\u5B9E\u80FD\u51CF\u5C11\u672C\u9898\u7684\u8FD0\u7B97\u91CF\u6216\u601D\u8003\u91CF\u300D\uFF1A\u4F8B\u5982\u7279\u503C\u6CD5\u5728\u300C\u4E00\u5B9A\u6210\u7ACB\u300D\u578B\u5224\u65AD\u4E2D\u6700\u6709\u6548\uFF0C\u56E0\u4E3A\u53EA\u9700\u4EE3\u5165\u68C0\u9A8C\u800C\u4E0D\u5FC5\u8BC1\u660E\uFF1B\u6570\u5F62\u7ED3\u5408\u6CD5\u5728\u56FE\u8C61\u6027\u8D28\u9898\u4E2D\u6700\u6709\u6548\uFF0C\u56E0\u4E3A\u56FE\u5F62\u628A\u62BD\u8C61\u5173\u7CFB\u76F4\u89C2\u5316\u4E86\u3002\u82E5\u53EA\u5217\u540D\u79F0\u4E0D\u7ED9\u60C5\u5883\uFF0C\u6216\u7ED9\u51FA\u7684\u60C5\u5883\u4E0E\u6280\u5DE7\u5E76\u4E0D\u5951\u5408\uFF08\u5982\u628A\u7279\u503C\u6CD5\u7528\u4E8E\u7EAF\u51E0\u4F55\u8BC1\u660E\u9898\uFF09\uFF0C\u5219\u4E0D\u80FD\u5F97\u5206\u3002",
