          answer: "$\\frac{x-1}{x+1}$\uFF08$x\\ne-1$\uFF09",
          analysis: "\u600E\u4E48\u60F3\u5230\u7684\uFF1A\u5206\u5F0F\u7684\u5316\u7B80\u4E0D\u505A\u9664\u6CD5\u3001\u4E5F\u4E0D\u79FB\u9879\uFF0C\u53EA\u8981\u628A\u5206\u5B50\u5206\u6BCD\u90FD\u53D8\u6210\u4E58\u79EF\u5F62\u5F0F\uFF0C\u76F8\u540C\u7684\u56E0\u5F0F\u5C31\u770B\u5F97\u51FA\u6765\u3002\u6240\u4EE5\u7B2C\u4E00\u6B65\u4E0D\u662F\u7EA6\u5206\uFF0C\u800C\u662F\u5206\u89E3\u56E0\u5F0F\uFF1B\u7EA6\u5206\u4E4B\u540E\u987A\u624B\u628A\u9650\u5236\u6761\u4EF6\u5199\u4E0A\uFF0C\u8FD9\u4E00\u6B65\u5728\u89E3\u7B54\u9898\u91CC\u5355\u72EC\u5360\u5206\u3002"
