        "\u6B63\u786E\u5199\u51FA\u5E76\u5316\u7B80\u51FD\u6570\u5173\u7CFB\u5F0F $y=3.8x-26$\uFF0C\u540C\u65F6\u6CE8\u660E\u81EA\u53D8\u91CF\u8303\u56F4 $x>20$\u3002",
