            "\u70B9\u6570\u548C\u4E3A 7 \u7684\u7ED3\u679C\u6709 $(1,6)$\uFF0C$(2,5)$\uFF0C$(3,4)$\uFF0C$(4,3)$\uFF0C$(5,2)$\uFF0C$(6,1)$\uFF0C\u5171 6 \u79CD\u3002",
            "\u6240\u6C42\u6982\u7387 $P=\\dfrac{6}{36}=\\dfrac{1}{6}$\u3002"
