        "\u5229\u6DA6\u578B\uFF1A$w=(\\text{\u552E\u4EF7}-\\text{\u8FDB\u4EF7})\\times\\text{\u9500\u91CF}$\uFF1B\u9762\u79EF\u578B\uFF1A\u7528\u5468\u957F\u6216\u7BF1\u7B06\u957F\u628A\u53E6\u4E00\u6761\u8FB9\u8868\u793A\u6210\u542B $x$ \u7684\u5F0F\u5B50\uFF1B\u8D39\u7528\u578B\uFF1A\u5206\u6BB5\u5199\u51FA\u6BCF\u4E00\u6BB5\u7684\u6536\u8D39\u3002",
        "\u914D\u65B9\u6210 $y=a(x-h)^2+k$\uFF0C\u770B\u6E05 $a$ \u7684\u6B63\u8D1F\uFF08$a<0$ \u9876\u70B9\u6700\u5927\u3001$a>0$ \u9876\u70B9\u6700\u5C0F\uFF09\u3002",
        "\u5199\u51FA\u81EA\u53D8\u91CF\u53D6\u503C\u8303\u56F4\uFF0C\u5E76\u5224\u65AD\u9876\u70B9\u6A2A\u5750\u6807 $h$ \u662F\u5426\u843D\u5728\u8303\u56F4\u5185\uFF1A\u5728\u5219\u53D6\u9876\u70B9\uFF0C\u4E0D\u5728\u5219\u53D6\u79BB $h$ \u6700\u8FD1\u7684\u7AEF\u70B9\u3002",
        "\u7B54\u53E5\u5199\u6E05\u300C\u5F53\u2026\u2026\u65F6\u53D6\u5F97\u6700\u5927\u503C\u2026\u2026\u300D\uFF0C\u5206\u6BB5\u8BA1\u8D39\u9898\u5148\u7B97\u5206\u754C\u70B9\u5904\u7684\u8D39\u7528\u518D\u5224\u65AD\u843D\u5728\u54EA\u4E00\u6BB5\u3002"
