        "\u5355\u6B21\u89C2\u6D4B\u7528\u4E00\u6761 $\\tan$ \u5173\u7CFB\u5F0F\uFF1B\u4E24\u6B21\u89C2\u6D4B\u8BBE\u540C\u4E00\u4E2A\u94C5\u76F4\u9AD8\u5EA6 $h$\uFF0C\u7528\u300C\u4E24\u6BB5\u6C34\u5E73\u8DDD\u79BB\u4E4B\u5DEE\u7B49\u4E8E\u540E\u9000\u8DDD\u79BB\u300D\u8054\u7ACB\u3002",
        "\u5761\u5EA6 $i=1:m$ \u8868\u793A\u94C5\u76F4\u9AD8\u5EA6\u4E0E\u6C34\u5E73\u5BBD\u5EA6\u4E4B\u6BD4\u4E3A $1:m$\uFF0C\u5761\u9762\u957F\u662F\u659C\u8FB9\uFF0C\u5E38\u914D 3\u30014\u30015 \u6216 5\u300112\u300113 \u8FD9\u7EC4\u52FE\u80A1\u6570\u3002",
        "\u4E0D\u53EF\u8FBE\u8DDD\u79BB\u5148\u60F3\u5728\u5E73\u5730\u4E0A\u53D6\u70B9\u6784\u9020\u76F4\u89D2\u4E09\u89D2\u5F62\u7528\u52FE\u80A1\u5B9A\u7406\uFF1B\u4E0D\u80FD\u6784\u9020\u5C31\u7528\u540C\u4E00\u65F6\u523B\u7684\u5F71\u957F\u6216\u6807\u6746\u9020\u76F8\u4F3C\u4E09\u89D2\u5F62\u3002",
        "\u65B9\u6848\u8BBE\u8BA1\u9898\u6309\u56DB\u6B65\u5199\uFF1A\u6D4B\u91CF\u5BF9\u8C61\u4E0E\u5DE5\u5177\u3001\u64CD\u4F5C\u6B65\u9AA4\u3001\u8BA1\u7B97\u4F9D\u636E\uFF08\u7528\u4E86\u54EA\u4E2A\u516C\u5F0F\u6216\u76F8\u4F3C\u5173\u7CFB\uFF09\u3001\u7ED3\u679C\u8868\u8FBE\u5F0F\uFF1B\u5E26\u6D4B\u89D2\u4EEA\u65F6\u6700\u540E\u52A0\u56DE\u4EEA\u5668\u9AD8\u5EA6\u3002"
