        "\u6700\u503C\u9898\u5199\u51FA\u914D\u65B9\u7ED3\u679C\u4E0E\u53D6\u503C\u8303\u56F4\u4E24\u884C\uFF0C\u5E76\u5199\u300C\u56E0\u4E3A $a<0$\uFF0C\u6240\u4EE5\u5F53\u2026\u2026\u65F6\u53D6\u5F97\u6700\u5927\u503C\u300D\u3002",
        "\u68C0\u9A8C\u5355\u72EC\u6210\u884C\uFF1A\u628A\u89E3\u4EE3\u56DE\u5B9E\u9645\u60C5\u5883\u6838\u5BF9\uFF08\u5EA7\u4F4D\u6570\u3001\u4EBA\u6570\u3001\u8D39\u7528\uFF09\uFF0C\u5E76\u5199\u300C\u7B26\u5408\u9898\u610F\u300D\u3002",
