        "\u65B9\u6848 A \u603B\u989D\uFF1A$900\\times3=2700$\uFF08\u5143\uFF09\u3002",
        "\u65B9\u6848 B \u5206\u6863\u5355\u4EF7\u7B97\u5BF9\uFF1A10 \u5428\u6237\u6BCF\u6237 25 \u5143\uFF0C20 \u5428\u6237\u6BCF\u6237 $15\\times2.5+5\\times4=57.5$ \u5143\uFF0C30 \u5428\u6237\u6BCF\u6237 $15\\times2.5+15\\times4=97.5$ \u5143\u3002",
