      explanation: "\u600E\u4E48\u60F3\u5230\u7684\uFF1A\u53D6\u503C\u8303\u56F4\u7531\u300C\u8C01\u5148\u505C\u6B62\u300D\u51B3\u5B9A\u2014\u2014$Q$ \u4ECE $A$ \u5230 $C$ \u8981\u8D70 $AC=6$ \u4E2A\u5355\u4F4D\u3001\u901F\u5EA6\u662F\u6BCF\u79D2 1 \u4E2A\u5355\u4F4D\uFF0C\u6240\u4EE5\u6700\u591A\u8FD0\u52A8 6 \u79D2\uFF1B\u867D\u7136 $P$ \u6CBF\u5C04\u7EBF $CB$ \u53EF\u4EE5\u4E00\u76F4\u8D70\u4E0B\u53BB\uFF0C\u4F46\u9898\u76EE\u89C4\u5B9A $Q$ \u5230\u8FBE $C$ \u65F6\u4E24\u70B9\u540C\u65F6\u505C\u6B62\uFF0C\u56E0\u6B64 $t\\le6$\u3002\u51FA\u53D1\u77AC\u95F4\uFF08$t=0$\uFF09\u4E0E\u505C\u6B62\u77AC\u95F4\uFF08$t=6$\uFF09\u90FD\u8FD8\u5728\u8FD0\u52A8\u8FC7\u7A0B\u4E2D\uFF0C\u7AEF\u70B9\u90FD\u8981\u4FDD\u7559\u3002\u6545\u9009 B\u3002",
      difficulty: 1,
      tags: ["\u52A8\u70B9\u95EE\u9898", "\u538B\u8F74\u4E0E\u5E94\u8BD5", "\u53D6\u503C\u8303\u56F4"]
