      explanation: "\u600E\u4E48\u60F3\u5230\u7684\uFF1A\u76F4\u89D2\u6761\u4EF6\u4E0B\u7684\u4E09\u89D2\u5F62\u9762\u79EF\uFF0C\u6C38\u8FDC\u5148\u627E\u300C\u4E92\u76F8\u5782\u76F4\u7684\u4E24\u6761\u8FB9\u300D\u5F53\u5E95\u548C\u9AD8\uFF0C\u8FD9\u6837\u4E0D\u5FC5\u53E6\u5916\u6C42\u9AD8\u3002$PB$ \u7528\u300C\u603B\u957F\u51CF\u53BB\u8D70\u8FC7\u7684\u8DEF\u7A0B\u300D\u8868\u793A\uFF0C$BQ$ \u5C31\u662F\u8DEF\u7A0B\u672C\u8EAB\uFF1B\u5F97\u5230\u4E8C\u6B21\u5F0F\u4E4B\u540E\u914D\u65B9\u6C42\u6700\u503C\uFF0C\u6700\u540E\u4E00\u5B9A\u56DE\u5230\u53D6\u503C\u8303\u56F4\u786E\u8BA4\u9876\u70B9\u53EF\u7528\u3002",
      difficulty: 2,
      tags: ["\u52A8\u70B9\u95EE\u9898", "\u538B\u8F74\u4E0E\u5E94\u8BD5", "\u6700\u503C"]
