      type: "choice",
      stem: "\u76F4\u7EBF $y=2x-3$ \u4E0E\u629B\u7269\u7EBF $y=x^2$ \u7684\u516C\u5171\u70B9\u4E2A\u6570\u662F\uFF08\u3000\u3000\uFF09",
