        answer: "\u7B2C\u4E00\u6761\uFF1A\u5148\u8DF3\u8FC7\u8FD9\u4E2A\u7A7A\uFF0C\u628A\u540E\u9762\uFF08\u6216\u524D\u9762\uFF09\u7684\u53E5\u5B50\u8BFB\u4E0B\u53BB\uFF0C\u7528\u4E0A\u4E0B\u6587\u7EBF\u7D22\u56DE\u5934\u5224\u65AD\u2014\u2014\u5B8C\u5F62\u586B\u7A7A\u7684\u7B54\u6848\u5E38\u5E38\u5728\u4E0B\u4E00\u53E5\u91CC\uFF0C\u4F8B\u5982\u4E0B\u6587\u51FA\u73B0\u4E86\u540C\u4E49\u8BCD\u3001\u53CD\u4E49\u8BCD\u6216\u7ED3\u679C\uFF0C\u5C31\u80FD\u53CD\u63A8\u8FD9\u4E2A\u7A7A\u7684\u65B9\u5411\u3002\u7B2C\u4E8C\u6761\uFF1A\u628A\u56DB\u4E2A\u9009\u9879\u9010\u4E00\u653E\u56DE\u539F\u53E5\uFF0C\u8FDE\u540C\u524D\u540E\u5404\u4E00\u53E5\u9ED8\u8BFB\u4E00\u904D\uFF0C\u8BFB\u4E0D\u901A\uFF08\u65F6\u6001\u4E0D\u4E00\u81F4\u3001\u642D\u914D\u4E0D\u5BF9\u3001\u610F\u601D\u77DB\u76FE\uFF09\u7684\u5148\u6392\u9664\uFF0C\u5269\u4E0B\u4E24\u4E2A\u518D\u6BD4\u8F83\u611F\u60C5\u8272\u5F69\u4E0E\u5168\u6587\u57FA\u8C03\u3002\u6B64\u5916\u8FD8\u53EF\u4EE5\u68C0\u67E5\u642D\u914D\uFF1A\u770B\u8BE5\u8BCD\u80FD\u5426\u4E0E\u7A7A\u683C\u524D\u540E\u7684\u4ECB\u8BCD\u6216\u540D\u8BCD\u642D\u914D\uFF0C\u4EE5\u53CA\u4E3B\u8BED\u7684\u5355\u590D\u6570\u3001\u53E5\u5B50\u7684\u65F6\u6001\u662F\u5426\u5339\u914D\u3002",
        rubric: [
          "\u5199\u51FA\u300C\u5148\u8DF3\u8FC7\uFF0C\u9760\u4E0A\u4E0B\u6587\u7EBF\u7D22\u56DE\u586B\u300D\u8FD9\u4E00\u6761\uFF0C\u5E76\u8BF4\u660E\u7EBF\u7D22\u6765\u81EA\u4E0A\u4E0B\u6587\uFF08\u540C\u4E49\u590D\u73B0\u3001\u53CD\u4E49\u8BCD\u3001\u56E0\u679C\u6216\u7ED3\u679C\uFF09\u3002",
          "\u5199\u51FA\u300C\u9009\u9879\u4EE3\u5165\u539F\u53E5\u6717\u8BFB\u300D\uFF0C\u5E76\u8BF4\u660E\u8981\u8FDE\u524D\u540E\u53E5\u4E00\u8D77\u8BFB\uFF0C\u628A\u4E0D\u901A\u987A\u3001\u642D\u914D\u9519\u7684\u6392\u9664\u3002",
          "\u81F3\u5C11\u63D0\u5230\u4E00\u9879\u8BED\u6CD5\u68C0\u67E5\uFF1A\u65F6\u6001\u4E00\u81F4\u3001\u4E3B\u8C13\u5355\u590D\u6570\u3001\u4ECB\u8BCD\u642D\u914D\u6216\u975E\u8C13\u8BED\u5F62\u5F0F\u3002",
          "\u505A\u6CD5\u8981\u5177\u4F53\u53EF\u64CD\u4F5C\uFF08\u8BF4\u6E05\u600E\u4E48\u505A\uFF09\uFF0C\u4E0D\u80FD\u53EA\u5199\u300C\u591A\u8BFB\u51E0\u904D\u300D\u300C\u8BA4\u771F\u5BA1\u9898\u300D\u8FD9\u7C7B\u7A7A\u8BDD\u3002"
        ],
        explanation: "\u5B8C\u5F62\u586B\u7A7A\u7684\u6B63\u786E\u7B54\u6848\u4E00\u5B9A\u80FD\u5728\u539F\u6587\u91CC\u627E\u5230\u4F9D\u636E\uFF0C\u6240\u4EE5\u300C\u9009\u4E0D\u51FA\u300D\u65F6\u4E0D\u80FD\u51ED\u611F\u89C9\uFF0C\u800C\u662F\u56DE\u53BB\u627E\u7EBF\u7D22\uFF1A\u4E0A\u4E0B\u6587\u590D\u73B0\u3001\u903B\u8F91\u5173\u7CFB\u3001\u56FA\u5B9A\u642D\u914D\u3001\u8BED\u6CD5\u5F62\u5F0F\u3002\u628A\u56DB\u4E2A\u9009\u9879\u90FD\u4EE3\u5165\u6717\u8BFB\uFF0C\u662F\u6392\u9664\u6CD5\u7684\u6838\u5FC3\u52A8\u4F5C\u3002",
        difficulty: 2,
        tags: ["\u5E94\u8BD5\u7B56\u7565", "\u5B8C\u5F62\u586B\u7A7A\u65B9\u6CD5"]
