        explain: "\u5178\u578B\u5E72\u6270\u9879\u6709\u56DB\u7C7B\uFF1A\u539F\u6587\u6CA1\u63D0\u8FC7\uFF08\u65E0\u4E2D\u751F\u6709\uFF09\u3001\u628A A \u7684\u7279\u70B9\u5B89\u5230 B \u8EAB\u4E0A\uFF08\u5F20\u51A0\u674E\u6234\uFF09\u3001\u628A some \u8BF4\u6210 all \u6216\u628A always \u8BF4\u6210 sometimes\uFF08\u4EE5\u504F\u6982\u5168\uFF09\u3001\u6B63\u8BEF\u6DF7\u6742\uFF08\u524D\u534A\u53E5\u5BF9\u540E\u534A\u53E5\u9519\uFF09\u3002\u9010\u4E2A\u6838\u5BF9\uFF0C\u53EA\u8981\u6709\u4E00\u5904\u4E0E\u539F\u6587\u4E0D\u7B26\u5C31\u6392\u9664\u3002"
