        explain: "\u5E7F\u5DDE\u4E2D\u8003\u9879\u76EE\u60C5\u5883\u7B2C\u4E8C\u8282\u662F\u7B80\u7B54\u9898\uFF0C\u7B54\u6848\u8981\u6709\u4E09\u5757\uFF1A\u5148\u7B54\u6570\u636E\uFF08\u51C6\u786E\u3001\u5E26\u5355\u4F4D\uFF09\uFF0C\u518D\u8BF4\u51FA\u6BD4\u8F83\u6216\u7ED3\u8BBA\uFF08\u6BD4\u8C01\u591A\u3001\u8BF4\u660E\u4EC0\u4E48\uFF09\uFF0C\u6700\u540E\u6309\u9898\u76EE\u8981\u6C42\u8865\u4E00\u53E5\u81EA\u5DF1\u7684\u770B\u6CD5\u6216\u5EFA\u8BAE\u3002\u53EA\u5199\u300C160 litres\u300D\u8FD9\u6837\u7684\u7247\u6BB5\u901A\u5E38\u62FF\u4E0D\u5230\u6EE1\u5206\u3002"
