            explanation: "\u6750\u6599\u6700\u540E\u4E00\u53E5\u5C31\u662F\u4E3B\u65E8\u53E5\uFF1B\u4E3B\u65E8\u7C7B\u9898\u76EE\u7528\u5B83\u7684\u540C\u4E49\u8BF4\u6CD5\u4F5C\u7B54\u5373\u53EF\uFF0C\u4E0D\u9700\u8981\u53E6\u627E\u89C2\u70B9\u3002",
            difficulty: 2,
