              "\u7528\u7B2C\u4E00\u4EBA\u79F0 I \u6216 we\uFF0C\u7528\u4E00\u822C\u8FC7\u53BB\u65F6",
              "\u7528\u7B2C\u4E8C\u4EBA\u79F0 you\uFF0C\u7528\u73B0\u5728\u5B8C\u6210\u65F6",
              "\u4EBA\u79F0\u968F\u610F\uFF0C\u65F6\u6001\u7528\u4E00\u822C\u73B0\u5728\u65F6"
