        stem: "\u7528\u4E24\u4E2A\u5B57\u6982\u62EC\u5B8C\u5F62\u586B\u7A7A\u7684\u89E3\u9898\u987A\u5E8F\uFF1A\u5148 ____ \u5168\u6587\uFF0C\u518D\u56DE\u586B\u6BCF\u4E2A\u7A7A\u3002",
        answer: "\u901A\u8BFB|\u901A\u8BFB\u4E00\u904D|\u8BFB\u901A",
