        explain: "\u591A\u5199 20 \u4E2A\u8BCD\u7684\u98CE\u9669\u5927\u4E8E\u6536\u76CA\uFF1A\u6BCF\u4E2A\u591A\u4F59\u7684\u53E5\u5B50\u90FD\u53EF\u80FD\u662F\u9519\u8BEF\u7684\u6765\u6E90\u3002\u628A\u8981\u70B9\u5199\u6E05\u695A\uFF0C\u518D\u8865\u4E00\u53E5\u611F\u53D7\uFF0C\u4E00\u822C\u6B63\u597D\u843D\u5728 100 \u8BCD\u5DE6\u53F3\u3002"
