        material: "\u3010\u6750\u6599\u4E00\u3011\u5317\u4EAC\u4EBA\u9057\u5740\u51FA\u571F\u4E86\u5927\u91CF\u6253\u5236\u77F3\u5668\u3001\u6210\u5806\u7684\u7070\u70EC\u5C42\uFF0C\u7070\u70EC\u4E2D\u6709\u70E7\u8FC7\u7684\u517D\u9AA8\u548C\u6811\u7C7D\u3002\n\u3010\u6750\u6599\u4E8C\u3011\u826F\u6E1A\u53E4\u57CE\u9057\u5740\u7531\u5BAB\u6BBF\u533A\u3001\u5185\u57CE\u3001\u5916\u57CE\u7EC4\u6210\uFF0C\u5916\u56F4\u53D1\u73B0\u7531 11 \u6761\u5824\u575D\u7EC4\u6210\u7684\u6C34\u5229\u7CFB\u7EDF\uFF1B\u57CE\u5185\u51FA\u571F\u5927\u91CF\u7CBE\u81F4\u7684\u7389\u742E\u3001\u7389\u74A7\u3002\n\u3010\u6750\u6599\u4E09\u3011\u4E2D\u534E\u6587\u660E\u63A2\u6E90\u5DE5\u7A0B\u63D0\u51FA\u5224\u65AD\u8FDB\u5165\u6587\u660E\u793E\u4F1A\u7684\u4E2D\u56FD\u65B9\u6848\uFF1A\u51FA\u73B0\u57CE\u5E02\u3001\u51FA\u73B0\u9636\u7EA7\u5206\u5316\u3001\u51FA\u73B0\u738B\u6743\u4E0E\u56FD\u5BB6\u3002",
