        text: "\u4E24\u6C49\u79D1\u6280\u6587\u5316\uFF1A\u8521\u4F26\u6539\u8FDB\u9020\u7EB8\u672F\u3001\u5F20\u4EF2\u666F\u300A\u4F24\u5BD2\u6742\u75C5\u8BBA\u300B\u3001\u534E\u4F57\u3001\u53F8\u9A6C\u8FC1\u300A\u53F2\u8BB0\u300B\uFF08\u6211\u56FD\u7B2C\u4E00\u90E8\u7EAA\u4F20\u4F53\u901A\u53F2\uFF09\u3002"
