            stem: "\uFF081\uFF09\u6750\u6599\u4E00\u3001\u4E8C\u53CD\u6620\u4E86\u79E6\u4E0E\u6C49\u521D\u600E\u6837\u7684\u4E0D\u540C\uFF1F\u6C49\u521D\u7EDF\u6CBB\u8005\u8FD9\u6837\u505A\u7684\u76EE\u7684\u662F\u4EC0\u4E48\uFF1F\uFF084 \u5206\uFF09",
            answer: "\u4E0D\u540C\uFF1A\u79E6\u671D\u8D4B\u7A0E\u5FAD\u5F79\u6C89\u91CD\u3001\u5211\u6CD5\u4E25\u9177\uFF0C\u767E\u59D3\u56F0\u82E6\uFF1B\u6C49\u521D\u51CF\u8F7B\u8D4B\u7A0E\uFF08\u5341\u4E94\u7A0E\u4E00\uFF09\u3001\u7EA6\u6CD5\u7701\u7981\uFF0C\u5B9E\u884C\u4F11\u517B\u751F\u606F\u3002\u76EE\u7684\uFF1A\u5438\u53D6\u79E6\u671D\u901F\u4EA1\u7684\u6559\u8BAD\uFF0C\u6062\u590D\u751F\u4EA7\u3001\u7A33\u5B9A\u793E\u4F1A\uFF0C\u5DE9\u56FA\u7EDF\u6CBB\u3002",
            rubric: ["\u6307\u51FA\u79E6\u7684\u66B4\u653F", "\u6307\u51FA\u6C49\u521D\u8F7B\u5FAD\u8584\u8D4B/\u4F11\u517B\u751F\u606F", "\u7B54\u51FA\u5438\u53D6\u79E6\u4EA1\u6559\u8BAD", "\u7B54\u51FA\u6062\u590D\u7ECF\u6D4E\u3001\u5DE9\u56FA\u7EDF\u6CBB"],
