      "\u7ECF\u6D4E\u91CD\u5FC3\u5357\u79FB\u7684\u56E0\u679C\u94FE\uFF1A\u5317\u65B9\u6218\u4E71\u4E0E\u4EBA\u53E3\u5357\u8FC1\uFF08\u5E26\u6765\u52B3\u52A8\u529B\u4E0E\u5148\u8FDB\u6280\u672F\uFF09\uFF0B\u5357\u65B9\u81EA\u7136\u6761\u4EF6\u4F18\u8D8A\u3001\u793E\u4F1A\u76F8\u5BF9\u5B89\u5B9A \u2192 \u5357\u65B9\u7ECF\u6D4E\u53D1\u5C55 \u2192 \u5357\u5B8B\u65F6\u7ECF\u6D4E\u91CD\u5FC3\u5357\u79FB\u5B8C\u6210\uFF0C\u51FA\u73B0\u300C\u56FD\u5BB6\u6839\u672C\uFF0C\u4EF0\u7ED9\u4E1C\u5357\u300D\u7684\u5C40\u9762\u3002",
      "\u5143\u671D\u7684\u884C\u7701\u5236\u5EA6\u662F\u6211\u56FD\u7701\u7EA7\u884C\u653F\u533A\u5212\u7684\u5F00\u7AEF\uFF1B\u5BA3\u653F\u9662\u4E0E\u6F8E\u6E56\u5DE1\u68C0\u53F8\u7684\u8BBE\u7F6E\u8BF4\u660E\u897F\u85CF\u3001\u53F0\u6E7E\u5730\u533A\u81EA\u53E4\u4EE5\u6765\u5C31\u662F\u4E2D\u56FD\u9886\u571F\u7684\u4E00\u90E8\u5206\u3002",
      "\u5B8B\u5143\u65F6\u671F\u4E09\u5927\u53D1\u660E\u7ECF\u7531\u963F\u62C9\u4F2F\u4EBA\u4F20\u5165\u6B27\u6D32\uFF0C\u4E3A\u6B27\u6D32\u7684\u6587\u827A\u590D\u5174\u4E0E\u5730\u7406\u5927\u53D1\u73B0\u63D0\u4F9B\u4E86\u91CD\u8981\u6761\u4EF6\uFF0C\u5145\u5206\u4F53\u73B0\u4E86\u4E2D\u56FD\u53E4\u4EE3\u79D1\u6280\u5BF9\u4E16\u754C\u6587\u660E\u7684\u8D21\u732E\u3002",
      "\u4E24\u5B8B\u4E0E\u5C11\u6570\u6C11\u65CF\u653F\u6743\u7684\u5173\u7CFB\u4EE5\u548C\u5E73\u5F80\u6765\u4E3A\u4E3B\u6D41\uFF1A\u6FB6\u6E0A\u4E4B\u76DF\u3001\u5B8B\u590F\u548C\u8BAE\u3001\u5B8B\u91D1\u548C\u8BAE\u867D\u5E26\u6709\u5C48\u8FB1\u8272\u5F69\uFF0C\u4F46\u5BA2\u89C2\u4E0A\u4FC3\u8FDB\u4E86\u8FB9\u5883\u8D38\u6613\u4E0E\u6C11\u65CF\u4EA4\u878D\u3002"
