        text: "\u300A\u5357\u4EAC\u6761\u7EA6\u300B\u7684\u5185\u5BB9\uFF1A\u5272\u9999\u6E2F\u5C9B\u7ED9\u82F1\u56FD\uFF1B\u8D54\u6B3E 2100 \u4E07\u94F6\u5143\uFF1B\u5F00\u653E\u5E7F\u5DDE\u3001\u53A6\u95E8\u3001\u798F\u5DDE\u3001\u5B81\u6CE2\u3001\u4E0A\u6D77\u4E94\u5904\u4E3A\u901A\u5546\u53E3\u5CB8\uFF1B\u82F1\u5546\u8FDB\u51FA\u53E3\u8D27\u7269\u5E94\u7EB3\u7A0E\u6B3E\u987B\u7ECF\u53CC\u65B9\u534F\u8BAE\uFF08\u534F\u5B9A\u5173\u7A0E\uFF09\u3002",
        explain: "\u7B54\u9898\u8981\u6309\u300C\u5272\u5730\u2014\u8D54\u6B3E\u2014\u901A\u5546\u2014\u5173\u7A0E\u300D\u56DB\u70B9\u9ED8\u5199\u3002\u5176\u4E2D\u534F\u5B9A\u5173\u7A0E\u7834\u574F\u4E86\u4E2D\u56FD\u5173\u7A0E\u81EA\u4E3B\u6743\uFF0C\u662F\u5217\u5F3A\u7ECF\u6D4E\u4FB5\u7565\u7684\u5173\u952E\u6761\u6B3E\uFF0C\u6700\u7231\u8003\u3002"
