    materials: [
      {
        id: "h8a-u5-m1",
        material: "\u3010\u6750\u6599\u4E00\u3011\u8FB9\u754C\u7EA2\u65D7\u5B50\u59CB\u7EC8\u4E0D\u5012\uFF0C\u4E0D\u4F46\u8868\u793A\u4E86\u5171\u4EA7\u515A\u7684\u529B\u91CF\uFF0C\u800C\u4E14\u8868\u793A\u4E86\u7EDF\u6CBB\u9636\u7EA7\u7684\u7834\u4EA7\uFF0C\u5728\u5168\u56FD\u653F\u6CBB\u4E0A\u6709\u91CD\u5927\u7684\u610F\u4E49\u3002\u2014\u2014\u6BDB\u6CFD\u4E1C\u300A\u4E95\u5188\u5C71\u7684\u6597\u4E89\u300B\uFF081928 \u5E74\uFF09\n\u3010\u6750\u6599\u4E8C\u3011\u7EA2\u519B\u4E0D\u6015\u8FDC\u5F81\u96BE\uFF0C\u4E07\u6C34\u5343\u5C71\u53EA\u7B49\u95F2\u3002\u4E94\u5CAD\u9036\u8FE4\u817E\u7EC6\u6D6A\uFF0C\u4E4C\u8499\u78C5\u7934\u8D70\u6CE5\u4E38\u3002\u91D1\u6C99\u6C34\u62CD\u4E91\u5D16\u6696\uFF0C\u5927\u6E21\u6865\u6A2A\u94C1\u7D22\u5BD2\u3002\u66F4\u559C\u5CB7\u5C71\u5343\u91CC\u96EA\uFF0C\u4E09\u519B\u8FC7\u540E\u5C3D\u5F00\u989C\u3002\u2014\u2014\u6BDB\u6CFD\u4E1C\u300A\u4E03\u5F8B\xB7\u957F\u5F81\u300B\uFF081935 \u5E74 10 \u6708\uFF09\n\u3010\u6750\u6599\u4E09\u3011\u9075\u4E49\u4F1A\u8BAE\u96C6\u4E2D\u5168\u529B\u89E3\u51B3\u4E86\u5F53\u65F6\u5177\u6709\u51B3\u5B9A\u610F\u4E49\u7684\u519B\u4E8B\u548C\u7EC4\u7EC7\u95EE\u9898\u2026\u2026\u5F00\u59CB\u786E\u7ACB\u4EE5\u6BDB\u6CFD\u4E1C\u540C\u5FD7\u4E3A\u4E3B\u8981\u4EE3\u8868\u7684\u9A6C\u514B\u601D\u4E3B\u4E49\u6B63\u786E\u8DEF\u7EBF\u5728\u515A\u4E2D\u592E\u7684\u9886\u5BFC\u5730\u4F4D\u3002",
        questions: [
          {
            id: "h8a-u5-m1-q1",
            stem: "\uFF081\uFF09\u6750\u6599\u4E00\u4E2D\u7684\u300C\u8FB9\u754C\u7EA2\u65D7\u5B50\u300D\u6307\u4EC0\u4E48\uFF1F\u7ED3\u5408\u6240\u5B66\u8BF4\u660E\u4E2D\u56FD\u5171\u4EA7\u515A\u4E3A\u4EC0\u4E48\u5FC5\u987B\u8D70\u8FD9\u6761\u9053\u8DEF\u3002\uFF086 \u5206\uFF09",
            answer: "\u300C\u8FB9\u754C\u7EA2\u65D7\u5B50\u300D\u6307\u4E95\u5188\u5C71\u9769\u547D\u6839\u636E\u5730\uFF08\u519C\u6751\u9769\u547D\u6839\u636E\u5730\uFF09\u4EE5\u53CA\u519C\u6751\u5305\u56F4\u57CE\u5E02\u3001\u6B66\u88C5\u593A\u53D6\u653F\u6743\u7684\u9769\u547D\u9053\u8DEF\u3002\u539F\u56E0\uFF1A\u4E2D\u56FD\u662F\u534A\u6B96\u6C11\u5730\u534A\u5C01\u5EFA\u793E\u4F1A\uFF0C\u653F\u6CBB\u7ECF\u6D4E\u53D1\u5C55\u4E0D\u5E73\u8861\uFF1B\u53CD\u52A8\u7EDF\u6CBB\u529B\u91CF\u4E3B\u8981\u96C6\u4E2D\u5728\u4E2D\u5FC3\u57CE\u5E02\uFF0C\u519C\u6751\u5730\u533A\u654C\u4EBA\u529B\u91CF\u76F8\u5BF9\u8584\u5F31\uFF1B\u519C\u6751\u6709\u5E7F\u5927\u519C\u6C11\u7FA4\u4F17\uFF0C\u5177\u5907\u5EFA\u7ACB\u9769\u547D\u6839\u636E\u5730\u7684\u6761\u4EF6\uFF1B\u5357\u660C\u8D77\u4E49\u3001\u79CB\u6536\u8D77\u4E49\u7B49\u57CE\u5E02\u6B66\u88C5\u8D77\u4E49\u53D7\u632B\uFF0C\u8BC1\u660E\u7167\u642C\u4FC4\u56FD\u57CE\u5E02\u4E2D\u5FC3\u7684\u9053\u8DEF\u5728\u4E2D\u56FD\u884C\u4E0D\u901A\uFF0C\u5FC5\u987B\u7ED3\u5408\u672C\u56FD\u56FD\u60C5\u628A\u5DE5\u4F5C\u91CD\u5FC3\u8F6C\u5411\u519C\u6751\u3002",
            rubric: ["\u7B54\u51FA\u4E95\u5188\u5C71\u9769\u547D\u6839\u636E\u5730/\u519C\u6751\u5305\u56F4\u57CE\u5E02\u9053\u8DEF", "\u7B54\u51FA\u534A\u6B96\u6C11\u5730\u534A\u5C01\u5EFA\u793E\u4F1A\u3001\u57CE\u5E02\u654C\u4EBA\u529B\u91CF\u5F3A\u5927", "\u7B54\u51FA\u519C\u6751\u654C\u4EBA\u529B\u91CF\u8584\u5F31\u3001\u7FA4\u4F17\u57FA\u7840\u597D", "\u7B54\u51FA\u57CE\u5E02\u8D77\u4E49\u53D7\u632B\u3001\u7167\u642C\u5916\u56FD\u9053\u8DEF\u884C\u4E0D\u901A"],
            tags: ["\u4E95\u5188\u5C71\u9053\u8DEF", "\u5386\u53F2\u89E3\u91CA"]
          },
          {
            id: "h8a-u5-m1-q2",
            stem: "\uFF082\uFF09\u6750\u6599\u4E8C\u53CD\u6620\u4E86\u600E\u6837\u7684\u9769\u547D\u7CBE\u795E\uFF1F\u4F9D\u636E\u6750\u6599\u4E09\u8BF4\u660E\u9075\u4E49\u4F1A\u8BAE\u7684\u5386\u53F2\u5730\u4F4D\u3002\uFF085 \u5206\uFF09",
            answer: "\u9769\u547D\u7CBE\u795E\uFF1A\u300A\u4E03\u5F8B\xB7\u957F\u5F81\u300B\u8868\u73B0\u51FA\u7EA2\u519B\u4E0D\u6015\u8270\u96BE\u9669\u963B\u3001\u9769\u547D\u4E50\u89C2\u4E3B\u4E49\u548C\u575A\u5B9A\u7406\u60F3\u4FE1\u5FF5\u7684\u7CBE\u795E\uFF0C\u5373\u957F\u5F81\u7CBE\u795E\u2014\u2014\u628A\u5168\u56FD\u4EBA\u6C11\u548C\u4E2D\u534E\u6C11\u65CF\u7684\u6839\u672C\u5229\u76CA\u770B\u5F97\u9AD8\u4E8E\u4E00\u5207\uFF0C\u575A\u5B9A\u9769\u547D\u7684\u7406\u60F3\u548C\u4FE1\u5FF5\uFF1B\u4E0D\u6015\u727A\u7272\u3001\u8270\u82E6\u594B\u6597\u3001\u56E2\u7ED3\u4E92\u52A9\u3002\u5386\u53F2\u5730\u4F4D\uFF1A\u9075\u4E49\u4F1A\u8BAE\u5F00\u59CB\u786E\u7ACB\u4EE5\u6BDB\u6CFD\u4E1C\u540C\u5FD7\u4E3A\u4E3B\u8981\u4EE3\u8868\u7684\u9A6C\u514B\u601D\u4E3B\u4E49\u6B63\u786E\u8DEF\u7EBF\u5728\u515A\u4E2D\u592E\u7684\u9886\u5BFC\u5730\u4F4D\uFF0C\u662F\u515A\u7684\u5386\u53F2\u4E0A\u751F\u6B7B\u6538\u5173\u7684\u8F6C\u6298\u70B9\uFF0C\u662F\u4E2D\u56FD\u5171\u4EA7\u515A\u4ECE\u5E7C\u5E74\u8D70\u5411\u6210\u719F\u7684\u6807\u5FD7\uFF0C\u4E3A\u957F\u5F81\u7684\u80DC\u5229\u548C\u4E2D\u56FD\u9769\u547D\u7684\u53D1\u5C55\u5960\u5B9A\u4E86\u57FA\u7840\u3002",
            rubric: ["\u7B54\u51FA\u4E0D\u6015\u727A\u7272\u3001\u8270\u82E6\u594B\u6597\u7684\u4E50\u89C2\u7CBE\u795E", "\u7B54\u51FA\u575A\u5B9A\u7684\u7406\u60F3\u4FE1\u5FF5/\u957F\u5F81\u7CBE\u795E", "\u7B54\u51FA\u786E\u7ACB\u6B63\u786E\u8DEF\u7EBF\u7684\u9886\u5BFC\u5730\u4F4D", "\u7B54\u51FA\u300C\u751F\u6B7B\u6538\u5173\u7684\u8F6C\u6298\u70B9\u300D", "\u7B54\u51FA\u4ECE\u5E7C\u5E74\u8D70\u5411\u6210\u719F\u7684\u6807\u5FD7"],
            tags: ["\u957F\u5F81", "\u9075\u4E49\u4F1A\u8BAE"]
          }
        ]
      }
    ],
