            stem: "\uFF081\uFF09\u4F9D\u636E\u6750\u6599\u4E00\uFF0C\u8BF4\u660E\u6BDB\u6CFD\u4E1C\u63D0\u51FA\u4E86\u600E\u6837\u7684\u6297\u6218\u4E3B\u5F20\uFF1B\u7ED3\u5408\u6750\u6599\u4E8C\u6307\u51FA\u4E2D\u56FD\u5171\u4EA7\u515A\u4E3A\u5EFA\u7ACB\u6297\u65E5\u6C11\u65CF\u7EDF\u4E00\u6218\u7EBF\u4F5C\u51FA\u4E86\u54EA\u4E9B\u52AA\u529B\u3002\uFF086 \u5206\uFF09",
            answer: "\u4E3B\u5F20\uFF1A\u6297\u65E5\u6218\u4E89\u5FC5\u987B\u662F\u5168\u6C11\u65CF\u7684\u6297\u6218\uFF0C\u8981\u5E7F\u6CDB\u53D1\u52A8\u548C\u4F9D\u9760\u4EBA\u6C11\u7FA4\u4F17\uFF0C\u5B9E\u884C\u5168\u9762\u6297\u6218\u8DEF\u7EBF\uFF08\u300A\u8BBA\u6301\u4E45\u6218\u300B\u8FD8\u6307\u51FA\u6297\u6218\u662F\u6301\u4E45\u6218\uFF0C\u6700\u540E\u80DC\u5229\u5C5E\u4E8E\u4E2D\u56FD\uFF09\u3002\u52AA\u529B\uFF1A\u53D1\u8868\u56FD\u5171\u5408\u4F5C\u5BA3\u8A00\uFF0C\u8868\u793A\u613F\u4E3A\u5F7B\u5E95\u5B9E\u73B0\u4E09\u6C11\u4E3B\u4E49\u800C\u594B\u6597\uFF1B\u53D6\u6D88\u63A8\u7FFB\u56FD\u6C11\u515A\u653F\u6743\u7684\u66B4\u52A8\u653F\u7B56\uFF0C\u53D6\u6D88\u82CF\u7EF4\u57C3\u653F\u5E9C\uFF0C\u628A\u7EA2\u519B\u6539\u7F16\u4E3A\u56FD\u6C11\u9769\u547D\u519B\uFF0C\u4E3B\u52A8\u4F5C\u51FA\u8BA9\u6B65\uFF1B\u4FC3\u6210\u897F\u5B89\u4E8B\u53D8\u7684\u548C\u5E73\u89E3\u51B3\uFF0C\u6700\u7EC8\u63A8\u52A8\u56FD\u5171\u5B9E\u73B0\u7B2C\u4E8C\u6B21\u5408\u4F5C\uFF0C\u6B63\u5F0F\u5EFA\u7ACB\u6297\u65E5\u6C11\u65CF\u7EDF\u4E00\u6218\u7EBF\u3002",
