        text: "\u89E3\u653E\u6218\u4E89\u80DC\u5229\u7684\u539F\u56E0\uFF1A\u4E2D\u56FD\u5171\u4EA7\u515A\u7684\u6B63\u786E\u9886\u5BFC\u4E0E\u6B63\u786E\u7684\u6218\u7565\u6218\u672F\uFF08\u96C6\u4E2D\u4F18\u52BF\u5175\u529B\u3001\u8FD0\u52A8\u6218\u3001\u6B7C\u706D\u6218\uFF09\uFF1B\u4EBA\u6C11\u7FA4\u4F17\u7684\u5E7F\u6CDB\u652F\u6301\uFF08\u571F\u6539\u8C03\u52A8\u519C\u6C11\u79EF\u6781\u6027\uFF0C\u300C\u4EBA\u6C11\u7FA4\u4F17\u7528\u5C0F\u8F66\u63A8\u51FA\u6765\u7684\u80DC\u5229\u300D\uFF09\uFF1B\u4EBA\u6C11\u89E3\u653E\u519B\u82F1\u52C7\u4F5C\u6218\uFF1B\u56FD\u6C11\u515A\u653F\u6CBB\u5B64\u7ACB\u3001\u7ECF\u6D4E\u5D29\u6E83\u3001\u5931\u53BB\u6C11\u5FC3\u3002",
