        text: "\u897F\u85CF\u548C\u5E73\u89E3\u653E\uFF081951 \u5E74\uFF09\u7684\u610F\u4E49\uFF1A\u7956\u56FD\u5927\u9646\u83B7\u5F97\u7EDF\u4E00\uFF0C\u5404\u65CF\u4EBA\u6C11\u5B9E\u73B0\u4E86\u5927\u56E2\u7ED3\u3002",
