    conclusions: [
      "\u82F1\u7F8E\u6CD5\u4E09\u56FD\u8D44\u4EA7\u9636\u7EA7\u9769\u547D\u90FD\u4EE5\u6CD5\u5F8B\u6587\u732E\u7684\u5F62\u5F0F\u628A\u9769\u547D\u6210\u679C\u56FA\u5B9A\u4E0B\u6765\uFF08\u82F1\u56FD\u300A\u6743\u5229\u6CD5\u6848\u300B\u3001\u7F8E\u56FD 1787 \u5E74\u5BAA\u6CD5\u3001\u6CD5\u56FD\u300A\u4EBA\u6743\u5BA3\u8A00\u300B\u4E0E\u300A\u62FF\u7834\u4ED1\u6CD5\u5178\u300B\uFF09\uFF0C\u8BF4\u660E**\u7528\u6CD5\u5F8B\u786E\u7ACB\u5236\u5EA6\u662F\u8FD1\u4EE3\u653F\u6CBB\u6587\u660E\u7684\u91CD\u8981\u7279\u5F81**\u3002",
      "\u82F1\u56FD\u786E\u7ACB\u7684\u662F**\u541B\u4E3B\u7ACB\u5BAA\u5236**\uFF08\u4FDD\u7559\u56FD\u738B\u3001\u8BAE\u4F1A\u638C\u6743\uFF09\uFF0C\u7F8E\u56FD\u786E\u7ACB\u7684\u662F**\u8054\u90A6\u5171\u548C\u5236**\uFF08\u6CA1\u6709\u56FD\u738B\u3001\u603B\u7EDF\u7531\u9009\u4E3E\u4EA7\u751F\uFF09\uFF0C\u6CD5\u56FD\u5927\u9769\u547D\u5219\u5F7B\u5E95\u6467\u6BC1\u4E86\u541B\u4E3B\u4E13\u5236\u2014\u2014\u4E09\u56FD\u9009\u62E9\u4E86\u4E0D\u540C\u7684\u653F\u4F53\uFF0C\u4F46\u90FD\u5EFA\u7ACB\u4E86\u8D44\u4EA7\u9636\u7EA7\u7684\u7EDF\u6CBB\u3002",
      "\u4E09\u56FD\u9769\u547D\u90FD\u4F53\u73B0\u4E86\u542F\u8499\u601D\u60F3\u7684\u5F71\u54CD\uFF1A\u81EA\u7531\u3001\u5E73\u7B49\u3001\u6C11\u4E3B\u3001\u6CD5\u6CBB\u3001\u5206\u6743\u5236\u8861\u7B49\u89C2\u5FF5\u4ECE\u6B64\u6DF1\u5165\u4EBA\u5FC3\u3002",
      "\u8BC4\u4EF7\u8D44\u4EA7\u9636\u7EA7\u9769\u547D\u8981\u770B\u5230\u4E24\u9762\uFF1A\u5B83\u4EEC\u63A8\u7FFB\u4E86\u5C01\u5EFA\u4E13\u5236\u6216\u6B96\u6C11\u7EDF\u6CBB\uFF0C\u4FC3\u8FDB\u4E86\u8D44\u672C\u4E3B\u4E49\u7684\u53D1\u5C55\uFF1B\u4F46\u4E5F\u4FDD\u7559\u4E86\u5974\u96B6\u5236\u3001\u79CD\u65CF\u6B67\u89C6\u7B49\u5C40\u9650\uFF0C\u9769\u547D\u6210\u679C\u4E3B\u8981\u7531\u8D44\u4EA7\u9636\u7EA7\u4EAB\u6709\u3002",
      "\u4E2D\u5916\u8054\u52A8\uFF1A\u82F1\u7F8E\u6CD5\u9769\u547D\uFF0817\u201418 \u4E16\u7EAA\uFF09\u53D1\u751F\u65F6\uFF0C\u4E2D\u56FD\u6B63\u5904\u4E8E\u6E05\u671D\u524D\u671F\uFF0C\u541B\u4E3B\u4E13\u5236\u7A7A\u524D\u5F3A\u5316\u3001\u95ED\u5173\u9501\u56FD\uFF0C\u4E0E\u897F\u65B9\u300C\u4EE5\u6CD5\u5F8B\u9650\u5236\u738B\u6743\u300D\u7684\u6F6E\u6D41\u5F62\u6210\u9C9C\u660E\u5BF9\u7167\uFF1B19 \u4E16\u7EAA\u672B\uFF0C\u897F\u65B9\u542F\u8499\u601D\u60F3\u4E0E\u653F\u6CBB\u5236\u5EA6\u4F20\u5165\u4E2D\u56FD\uFF0C\u6210\u4E3A\u620A\u620C\u53D8\u6CD5\u4E0E\u8F9B\u4EA5\u9769\u547D\u7684\u91CD\u8981\u601D\u60F3\u6B66\u5668\u3002"
    ],
