        text: "\u5DE5\u4E1A\u9769\u547D\u9020\u6210\u4E86\u5DE8\u5927\u5F71\u54CD\uFF1A\u6781\u5927\u5730\u63D0\u9AD8\u4E86\u793E\u4F1A\u751F\u4EA7\u529B\uFF0C\u4EBA\u7C7B\u8FDB\u5165\u300C\u84B8\u6C7D\u65F6\u4EE3\u300D\uFF1B\u673A\u5668\u751F\u4EA7\u53D6\u4EE3\u624B\u5DE5\u52B3\u52A8\uFF0C\u5DE5\u5382\u5236\u5EA6\u5F62\u6210\uFF1B\u793E\u4F1A\u65E5\u76CA\u5206\u88C2\u4E3A\u5DE5\u4E1A\u8D44\u4EA7\u9636\u7EA7\u548C\u5DE5\u4E1A\u65E0\u4EA7\u9636\u7EA7\u4E24\u5927\u5BF9\u7ACB\u9636\u7EA7\uFF1B\u57CE\u5E02\u5316\u8FDB\u7A0B\u52A0\u5FEB\uFF0C\u540C\u65F6\u4E5F\u5E26\u6765\u73AF\u5883\u6C61\u67D3\u7B49\u95EE\u9898\u3002",
