        right: "\u5E9F\u85E9\u7F6E\u53BF\u662F\u653F\u6CBB\u63AA\u65BD\uFF08\u5E9F\u9664\u85E9\u56FD\u3001\u8BBE\u7F6E\u5E9C\u53BF\uFF0C\u52A0\u5F3A\u4E2D\u592E\u96C6\u6743\uFF09\uFF1B\u6B96\u4EA7\u5174\u4E1A\u662F\u7ECF\u6D4E\u63AA\u65BD\uFF08\u5F15\u8FDB\u897F\u65B9\u6280\u672F\u3001\u53D1\u5C55\u8FD1\u4EE3\u5DE5\u4E1A\uFF09\u3002",
        why: "\u6750\u6599\u9898\u8981\u6C42\u300C\u6309\u653F\u6CBB\u3001\u7ECF\u6D4E\u3001\u519B\u4E8B\u3001\u6587\u5316\u5206\u7C7B\u6982\u62EC\u63AA\u65BD\u300D\uFF0C\u6DF7\u5728\u4E00\u8D77\u5C31\u4E22\u5206\u3002"
