    conclusions: [
      "\u51B7\u6218\u662F\u4E8C\u6218\u540E\u7F8E\u82CF\u56FD\u5BB6\u5229\u76CA\u548C\u610F\u8BC6\u5F62\u6001\u5BF9\u7ACB\u51B2\u7A81\u7684\u4EA7\u7269\uFF1B\u4E24\u6781\u683C\u5C40\u4E0B\u7F8E\u82CF\u52BF\u5747\u529B\u654C\uFF0C\u907F\u514D\u4E86\u65B0\u7684\u4E16\u754C\u5927\u6218\u7206\u53D1\uFF0C\u4F46\u957F\u671F\u5A01\u80C1\u4E16\u754C\u548C\u5E73\u4E0E\u5404\u56FD\u53D1\u5C55\u3002",
      "\u82CF\u8054\u89E3\u4F53\u7684\u6839\u672C\u539F\u56E0\u662F\u9AD8\u5EA6\u96C6\u4E2D\u7684\u653F\u6CBB\u7ECF\u6D4E\u4F53\u5236\uFF08\u65AF\u5927\u6797\u6A21\u5F0F\uFF09\u7684\u5F0A\u7AEF\u957F\u671F\u5F97\u4E0D\u5230\u7EA0\u6B63\uFF1B\u897F\u65B9\u56FD\u5BB6\u7684\u300C\u548C\u5E73\u6F14\u53D8\u300D\u53EA\u662F\u5916\u90E8\u539F\u56E0\u3002",
      "\u82CF\u8054\u89E3\u4F53\u3001\u4E1C\u6B27\u5267\u53D8\u8BF4\u660E\u82CF\u8054\u6A21\u5F0F\u7684\u5931\u8D25\uFF0C\u793E\u4F1A\u4E3B\u4E49\u8FD0\u52A8\u906D\u53D7\u4E25\u91CD\u632B\u6298\uFF1B\u4F46\u4E2D\u56FD\u7279\u8272\u793E\u4F1A\u4E3B\u4E49\u7684\u6210\u529F\u8BC1\u660E\u793E\u4F1A\u4E3B\u4E49\u5236\u5EA6\u5177\u6709\u5F3A\u5927\u7684\u751F\u547D\u529B\u2014\u2014\u6539\u9769\u5FC5\u987B\u575A\u6301\u6B63\u786E\u65B9\u5411\u3001\u7ACB\u8DB3\u672C\u56FD\u56FD\u60C5\u3002",
      "\u6539\u9769\u5FC5\u987B\u575A\u6301\u6B63\u786E\u65B9\u5411\u3001\u7ACB\u8DB3\u56FD\u60C5\uFF1A\u6208\u5C14\u5DF4\u4E54\u592B\u6539\u9769\u80CC\u79BB\u793E\u4F1A\u4E3B\u4E49\u65B9\u5411\u3001\u653E\u5F03\u515A\u7684\u9886\u5BFC\uFF0C\u6700\u7EC8\u5BFC\u81F4\u56FD\u5BB6\u89E3\u4F53\uFF1B\u4E2D\u56FD\u6539\u9769\u5F00\u653E\u575A\u6301\u515A\u7684\u9886\u5BFC\u4E0E\u793E\u4F1A\u4E3B\u4E49\u9053\u8DEF\uFF0C\u53D6\u5F97\u5DE8\u5927\u6210\u5C31\u3002",
      "\u4E16\u754C\u683C\u5C40\u591A\u6781\u5316\u8D8B\u52BF\u5728\u51B7\u6218\u7ED3\u675F\u540E\u52A0\u901F\u53D1\u5C55\uFF1B\u548C\u5E73\u4E0E\u53D1\u5C55\u662F\u5F53\u4ECA\u65F6\u4EE3\u7684\u4E3B\u9898\uFF0C\u5404\u56FD\u5E94\u52A0\u5F3A\u5408\u4F5C\u3001\u5171\u540C\u53D1\u5C55\u3002",
      "\u4E9A\u975E\u62C9\u56FD\u5BB6\u7684\u72EC\u7ACB\u4E0E\u53D1\u5C55\u51B2\u51FB\u4E86\u6B96\u6C11\u4F53\u7CFB\uFF0C\u63A8\u52A8\u4E86\u4E16\u754C\u591A\u6781\u5316\uFF0C\u53D1\u5C55\u4E2D\u56FD\u5BB6\u6210\u4E3A\u56FD\u9645\u821E\u53F0\u4E0A\u7684\u91CD\u8981\u529B\u91CF\u3002"
    ],
