        type: "choice",
        stem: "\u4E0B\u5217\u6D0B\u52A1\u6D3E\u521B\u529E\u7684\u4F01\u4E1A\u4E2D\uFF0C\u5C5E\u4E8E\u4EE5\u300C\u6C42\u5BCC\u300D\u4E3A\u53E3\u53F7\u521B\u529E\u7684\u6C11\u7528\u5DE5\u4E1A\u7684\u662F",
