        right: "\u9075\u4E49\u4F1A\u8BAE\u5F00\u59CB\u786E\u7ACB\u7684\u662F\u4EE5\u6BDB\u6CFD\u4E1C\u540C\u5FD7\u4E3A\u4E3B\u8981\u4EE3\u8868\u7684\u9A6C\u514B\u601D\u4E3B\u4E49\u6B63\u786E\u8DEF\u7EBF\u5728\u515A\u4E2D\u592E\u7684\u9886\u5BFC\u5730\u4F4D\uFF1B\u786E\u7ACB\u6BDB\u6CFD\u4E1C\u601D\u60F3\u4E3A\u515A\u7684\u6307\u5BFC\u601D\u60F3\u662F 1945 \u5E74\u4E2D\u5171\u4E03\u5927\u3002",
        why: "\u300C\u786E\u7ACB\u9886\u5BFC\u5730\u4F4D\u300D\u4E0E\u300C\u786E\u7ACB\u4E3A\u6307\u5BFC\u601D\u60F3\u300D\u662F\u4E24\u4EF6\u4E8B\uFF0C\u5E74\u4EFD\u76F8\u5DEE\u5341\u5E74\uFF0C\u662F\u6781\u5E38\u89C1\u7684\u6DF7\u6DC6\u3002"
