          { item: "\u4E3B\u8981\u63AA\u65BD", left: "\u73ED\u7530\u6536\u6388\u6CD5\u3001\u5EFA\u7ACB\u4E2D\u592E\u96C6\u6743\uFF0C\u6548\u4EFF\u968B\u5510\u5236\u5EA6", right: "\u5E9F\u85E9\u7F6E\u53BF\u3001\u6B96\u4EA7\u5174\u4E1A\u3001\u5F81\u5175\u5236\u3001\u6587\u660E\u5F00\u5316" },
          { item: "\u793E\u4F1A\u6027\u8D28\u53D8\u5316", left: "\u7531\u5974\u96B6\u793E\u4F1A\u8FC7\u6E21\u5230\u5C01\u5EFA\u793E\u4F1A", right: "\u7531\u5C01\u5EFA\u793E\u4F1A\u8FC7\u6E21\u5230\u8D44\u672C\u4E3B\u4E49\u793E\u4F1A" },
          { item: "\u5171\u540C\u70B9", left: "\u90FD\u662F\u4E3B\u52A8\u5411\u5148\u8FDB\u6587\u660E\u5B66\u4E60\u3001\u4EE5\u6539\u9769\u65B9\u5F0F\u5B8C\u6210\u7684\u5236\u5EA6\u53D8\u9769", right: "\u540C\u5DE6" }
