            stem: "\uFF083\uFF09\u7EFC\u5408\u4E09\u5219\u6750\u6599\uFF0C\u8BF4\u660E\u6539\u9769\u8981\u53D6\u5F97\u6210\u529F\u9700\u8981\u5177\u5907\u54EA\u4E9B\u6761\u4EF6\u3002\uFF084 \u5206\uFF09",
            answer: "\u2460\u6539\u9769\u5FC5\u987B\u7ACB\u8DB3\u672C\u56FD\u56FD\u60C5\uFF0C\u4ECE\u5B9E\u9645\u51FA\u53D1\u3001\u5FAA\u5E8F\u6E10\u8FDB\uFF08\u4E2D\u56FD\u6539\u9769\u4ECE\u519C\u6751\u8D77\u6B65\uFF0C\u9010\u6B65\u63A8\u5411\u57CE\u5E02\uFF09\uFF1B\u2461\u5FC5\u987B\u9075\u5FAA\u5BA2\u89C2\u7ECF\u6D4E\u89C4\u5F8B\uFF0C\u5584\u4E8E\u628A\u56FD\u5BB6\u8C03\u8282\u4E0E\u5E02\u573A\u4F5C\u7528\u7ED3\u5408\u8D77\u6765\uFF08\u7F57\u65AF\u798F\u65B0\u653F\u3001\u793E\u4F1A\u4E3B\u4E49\u5E02\u573A\u7ECF\u6D4E\u4F53\u5236\uFF09\uFF1B\u2462\u5FC5\u987B\u6709\u6B63\u786E\u7684\u653F\u6CBB\u65B9\u5411\u4E0E\u575A\u5F3A\u7684\u9886\u5BFC\u6838\u5FC3\uFF0C\u575A\u6301\u793E\u4F1A\u4E3B\u4E49\u9053\u8DEF\uFF0C\u5FAA\u5E8F\u6E10\u8FDB\u5730\u63A8\u8FDB\u653F\u6CBB\u4F53\u5236\u6539\u9769\uFF08\u4E0E\u4E2D\u56FD\u6210\u529F\u7ECF\u9A8C\u5BF9\u6BD4\uFF0C\u82CF\u8054\u6539\u9769\u80CC\u79BB\u793E\u4F1A\u4E3B\u4E49\u65B9\u5411\u5BFC\u81F4\u89E3\u4F53\uFF09\uFF1B\u2463\u5FC5\u987B\u5173\u6CE8\u6C11\u751F\u3001\u5F97\u5230\u4EBA\u6C11\u7684\u652F\u6301\uFF08\u5BB6\u5EAD\u8054\u4EA7\u627F\u5305\u8D23\u4EFB\u5236\u8C03\u52A8\u4E86\u519C\u6C11\u7684\u751F\u4EA7\u79EF\u6781\u6027\uFF09\uFF1B\u2464\u5FC5\u987B\u5904\u7406\u597D\u6539\u9769\u3001\u53D1\u5C55\u3001\u7A33\u5B9A\u7684\u5173\u7CFB\uFF0C\u4FDD\u6301\u793E\u4F1A\u5B89\u5B9A\u3002",
