        right: "\u7F51\u4E0A\u4EA4\u5F80\u5177\u6709\u865A\u62DF\u6027\uFF0C\u5E26\u6709\u5F88\u591A\u4E0D\u786E\u5B9A\u56E0\u7D20\uFF1B\u7F51\u4E0A\u4EA4\u53CB\u8981\u7406\u6027\u8FA8\u522B\u3001\u614E\u91CD\u9009\u62E9\uFF0C\u589E\u5F3A\u81EA\u6211\u4FDD\u62A4\u610F\u8BC6\uFF0C\u4E0D\u8F7B\u6613\u900F\u9732\u4E2A\u4EBA\u4FE1\u606F\uFF0C\u4E0D\u8F7B\u6613\u4E0E\u7F51\u53CB\u89C1\u9762\uFF0C\u9047\u5230\u4FB5\u5BB3\u53CA\u65F6\u6C42\u52A9\u3002",
        why: "\u6750\u6599\u9898\u5E38\u8BBE\u300C\u7F51\u53CB\u7EA6\u89C1\u300D\u60C5\u5883\uFF0C\u7B54\u6848\u4E0D\u5199\u300C\u81EA\u6211\u4FDD\u62A4\u300D\u4E0E\u300C\u53CA\u65F6\u544A\u8BC9\u7236\u6BCD\u3001\u8001\u5E08\u6216\u62A5\u8B66\u300D\u5C31\u4F1A\u4E22\u5206\u3002"
