          { item: "\u5BF9\u4ED6\u4EBA\u7684\u6001\u5EA6", left: "\u5C0A\u91CD\u4ED6\u4EBA\uFF0C\u865A\u5FC3\u5411\u4ED6\u4EBA\u5B66\u4E60\uFF0C\u80FD\u542C\u53D6\u4E0D\u540C\u610F\u89C1", right: "\u81EA\u8D1F\uFF1A\u770B\u4E0D\u8D77\u522B\u4EBA\uFF0C\u542C\u4E0D\u8FDB\u4E0D\u540C\u610F\u89C1\uFF1B\u81EA\u5351\uFF1A\u4E0D\u6562\u4E0E\u4EBA\u4EA4\u5F80\uFF0C\u5BB3\u6015\u88AB\u6BD4\u8F83" },
          { item: "\u9762\u5BF9\u56F0\u96BE\u4E0E\u5931\u8D25", left: "\u6562\u4E8E\u5C1D\u8BD5\uFF0C\u628A\u632B\u6298\u5F53\u4F5C\u6210\u957F\u7684\u8D22\u5BCC\uFF0C\u575A\u6301\u628A\u4E8B\u60C5\u505A\u4E0B\u53BB", right: "\u81EA\u8D1F\uFF1A\u628A\u5931\u8D25\u5F52\u548E\u4E8E\u5916\u754C\uFF0C\u4E0D\u80AF\u53CD\u601D\uFF1B\u81EA\u5351\uFF1A\u8F7B\u6613\u653E\u5F03\uFF0C\u8BA4\u4E3A\u81EA\u5DF1\u300C\u80AF\u5B9A\u4E0D\u884C\u300D" },
          { item: "\u884C\u4E3A\u8868\u73B0", left: "\u4F1A\u7B54\u7684\u95EE\u9898\u6562\u4E8E\u4E3E\u624B\uFF0C\u4E3B\u52A8\u53C2\u52A0\u6D3B\u52A8\u3001\u5C55\u793A\u81EA\u5DF1", right: "\u81EA\u8D1F\uFF1A\u62A2\u7740\u8868\u73B0\u5374\u51C6\u5907\u4E0D\u8DB3\uFF1B\u81EA\u5351\uFF1A\u660E\u660E\u4F1A\u505A\u4E5F\u4E0D\u6562\u4E3E\u624B\u3001\u4E0D\u6562\u62A5\u540D" },
          { item: "\u7ED3\u679C", left: "\u6FC0\u53D1\u6F5C\u80FD\uFF0C\u4E0D\u65AD\u8FDB\u6B65\uFF0C\u662F\u6210\u529F\u7684\u57FA\u77F3", right: "\u81EA\u8D1F\u5BB9\u6613\u683D\u8DDF\u5934\uFF0C\u81EA\u5351\u9519\u5931\u953B\u70BC\u548C\u6210\u957F\u7684\u673A\u4F1A" }
