          { item: "\u5178\u578B\u8868\u73B0", left: "\u77E5\u5EC9\u803B\u3001\u61C2\u8363\u8FB1\uFF0C\u7EF4\u62A4\u4EBA\u683C\u5C0A\u4E25\uFF0C\u5C0A\u91CD\u4ED6\u4EBA\uFF0C\u770B\u5230\u81EA\u5DF1\u7684\u8FDB\u6B65\u4E0E\u957F\u5904", right: "\u6811\u7ACB\u76EE\u6807\u3001\u514B\u670D\u60F0\u6027\u3001\u62B5\u5236\u8BF1\u60D1\uFF0C\u523B\u82E6\u5B66\u4E60\u3001\u575A\u6301\u953B\u70BC\uFF0C\u6218\u80DC\u81EA\u6211\u3001\u8D85\u8D8A\u81EA\u6211" },
          { item: "\u4E3B\u8981\u4F5C\u7528", left: "\u8BA9\u4EBA\u5B88\u4F4F\u505A\u4EBA\u7684\u5E95\u7EBF\uFF0C\u83B7\u5F97\u4ED6\u4EBA\u7684\u5C0A\u91CD\uFF0C\u6562\u4E8E\u5C1D\u8BD5\u5E76\u575A\u6301\u4E0B\u53BB", right: "\u8BA9\u9752\u6625\u594B\u8FDB\u7684\u6B65\u4F10\u6C38\u4E0D\u505C\u606F\uFF0C\u9760\u575A\u5F3A\u7684\u610F\u5FD7\u3001\u8FDB\u53D6\u7684\u7CBE\u795E\u548C\u4E0D\u61C8\u7684\u575A\u6301\u4E0D\u65AD\u524D\u8FDB" },
          { item: "\u7F3A\u5931\u65F6\u7684\u540E\u679C", left: "\u6CA1\u6709\u81EA\u5C0A\u5BB9\u6613\u968F\u6CE2\u9010\u6D41\u3001\u5931\u53BB\u5E95\u7EBF\uFF1B\u6CA1\u6709\u81EA\u4FE1\u5BB9\u6613\u81EA\u5351\u9000\u7F29\uFF0C\u9519\u5931\u673A\u4F1A", right: "\u6CA1\u6709\u81EA\u5F3A\uFF0C\u518D\u597D\u7684\u60F3\u6CD5\u4E5F\u505C\u5728\u53E3\u5934\u4E0A\uFF0C\u7406\u60F3\u65E0\u6CD5\u5B9E\u73B0" },
          { item: "\u600E\u6837\u7EDF\u4E00", left: "\u4EE5\u81EA\u5C0A\u7ACB\u8EAB\u3001\u4EE5\u81EA\u4FE1\u7ACB\u5FD7", right: "\u4EE5\u81EA\u5F3A\u7ACB\u4E1A\uFF0C\u628A\u4E2A\u4EBA\u594B\u6597\u878D\u5165\u56FD\u5BB6\u53D1\u5C55\uFF0C\u4E0E\u7956\u56FD\u540C\u884C" }
