        explanation: "\u4EBA\u6C11\u6CD5\u9662\u4F9D\u6CD5\u5224\u5904\u5211\u7F5A\uFF0C\u4EE5\u56FD\u5BB6\u5F3A\u5236\u529B\u4E3A\u540E\u76FE\uFF0C\u76F4\u63A5\u4F53\u73B0\u6CD5\u5F8B\u9760\u56FD\u5BB6\u5F3A\u5236\u529B\u4FDD\u8BC1\u5B9E\u65BD\uFF0CC \u9879\u7B26\u5408\u3002A \u9879\u5C5E\u4E8E\u9053\u5FB7\u5021\u5BFC\uFF0C\u9760\u793E\u4F1A\u8206\u8BBA\u548C\u4EBA\u4EEC\u7684\u81EA\u89C9\uFF1BB \u9879\u5C5E\u4E8E\u5B66\u6821\u7EAA\u5F8B\u5904\u5206\uFF0C\u4E0D\u662F\u6CD5\u5F8B\u5236\u88C1\uFF1BD \u9879\u5C5E\u4E8E\u96C6\u4F53\u7EA6\u5B9A\u7684\u89C4\u5219\uFF0C\u9760\u540C\u5B66\u81EA\u89C9\u9075\u5B88\u3002",
        difficulty: 2,
        tags: ["\u6CD5\u5F8B\u7684\u7279\u5F81", "\u56FD\u5BB6\u5F3A\u5236\u529B"]
