        type: "choice",
        stem: "\u4E0B\u5217\u5173\u4E8E\u4E2A\u4EBA\u4E0E\u793E\u4F1A\u5173\u7CFB\u7684\u8868\u8FF0\uFF0C\u6B63\u786E\u7684\u662F",
