        explanation: "\u4E2A\u4EBA\u662F\u793E\u4F1A\u7684\u6709\u673A\u7EC4\u6210\u90E8\u5206\uFF0C\u4EBA\u7684\u8EAB\u4EFD\u662F\u5728\u793E\u4F1A\u5173\u7CFB\u4E2D\u786E\u5B9A\u7684\uFF1A\u540C\u4E00\u4E2A\u4EBA\u5728\u4E0D\u540C\u7684\u793E\u4F1A\u5173\u7CFB\u4E2D\u5177\u6709\u4E0D\u540C\u7684\u8EAB\u4EFD\u3002A \u9879\u9519\u5728\u300C\u4E0E\u751F\u4FF1\u6765\u3001\u4E0D\u4F1A\u53D8\u5316\u300D\uFF1BB\u3001D \u4E24\u9879\u5426\u8BA4\u4E2A\u4EBA\u5BF9\u793E\u4F1A\u7684\u4F9D\u8D56\uFF0C\u4EBA\u7684\u751F\u5B58\u548C\u53D1\u5C55\u79BB\u4E0D\u5F00\u793E\u4F1A\u3002",
        difficulty: 1,
