        text: "\u81EA\u7531\u4E0E\u89C4\u5219\u4E0D\u53EF\u5206\uFF1A\u81EA\u7531\u4E0D\u662F\u968F\u5FC3\u6240\u6B32\uFF0C\u5B83\u53D7\u9053\u5FB7\u3001\u7EAA\u5F8B\u3001\u6CD5\u5F8B\u7B49\u793E\u4F1A\u89C4\u5219\u7684\u7EA6\u675F\uFF1B\u793E\u4F1A\u89C4\u5219\u5212\u5B9A\u4E86\u81EA\u7531\u7684\u8FB9\u754C\uFF0C\u793E\u4F1A\u89C4\u5219\u662F\u4EBA\u4EEC\u4EAB\u6709\u81EA\u7531\u7684\u4FDD\u969C\u3002\u4EBA\u4EEC\u5EFA\u7ACB\u89C4\u5219\u7684\u76EE\u7684\u4E0D\u662F\u9650\u5236\u81EA\u7531\uFF0C\u800C\u662F\u4FDD\u8BC1\u6BCF\u4E2A\u4EBA\u4E0D\u8D8A\u8FC7\u81EA\u7531\u7684\u8FB9\u754C\uFF0C\u4FC3\u8FDB\u793E\u4F1A\u6709\u5E8F\u8FD0\u884C\u3002",
        explain: "\u8FD9\u662F\u672C\u5355\u5143\u5206\u503C\u6700\u9AD8\u7684\u4E00\u53E5\uFF0C\u8FA8\u6790\u9898\u51E0\u4E4E\u5FC5\u8003\u3002\u7B54\u300C\u89C4\u5219\u4E0E\u81EA\u7531\u7684\u5173\u7CFB\u300D\u5FC5\u987B\u51FA\u73B0\u4E09\u4E2A\u5173\u952E\u8BCD\uFF1A\u5212\u5B9A\u81EA\u7531\u7684\u8FB9\u754C\u3001\u4EBA\u4EEC\u4EAB\u6709\u81EA\u7531\u7684\u4FDD\u969C\u3001\u4E0D\u662F\u9650\u5236\u81EA\u7531\u800C\u662F\u4FDD\u8BC1\u4E0D\u8D8A\u8FC7\u8FB9\u754C\u3002\u5199\u6210\u300C\u89C4\u5219\u9650\u5236\u4E86\u81EA\u7531\u300D\u76F4\u63A5\u5224\u9519\u3002"
