        text: "\u5C0A\u91CD\u662F\u4EA4\u5F80\u7684\u8D77\u70B9\uFF0C\u5C0A\u91CD\u4ED6\u4EBA\u662F\u4E00\u4E2A\u4EBA\u5185\u5728\u4FEE\u517B\u7684\u5916\u5728\u8868\u73B0\uFF1B\u5C0A\u91CD\u4F7F\u793E\u4F1A\u751F\u6D3B\u548C\u8C10\u878D\u6D3D\u3002\u5C0A\u91CD\u4ED6\u4EBA\u8981\u79EF\u6781\u5173\u6CE8\u3001\u91CD\u89C6\u4ED6\u4EBA\uFF0C\u5E73\u7B49\u5BF9\u5F85\u4ED6\u4EBA\uFF0C\u5B66\u4F1A\u6362\u4F4D\u601D\u8003\uFF0C\u5B66\u4F1A\u6B23\u8D4F\u4ED6\u4EBA\u3002",
        explain: "\u60C5\u5883\u9898\u7ED9\u300C\u8D77\u7EF0\u53F7\u3001\u6253\u65AD\u522B\u4EBA\u53D1\u8A00\u3001\u53EA\u4E0E\u6210\u7EE9\u76F8\u5F53\u7684\u540C\u5B66\u4EA4\u5F80\u300D\u7B49\u6750\u6599\uFF0C\u95EE\u300C\u4F60\u600E\u6837\u770B\u5F85\u8FD9\u79CD\u884C\u4E3A\u300D\uFF0C\u7B54\u6CD5\u56FA\u5B9A\uFF1A\u5148\u5B9A\u6027\u4E3A\u4E0D\u5C0A\u91CD\u4ED6\u4EBA\uFF08\u4E0D\u5E73\u7B49\u5BF9\u5F85\u3001\u4E0D\u6362\u4F4D\u601D\u8003\uFF09\uFF0C\u518D\u8865\u4E0A\u5C0A\u91CD\u4ED6\u4EBA\u7684\u56DB\u70B9\u505A\u6CD5\uFF0C\u56DB\u70B9\u8981\u5199\u5168\u3002"
