            left: "\u6C11\u4E8B\u8BC9\u8BBC\u4E0D\u662F\u300C\u6C11\u544A\u5B98\u300D\uFF1B\u4EF2\u88C1\u4E0E\u4EBA\u6C11\u8C03\u89E3\u90FD\u4E0D\u662F\u8BC9\u8BBC",
            right: "\u884C\u653F\u8BC9\u8BBC\u4FD7\u79F0\u300C\u6C11\u544A\u5B98\u300D\uFF0C\u4E0D\u662F\u300C\u5B98\u544A\u6C11\u300D\uFF1B\u884C\u653F\u673A\u5173\u4E0D\u80FD\u4F5C\u4E3A\u884C\u653F\u8BC9\u8BBC\u7684\u539F\u544A\u8D77\u8BC9\u516C\u6C11"
