          {
            item: "\u5171\u540C\u8981\u6C42",
            left: "\u4F9D\u7167\u6CD5\u5F8B\u89C4\u5B9A\u72EC\u7ACB\u884C\u4F7F\u5BA1\u5224\u6743\uFF0C\u4E0D\u53D7\u884C\u653F\u673A\u5173\u3001\u793E\u4F1A\u56E2\u4F53\u548C\u4E2A\u4EBA\u7684\u5E72\u6D89\uFF1B\u575A\u6301\u516C\u6B63\u53F8\u6CD5\uFF0C\u4EE5\u4E8B\u5B9E\u4E3A\u6839\u636E\u3001\u4EE5\u6CD5\u5F8B\u4E3A\u51C6\u7EF3",
            right: "\u4F9D\u7167\u6CD5\u5F8B\u89C4\u5B9A\u72EC\u7ACB\u884C\u4F7F\u68C0\u5BDF\u6743\uFF0C\u4E0D\u53D7\u884C\u653F\u673A\u5173\u3001\u793E\u4F1A\u56E2\u4F53\u548C\u4E2A\u4EBA\u7684\u5E72\u6D89\uFF1B\u575A\u6301\u516C\u6B63\u53F8\u6CD5\uFF0C\u4EE5\u4E8B\u5B9E\u4E3A\u6839\u636E\u3001\u4EE5\u6CD5\u5F8B\u4E3A\u51C6\u7EF3"
          }
