            left: "\u56FD\u5BB6\u4E0D\u5206\u5927\u5C0F\u3001\u5F3A\u5F31\u3001\u8D2B\u5BCC\u4E00\u5F8B\u5E73\u7B49\uFF0C\u56FD\u9645\u4E0A\u7684\u4E8B\u7531\u5927\u5BB6\u5171\u540C\u5546\u91CF\u7740\u529E\uFF0C\u4E16\u754C\u524D\u9014\u547D\u8FD0\u7531\u5404\u56FD\u5171\u540C\u638C\u63E1",
            right: "\u4EE5\u5F3A\u51CC\u5F31\u3001\u4EE5\u5BCC\u538B\u8D2B\uFF0C\u628A\u81EA\u5DF1\u7684\u610F\u5FD7\u548C\u6807\u51C6\u5F3A\u52A0\u4E8E\u4EBA\uFF0C\u641E\u552F\u6211\u72EC\u5C0A"
