            point: "\u4EBA\u7C7B\u547D\u8FD0\u5171\u540C\u4F53\u3001\u5408\u4F5C\u5171\u8D62",
            answer: "\u5404\u56FD\u8981\u6811\u7ACB\u4EBA\u7C7B\u547D\u8FD0\u5171\u540C\u4F53\u610F\u8BC6\uFF0C\u575A\u6301\u5BF9\u8BDD\u534F\u5546\u3001\u5171\u5EFA\u5171\u4EAB\u3001\u5408\u4F5C\u5171\u8D62\u3001\u4EA4\u6D41\u4E92\u9274\u3001\u7EFF\u8272\u4F4E\u78B3\uFF0C\u5171\u540C\u5E94\u5BF9\u6C14\u5019\u53D8\u5316\u3001\u8D2B\u56F0\u3001\u516C\u5171\u536B\u751F\u7B49\u5168\u7403\u6027\u6311\u6218\uFF1B\u5C0A\u91CD\u5F7C\u6B64\u6838\u5FC3\u5229\u76CA\u548C\u91CD\u5927\u5173\u5207\uFF0C\u575A\u6301\u901A\u8FC7\u548C\u5E73\u65B9\u5F0F\u89E3\u51B3\u4E89\u7AEF\uFF0C\u53CD\u5BF9\u9738\u6743\u4E3B\u4E49\u548C\u5F3A\u6743\u653F\u6CBB\uFF0C\u63A8\u52A8\u5168\u7403\u6CBB\u7406\u4F53\u7CFB\u671D\u7740\u66F4\u52A0\u516C\u6B63\u5408\u7406\u7684\u65B9\u5411\u53D1\u5C55\u3002"
