        explain: "\u5F88\u591A\u5B66\u751F\u4ECE\u5934\u5230\u5C3E\u53EA\u8BFB\u6750\u6599\u3001\u4E0D\u8BFB\u8BBE\u95EE\uFF0C\u8BFB\u5B8C\u4ECD\u4E0D\u77E5\u9053\u8981\u7B54\u4EC0\u4E48\u3002\u5148\u8BFB\u8BBE\u95EE\u80FD\u5E26\u7740\u95EE\u9898\u53BB\u7B5B\u6750\u6599\uFF0C\u8BFB\u7684\u65F6\u5019\u5C31\u77E5\u9053\u54EA\u4E9B\u53E5\u5B50\u662F\u6709\u7528\u7684\u8BC1\u636E\uFF0C\u6548\u7387\u4E0E\u51C6\u786E\u7387\u90FD\u4F1A\u660E\u663E\u63D0\u9AD8\u3002"
