// src/data/physics/modules/heat.ts
function thermoScale(x, y, h, minT, maxT, step) {
  const bottom = y + h;
  const span = h - 5.2;
  const out = [];
  for (let T = minT; T <= maxT + 1e-9; T += step) {
    const yy = bottom - span * (T - minT) / (maxT - minT);
    out.push({ t: "line", x1: x - 5.4, y1: yy, x2: x - 1.6, y2: yy, tone: "muted", width: 0.35 });
    out.push({
      t: "text",
      x: x - 6.4,
      y: yy,
      text: T === maxT ? `${T} \u2103` : `${T}`,
      anchor: "end",
      size: 3.4,
      tone: "muted"
    });
  }
  return out;
}
function readingThermometer(id, title, readT, maxT, step, x, y, h) {
  return {
    id,
    title,
    caption: `\u5DE6\u4FA7\u662F\u523B\u5EA6\u503C\uFF0C\u5206\u5EA6\u503C 1 \u2103\uFF0C\u6DB2\u67F1\u9876\u7AEF\u505C\u5728 ${readT} \u2103 \u5904`,
    view: "tall",
    alt: `\u4E00\u652F\u7AD6\u653E\u7684\u6DB2\u4F53\u6E29\u5EA6\u8BA1\uFF0C\u5DE6\u4FA7\u523B\u5EA6\u4ECE 0 \u2103 \u5230 ${maxT} \u2103\uFF0C\u7BA1\u5185\u7EA2\u8272\u6DB2\u67F1\u7684\u9876\u7AEF\u6B63\u597D\u4E0E ${readT} \u2103 \u7684\u523B\u5EA6\u7EBF\u76F8\u5E73`,
    prims: [
      { t: "thermometer", x, y, h, value: readT / maxT, label: "\u6E29\u5EA6\u8BA1" },
      ...thermoScale(x, y, h, 0, maxT, step)
    ]
  };
}
