        answer: "\u5668\u6750\uFF1A\u94C1\u67B6\u53F0\u3001\u70E7\u676F\u3001\u8BD5\u7BA1\u3001\u6D77\u6CE2\uFF08\u7814\u788E\uFF09\u3001\u6E29\u5EA6\u8BA1\u3001\u9152\u7CBE\u706F\u3001\u77F3\u68C9\u7F51\u3001\u79D2\u8868\u3001\u6405\u62CC\u68D2\uFF08\u6216\u7EC6\u94C1\u4E1D\uFF09\u3002\u52A0\u70ED\u65B9\u5F0F\uFF1A\u7528\u6C34\u6D74\u6CD5\uFF08\u628A\u88C5\u6D77\u6CE2\u7684\u8BD5\u7BA1\u6D78\u5728\u70E7\u676F\u7684\u6C34\u4E2D\u52A0\u70ED\uFF09\uFF0C\u597D\u5904\u662F\u4F7F\u6D77\u6CE2\u53D7\u70ED\u5747\u5300\u3001\u6E29\u5EA6\u53D8\u5316\u7F13\u6162\uFF0C\u4FBF\u4E8E\u6BCF\u9694\u4E00\u6BB5\u65F6\u95F4\u51C6\u786E\u8BFB\u53D6\u6E29\u5EA6\u3002\u8BB0\u5F55\u7684\u6570\u636E\uFF1A\u6BCF\u9694 1 min\uFF08\u6216 0.5 min\uFF09\u8BB0\u5F55\u4E00\u6B21\u6D77\u6CE2\u7684\u6E29\u5EA6\uFF0C\u76F4\u5230\u6D77\u6CE2\u5B8C\u5168\u7194\u5316\u540E\u518D\u8BB0\u5F55\u51E0\u6B21\uFF0C\u5373\u8BB0\u5F55\u300C\u65F6\u95F4\u2014\u6E29\u5EA6\u300D\u7684\u5BF9\u5E94\u5173\u7CFB\u3002\u5224\u65AD\u4F9D\u636E\uFF1A\u628A\u6570\u636E\u63CF\u70B9\u8FDE\u7EBF\u6210\u56FE\u50CF\uFF0C\u82E5\u56FE\u50CF\u51FA\u73B0\u4E00\u6BB5\u6C34\u5E73\u7684\u7EBF\u6BB5\uFF08\u6E29\u5EA6\u4FDD\u6301\u4E0D\u53D8\uFF09\uFF0C\u5219\u6D77\u6CE2\u6709\u56FA\u5B9A\u7684\u7194\u5316\u6E29\u5EA6\uFF08\u7194\u70B9 48 \u2103\uFF09\uFF0C\u662F\u6676\u4F53\uFF1B\u6C34\u5E73\u6BB5\u5BF9\u5E94\u7684\u6E29\u5EA6\u5C31\u662F\u7194\u70B9\u3002\u6CE8\u610F\u6E29\u5EA6\u8BA1\u7684\u73BB\u7483\u6CE1\u8981\u63D2\u5728\u6D77\u6CE2\u4E2D\u95F4\uFF0C\u4E0D\u8981\u78B0\u5230\u8BD5\u7BA1\u58C1\u548C\u8BD5\u7BA1\u5E95\u3002",
        rubric: [
          "\u5668\u6750\u9F50\u5168\uFF08\u70E7\u676F\u3001\u8BD5\u7BA1\u3001\u6E29\u5EA6\u8BA1\u3001\u9152\u7CBE\u706F\u3001\u79D2\u8868\u7B49\uFF09",
          "\u8BF4\u660E\u7528\u6C34\u6D74\u6CD5\u52A0\u70ED\u5E76\u7B54\u51FA\u597D\u5904\uFF08\u53D7\u70ED\u5747\u5300\u3001\u6E29\u5EA6\u53D8\u5316\u7F13\u6162\u4FBF\u4E8E\u8BB0\u5F55\uFF09",
          "\u8BF4\u660E\u8BB0\u5F55\u65B9\u5F0F\uFF1A\u6BCF\u9694\u76F8\u540C\u65F6\u95F4\u8BB0\u5F55\u4E00\u6B21\u6E29\u5EA6\uFF0C\u753B\u6210\u6E29\u5EA6\u2014\u65F6\u95F4\u56FE\u50CF",
          "\u7531\u56FE\u50CF\u6709\u65E0\u6C34\u5E73\u6BB5\u5224\u65AD\u662F\u5426\u4E3A\u6676\u4F53\uFF0C\u5E76\u6307\u51FA\u6C34\u5E73\u6BB5\u5BF9\u5E94\u7194\u70B9",
          "\u8BF4\u660E\u6E29\u5EA6\u8BA1\u73BB\u7483\u6CE1\u4F4D\u7F6E\u6B63\u786E\uFF08\u63D2\u5728\u88AB\u6D4B\u7269\u8D28\u4E2D\uFF0C\u4E0D\u78B0\u58C1\u4E0D\u78B0\u5E95\uFF09"
        ],
        explanation: "\u672C\u5B9E\u9A8C\u7684\u8E29\u5206\u70B9\u5728\u300C\u600E\u4E48\u52A0\u70ED\u300D\u300C\u600E\u4E48\u8BB0\u5F55\u300D\u300C\u600E\u4E48\u5224\u65AD\u300D\u4E09\u5904\u3002\u53EA\u5199\u300C\u52A0\u70ED\u6D77\u6CE2\u5E76\u89C2\u5BDF\u300D\u4E0D\u5F97\u5206\uFF0C\u56E0\u4E3A\u7194\u5316\u89C4\u5F8B\u5FC5\u987B\u9760\u6570\u636E\uFF08\u65F6\u95F4\u2014\u6E29\u5EA6\u56FE\u50CF\uFF09\u624D\u80FD\u770B\u51FA\u6765\u3002\u6C34\u6D74\u6CD5\u7684\u4E24\u4E2A\u597D\u5904\u3001\u6E29\u5EA6\u8BA1\u7684\u4F7F\u7528\u89C4\u8303\u3001\u4EE5\u53CA\u300C\u6709\u6C34\u5E73\u6BB5\u624D\u662F\u6676\u4F53\u300D\u7684\u5224\u65AD\u6807\u51C6\uFF0C\u662F\u8FD9\u9053\u9898\u7684\u4E09\u4E2A\u5FC5\u7B54\u70B9\u3002",
