          "\u5168\u4E16\u754C\u4E00\u5E74\u6570\u51FA\u7684\u5206\u5B50\u6570\uFF1A7\xD710\u2079 \u4E2A/s \xD7 3.15\xD710\u2077 s = 2.205\xD710\xB9\u2077 \u4E2A\u3002",
          "\u9700\u8981\u7684\u5E74\u6570\uFF1A3.3\xD710\xB2\xB2 \xF7 2.205\xD710\xB9\u2077 \u2248 1.5\xD710\u2075 \u5E74\u3002",
