// src/data/physics/modules/electric.ts
function dialPrims(cx, cy, r, o) {
  const FROM = 150;
  const TO = 30;
  const angleOf = (v) => FROM + (TO - FROM) * (v / o.max);
  const pt = (v, rr) => {
    const a = angleOf(v) * Math.PI / 180;
    return [cx + rr * Math.cos(a), cy - rr * Math.sin(a)];
  };
  const out = [];
  const arcPts = [];
  for (let i = 0; i <= 48; i += 1) arcPts.push(pt(o.max * i / 48, r));
  out.push({ t: "curve", points: arcPts, tone: "main", width: 0.5 });
  const count = Math.round(o.max / o.step);
  for (let k = 0; k <= count; k += 1) {
    const v = k * o.step;
    const major = k % o.labelEvery === 0;
    const [x1, y1] = pt(v, r);
    const [x2, y2] = pt(v, r - (major ? 3.8 : 2));
    out.push({ t: "line", x1, y1, x2, y2, tone: "main", width: major ? 0.5 : 0.28 });
    if (major) {
      const [lx, ly] = pt(v, r - 7.4);
      out.push({ t: "text", x: lx, y: ly, text: `${Number(v.toFixed(2))}`, size: 3.4, tone: "muted" });
    }
  }
  const [nx, ny] = pt(o.read, r - 3.2);
  const [bx, by] = pt(o.read, -r * 0.14);
  out.push({ t: "line", x1: bx, y1: by, x2: nx, y2: ny, tone: "danger", width: 0.7 });
  out.push({ t: "circle", cx, cy, r: 1.5, fill: true, tone: "main" });
  return out;
}
