        detail: "\u4EE5\u64AC\u68D2\u3001\u7F8A\u89D2\u9524\u3001\u5929\u5E73\u3001\u6746\u79E4\u4E3A\u60C5\u5883\uFF0C\u7ED9\u51FA\u4E00\u90E8\u5206\u529B\u6216\u529B\u81C2\uFF0C\u6C42\u53E6\u4E00\u4E2A\u91CF\uFF1B\u6216\u8005\u6539\u53D8\u529B\u7684\u65B9\u5411\uFF0C\u95EE\u529B\u7684\u5927\u5C0F\u600E\u4E48\u53D8\u3002\u7B54\u9898\u8981\u5199\u6E05\u300C\u627E\u529B\u81C2\u2014\u4EE3\u516C\u5F0F\u2014\u7B97\u7ED3\u679C\u2014\u5E26\u5355\u4F4D\u300D\uFF0C\u5E76\u4E14\u5728\u5224\u65AD\u7701\u529B\u8D39\u529B\u65F6\u8BF4\u660E\u662F\u54EA\u4E00\u4FA7\u7684\u529B\u81C2\u66F4\u957F\u3002"
