              "\u8BF4\u660E\u89C6\u7EBF\u659C\u5411\u4E0B\u3001\u770B\u5230\u7684\u523B\u5EA6\u504F\u4E0A\uFF081 \u5206\uFF09",
              "\u63A8\u51FA\u5B9E\u9645\u91CF\u5230\u7684\u6C34\u5C11\u4E8E 40 mL\uFF081 \u5206\uFF09"
