    keyIdea: "\u4E09\u6B65\u8BFB\u6750\u6599\uFF1A\u5148\u770B\u8BBE\u95EE\u518D\u770B\u6750\u6599\uFF08\u77E5\u9053\u8981\u627E\u4EC0\u4E48\uFF09\u2192 \u5728\u6750\u6599\u91CC\u5708\u51FA\u300C\u6570\u5B57\uFF0B\u5355\u4F4D\uFF0B\u7269\u7406\u91CF\u540D\u79F0\u300D\u2192 \u628A\u751F\u6D3B\u8BED\u8A00\u7FFB\u8BD1\u6210\u7269\u7406\u91CF\u5E76\u7EDF\u4E00\u5355\u4F4D\u3002\u6750\u6599\u91CC\u7684\u6570\u5B57\u4E0D\u7B49\u4E8E\u5DF2\u77E5\u91CF\uFF0C\u53EA\u6709\u4E0E\u8BBE\u95EE\u76F8\u5173\u7684\u624D\u662F\uFF1B\u300C\u5300\u901F\u3001\u6F02\u6D6E\u3001\u6B63\u5E38\u5DE5\u4F5C\u3001\u9759\u6B62\u300D\u8FD9\u4E9B\u8BF4\u6CD5\u8981\u81EA\u5DF1\u7FFB\u8BD1\u6210\u7269\u7406\u6761\u4EF6\u3002",
