            answer: "\u2460\u6BD4\u8F83\u2460\u2461\uFF1A\u63A5\u89E6\u9762\u90FD\u662F\u957F\u6728\u677F\uFF08\u7C97\u7CD9\u7A0B\u5EA6\u76F8\u540C\uFF09\uFF0C\u6B65\u9AA4\u2461\u5728\u6728\u5757\u4E0A\u52A0\u4E86\u781D\u7801\u4F7F\u538B\u529B\u589E\u5927\uFF0C\u793A\u6570\u7531 1.2 N \u589E\u5927\u5230 2.0 N\u2014\u2014\u5728\u63A5\u89E6\u9762\u7C97\u7CD9\u7A0B\u5EA6\u76F8\u540C\u65F6\uFF0C\u538B\u529B\u8D8A\u5927\uFF0C\u6ED1\u52A8\u6469\u64E6\u529B\u8D8A\u5927\u3002\u2461\u6BD4\u8F83\u2460\u2462\uFF1A\u6728\u5757\u4E0A\u90FD\u6CA1\u6709\u653E\u781D\u7801\uFF08\u538B\u529B\u76F8\u540C\uFF09\uFF0C\u6B65\u9AA4\u2462\u628A\u6728\u5757\u653E\u5728\u6BDB\u5DFE\u4E0A\u4F7F\u63A5\u89E6\u9762\u66F4\u7C97\u7CD9\uFF0C\u793A\u6570\u7531 1.2 N \u589E\u5927\u5230 2.4 N\u2014\u2014\u5728\u538B\u529B\u76F8\u540C\u65F6\uFF0C\u63A5\u89E6\u9762\u8D8A\u7C97\u7CD9\uFF0C\u6ED1\u52A8\u6469\u64E6\u529B\u8D8A\u5927\u3002",
