// src/data/chemistry/modules/matter.ts
function mol(x, y, atoms, bonds = []) {
  return { t: "molecule", x, y, atoms, bonds };
}
function h2o(x, y, k = 1) {
  return mol(
    x,
    y,
    [
      { dx: 0, dy: 0, r: 4.2 * k, symbol: "O", color: "red" },
      { dx: -5.2 * k, dy: -4 * k, r: 2.6 * k, symbol: "H" },
      { dx: 5.2 * k, dy: -4 * k, r: 2.6 * k, symbol: "H" }
    ],
    [
      [0, 1],
      [0, 2]
    ]
  );
}
function o2(x, y, k = 1) {
  return mol(
    x,
    y,
    [
      { dx: -3.6 * k, dy: 0, r: 4 * k, symbol: "O", color: "red" },
      { dx: 3.6 * k, dy: 0, r: 4 * k, symbol: "O", color: "red" }
    ],
    [[0, 1]]
  );
}
function h2(x, y, k = 1) {
  return mol(
    x,
    y,
    [
      { dx: -3 * k, dy: 0, r: 2.8 * k, symbol: "H" },
      { dx: 3 * k, dy: 0, r: 2.8 * k, symbol: "H" }
    ],
    [[0, 1]]
  );
}
function co2mol(x, y, k = 1) {
  return mol(
    x,
    y,
    [
      { dx: -7.4 * k, dy: 0, r: 4 * k, symbol: "O", color: "red" },
      { dx: 0, dy: 0, r: 4.4 * k, symbol: "C", color: "black" },
      { dx: 7.4 * k, dy: 0, r: 4 * k, symbol: "O", color: "red" }
    ],
    [
      [0, 1],
      [1, 2]
    ]
  );
}
function plainMol(x, y, k = 1) {
  return mol(x, y, [{ dx: -1.9 * k, dy: 0, r: 1.5 * k }, { dx: 1.9 * k, dy: 0, r: 1.5 * k }], [[0, 1]]);
}
function shell(cx, cy, proton, shells, label, k = 1) {
  const core = 4.4 * k;
  const step = 4.1 * k;
  const prims = [
    { t: "circle", cx, cy, r: core, tone: "main" },
    { t: "text", x: cx, y: cy + 0.2, text: `+${proton}`, size: 3.1 * k }
  ];
  shells.forEach((n, i) => {
    const r = core + (i + 1) * step;
    prims.push({ t: "circle", cx, cy, r, tone: "muted" });
    prims.push({ t: "text", x: cx, y: cy - r, text: `${n}`, size: 3.1 * k });
  });
  if (label) {
    prims.push({ t: "text", x: cx, y: cy + core + (shells.length + 1) * step, text: label, size: 3.6 });
  }
  return prims;
}
function periodCell(x, y, w, h, z, sym, name, ar) {
  const out = [
    { t: "rect", x, y, w, h, tone: "muted" },
    { t: "text", x: x + 1.4, y: y + 3.2, text: `${z}`, size: 2.8, anchor: "start", tone: "muted" },
    { t: "text", x: x + w / 2, y: y + h * 0.46, text: sym, size: 4.4 },
    { t: "text", x: x + w / 2, y: y + h * 0.82, text: name, size: 3.2 }
  ];
  if (ar !== void 0) {
    out.push({ t: "text", x: x + w - 1.4, y: y + 3.2, text: `${ar}`, size: 2.8, anchor: "end", tone: "muted" });
  }
  return out;
}
function ionGrid(x, y, cols, rows, gap, k = 1) {
  const out = [];
  for (let j = 0; j < rows; j += 1) {
    for (let i = 0; i < cols; i += 1) {
      const isNa = (i + j) % 2 === 0;
      out.push({
        t: "atom",
        x: x + i * gap,
        y: y + j * gap,
        r: 3.9 * k,
        symbol: isNa ? "Na" : "Cl",
        charge: isNa ? "+" : "-",
        color: isNa ? "purple" : "green"
      });
    }
  }
  return out;
}
function dyeBeaker(x, y, w, h, dye, label) {
  const water = 0.72;
  const top = y + h * (1 - water);
  const wh = h * water;
  return [
    { t: "beaker", x, y, w, h, fill: 0 },
    { t: "line", x1: x, y1: top, x2: x + w, y2: top, tone: "muted", width: 0.35 },
    { t: "rect", x: x + 0.7, y: top + wh * (1 - dye), w: w - 1.4, h: wh * dye, tone: "danger", fill: true },
    { t: "text", x: x + w / 2, y: y + h + 5.2, text: label, size: 3.4 }
  ];
}
function molsIn(xs, ys, k = 1) {
  const out = [];
  xs.forEach((x, i) => {
    (ys[i] ?? []).forEach((y) => out.push(plainMol(x, y, k)));
  });
  return out;
}
