        conclusion: "\u6D53\u6C28\u6C34\u4E2D\u7684\u6C28\u5206\u5B50\u4E0D\u65AD\u8FD0\u52A8\uFF0C\u6269\u6563\u5230\u7A7A\u6C14\u4E2D\u540E\u53C8\u8FDB\u5165\u915A\u915E\u6EB6\u6DB2\uFF0C\u4F7F\u915A\u915E\u6EB6\u6DB2\u53D8\u7EA2\u2014\u2014\u8BF4\u660E\u5206\u5B50\u5728\u4E0D\u505C\u8FD0\u52A8\uFF1B\u6E29\u5EA6\u8D8A\u9AD8\uFF0C\u5206\u5B50\u8FD0\u52A8\u8D8A\u5FEB\uFF0C\u53D8\u7EA2\u4E5F\u8D8A\u5FEB",
        cautions: [
          "\u6D53\u6C28\u6C34\u6709\u5F3A\u70C8\u7684\u523A\u6FC0\u6027\u6C14\u5473\uFF0C\u5B9E\u9A8C\u8981\u5728\u901A\u98CE\u5904\u8FDB\u884C\uFF0C\u95FB\u6C14\u5473\u65F6\u8981\u7528\u624B\u5728\u74F6\u53E3\u8F7B\u8F7B\u6247\u52A8\uFF0C\u4E0D\u8981\u628A\u9F3B\u5B54\u51D1\u5230\u74F6\u53E3",
          "\u4E24\u53EA\u5C0F\u70E7\u676F\u4E0D\u80FD\u63A5\u89E6\uFF0C\u5426\u5219\u53D8\u7EA2\u53EF\u80FD\u662F\u6DB2\u4F53\u76F4\u63A5\u6DF7\u5408\u9020\u6210\u7684\uFF0C\u5B9E\u9A8C\u5C31\u5931\u53BB\u4E86\u610F\u4E49",
          "\u5927\u70E7\u676F\uFF08\u6216\u949F\u7F69\uFF09\u8981\u7F69\u4E25\u5B9E\uFF0C\u9632\u6B62\u6C28\u5206\u5B50\u5927\u91CF\u9038\u6563\uFF1B\u8BE5\u5B9E\u9A8C\u5C5E\u4E8E\u5BF9\u6BD4\u5B9E\u9A8C\uFF0C\u300C\u4E0D\u653E\u6D53\u6C28\u6C34\u300D\u7684\u4E00\u7EC4\u662F\u7A7A\u767D\u5BF9\u7167"
        ]
