        text: "\u6E29\u5EA6\u8D8A\u9AD8\uFF0C\u5206\u5B50\uFF08\u539F\u5B50\uFF09\u7684\u65E0\u89C4\u5219\u8FD0\u52A8\u8D8A\u5FEB",
        usage: "\u7528\u4E8E\u89E3\u91CA\u6269\u6563\u3001\u84B8\u53D1\u3001\u6EB6\u89E3\u7B49\u73B0\u8C61\u7684\u5FEB\u6162\uFF08\u70ED\u6C34\u4E2D\u54C1\u7EA2\u6269\u6563\u66F4\u5FEB\u3001\u9633\u5149\u4E0B\u6E7F\u8863\u670D\u5E72\u5F97\u66F4\u5FEB\uFF09\u3002\u53EA\u80FD\u8BF4\u660E\u8FD0\u52A8\u5FEB\u6162\uFF0C\u4E0D\u80FD\u7528\u6765\u89E3\u91CA\u300C\u5206\u5B50\u53D8\u5927\u6216\u53D8\u5C0F\u300D\u2014\u2014\u6E29\u5EA6\u53D8\u5316\u6539\u53D8\u7684\u662F\u95F4\u9694\u4E0E\u8FD0\u52A8\u5FEB\u6162\uFF0C\u4E0D\u662F\u5206\u5B50\u672C\u8EAB\u7684\u5927\u5C0F\u3002"
