            rubric: ["\u7B54\u51FA\u300C\u8D28\u5B50\u6570\uFF08\u5143\u7D20\u79CD\u7C7B\uFF09\u4E0D\u53D8\u300D\uFF082 \u5206\uFF09", "\u7B54\u51FA\u300C\u7535\u5B50\u6570\u6539\u53D8\u300D\u5E76\u6307\u51FA\u7535\u5B50\u6570\u7531 11 \u53D8 10\uFF081 \u5206\uFF09"],
