        phenomenon: "\u7535\u6781\u63D2\u5728\u5E72\u71E5\u7684\u6C2F\u5316\u94A0\u56FA\u4F53\u4E2D\uFF08\u4EE5\u53CA\u63D2\u5728\u84B8\u998F\u6C34\u4E2D\uFF09\u706F\u6CE1\u90FD\u4E0D\u4EAE\uFF1B\u6C2F\u5316\u94A0\u6EB6\u89E3\u540E\uFF0C\u706F\u6CE1\u53D1\u5149",
