        text: "\u6700\u524D\u9762\uFF1A\u5FAE\u7C92\u4E2A\u6570\uFF1B\u53F3\u4E0B\u89D2\uFF1A1 \u4E2A\u5206\u5B50\u4E2D\u7684\u539F\u5B50\u4E2A\u6570\uFF1B\u53F3\u4E0A\u89D2\uFF1A\u79BB\u5B50\u7535\u8377\uFF08\u6570\u5B57\u5728\u524D\u30011 \u7701\u7565\uFF09\uFF1B\u6B63\u4E0A\u65B9\uFF1A\u5316\u5408\u4EF7\uFF08\u7B26\u53F7\u5728\u524D\u30011 \u4E0D\u7701\u7565\uFF09",
