        text: "\u5143\u7D20\u8D28\u91CF\u5206\u6570 =\uFF08\u76F8\u5BF9\u539F\u5B50\u8D28\u91CF \xD7 \u539F\u5B50\u4E2A\u6570\uFF09\xF7 \u76F8\u5BF9\u5206\u5B50\u8D28\u91CF \xD7 100%",
