        phenomenon: "\u7EA2\u78F7\u71C3\u70E7\u4EA7\u751F\u5927\u91CF\u767D\u70DF\uFF0C\u653E\u51FA\u70ED\u91CF\uFF1B\u51B7\u5374\u540E\u6253\u5F00\u5F39\u7C27\u5939\uFF0C\u70E7\u676F\u4E2D\u7684\u6C34\u6CBF\u5BFC\u7BA1\u5012\u5438\u8FDB\u96C6\u6C14\u74F6\uFF0C\u8FDB\u5165\u74F6\u5185\u7684\u6C34\u7684\u4F53\u79EF\u7EA6\u5360\u74F6\u5185\u7A7A\u6C14\u4F53\u79EF\u7684 1/5\u3002",
