          "\u76F8\u5BF9\u8D28\u91CF 168\u300164\u3001232 \u7B97\u5BF9\uFF08\u7279\u522B\u662F O\u2082 \u8981\u6309 32 \u7B97\uFF09",
          "\u4E24\u4E2A\u6BD4\u4F8B\u5F0F\u5206\u522B\u5217\u5BF9\u5E76\u6C42\u51FA\u7ED3\u679C",
