          "\u7535\u89E3\u6C34\u65F6\u6C22\u6C14\u4E0E\u6C27\u6C14\u7684\u4F53\u79EF\u6BD4\u7406\u8BBA\u4E0A\u662F 2\u22361\uFF0C\u5B9E\u9645\u5B9E\u9A8C\u4E2D\u6C27\u6C14\u4F53\u79EF\u5F80\u5F80\u7565\u5C0F\u4E8E\u7406\u8BBA\u503C\uFF08\u6C27\u6C14\u5728\u6C34\u4E2D\u6EB6\u89E3\u5F97\u6BD4\u6C22\u6C14\u591A\u3001\u7535\u6781\u4E0A\u4E5F\u4F1A\u6D88\u8017\u5C11\u91CF\u6C27\u6C14\uFF09\uFF0C\u8FD9\u662F\u6B63\u5E38\u73B0\u8C61\u3002",
