        steps: [
          "\u53D6\u4E00\u652F\u8BD5\u7BA1\uFF0C\u52A0\u5165\u7EA6\u4E09\u5206\u4E4B\u4E00\u4F53\u79EF\u7684\u7D2B\u8272\u77F3\u854A\u6EB6\u6DB2\uFF0C\u89C2\u5BDF\u5B83\u7684\u989C\u8272\u3002",
          "\u628A\u4E8C\u6C27\u5316\u78B3\u6C14\u4F53\u901A\u5165\u7D2B\u8272\u77F3\u854A\u6EB6\u6DB2\u4E2D\uFF0C\u89C2\u5BDF\u6EB6\u6DB2\u989C\u8272\u7684\u53D8\u5316\u3002",
          "\u7528\u8BD5\u7BA1\u5939\u5939\u4F4F\u8BD5\u7BA1\uFF0C\u5728\u9152\u7CBE\u706F\u4E0A\u52A0\u70ED\u53D8\u7EA2\u7684\u6EB6\u6DB2\uFF0C\u89C2\u5BDF\u989C\u8272\u53C8\u53D1\u751F\u4E86\u4EC0\u4E48\u53D8\u5316\u3002",
          "\u8BB0\u5F55\u4E24\u6B21\u989C\u8272\u53D8\u5316\uFF0C\u5199\u51FA\u5BF9\u5E94\u7684\u5316\u5B66\u65B9\u7A0B\u5F0F\u3002"
        ],
        phenomenon: "\u901A\u5165\u4E8C\u6C27\u5316\u78B3\u540E\uFF0C\u7D2B\u8272\u77F3\u854A\u6EB6\u6DB2\u9010\u6E10\u53D8\u6210\u7EA2\u8272\uFF1B\u52A0\u70ED\u540E\uFF0C\u7EA2\u8272\u53C8\u9010\u6E10\u53D8\u56DE\u7D2B\u8272\uFF0C\u540C\u65F6\u6709\u6C14\u6CE1\u5192\u51FA\u3002",
        conclusion: "\u4E8C\u6C27\u5316\u78B3\u4E0E\u6C34\u53CD\u5E94\u751F\u6210\u78B3\u9178\uFF0C\u78B3\u9178\u4F7F\u7D2B\u8272\u77F3\u854A\u6EB6\u6DB2\u53D8\u7EA2\uFF08CO\u2082 + H\u2082O = H\u2082CO\u2083\uFF09\uFF1B\u78B3\u9178\u4E0D\u7A33\u5B9A\uFF0C\u53D7\u70ED\u5206\u89E3\u751F\u6210\u6C34\u548C\u4E8C\u6C27\u5316\u78B3\uFF08H\u2082CO\u2083 = H\u2082O + CO\u2082\u2191\uFF09\uFF0C\u6240\u4EE5\u7EA2\u8272\u53C8\u53D8\u56DE\u7D2B\u8272\u3002",
        cautions: [
          "\u4F7F\u77F3\u854A\u53D8\u7EA2\u7684\u662F\u78B3\u9178\u800C\u4E0D\u662F\u4E8C\u6C27\u5316\u78B3\uFF1A\u53EF\u4EE5\u7528\u5E72\u71E5\u7684\u7D2B\u8272\u77F3\u854A\u7EB8\u82B1\u505A\u5BF9\u7167\uFF0C\u628A\u4E8C\u6C27\u5316\u78B3\u76F4\u63A5\u901A\u5230\u5E72\u71E5\u7EB8\u82B1\u4E0A\uFF0C\u7EB8\u82B1\u4E0D\u53D8\u7EA2\u3002",
          "\u52A0\u70ED\u8BD5\u7BA1\u65F6\u8981\u5148\u9884\u70ED\u3001\u518D\u7528\u5916\u7130\u52A0\u70ED\uFF0C\u8BD5\u7BA1\u53E3\u4E0D\u8981\u5BF9\u7740\u4EBA\uFF1B\u6DB2\u4F53\u4F53\u79EF\u4E0D\u8981\u8D85\u8FC7\u8BD5\u7BA1\u5BB9\u79EF\u7684\u4E09\u5206\u4E4B\u4E00\u3002",
          "\u4E0D\u80FD\u7528\u5634\u5439\u706D\u9152\u7CBE\u706F\uFF0C\u8981\u7528\u706F\u5E3D\u76D6\u706D\uFF1B\u5B9E\u9A8C\u7ED3\u675F\u540E\u7B49\u8BD5\u7BA1\u51B7\u5374\u518D\u6D17\u6DA4\uFF0C\u9632\u6B62\u9AA4\u51B7\u70B8\u88C2\u3002",
          "\u901A\u5165\u4E8C\u6C27\u5316\u78B3\u7684\u65F6\u95F4\u4E0D\u8981\u592A\u957F\uFF0C\u89C2\u5BDF\u5230\u989C\u8272\u53D8\u5316\u5373\u53EF\uFF0C\u907F\u514D\u78B3\u9178\u5206\u89E3\u4E0E\u751F\u6210\u53CD\u590D\u8FDB\u884C\u3001\u73B0\u8C61\u4E0D\u6E05\u695A\u3002",
          "\u8FD9\u4E2A\u5B9E\u9A8C\u53EA\u80FD\u8BF4\u660E\u4E8C\u6C27\u5316\u78B3\u4E0E\u6C34\u53CD\u5E94\u751F\u6210\u4E86\u9178\u6027\u7269\u8D28\uFF0C\u4E0D\u80FD\u8BF4\u660E\u4E8C\u6C27\u5316\u78B3\u672C\u8EAB\u663E\u9178\u6027\u3002"
        ]
