        answer: "\u539F\u56E0\uFF1A\u7A00\u786B\u9178\u4E0E\u5927\u7406\u77F3\u53CD\u5E94\u751F\u6210\u786B\u9178\u9499\uFF0C\u786B\u9178\u9499\u5FAE\u6EB6\u4E8E\u6C34\uFF0C\u8986\u76D6\u5728\u5927\u7406\u77F3\u7684\u8868\u9762\uFF0C\u628A\u5927\u7406\u77F3\u4E0E\u7A00\u786B\u9178\u9694\u5F00\uFF0C\u53CD\u5E94\u5C31\u65E0\u6CD5\u7EE7\u7EED\u8FDB\u884C\u3002\u9A8C\u8BC1\u65B9\u6CD5\uFF1A\u53D6\u53CD\u5E94\u540E\u7684\u5927\u7406\u77F3\uFF0C\u7528\u6C34\u51B2\u6D17\u5E72\u51C0\u540E\u653E\u5165\u8BD5\u7BA1\u4E2D\uFF0C\u518D\u52A0\u5165\u7A00\u76D0\u9178\uFF08\u6216\u7A00\u786B\u9178\u4E4B\u5916\u7684\u9178\uFF09\uFF0C\u89C2\u5BDF\u5230\u53C8\u6709\u5927\u91CF\u6C14\u6CE1\u4EA7\u751F\uFF0C\u8BF4\u660E\u5927\u7406\u77F3\u672C\u8EAB\u5E76\u6CA1\u6709\u88AB\u6D88\u8017\u5B8C\uFF0C\u53EA\u662F\u8868\u9762\u88AB\u751F\u6210\u7684\u786B\u9178\u9499\u8986\u76D6\u4E86\uFF1B\u4E5F\u53EF\u4EE5\u628A\u8868\u9762\u8986\u76D6\u7684\u56FA\u4F53\u522E\u4E0B\u5C11\u91CF\uFF0C\u68C0\u9A8C\u5B83\u7684\u6210\u5206\uFF08\u80FD\u6EB6\u4E8E\u6C34\u5F88\u5C11\u3001\u4E0E\u76D0\u9178\u53CD\u5E94\u53C8\u6709\u6C14\u4F53\uFF09\u3002",
        rubric: [
          "\u6307\u51FA\u539F\u56E0\u662F\u300C\u751F\u6210\u5FAE\u6EB6\u7684\u786B\u9178\u9499\u8986\u76D6\u5728\u5927\u7406\u77F3\u8868\u9762\u300D",
          "\u8BF4\u660E\u540E\u679C\uFF1A\u5927\u7406\u77F3\u4E0E\u7A00\u786B\u9178\u88AB\u9694\u5F00\uFF0C\u53CD\u5E94\u4E0D\u80FD\u7EE7\u7EED",
          "\u8BBE\u8BA1\u9A8C\u8BC1\u5B9E\u9A8C\uFF1A\u628A\u53CD\u5E94\u540E\u7684\u5927\u7406\u77F3\u6D17\u51C0\u540E\u52A0\u5165\u7A00\u76D0\u9178\uFF0C\u89C2\u5BDF\u5230\u53C8\u6709\u6C14\u6CE1\u4EA7\u751F",
          "\u7ED3\u8BBA\u4E0E\u73B0\u8C61\u5BF9\u5E94\uFF0C\u5E76\u80FD\u7531\u6B64\u5F97\u51FA\u300C\u5B9E\u9A8C\u5BA4\u5236\u4E8C\u6C27\u5316\u78B3\u5E94\u8BE5\u7528\u7A00\u76D0\u9178\u300D"
        ],
        explanation: "\u8FD9\u7C7B\u300C\u53CD\u5E94\u4E3A\u4EC0\u4E48\u505C\u4E0B\u6765\u300D\u7684\u9898\u76EE\uFF0C\u601D\u8DEF\u662F\u4ECE\u300C\u53CD\u5E94\u7269\u6709\u6CA1\u6709\u7528\u5B8C\u300D\u548C\u300C\u53CD\u5E94\u7269\u6709\u6CA1\u6709\u88AB\u9694\u5F00\u300D\u4E24\u6761\u53BB\u5206\u6790\u3002\u8FD9\u91CC\u5927\u7406\u77F3\u5E76\u6CA1\u6709\u7528\u5B8C\uFF0C\u95EE\u9898\u51FA\u5728\u8868\u9762\u8986\u76D6\u4E86\u4E00\u5C42\u5FAE\u6EB6\u7684\u786B\u9178\u9499\u3002\u9A8C\u8BC1\u5B9E\u9A8C\u7684\u8BBE\u8BA1\u8981\u70B9\u662F\u300C\u6362\u4E00\u79CD\u9178\u518D\u8BD5\u300D\u6216\u300C\u68C0\u9A8C\u8868\u9762\u7684\u7269\u8D28\u300D\u2014\u2014\u6362\u7528\u7A00\u76D0\u9178\u540E\u6C14\u6CE1\u53C8\u5927\u91CF\u4EA7\u751F\uFF0C\u5C31\u8BC1\u660E\u5927\u7406\u77F3\u8FD8\u6709\u5269\u4F59\u3001\u53CD\u5E94\u662F\u88AB\u9694\u5F00\u7684\u3002",
