        phenomenon: "\u94C1\u9489\u8868\u9762\u9010\u6E10\u8986\u76D6\u4E00\u5C42\u7EA2\u8272\u7684\u7269\u8D28\uFF08\u94DC\uFF09\uFF0C\u6EB6\u6DB2\u7531\u84DD\u8272\u9010\u6E10\u53D8\u6210\u6D45\u7EFF\u8272\u3002",
        conclusion: "\u94C1\u7684\u6D3B\u52A8\u6027\u6BD4\u94DC\u5F3A\uFF0C\u80FD\u628A\u94DC\u4ECE\u786B\u9178\u94DC\u6EB6\u6DB2\u4E2D\u7F6E\u6362\u51FA\u6765\uFF0C\u5316\u5B66\u65B9\u7A0B\u5F0F\u4E3A Fe + CuSO\u2084 = FeSO\u2084 + Cu\u3002\u6EB6\u6DB2\u7531\u84DD\u8272\u53D8\u6D45\u7EFF\u8272\u662F\u56E0\u4E3A Cu\xB2\u207A \u51CF\u5C11\u3001Fe\xB2\u207A \u589E\u591A\u3002",
