          "\u7B97\u51FA\u76F8\u5BF9\u8D28\u91CF\uFF1AZn = 65\uFF0CZnSO\u2084 = 65 + 32 + 16\xD74 = 161\uFF0CH\u2082 = 1\xD72 = 2\u3002",
          "\u8BBE\u751F\u6210\u6C22\u6C14\u7684\u8D28\u91CF\u4E3A x\uFF1A65\u22362 = 13 g\u2236x\uFF0C\u89E3\u5F97 x = 0.4 g\u3002",
