              "\u7B97\u51FA\u76F8\u5BF9\u8D28\u91CF 65\u3001161\u30012\uFF08H\u2082 \u6309 2 \u7B97\uFF0CZnSO\u2084 \u6309 161 \u7B97\uFF09",
              "\u6C42\u51FA\u6C22\u6C14\u8D28\u91CF\u4E3A 0.4 g",
              "\u6C42\u51FA\u786B\u9178\u950C\u8D28\u91CF\u4E3A 32.2 g\uFF0C\u5E76\u5199\u51FA\u5E26\u5355\u4F4D\u7684\u7B54\u53E5"
