        stem: "\u8BF7\u753B\u51FA\u63A2\u7A76\u94C1\u751F\u9508\u6761\u4EF6\u7684\u4E09\u652F\u8BD5\u7BA1\u7684\u5BF9\u6BD4\u5B9E\u9A8C\u88C5\u7F6E\u56FE\uFF0C\u5E76\u5728\u6BCF\u652F\u8BD5\u7BA1\u65C1\u7528\u6587\u5B57\u6807\u6CE8\u5B83\u6240\u63A7\u5236\u7684\u6761\u4EF6\uFF08\u63A5\u89E6\u5230\u7684\u7269\u8D28\uFF09\u3002",
        answer: "\u753B\u6CD5\uFF1A\u753B\u51FA\u4E09\u652F\u8BD5\u7BA1\u3002\u8BD5\u7BA1\u2460\u4E2D\u753B\u5C11\u91CF\u6C34\uFF0C\u94C1\u9489\u4E00\u534A\u6D78\u5728\u6C34\u4E2D\u3001\u4E00\u534A\u9732\u5728\u7A7A\u6C14\u4E2D\uFF0C\u6807\u6CE8\u300C\u540C\u65F6\u63A5\u89E6\u6C34\u548C\u6C27\u6C14\u300D\uFF1B\u8BD5\u7BA1\u2461\u4E2D\u753B\u4E00\u6839\u94C1\u9489\u5E76\u5728\u7BA1\u5E95\u753B\u659C\u7EBF\u9634\u5F71\u8868\u793A\u5E72\u71E5\u5242\uFF0C\u7528\u6A61\u76AE\u585E\u585E\u7D27\uFF0C\u6807\u6CE8\u300C\u53EA\u6709\u6C27\u6C14\uFF08\u653E\u5E72\u71E5\u5242\uFF09\u300D\uFF1B\u8BD5\u7BA1\u2462\u4E2D\u753B\u6D78\u6CA1\u94C1\u9489\u7684\u84B8\u998F\u6C34\uFF0C\u5E76\u5728\u6C34\u9762\u4E0A\u753B\u4E00\u5C42\u690D\u7269\u6CB9\uFF0C\u7528\u6A61\u76AE\u585E\u585E\u7D27\uFF0C\u6807\u6CE8\u300C\u53EA\u6709\u6C34\uFF08\u716E\u6CB8\u9664\u6C27\uFF0C\u690D\u7269\u6CB9\u9694\u7EDD\u7A7A\u6C14\uFF09\u300D\u3002\u5728\u4E09\u652F\u8BD5\u7BA1\u4E0B\u65B9\u5199\u51FA\u7ED3\u8BBA\uFF1A\u53EA\u6709\u2460\u4E2D\u7684\u94C1\u9489\u751F\u9508\uFF0C\u8BF4\u660E\u94C1\u751F\u9508\u9700\u8981\u540C\u65F6\u63A5\u89E6\u6C27\u6C14\u548C\u6C34\u3002",
