// src/data/chemistry/modules/acid.ts
function tubeLevel(x, y, h, w, liq) {
  const yy = y + h / 2 - w / 2 - (h - w) * liq * 0.9;
  return { t: "line", x1: x - w / 2 + 0.6, y1: yy, x2: x + w / 2 - 0.6, y2: yy, tone: "accent", width: 0.4 };
}
function flaskLevel(x, y, h, w, liq) {
  const yy = y + h / 2 - h * 0.7 * liq;
  return { t: "line", x1: x - w / 2 + 3, y1: yy, x2: x + w / 2 - 3, y2: yy, tone: "accent", width: 0.4 };
}
function beakerLevel(x, y, w, h, fill) {
  const yy = y + h * (1 - fill);
  return { t: "line", x1: x, y1: yy, x2: x + w, y2: yy, tone: "accent", width: 0.4 };
}
