      stem: "\u5B9E\u9A8C\u63A2\u7A76\uFF1A\u4E3A\u5F52\u7EB3\u7A00\u76D0\u9178\u7684\u5316\u5B66\u6027\u8D28\uFF0C\u5C0F\u660E\u505A\u4E86\u4E09\u7EC4\u5B9E\u9A8C\uFF1A\u2460\u5411\u76DB\u6709\u7A00\u76D0\u9178\u7684\u8BD5\u7BA1\u4E2D\u6EF4\u5165 2 \u6EF4\u7D2B\u8272\u77F3\u854A\u8BD5\u6DB2\uFF1B\u2461\u5411\u53E6\u4E00\u652F\u76DB\u6709\u7A00\u76D0\u9178\u7684\u8BD5\u7BA1\u4E2D\u52A0\u5165\u5C11\u91CF\u950C\u7C92\uFF1B\u2462\u5411\u7B2C\u4E09\u652F\u8BD5\u7BA1\u4E2D\u52A0\u5165\u5C11\u91CF\u6C27\u5316\u94C1\u7C89\u672B\u5E76\u632F\u8361\u3002\u8BF7\u5199\u51FA\u4E09\u7EC4\u5B9E\u9A8C\u5404\u81EA\u7684\u73B0\u8C61\u3001\u7ED3\u8BBA\u4E0E\u53CD\u5E94\u7684\u5316\u5B66\u65B9\u7A0B\u5F0F\uFF0C\u5E76\u8BF4\u660E\u7B2C\u2462\u7EC4\u5B9E\u9A8C\u4E2D\u300C\u6EB6\u6DB2\u53D8\u9EC4\u300D\u8BF4\u660E\u4E86\u4EC0\u4E48\u3002",
      answer: "\u2460\u73B0\u8C61\uFF1A\u6EB6\u6DB2\u53D8\u6210\u7EA2\u8272\uFF1B\u7ED3\u8BBA\uFF1A\u7A00\u76D0\u9178\u663E\u9178\u6027\uFF0C\u80FD\u4F7F\u7D2B\u8272\u77F3\u854A\u8BD5\u6DB2\u53D8\u7EA2\uFF08\u8FD9\u662F\u9178\u7684\u901A\u6027\u4E4B\u4E00\uFF09\uFF1B\u8BE5\u7EC4\u53EA\u53D1\u751F\u6307\u793A\u5242\u53D8\u8272\uFF0C\u65E0\u5316\u5B66\u65B9\u7A0B\u5F0F\u3002\u2461\u73B0\u8C61\uFF1A\u950C\u7C92\u8868\u9762\u4EA7\u751F\u6C14\u6CE1\uFF0C\u950C\u7C92\u9010\u6E10\u6EB6\u89E3\uFF1B\u7ED3\u8BBA\uFF1A\u7A00\u76D0\u9178\u80FD\u4E0E\u6D3B\u6CFC\u91D1\u5C5E\u53CD\u5E94\u653E\u51FA\u6C22\u6C14\uFF1B\u65B9\u7A0B\u5F0F\uFF1AZn + 2HCl \u2014\u2192 ZnCl\u2082 + H\u2082\u2191\u3002\u2462\u73B0\u8C61\uFF1A\u7EA2\u68D5\u8272\u7C89\u672B\u9010\u6E10\u6EB6\u89E3\uFF0C\u6EB6\u6DB2\u7531\u65E0\u8272\u53D8\u6210\u9EC4\u8272\uFF1B\u7ED3\u8BBA\uFF1A\u7A00\u76D0\u9178\u80FD\u4E0E\u91D1\u5C5E\u6C27\u5316\u7269\u53CD\u5E94\uFF1B\u65B9\u7A0B\u5F0F\uFF1AFe\u2082O\u2083 + 6HCl \u2014\u2192 2FeCl\u2083 + 3H\u2082O\u3002\u6EB6\u6DB2\u53D8\u9EC4\u8BF4\u660E\u751F\u6210\u4E86 Fe\xB3\u207A\uFF08\u6C2F\u5316\u94C1\u6EB6\u6DB2\u5448\u9EC4\u8272\uFF09\uFF0C\u94C1\u9508\u4E2D\u7684\u94C1\u5143\u7D20\u7531 +3 \u4EF7\u8FDB\u5165\u6EB6\u6DB2\u3002",
