      purpose: "\u501F\u52A9\u65E0\u8272\u915A\u915E\u8BD5\u6DB2\u5224\u65AD\u4E2D\u548C\u53CD\u5E94\u662F\u5426\u6070\u597D\u5B8C\u6210\uFF0C\u5E76\u68C0\u9A8C\u76D0\u9178\u662F\u5426\u8FC7\u91CF",
      apparatus: ["\u6C22\u6C27\u5316\u94A0\u6EB6\u6DB2", "\u7A00\u76D0\u9178", "\u65E0\u8272\u915A\u915E\u8BD5\u6DB2", "pH \u8BD5\u7EB8", "\u73BB\u7483\u68D2", "\u70E7\u676F", "\u80F6\u5934\u6EF4\u7BA1", "\u8868\u9762\u76BF"],
