    {
      heading: "\u5316\u80A5\u7684\u9009\u8D2D\u4E0E\u5408\u7406\u65BD\u7528",
      representation: "\u5E94\u7528",
      body: "\u9009\u8D2D\u5316\u80A5\u65F6\u8981\u770B\u6709\u6548\u6210\u5206\u7684\u542B\u91CF\uFF0C\u542B\u6C2E\u91CF\u662F\u91CD\u8981\u6307\u6807\u3002\u5C3F\u7D20\u4E2D\u542B\u6C2E\u91CF\u7684\u8BA1\u7B97\uFF1ACO(NH\u2082)\u2082 \u7684\u76F8\u5BF9\u5206\u5B50\u8D28\u91CF = 12 + 16 + (14 + 2) \xD7 2 = 60\uFF0C\u6C2E\u5143\u7D20\u7684\u8D28\u91CF\u5206\u6570 = 28 \xF7 60 \xD7 100% \u2248 46.7%\u3002\u785D\u9178\u94F5\uFF1ANH\u2084NO\u2083 \u7684\u76F8\u5BF9\u5206\u5B50\u8D28\u91CF = 14 + 4 + 14 + 48 = 80\uFF0C\u542B\u6C2E\u91CF = 28 \xF7 80 \xD7 100% = 35%\u3002\u65BD\u7528\u4E0E\u4FDD\u5B58\u65F6\u8981\u6CE8\u610F\uFF1A\u94F5\u6001\u6C2E\u80A5\u4E0D\u4E0E\u78B1\u6027\u7269\u8D28\u6DF7\u7528\uFF1B\u78B3\u9178\u6C22\u94F5\u53D7\u70ED\u6613\u5206\u89E3\uFF0C\u8981\u6DF1\u65BD\u8986\u571F\u3001\u907F\u514D\u9AD8\u6E29\uFF1B\u5316\u80A5\u8981\u9632\u6F6E\u9632\u6652\u3001\u5BC6\u5C01\u4FDD\u5B58\u3002",
      note: "\u8BA1\u7B97\u542B\u6C2E\u91CF\u65F6\u5206\u5B50\u662F\u300C\u6C2E\u539F\u5B50\u7684\u76F8\u5BF9\u539F\u5B50\u8D28\u91CF \xD7 \u6C2E\u539F\u5B50\u4E2A\u6570\u300D\uFF0C\u4E0D\u80FD\u6F0F\u4E58\u4E2A\u6570\uFF1ANH\u2084NO\u2083 \u4E2D\u6709 2 \u4E2A N\uFF0C\u4E0D\u80FD\u53EA\u7B97 1 \u4E2A\u3002"
    }
