      result: "\u5C3F\u7D20\u7684\u542B\u6C2E\u91CF\u7EA6 46.7%\uFF0C\u9AD8\u4E8E\u785D\u9178\u94F5\u7684 35%\uFF1B\u540C\u6837 50 kg\uFF0C\u5C3F\u7D20\u63D0\u4F9B\u66F4\u591A\u7684\u6C2E\u5143\u7D20\u3002"
