      body: "\u300C\u80FD\u5927\u91CF\u5171\u5B58\u300D\u5C31\u662F\u79BB\u5B50\u4E4B\u95F4\u4E24\u4E24\u7ED3\u5408\u90FD\u4E0D\u751F\u6210\u6C89\u6DC0\u3001\u6C14\u4F53\u6216\u6C34\u3002\u5E38\u89C1\u7684\u4E0D\u80FD\u5171\u5B58\u7684\u79BB\u5B50\u5BF9\uFF1AH\u207A \u4E0E OH\u207B\u3001CO\u2083\xB2\u207B\u3001HCO\u2083\u207B\uFF1BOH\u207B \u4E0E NH\u2084\u207A\u3001Cu\xB2\u207A\u3001Fe\xB3\u207A\u3001Mg\xB2\u207A\uFF1BCO\u2083\xB2\u207B \u4E0E Ca\xB2\u207A\u3001Ba\xB2\u207A\u3001Ag\u207A\uFF1BSO\u2084\xB2\u207B \u4E0E Ba\xB2\u207A\uFF1BCl\u207B \u4E0E Ag\u207A\u3002\u82E5\u9898\u76EE\u8981\u6C42\u6EB6\u6DB2\u300C\u65E0\u8272\u300D\uFF0C\u8FD8\u8981\u6392\u9664\u6709\u8272\u79BB\u5B50\uFF1ACu\xB2\u207A \u663E\u84DD\u8272\u3001Fe\xB3\u207A \u663E\u9EC4\u8272\u3001Fe\xB2\u207A \u663E\u6D45\u7EFF\u8272\u3002",
