    materials: [
      {
        id: "chem-equation-2-m1",
        material: "\u3010\u6750\u6599\u4E00\u3011\u5316\u5B66\u5C0F\u7EC4\u505A\u4E86\u4E09\u4E2A\u5B9E\u9A8C\uFF1A\u2460 \u5728\u9152\u7CBE\u706F\u4E0A\u52A0\u70ED\u94DC\u4E1D\uFF0C\u94DC\u4E1D\u8868\u9762\u53D8\u9ED1\uFF1B\u2461 \u7535\u89E3\u6C34\uFF0C\u8D1F\u6781\u6536\u96C6\u5230\u53EF\u71C3\u6C14\u4F53\u3001\u6B63\u6781\u6536\u96C6\u5230\u80FD\u4F7F\u5E26\u706B\u661F\u6728\u6761\u590D\u71C3\u7684\u6C14\u4F53\uFF1B\u2462 \u628A\u77F3\u7070\u77F3\u653E\u5165\u7A00\u76D0\u9178\u4E2D\uFF0C\u56FA\u4F53\u6EB6\u89E3\u5E76\u4EA7\u751F\u5927\u91CF\u6C14\u6CE1\u3002\n\u3010\u6750\u6599\u4E8C\u3011\u4F5C\u4E1A\u4E2D\u51FA\u73B0\u4E86\u4E0B\u5217\u4E09\u79CD\u5199\u6CD5\uFF1A\n\u7532\uFF1AH\u2082 + O\u2082 \u2014\u70B9\u71C3\u2192 H\u2082O\n\u4E59\uFF1A2H\u2082O \u2014\u901A\u7535\u2192 2H\u2082 + O\u2082\n\u4E19\uFF1ACaCO\u2083 + HCl \u2014\u2192 CaCl\u2082 + H\u2082O + CO\u2082\u2191",
        questions: [
          {
            id: "chem-equation-2-m1-q1",
            stem: "\u5199\u51FA\u5B9E\u9A8C\u2460\u2461\u2462\u5BF9\u5E94\u7684\u5316\u5B66\u65B9\u7A0B\u5F0F\uFF08\u8981\u6807\u51FA\u53CD\u5E94\u6761\u4EF6\uFF0C\u6C14\u4F53\u4E0E\u6C89\u6DC0\u7B26\u53F7\u6309\u89C4\u8303\u6807\u6CE8\uFF09\u3002\uFF086 \u5206\uFF09",
            answer: "\u2460 2Cu + O\u2082 \u2014\u52A0\u70ED\u2192 2CuO\uFF1B\u2461 2H\u2082O \u2014\u901A\u7535\u2192 2H\u2082\u2191 + O\u2082\u2191\uFF1B\u2462 CaCO\u2083 + 2HCl \u2014\u2192 CaCl\u2082 + H\u2082O + CO\u2082\u2191\uFF08\u5E38\u6E29\uFF0C\u4E0D\u9700\u5199\u6761\u4EF6\uFF09\u3002",
            rubric: [
              "\u2460 \u5316\u5B66\u5F0F\u6B63\u786E\u3001\u914D\u5E73\uFF082 \u5206\uFF09",
              "\u2461 \u914D\u5E73\u6B63\u786E\uFF0C\u4E24\u79CD\u6C14\u4F53\u90FD\u6807 \u2191\uFF0C\u6761\u4EF6\u5199\u300C\u901A\u7535\u300D\uFF082 \u5206\uFF09",
              "\u2462 \u5316\u5B66\u5F0F CaCl\u2082 \u4E0E CaCO\u2083 \u4E0B\u6807\u6B63\u786E\u3001\u914D\u5E73\u3001\u6C14\u4F53\u6807 \u2191\uFF082 \u5206\uFF09"
            ],
            tags: ["\u5316\u5B66\u65B9\u7A0B\u5F0F", "\u4E66\u5199\u89C4\u8303"]
          },
          {
            id: "chem-equation-2-m1-q2",
            stem: "\u6307\u51FA\u6750\u6599\u4E8C\u4E2D\u7532\u3001\u4E59\u3001\u4E19\u4E09\u4E2A\u65B9\u7A0B\u5F0F\u5404\u81EA\u7684\u9519\u8BEF\uFF0C\u5E76\u5199\u51FA\u6539\u6B63\u540E\u7684\u65B9\u7A0B\u5F0F\u3002\uFF085 \u5206\uFF09",
            answer: "\u7532\u6CA1\u914D\u5E73\uFF0C\u5E94\u6539\u4E3A 2H\u2082 + O\u2082 \u2014\u70B9\u71C3\u2192 2H\u2082O\u3002\u4E59\u751F\u6210\u7684\u6C14\u4F53\u6CA1\u6709\u6807 \u2191\uFF08\u53CD\u5E94\u7269\u4E2D\u6CA1\u6709\u6C14\u4F53\uFF09\uFF0C\u5E94\u6539\u4E3A 2H\u2082O \u2014\u901A\u7535\u2192 2H\u2082\u2191 + O\u2082\u2191\u3002\u4E19\u6709\u4E24\u4E2A\u9519\u8BEF\uFF1A\u4E00\u662F\u76D0\u9178\u7684\u5316\u5B66\u5F0F\u6F0F\u4E86\u4E0B\u6807\uFF0C\u5E94\u5199 HCl \u524D\u914D 2\uFF0C\u4E8C\u662F\u6C2F\u5316\u9499\u6F0F\u5199\u4E0B\u6807\uFF0C\u5E94\u5199 CaCl\u2082\uFF1B\u6539\u6B63\u540E\u4E3A CaCO\u2083 + 2HCl \u2014\u2192 CaCl\u2082 + H\u2082O + CO\u2082\u2191\u3002",
            rubric: [
              "\u7532\uFF1A\u6307\u51FA\u672A\u914D\u5E73\u5E76\u6539\u6B63\uFF081 \u5206\uFF09",
              "\u4E59\uFF1A\u6307\u51FA\u751F\u6210\u6C14\u4F53\u672A\u6807 \u2191 \u5E76\u6539\u6B63\uFF082 \u5206\uFF09",
              "\u4E19\uFF1A\u6307\u51FA HCl \u524D\u8981\u914D 2\uFF081 \u5206\uFF09",
              "\u4E19\uFF1A\u6307\u51FA CaCl\u2082 \u4E0B\u6807\u9519\u8BEF\u5E76\u6539\u6B63\uFF081 \u5206\uFF09"
            ],
            tags: ["\u5316\u5B66\u65B9\u7A0B\u5F0F", "\u5E38\u89C1\u9519\u8BEF", "\u914D\u5E73"]
          },
          {
            id: "chem-equation-2-m1-q3",
            stem: "\u6839\u636E 2H\u2082O \u2014\u901A\u7535\u2192 2H\u2082\u2191 + O\u2082\u2191 \u8BA1\u7B97\uFF1A36 g \u6C34\u5B8C\u5168\u5206\u89E3\uFF0C\u53EF\u5F97\u5230\u6C22\u6C14\u548C\u6C27\u6C14\u5404\u591A\u5C11\u514B\uFF1F\uFF084 \u5206\uFF09",
            answer: "\u53EF\u5F97\u5230\u6C22\u6C14 4 g\u3001\u6C27\u6C14 32 g\u3002",
            answerSteps: [
              "\u8BBE\u672A\u77E5\u91CF\uFF1A\u8BBE\u751F\u6210\u6C22\u6C14\u7684\u8D28\u91CF\u4E3A x\uFF0C\u751F\u6210\u6C27\u6C14\u7684\u8D28\u91CF\u4E3A y\u3002",
              "\u5199\u51FA\u5316\u5B66\u65B9\u7A0B\u5F0F\uFF1A2H\u2082O \u2014\u901A\u7535\u2192 2H\u2082\u2191 + O\u2082\u2191\u3002",
              "\u7B97\u76F8\u5BF9\u5206\u5B50\u8D28\u91CF\uFF1A2H\u2082O \u4E3A 36\uFF0C2H\u2082 \u4E3A 4\uFF0CO\u2082 \u4E3A 32\u3002",
              "\u5217\u6BD4\u4F8B\u5F0F\uFF1A36/4 = 36 g/x\uFF0C\u5F97 x = 4 g\uFF1B36/32 = 36 g/y\uFF0C\u5F97 y = 32 g\u3002",
              "\u4F5C\u7B54\uFF1A\u751F\u6210\u6C22\u6C14 4 g\uFF0C\u751F\u6210\u6C27\u6C14 32 g\uFF08\u68C0\u9A8C 4 g + 32 g = 36 g\uFF0C\u7B26\u5408\u8D28\u91CF\u5B88\u6052\uFF09\u3002"
            ],
            rubric: [
              "\u8BBE\u672A\u77E5\u91CF\u5E76\u5199\u51FA\u914D\u5E73\u6B63\u786E\u7684\u65B9\u7A0B\u5F0F\uFF081 \u5206\uFF09",
              "\u7B97\u5BF9\u76F8\u5BF9\u5206\u5B50\u8D28\u91CF 36\u30014\u300132\uFF081 \u5206\uFF09",
              "\u5217\u51FA\u6BD4\u4F8B\u5F0F\u5E76\u6C42\u51FA\u6C22\u6C14 4 g\uFF081 \u5206\uFF09",
              "\u6C42\u51FA\u6C27\u6C14 32 g\uFF0C\u7B54\u6848\u5E26\u5355\u4F4D\uFF081 \u5206\uFF09"
            ],
            tags: ["\u5316\u5B66\u65B9\u7A0B\u5F0F", "\u5316\u5B66\u65B9\u7A0B\u5F0F\u8BA1\u7B97"]
          }
        ]
      }
    ],
