            stem: "\uFF082 \u5206\uFF09\u5224\u65AD\u8BD5\u7BA1\u662F\u5426\u6D17\u6DA4\u5E72\u51C0\u7684\u6807\u51C6\u662F\u4EC0\u4E48\uFF1F\u6D17\u51C0\u540E\u7684\u8BD5\u7BA1\u5E94\u600E\u6837\u653E\u7F6E\uFF1F",
            answer: "\u8BD5\u7BA1\u5185\u58C1\u9644\u7740\u7684\u6C34\u65E2\u4E0D\u805A\u6210\u6C34\u6EF4\uFF0C\u4E5F\u4E0D\u6210\u80A1\u6D41\u4E0B\uFF0C\u8BF4\u660E\u5DF2\u7ECF\u6D17\u5E72\u51C0\uFF1B\u6D17\u51C0\u7684\u8BD5\u7BA1\u5E94\u5012\u653E\u5728\u8BD5\u7BA1\u67B6\u4E0A\u667E\u5E72\u3002",
            rubric: ["\u7B54\u51FA\u300C\u65E2\u4E0D\u805A\u6210\u6C34\u6EF4\uFF0C\u4E5F\u4E0D\u6210\u80A1\u6D41\u4E0B\u300D\uFF081 \u5206\uFF09", "\u7B54\u51FA\u300C\u5012\u653E\u5728\u8BD5\u7BA1\u67B6\u4E0A\u667E\u5E72\u300D\uFF081 \u5206\uFF09"]
