        phenomenon: "\u6392\u6C34\u6CD5\u6536\u96C6\u65F6\u74F6\u5185\u6C34\u9762\u4E0D\u65AD\u4E0B\u964D\uFF0C\u6536\u96C6\u6EE1\u65F6\u74F6\u53E3\u6709\u5927\u6C14\u6CE1\u5192\u51FA\uFF1B\u6392\u7A7A\u6C14\u6CD5\u6536\u96C6\u6EE1\u65F6\uFF0C\u5E26\u706B\u661F\u7684\u6728\u6761\u5728\u74F6\u53E3\u590D\u71C3\u3002",
