        stem: "\u5199\u51FA\u5B9E\u9A8C\u5BA4\u7528\u5927\u7406\u77F3\uFF08\u4E3B\u8981\u6210\u5206 CaCO\u2083\uFF09\u4E0E\u7A00\u76D0\u9178\u5236\u53D6\u4E8C\u6C27\u5316\u78B3\u7684\u5316\u5B66\u65B9\u7A0B\u5F0F\uFF1B\u5E76\u8BA1\u7B97 100 g \u78B3\u9178\u9499\u5B8C\u5168\u53CD\u5E94\u6700\u591A\u80FD\u751F\u6210\u591A\u5C11\u514B\u4E8C\u6C27\u5316\u78B3\uFF08\u76F8\u5BF9\u539F\u5B50\u8D28\u91CF\uFF1AC 12\u3001O 16\u3001Ca 40\uFF09\u3002",
