          "\u628A\u6DF7\u5408\u7269\u8D28\u91CF\u6362\u7B97\u4E3A\u7EAF\u51C0\u7269\u8D28\u91CF\uFF1A25 g \xD7 80% = 20 g",
          "\u5217\u6BD4\u4F8B\u5F0F 100 : 44 = 20 g : x",
