        phenomenon: "\u7EA2\u78F7\u71C3\u70E7\u4EA7\u751F\u5927\u91CF\u767D\u70DF\uFF0C\u653E\u51FA\u70ED\u91CF\uFF1B\u51B7\u5374\u540E\u6253\u5F00\u6B62\u6C34\u5939\uFF0C\u6C34\u88AB\u538B\u5165\u96C6\u6C14\u74F6\u4E2D\uFF0C\u8FDB\u5165\u7684\u6C34\u7684\u4F53\u79EF\u7EA6\u5360\u74F6\u5185\u7A7A\u6C14\u4F53\u79EF\u7684 1/5\u3002",
