        answer: "\u5B9E\u9A8C\u6B65\u9AA4\uFF1A\u53D6\u4E09\u652F\u89C4\u683C\u76F8\u540C\u7684\u8BD5\u7BA1\uFF0C\u5206\u522B\u52A0\u5165 5 mL 5%\u300110%\u300115% \u7684\u8FC7\u6C27\u5316\u6C22\u6EB6\u6DB2\uFF0C\u518D\u5404\u52A0\u5165 0.5 g \u4E8C\u6C27\u5316\u9530\uFF0C\u540C\u65F6\u5F00\u59CB\u8BA1\u65F6\uFF0C\u8BB0\u5F55\u76F8\u540C\u65F6\u95F4\u5185\u6536\u96C6\u5230\u7684\u6C14\u4F53\u4F53\u79EF\uFF08\u6216\u6BD4\u8F83\u4EA7\u751F\u6C14\u6CE1\u7684\u5FEB\u6162\uFF09\u3002\u5FC5\u987B\u63A7\u5236\u76F8\u540C\u7684\u6761\u4EF6\uFF1A\u6EB6\u6DB2\u7684\u4F53\u79EF\u3001\u6E29\u5EA6\u3001\u4E8C\u6C27\u5316\u9530\u7684\u8D28\u91CF\u4E0E\u72B6\u6001\u3001\u8BD5\u7BA1\u89C4\u683C\u3001\u89C2\u5BDF\uFF08\u8BA1\u65F6\uFF09\u7684\u65F6\u95F4\u3002\u73B0\u8C61\uFF1A\u6D53\u5EA6\u8D8A\u5927\u7684\u8BD5\u7BA1\u4E2D\u4EA7\u751F\u6C14\u6CE1\u8D8A\u5FEB\u8D8A\u591A\uFF0C\u76F8\u540C\u65F6\u95F4\u5185\u6536\u96C6\u5230\u7684\u6C14\u4F53\u4F53\u79EF\u8D8A\u5927\u3002\u7ED3\u8BBA\uFF1A\u5728\u5176\u4ED6\u6761\u4EF6\u76F8\u540C\u7684\u60C5\u51B5\u4E0B\uFF0C\u8FC7\u6C27\u5316\u6C22\u6EB6\u6DB2\u7684\u6D53\u5EA6\u8D8A\u5927\uFF0C\u5206\u89E3\u901F\u7387\u8D8A\u5FEB\u3002",
