          "\u4E24\u4E2A\u6C34\u5206\u5B50\u7684\u6A21\u578B\u5B8C\u5168\u76F8\u540C\uFF0C\u4E0B\u65B9\u7B26\u53F7\u5199\u4F5C 2H\u2082O",
          "\u5199\u51FA\u914D\u5E73\u7684\u5316\u5B66\u65B9\u7A0B\u5F0F 2H\u2082O \u2014\u901A\u7535\u2192 2H\u2082\u2191\uFF0BO\u2082\u2191\uFF0C\u6761\u4EF6\u5199\u300C\u901A\u7535\u300D\uFF0C\u6C14\u4F53\u7B26\u53F7\u6807\u5168"
