        explanation: "\u4F5C\u56FE\u9898\u6309\u300C\u7C92\u5B50\u79CD\u7C7B\u3001\u7C92\u5B50\u4E2A\u6570\u3001\u7B26\u53F7\u6807\u6CE8\u300D\u4E09\u9879\u7ED9\u5206\u3002\u6C34\u5206\u5B50\u4E2D\u6C22\u539F\u5B50\u4E0E\u6C27\u539F\u5B50\u7684\u4E2A\u6570\u6BD4\u5FC5\u987B\u662F 2\u22361\uFF1B\u4E24\u4E2A\u6A21\u578B\u7684\u5F62\u72B6\u8981\u5B8C\u5168\u4E00\u6837\uFF0C\u8868\u793A\u5B83\u4EEC\u90FD\u662F\u6C34\u5206\u5B50\uFF1B\u7B26\u53F7\u5199\u5728\u6A21\u578B\u4E0B\u65B9\u5E76\u5E26\u4E0A\u7CFB\u6570 2\u3002\u6700\u540E\u522B\u5FD8\u4E86\u914D\u5E73\u7684\u901A\u7535\u5206\u89E3\u65B9\u7A0B\u5F0F\u3002",
